insert into original_claims values ('51b623f2-bea9-4af4-9d2e-ddf6be258d7a','{"approval_origin": "ai_candidate", "certainty": "medium", "claim_id": "51b623f2-bea9-4af4-9d2e-ddf6be258d7a", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "Kalam argued that meaningful education of young people was a central investment in India''s future.", "current_status": "draft", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "SCHOLARLY_ATTRIBUTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "67c1cd72-8f17-44b0-94c5-52ef3bd1d21b", "field_label": "Mentorship and education", "parameter_id": "8b5583b5-ba98-4e9e-994f-b0c5c9346b9d", "parameter_name": "Mentorship and education"}, "parent_claim_id": null, "personality_id": "96abdf31-9bb6-4fa9-8e02-1508cdcba4c9", "personality_name": "A. P. J. Abdul Kalam", "reviewer_decision": null, "sources": [{"evidence_excerpt": "If education in its real sense can be imparted to the younger generation, there is nothing better than that as an investment for an assured future. In my view, education is the ultimate realisation of eternal human values fortified by increasing knowledge of the Universe''s systems leading to self-realisation.", "link_id": "6d0f6688-9e5d-4749-8065-15b06119c1af", "page_or_section": "My education", "passages": [{"chunk_id": "d378a57c-7fd5-4934-a512-960e16fe82ad", "confidence": null, "excerpt": "If education in its real sense can be imparted to the younger generation, there is nothing better than that as an investment for an assured future. In my view, education is the ultimate realisation of eternal human values fortified by increasing knowledge of the Universe''s systems leading to self-realisation.", "excerpt_trunc