insert into original_claims values ('a85760f8-9f86-423f-81ca-dab8c9921458','{"approval_origin": "ai_candidate", "certainty": "medium", "claim_id": "a85760f8-9f86-423f-81ca-dab8c9921458", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "What distinguished Shankara’s Advaita was a systematic articulation of nonduality across metaphysics, language and epistemology, combined with a pedagogy directed to liberation.", "current_status": "draft", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "SCHOLARLY_INTERPRETATION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "d5ea0700-b35b-4155-ab8f-33c0deb87b03", "field_label": "Teachings and philosophy", "parameter_id": "19c06971-4bed-4e8e-ad0d-ea8a32be0580", "parameter_name": "Teachings and philosophy"}, "parent_claim_id": null, "personality_id": "32e53e02-71cd-4232-9d33-247d37f039a7", "personality_name": "Adi Shankaracharya", "reviewer_decision": null, "sources": [{"evidence_excerpt": "This effort entails tying a metaphysics of brahman to a philosophy of consciousness. This philosophical tradition finds its most sustained early articulation in the works of the preeminent Advaita Vedantin, Sankaracarya (hereafter Sankara), who flourished during the eighth century CE. Sankara endeavored to communicate nonduality through systematized …", "link_id": "8da582c6-4c5f-479a-9418-ff266b3bea97", "page_or_section": "SEP: Introduction", "passages": [{"chunk_id": "1142cbe8-7b7f-4768-8bd7-0774329d4e9f", "confidence": null, "excerpt": "This effort entails tying a metaphysics of brahman to a philosophy of consciousness. This philosophical tradition finds its most sustained early articulation in the works of the preeminent Advaita Vedan