insert into original_claims values ('de429f87-b2b8-4697-854f-90052fbcb30f','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "de429f87-b2b8-4697-854f-90052fbcb30f", "claim_kind": "established_fact", "claim_relations": [], "claim_text": "In February 1931 Bhagat Singh defined revolution as replacing an unjust social order with a socialist order, making socialism central to his late political programme.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification", "Current approval origin does not establish strict verification"], "evidence_type": "direct_primary_text", "lens": {"field_id": "df1cb714-b56f-4de8-8e59-383e6d8ac800", "field_label": "Ideas of independence and the state", "parameter_id": "80417d3d-1a0d-4d71-bc0b-f9dafb8049f1", "parameter_name": "Ideas of independence and the state"}, "parent_claim_id": null, "personality_id": "8ece70a0-5e61-488f-ab95-2e0810e65e92", "personality_name": "Bhagat Singh", "reviewer_decision": null, "sources": [{"evidence_excerpt": "He defined it as overthrow of an unjust existing social order and its replacement by a socialist order.", "link_id": "9b670855-a742-481f-b6a4-f29e2eb58dd2", "page_or_section": "socialist order", "passages": [{"chunk_id": "662f833c-889b-428a-9fac-c241a8cfe738", "confidence": null, "excerpt": "He defined it as overthrow of an unjust existing social order and its replacement by a socialist order.", "excerpt_truncated": false, "is_active": true, "link_method": null, "page_or_section": "socialist order", "relationship": "supports", "section_title": "Bhagat Singh: To Young Political Workers", "source_id": "d1050391-e26d-4fc6-9d10-6bee7f973be8", "textual_layer": "Bhagat Singh’s late politi