insert into original_claims values ('f855c5c6-4a1c-476d-86fa-703567e0f6ef','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "f855c5c6-4a1c-476d-86fa-703567e0f6ef", "claim_kind": "established_fact", "claim_relations": [], "claim_text": "Bhagat Singh’s appeal to work among peasants and workers indicates that his nationalism increasingly linked liberation from empire to social and economic transformation.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification", "Current approval origin does not establish strict verification"], "evidence_type": "direct_primary_text", "lens": {"field_id": "df1cb714-b56f-4de8-8e59-383e6d8ac800", "field_label": "Ideas of independence and the state", "parameter_id": "80417d3d-1a0d-4d71-bc0b-f9dafb8049f1", "parameter_name": "Ideas of independence and the state"}, "parent_claim_id": null, "personality_id": "8ece70a0-5e61-488f-ab95-2e0810e65e92", "personality_name": "Bhagat Singh", "reviewer_decision": null, "sources": [{"evidence_excerpt": "He urged study, organization, work among peasants and workers, and warned against individual heroics substituting for a disciplined mass movement.", "link_id": "4ddb5eaa-825b-4201-b951-104b378b5e8f", "page_or_section": "peasants and workers", "passages": [{"chunk_id": "373ada14-8f99-4900-8361-4dee341af259", "confidence": null, "excerpt": "He urged study, organization, work among peasants and workers, and warned against individual heroics substituting for a disciplined mass movement.", "excerpt_truncated": false, "is_active": true, "link_method": null, "page_or_section": "study, organization", "relationship": "supports", "section_title": "Bhagat Singh: To Young Political Workers",