insert into original_claims values ('29d44a29-fbe8-431f-be19-2b6b7ee43ea7','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "29d44a29-fbe8-431f-be19-2b6b7ee43ea7", "claim_kind": "established_fact", "claim_relations": [], "claim_text": "The accused said the bombs were not intended to kill and had been thrown in empty spaces; this is their political and legal self-explanation, to be distinguished from independent reconstruction.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification", "Current approval origin does not establish strict verification"], "evidence_type": "direct_primary_text", "lens": {"field_id": "9b1b41b5-66f7-453b-aa6a-060e298d8529", "field_label": "Sources and contested questions", "parameter_id": "090d964f-1f65-43f4-953a-bb879cbe2234", "parameter_name": "Sources and contested questions"}, "parent_claim_id": null, "personality_id": "8ece70a0-5e61-488f-ab95-2e0810e65e92", "personality_name": "Bhagat Singh", "reviewer_decision": null, "sources": [{"evidence_excerpt": "They said the bombs were not intended to kill and had been thrown in empty spaces after care to avoid casualties.", "link_id": "e3a745f1-623e-4be6-a06b-508df81cbf3a", "page_or_section": "not intended to kill", "passages": [{"chunk_id": "c7d89946-e53a-4240-8d40-56a80b2cdb06", "confidence": null, "excerpt": "They said the bombs were not intended to kill and had been thrown in empty spaces after care to avoid casualties.", "excerpt_truncated": false, "is_active": true, "link_method": null, "page_or_section": "not intended to kill", "relationship": "supports", "section_title": "Bhagat Singh: Statement in the Assembly Bomb Case", "source_id": "97041519-fa56-4075-9e3d-