insert into original_claims values ('5027fff7-ae38-4403-8e9f-8ebf51df5aae','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "5027fff7-ae38-4403-8e9f-8ebf51df5aae", "claim_kind": "established_fact", "claim_relations": [], "claim_text": "Why I Am an Atheist is strong evidence for Bhagat Singh’s late prison position, but it should not be used to erase changes or complexity in his earlier thought.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification", "Current approval origin does not establish strict verification"], "evidence_type": "direct_primary_text", "lens": {"field_id": "9b1b41b5-66f7-453b-aa6a-060e298d8529", "field_label": "Sources and contested questions", "parameter_id": "090d964f-1f65-43f4-953a-bb879cbe2234", "parameter_name": "Sources and contested questions"}, "parent_claim_id": null, "personality_id": "8ece70a0-5e61-488f-ab95-2e0810e65e92", "personality_name": "Bhagat Singh", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The essay is evidence of a late prison position on religion and reason; it is not a complete account of every earlier belief.", "link_id": "72dd5c89-86cb-47cb-b8d6-8b7b0fd89e56", "page_or_section": "not a complete account", "passages": [{"chunk_id": "4bc56261-879e-461f-b8a0-3730af39f4ac", "confidence": null, "excerpt": "The essay is evidence of a late prison position on religion and reason; it is not a complete account of every earlier belief.", "excerpt_truncated": false, "is_active": true, "link_method": null, "page_or_section": "not a complete account", "relationship": "supports", "section_title": "Bhagat Singh: Why I Am an Atheist", "source_id": "92e1355f-4dab-4c39-80f8-f714cf0c1867", "textua