insert into original_claims values ('e69af90a-8b8c-42aa-9c29-8d46d30e6b6e','{"approval_origin": "ai_candidate", "certainty": "medium", "claim_id": "e69af90a-8b8c-42aa-9c29-8d46d30e6b6e", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "Historian Nandini Chatterjee describes Shivaji''s 1656 approach to Aurangzeb as a move within the rivalry between Bijapur and the Mughals.", "current_status": "needs_review", "epistemics": null, "evidence_flags": ["Missing assigned epistemic classification"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "646e836b-f7be-484c-9230-81a14ba22dc7", "field_label": "Political relationships and conflict", "parameter_id": "0bb87470-3066-4266-bdfe-b3677630552e", "parameter_name": "Political relationships and conflict"}, "parent_claim_id": null, "personality_id": "7d85b2ab-8c8f-4095-bd02-37dab732d2de", "personality_name": "Chhatrapati Shivaji Maharaj", "reviewer_decision": null, "sources": [{"evidence_excerpt": "In 1656, around the same time that Purshottam Das was picking up the family mantle, Shivaji, the ambitious son of a high-ranking noble of Bijapur, offered his services to the equally ambitious Mughal prince, Aurangzeb.Footnote 1 Bijapur was a flourishing kingdom in south-west India, located at the junction between two linguistic zones, Marathi and Kannada, …", "link_id": "f2baa919-0a0f-46ca-8067-345668e29820", "page_or_section": "Invaders: Marathas and the British", "passages": [{"chunk_id": "00d6451a-be7b-4498-9a63-366b665d7678", "confidence": null, "excerpt": "In 1656, around the same time that Purshottam Das was picking up the family mantle, Shivaji, the ambitious son of a high-ranking noble of Bijapur, offered his services to the equally ambitious Mughal prince, Aurangzeb.Footnote 1 Bijapur was a flourishing kingdom in south-west India, located at the junction between two linguistic zones, Marathi and Kannada, …", "excerpt_truncated": true, "is_active": true, "link_method": null, "pa