insert into original_claims values ('75243eba-d626-46a9-b6b0-79b64535ad22','{"approval_origin": "ai_candidate", "certainty": "medium", "claim_id": "75243eba-d626-46a9-b6b0-79b64535ad22", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "The Akademi associated her popularity with devotional songs in South Indian languages and Hindi, linking multilingual performance to wider public reach.", "current_status": "draft", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "INSTITUTIONAL_PRAISE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "1343a33e-b17d-4004-8a09-2fdb01ff206b", "field_label": "Devotional music", "parameter_id": "a7070d15-d58d-4ef3-a48a-e839b1923fd3", "parameter_name": "Devotional music"}, "parent_claim_id": null, "personality_id": "98e98962-0076-4b41-b23f-2aa0e4c82b93", "personality_name": "M. S. Subbulakshmi", "reviewer_decision": null, "sources": [{"evidence_excerpt": "She is known both for her mellifluous presentation of ragas and her chaste diction. Her rendition of devotional music in South Indian languages as well as in Hindi has won her a whole class of music-lovers. She has also acted in a few films, the most famous of which is \"Meera\".", "link_id": "041ef413-7f00-4057-9343-d88f633da609", "page_or_section": "Fellow citation", "passages": [{"chunk_id": "3a47c782-6617-4a17-abea-929cd8daefdb", "confidence": null, "excerpt": "She is known both for her mellifluous presentation of ragas and her chaste diction. Her rendition of devotional music in South Indian languages as well as in Hindi has won her a whole class of music-lovers. She has also acted in a few films, the most famous of which is \"Meera\".", "excerpt_truncated": false, "is_active"