insert into original_claims values ('85a08ca7-b79c-4489-b669-0d4ecaead601','{"approval_origin": "ai_candidate", "certainty": "medium", "claim_id": "85a08ca7-b79c-4489-b669-0d4ecaead601", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "A government centenary profile associates her closely with Tyagaraja’s devotional compositions; this is a later account of her repertoire and reception, not evidence that she alone popularized the composer.", "current_status": "draft", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "MODERN_RECEPTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "1343a33e-b17d-4004-8a09-2fdb01ff206b", "field_label": "Devotional music", "parameter_id": "a7070d15-d58d-4ef3-a48a-e839b1923fd3", "parameter_name": "Devotional music"}, "parent_claim_id": null, "personality_id": "98e98962-0076-4b41-b23f-2aa0e4c82b93", "personality_name": "M. S. Subbulakshmi", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Narayanan on January 14, 1998 at a function held in Rashtrapati Bhavan in New Delhi. Subbulakshmi’s was deeply immersed in the devotional music of Saint Thyagaraja. The only time she was out of touch of Thyagraja’s bhajans were in 1940s when was a part of a Tamil Isai Movement to popularize Tamil music.", "link_id": "277cd631-ab02-45cf-aa6e-7dc4baaac176", "page_or_section": "Government centenary profile", "passages": [{"chunk_id": "4e066210-5709-4fe1-9152-91d728948168", "confidence": null, "excerpt": "Narayanan on January 14, 1998 at a function held in Rashtrapati Bhavan in New Delhi. Subbulakshmi’s was deeply immersed in the devotional music of Saint Thyagaraja. The only time she was out of touch of Thyagraja’s bhajans were in 1940s when was a part of a Tamil Isai Movement to popularize Tamil music.", "excerpt_truncated": false, "is_active": true, "link_method": null, "page_or_section": "Government centenary profile", "relationship": "supports", "section_title": "M. S. Subbulakshmi: The inimitable M.S. Subbulakshmi", "source_id": "1d457b5a-ad3a-44fa-ae3c-ec16a7df6ff4", "textual_layer": "Centenary retrospective; commemorative claims and recollections require attribution"}], "relationship": "supports", "source": {"author": null, "authority_metadata": {"verified_at": "2026-10-12"}, "citation": "The inimitable M.S. Subbulakshmi. Press Information Bureau, Government of India. https://www.pib.gov.in/newsite/printrelease.aspx?lang=2&reg=48&relid=149779", "original_work_identity": {}, "publication_year": 2016, "publisher_or_institution": "Press Information Bureau, Government of India", "rights_or_access_note": "Public original; short research excerpts.", "source_status": "approved", "source_type": "institutional", "storage_path": null, "title": "The inimitable M.S. Subbulakshmi", "url": "https://www.pib.gov.in/newsite/printrelease.aspx?lang=2&reg=48&relid=149779"}, "source_id": "1d457b5a-ad3a-44fa-ae3c-ec16a7df6ff4"}], "unmatched_passage_links": []}'::jsonb,'draft','ai_candidate');
insert into original_claims values ('d713e2b5-57c7-4a40-8210-2975436ee170','{"approval_origin": "ai_candidate", "certainty": "medium", "claim_id": "d713e2b5-57c7-4a40-8210-2975436ee170", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "In the same response she described music in devotional terms and acknowledged Chandrasekharendra Saraswathi of Kanchi; this records her stated religious understanding of performance.", "current_status": "draft", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "1343a33e-b17d-4004-8a09-2fdb01ff206b", "field_label": "Devotional music", "parameter_id": "a7070d15-d58d-4ef3-a48a-e839b1923fd3", "parameter_name": "Devotional music"}, "parent_claim_id": null, "personality_id": "98e98962-0076-4b41-b23f-2aa0e4c82b93", "personality_name": "M. S. Subbulakshmi", "reviewer_decision": null, "sources": [{"evidence_excerpt": "By his loving care he is my parent; by his unerring guidance he is my preceptor. Indian music is orientated solely to the end of divine communion. If I have done something in this respect, it is entirely due to the Grace of the Almighty who has chosen my humble self as a tool.", "link_id": "13f76cb6-798e-48a0-af5a-40391818209c", "page_or_section": "1974 response", "passages": [{"chunk_id": "1cfed6a0-11ee-435d-85ce-018bf4d175e7", "confidence": null, "excerpt": "I offer my deepest homage to this trinity. My all I owe to my husband, Sri T. Sadasivam.", "excerpt_truncated": false, "is_active": true, "link_method": null, "page_or_section": "1974 response", "relationship": "supports", "section_title": "M. S. Subbulakshmi: M. S. Subbulakshmi: 1974 award citation