insert into original_claims values ('ca9b56b6-bfa5-4a47-ab09-3a094b59c2c5','{"approval_origin": "ai_candidate", "certainty": "medium", "claim_id": "ca9b56b6-bfa5-4a47-ab09-3a094b59c2c5", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "Menon notes that the Edinburgh recitals were shorter than Indian concerts but retained their standard musical pattern; the festival presentation did not simply replace Carnatic form with a Western programme.", "current_status": "draft", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "SCHOLARLY_ATTRIBUTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "a11004ed-978b-4496-a58d-41229c0a3604", "field_label": "International performance", "parameter_id": "810f9112-f91d-4489-9696-dda41dbf19d4", "parameter_name": "International performance"}, "parent_claim_id": null, "personality_id": "98e98962-0076-4b41-b23f-2aa0e4c82b93", "personality_name": "M. S. Subbulakshmi", "reviewer_decision": null, "sources": [{"evidence_excerpt": "In 1963, Subbulakshmi went to Europe for the first time, to participate in the Edinburgh International Festival. She gave two recitals there — short, by Indian standards, but otherwise no different from the standard pattern of her Indian concerts. This was the first time a major Indian vocal musician was being presented at an Inter national Festival abroad …", "link_id": "3e901a67-209a-4820-8a9a-4d40d3474012", "page_or_section": "Menon profile, p. 33", "passages": [{"chunk_id": "67d664b4-cb65-4808-ae46-0c757d8d3b62", "confidence": null, "excerpt": "In 1963, Subbulakshmi went to Europe for the first time, to participate in the Edinburgh International Festival. She gave two recitals there — short, by Indian sta