insert into original_claims values ('0f36dc1e-79a2-465a-981b-77b75665f4d7','{"approval_origin": "ai_candidate", "certainty": "high", "claim_id": "0f36dc1e-79a2-465a-981b-77b75665f4d7", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "The Gospel''s translator, Nikhilananda, adds a note that Ramakrishna''s frequent phrase kamini-kanchan (\"woman and gold\") meant only \"lust and greed\" and that he used \"woman\" as a concrete term for the sex instinct when addressing male devotees; critics dispute such translation choices.", "current_status": "draft", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification"], "evidence_type": "direct_primary_text", "lens": {"field_id": "cd01e895-3db1-4ce4-bdfa-bf792abf0284", "field_label": "Challenges and contested interpretations", "parameter_id": "8f0225f6-5acd-4481-8c81-428a067efede", "parameter_name": "Challenges and contested interpretations"}, "parent_claim_id": null, "personality_id": "9ef04ec3-7bf1-4210-a951-1d6da7b2fc99", "personality_name": "Ramakrishna Paramahamsa", "reviewer_decision": null, "sources": [{"evidence_excerpt": "This favourite expression of the Master, \"kaminikanchan\", has often been misconstrued. By it he meant only \"lust and greed\", the baneful influence of which retards the aspirant''s spiritual growth. He used the word \"kamini\", or \"woman\", as a concrete term for the sex instinct when addressing his man devotees.", "link_id": "a88a2d84-12a2-4c99-82dd-235eb2bbc836", "page_or_section": "Gospel vol. 1, ch. 1 (translator''s note)", "passages": [{"chunk_id": "25560911-71d0-4342-bc5a-f3fd8c15b58f", "confidence": null, "excerpt": "This favourite expression of the Master, \"kaminikanchan\", has often been misconstrued. By it he meant only \"lust and greed\", the baneful influence of which retards the aspirant''s spiritual growth. He used the word \"kamini\", or \"woman\", as a concrete term for the sex instinct when addressing his man devotees.", "excerpt_truncated": false, "is_active": true, "link_method": null, "page_or_section": "Gospel vol. 1, ch. 1 (translator''s note)", "relationship": "supports", "section_title": "Ramakrishna Paramahamsa: The Gospel''s translator, Nikhilananda, adds a note that Ramakrishna''s frequent phrase kamini-kanchan (\"woman and gold\") meant only \"lust and greed\" and that he used \"woman\" as a concrete term for the sex instinct when addressing male devotees; critics dispute such translation choices.", "source_id": "6bd19767-fd30-4b73-900b-11576daedd8e", "textual_layer": "Reported teachings: M.''s diary-style record of Ramakrishna''s conversations, in translation"}], "relationship": "supports", "source": {"author": "Mahendranath Gupta (M.), translated by Swami Nikhilananda", "authority_metadata": {"verified_at": "2026-10-12"}, "citation": "Mahendranath Gupta (M.), translated by Swami Nikhilananda. The Gospel of Sri Ramakrishna (Kathamrita): conversations recorded by M.. Ramakrishna-Vivekananda Center, New York (1942); online edition ramakrishnavivekananda.info. https://www.ramakrishnavivekananda.info/gospel/gospel.htm", "original_work_identity": {}, "publication_year": 1942, "publisher_or_institution": "Ramakrishna-Vivekananda Center, New York (1942); online edition ramakrishnavivekananda.info", "rights_or_access_note": "Translation of the Bengali Kathamrita; Sil and others argue the translation omits or softens some passages.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "The Gospel of Sri Ramakrishna (Kathamrita): conversations recorded by M.", "url": "https://www.ramakrishnavivekananda.info/gospel/gospel.htm"}, "source_id": "6bd19767-fd30-4b73-900b-11576daedd8e"}, {"evidence_excerpt": "With