insert into original_claims values ('10d60574-26c1-4d5d-98c8-0284d29ea5be','{"approval_origin": "ai_candidate", "certainty": "medium", "claim_id": "10d60574-26c1-4d5d-98c8-0284d29ea5be", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "Müller warned that even Vivekananda''s account of his master shows the \"Dialogic Process\" of legend-making: veneration makes it natural to omit anything unfavourable, and doubt is treated as unkindness — a contemporary reminder to separate testimony from history.", "current_status": "draft", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "SCHOLARLY_INTERPRETATION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "cd01e895-3db1-4ce4-bdfa-bf792abf0284", "field_label": "Challenges and contested interpretations", "parameter_id": "8f0225f6-5acd-4481-8c81-428a067efede", "parameter_name": "Challenges and contested interpretations"}, "parent_claim_id": null, "personality_id": "9ef04ec3-7bf1-4210-a951-1d6da7b2fc99", "personality_name": "Ramakrishna Paramahamsa", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Yet we can hardly fail to see the first beginnings of the ravages which the Dialogic Process works even in the first generation. Given his own veneration for his departed master, there is a natural unwillingness, nay, an incapability, to believe or to repeat anything that might place his master in an unfavourable light. Besides, his master was dead when …", "link_id": "ca6f694f-429b-48b8-9624-c1d3cbd5637c", "page_or_section": "Müller 1898, Remarks on Ramakrishna''s life", "passages": [{"chunk_id": "79067bb0-5a81-40c8-8acc-2410326cfa7e", "confidence": null, "excerpt": "Yet we can hardly fail to see the first beginni