insert into original_claims values ('56d372f8-89b4-491d-8535-99e2d6e2abab','{"approval_origin": "ai_candidate", "certainty": "medium", "claim_id": "56d372f8-89b4-491d-8535-99e2d6e2abab", "claim_kind": "uncertain", "claim_relations": [], "claim_text": "Jeffrey Kripal''s Kali''s Child (1995) applied psychoanalytic theory to Ramakrishna and argued that homoeroticism and sexual abuse lay at the secret heart of his life and work; the Encyclopedia of Religion adds that Kripal rejected reducing his spirituality to pathology.", "current_status": "draft", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "CONTESTED", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification"], "evidence_type": "contested", "lens": {"field_id": "cd01e895-3db1-4ce4-bdfa-bf792abf0284", "field_label": "Challenges and contested interpretations", "parameter_id": "8f0225f6-5acd-4481-8c81-428a067efede", "parameter_name": "Challenges and contested interpretations"}, "parent_claim_id": null, "personality_id": "9ef04ec3-7bf1-4210-a951-1d6da7b2fc99", "personality_name": "Ramakrishna Paramahamsa", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Intrigued by the man so many consider a modern saint, Kripal set about dissecting the sage''s psyche with the scalpel of psychoanalytic theory. What he believed he uncovered at the secret heart of Ramakrishna''s life and work was homoeroticism and sexual abuse.Objections to academic texts are typically voiced by the author''s colleagues in journals, books, and …", "link_id": "136b111a-40ea-4491-bbb3-242a560e8bea", "page_or_section": "Los Angeles Review of Books, 2011", "passages": [{"chunk_id": "5d934ba0-f268-44f0-a254-b25a72225f01", "confidence": null, "excerpt": "Intrigued by the man so many consider a modern saint, Kripal set about dissecting the sage''s psyche with the scalpel of psychoanalytic theory. What he believed he uncovered at the secret heart of Ramakrishna''s life and work was homoeroticism and sexual abuse.Objections to academic texts are typically voiced by the author''s colleagues in journals, books, and …", "excerpt_truncated": true, "is_active": true, "link_method": null, "page_or_section": "Los Angeles Review of Books, 2011", "relationship": "supports", "section_title": "Ramakrishna Paramahamsa: Jeffrey Kripal''s Kali''s Child (1995) applied psychoanalytic theory to Ramakrishna and argued that homoeroticism and sexual abuse lay at the secret heart of his life and work; the Encyclopedia of Religion adds that Kripal rejected reducing his spirituality to pathology.", "source_id": "ac02dde3-2c64-4cb9-bac4-1425c20d8add", "textual_layer": "Review essay in a literary magazine, by a non-specialist author of American Veda who interviewed both sides"}], "relationship": "supports", "source": {"author": null, "authority_metadata": {"verified_at": "2026-10-12"}, "citation": "The Most Versatile of Mystics. Los Angeles Review of Books. https://lareviewofbooks.org/essay/the-most-versatile-of-mystics", "original_work_identity": {}, "publication_year": 2011, "publisher_or_institution": "Los Angeles Review of Books", "rights_or_access_note": "Magazine review of Interpreting Ramakrishna; the author says he is not an expert on Ramakrishna.", "source_status": "approved", "source_type": "institutional", "storage_path": null, "title": "The Most Versatile of Mystics", "url": "https://lareviewofbooks.org/essay/the-most-versatile-of-mystics"}, "source_id": "ac02dde3-2c64-4cb9-bac4-1425c20d8add"}, {"evidence_excerpt": "In the furor over the book two things were overlooked. First, far from trying to stigmatize Ramakrishna''s sexuality, Kripal sought to recognize it as one dimension of a profoundly spiritual life; second, Kripal explicitly rejected any simplistic psychologism that reduced Ramakrishna''s spirituality to a ma