insert into original_claims values ('2d6d5273-b58d-4fc2-977c-df009060e4bd','{"approval_origin": "ai_candidate", "certainty": "medium", "claim_id": "2d6d5273-b58d-4fc2-977c-df009060e4bd", "claim_kind": "traditional_account", "claim_relations": [], "claim_text": "The Order contrasts the Brahmo leader Keshab, an orator and writer who stressed social reform and treated Hindu images as allegory, with Ramakrishna, who \"hardly knew how to write his own name\", disliked lecturing and held God-realization the only goal of life.", "current_status": "draft", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification"], "evidence_type": "traditional_narrative", "lens": {"field_id": "15827701-bdce-4de2-9973-573ae507ae28", "field_label": "Historical context and reception", "parameter_id": "1565b520-d15c-4880-aef2-9f7cba878070", "parameter_name": "Historical context and reception"}, "parent_claim_id": null, "personality_id": "9ef04ec3-7bf1-4210-a951-1d6da7b2fc99", "personality_name": "Ramakrishna Paramahamsa", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Keshab was an orator and a writer of books and magazine articles; Sri Ramakrishna had a horror of lecturing and hardly knew how to write his own name, Keshab''s fame spread far and wide, even reaching the distant shores of England; the Master still led a secluded life in the village of Dakshineswar. Keshab emphasized social reforms for India''s regeneration; …", "link_id": "fcbb7c3e-a4fa-48c5-9189-7295be554ecd", "page_or_section": "Gospel introduction: Keshab Chandra Sen", "passages": [{"chunk_id": "25972267-7868-412a-80cd-4ae4b1419c40", "confidence": null, "excerpt": "Keshab was an orator and a writer of books and magazine articles; Sri Ramak