insert into original_claims values ('a46df63b-dcae-4504-b6f8-337212c04b88','{"approval_origin": "ai_candidate", "certainty": "medium", "claim_id": "a46df63b-dcae-4504-b6f8-337212c04b88", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "Scholars call Vivekananda''s Practical Vedanta a creative transformation of Ramakrishna''s teaching, and some argue that his neo-Vedanta also reflects Western reconstructions of Advaita and Brahmo influence.", "current_status": "draft", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "SCHOLARLY_INTERPRETATION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "15827701-bdce-4de2-9973-573ae507ae28", "field_label": "Historical context and reception", "parameter_id": "1565b520-d15c-4880-aef2-9f7cba878070", "parameter_name": "Historical context and reception"}, "parent_claim_id": null, "personality_id": "9ef04ec3-7bf1-4210-a951-1d6da7b2fc99", "personality_name": "Ramakrishna Paramahamsa", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Scholars debate whether Ramakrishna viewed himself as a Vedāntin; the case can be made that his nondualism was more Tantric than Vedāntic. What is clear is that Vivekananda''s Practical Vedānta represents a creative transformation of Ramakrishna''s teaching. Some argue that the officially sanctioned neo-Vedānta of the Ramakrishna movement reflects the impact …", "link_id": "35785700-5dbf-45b7-b9a6-221e6149ff8a", "page_or_section": "Encyclopedia of Religion: Vivekananda", "passages": [{"chunk_id": "711e5f3a-deb2-4426-af20-a43c48f2f0f9", "confidence": null, "excerpt": "Scholars debate whether Ramakrishna viewed himself as a Vedāntin; the case can be made that his nondualism was more Tantric than Vedāntic. What is clear is that Vivekananda''s Practical Vedānta represents a creative transformation of Ramakrishna''s teaching. Some argue that the officially sanctioned neo-Vedānta of the Ramakrishna movement reflects the impact …", "excerpt_truncated": true, "is_active": true, "link_method": null, "page_or_section": "Encyclopedia of Religion: Vivekananda", "relationship": "supports", "section_title": "Ramakrishna Paramahamsa: Scholars call Vivekananda''s Practical Vedanta a creative transformation of Ramakrishna''s teaching, and some argue that his neo-Vedanta also reflects Western reconstructions of Advaita and Brahmo influence.", "source_id": "685aedc9-c39f-4c63-a43b-2b7d4086b6ae", "textual_layer": "Scholarly encyclopedia entry by university historians of religion"}], "relationship": "supports", "source": {"author": "Thomas J. Hopkins (1987); revised by Brian A. Hatcher (2005)", "authority_metadata": {"verified_at": "2026-10-12"}, "citation": "Thomas J. Hopkins (1987); revised by Brian A. Hatcher (2005). Vivekananda (Encyclopedia of Religion, 2nd edition). Macmillan Reference / Gale; read through Encyclopedia.com. https://www.encyclopedia.com/people/philosophy-and-religion/hinduism-biographies/vivekananda", "original_work_identity": {}, "publication_year": 2005, "publisher_or_institution": "Macmillan Reference / Gale; read through Encyclopedia.com", "rights_or_access_note": "Reference entry; short research excerpts only.", "source_status": "approved", "source_type": "institutional", "storage_path": null, "title": "Vivekananda (Encyclopedia of Religion, 2nd edition)", "url": "https://www.encyclopedia.com/people/philosophy-and-religion/hinduism-biographies/vivekananda"}, "source_id": "685aedc9-c39f-4c63-a43b-2b7d4086b6ae"}, {"evidence_excerpt": "Among other things, this allowed Neevel to interpret Ramakrishna''s concern with worldly activity as arising from his understanding of the Mother''s playful śakti. This, in turn, seemed to accord better with the ideals of service that are so characteristic of the Ramakrishna Mission, since the renunciatory ethic of Advaita Vedānta less readily supports the …", "link_id": "1b099dcc-eceb-4b0d-8526-f314973b0ef4", "page_or_section": "Encyclopedia of Religion", "passages": [], "relationship": "supports", "source": {"author": "Walter G. Neevel Jr. (1987); revised by Brian A. Hatcher (2005)", "authority_metadata": {"verified_at": "2026-10-12"}, "citation": "Walter G. Neevel Jr. (1987); revised by Brian A. Hatcher (2005). Ramakrishna (Encyclopedia of Religion, 2nd edition). Macmillan Reference / Gale; read through Encyclopedia.com. https://www.encyclopedia.com/people/philosophy-and-religion/hinduism-biographies/ramakrishna", "original_work_identity": {}, "publication_year": 2005, "publisher_or_institution": "Macmillan Reference / Gale; read through Encyclopedia.com", "rights_or_access_note": "Reference entry; short research excerpts only.", "source_status": "approved", "source_type": "institutional", "storage_path": null, "title": "Ramakrishna (Encyclopedia of Religion, 2nd edition)", "url": "https://www.encyclopedia.com/people/philosophy-and-religion/hinduism-biographies/ramakrishna"}, "source_id": "d5a13923-a194-487e-8a9b-0d61f574d7e7"}], "unmatched_passage_links": []}'::jsonb,'draft','ai_candidate');
insert into original_claims values ('f225e1d1-7a6e-4156-9a9e-d9c8bff18bf8','{"approval_origin": "ai_candidate", "certainty": "high", "claim_id": "f225e1d1-7a6e-4156-9a9e-d9c8bff18bf8", "claim_kind": "established_fact", "claim_relations": [], "claim_text": "Britannica describes the Brahmo Samaj as a theistic movement within Hinduism founded in Calcutta in 1828 by Ram Mohun Roy that does not accept the authority of the Vedas or belief in avatars; the Order''s biography agrees on the 1828 founding.", "current_status": "draft", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "HISTORICAL_FACT", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification"], "evidence_type": "historical_inference", "lens": {"field_id": "15827701-bdce-4de2-9973-573ae507ae28", "field_label": "Historical context and reception", "parameter_id": "1565b520-d15c-4880-aef2-9f7cba878070", "parameter_name": "Historical context and reception"}, "parent_claim_id": null, "personality_id": "9ef04ec3-7bf1-4210-a951-1d6da7b2fc99", "personality_name": "Ramakrishna Paramahamsa", "reviewer_decision": null, "sources": [{"evidence_excerpt": "But he always went back to the Vedas for his spiritual inspiration. The Brahmo Samaj, which he founded in 1828, was dedicated to the \"worship and adoration of the Eternal, the Unsearchable, the Immutable Being, who is the Author and Preserver of the Universe\". The Samaj was open to all without distinction of colour, creed, caste, nation, or religion.", "link_id": "57466764-ca1d-4f1d-a7b1-b1cd07e35a5d", "page_or_section": "The Brahmo Samaj, which he founded in 1828", "passages": [], "relationship": "supports", "source": {"author": "Swami Nikhilananda", "authority_metadata": {"verified_at": "2026-10-12"}, "citation": "Swami Nikhilananda. Introduction to The Gospel of Sri Ramakrishna (biography of Sri Ramakrishna). Ramakrishna-Vivekananda Center, New York (1942); online edition ramakrishnavivekananda.info. https://www.ramakrishnavivekananda.info/gospel/introduction/introduction.htm", "original_work_identity": {}, "publication_year": 1942, "publisher_or_institution": "Ramakrishna-Vivekananda Center, New York (1942); online edition ramakrishnavivekananda.info", "rights_or_access_note": "Unofficial online edition of a monk''s biography of his own order''s founder; institutional tradition, not independent history.", "source_status": "approved", "source_type": "institutional", "storage_path": null, "title": "Introduction to The Gospel of Sri Ramakrishna (biography of Sri Ramakrishna)", "url": "https://www.ramakrishnavivekananda.info/gospel/introduction/introduction.htm"}, "source_id": "61914dc5-f03e-451c-81ef-145d18079b40"}, {"evidence_excerpt": "The Editors of Encyclopaedia Britannica Last Updated: Article History Table of Contents Category: History & Society Sanskrit: “Society of Brahma” (Show more) Brahmo also spelled: Brahma (Show more) Date: 1828 - present (Show more) Areas Of Involvement: Christianity Hinduism Islam polytheism religious syncretism (Show more) Related People: Ram Mohan Roy …", "link_id": "1c7c9c12-54ae-4e3a-8f93-958420f4157e", "page_or_section": "Britannica: Brahmo Samaj", "passages": [{"chunk_id": "53ba27ab-8bca-43c3-81d0-29db6062de17", "confidence": null, "excerpt": "The Editors of Encyclopaedia Britannica Last Updated: Article History Table of Contents Category: History & Society Sanskrit: “Society of Brahma” (Show more) Brahmo also spelled: Brahma (Show more) Date: 1828 - present (Show more) Areas Of Involvement: Christianity Hinduism Islam polytheism religious syncretism (Show more) Related People: Ram Mohan Roy …", "excerpt_truncated": true, "is_active": true, "link_method": null, "page_or_section": "Britannica: Brahmo Samaj", "relationship": "supports", "section_title": "Ramakrishna Paramahamsa: Britannica descri