insert into original_claims values ('4a430925-c049-4438-a455-b4c2d2c2acaf','{"approval_origin": "ai_candidate", "certainty": "medium", "claim_id": "4a430925-c049-4438-a455-b4c2d2c2acaf", "claim_kind": "traditional_account", "claim_relations": [], "claim_text": "The Order''s biography says the Dakshineswar temple garden built by Rani Rasmani, centred on Kali as Bhavatarini, was dedicated on 31 May 1855, and that Ramakrishna came to it with his elder brother Ramkumar, who was appointed priest of the Kali temple.", "current_status": "draft", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification"], "evidence_type": "traditional_narrative", "lens": {"field_id": "e104f80d-b6c9-4043-8391-b78430f2cfc1", "field_label": "Life and vocation", "parameter_id": "73d95f66-e9fe-4c44-9891-5e4951695c81", "parameter_name": "Life and vocation"}, "parent_claim_id": null, "personality_id": "9ef04ec3-7bf1-4210-a951-1d6da7b2fc99", "personality_name": "Ramakrishna Paramahamsa", "reviewer_decision": null, "sources": [{"evidence_excerpt": "(Romain Holland, Prophets of the New India, p. 11.) Rani Rasmani spent a fortune for the construction of the temple garden and another fortune for its dedication ceremony, which took place on May 31, 1855. Sri Ramakrishna — henceforth we shall call Gadadhar by this familiar name —1 came to the temple garden with his elder brother Ramkumar, who was appointed …", "link_id": "18196d55-a0ce-4f1d-9c2d-fda007a762eb", "page_or_section": "Gospel introduction: Kali", "passages": [{"chunk_id": "74166853-47c7-49c7-bae9-792140f08f5a", "confidence": null, "excerpt": "(Romain Holland, Prophets of the New India, p. 11.) Rani Rasmani spent a fortune for the construction of the temple garden and another fortune for its dedication ceremony, which took place on May 31, 1855. Sri Ramakrishna — henceforth we shall call Gadadhar by this familiar name —1 came to the temple garden with his elder brother Ramkumar, who was appointed …", "excerpt_truncated": true, "is_active": true, "link_method": null, "page_or_section": "Gospel introduction: Kali", "relationship": "supports", "section_title": "Ramakrishna Paramahamsa: The Order''s biography says the Dakshineswar temple garden built by Rani Rasmani, centred on Kali as Bhavatarini, was dedicated on 31 May 1855, and that Ramakrishna came to it with his elder brother Ramkumar, who was appointed priest of the Kali temple.", "source_id": "61914dc5-f03e-451c-81ef-145d18079b40", "textual_layer": "Ramakrishna Order monastic biography (Nikhilananda, 1942)"}], "relationship": "supports", "source": {"author": "Swami Nikhilananda", "authority_metadata": {"verified_at": "2026-10-12"}, "citation": "Swami Nikhilananda. Introduction to The Gospel of Sri Ramakrishna (biography of Sri Ramakrishna). Ramakrishna-Vivekananda Center, New York (1942); online edition ramakrishnavivekananda.info. https://www.ramakrishnavivekananda.info/gospel/introduction/introduction.htm", "original_work_identity": {}, "publication_year": 1942, "publisher_or_institution": "Ramakrishna-Vivekananda Center, New York (1942); online edition ramakrishnavivekananda.info", "rights_or_access_note": "Unofficial online edition of a monk''s biography of his own order''s founder; institutional tradition, not independent history.", "source_status": "approved", "source_type": "institutional", "storage_path": null, "title": "Introduction to The Gospel of Sri Ramakrishna (biography of Sri Ramakrishna)", "url": "https://www.ramakrishnavivekananda.info/gospel/introduction/introduction.htm"}, "source_id": "61914dc5-f03e-451c-81ef-145d18079b40"}], "unmatched_passage_links": []}'::jsonb,'draft','ai_candidate');
insert into original_claims values ('4f33bfc4-3624-4e0b-9a1e-cbc3e0061f7f','{"approval_origin": "ai_candidate", "certainty": "medium", "claim_id": "4f33bfc4-3624-4e0b-9a1e-cbc3e0061f7f", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "The Brahmo leader Pratap Chandra Mozoomdar, an admirer, wrote to Max Müller in 1895 that Ramakrishna knew no Sanskrit and perhaps not enough Bengali, attributing his wisdom to \"genius and practical observation\"; Müller found the judgement impartial, and the Order''s biography likewise says he hardly knew how to write his name.", "current_status": "draft", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "HISTORICAL_INFERENCE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification"], "evidence_type": "historical_inference", "lens": {"field_id": "e104f80d-b6c9-4043-8391-b78430f2cfc1", "field_label": "Life and vocation", "parameter_id": "73d95f66-e9fe-4c44-9891-5e4951695c81", "parameter_name": "Life and vocation"}, "parent_claim_id": null, "personality_id": "9ef04ec3-7bf1-4210-a951-1d6da7b2fc99", "personality_name": "Ramakrishna Paramahamsa", "reviewer_decision": null, "sources": [{"evidence_excerpt": "For all that, he was, as you say, a real Mahatman, and I would not with- draw a single word I wrote in his praise. Ramakr/shna was not in the least a Vedantist, except that every Hindu uncon- sciously imbibes from the atmosphere around some amount of Vedantism, which is the philosophical backbone of every national cult He did not know a word of Sanskrit, …", "link_id": "869ce467-095f-411a-abf9-ad55cdb5f107", "page_or_section": "Müller 1898, Mozoomdar''s judgement", "passages": [{"chunk_id": "02dda01e-82a9-452f-b67c-67f18f7dcd08", "confidence": null, "excerpt": "For all that, he was, as you say, a real Mahatman, and I would not with- draw a single word I wrote in his praise. Ramakr/shna was not in the least a Vedantist, except that every Hindu uncon- sciously imbibes from the atmosphere around some amount of Vedantism, which is the philosophical backbone of every national cult He did not know a word of Sanskrit, …", "excerpt_truncated": true, "is_active": true, "link_method": null, "page_or_section": "Müller 1898, Mozoomdar''s judgement", "relationship": "supports", "section_title": "Ramakrishna Paramahamsa: Mozoomdar told Müller that Ramakrishna was \"not in the least a Vedantist\" beyond the Vedantism every Hindu absorbs, whereas the Order treats his Advaita realization under Totapuri as the culmination of his sadhana and later scholars debate whether he saw himself as a Vedantin.", "source_id": "1dd0350d-81fc-4168-84cd-2cde60317874", "textual_layer": "Contemporary Oxford scholar''s account (1898), partly relayed from Vivekananda and the Indian press"}], "relationship": "supports", "source": {"author": "F. Max Müller", "authority_metadata": {"verified_at": "2026-10-12"}, "citation": "F. Max Müller. Ramakrishna: His Life and Sayings. Charles Scribner''s Sons (first edition Longmans, London, November 1898); Internet Archive scan. https://archive.org/download/rmakrishnahisl00mliala/rmakrishnahisl00mliala.pdf", "original_work_identity": {}, "publication_year": 1899, "publisher_or_institution": "Charles Scribner''s Sons (first edition Longmans, London, November 1898); Internet Archive scan", "rights_or_access_note": "Public-domain 1899 edition; OCR text layer garbles some Bengali and Sanskrit names.", "source_status": "approved", "source_type": "scholarly_book", "storage_path": null, "title": "Ramakrishna: His Life and Sayings", "url": "https://archive.org/download/rmakrishnahisl00mliala/rmakrishnahisl00mliala.pdf"}, "source_id": "1dd0350d-81fc-4168-84cd-2cde60317874"}, {"evidence_excerpt": "Keshab, on the other hand, regarded image worship as idolatry and gave allegorical explanations of the Hindu deities. Keshab was an orator and a writer of books and magazine articles; Sri Ramakrishna had a horror of lecturing and hardly knew how to write his own name, Keshab''s fame spread far and wide, even reaching the distant shores of England; the Master …", "link_id": "b71287bf-8664-4dec-ac97-f41cd084bb9c", "page_or_section": "Sri Ramakrishna had a horror of lecturing and hardly knew how to write his own name", "passages": [], "relationship": "supports", "source": {"author": "Swami Nikhilananda", "authority_metadata": {"verified_at": "2026-10-12"}, "citation": "Swami Nikhilananda. Introduction to The Gospel of Sri Ramakrishna (biography of Sri Ramakrishna). Ramakrishna-Vivekananda Center, New York (1942); online edition ramakrishnavivekananda.info. https://www.ramakrishnavivekananda.info/gospel/introduction/introduction.htm", "original_work_identity": {}, "publication_year": 1942, "publisher_or_institution": "Ramakrishna-Vivekananda Center, New York (1942); online edition ramakrishnavivekananda.info", "rights_or_access_note": "Unofficial online edition of a monk''s biography of his own order''s founder; institutional tradition, not independent history.", "source_status": "approved", "source_type": "institutional", "storage_path": null, "title": "Introduction to The Gospel of Sri Ramakrishna (biography of Sri Ramakrishna)", "url": "https://www.ramakrishnavivekananda.info/gospel/introduction/introduction.htm"}, "source_id": "61914dc5-f03e-451c-81ef-145d18079b40"}], "unmatched_passage_links": []}'::jsonb,'draft','ai_candidate');
