insert into original_claims values ('ee73dc34-1a5b-45c7-8de3-62d5901b682b','{"approval_origin": "ai_candidate", "certainty": "medium", "claim_id": "ee73dc34-1a5b-45c7-8de3-62d5901b682b", "claim_kind": "traditional_account", "claim_relations": [], "claim_text": "The Order says that while seeking union with Krishna he regarded himself as a gopi (cowherd woman) of Vrindavan and, at his request, his patron Mathur provided woman''s dress and jewelry; a scholarly reference entry lists his \"fondness for wearing women''s clothing\" among the \"scandalous particulars\" long played down.", "current_status": "draft", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification"], "evidence_type": "traditional_narrative", "lens": {"field_id": "4a09d425-67c9-41cd-afb7-cca6ad1d1a96", "field_label": "Practice and discipline", "parameter_id": "a7e372c4-dbbd-4d61-901b-73713d1e3670", "parameter_name": "Practice and discipline"}, "parent_claim_id": null, "personality_id": "9ef04ec3-7bf1-4210-a951-1d6da7b2fc99", "personality_name": "Ramakrishna Paramahamsa", "reviewer_decision": null, "sources": [{"evidence_excerpt": "He regarded himself as one of the gopis of Vrindavan, mad with longing for her divine Sweetheart. At his request Mathur provided him with woman''s dress and jewelry. In this love-pursuit, food and drink were forgotten.", "link_id": "6bbd6299-2f51-4b0c-8e58-16bb06a49110", "page_or_section": "Gospel introduction: In communion with the Divine Beloved", "passages": [{"chunk_id": "730510e8-ba47-4898-8be2-51572ec57e9d", "confidence": null, "excerpt": "He regarded himself as one of the gopis of Vrindavan, mad with longing for her divine Sweetheart. At his request Mathur provided him with woman''s dress and jewelry. In this love-pursuit, food and drink were forgotten.", "excerpt_truncated": false, "is_active": true, "link_method": null, "page_or_section": "Gospel introduction: In communion with the Divine Beloved", "relationship": "supports", "section_title": "Ramakrishna Paramahamsa: The Order says that while seeking union with Krishna he regarded himself as a gopi (cowherd woman) of Vrindavan and, at his request, his patron Mathur provided woman''s dress and jewelry; a scholarly reference entry lists his \"fondness for wearing women''s clothing\" among the \"scandalous particulars\" long played down.", "source_id": "61914dc5-f03e-451c-81ef-145d18079b40", "textual_layer": "Ramakrishna Order monastic biography (Nikhilananda, 1942)"}], "relationship": "supports", "source": {"author": "Swami Nikhilananda", "authority_metadata": {"verified_at": "2026-10-12"}, "citation": "Swami Nikhilananda. Introduction to The Gospel of Sri Ramakrishna (biography of Sri Ramakrishna). Ramakrishna-Vivekananda Center, New York (1942); online edition ramakrishnavivekananda.info. https://www.ramakrishnavivekananda.info/gospel/introduction/introduction.htm", "original_work_identity": {}, "publication_year": 1942, "publisher_or_institution": "Ramakrishna-Vivekananda Center, New York (1942); online edition ramakrishnavivekananda.info", "rights_or_access_note": "Unofficial online edition of a monk''s biography of his own order''s founder; institutional tradition, not independent history.", "source_status": "approved", "source_type": "institutional", "storage_path": null, "title": "Introduction to The Gospel of Sri Ramakrishna (biography of Sri Ramakrishna)", "url": "https://www.ramakrishnavivekananda.info/gospel/introduction/introduction.htm"}, "source_id": "61914dc5-f03e-451c-81ef-145d18079b40"}, {"evidence_excerpt": "Seen in this light, it is understandable that Vivekananda and the early disciples would have been sensitive about foregrounding the importance of Tantra for Ramakrishna. But beyond t