insert into original_claims values ('ad245e15-54a5-4b4c-9032-2a28bbb95cb5','{"approval_origin": "ai_candidate", "certainty": "medium", "claim_id": "ad245e15-54a5-4b4c-9032-2a28bbb95cb5", "claim_kind": "traditional_account", "claim_relations": [], "claim_text": "The Order reports that at Cossipore, in samadhi, Ramakrishna wept and told Narendra, \"Today I have given you my all and I am now only a poor fakir\"; this is traditional narrative about a spiritual transmission that scholars describe as resting on official accounts.", "current_status": "draft", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification"], "evidence_type": "traditional_narrative", "lens": {"field_id": "efad4a5b-785c-40fe-91c8-637186995e83", "field_label": "Teachers and lineage", "parameter_id": "fbad22f1-3f0c-4bf7-a214-28df38348475", "parameter_name": "Teachers and lineage"}, "parent_claim_id": null, "personality_id": "9ef04ec3-7bf1-4210-a951-1d6da7b2fc99", "personality_name": "Ramakrishna Paramahamsa", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Regaining presently the normal mood, he found the Master weeping. Sri Ramakrishna said to him: \"Today I have given you my all and I am now only a poor fakir, possessing nothing. By this power you will do immense good in the world, and not until it is accomplished will you return.\" Henceforth the Master lived in the disciple.", "link_id": "e36a511a-7256-4106-a1e3-0baa4f5ca954", "page_or_section": "Gospel introduction: Last days at Cossipore", "passages": [{"chunk_id": "7c7324ed-6716-41bb-a909-45abdd2739cf", "confidence": null, "excerpt": "Regaining presently the normal mood, he found the Master weeping. Sri Ramakrishna said to him: \"Today I have given you my all and I am now only a poor fakir, possessing nothing. By this power you will do immense good in the world, and not until it is accomplished will you return.\" Henceforth the Master lived in the disciple.", "excerpt_truncated": false, "is_active": true, "link_method": null, "page_or_section": "Gospel introduction: Last days at Cossipore", "relationship": "supports", "section_title": "Ramakrishna Paramahamsa: The Order reports that at Cossipore, in samadhi, Ramakrishna wept and told Narendra, \"Today I have given you my all and I am now only a poor fakir\"; this is traditional narrative about a spiritual transmission that scholars describe as resting on official accounts.", "source_id": "61914dc5-f03e-451c-81ef-145d18079b40", "textual_layer": "Ramakrishna Order monastic biography (Nikhilananda, 1942)"}], "relationship": "supports", "source": {"author": "Swami Nikhilananda", "authority_metadata": {"verified_at": "2026-10-12"}, "citation": "Swami Nikhilananda. Introduction to The Gospel of Sri Ramakrishna (biography of Sri Ramakrishna). Ramakrishna-Vivekananda Center, New York (1942); online edition ramakrishnavivekananda.info. https://www.ramakrishnavivekananda.info/gospel/introduction/introduction.htm", "original_work_identity": {}, "publication_year": 1942, "publisher_or_institution": "Ramakrishna-Vivekananda Center, New York (1942); online edition ramakrishnavivekananda.info", "rights_or_access_note": "Unofficial online edition of a monk''s biography of his own order''s founder; institutional tradition, not independent history.", "source_status": "approved", "source_type": "institutional", "storage_path": null, "title": "Introduction to The Gospel of Sri Ramakrishna (biography of Sri Ramakrishna)", "url": "https://www.ramakrishnavivekananda.info/gospel/introduction/introduction.htm"}, "source_id": "61914dc5-f03e-451c-81ef-145d18079b40"}, {"evidence_excerpt": "325). Official accounts report that just before his death Ramakrishna transferred his spiritual powers to Narendranath, saying, \"by the force of the power transmitted by me, great things will be done by you\" (Life, 1989, vol. 1, p.", "link_id": "3bbaea6d-ee2f-457e-851c-1701059b9757", "page_or_section": "Official accounts report that just before his death Ramakrishna transferred his spiritual powers to Narendranath", "passages": [], "relationship": "supports", "source": {"author": "Thomas J. Hopkins (1987); revised by Brian A. Hatcher (2005)", "authority_metadata": {"verified_at": "2026-10-12"}, "citation": "Thomas J. Hopkins (1987); revised by Brian A. Hatcher (2005). Vivekananda (Encyclopedia of Religion, 2nd edition). Macmillan Reference / Gale; read through Encyclopedia.com. https://www.encyclopedia.com/people/philosophy-and-religion/hinduism-biographies/vivekananda", "original_work_identity": {}, "publication_year": 2005, "publisher_or_institution": "Macmillan Reference / Gale; read through Encyclopedia.com", "rights_or_access_note": "Reference entry; short research excerpts only.", "source_status": "approved", "source_type": "institutional", "storage_path": null, "title": "Vivekananda (Encyclopedia of Religion, 2nd edition)", "url": "https://www.encyclopedia.com/people/philosophy-and-religion/hinduism-biographies/vivekananda"}, "source_id": "685aedc9-c39f-4c63-a43b-2b7d4086b6ae"}], "unmatched_passage_links": []}'::jsonb,'draft','ai_candidate');
insert into original_claims values ('b0d5d60d-c2dc-43f8-9fe3-34a21ce75cff','{"approval_origin": "ai_candidate", "certainty": "medium", "claim_id": "b0d5d60d-c2dc-43f8-9fe3-34a21ce75cff", "claim_kind": "traditional_account", "claim_relations": [], "claim_text": "In the Order''s account Ramakrishna was grateful to the Divine Mother for sending him a disciple who doubted his realizations, often asking Narendra to test him as money-changers test coins, and laughing at his biting criticism of his samadhi.", "current_status": "draft", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification"], "evidence_type": "traditional_narrative", "lens": {"field_id": "efad4a5b-785c-40fe-91c8-637186995e83", "field_label": "Teachers and lineage", "parameter_id": "fbad22f1-3f0c-4bf7-a214-28df38348475", "parameter_name": "Teachers and lineage"}, "parent_claim_id": null, "personality_id": "9ef04ec3-7bf1-4210-a951-1d6da7b2fc99", "personality_name": "Ramakrishna Paramahamsa", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Sri Ramakrishna was grateful to the Divine Mother for sending him one who doubted his own realizations. Often he asked Narendra to test him as the money-changers test their coins. He laughed at Narendra''s biting criticism of his spiritual experiences and samadhi.", "link_id": "93521166-433b-4d5c-878f-d72e1e775b3a", "page_or_section": "Gospel introduction: Narendra", "passages": [{"chunk_id": "1df793d7-77d8-41cb-94c5-ee85882ece36", "confidence": null, "excerpt": "Sri Ramakrishna was grateful to the Divine Mother for sending him one who doubted his own realizations. Often he asked Narendra to test him as the money-changers test their coins. He laughed at Narendra''s biting criticism of h