insert into original_claims values ('c8d59d4f-47fc-42a3-9a72-26fc16c3f97b','{"approval_origin": "ai_candidate", "certainty": "medium", "claim_id": "c8d59d4f-47fc-42a3-9a72-26fc16c3f97b", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "After Ramakrishna''s death Sarada became \"Sarada Ma, the Holy Mother\" (d. 1920), a status that scholars read as reflecting both her service to him and the power of the Divine Mother.", "current_status": "draft", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "SCHOLARLY_INTERPRETATION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "efad4a5b-785c-40fe-91c8-637186995e83", "field_label": "Teachers and lineage", "parameter_id": "fbad22f1-3f0c-4bf7-a214-28df38348475", "parameter_name": "Teachers and lineage"}, "parent_claim_id": null, "personality_id": "9ef04ec3-7bf1-4210-a951-1d6da7b2fc99", "personality_name": "Ramakrishna Paramahamsa", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Before his premature death in 1902, Vivekananda traveled widely in India and the West, promoting what he called \"Practical Vedānta,\" a religious vision that supported not just spiritual progress, but interreligious understanding, social uplift, and Indian national pride. As for Sāradā Devī, after Ramakrishna''s death she was elevated to the status of Sāradā …", "link_id": "95148b31-b971-4de9-945c-73fe485c4bef", "page_or_section": "Encyclopedia of Religion", "passages": [{"chunk_id": "a2858663-a3ff-41e4-94a0-c5f75f44a4e5", "confidence": null, "excerpt": "Before his premature death in 1902, Vivekananda traveled widely in India and the West, promoting what he called \"Practical Vedānta,\" a religious vision that supported not just spi