insert into original_claims values ('e33d7beb-875d-489b-958d-ac717133982f','{"approval_origin": "ai_candidate", "certainty": "medium", "claim_id": "e33d7beb-875d-489b-958d-ac717133982f", "claim_kind": "traditional_account", "claim_relations": [], "claim_text": "The Order''s biography says Ramakrishna married Sarada, a little girl of five from Jayrambati, in an early marriage that was in the nature of a betrothal, and that it \"remained for ever unconsummated\"; a scholarly reference entry makes the same statement.", "current_status": "draft", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification"], "evidence_type": "traditional_narrative", "lens": {"field_id": "efad4a5b-785c-40fe-91c8-637186995e83", "field_label": "Teachers and lineage", "parameter_id": "fbad22f1-3f0c-4bf7-a214-28df38348475", "parameter_name": "Teachers and lineage"}, "parent_claim_id": null, "personality_id": "9ef04ec3-7bf1-4210-a951-1d6da7b2fc99", "personality_name": "Ramakrishna Paramahamsa", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Such early marriage in India is in the nature of a betrothal, the marriage being consummated when the girl attains puberty. But in this case the marriage remained for ever unconsummated. Sri Ramakrishna lived at Kamarpukur about a year and a half and then returned to Dakshineswar.", "link_id": "0ea3d757-97aa-4639-9850-487498cf72f1", "page_or_section": "Gospel introduction: Marriage and after", "passages": [{"chunk_id": "d795cec8-1729-4518-a837-46837fc98739", "confidence": null, "excerpt": "Such early marriage in India is in the nature of a betrothal, the marriage being consummated when the girl attains puberty. But in this case the marriage remained for ever unconsummated. Sri Ramakrishna lived at Kamarpukur about a year and a half and then returned to Dakshineswar.", "excerpt_truncated": false, "is_active": true, "link_method": null, "page_or_section": "Gospel introduction: Marriage and after", "relationship": "supports", "section_title": "Ramakrishna Paramahamsa: The Order''s biography says Ramakrishna married Sarada, a little girl of five from Jayrambati, in an early marriage that was in the nature of a betrothal, and that it \"remained for ever unconsummated\"; a scholarly reference entry makes the same statement.", "source_id": "61914dc5-f03e-451c-81ef-145d18079b40", "textual_layer": "Ramakrishna Order monastic biography (Nikhilananda, 1942)"}], "relationship": "supports", "source": {"author": "Swami Nikhilananda", "authority_metadata": {"verified_at": "2026-10-12"}, "citation": "Swami Nikhilananda. Introduction to The Gospel of Sri Ramakrishna (biography of Sri Ramakrishna). Ramakrishna-Vivekananda Center, New York (1942); online edition ramakrishnavivekananda.info. https://www.ramakrishnavivekananda.info/gospel/introduction/introduction.htm", "original_work_identity": {}, "publication_year": 1942, "publisher_or_institution": "Ramakrishna-Vivekananda Center, New York (1942); online edition ramakrishnavivekananda.info", "rights_or_access_note": "Unofficial online edition of a monk''s biography of his own order''s founder; institutional tradition, not independent history.", "source_status": "approved", "source_type": "institutional", "storage_path": null, "title": "Introduction to The Gospel of Sri Ramakrishna (biography of Sri Ramakrishna)", "url": "https://www.ramakrishnavivekananda.info/gospel/introduction/introduction.htm"}, "source_id": "61914dc5-f03e-451c-81ef-145d18079b40"}, {"evidence_excerpt": "His family arranged for him to return to their village, where he was married to a local girl, Sāradāmaṇi Devī, then age six. Sāradā remained in her parents'' home for several more years, only visiting Ramakrishna at Dakshineshwar for the first time in 1872. By this time Ramakrishna was practicing strict celibacy, his ascetic inclinations routinely summed up …", "link_id": "d1565d08-9907-47b8-9e7f-e38300cd35b6", "page_or_section": "Sāradā remained in her parents'' home for several more years", "passages": [], "relationship": "supports", "source": {"author": "Walter G. Neevel Jr. (1987); revised by Brian A. Hatcher (2005)", "authority_metadata": {"verified_at": "2026-10-12"}, "citation": "Walter G. Neevel Jr. (1987); revised by Brian A. Hatcher (2005). Ramakrishna (Encyclopedia of Religion, 2nd edition). Macmillan Reference / Gale; read through Encyclopedia.com. https://www.encyclopedia.com/people/philosophy-and-religion/hinduism-biographies/ramakrishna", "original_work_identity": {}, "publication_year": 2005, "publisher_or_institution": "Macmillan Reference / Gale; read through Encyclopedia.com", "rights_or_access_note": "Reference entry; short research excerpts only.", "source_status": "approved", "source_type": "institutional", "storage_path": null, "title": "Ramakrishna (Encyclopedia of Religion, 2nd edition)", "url": "https://www.encyclopedia.com/people/philosophy-and-religion/hinduism-biographies/ramakrishna"}, "source_id": "d5a13923-a194-487e-8a9b-0d61f574d7e7"}], "unmatched_passage_links": []}'::jsonb,'draft','ai_candidate');
insert into original_claims values ('e76a77c7-134b-4723-92c7-2af6224bd1b1','{"approval_origin": "ai_candidate", "certainty": "medium", "claim_id": "e76a77c7-134b-4723-92c7-2af6224bd1b1", "claim_kind": "traditional_account", "claim_relations": [], "claim_text": "The Order says that a few months after Sarada joined him at Dakshineswar in 1872 he arranged a special worship of the Divine Mother and seated Sarada herself as the living image; both reportedly went into samadhi, and the Order presents their bond as a spiritual companionship.", "current_status": "draft", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification"], "evidence_type": "traditional_narrative", "lens": {"field_id": "efad4a5b-785c-40fe-91c8-637186995e83", "field_label": "Teachers and lineage", "parameter_id": "fbad22f1-3f0c-4bf7-a214-28df38348475", "parameter_name": "Teachers and lineage"}, "parent_claim_id": null, "personality_id": "9ef04ec3-7bf1-4210-a951-1d6da7b2fc99", "personality_name": "Ramakrishna Paramahamsa", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Life at Dakshineshwar Sri Ramakrishna looked upon Sarada Devi as a special manifestation of Divine Mother of the universe. In 1872, on the night of the Phala-harini-Kali-puja, he ritualistically worshipped Sarada Devi as the Divine Mother, thereby awakening universal Motherhood latent in her. When disciples began to gather around Sri Ramakrishna, Sarada …", "link_id": "3617e57c-6a0d-4248-8a87-f71e9b2741b8", "page_or_section": "he ritualistically worshipped Sarada Devi as the Divine Mother", "passages": [], "relationship": "supports", "source": {"author": null, "authority_metadata": {"verified_at": "2026-10-12"}, "citation": "Sri Sarada Devi. Belur Math, Ramakrishna Math and Ramakrishna Mission. https://belurmath.org/sri-sarada-devi/", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Belur Math, Ramakrishna Math and Ramakrishna Mission", "rights_or_access_note": "Public original; short research excerpts.", "source_status": "approved", "source_type": "institutional", "storage_path": null, "title": "Sri Sarada Devi", "url": "https://belurmath.org/sri-sarada-devi/"}, "source_id": "2aa55178-75fe-4a1c-92b5-3ec77c532dca"}, {"evidence_excerpt": "A few months after Sarada Devi''s arrival Sri Ramakrishna arranged, on an auspicious day, a special worship of Kali, the Divine Mother. Instead of an image of the Deity, he placed on the seat the living image, Sarada Devi herself. The worshipper and the worshipped went into deep samadhi and in the transcendental plane their souls were united.", "link_id": "fb0b7ea9-a26f-4bca-bb35-561dff6a32d1", "page_or_section": "Gospel introduction: Relation with his wife", "passages": [{"chunk_id": "ecd02658-a920-444d-9fde-5b9dd1e9aaad", "confidence": null, "excerpt": "A few months after Sarada Devi''s arrival Sri Ramakrishna arranged, on an auspicious day, a special worship of Kali, the Divine Mother. Instead of an image of the Deity, he placed on the seat the living image, Sarada Devi herself. The worshipper and the worshipped went into deep samadhi and in the transcendental plane their souls were united.", "excerpt_truncated": false, "is_active": true, "link_method": null, "page_or_section": "Gospel introduction: Relation with his wife", "relationship": "supports", "section_title": "Ramakrishna Paramahamsa: The Order says that a few months after Sarada joined him at Dakshineswar in 1872 he arranged a special worship of the Divine Mother and seated Sarada herself as the living image; both reportedly went into samadhi, and the Order presents their bond as a spiritual companionship.", "source_id": "61914dc5-f03e-451c-81ef-145d18079b40", "textual_layer": "Ramakrishna Order monastic biography (Nikhilananda, 1942)"}], "relationship": "supports", "source": {"author": "Swami Nikhilananda", "authority_metadata": {"verified_at": "2026-10-12"}, "citation": "Swami Nikhilananda. Introduction to The Gospel of Sri Ramakrishna (biography of Sri Ramakrishna). Ramakrishna-Vivekananda Center, New York (1942); online edition ramakrishnavivekananda.info. https://www.ramakrishnavivekananda.info/gospel/introduction/introduction.htm", "original_work_identity": {}, "publication_year": 1942, "publisher_or_institution": "Ramakrishna-Vivekananda Center, New York (1942); online edition ramakrishnavivekananda.info", "rights_or_access_note": "Unofficial online edition of a monk''s biography of his own order''s founder; institutional tradition, not independent history.", "source_status": "approved", "source_type": "institutional", "storage_path": null, "title": "Introduction to The Gospel of Sri Ramakrishna (biography of Sri Ramakrishna)", "url": "https://www.ramakrishnavivekananda.info/gospel/introduction/introduction.htm"}, "source_id": "61914dc5-f03e-451c-81ef-145d18079b40"}], "unmatched_passage_links": []}'::jsonb,'draft','ai_candidate');
