insert into original_claims values ('0886e626-38d7-482f-bbbc-24db2fb27d60','{"approval_origin": "ai_candidate", "certainty": "high", "claim_id": "0886e626-38d7-482f-bbbc-24db2fb27d60", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "Visiting the scholar Vidyasagar on 5 August 1882, Ramakrishna is recorded saying that the Vedas, Puranas, Tantras and philosophies have been \"defiled\" by being spoken, while Brahman alone has not, since no one can say what it is; Vidyasagar is recorded replying that he had learnt something new.", "current_status": "draft", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification"], "evidence_type": "direct_primary_text", "lens": {"field_id": "d5ea0700-b35b-4155-ab8f-33c0deb87b03", "field_label": "Teachings and philosophy", "parameter_id": "19c06971-4bed-4e8e-ad0d-ea8a32be0580", "parameter_name": "Teachings and philosophy"}, "parent_claim_id": null, "personality_id": "9ef04ec3-7bf1-4210-a951-1d6da7b2fc99", "personality_name": "Ramakrishna Paramahamsa", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Only one thing has not been defiled in this way, and that is Brahman. No one has ever been able to say what Brahman is.\" VIDYASAGAR (to his friends): \"Oh! That is a remarkable statement. I have learnt something new today.\" MASTER: \"A man had two sons.", "link_id": "0d3c682b-46e8-4535-97b7-1d3a6f2d4ec9", "page_or_section": "Gospel vol. 1, ch. 3 (5 Aug 1882)", "passages": [{"chunk_id": "d9f8135e-db35-48e5-832c-bf0790227ca9", "confidence": null, "excerpt": "Only one thing has not been defiled in this way, and that is Brahman. No one has ever been able to say what Brahman is.\" VIDYASAGAR (to his friends): \"Oh! That is a remarkable statement. I have learnt something new today.\" MASTER: \"A man had two sons.", "excerpt_truncated": false, "is_active": true, "link_method": null, "page_or_section": "Gospel vol. 1, ch. 3 (5 Aug 1882)", "relationship": "supports", "section_title": "Ramakrishna Paramahamsa: Visiting the scholar Vidyasagar on 5 August 1882, Ramakrishna is recorded saying that the Vedas, Puranas, Tantras and philosophies have been \"defiled\" by being spoken, while Brahman alone has not, since no one can say what it is; Vidyasagar is recorded replying that he had learnt something new.", "source_id": "6bd19767-fd30-4b73-900b-11576daedd8e", "textual_layer": "Reported teachings: M.''s diary-style record of Ramakrishna''s conversations, in translation"}], "relationship": "supports", "source": {"author": "Mahendranath Gupta (M.), translated by Swami Nikhilananda", "authority_metadata": {"verified_at": "2026-10-12"}, "citation": "Mahendranath Gupta (M.), translated by Swami Nikhilananda. The Gospel of Sri Ramakrishna (Kathamrita): conversations recorded by M.. Ramakrishna-Vivekananda Center, New York (1942); online edition ramakrishnavivekananda.info. https://www.ramakrishnavivekananda.info/gospel/gospel.htm", "original_work_identity": {}, "publication_year": 1942, "publisher_or_institution": "Ramakrishna-Vivekananda Center, New York (1942); online edition ramakrishnavivekananda.info", "rights_or_access_note": "Translation of the Bengali Kathamrita; Sil and others argue the translation omits or softens some passages.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "The Gospel of Sri Ramakrishna (Kathamrita): conversations recorded by M.", "url": "https://www.ramakrishnavivekananda.info/gospel/gospel.htm"}, "source_id": "6bd19767-fd30-4b73-900b-11576daedd8e"}, {"evidence_excerpt": "Also, he never knew when he would be in trance and lose control of his body and outfit.’ (LP, II: Gurubhāva-Uttarārdha, 223). He was apprehensive and hesitant on his way to Paṇḍit Ishwarchandra Vidyāsāgar’s (1820–91) home to meet him. He confided to his escort M like a child: ‘My shirt is unbuttoned.", "link_id": "af4bdd21-1763-4527-a067-995a92160d5e", "page_or_section": "He was apprehensive and hesitant on his way to Paṇḍit Ishwarchandra Vidyāsāgar", "passages": [], "relationship": "supports", "source": {"author": "Narasingha Prosad Sil", "authority_metadata": {"verified_at": "2026-10-12"}, "citation": "Narasingha Prosad Sil. The Nectar of the Master''s Speech: An Anatomy of Sri Ramakrishna''s Kathāmṛta. The South Asianist 8: 81–117 (University of Edinburgh, open access). https://www.southasianist.ed.ac.uk/southasianist/article/download/5556/8906", "original_work_identity": {}, "publication_year": 2021, "publisher_or_institution": "The South Asianist 8: 81–117 (University of Edinburgh, open access)", "rights_or_access_note": "Open-access journal article; the author argues from a deliberately critical, partly psychological standpoint.", "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "The Nectar of the Master''s Speech: An Anatomy of Sri Ramakrishna''s Kathāmṛta", "url": "https://www.southasianist.ed.ac.uk/southasianist/article/download/5556/8906"}, "source_id": "8cd5175c-1fa9-4fc0-9d96-2edce7212fec"}], "unmatched_passage_links": []}'::jsonb,'draft','ai_candidate');
