insert into original_claims values ('7ea3394f-d5cb-4af2-85ed-bd473cf325a6','{"approval_origin": "ai_candidate", "certainty": "medium", "claim_id": "7ea3394f-d5cb-4af2-85ed-bd473cf325a6", "claim_kind": "traditional_account", "claim_relations": [], "claim_text": "The Order says Ramakrishna wrote no book and gave no public lectures, but spoke in simple language with parables and metaphors drawn from nature and daily life, which attracted Bengal''s cultural elite.", "current_status": "draft", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification"], "evidence_type": "traditional_narrative", "lens": {"field_id": "cce0c4eb-ef06-4204-b265-a1377afb0691", "field_label": "Works and speeches", "parameter_id": "c2bc8a47-86b1-4d7b-a18c-ff813dafedb5", "parameter_name": "Works and speeches"}, "parent_claim_id": null, "personality_id": "9ef04ec3-7bf1-4210-a951-1d6da7b2fc99", "personality_name": "Ramakrishna Paramahamsa", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The Gospel of Sri Ramakrishna Sri Ramakrishna did not write any book, nor did he deliver public lectures. Instead, he chose to speak in a simple language using parables and metaphors by way of illustration, drawn from the observation of nature and ordinary things of daily use. His conversations were charming and attracted the cultural elite of Bengal.", "link_id": "9ac82723-c436-4c4e-8f90-3c79ca4e0825", "page_or_section": "Belur Math: Sri Ramakrishna", "passages": [{"chunk_id": "8952c8b4-a32a-43a0-a80e-25e6b45c4eea", "confidence": null, "excerpt": "The Gospel of Sri Ramakrishna Sri Ramakrishna did not write any book, nor did he deliver public lectures. Instead, he chose to speak in a simple language using parables and metaphors by