insert into original_claims values ('627faf17-0b68-495b-8439-9e76d0c3ad58','{"approval_origin": "ai_candidate", "certainty": "high", "claim_id": "627faf17-0b68-495b-8439-9e76d0c3ad58", "claim_kind": "established_fact", "claim_relations": [], "claim_text": "Jhansi’s annexation belonged to wider Company expansion that also absorbed Satara and Nagpur, rather than an isolated quarrel with one queen.", "current_status": "draft", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "HISTORICAL_FACT", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification"], "evidence_type": "uncertain", "lens": {"field_id": "e2678179-acd4-40b8-ada5-325317546ea5", "field_label": "Historical setting", "parameter_id": "76a75ddb-e12c-4327-bb06-e953f7b23a76", "parameter_name": "Historical setting"}, "parent_claim_id": null, "personality_id": "26758dfe-ffe6-4c2c-b6c5-682353713af3", "personality_name": "Rani Lakshmibai of Jhansi", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The doctrine declared that if an Indian ruler died without a male heir his kingdom would “lapse”, that is, become a part of Company territory. One kingdom after another was annexed simply by applying this doctrine: Satara (1848), Sambalpur (1850), Udaipur (1852), Nagpur (1853) and Jhansi (1854). Finally, in 1856, the Company also took over Awadh.", "link_id": "fdf57d78-3124-4f84-bd28-b67dcf0128b3", "page_or_section": "One kingdom after another was annexed", "passages": [{"chunk_id": "6eea7bc2-58fd-4c27-bf5e-74545a25690d", "confidence": null, "excerpt": "The doctrine declared that if an Indian ruler died without a male heir his kingdom would “lapse”, that is, become a part of Company territory. One kingdom after another was annexed simply by applying this doctrine: Satara (1848), Sambalpur (1850), Udaipur (1852), Nagpur (1853) and Jhansi (1854). Finally, in 1856, the Company also took over Awadh.", "excerpt_truncated": false, "is_active": true, "link_method": null, "page_or_section": "Jhansi (1854)", "relationship": "supports", "section_title": "Rani Lakshmibai of Jhansi: From Trade to Territory", "source_id": "b7b4f6c8-7fbe-4426-8b1d-27782a188ec4", "textual_layer": "Modern educational synthesis of East India Company expansion"}], "relationship": "supports", "source": {"author": null, "authority_metadata": {"verified_at": "2026-10-11"}, "citation": "From Trade to Territory. NCERT, Our Pasts III, chapter 2. https://ncert.nic.in/textbook/pdf/hess202.pdf", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "NCERT, Our Pasts III, chapter 2", "rights_or_access_note": "Public original; short research excerpts. Scholarly abstract/summary access does not imply full chapter access.", "source_status": "approved", "source_type": "institutional", "storage_path": null, "title": "From Trade to Territory", "url": "https://ncert.nic.in/textbook/pdf/hess202.pdf"}, "source_id": "b7b4f6c8-7fbe-4426-8b1d-27782a188ec4"}], "unmatched_passage_links": []}'::jsonb,'draft','ai_candidate');
insert into original_claims values ('708d3c72-9514-40a2-9159-8dc2ce0fdbbc','{"approval_origin": "ai_candidate", "certainty": "high", "claim_id": "708d3c72-9514-40a2-9159-8dc2ce0fdbbc", "claim_kind": "established_fact", "claim_relations": [], "claim_text": "Rebels invoked the Mughal emperor Bahadur Shah Zafar as a source of legitimacy, while leaders such as Lakshmibai defended local authority within the wider uprising.", "current_status": "draft", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "HISTORICAL_FACT", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification"], "evidence_type": "uncertain", "lens": {"field_id": "e2678179-acd4-40b8-ada5-325317546ea5", "field_label": "Historical setting", "parameter_id": "76a75ddb-e12c-4327-bb06-e953f7b23a76", "parameter_name": "Historical setting"}, "parent_claim_id": null, "personality_id": "26758dfe-ffe6-4c2c-b6c5-682353713af3", "personality_name": "Rani Lakshmibai of Jhansi", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The emperor was not quite willing to challenge the mighty British power but the soldiers persisted. They forced their way into the palace and proclaimed Bahadur Shah Zafar as their leader. Firangis – Foreigners The term reflects an attitude of contempt.", "link_id": "f62de836-ba0d-406e-8013-8ae3bae033bc", "page_or_section": "proclaimed Bahadur Shah Zafar as their leader", "passages": [{"chunk_id": "1c674eb9-f122-4d5f-96d9-913751342314", "confidence": null, "excerpt": "The emperor was not quite willing to challenge the mighty British power but the soldiers persisted. They forced their way into the palace and proclaimed Bahadur Shah Zafar as their leader. Firangis – Foreigners The term reflects an attitude of contempt.", "excerpt_truncated": false, "is_active": true, "link_method": null, "p