insert into original_claims values ('8c4303bd-4fa0-4c79-bad5-79840a1bcc1e','{"approval_origin": "ai_candidate", "certainty": "high", "claim_id": "8c4303bd-4fa0-4c79-bad5-79840a1bcc1e", "claim_kind": "established_fact", "claim_relations": [], "claim_text": "The uprising at Meerut on 10 May 1857 spread toward Delhi and other centers, turning military discontent into a much wider challenge to Company authority.", "current_status": "draft", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "HISTORICAL_FACT", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification"], "evidence_type": "uncertain", "lens": {"field_id": "e2678179-acd4-40b8-ada5-325317546ea5", "field_label": "Historical setting", "parameter_id": "76a75ddb-e12c-4327-bb06-e953f7b23a76", "parameter_name": "Historical setting"}, "parent_claim_id": null, "personality_id": "26758dfe-ffe6-4c2c-b6c5-682353713af3", "personality_name": "Rani Lakshmibai of Jhansi", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The response of the other Indian soldiers in Meerut was quite extraordinary. On 10 May, the soldiers marched to the jail in Meerut and released the imprisoned sepoys. They attacked and killed British officers.", "link_id": "de4d9480-8a9f-4ebd-91e1-c26cb863f415", "page_or_section": "On 10 May, the soldiers marched", "passages": [{"chunk_id": "51a0e6ff-ccbe-4894-aaba-0d192e391d4b", "confidence": null, "excerpt": "The response of the other Indian soldiers in Meerut was quite extraordinary. On 10 May, the soldiers marched to the jail in Meerut and released the imprisoned sepoys. They attacked and killed British officers.", "excerpt_truncated": false, "is_active": true, "link_method": null, "page_or_section": "On 10 May, the soldiers marched", "relationship": "supports", "section_title": "Rani Lakshmiba