insert into original_claims values ('a3611065-b930-446e-8fc8-a2ef28fdab42','{"approval_origin": "ai_candidate", "certainty": "high", "claim_id": "a3611065-b930-446e-8fc8-a2ef28fdab42", "claim_kind": "established_fact", "claim_relations": [], "claim_text": "Dalhousie’s governorship, 1848–1856, brought an annexation policy that threatened dynastic succession in states such as Jhansi.", "current_status": "draft", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "HISTORICAL_FACT", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification"], "evidence_type": "uncertain", "lens": {"field_id": "e2678179-acd4-40b8-ada5-325317546ea5", "field_label": "Historical setting", "parameter_id": "76a75ddb-e12c-4327-bb06-e953f7b23a76", "parameter_name": "Historical setting"}, "parent_claim_id": null, "personality_id": "26758dfe-ffe6-4c2c-b6c5-682353713af3", "personality_name": "Rani Lakshmibai of Jhansi", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Ultimately, in 1849, Punjab was annexed. The Doctrine of Lapse The final wave of annexations occurred under Lord Dalhousie who was the Governor-General from 1848 to 1856. He devised a policy that came to be known as the Doctrine of Lapse.", "link_id": "6d2d8006-0ecb-41bc-8d4c-5ce597d3b7d1", "page_or_section": "Governor-General from 1848 to 1856", "passages": [{"chunk_id": "40779457-6204-431b-82df-fe5c372480ac", "confidence": null, "excerpt": "Ultimately, in 1849, Punjab was annexed. The Doctrine of Lapse The final wave of annexations occurred under Lord Dalhousie who was the Governor-General from 1848 to 1856. He devised a policy that came to be known as the Doctrine of Lapse.", "excerpt_truncated": false, "is_active": true, "link_method": null, "page_or_section": "Governor-General from 1848 to 1856", "relationship": "suppor