insert into original_claims values ('8787018f-bd39-4e41-ba16-55da7c58fc1e','{"approval_origin": "ai_candidate", "certainty": "high", "claim_id": "8787018f-bd39-4e41-ba16-55da7c58fc1e", "claim_kind": "established_fact", "claim_relations": [], "claim_text": "Savitribai died of plague on 10 March 1897 while involved in epidemic relief; the NCERT essay body and the university graphic biography agree on this date, unlike the NCERT cover’s inconsistent 19 March entry.", "current_status": "draft", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "HISTORICAL_FACT", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification"], "evidence_type": "uncertain", "lens": {"field_id": "3b1432d7-3b08-4308-989f-d9ef5e4e2bd8", "field_label": "Background and education", "parameter_id": "56859ce6-5fa6-4164-8e6c-7323efe334b2", "parameter_name": "Background and education"}, "parent_claim_id": null, "personality_id": "7dd19728-dbbf-4288-a3ec-ddb57806b863", "personality_name": "Savitribai Phule", "reviewer_decision": null, "sources": [{"evidence_excerpt": "As soon as she came to know that the son of Pandurang Babaji Gaekwad in the Mahar settlement outside the village of Mundhwa was afflicted with plague, she went there and rushed back to the hospital with the sick child on her back. She herself caught the disease in this process, and at 9 pm -- 26 of 54 -- 25 on 10 March 1897, she passed away. ëDeenbandhuí …", "link_id": "2a97df9f-1fbc-4cbd-9029-6d7bfffb32e5", "page_or_section": "printed p. 25; distinguish cover chronology", "passages": [{"chunk_id": "27ca5374-cdce-47e3-b57a-c7527d7c2862", "confidence": null, "excerpt": "As soon as she came to know that the son of Pandurang Babaji Gaekwad in the Mahar settlement outside the village of Mundhwa was afflicted with plague, she went there and rushe