insert into original_claims values ('ba565e39-49a9-4e56-bd5f-fd1b8ff761df','{"approval_origin": "ai_candidate", "certainty": "high", "claim_id": "ba565e39-49a9-4e56-bd5f-fd1b8ff761df", "claim_kind": "established_fact", "claim_relations": [], "claim_text": "Savitribai Phule was born on 3 January 1831 at Naigaon in the Satara region; her later educational work developed in nineteenth-century western India.", "current_status": "draft", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "HISTORICAL_FACT", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification"], "evidence_type": "uncertain", "lens": {"field_id": "3b1432d7-3b08-4308-989f-d9ef5e4e2bd8", "field_label": "Background and education", "parameter_id": "56859ce6-5fa6-4164-8e6c-7323efe334b2", "parameter_name": "Background and education"}, "parent_claim_id": null, "personality_id": "7dd19728-dbbf-4288-a3ec-ddb57806b863", "personality_name": "Savitribai Phule", "reviewer_decision": null, "sources": [{"evidence_excerpt": "But it is sad to note that not even, a single critical biography has ever been written on Savitribai yet. Savitribai was born on 3rd January 1831 at Naigaon situated on the Pune-Satara Road, about 5 kms. from Shirval and about 50 kms.", "link_id": "4f3066eb-a9a9-4022-af59-eb0034b99166", "page_or_section": "printed p. 9", "passages": [{"chunk_id": "d9f1959d-aacf-45bf-81f6-ed7893c192f3", "confidence": null, "excerpt": "But it is sad to note that not even, a single critical biography has ever been written on Savitribai yet. Savitribai was born on 3rd January 1831 at Naigaon situated on the Pune-Satara Road, about 5 kms. from Shirval and about 50 kms.", "excerpt_truncated": false, "is_active": true, "link_method": null, "page_or_section": "printed p. 9", "relationship": "supports", "section_title": "Savitribai Phule: Savitribai Phule First Memorial Lecture: Dnyanajyoti Savitribai Phule", "source_id": "66e60995-852c-477c-8aaa-4ce3fe4c6d13", "textual_layer": "Modern historical essay citing records, memoirs and adapted poems; distinguish each layer"}], "relationship": "supports", "source": {"author": "Hari Narake; T. Sundararaman", "authority_metadata": {"verified_at": "2026-10-11"}, "citation": "Hari Narake; T. Sundararaman. Savitribai Phule First Memorial Lecture: Dnyanajyoti Savitribai Phule. NCERT, first edition April 2009 (lecture December 2008). https://www.ncert.nic.in/pdf/publication/otherpublications/Memorial-Lectures-Series/FINAL%20COVER%20OF%20SAVIRTIBAI%20PHULE.pdf", "original_work_identity": {}, "publication_year": 2009, "publisher_or_institution": "NCERT, first edition April 2009 (lecture December 2008)", "rights_or_access_note": "Public original; short research excerpts. Scholarly abstract/summary access does not imply full chapter access.", "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Savitribai Phule First Memorial Lecture: Dnyanajyoti Savitribai Phule", "url": "https://www.ncert.nic.in/pdf/publication/otherpublications/Memorial-Lectures-Series/FINAL%20COVER%20OF%20SAVIRTIBAI%20PHULE.pdf"}, "source_id": "66e60995-852c-477c-8aaa-4ce3fe4c6d13"}], "unmatched_passage_links": []}'::jsonb,'draft','ai_candidate');
insert into original_claims values ('20c74010-67cb-4d20-90d4-331cc5ea8a83','{"approval_origin": "ai_candidate", "certainty": "medium", "claim_id": "20c74010-67cb-4d20-90d4-331cc5ea8a83", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "In the same 1877 letter, Savitribai reports negotiating with the Collector for detained volunteers and securing food aid, showing relief work involved dealing with colonial administrative power.", "current_status": "draft", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "260a2e11-aea5-4983-b374-0eb21a965733", "field_label": "Care, relief and social support", "parameter_id": "fe9e2a3f-8549-4be2-ba18-375ed9e1c599", "parameter_name": "Care, relief and social support"}, "parent_claim_id": null, "personality_id": "7dd19728-dbbf-4288-a3ec-ddb57806b863", "personality_name": "Savitribai Phule", "reviewer_decision": null, "sources": [{"evidence_excerpt": "I asked the Collector why the good volunteers had been framed with false charges and arrested without any rhyme or reason. I asked him to release them immediately. The Collector was quite decent and unbiased.", "link_id": "d3b1e850-b384-40c4-a740-57f71eb83808", "page_or_section": "20 April 1877 letter; own testimony", "passages": [{"chunk_id": "c2c48ccf-ba3f-4344-9a69-839a8a89e2b8", "confidence": null, "excerpt": "I asked the Collector why the good volunteers had been framed with false charges and arrested without any rhyme or reason. I asked him to release them immediately. The Collector was quite decent and unbiased.", "excerpt_truncated": false, "is_active": true, "link_method": null, "page_or_section": "20 April 1877 letter; own testimony", "relationship": "supports", "section_title": "Savitribai Phule: Savitribai Phule’s letters to Jyotiba: October 1856, August 1868, April 1877", "source_id": "becd7ef7-bbbb-4d57-bec8-71d78df33131", "textual_layer": "Attributed nineteenth-century letters in modern English translation; own testimony, not independently proven events"}], "relationship": "supports", "source": {"author": "Savitribai Phule; English translations introduced by Sunil Sardar", "authority_metadata": {"verified_at": "2026-10-11"}, "citation": "Savitribai Phule; English translations introduced by Sunil Sardar. Savitribai Phule’s letters to Jyotiba: October 1856, August 1868, April 1877. Sabrang / Scroll, reproducing M. G. Mali’s collected Marathi works via A Forgotten Liberator. https://scroll.in/article/801848/to-jyotiba-from-savitribai-phule-these-arent-love-letters-but-tell-you-what-love-is-all-about", "original_work_identity": {}, "publication_year": 2016, "publisher_or_institution": "Sabrang / Scroll, reproducing M. G. Mali’s collected Marathi works via A Forgotten Liberator", "rights_or_access_note": "Public original; short research excerpts. Scholarly abstract/summary access does not imply full chapter access.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Savitribai Phule’s letters to Jyotiba: October 1856, August 1868, April 1877", "url": "https://scroll.in/article/801848/to-jyotiba-from-savitribai-phule-these-arent-love-letters-but-tell-you-what-love-is-all-about"}, "source_id": "becd7ef7-bbbb-4d57-bec8-71d78df33131"}], "unmatched_passage_links": []}'::jsonb,'draft','ai_candidate');
insert into original_claims values ('80faee7b-f2c6-4927-8b9b-a21959c3ffb4','{"approval_origin": "ai_candidate", "certainty": "medium", "claim_id": "80faee7b-f2c6-4927-8b9b-a21959c3ffb4", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "O’Hanlon dates the Phules’ home for the prevention of infanticide to 1863; it provided pregnant high-caste widows a place to give birth safely and privately amid punitive social attitudes.", "current_status": "draft", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "SCHOLARLY_ATTRIBUTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "260a2e11-aea5-4983-b374-0eb21a965733", "field_label": "Care, relief and social support", "parameter_id": "fe9e2a3f-8549-4be2-ba18-375ed9e1c599", "parameter_name": "Care, relief and social support"}, "parent_claim_id": null, "personality_id": "7dd19728-dbbf-4288-a3ec-ddb57806b863", "personality_name": "Savitribai Phule", "reviewer_decision": null, "sources": [{"evidence_excerpt": "He took part in the first attempts in Pune to liberalise attitudes towards the remarriage of widows. In 1863 he made an even bolder move with the opening of a ‘Home for the prevention of infanticide’. Here, high caste widows who had become pregnant could come and give birth in secret and return quietly to their families, leaving the babies at the home.", "link_id": "d58ffe76-8f81-4e08-aabe-410f8a8fea45", "page_or_section": "public chapter 7 summary", "passages": [{"chunk_id": "8d98c74a-e286-4cac-bc66-11d83f363f6c", "confidence": null, "excerpt": "He took part in the first attempts in Pune to liberalise attitudes towards the remarriage of widows. In 1863 he made an even bolder move with the opening of a ‘Home for the prevention of infanticide’. Here, high caste widows who had become pregnant could come and give birth in secret and return quietly to their families, leaving the babies at the home.", "excerpt_truncated": false, "is_active": true, "link_method": null, "page_or_section": "public chapter 7 summary", "relationship": "supports", "section_title": "Savitribai Phule: Ritual status and political conflict in later nineteenth-century Maharashtra", "source_id": "33348d1b-f607-4e12-87cc-785a33300fb6", "textual_layer": "Academic history; publicly accessible chapter summary only, not unaccessed full chapter"}], "relationship": "supports", "source": {"author": "Rosalind O’Hanlon", "authority_metadata": {"verified_at": "2026-10-11"}, "citation": "Rosalind O’Hanlon. Ritual status and political conflict in later nineteenth-century Maharashtra. Cambridge University Press, Caste, Conflict and Ideology, chapter 7. https://www.cambridge.org/core/books/abs/caste-conflict-and-ideology/ritual-status-and-political-conflict-in-later-nineteenthcentury-maharashtra/5B894F9D29677C97AEC50840D3A31CA2", "original_work_identity": {}, "publication_year": 1985, "publisher_or_institution": "Cambridge University Press, Caste, Conflict and Ideology, chapter 7", "rights_or_access_note": "Public original; short research excerpts. Scholarly abstract/summary access does not imply full chapter access.", "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Ritual status and political conflict in later nineteenth-century Maharashtra", "url": "https://www.cambridge.org/core/books/abs/caste-conflict-and-ideology/ritual-status-and-political-conflict-in-later-nineteenthcentury-maharashtra/5B894F9D29677C97AEC50840D3A31CA2"}, "source_id": "33348d1b-f607-4e12-87cc-785a33300fb6"}], "unmatched_passage_links": []}'::jsonb,'draft','ai_candidate');
insert into original_claims values ('b24333d3-f62f-4c66-b017-136298ac3ff9','{"approval_origin": "ai_candidate", "certainty": "medium", "claim_id": "b24333d3-f62f-4c66-b017-136298ac3ff9", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "Narake’s account describes Savitribai assisting widows in childbirth and caring for their children, linking women’s safety to practical support rather than moral condemnation.", "current_status": "draft", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "SCHOLARLY_ATTRIBUTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "260a2e11-aea5-4983-b374-0eb21a965733", "field_label": "Care, relief and social support", "parameter_id": "fe9e2a3f-8549-4be2-ba18-375ed9e1c599", "parameter_name": "Care, relief and social support"}, "parent_claim_id": null, "personality_id": "7dd19728-dbbf-4288-a3ec-ddb57806b863", "personality_name": "Savitribai Phule", "reviewer_decision": null, "sources": [{"evidence_excerpt": "By 1884, 35 Brahman widows had come to them from different places. Savitribai would herself help in the delivery of their children and take care of them. In 1874, another exploited ëKashibaií came to them and they adopted her son.", "link_id": "4c0a2971-dfc3-4e6a-92f3-db1b630b78b4", "page_or_section": "printed p. 18", "passages": [{"chunk_id": "508482c3-b364-48c1-8f96-1a1b9e7c219b", "confidence": null, "excerpt": "By 1884, 35 Brahman widows had come to them from different places. Savitribai would herself help in the delivery of their children and take care of them. In 1874, another exploited ëKashibaií came to them and they adopted her son.", "excerpt_truncated": false, "is_active": true, "link_method": null, "page_or_section": "printed p. 18", "relationship": "supports", "section_title": "Savitribai Phule: Savitribai Phule First Memorial Lecture: Dnyanajyoti Savitribai Phule", "source_id": "66e60995-852c-477c-8aaa-4ce3fe4c6d13", "textual_layer": "Modern historical essay citing records, memoirs and adapted poems; distinguish each layer"}], "relationship": "supports", "source": {"author": "Hari Narake; T. Sundararaman", "authority_metadata": {"verified_at": "2026-10-11"}, "citation": "Hari Narake; T. Sundararaman. Savitribai Phule First Memorial Lecture: Dnyanajyoti Savitribai Phule. NCERT, first edition April 2009 (lecture December 2008). https://www.ncert.nic.in/pdf/publication/otherpublications/Memorial-Lectures-Series/FINAL%20COVER%20OF%20SAVIRTIBAI%20PHULE.pdf", "original_work_identity": {}, "publication_year": 2009, "publisher_or_institution": "NCERT, first edition April 2009 (lecture December 2008)", "rights_or_access_note": "Public original; short research excerpts. Scholarly abstract/summary access does not imply full chapter access.", "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Savitribai Phule First Memorial Lecture: Dnyanajyoti Savitribai Phule", "url": "https://www.ncert.nic.in/pdf/publication/otherpublications/Memorial-Lectures-Series/FINAL%20COVER%20OF%20SAVIRTIBAI%20PHULE.pdf"}, "source_id": "66e60995-852c-477c-8aaa-4ce3fe4c6d13"}], "unmatched_passage_links": []}'::jsonb,'draft','ai_candidate');
insert into original_claims values ('cb73ed9c-5359-4224-9d4e-d7143a080184','{"approval_origin": "ai_candidate", "certainty": "medium", "claim_id": "cb73ed9c-5359-4224-9d4e-d7143a080184", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "Her letter of 20 April 1877 describes Satyashodhak committees and relief squads distributing essential supplies during famine, evidence of organized social service as part of the reform movement.", "current_status": "draft", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "260a2e11-aea5-4983-b374-0eb21a965733", "field_label": "Care, relief and social support", "parameter_id": "fe9e2a3f-8549-4be2-ba18-375ed9e1c599", "parameter_name": "Care, relief and social support"}, "parent_claim_id": null, "personality_id": "7dd19728-dbbf-4288-a3ec-ddb57806b863", "personality_name": "Savitribai Phule", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Some are eating poisonous fruits, and drinking their own urine to quench their thirst. They cry for food and drink, and then they die.Our Satyashodhak volunteers have formed committees to provide food and other life-saving material to the people in need. They have formed relief squads.Brother Kondaj and his wife Umabai are taking good care of me.", "link_id": "c773844f-1382-434e-ba17-629ea600caca", "page_or_section": "20 April 1877 letter", "passages": [{"chunk_id": "0a2edc2f-1b70-475a-a260-d37adb8977c1", "confidence": null, "excerpt": "Some are eating poisonous fruits, and drinking their own urine to quench their thirst. They cry for food and drink, and then they die.Our Satyashodhak volunteers have formed committees to provide food and other life-saving material to the people in need. They have formed relief squads.Brother Kondaj and his wife Umabai are taking good care of me.", "excerpt_truncated": false, "is_active": true, "link_method": null, "page_or_section": "20 April 1877 letter", "relationship": "supports", "section_title": "Savitribai Phule: Savitribai Phule’s letters to Jyotiba: October 1856, August 1868, April 1877", "source_id": "becd7ef7-bbbb-4d57-bec8-71d78df33131", "textual_layer": "Attributed nineteenth-century letters in modern English translation; own testimony, not independently proven events"}], "relationship": "supports", "source": {"author": "Savitribai Phule; English translations introduced by Sunil Sardar", "authority_metadata": {"verified_at": "2026-10-11"}, "citation": "Savitribai Phule; English translations introduced by Sunil Sardar. Savitribai Phule’s letters to Jyotiba: October 1856, August 1868, April 1877. Sabrang / Scroll, reproducing M. G. Mali’s collected Marathi works via A Forgotten Liberator. https://scroll.in/article/801848/to-jyotiba-from-savitribai-phule-these-arent-love-letters-but-tell-you-what-love-is-all-about", "original_work_identity": {}, "publication_year": 2016, "publisher_or_institution": "Sabrang / Scroll, reproducing M. G. Mali’s collected Marathi works via A Forgotten Liberator", "rights_or_access_note": "Public original; short research excerpts. Scholarly abstract/summary access does not imply full chapter access.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Savitribai Phule’s letters to Jyotiba: October 1856, August 1868, April 1877", "url": "https://scroll.in/article/801848/to-jyotiba-from-savitribai-phule-these-arent-love-letters-but-tell-you-what-love-is-all-about"}, "source_id": "becd7ef7-bbbb-4d57-bec8-71d78df33131"}], "unmatched_passage_links": []}'::jsonb,'draft','ai_candidate');
insert into original_claims values ('d0445e5b-2692-486f-ba48-9206c4d11420','{"approval_origin": "ai_candidate", "certainty": "medium", "claim_id": "d0445e5b-2692-486f-ba48-9206c4d11420", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "During Pune’s plague outbreak in 1897, Savitribai worked with her physician son Yeshwant to provide treatment and bring patients to a hospital, according to Narake.", "current_status": "draft", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "SCHOLARLY_ATTRIBUTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "260a2e11-aea5-4983-b374-0eb21a965733", "field_label": "Care, relief and social support", "parameter_id": "fe9e2a3f-8549-4be2-ba18-375ed9e1c599", "parameter_name": "Care, relief and social support"}, "parent_claim_id": null, "personality_id": "7dd19728-dbbf-4288-a3ec-ddb57806b863", "personality_name": "Savitribai Phule", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The government took up the task of controlling the epidemic under the leadership of an officer called Rand. Savitribai asked Yeshwant to take leave and come back and made him set up a hospital on the fields of the Sasane family. She would herself pick up sick people and bring them to the hospital and treat them.", "link_id": "91985968-549b-4494-8b0e-cb7e5cf0b58d", "page_or_section": "printed p. 24", "passages": [{"chunk_id": "652d5965-3f4c-4fce-8626-d243ae205a2b", "confidence": null, "excerpt": "The government took up the task of controlling the epidemic under the leadership of an officer called Rand. Savitribai asked Yeshwant to take leave and come back and made him set up a hospital on the fields of the Sasane family. She would herself pick up sick people and bring them to the hospital and treat them.", "excerpt_truncated": false, "is_active": true, "link_method": null, "page_or_section": "printed p. 24", "relationship": "supports", "section_title": "Savitribai Phule: Savitribai Phule First Memorial Lecture: Dnyanajyoti Savitribai Phule", "source_id": "66e60995-852c-477c-8aaa-4ce3fe4c6d13", "textual_layer": "Modern historical essay citing records, memoirs and adapted poems; distinguish each layer"}], "relationship": "supports", "source": {"author": "Hari Narake; T. Sundararaman", "authority_metadata": {"verified_at": "2026-10-11"}, "citation": "Hari Narake; T. Sundararaman. Savitribai Phule First Memorial Lecture: Dnyanajyoti Savitribai Phule. NCERT, first edition April 2009 (lecture December 2008). https://www.ncert.nic.in/pdf/publication/otherpublications/Memorial-Lectures-Series/FINAL%20COVER%20OF%20SAVIRTIBAI%20PHULE.pdf", "original_work_identity": {}, "publication_year": 2009, "publisher_or_institution": "NCERT, first edition April 2009 (lecture December 2008)", "rights_or_access_note": "Public original; short research excerpts. Scholarly abstract/summary access does not imply full chapter access.", "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Savitribai Phule First Memorial Lecture: Dnyanajyoti Savitribai Phule", "url": "https://www.ncert.nic.in/pdf/publication/otherpublications/Memorial-Lectures-Series/FINAL%20COVER%20OF%20SAVIRTIBAI%20PHULE.pdf"}, "source_id": "66e60995-852c-477c-8aaa-4ce3fe4c6d13"}], "unmatched_passage_links": []}'::jsonb,'draft','ai_candidate');
insert into original_claims values ('22c82714-65c4-4950-8def-753d64902327','{"approval_origin": "ai_candidate", "certainty": "medium", "claim_id": "22c82714-65c4-4950-8def-753d64902327", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "In her October 1856 letter, Savitribai describes teaching girls, women, Mangs and Mahars with Jyotirao, explicitly connecting gender inclusion to the education of caste-excluded communities.", "current_status": "draft", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "3d92840a-9a05-4f27-942e-849f6de37095", "field_label": "Caste, gender and social equality", "parameter_id": "a4dd9dcc-8b91-4f8c-8ac0-e9361769ed8c", "parameter_name": "Caste, gender and social equality"}, "parent_claim_id": null, "personality_id": "7dd19728-dbbf-4288-a3ec-ddb57806b863", "personality_name": "Savitribai Phule", "reviewer_decision": null, "sources": [{"evidence_excerpt": "I also teach them for the same reason. What is wrong with that? Yes, we both teach girls, women, Mangs and Mahars. The Brahmans are upset because they believe this will create problems for them.", "link_id": "1ff618e7-1527-4da7-905e-18d79180364e", "page_or_section": "October 1856 letter; modern translation", "passages": [{"chunk_id": "feae4143-11b4-4f9a-ab2c-c255ca977f10", "confidence": null, "excerpt": "I also teach them for the same reason. What is wrong with that? Yes, we both teach girls, women, Mangs and Mahars. The Brahmans are upset because they believe this will create problems for them.", "excerpt_truncated": false, "is_active": true, "link_method": null, "page_or_section": "October 1856 letter; modern tran