insert into original_claims values ('4f0b7d9b-47d5-4e3f-b370-27f9b6c56017','{"approval_origin": "ai_candidate", "certainty": "high", "claim_id": "4f0b7d9b-47d5-4e3f-b370-27f9b6c56017", "claim_kind": "established_fact", "claim_relations": [], "claim_text": "Savitribai faced opposition for teaching girls and disadvantaged caste groups; this resistance reveals that her schools challenged who was entitled to knowledge and a public role.", "current_status": "draft", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "HISTORICAL_FACT", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification"], "evidence_type": "uncertain", "lens": {"field_id": "3d92840a-9a05-4f27-942e-849f6de37095", "field_label": "Caste, gender and social equality", "parameter_id": "a4dd9dcc-8b91-4f8c-8ac0-e9361769ed8c", "parameter_name": "Caste, gender and social equality"}, "parent_claim_id": null, "personality_id": "7dd19728-dbbf-4288-a3ec-ddb57806b863", "personality_name": "Savitribai Phule", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Jotirao prepared his wife Savitribai to teach in the girls'' school, with a view to educating the women first, in order to bring in the value of equality at home. Savitribai had to face bitter opposition from the orthodox people in the society for teaching girls and people from the underprivileged groups in the school. Despite this bitter opposition, Jotirao …", "link_id": "28e05be4-8484-4a71-8c01-2961922ee397", "page_or_section": "university account of educational work", "passages": [{"chunk_id": "ff20d611-5b70-4a33-8c88-c7ec7b2abe52", "confidence": null, "excerpt": "Jotirao prepared his wife Savitribai to teach in the girls'' school, with a view to educating the women first, in order to bring in the value of equality at home. Savitribai had to face bitter opposition from the orthodox people in the society for teaching girls and people from the underprivileged groups in the school. Despite this bitter opposition, Jotirao …", "excerpt_truncated": true, "is_active": true, "link_method": null, "page_or_section": "university account of educational work", "relationship": "supports", "section_title": "Savitribai Phule: Life and Work of Mahatma Jotirao Phule", "source_id": "03dac697-d0c6-4fae-b627-f49611844f82", "textual_layer": "Retrospective university history of Jyotirao and shared institutions; do not transfer all his views to Savitribai"}], "relationship": "supports", "source": {"author": null, "authority_metadata": {"verified_at": "2026-10-11"}, "citation": "Life and Work of Mahatma Jotirao Phule. Mahatma Phule Chair, Savitribai Phule Pune University. https://www.unipune.ac.in/chairs/mahatma_phule_chair/mphule_webfiles/Life_%20%26%20_Work.htm", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Mahatma Phule Chair, Savitribai Phule Pune University", "rights_or_access_note": "Public original; short research excerpts. Scholarly abstract/summary access does not imply full chapter access.", "source_status": "approved", "source_type": "institutional", "storage_path": null, "title": "Life and Work of Mahatma Jotirao Phule", "url": "https://www.unipune.ac.in/chairs/mahatma_phule_chair/mphule_webfiles/Life_%20%26%20_Work.htm"}, "source_id": "03dac697-d0c6-4fae-b627-f49611844f82"}], "unmatched_passage_links": []}'::jsonb,'draft','ai_candidate');
insert into original_claims values ('67488e84-8936-4b12-8626-03907d611ae2','{"approval_origin": "ai_candidate", "certainty": "medium", "claim_id": "67488e84-8936-4b12-8626-03907d611ae2", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "Satyashodhak marriage pledges included education and equal rights for women, according to Narake’s history, connecting gender equality with reform of marriage practice.", "current_status": "draft", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "3d92840a-9a05-4f27-942e-849f6de37095", "field_label": "Caste, gender and social equality", "parameter_id": "a4dd9dcc-8b91-4f8c-8ac0-e9361769ed8c", "parameter_name": "Caste, gender and social equality"}, "parent_claim_id": null, "personality_id": "7dd19728-dbbf-4288-a3ec-ddb57806b863", "personality_name": "Savitribai Phule", "reviewer_decision": null, "sources": [{"evidence_excerpt": "This was the first inter-caste marriage in modern India. The Satyashodhak marriage required the bridegroom to take an oath of giving education and equal rights to women. The ëmangalashtakeí (the Mantras chanted at the time of the wedding) were to be sung by the bride and the bridegroom themselves, and these were in the form of pledges made by the bride and …", "link_id": "676908b8-83d6-4311-bbce-927c69b9e55d", "page_or_section": "printed p. 21", "passages": [{"chunk_id": "7e5dceb5-f43b-485d-bbf6-506d125214b4", "confidence": null, "excerpt": "This was the first inter-caste marriage in modern India. The Satyashodhak marriage required the bridegroom to take an oath of giving education and equal rights to women. The ëmangalashtakeí (the Mantras chanted at the time of the wedding) were to be sung by the bride and the bridegroom themselves, and these were in the form of pledges made by the bride and …", "excerpt_truncated": true, "is_active": true, "link_method": null, "page_or_section": "printed p. 21", "relationship": "supports", "section_title": "Savitribai Phule: Savitribai Phule First Memorial Lecture: Dnyanajyoti Savitribai Phule", "source_id": "66e60995-852c-477c-8aaa-4ce3fe4c6d13", "textual_layer": "Modern historical essay citing records, memoirs and adapted poems; distinguish each layer"}], "relationship": "supports", "source": {"author": "Hari Narake; T. Sundararaman", "authority_metadata": {"verified_at": "2026-10-11"}, "citation": "Hari Narake; T. Sundararaman. Savitribai Phule First Memorial Lecture: Dnyanajyoti Savitribai Phule. NCERT, first edition April 2009 (lecture December 2008). https://www.ncert.nic.in/pdf/publication/otherpublications/Memorial-Lectures-Series/FINAL%20COVER%20OF%20SAVIRTIBAI%20PHULE.pdf", "original_work_identity": {}, "publication_year": 2009, "publisher_or_institution": "NCERT, first edition April 2009 (lecture December 2008)", "rights_or_access_note": "Public original; short research excerpts. Scholarly abstract/summary access does not imply full chapter access.", "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Savitribai Phule First Memorial Lecture: Dnyanajyoti Savitribai Phule", "url": "https://www.ncert.nic.in/pdf/publication/otherpublications/Memorial-Lectures-Series/FINAL%20COVER%20OF%20SAVIRTIBAI%20PHULE.pdf"}, "source_id": "66e60995-852c-477c-8aaa-4ce3fe4c6d13"}], "unmatched_passage_links": []}'::jsonb,'draft','ai_candidate');
insert into original_claims values ('77214522-5a34-413a-bde8-8c271e944837','{"approval_origin": "ai_candidate", "certainty": "medium", "claim_id": "77214522-5a34-413a-bde8-8c271e944837", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "In her letter of 29 August 1868, Savitribai reports intervening against threatened violence toward a Brahman man and a Mahar woman and invoking British law to protect them; this is her attributed account of defending an inter-caste relationship.", "current_status": "draft", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "3d92840a-9a05-4f27-942e-849f6de37095", "field_label": "Caste, gender and social equality", "parameter_id": "a4dd9dcc-8b91-4f8c-8ac0-e9361769ed8c", "parameter_name": "Caste, gender and social equality"}, "parent_claim_id": null, "personality_id": "7dd19728-dbbf-4288-a3ec-ddb57806b863", "personality_name": "Savitribai Phule", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The enraged people caught them, and paraded them through the village, threatening to bump them off.I came to know about their murderous plan. I rushed to the spot and scared them away, pointing out the grave consequences of killing the lovers under the British law. They changed their mind after listening to me.Sadubhau angrily said that the wily Brahman boy …", "link_id": "dbce8f02-a9e2-4380-8d8a-6094b0d0c360", "page_or_section": "29 August 1868 letter", "passages": [{"chunk_id": "fe9bf64c-761d-4c8d-950d-363205e1f901", "confidence": null, "excerpt": "The enraged people caught them, and paraded them through the village, threatening to bump them off.I came to know about their murderous plan. I rushed to the spot and scared them away, pointing out the grave consequences of killing the lovers under the British law. They changed their mind after listening to me.Sadubhau angrily said that the wily Brahman boy …", "excerpt_truncated": true, "is_active": true, "link_method": null, "page_or_section": "29 August 1868 letter", "relationship": "supports", "section_title": "Savitribai Phule: Savitribai Phule’s letters to Jyotiba: October 1856, August 1868, April 1877", "source_id": "becd7ef7-bbbb-4d57-bec8-71d78df33131", "textual_layer": "Attributed nineteenth-century letters in modern English translation; own testimony, not independently proven events"}], "relationship": "supports", "source": {"author": "Savitribai Phule; English translations introduced by Sunil Sardar", "authority_metadata": {"verified_at": "2026-10-11"}, "citation": "Savitribai Phule; English translations introduced by Sunil Sardar. Savitribai Phule’s letters to Jyotiba: October 1856, August 1868, April 1877. Sabrang / Scroll, reproducing M. G. Mali’s collected Marathi works via A Forgotten Liberator. https://scroll.in/article/801848/to-jyotiba-from-savitribai-phule-these-arent-love-letters-but-tell-you-what-love-is-all-about", "original_work_identity": {}, "publication_year": 2016, "publisher_or_institution": "Sabrang / Scroll, reproducing M. G. Mali’s collected Marathi works via A Forgotten Liberator", "rights_or_access_note": "Public original; short research excerpts. Scholarly abstract/summary access does not imply full chapter access.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Savitribai Phule’s letters to Jyotiba: October 1856, August 1868, April 1877", "url": "https://scroll.in/article/801848/to-jyotiba-from-savitribai-phule-these-arent-love-letters-but-tell-you-what-love-is-all-about"}, "source_id": "becd7ef7-bbbb-4d57-bec8-71d78df33131"}], "unmatched_passage_links": []}'::jsonb,'draft','ai_candidate');
insert into original_claims values ('a4cabecf-a0fc-4001-ab58-d44c11b9077d','{"approval_origin": "ai_candidate", "certainty": "high", "claim_id": "a4cabecf-a0fc-4001-ab58-d44c11b9077d", "claim_kind": "established_fact", "claim_relations": [], "claim_text": "The Satyashodhak Samaj promoted low-cost marriages without priestly mediation or dowry, contesting social authority through practical changes in family institutions.", "current_status": "draft", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "HISTORICAL_FACT", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification"], "evidence_type": "uncertain", "lens": {"field_id": "3d92840a-9a05-4f27-942e-849f6de37095", "field_label": "Caste, gender and social equality", "parameter_id": "a4dd9dcc-8b91-4f8c-8ac0-e9361769ed8c", "parameter_name": "Caste, gender and social equality"}, "parent_claim_id": null, "personality_id": "7dd19728-dbbf-4288-a3ec-ddb57806b863", "personality_name": "Savitribai Phule", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The Satyashodhak Samaj (The Truth-Seekerís Society) was established on 24 September 1873, and Savitribai was an extremely dedicated and passionate activist of the Samaj. The Samaj undertook the programme of arranging marriages without a priest, without dowry and at minimum costs. The first such marriage was arranged on 25 December 1873.", "link_id": "fce67c15-d191-49d8-99fd-cfe7cb802bd9", "page_or_section": "printed p. 20", "passages": [{"chunk_id": "3f96a9b5-1553-49b9-b570-21dea0a20e96", "confidence": null, "excerpt": "The Satyashodhak Samaj (The Truth-Seekerís Society) was established on 24 September 1873, and Savitribai was an extremely dedicated and passionate activist of the Samaj. The Samaj undertook the programme of arranging marriages without a priest, withou