insert into original_claims values ('a6d8f988-6244-46e7-8987-81d3b280dd85','{"approval_origin": "ai_candidate", "certainty": "medium", "claim_id": "a6d8f988-6244-46e7-8987-81d3b280dd85", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "Savitribai’s 1856 letter challenges her brother’s treatment of Mahars and Mangs as untouchable by asserting their common humanity; education and opposition to caste exclusion were inseparable in her argument.", "current_status": "draft", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "3d92840a-9a05-4f27-942e-849f6de37095", "field_label": "Caste, gender and social equality", "parameter_id": "a4dd9dcc-8b91-4f8c-8ac0-e9361769ed8c", "parameter_name": "Caste, gender and social equality"}, "parent_claim_id": null, "personality_id": "7dd19728-dbbf-4288-a3ec-ddb57806b863", "personality_name": "Savitribai Phule", "reviewer_decision": null, "sources": [{"evidence_excerpt": "You catch poisonous snakes on the day of the snake-festival and feed them milk. But you consider Mahars and Mangs, who are as human as you and I, untouchables. Can you give me any reason for this? When the Brahmans perform their religious duties in their holy clothes, they consider you also impure and untouchable, they are afraid that your touch will …", "link_id": "65acb234-073d-437e-9806-06766e6a33af", "page_or_section": "October 1856 letter", "passages": [{"chunk_id": "6b9c237f-37fc-4ecb-97cc-4b5f727f5630", "confidence": null, "excerpt": "You catch poisonous snakes on the day of the snake-festival and feed them milk. But you consider Mahars and Mangs, who are as human as you and I, untouchables.