insert into original_claims values ('868f69cb-5892-4a43-bdf7-a77627dd123f','{"approval_origin": "ai_candidate", "certainty": "medium", "claim_id": "868f69cb-5892-4a43-bdf7-a77627dd123f", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "Narake describes the Phules’ educational programme as vocational and trade-oriented, intended to support self-reliance and independent thought; this was a shared institutional programme, not a claim that Savitribai alone designed every method.", "current_status": "draft", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "SCHOLARLY_ATTRIBUTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "bf438e7e-3605-43a1-9f95-77060b9b7306", "field_label": "Schools and educational practice", "parameter_id": "8b3770f5-d29c-466e-9658-257de27c7a5a", "parameter_name": "Schools and educational practice"}, "parent_claim_id": null, "personality_id": "7dd19728-dbbf-4288-a3ec-ddb57806b863", "personality_name": "Savitribai Phule", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The orthodox, however, expressed displeasure that a Shudra like Jotirao should be felicitated by giving him a ëmahavastraí (ceremonial shawl). Jotirao and Savitribai focused on providing girls and boys with education that was vocational and trade- oriented in nature, to make their students self-reliant and capable of independent thought. In the 1852 report, …", "link_id": "6bcc2bf1-fd0d-440e-abf9-71a9a0dd21c0", "page_or_section": "printed p. 15", "passages": [{"chunk_id": "80d57823-e316-41be-84f8-1230326ad999", "confidence": null, "excerpt": "The orthodox, however, expressed displeasure that a Shudra like Jotirao should be felicitated by giving him a ëmahavastra