insert into original_claims values ('ff8c6a25-6dc2-4162-89f6-74cf137974fb','{"approval_origin": "ai_candidate", "certainty": "medium", "claim_id": "ff8c6a25-6dc2-4162-89f6-74cf137974fb", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "Hardy judged that some of Ramanujan''s early prime-number results were false, illustrating the limits of intuition without rigorous proof.", "current_status": "draft", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "SCHOLARLY_ATTRIBUTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "9bb89c2d-6f52-4924-b75d-687aa6c3170d", "field_label": "Contested aspects and limits", "parameter_id": "e5917260-0dfa-4d63-a162-c7eb5eb5040a", "parameter_name": "Contested aspects and limits"}, "parent_claim_id": null, "personality_id": "1f893928-3c09-424a-b513-c62893e57cb8", "personality_name": "Srinivasa Ramanujan", "reviewer_decision": null, "sources": [{"evidence_excerpt": "There are regions of mathematics in which the precepts of modern rigour may be disregarded with comparative safety, but the Analytic Theory of Numbers is not one of them, and Ramanujan’s Indian work on primes, and on all the allied problems of the theory, was definitely wrong. That his proofs should have been invalid was only to be expected.", "link_id": "c65d5ac2-f756-44c9-84dc-bf9b975ab48e", "page_or_section": "Hardy obituary, pp. xvi–xvii", "passages": [{"chunk_id": "d22402a7-2ccf-4134-95fb-580b170e8b1f", "confidence": null, "excerpt": "There are regions of mathematics in which the precepts of modern rigour may be disregarded with comparative safety, but the Analytic Theory of Numbers is not one of them, and Ramanujan’s Indian work on primes, and on all the allied pr