insert into original_claims values ('a706a217-cc46-498a-a955-f855469c442c','{"approval_origin": "ai_candidate", "certainty": "medium", "claim_id": "a706a217-cc46-498a-a955-f855469c442c", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "Bollobás argues that Hardy tried to give Ramanujan the mathematical foundations needed to develop his exceptional talent.", "current_status": "draft", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "SCHOLARLY_ATTRIBUTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "67c1cd72-8f17-44b0-94c5-52ef3bd1d21b", "field_label": "Mentorship and education", "parameter_id": "8b5583b5-ba98-4e9e-994f-b0c5c9346b9d", "parameter_name": "Mentorship and education"}, "parent_claim_id": null, "personality_id": "1f893928-3c09-424a-b513-c62893e57cb8", "personality_name": "Srinivasa Ramanujan", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Hardy knew that if Ramanujan was to fulfil his potential, he had to have a solid foundation in mathematics, at least as much as the best Cambridge graduates. It was for Ramanujan’s good that Hardy invited him to Cambridge, then, and he was taken aback when, due to caste prejudices, Ramanujan did not jump at the chance.", "link_id": "69728187-c687-4e97-84af-636cd7e48418", "page_or_section": "Mathematical training", "passages": [{"chunk_id": "df8ef198-e477-4a6f-a4af-eb71d78c2027", "confidence": null, "excerpt": "Hardy knew that if Ramanujan was to fulfil his potential, he had to have a solid foundation in mathematics, at least as much as the best Cambridge graduates. It was for Ramanujan’s good that Hardy invited him to Cambridge, then, and he was taken aback when, due to caste prejudices, Ramanujan did not jump at the chance.", "excerpt_truncated": false, "is_active": true, "link_method": null, "page_or_section": "Mathematical training", "relationship": "supports", "section_title": "Mathematical training", "source_id": "57dabed4-de88-4874-aead-d26876c87cba", "textual_layer": "Mathematician''s historical interpretation"}], "relationship": "supports", "source": {"author": "Béla Bollobás", "authority_metadata": {"verified_at": "2026-10-09T14:28:13.168Z"}, "citation": "Béla Bollobás. The man who taught infinity: Hardy and Ramanujan. University of Cambridge. https://www.cam.ac.uk/research/news/opinion-the-man-who-taught-infinity-how-gh-hardy-tamed-srinivasa-ramanujans-genius", "original_work_identity": {}, "publication_year": 2016, "publisher_or_institution": "University of Cambridge", "rights_or_access_note": "Public source; short research excerpts only.", "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "The man who taught infinity: Hardy and Ramanujan", "url": "https://www.cam.ac.uk/research/news/opinion-the-man-who-taught-infinity-how-gh-hardy-tamed-srinivasa-ramanujans-genius"}, "source_id": "57dabed4-de88-4874-aead-d26876c87cba"}], "unmatched_passage_links": []}'::jsonb,'draft','ai_candidate');
