insert into original_claims values ('225ffc81-80a8-4d29-a9f1-31ece13e6baf','{"approval_origin": "ai_candidate", "certainty": "medium", "claim_id": "225ffc81-80a8-4d29-a9f1-31ece13e6baf", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "The World Bank evaluation argues that producer control required autonomy from government and political interference; state appointments at higher cooperative tiers sometimes undermined that ideal.", "current_status": "draft", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "SCHOLARLY_INTERPRETATION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "8cc6a334-cc43-4e90-aeec-2061c5bb5e32", "field_label": "Evidence and limitations", "parameter_id": "337a665b-f24a-43eb-a754-f79b4982feaa", "parameter_name": "Evidence and limitations"}, "parent_claim_id": null, "personality_id": "9a66a004-b1ce-429d-946e-715ae059f730", "personality_name": "Verghese Kurien", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The Anand principles call for a three-tier system of cooperatives owned and controlled by farmers, with professional management. They are to be free of government or political interference. Actual compliance has been mixed, with many states still appointing civil servants as managing directors of the federations or even milk producers unions.", "link_id": "f342e7fc-b873-4253-aa94-ed28c7b073e1", "page_or_section": "Executive summary", "passages": [{"chunk_id": "dddb17c4-1811-4386-a341-56c58d484b13", "confidence": null, "excerpt": "The Anand principles call for a three-tier system of cooperatives owned and controlled by farmers, with professional management. They are to be free of government or political interference. Actual compliance has been mixed, with many states still appointing civil servants as managing directors of the federations or even milk producers unions.", "excerpt_truncated": false, "is_active": true, "link_method": null, "page_or_section": "Executive summary", "relationship": "supports", "section_title": "Verghese Kurien: India: The Dairy Revolution", "source_id": "a419d399-18d8-497a-a050-659b7658d7eb", "textual_layer": "Independent project evaluation; short English-column transcriptions checked against the original three-column PDF"}], "relationship": "supports", "source": {"author": null, "authority_metadata": {"verified_at": "2026-10-12"}, "citation": "India: The Dairy Revolution. World Bank Operations Evaluation Department. https://documents1.worldbank.org/curated/en/967841468771597123/pdf/multi-page.pdf", "original_work_identity": {}, "publication_year": 1998, "publisher_or_institution": "World Bank Operations Evaluation Department", "rights_or_access_note": "Public original; short research excerpts.", "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "India: The Dairy Revolution", "url": "https://documents1.worldbank.org/curated/en/967841468771597123/pdf/multi-page.pdf"}, "source_id": "a419d399-18d8-497a-a050-659b7658d7eb"}], "unmatched_passage_links": []}'::jsonb,'draft','ai_candidate');
insert into original_claims values ('4b36a24a-2c31-4417-a546-05617b0a1fb0','{"approval_origin": "human_manual", "certainty": "medium", "claim_id": "4b36a24a-2c31-4417-a546-05617b0a1fb0", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "Claims about the White Revolution should credit farmers, Tribhuvandas Patel, and H. M. Dalaya, while independent evaluation cautions against attributing all milk-production growth or poverty reduction to Operation Flood alone.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "SYNTHESIS_ACROSS_SOURCES", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "8cc6a334-cc43-4e90-aeec-2061c5bb5e32", "field_label": "Evidence and limitations", "parameter_id": "337a665b-f24a-43eb-a754-f79b4982feaa", "parameter_name": "Evidence and limitations"}, "parent_claim_id": null, "personality_id": "9a66a004-b1ce-429d-946e-715ae059f730", "personality_name": "Verghese Kurien", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Before that, Polson was supplying milk products to British Army and the Bombay Milk Scheme. The farmers involved were exploited in financial terms by the middleman. To provide better remuneration to farmers and remove the middleman, Tribhuvandas Patel and Sardar Patel helped create the Kaira District Cooperative Milk Producer''s Union (KDCMPU).", "link_id": "1345547f-7ffd-47df-b5e1-89f3bc1f9aca", "page_or_section": "Cooperative retrospective", "passages": [{"chunk_id": "e17c9968-81e2-4223-924d-d80d0de52785", "confidence": 0.95, "excerpt": "Before that, Polson was supplying milk products to British Army and the Bombay Milk Scheme. The farmers involved were exploited in financial terms by the middleman. To provide better remuneration to farmers and remove the middleman, Tribhuvandas Patel and Sardar Patel helped create the Kaira District Cooperative Milk Producer''s Union (KDCMPU).", "excerpt_truncated": false, "is_active": true, "link_method": "manual", "page_or_section": "Cooperative retrospective", "relationship": "supports", "section_title": "Verghese Kurien: Remembering Father of White Revolution on this World Milk Day", "source_id": "4c4e8e46-97c5-4ef6-aab4-8e96fe8a70fc", "textual_layer": "Later cooperative institutional memory; precise historical recollections and praise require attribution"}], "relationship": "supports", "source": {"author": null, "authority_metadata": {"verified_at": "2026-10-12"}, "citation": "Remembering Father of White Revolution on this World Milk Day. Gujarat Cooperative Milk Marketing Federation. https://old.amul.com/files/pdf/Worldmilkday_storyinEnglish_31stMay2021.pdf", "original_work_identity": {}, "publication_year": 2021, "publisher_or_institution": "Gujarat Cooperative Milk Marketing Federation", "rights_or_access_note": "Short original-page transcript excerpts checked on 2026-10-12; direct fetch intermittent.", "source_status": "approved", "source_type": "institutional", "storage_path": null, "title": "Remembering Father of White Revolution on this World Milk Day", "url": "https://old.amul.com/files/pdf/Worldmilkday_storyinEnglish_31stMay2021.pdf"}, "source_id": "4c4e8e46-97c5-4ef6-aab4-8e96fe8a70fc"}, {"evidence_excerpt": "Operation Flood provided the example of large-scale modern milk processing fed by a well-organized milkshed procuring milk from a large number of producers in very small amounts (1 and 2 liters). The actual volume of milk handled by Operation Flood remains a small fraction of the increased supply. It is thus not possible to attribute increased production …", "link_id": "19959533-a21f-404c-bae4-343440962a58", "page_or_section": "Executive summary", "passages": [{"chunk_id": "b2da94b1-f29b-4f52-ba52-b88d59c666a3", "confidence": 0.95, "excerpt": "Operation Flood provided the example of large-scale modern milk processing fed by a well-organized milkshed procuring milk from a large number of producers in very small amounts (1 and 2 liters). The actual volume of milk handled by Operation Flood remains a small fraction of the increased supply. It is thus not possible to attribute increased production …", "excerpt_truncated": true, "is_active": true, "link_method": "manual", "page_or_section": "Executive summary", "relationship": "supports", "section_title": "Verghese Kurien: India: The Dairy Revolution", "source_id": "a419d399-18d8-497a-a050-659b7658d7eb", "textual_layer": "Independent project evaluation; short English-column transcriptions checked against the original three-column PDF"}, {"chunk_id": "e165e449-d2be-4562-aaae-760507d2dbb1", "confidence": 0.95, "excerpt": "For those landless people who own or have been able to purchase a milch animal, it has been a boon. Of course, those who are both cowless and landless have only been slightly affected by some of the social programs supported by the village Dairy Cooperative Societies.", "excerpt_truncated": false, "is_active": true, "link_method": "manual", "page_or_section": "Executive summary", "relationship": "supports", "section_title": "Verghese Kurien: India: The Dairy Revolution", "source_id": "a419d399-18d8-497a-a050-659b7658d7eb", "textual_layer": "Independent project evaluation; short English-column transcriptions checked against the original three-column PDF"}], "relationship": "supports", "source": {"author": null, "authority_metadata": {"verified_at": "2026-10-12"}, "citation": "India: The Dairy Revolution. World Bank Operations Evaluation Department. https://documents1.worldbank.org/curated/en/967841468771597123/pdf/multi-page.pdf", "original_work_identity": {}, "publication_year": 1998, "publisher_or_institution": "World Bank Operations Evaluation Department", "rights_or_access_note": "Public ori