insert into original_claims values ('50c5e872-c9e3-459a-bd7b-be6597f2956b','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "50c5e872-c9e3-459a-bd7b-be6597f2956b", "claim_kind": "contemporary_relevance", "claim_relations": [], "claim_text": "The move from confidence in kshatriya force to pursuit of brahma-tejas can be used as a literary case study in changing one''s definition of power after failure, provided it is presented as interpretation of Bala Kanda rather than a universal historical lesson.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "SYNTHETIC_INTERPRETATION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Recorded source access issue"], "evidence_type": "modern_spiritual_interpretation", "lens": {"field_id": "5437dc8e-ae06-404c-9fd7-e93763bb5c4c", "field_label": "Ecological, scientific, or ethical insight still cited today", "parameter_id": "6a196681-0157-4a55-8c94-e34688a3deda", "parameter_name": "Contemporary Relevance"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Vishvamitra explicitly reevaluates force and redirects himself toward tapas.", "link_id": "041e2a5f-3690-48da-b2e8-03aa83b2934b", "page_or_section": "1.56.23-24", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur Valmiki Ramayanam Project", "rights_or_access_no