insert into original_claims values ('57712c65-7d33-4691-97c5-4f9807ca3e2a','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "57712c65-7d33-4691-97c5-4f9807ca3e2a", "claim_kind": "contemporary_relevance", "claim_relations": [], "claim_text": "A robust modern profile of Vishvamitra should model epistemic humility: users can learn not only ''what the tradition says'' but also which source says it, what kind of text it is, and where traditions conflict.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "SYNTHETIC_INTERPRETATION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "modern_spiritual_interpretation", "lens": {"field_id": "5437dc8e-ae06-404c-9fd7-e93763bb5c4c", "field_label": "Ecological, scientific, or ethical insight still cited today", "parameter_id": "6a196681-0157-4a55-8c94-e34688a3deda", "parameter_name": "Contemporary Relevance"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The expanded corpus contains explicit differences among source layers and is suited to provenance-aware presentation.", "link_id": "f38d71f2-e9d4-46d2-816e-a136ab49102b", "page_or_section": "Research-method application", "passages": [], "relationship": "supports", "source": {"author": "Mahidasa Aitareya (traditional attribution)", "authority_metadata": {}, "citation": "Aitareya Brahmana", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Vedic H