insert into original_claims values ('591afbb4-c364-46d4-95b5-0c0a35274d5b','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "591afbb4-c364-46d4-95b5-0c0a35274d5b", "claim_kind": "contemporary_relevance", "claim_relations": [], "claim_text": "The Galava story can support reflection on unhealthy insistence and escalating obligation: the Mahabharata itself introduces the story as an example of the dangers of rigid persistence, not merely as praise of guru-dakshina.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "UNSUPPORTED", "epistemic_type": "NORMATIVE_RELEVANCE", "proposed_type": "NORMATIVE_RELEVANCE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source", "Recorded source access issue"], "evidence_type": "modern_spiritual_interpretation", "lens": {"field_id": "5437dc8e-ae06-404c-9fd7-e93763bb5c4c", "field_label": "Ecological, scientific, or ethical insight still cited today", "parameter_id": "6a196681-0157-4a55-8c94-e34688a3deda", "parameter_name": "Contemporary Relevance"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The framing discourse warns against nirbandha before narrating Galava''s repeated insistence.", "link_id": "b36c1666-6f09-464a-9062-6f052aab83ef", "page_or_section": "5.104", "passages": [], "relationship": "supports", "source": {"author": "Vyasa (traditional attribution); BORI Critical Edition", "authority_metadata": {}, "citation": "Mahabharata BORI, Udyoga Parva, 104", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Bhandarkar Oriental Re