insert into original_claims values ('8797c1b5-ffa0-40d1-80de-9b7f082e3f9c','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "8797c1b5-ffa0-40d1-80de-9b7f082e3f9c", "claim_kind": "contemporary_relevance", "claim_relations": [], "claim_text": "The river dialogue of RV 3.33 can support reflection on negotiation with environmental constraints because the poem gives the rivers voices and depicts a request for passage; calling it a scientific or ecological theory would exceed the evidence.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "PARTIALLY_SUPPORTED", "epistemic_type": "NORMATIVE_RELEVANCE", "proposed_type": "NORMATIVE_RELEVANCE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source", "Recorded source access issue", "Claim-passage link points to a source absent from claim-source links"], "evidence_type": "modern_spiritual_interpretation", "lens": {"field_id": "5437dc8e-ae06-404c-9fd7-e93763bb5c4c", "field_label": "Ecological, scientific, or ethical insight still cited today", "parameter_id": "6a196681-0157-4a55-8c94-e34688a3deda", "parameter_name": "Contemporary Relevance"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The hymn''s human-river dialogue centers on crossing and accommodation.", "link_id": "85ede3c3-0541-4dc2-8906-5594ffa9d629", "page_or_section": "RV 3.33", "passages": [], "relationship": "supports", "source": {"author": "", "authority_metadata": {}, "citation": "Rigveda Mandala 3 translation edition", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IGNCA Digital Library, Government of India", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Rigveda Samhita, Volume III", "url": "https://ignca.gov.in/eBooks/RigVeda_Samhita_Vol_03.pdf"}, "source_id": "eabc9c3f-496a-4d87-acae-c67d983ccf20"}], "unmatched_passage_links": [{"chunk_id": "391eb3b5-1fcd-4354-91a6-1149ddbc926c", "excerpt": "रमध्वं मे वचसे सोम्याय ऋतावरीरुप मुहूर्तमेवैः । प्र सिन्धुमच्छा बृहती मनीषावस्युरह्वे कुशिकस्य सूनुः ramadhvaṃ me vacase somyāya ṛtāvarīrupa muhūrtamevaiḥ | pra sindhumacchā bṛhatī manīṣāvasyurahve kuśikasya sūnuḥ Linger a little at my friendly bidding rest, Holy Ones, a moment in your journey. With hymn sublime soliciting your favour Kusika''s son hath …", "excerpt_truncated": true, "page_or_section": "3.33.5", "relationship": "context", "source": {"author": null, "publication_year": null, "publisher_or_institution": null, "rights_or_access_note": null, "source_status": "approved", "source_type": "primary_text", "title": "Maṇḍala 3 — 62 hymns of the Viśvāmitra family (incl. Gāyatrī) — Rigveda — Swaveda", "url": "https://www.swaveda.com/texts/rigveda/3/"}, "source_id": "681b7993-1899-497d-864c-287d302819ec"}]}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('a953ef3f-5b7a-492b-bf55-a38553087bb5','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "a953ef3f-5b7a-492b-bf55-a38553087bb5", "claim_kind": "contemporary_relevance", "claim_relations": [], "claim_text": "Rigveda 3.33 can support modern reflection on human relationships with rivers because the hymn dramatizes an encounter between a human speaker/tradition and personified rivers; calling it an ecological doctrine would go beyond the text.", "current_status": "approved", "epistemics": {"contract_basis": "synthesis", "contract_satisfied": true, "contract_status": "SUPPORTED", "epistemic_type": "NORMATIVE_RELEVANCE", "proposed_type": "NORMATIVE_RELEVANCE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source", "Claim-passage link points to a source absent from claim-source links"], "evidence_type": "modern_spiritual_interpretation", "lens": {"field_id": "5437dc8e-ae06-404c-9fd7-e93763bb5c4c", "field_label": "Ecological, scientific, or ethical insight still cited today", "parameter_id": "6a196681-0157-4a55-8c94-e34688a3deda", "parameter_name": "Contemporary Relevance"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The hymn is structured around the rivers Vipash and Shutudri and a dialogue involving the Vishvamitra tradition.", "link_id": "70b51291-b08b-4979-9bb6-48501ed72e06", "page_or_section": "RV 3.33", "passages": [{"chunk_id": "28e43212-3a25-40bd-b90a-b626c17c3dfc", "confidence": 0.74, "excerpt": "Hindi Translation by Pt. Sripada Damodara Satavalekar  English Translation by H.H. Wilson  Commentary of Sayanacharya", "excerpt_truncated": false, "is_active": true, "link_method": "single_chu