insert into original_claims values ('b0f78340-5c9b-4391-85ea-21d795dc65a5','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "b0f78340-5c9b-4391-85ea-21d795dc65a5", "claim_kind": "contemporary_relevance", "claim_relations": [], "claim_text": "The Aitareya Devarata episode can support discussion of how communities construct belonging through adoption, recognition, and knowledge-lineage, while any comparison with modern caste or legal adoption requires careful qualification.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "PARTIALLY_SUPPORTED", "epistemic_type": "NORMATIVE_RELEVANCE", "proposed_type": "NORMATIVE_RELEVANCE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source", "Recorded source access issue", "Claim-passage link points to a source absent from claim-source links"], "evidence_type": "modern_spiritual_interpretation", "lens": {"field_id": "5437dc8e-ae06-404c-9fd7-e93763bb5c4c", "field_label": "Ecological, scientific, or ethical insight still cited today", "parameter_id": "6a196681-0157-4a55-8c94-e34688a3deda", "parameter_name": "Contemporary Relevance"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Devarata receives a new filial identity, precedence, and a dual heritage in the Brahmana narrative.", "link_id": "04c095e2-5b82-4cce-94ca-557c82ce3d25", "page_or_section": "Aitareya Brahmana Devarata section", "passages": [], "relationship": "supports", "source": {"author": "", "authority_metadata": {}, "citation": "Aitareya Brahmana Devarata lineage passage", "original_work_identity": {},