insert into original_claims values ('bf538f50-667a-41c3-b0a5-6c5aef606ef8','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "bf538f50-667a-41c3-b0a5-6c5aef606ef8", "claim_kind": "contemporary_relevance", "claim_relations": [], "claim_text": "The contrast among Rigvedic, Brahmana, Ramayana, Mahabharata, and later Upanishadic Vishvamitra traditions can be used to teach how cultural memory grows through layers rather than assuming every source records the same biography.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "modern_spiritual_interpretation", "lens": {"field_id": "5437dc8e-ae06-404c-9fd7-e93763bb5c4c", "field_label": "Ecological, scientific, or ethical insight still cited today", "parameter_id": "6a196681-0157-4a55-8c94-e34688a3deda", "parameter_name": "Contemporary Relevance"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The later Arsheya text visibly differs in genre and purpose from the early Vedic and epic sources.", "link_id": "6f5b325d-d137-44a7-af84-db12a4dfe76d", "page_or_section": "Reception-history application", "passages": [], "relationship": "supports", "source": {"author": "Traditional text", "authority_metadata": {}, "citation": "Arsheya Upanishad", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Vedic Heritage Portal / IGNCA / Ministr