insert into original_claims values ('c789f291-b26e-403b-a2f4-c2713c25a607','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "c789f291-b26e-403b-a2f4-c2713c25a607", "claim_kind": "contemporary_relevance", "claim_relations": [], "claim_text": "The Shanti Parva famine dialogue can be used to examine crisis ethics—how normal rules are argued over when survival is threatened—without claiming that the text supplies a simple modern policy rule.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "NORMATIVE_RELEVANCE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source", "Recorded source access issue"], "evidence_type": "modern_spiritual_interpretation", "lens": {"field_id": "5437dc8e-ae06-404c-9fd7-e93763bb5c4c", "field_label": "Ecological, scientific, or ethical insight still cited today", "parameter_id": "6a196681-0157-4a55-8c94-e34688a3deda", "parameter_name": "Contemporary Relevance"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The chapter presents competing arguments over forbidden food and preservation of life under famine.", "link_id": "19cfe835-479b-44ac-8ab7-dab2d1ea16bf", "page_or_section": "12.142", "passages": [], "relationship": "supports", "source": {"author": "Vyasa (traditional attribution)", "authority_metadata": {}, "citation": "Mahabharata, Shanti Parva, 142", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Gita Press edition / Vedapath 