insert into original_claims values ('d98b5b2f-ad60-423e-813b-abdff6bfbd80','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "d98b5b2f-ad60-423e-813b-abdff6bfbd80", "claim_kind": "contemporary_relevance", "claim_relations": [], "claim_text": "The Trishanku refuge statement can support discussion of responsibility toward someone who has sought protection, while the curses that follow prevent the episode from being reduced to a simple modern humanitarian slogan.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "PARTIALLY_SUPPORTED", "epistemic_type": "NORMATIVE_RELEVANCE", "proposed_type": "NORMATIVE_RELEVANCE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["Current approval origin does not establish strict verification", "Recorded source access issue"], "evidence_type": "modern_spiritual_interpretation", "lens": {"field_id": "5437dc8e-ae06-404c-9fd7-e93763bb5c4c", "field_label": "Ecological, scientific, or ethical insight still cited today", "parameter_id": "6a196681-0157-4a55-8c94-e34688a3deda", "parameter_name": "Contemporary Relevance"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The same narrative includes both protection of Trishanku and punitive anger toward opponents.", "link_id": "026dfd50-0992-43cf-8b7c-51a5eada9313", "page_or_section": "1.59", "passages": [{"chunk_id": "5326a31a-1540-4cb8-bab3-96ed76b89a7a", "confidence": 0.843076923076923, "excerpt": "\"The eminent sage Vishvamitra having heard those words of the sons of Vashishta  from all of his disciples, said this rancorously with bloodshot eyes.  \" ''He who reproves me, who am abiding in rigorous ascesis, and who am an  unreprovable one by my ascetic merit, that irreverent person will be reduced to  ashes, and there is no doubt about it. Now they will …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Book I : Bala Kanda - The Youthful Majesties\n Sarga 59 in Prose", "relationship": "supports", "section_title": "Book I : Bala Kanda - The Youthful Majesties\n Sarga 59 in Prose", "source_id": "7b637414-d012-4349-9ea0-bded3c081f08", "textual_layer": "Ramayana — Bala Kanda"}, {"chunk_id": "7fa20770-91d1-4b00-a9ae-b651c966d204", "confidence": 0.926153846153846, "excerpt": "Vishvamitra undertakes Trishanku''s Vedic ritual and sends disciples   to invite all Vedic-scholars. Many sages have come except for   Vashishta and his sons. Further, the sons of Vashishta have   ridiculed this ritual of Vishvamitra and Trishanku. Vishvamitra gets   irritated and hurls curses at the sons of Vashishta.  \"Vishvamitra, the son of Kushi, …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Book I : Bala Kanda - The Youthful Majesties\n Sarga 59 in Prose", "relationship": "supports", "section_title": "Book I : Bala Kanda - The Youthful Majesties\n Sarga 59 in Prose", "source_id": "7b637414-d012-4349-9ea0-bded3c081f08", "textual_layer": "Ramayana — Bala Kanda"}], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution); English rendering by Desiraju Hanumanta Rao", "authority_metadata": {"verified_http_status": 200}, "citation": "Valmiki Ramayana, Bala Kanda 1.59, chapter-level prose rendering.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": "Publicly accessible chapter page; preserve source attribution and link.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayana — Bala Kanda, Sarga 59 (prose)", "url": "https://www.valmikiramayan.net/utf8/baala/sarga59/bala_59_prose.htm"}, "source_id": "7b637414-d012-4349-9ea0-bded3c081f08"}, {"evidence_excerpt": "The same narrative includes both protection of Trishanku and punitive anger toward opponents.", "link_id": "0b38936e-b67b-4d92-acee-64c150aa114a", "page_or_section": "1.59", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur Valmiki Ramayanam Project", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same Bala Kanda chapter is linked below; compare editions before using a quotation.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayanam, Bala Kanda, Sarga 59", "url": "https://www.valmiki.iitk.ac.in/summary?field_kanda_tid=1&field_sarga_value=59"}, "source_id": "a7c009d6-db4c-405e-b465-47bdc344f5b4"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
