insert into original_claims values ('5b955e77-8ebc-4140-88e7-014663f7827c','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "5b955e77-8ebc-4140-88e7-014663f7827c", "claim_kind": "contemporary_relevance", "claim_relations": [], "claim_text": "Contemporary practice claims such as how many people recite a Vishvamitra-associated mantra, what benefits they receive, or how it is used in specific communities require separate modern evidence and should not be inferred from the ancient text alone.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "SYNTHETIC_INTERPRETATION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "modern_spiritual_interpretation", "lens": {"field_id": "8254a49f-53cc-43e8-9761-c306b5c6b07c", "field_label": "Relevance to modern seekers or practitioners", "parameter_id": "6a196681-0157-4a55-8c94-e34688a3deda", "parameter_name": "Contemporary Relevance"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The portal establishes the mantra text and attribution, not present-day prevalence or outcomes.", "link_id": "caad2437-4115-4799-9b09-da021073f86f", "page_or_section": "Evidence-limit statement", "passages": [{"chunk_id": "dbcfbb5a-8120-4b13-9f5a-9d266e46e0d0", "confidence": 0.74, "excerpt": "Hindi Translation by Pt. Sripada Damodara Satavalekar  English Translation by H.H. Wilson  Commentary of Sayanacharya", "excerpt_truncated": false, "is_active": true, "link_method": "single_chunk_curated_source", "page_or_secti