insert into original_claims values ('b46edeb8-41a6-4e38-858b-fe14ad30e974','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "b46edeb8-41a6-4e38-858b-fe14ad30e974", "claim_kind": "contemporary_relevance", "claim_relations": [], "claim_text": "The official Aitareya Brahmana page provides Indian editions/translations and contextual metadata, making the Shunahshepa-Devarata layer accessible for comparison with the epic version.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "modern_spiritual_interpretation", "lens": {"field_id": "8254a49f-53cc-43e8-9761-c306b5c6b07c", "field_label": "Relevance to modern seekers or practitioners", "parameter_id": "6a196681-0157-4a55-8c94-e34688a3deda", "parameter_name": "Contemporary Relevance"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The portal links editions/translations and describes the Brahmana''s structure and recension.", "link_id": "4fba71ea-ce78-44df-8fa8-04789b9aa519", "page_or_section": "Aitareya Brahmana portal", "passages": [], "relationship": "supports", "source": {"author": "Mahidasa Aitareya (traditional attribution)", "authority_metadata": {}, "citation": "Aitareya Brahmana", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Vedic Heritage Portal / IGNCA / Ministry of Culture, Government of India", "rights_