insert into original_claims values ('cbe404a2-efe8-4fd9-8572-44e9b7728225','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "cbe404a2-efe8-4fd9-8572-44e9b7728225", "claim_kind": "contemporary_relevance", "claim_relations": [], "claim_text": "For responsible contemporary study, source-layer labels are themselves a practical tool: learners should be able to filter Vishvamitra material by Samhita, Brahmana, Ramayana, Mahabharata, later Upanishad, and modern commentary before drawing conclusions.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "SYNTHETIC_INTERPRETATION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "modern_spiritual_interpretation", "lens": {"field_id": "8254a49f-53cc-43e8-9761-c306b5c6b07c", "field_label": "Relevance to modern seekers or practitioners", "parameter_id": "6a196681-0157-4a55-8c94-e34688a3deda", "parameter_name": "Contemporary Relevance"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The expanded source set demonstrates materially different genres and periods.", "link_id": "757fe4cc-3068-4103-9c9f-a80dc39b2374", "page_or_section": "Research-practice recommendation", "passages": [], "relationship": "supports", "source": {"author": "Mahidasa Aitareya (traditional attribution)", "authority_metadata": {}, "citation": "Aitareya Brahmana", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Vedic Heritage