insert into original_claims values ('ccaa820e-2581-480c-8dd2-b2af7ba6df99','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "ccaa820e-2581-480c-8dd2-b2af7ba6df99", "claim_kind": "contemporary_relevance", "claim_relations": [], "claim_text": "The Arsheya Upanishad page provides a separate modern access point for later philosophical reception of Vishvamitra, which can be studied without confusing it with the older Rigvedic material.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "MODERN_RECEPTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "modern_spiritual_interpretation", "lens": {"field_id": "8254a49f-53cc-43e8-9761-c306b5c6b07c", "field_label": "Relevance to modern seekers or practitioners", "parameter_id": "6a196681-0157-4a55-8c94-e34688a3deda", "parameter_name": "Contemporary Relevance"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The portal classifies the text as a later Vedantic Upanishad and summarizes its five-seer dialogue.", "link_id": "01cb2edf-2e55-4885-8a4a-57f66cb2e4eb", "page_or_section": "Arsheya Upanishad portal", "passages": [{"chunk_id": "2d2aac38-e6ad-4b85-b8a5-5c566247b921", "confidence": 0.870769230769231, "excerpt": "Ārṣeya Upaniṣad is not considered as a principal Upaniṣad of Vedic Literature but it is recognised as a significant Upaniṣad among the ‘Vedānta-Upanis̩ads’ of comparatively later times. Later Upaniṣads were developed to propound the concepts of certain famous schools, such as Yoga, Vedānta, Śākta, Vaiṣṇava and Śaiva.  ĀrṣeyaUpaniṣad is a …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Arsheyopanishad", "relationship": "supports", "section_title": "Arsheyopanishad", "source_id": "f76efd31-3f90-4b32-b386-99e3cce78d6a", "textual_layer": "Traditional or scholarly source"}], "relationship": "supports", "source": {"author": "Traditional text", "authority_metadata": {}, "citation": "Arsheya Upanishad", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Vedic Heritage Portal / IGNCA / Ministry of Culture, Government of India", "rights_or_access_note": null, "source_status": "approved", "source_type": "institutional", "storage_path": null, "title": "Arsheya Upanishad", "url": "https://vedicheritage.gov.in/upanishads/aarsheyopanishad/"}, "source_id": "f76efd31-3f90-4b32-b386-99e3cce78d6a"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('0eb957fc-9afa-4434-9aa8-2e2c3700d2d9','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "0eb957fc-9afa-4434-9aa8-2e2c3700d2d9", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "In Sri Aurobindo''s reading, the value of Vishvamitra''s hymns is not limited to external ritual description; they can encode inner spiritual processes.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "SCHOLARLY_INTERPRETATION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "008261e8-2588-40b3-bb3b-3de5dc1d4d4b", "field_label": "Resonance with Sri Aurobindo / Mother reinterpretations where relevant", "parameter_id": "6a196681-0157-4a55-8c94-e34688a3deda", "parameter_name": "Contemporary Relevance"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The work repeatedly develops a psychological interpretation of Vedic images and applies it to Vishvamitra material.", "link_id": "7d6457ca-f3de-4a8b-892e-2199bd4961fc", "page_or_section": "The Secret of the Veda", "passages": [{"chunk_id": "f39f9469-2abe-4d18-b267-8a6a7ee0dbe9", "confidence": 0.55, "excerpt": "Agni and the Truth 59 be necessary. A critical scrutiny covering the whole of the ten Mandalas would be indispensable. To justify for instance the idea I attach to the Vedic term Ritam, the Truth, or my ex- planation of the symbol of the Cow of Light, I should have to cite all passages of any importance in which the idea of the Truth or the image of the Cow …", "excerpt_truncated": true, "is_active": true, "link_method": "adaptive_partial", "page_or_section": "Page 71", "relationship": "context", "section_title": "Page 71", "source_id": "7efe2589-0b7e-4cee-bcc0-b71b0ba418e6", "textual_layer": "Modern spiritual interpretation"}], "relationship": "supports", "source": {"author": "Sri Aurobindo", "authority_metadata": {}, "citation": "Sri Aurobindo, The Secret of the Veda. Sri Aurobindo Ashram.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Sri Aurobindo Ashram", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_book", "storage_path": null, "title": "The Secret of the Veda", "url": "https://www.sriaurobindoashram.org/sriaurobindo/downloadpdf.php?id=30"}, "source_id": "7efe2589-0b7e-4cee-bcc0-b71b0ba418e6"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
