insert into original_claims values ('6d8963cd-9b9e-4775-b9f8-1a08ccb4b846','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "6d8963cd-9b9e-4775-b9f8-1a08ccb4b846", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "Sri Aurobindo explicitly reads Vedic rivers as psychological/spiritual symbols and uses hymns of Vishvamitra in developing that interpretive approach.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "008261e8-2588-40b3-bb3b-3de5dc1d4d4b", "field_label": "Resonance with Sri Aurobindo / Mother reinterpretations where relevant", "parameter_id": "6a196681-0157-4a55-8c94-e34688a3deda", "parameter_name": "Contemporary Relevance"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The Secret of the Veda discusses rivers as streams of conscious being and examines a hymn of Vishvamitra in that symbolic framework.", "link_id": "719094fb-e1c8-4fcb-bb8c-4ad7cedf3ded", "page_or_section": "The Secret of the Veda", "passages": [{"chunk_id": "ef24ca05-1fe2-47cc-a308-9e19c7d14740", "confidence": 0.76, "excerpt": "108 The Secret of the Veda Thus we find that both Veda and Purana use the same symbolic images; the ocean is for them the image of infinite and eternal existence. We find also that the image of the river or flowing cur