insert into original_claims values ('ad3ff90d-02b6-4377-8be5-b633c7a71559','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "ad3ff90d-02b6-4377-8be5-b633c7a71559", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "Sri Aurobindo''s treatment of Agni in Vishvamitra''s hymns is part of his wider ''mystic fire'' interpretation, in which Agni has an inward spiritual function in addition to the external sacrificial fire.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "SCHOLARLY_INTERPRETATION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "008261e8-2588-40b3-bb3b-3de5dc1d4d4b", "field_label": "Resonance with Sri Aurobindo / Mother reinterpretations where relevant", "parameter_id": "6a196681-0157-4a55-8c94-e34688a3deda", "parameter_name": "Contemporary Relevance"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Hymns to the Mystic Fire translates and interprets multiple Vishvamitra-family Agni hymns in this framework.", "link_id": "abc569b0-0222-42f4-903b-4c50d1ec8090", "page_or_section": "Hymns to the Mystic Fire", "passages": [], "relationship": "supports", "source": {"author": "Sri Aurobindo", "authority_metadata": {}, "citation": "Sri Aurobindo, Hymns to the Mystic Fire", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Sri Aurobindo Ashram", "right