insert into original_claims values ('b5244f1a-f73f-4ea8-943c-01877b54cf06','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "b5244f1a-f73f-4ea8-943c-01877b54cf06", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "In that reading, Sri Aurobindo interprets the seven rivers not primarily as earthly waterways but as ''waters'' of Truth and Bliss descending into consciousness.", "current_status": "approved", "epistemics": {"contract_basis": "reception", "contract_satisfied": true, "contract_status": "SUPPORTED", "epistemic_type": "MODERN_RECEPTION", "proposed_type": "MODERN_RECEPTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "008261e8-2588-40b3-bb3b-3de5dc1d4d4b", "field_label": "Resonance with Sri Aurobindo / Mother reinterpretations where relevant", "parameter_id": "6a196681-0157-4a55-8c94-e34688a3deda", "parameter_name": "Contemporary Relevance"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The chapter explains the rivers as spiritual/psychological waters connected with rta and divine felicity.", "link_id": "0b563bac-a381-487e-9da4-79eb60d3ea82", "page_or_section": "The Secret of the Veda, ''The Seven Rivers''", "passages": [{"chunk_id": "525c0ae6-7a16-4124-9cea-cc389895f9eb", "confidence": 0.76, "excerpt": "The Seven Rivers 117 increases by knowledge and makes his home and rest in the source of the Truth, of whom Heaven and Earth are the wives and lovers, who is increased by the divine waters in the unob- structed Vast, his own seat, and dwelling in that shoreless infinity yields to the illumined gods the supreme Immortality, cannot be the god of physical …", "excerpt_truncated": true, "is_active": true, "link_method": "adaptive_strong", "page_or_section": "Page 129", "relationship": "context", "section_title": "Page 129", "source_id": "7efe2589-0b7e-4cee-bcc0-b71b0ba418e6", "textual_layer": "Modern spiritual interpretation"}, {"chunk_id": "b3afae10-af26-4987-b206-61ddc5477469", "confidence": 0.95, "excerpt": "The Seven Rivers 113 construction upon such expressions. Obviously these are the waters of the Truth and the Bliss that flow from the supreme ocean. These rivers flow not upon earth, but in heaven; they are prevented by Vritra the Besieger, the Coverer from flowing down upon the earth-consciousness in which we mortals live till Indra, the god-mind, smites …", "excerpt_truncated": true, "is_active": true, "link_method": "citation_exact", "page_or_section": "Page 125", "relationship": "supports", "section_title": "Page 125", "source_id": "7efe2589-0b7e-4cee-bcc0-b71b0ba418e6", "textual_layer": "Modern spiritual interpretation"}], "relationship": "supports", "source": {"author": "Sri Aurobindo", "authority_metadata": {}, "citation": "Sri Aurobindo, The Secret of the Veda. Sri Aurobindo Ashram.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Sri Aurobindo Ashram", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_book", "storage_path": null, "title": "The Secret of the Veda", "url": "https://www.sriaurobindoashram.org/sriaurobindo/downloadpdf.php?id=30"}, "source_id": "7efe2589-0b7e-4cee-bcc0-b71b0ba418e6"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('b75384c6-f2a9-42d9-9ed8-530a91b3ad57','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "b75384c6-f2a9-42d9-9ed8-530a91b3ad57", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "Sri Aurobindo connects the obstruction of those symbolic waters with Vritra and their release with Indra, making Vishvamitra''s hymn part of a larger psychological reading of Vedic myth.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "SCHOLARLY_INTERPRETATION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "008261e8-2588-40b3-bb3b-3de5dc1d4d4b", "field_label": "Resonance with Sri Aurobindo / Mother reinterpretations where relevant", "parameter_id": "6a196681-0157-4a55-8c94-e34688a3deda", "parameter_name": "Contemporary Relevance"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The discussion links Vritra''s covering and Indra''s action to the descent of the truth-waters.", "link_id": "ece59989-b104-4d4c-bbff-6b6733812a1f", "page_or_section": "The Secret of the Veda", "passages": [{"chunk_id": "b3afae10-af26-4987-b206-61ddc5477469", "confidence": 0.55, "excerpt": "The Seven Rivers 113 construction upon such expressions. Obviously these are the waters of the Truth and the Bliss that flow from the supreme ocean. These rivers flow not upon earth, but in heaven; they are prevented by Vritra the Besieger, the Coverer from flowing down upon the earth-consciousness in which we mortals live till Indra, the god-mind, smites …", "excerpt_truncated": true, "is_active": true, "link_method": "adaptive_partial", "page_or_section": "Page 125", "relationship": "context", "section_title": "Page 125", "source_id": "7efe2589-0b7e-4cee-bcc0-b71b0ba418e6", "textual_layer": "Modern spiritual interpretation"}], "relationship": "supports", "source": {"author": "Sri Aurobindo", "authority_metadata": {}, "citation": "Sri Aurobindo, The Secret of the Veda. Sri Aurobindo Ashram.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Sri Aurobindo Ashram", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_book", "storage_path": null, "title": "The Secret of the Veda", "url": "https://www.sriaurobindoashram.org/sriaurobindo/downloadpdf.php?id=30"}, "source_id": "7efe2589-0b7e-4cee-bcc0-b71b0ba418e6"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
