insert into original_claims values ('e4f4b57d-1885-43e7-9527-d642b8e89ad7','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "e4f4b57d-1885-43e7-9527-d642b8e89ad7", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "Hymns to the Mystic Fire preserves a useful attribution map that separates Vishvamitra Gathina from Rishabha Vaishvamitra, Kata Vaishvamitra, Gathin Kaushika, and other Mandala 3 seers; this textual caution complements the philosophical interpretation.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "008261e8-2588-40b3-bb3b-3de5dc1d4d4b", "field_label": "Resonance with Sri Aurobindo / Mother reinterpretations where relevant", "parameter_id": "6a196681-0157-4a55-8c94-e34688a3deda", "parameter_name": "Contemporary Relevance"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The contents list different seer names for successive Mandala 3 hymn groups.", "link_id": "c2807de5-6bce-49d5-919b-ddc52a840432", "page_or_section": "Hymns to the Mystic Fire contents", "passages": [], "relationship": "supports", "source": {"author": "Sri Aurobindo", "authority_metadata": {}, "citation": "Sri Aurobindo, Hymns to the Mystic Fire", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Sri Aurobin