insert into original_claims values ('07cee02d-65d0-4e28-9c84-9dba4a419373','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "07cee02d-65d0-4e28-9c84-9dba4a419373", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "The Shanti Parva dog-meat episode is explicitly set during devastating famine and structured as a debate over emergency dharma, so presenting it as a shocking dietary anecdote would omit its core ethical context.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "SCHOLARLY_INTERPRETATION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source", "Recorded source access issue"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "deacfced-f020-44ef-94cd-27ff0c484505", "field_label": "Episodes commonly sensationalized or misread out of context", "parameter_id": "e9e12cd4-53da-4743-8917-a2868006ced2", "parameter_name": "Contested or Uncertain Aspects"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Vishvamitra and the shvapaka debate survival, purity, precedent, and right conduct under famine.", "link_id": "7bc82050-f5b9-4abb-8fef-5ee25eeab2f1", "page_or_section": "12.142", "passages": [], "relationship": "supports", "source": {"author": "Vyasa (traditional attribution)", "authority_metadata": {}, "citation": "Mahabharata, Shanti Parva, 142", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Gita Press edition / Vedapath presentation", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Mahabharata (Gita Press edition), Shanti Parva, Adhyaya 142", "url": "https://vedapath.app/en/mahabharata-gita-press/shanti-parva/142"}, "source_id": "1265258a-bc16-44e0-8c55-55ca3104767e"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('1e21747b-e3a9-40aa-8aaf-2992868e32a1','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "1e21747b-e3a9-40aa-8aaf-2992868e32a1", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "The Tataka episode should preserve the fact that Rama initially receives instruction and authorization from Vishvamitra; presenting it only as a monster-slaying adventure erases the episode''s teacher-student and dharma-deliberation frame.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "SYNTHETIC_INTERPRETATION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Recorded source access issue"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "deacfced-f020-44ef-94cd-27ff0c484505", "field_label": "Episodes commonly sensationalized or misread out of context", "parameter_id": "e9e12cd4-53da-4743-8917-a2868006ced2", "parameter_name": "Contested or Uncertain Aspects"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The chapter centers Vishvamitra''s command and Rama''s response to guru/fatherly instruction.", "link_id": "8f5fb602-f994-47eb-a966-08d8528ca119", "page_or_section": "1.26", "passages": [{"chunk_id": "2c5b47db-6540-4f24-9cc3-6db9940c0037", "confidence": 0.926153846153846, "excerpt": "Rama encounters his first problem-female demoness Tataka, also called as Taadaka, and   eliminates her at the orders of sage Vishvamitra. This is a crucial test put to Rama by   Vishvamitra in ascertaining whether Rama is the follower of dharma through elder men''s   orders or not. Rama eradicates Tataka basing on his own self-confidence.  On hearing the …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Book I : Bala Kanda - The Youthful Majesties\nSarga 26 in Prose", "relationship": "supports", "section_title": "Book I : Bala Kanda - The Youthful Majesties\nSarga 26 in Prose", "source_id": "20585d18-784f-4e7d-8daf-49e857c82117", "textual_layer": "Ramayana — Bala Kanda"}, {"chunk_id": "d16508d6-1660-4988-b84f-4fd1d2b71a40", "confidence": 0.898461538461538, "excerpt": "These are the sons like missiles of Krishaashava Prajaapati. About them, the divine weaponry and  their birth, c.f. 21st sarga/chapter, verse 10 to 20.  \"Rama is steadfast in following your assignments and thus he is the worthy receiver of those  missiles, and this prince has to accomplish a very great deed of gods.” So said gods to Vishvamitra.  All the …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Book I : Bala Kanda - The Youthful Majesties\nSarga 26 in Prose", "relationship": "supports", "section_title": "Book I : Bala Kanda - The Youthful Majesties\nSarga 26 in Prose", "source_id": "20585d18-784f-4e7d-8daf-49e857c82117", "textual_layer": "Ramayana — Bala Kanda"}], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution); English rendering by Desiraju Hanumanta Rao", "authority_metadata": {"verified_http_status": 200}, "citation": "Valmiki Ramayana, Bala Kanda 1.26, chapter-level prose rendering.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": "Publicly accessible chapter page; preserve source attribution and link.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayana — Bala Kanda, Sarga 26 (prose)", "url": "https://www.valmikiramayan.net/utf8/baala/sarga26/bala_26_prose.htm"}, "source_id": "20585d18-784f-4e7d-8daf-49e857c82117"}, {"evidence_excerpt": "The chapter centers Vishvamitra''s command and Rama''s response to guru/fatherly instruction.", "link_id": "9b04d343-8d19-4cfe-9948-85fbed72b621", "page_or_section": "1.26", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur Valmiki Ramayanam Project", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same Bala Kanda chapter is linked below; compare editions before using a quotation.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayanam, Bala Kanda, Sarga 26", "url": "https://www.valmiki.iitk.ac.in/summary?field_kanda_tid=1&field_sarga_value=26"}, "source_id": "52fd4b07-98c1-4502-b0b4-3adadf160d62"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('1e2b8e30-0d45-470e-9fa1-4fd4c652cb47','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "1e2b8e30-0d45-470e-9fa1-4fd4c652cb47", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "The final food-gift episode should not be reduced to a miracle of fasting; the narrative foregrounds hospitality to a supplicant and maintenance of a vow before escalating to supernatural tapas imagery.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "SYNTHETIC_INTERPRETATION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Recorded source access issue", "Claim-passage link points to a source absent from claim-source links"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "deacfced-f020-44ef-94cd-27ff0c484505", "field_label": "Episodes commonly sensationalized or misread out of context", "parameter_id": "e9e12cd4-53da-4743-8917-a2868006ced2", "parameter_name": "Contested or Uncertain Aspects"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Vishvamitra gives the meal away silently before beginning another ascetic phase.", "link_id": "86716372-061b-4c2f-9387-4ace2aeb6170", "page_or_section": "1.65", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur Valmiki Ramayanam Project", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same Bala Kanda chapter is linked below; compare editions before using a quotation.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayanam, Bala Kanda, Sarga 65", "url": "https://www.valmiki.iitk.ac.in/summary?field_kanda_tid=1&field_sarga_value=65"}, "source_id": "35d30c22-48b6-4242-ad17-697405136d76"}], "unmatched_passage_links": [{"chunk_id": "d5e6cd91-c377-43d8-a3aa-a6233c8d0a82", "excerpt": "This meal is prepared by Vishvamitra alone after a thousand years and such self-cooking  of food by the ascetics is called, vaishva devam, since it is a sacred  preparation anena vaishvadeva ante samaagato atithiH svayam upoShyaa api sviiya anna pradaanena  sambhojya iti suucitam - dk  तस्मैः दत्त्वा तदा सिद्धम् सर्वम् विप्राय निश्चितः | निःषेषिते अन्ने …", "excerpt_truncated": true, "page_or_section": "Introduction", "relationship": "context", "source": {"author": "Valmiki", "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "title": "Valmiki Ramayana, Bala Kanda, Sarga 65", "url": "https://www.valmikiramayan.net/utf8/baala/sarga65/balasans65.htm.orig"}, "source_id": "b1ff445c-d9d0-4f8e-a28f-f3a8053787ad"}, {"chunk_id": "ef5de7fd-af8f-4eaa-9685-ac9b0a43aa7d", "excerpt": "Vishvamitra becomes Brahma-sage after a prolonged ascesis that made all the worlds  to startle. All gods request Brahma to accord the supreme Brahma-sageship on Vishvamitra  as he is cleansed of all mortal impurities, and Brahma accords that highest order  on him. Thus Sage Shataananda concludes his narration about the legend of Vishvamitra.  अथ हैमवतीम् …", "excerpt_truncated": true, "page_or_section": "Introduction", "relationship": "context", "source": {"author": "Valmiki", "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "title": "Valmiki Ramayana, Bala Kanda, Sarga 65", "url": "https://www.valmikiramayan.net/utf8/baala/sarga65/balasans65.htm.orig"}, "source_id": "b1ff445c-d9d0-4f8e-a28f-f3a8053787ad"}]}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('3f1e2d3b-7ea3-45f3-b23a-6c4d4e55bb19','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "3f1e2d3b-7ea3-45f3-b23a-6c4d4e55bb19", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "The Galava-Madhavi story should not be summarized merely as ''Vishvamitra demanded 800 horses'': the Mahabharata first has him release Galava and only state the difficult demand after Galava repeatedly refuses to leave without paying.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "SCHOLARLY_INTERPRETATION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source", "Recorded source access issue"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "deacfced-f020-44ef-94cd-27ff0c484505", "field_label": "Episodes commonly sensationalized or misread out of context", "parameter_id": "e9e12cd4-53da-4743-8917-a2868006ced2", "parameter_name": "Contested or Uncertain Aspects"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The guru-dakshina demand is framed as the result of Galava''s obstinate insistence.", "link_id": "57ce3989-c656-4f79-b84b-a5bd2f790b1f", "page_or_section": "5.104", "passages": [], "relationship": "supports", "source": {"author": "Vyasa (traditional attribution); BORI Critical Edition", "authority_metadata": {}, "citation": "Mahabharata BORI, Udyoga Parva, 104", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Bhandarkar Oriental Research Institute critical text / Vedapath presentation", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Mahabharata (BORI Critical Edition), Udyoga Parva, Adhyaya 104", "url": "https://vedapath.app/en/mahabharata-bori/udyoga-parva/104"}, "source_id": "855f8c75-16cc-4e96-9ba3-d79579231842"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('4b527ad6-0edd-4d2c-9aee-d3df728949a5','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "4b527ad6-0edd-4d2c-9aee-d3df728949a5", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "The Menaka and Rambha episodes are best framed within the Ramayana’s larger arc of interruption, anger, remorse, renewed tapas, and eventual self-control rather than extracted as isolated scandal.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "PARTIALLY_SUPPORTED", "epistemic_type": "SYNTHETIC_INTERPRETATION", "proposed_type": "SYNTHETIC_INTERPRETATION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["Current approval origin does not establish strict verification", "Recorded source access issue"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "deacfced-f020-44ef-94cd-27ff0c484505", "field_label": "Episodes commonly sensationalized or misread out of context", "parameter_id": "e9e12cd4-53da-4743-8917-a2868006ced2", "parameter_name": "Contested or Uncertain Aspects"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The Menaka episode is embedded inside the larger tapas/Brahmarshi narrative.", "link_id": "22dd380a-a92c-47a6-8acd-78313662f414", "page_or_section": "Bala Kanda 1.63", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana, Bala Kanda 1.63. IIT Kanpur Valmiki Ramayanam.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same Bala Kanda chapter is linked below; compare editions before using a quotation.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayanam — Bala Kanda, Sarga 63", "url": "https://www.valmiki.iitk.ac.in/sloka?field_kanda_tid=1&field_sarga_value=63&language=dv"}, "source_id": "2025af50-f65e-4a13-b670-adc6a2a0e3dc"}, {"evidence_excerpt": "The Menaka episode is embedded inside the larger tapas/Brahmarshi narrative.", "link_id": "adcacaed-5b3a-4c31-9150-2d09dce32223", "page_or_section": "Bala Kanda 1.63", "passages": [{"chunk_id": "1c601c57-75d6-404c-868e-11361f2be7ee", "confidence": 0.926153846153846, "excerpt": "\" ''All this is the mischief of gods to defraud me of the great merit of my ascesis.  Ten years have rolled by as if they are just a day and a night. Furthermore, I who  am under the influence of lust and lure had to encounter this hindrance in my ascesis.''  Oh, Rama, that best saint suspired heavily when he became emotional with reparation.  But on seeing …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Book I : Bala Kanda - The Youthful Majesties\niSarga 63 n Prose", "relationship": "supports", "section_title": "Book I : Bala Kanda - The Youthful Majesties\niSarga 63 n Prose", "source_id": "d39ddd21-67b7-4c7c-bfae-ea1f99918420", "textual_layer": "Ramayana — Bala Kanda"}, {"chunk_id": "9c862712-4d53-404e-a5bb-1c24e1296451", "confidence": 0.843076923076923, "excerpt": "On Vishvamitra''s performing severe ascesis Brahma accords the sageship   of ''Great-sage'' to him, whereas Vishvamitra''s ambition is to acquire   the sageship of a ''Brahma-sage'' Absolute-sageship. In the meanwhile,   the celestial wench Menaka arrives at that place and Vishvamitra is   enticed by her beauty and spends some years with her. Later, on realising  …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Book I : Bala Kanda - The Youthful Majesties\niSarga 63 n Prose", "relationship": "supports", "section_title": "Book I : Bala Kanda - The Youthful Majesties\niSarga 63 n Prose", "source_id": "d39ddd21-67b7-4c7c-bfae-ea1f99918420", "textual_layer": "Ramayana — Bala Kanda"}], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution); English rendering by Desiraju Hanumanta Rao", "authority_metadata": {"verified_http_status": 200}, "citation": "Valmiki Ramayana, Bala Kanda 1.63, chapter-level prose rendering.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": "Publicly accessible chapter page; preserve source attribution and link.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayana — Bala Kanda, Sarga 63 (prose)", "url": "https://www.valmikiramayan.net/utf8/baala/sarga63/bala_63_prose.htm"}, "source_id": "d39ddd21-67b7-4c7c-bfae-ea1f99918420"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('921abb4e-69b7-4225-92ef-fddac41f8f66','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "921abb4e-69b7-4225-92ef-fddac41f8f66", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "The Menaka episode is not just a seduction anecdote in Bala Kanda: the text emphasizes a ten-year lapse, Vishvamitra''s later grief, recognition of interruption, and return to austerity.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "SYNTHETIC_INTERPRETATION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Recorded source access issue"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "deacfced-f020-44ef-94cd-27ff0c484505", "field_label": "Episodes commonly sensationalized or misread out of context", "parameter_id": "e9e12cd4-53da-4743-8917-a2868006ced2", "parameter_name": "Contested or Uncertain Aspects"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Verses 1.63.7-10 move from long companionship to remorse and renewed ascetic purpose.", "link_id": "a873a836-ae34-4bd8-bfc3-b49a88e9d141", "page_or_section": "1.63.7-10", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana, Bala Kanda 1.63. IIT Kanpur Valmiki Ramayanam.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same