insert into original_claims values ('a270dd64-9866-4032-b0dc-0c05a107bf10','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "a270dd64-9866-4032-b0dc-0c05a107bf10", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "The charu-exchange story in Anushasana Parva should be reported as a Mahabharata explanation of lineage and varna transformation, not sensationalized as a literal genetic account of inherited temperament.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "SCHOLARLY_INTERPRETATION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source", "Recorded source access issue"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "deacfced-f020-44ef-94cd-27ff0c484505", "field_label": "Episodes commonly sensationalized or misread out of context", "parameter_id": "e9e12cd4-53da-4743-8917-a2868006ced2", "parameter_name": "Contested or Uncertain Aspects"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "", "link_id": "74451169-bf80-4110-9b83-b90538e1082d", "page_or_section": "p. 61 (PDF page 21)", "passages": [{"chunk_id": "b5253384-909b-4ea2-b372-29b9842165a4", "confidence": 0.95, "excerpt": "61 at best what Ramanujan has termed ‘a presence of reflexive worlds’—a brief, fleeting glimpse of Kṣatriya-centered possibilities within the discourse of varṇa (ramanujan 1991, 54). Along with Viśvāmitra’s self-transformation, the resistant voices of his parents are rapidly foreclosed by the textual performance of the Satyavatī legend in the Anuśāsana …", "excerpt_truncated": true, "is_active": true, "link_method": "manual_exact_passage", "page_or_section": "p. 61 (PDF page 21)", "relationship": "supports", "section_title": "Page 21", "source_id": "06fec486-e5af-4c7e-95db-afbb2e237c75", "textual_layer": "Modern academic interpretation of Mahabharata"}], "relationship": "supports", "source": {"author": "Adheesh Sathaye", "authority_metadata": {}, "citation": "Sathaye, Adheesh. “How to become a Brahman.” Acta Orientalia Vilnensia 8.1 (2007): 41–67. doi:10.15388/AOV.2007.1.3751.", "original_work_identity": {"doi": "10.15388/aov.2007.1.3751", "independentWorkKey": "10.15388/aov.2007.1.3751", "sourceFamily": "journals.vu.lt/acta-orientalia-vilnensia"}, "publication_year": 2007, "publisher_or_institution": "Acta Orientalia Vilnensia / Vilnius University Press", "rights_or_access_note": "Official journal diamond open access, CC BY 4.0: https://www.journals.vu.lt/acta-orientalia-vilnensia/journalpolicy", "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "How to become a Brahman: The construction of varṇa as social place in the Mahābhārata’s legends of Viśvāmitra", "url": "https://www.journals.vu.lt/acta-orientalia-vilnensia/article/download/3751/5207"}, "source_id": "06fec486-e5af-4c7e-95db-afbb2e237c75"}, {"evidence_excerpt": "The chapter uses mantra-prepared ritual portions to explain contrasting brahmanic and kshatriya dispositions.", "link_id": "60241c6c-067e-48a9-9163-701db6b3479d", "page_or_section": "13.4", "passages": [], "relationship": "supports", "source": {"author": "Vyasa (traditional attribution); BORI Critical Edition", "authority_metadata": {}, "citation": "Mahabharata BORI, Anushasana Parva, 4", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Bhandarkar Oriental Research Institute critical text / Vedapath presentation", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Mahabharata (BORI Critical Edition), Anushasana Parva, Adhyaya 4", "url": "https://vedapath.app/en/mahabharata-bori/anushasana-parva/4"}, "source_id": "452b0f98-1f3c-49f2-b276-8e0bd02c7eef"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('be9c9822-362d-48f6-9964-38c02d26b3c6','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "be9c9822-362d-48f6-9964-38c02d26b3c6", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "The Rambha episode should not be reduced to a story of supernatural cursing; its narrative function also includes Vishvamitra''s recognition that anger has disrupted his ascetic goal.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "METHODOLOGICAL", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "deacfced-f020-44ef-94cd-27ff0c484505", "field_label": "Episodes commonly sensationalized or misread out of context", "parameter_id": "e9e12cd4-53da-4743-8917-a2868006ced2", "parameter_name": "Contested or Uncertain Aspects"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The chapter moves from Rambha''s attempted disruption to Vishvamitra''s anger, curse, shame, and renewed tapas.", "link_id": "b92a506c-3b2f-4136-965e-f730103cb41a", "page_or_section": "1.64", "passages": [{"chunk_id": "2a5bae86-6077-4fd8-8d21-59b2a47b760a", "confidence": 0.846086956521739, "excerpt": "Vishvamitra curses Rambha, the celestial wench, knowing that she arrived at the behest of Indra to cause  hindrance to his ascesis. But later feels ashamed to loose his tongue and then he is determined to undertake  another round of ascesis to conquer is own senses.  सुरकार्यमिदं रंभे कर्तव्यं सुमहत्त्वया |लोभनं कौशिकस्येह काममोहसमन्वितम् || १-६४-१  1. …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Introduction", "relationship": "supports", "section_title": "Introduction", "source_id": "8d1e7888-6577-4564-b935-96ed0ae1b902", "textual_layer": "Ramayana — Bala Kanda"}, {"chunk_id": "515003fb-3676-4dbd-8abb-a58e725319ce", "confidence": 0.903478260869565, "excerpt": "Whereof you tried to entice me who am wishing to win over the wanton and wroth, you unlucky female  Rambha, thereof you will become a rocklike statued wastrel. [1-64-12]  ब्राह्मणः सुमहातेजास्तपोबलसमन्वितः |उद्धरिष्यति रंभे त्वां मत्क्रोधकलुषीकृताम् || १-६४-१३  13. rambhe = oh Rambha; sumahaatejaaH = very high resplendent one;  tapobalasamanvitaH = having …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Introduction", "relationship": "supports", "section_title": "Introduction", "source_id": "8d1e7888-6577-4564-b935-96ed0ae1b902", "textual_layer": "Ramayana — Bala Kanda"}], "relationship": "supports", "source": {"author": "Valmiki", "authority_metadata": {}, "citation": "Valmiki Ramayana, Bala Kanda, Sarga 64 (https://www.valmikiramayan.net/utf8/baala/sarga64/balasans64.htm)", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Valmiki Ramayana, Bala Kanda, Sarga 64", "url": "https://www.valmikiramayan.net/utf8/baala/sarga64/balasans64.htm"}, "source_id": "8d1e7888-6577-4564-b935-96ed0ae1b902"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('ca4f2995-27cc-4c86-928a-42c08e06dddd','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "ca4f2995-27cc-4c86-928a-42c08e06dddd", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "The Shakuntala birth tradition should not be reduced to a Menaka-Vishvamitra romance: in the Mahabharata it becomes part of an adoption narrative, a theory of fatherhood, and ultimately the Bharata genealogy.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": null, "contract_status": "NOT_EVIDENTIARY", "epistemic_type": "METHODOLOGICAL", "proposed_type": "METHODOLOGICAL", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source", "Recorded source access issue"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "deacfced-f020-44ef-94cd-27ff0c484505", "field_label": "Episodes commonly sensationalized or misread out of context", "parameter_id": "e9e12cd4-53da-4743-8917-a2868006ced2", "parameter_name": "Contested or Uncertain Aspects"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The child is protected by birds, adopted by Kanva, and later linked to Bharata''s dynasty.", "link_id": "bca51de3-4188-4ede-a9d2-68193043e5d2", "page_or_section": "Adi Parva Shakuntala cycle", "passages": [], "relationship": "supports", "source": {"author": "Vyasa (traditional attribution); BORI Critical Edition", "authority_metadata": {}, "citation": "Mahabharata BORI, Adi Parva", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Bhandarkar Oriental Research Institute critical text / Vedapath presentation", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Mahabharata (BORI Critical Edition), Adi Parva", "url": "https://vedapath.app/en/mahabharata-bori/adi-parva"}, "source_id": "a97ed1ef-2f3e-46c0-a687-a334e69fc091"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('cf302d79-43e7-4c30-94ee-5a63e08598e9','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "cf302d79-43e7-4c30-94ee-5a63e08598e9", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "The Vasistha rivalry is not uniformly hostile across texts: Vasistha praises Vishvamitra before Dasharatha even though other narratives depict severe conflict, so a ''lifelong enemies'' label would flatten contradictory literary evidence.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "PARTIALLY_SUPPORTED", "epistemic_type": "SYNTHETIC_INTERPRETATION", "proposed_type": "SYNTHETIC_INTERPRETATION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["Current approval origin does not establish strict verification", "Recorded source access issue"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "deacfced-f020-44ef-94cd-27ff0c484505", "field_label": "Episodes commonly sensationalized or misread out of context", "parameter_id": "e9e12cd4-53da-4743-8917-a2868006ced2", "parameter_name": "Contested or Uncertain Aspects"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Bala Kanda 1.21 contains strong positive testimony from Vasistha about Vishvamitra.", "link_id": "5a50cb39-eca9-4a8b-902f-0ea86b1d1d80", "page_or_section": "1.21", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur Valmiki Ramayanam Project", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same Bala Kanda chapter is linked below; compare editions before using a quotation.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayanam, Bala Kanda, Sarga 21", "url": "https://www.valmiki.iitk.ac.in/summary?field_kanda_tid=1&field_sarga_value=21"}, "source_id": "0537c002-ff50-437a-88f6-1ca1f43572cf"}, {"evidence_excerpt": "Bala Kanda 1.21 contains strong positive testimony from Vasistha about Vishvamitra.", "link_id": "11cc1bde-9bea-4794-bfe7-7ebf6a600a55", "page_or_section": "1.21", "passages": [{"chunk_id": "16e8b4c0-c2b9-44bb-b4df-2f3f97395940", "confidence": 0.840689655172414, "excerpt": "\"All the missiles known to Vishvamitra are the highly righteous children of Krishaasva  Prajapati, where Prajapati-s were the earliest ruler of mankind, and god Shiva gave them to Vishvamitra  when was ruling kingdom. Those missiles are the sons of Daksha Prajaapati''s daughters and her husband  Krishaasva Prajapati, and they are disparate in their form, …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Valmiki Ramayana - Bala Kanda in \nProse Sarga 21", "relationship": "supports", "section_title": "Valmiki Ramayana - Bala Kanda in \nProse Sarga 21", "source_id": "9227358e-67a7-46f5-a873-bb5582ebb893", "textual_layer": "Ramayana — Bala Kanda"}, {"chunk_id": "eb13ef00-ba13-431c-9957-e70d915433bf", "confidence": 0.840689655172414, "excerpt": "The ire of sage Vishvamitra is shown at king Dasharatha. To pacify sage Vishvamitra,  sage Vashishta intervenes and convinces king Dasharatha to send Rama with sage Vishvamitra. While doing  so, sage Vashishta enumerates the capabilities of sage Vishvamitra, his knowledge of weaponry. Vashishta  also suggests that all those weapons will be given to Rama, if …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Valmiki Ramayana - Bala Kanda in \nProse Sarga 21", "relationship": "supports", "section_title": "Valmiki Ramayana - Bala Kanda in \nProse Sarga 21", "source_id": "9227358e-67a7-46f5-a873-bb5582ebb893", "textual_layer": "Ramayana — Bala Kanda"}], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution); English rendering by Desiraju Hanumanta Rao", "authority_metadata": {"verified_http_status": 200}, "citation": "Valmiki Ramayana, Bala Kanda 1.21, chapter-level prose rendering.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": "Publicly accessible chapter page; preserve source attribution and link.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayana — Bala Kanda, Sarga 21 (prose)", "url": "https://www.valmikiramayan.net/utf8/baala/sarga21/bala_21_prose.htm"}, "source_id": "9227358e-67a7-46f5-a873-bb5582ebb893"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('d8df62b0-a6ef-448b-b9d6-8ec7bbc73075','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "d8df62b0-a6ef-448b-b9d6-8ec7bbc73075", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "The Shunahshepa story requires careful treatment because it contains both refuge/protection and Vishvamitra''s harsh demand and curse toward his sons.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "deacfced-f020-44ef-94cd-27ff0c484505", "field_label": "Episodes commonly sensationalized or misread out of context", "parameter_id": "e9e12cd4-53da-4743-8917-a2868006ced2", "parameter_name": "Contested or Uncertain Aspects"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The same sarga presents the rescue effort and the curse against sons who refuse to substitute themselves.", "link_id": "a50ab2e3-6c57-4a57-a270-e636249c0e7b", "page_or_section": "1.62", "passages": [{"chunk_id": "01b9c2bc-82aa-4320-b659-3d37088c6c3b", "confidence": 0.872, "excerpt": "Vividly: ''A father''s ambition in begetting sons is to do something good and positive  to the society in the present world and when departed a right place is acquired  in heavens through these sons, by their yearly death-day rituals etc., and hence  you do some good in saving this boy from premature death and earn an apt place for  me in heavens...''  अयं …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Introduction", "relationship": "supports", "section_title": "Introduction", "source_id": "4bd01c3e-d436-4013-a8a9-49d839abe475", "textual_layer": "Ramayana — Bala Kanda"}, {"chunk_id": "72182ad9-a330-4762-8f24-13100a2975a7", "confidence": 0.872, "excerpt": "Vishvamitra will be nagged by almost all, including his sons, on this ''dog-meat-eating.''  There is a parable in Maha Bharata that Vishvamitra once tried to eat dog''s meat  when he did not get any food, but caught red-handedly. Later this has become the  curse-theme to Vishvamitra when he cursed Vashishta''s sons. At the present juncture  also he curses his …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Introduction", "relationship": "supports", "section_title": "Introduction", "source_id": "4bd01c3e-d436-4013-a8a9-49d839abe475", "textual_layer": "Ramayana — Bala Kanda"}], "relationship": "supports", "source": {"author": "Valmiki", "authority_metadata": {}, "citation": "Valmiki Ramayana, Bala Kanda, Sarga 62 (https://www.valmikiramayan.net/utf8/baala/sarga62/balasans62.htm)", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Valmiki Ramayana, Bala Kanda, Sarga 62", "url": "https://www.valmikiramayan.net/utf8/baala/sarga62/balasans62.htm"}, "source_id": "4bd01c3e-d436-4013-a8a9-49d839abe475"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('f353f24d-7ee7-4703-9c2c-c9db686d9d29','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "f353f24d-7ee7-4703-9c2c-c9db686d9d29", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "The later Galava-Madhavi sequence raises difficult questions about women''s agency, exchange, lineage, and guru-debt; any simplified moral judgment about Vishvamitra should remain under mentor review.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "METHODOLOGICAL", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source", "Recorded source access issue"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "deacfced-f020-44ef-94cd-27ff0c484505", "field_label": "Episodes commonly sensationalized or misread out of context", "parameter_id": "e9e12cd4-53da-4743-8917-a2868006ced2", "parameter_name": "Contested or Uncertain Aspects"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Madhavi becomes part of the strategy for satisfying the horse obligation and later bears Ashtaka to Vishvamitra.", "link_id": "e3024d6d-24c8-4b2c-9b58-f40eb9df1a18", "page_or_section": "Udyoga Parva Galava-Madhavi cycle", "passages": [], "relationship": "supports", "source": {"author": "Vyasa (traditional attribution); BORI Critical Edition", "authority_metadata": {}, "citation": "Mahabharata BORI, Udyoga Parva", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Bhandarkar Oriental Research Institute critical text / Vedapath presentation", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Mahabharata (BORI Critical Edition), Udyoga Parva", "url": "https://vedapath.app/en/mahabharata-bori/udyoga-parva"}, "source_id": "c3dbce9c-6c8c-4e2c-923b-c0394ecc916c"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('ff0e9fdc-4fa6-4eaf-9636-9292b0ae20e8','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "ff0e9fdc-4fa6-4eaf-9636-9292b0ae20e8", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "The Shabala conflict is better understood as a major turning point in the epic''s contrast between royal force and ascetic/brahmanical power than as an isolated magical-cow anecdote.", "current_status": "approved", "epistemics": {"contract_basis": "interpretation", "contract_satisfied": true, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "SCHOLARLY_INTERPRETATION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "deacfced-f020-44ef-94cd-27ff0c484505", "field_label": "Episodes commonly sensationalized or misread out of context", "parameter_id": "e9e12cd4-53da-4743-8917-a2868006ced2", "parameter_name": "Contested or Uncertain Aspects"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "", "link_id": "8fd5a1e5-f473-4682-a732-fb6787baab82", "page_or_section": "p. 57 (PDF page 17)", "passages": [{"chunk_id": "9d02c7d9-66e5-49c5-95b0-ee468f63dcd1", "confidence": 0.95, "excerpt": "57 duel between the sage and the king. Viśvāmitra’s utter defeat—including the death of his hundred sons incinerated by Vasiṣṭha himself—prompts the king to travel to the himālaya Mountains, perform tapas, and procure magic weapons from Śiva (Rām 1.54.12–18). Astras in hand, the king vengefully returns to Vasiṣṭha’s hermitage. In contrast to his earlier …", "excerpt_truncated": true, "is_active": true, "link_method": "manual_exact_passage", "page_or_section": "p. 57 (PDF page 17)", "relationship": "supports", "section_title": "Page 17", "source_id": "06fec486-e5af-4c7e-95db-afbb2e237c75", "textual_layer": "Modern academic interpretation of Mahabharata"}], "relationship": "supports", "source": {"author": "Adheesh Sathaye", "authority_metadata": {}, "citation": "Sathaye, Adheesh. “How to become a Brahman.” Acta Orientalia Vilnensia 8.1 (2007): 41–67. doi:10.15388/AOV.2007.1.3751.", "original_work_identity": {"doi": "10.15388/aov.2007.1.3751", "independentWorkKey": "10.15388/aov.2007.1.3751", "sourceFamily": "journals.vu.lt/acta-orientalia-vilnensia"}, "publication_year": 2007, "publisher_or_institution": "Acta Orientalia Vilnensia / Vilnius University Press", "rights_or_access_note": "Official journal diamond open access, CC BY 4.0: https://www.journals.vu.lt/acta-orientalia-vilnensia/journalpolicy", "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "How to become a Brahman: The construction of varṇa as social place in the Mahābhārata’s legends of Viśvāmitra", "url": "https://www.journals.vu.lt/acta-orientalia-vilnensia/article/download/3751/5207"}, "source_id": "06fec486-e5af-4c7e-95db-afbb2e237c75"}, {"evidence_excerpt": "The dispute escalates from royal acquisition to confrontation with Vasistha and precedes Vishvamitra''s intensified pursuit of ascetic power.", "link_id": "87643f8c-cf81-4f1e-a84b-3cbadaacc452", "page_or_section": "1.53-55", "passages": [{"chunk_id": "d875c0e7-aa4d-4c0c-bdc7-baa0d08e5529", "confidence": 0.841428571428571, "excerpt": "\"When honoured along with his advisers, ministers and attendants by way of receiving a royal banquet,  king Vishvamitra then in high admiration spoke this to Vashishta. [1-53-7]  पूजितो अहम् त्वया ब्रह्मन् पूज अर्हेण सुसत्कृतः |श्रूयताम् अभिधास्यामि वाक्यम् वाक्य विशारद || १-५३-८  8. brahman = oh, Brahman; puuja arheNa = for esteem, meetly [sage of your …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Introduction", "relationship": "supports", "section_title": "Introduction", "source_id": "b8f54a7f-3ef1-43eb-9749-48b122c27c56", "textual_layer": "Ramayana — Bala Kanda, Sarga 53"}], "relationship": "supports", "source": {"author": "Valmiki", "authority_metadata": {}, "citation": "Valmiki Ramayana, Bala Kanda, Sarga 53 (https://valmikiramayan.net/utf8/baala/sarga53/balasans53.htm.orig)", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Valmiki Ramayana, Bala Kanda, Sarga 53", "url": "https://valmikiramayan.net/utf8/baala/sarga53/balasans53.htm.orig"}, "source_id": "b8f54a7f-3ef1-43eb-9749-48b122c27c56"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('080d667d-799b-4a5c-8890-f74a929ae7ee','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "080d667d-799b-4a5c-8890-f74a929ae7ee", "claim_kind": "traditional_account", "claim_relations": [], "claim_text": "Supernatural Ramayana episodes and curses attributed to Vishvamitra should be labeled as scriptural/traditional accounts. The system should not present them as externally verified historical events or attempt to force a literal resolution.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "METHODOLOGICAL", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Recorded source access issue", "Claim-passage link points to a source absent from claim-source links"], "evidence_type": "traditional_narrative", "lens": {"field_id": "8d36194b-360a-499b-a5a1-e055ce8db12b", "field_label": "Mythologization vs. historical core, explicitly flagged rather than artificially resolved", "parameter_id": "e9e12cd4-53da-4743-8917-a2868006ced2", "parameter_name": "Contested or Uncertain Aspects"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The Rambha curse is explicitly part of the epic narrative.", "link_id": "ab2a8999-2660-4e36-9671-0ec2d32af832", "page_or_section": "Bala Kanda 1.64", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana, Bala Kanda 1.64. IIT Kanpur Valmiki Ramayanam.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same Bala Kanda chapter is linked below; compare editions before using a quotation.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayanam — Bala Kanda, Sarga 64", "url": "https://www.valmiki.iitk.ac.in/sloka?field_kanda_tid=1&field_sarga_value=64&language=dv"}, "source_id": "84367293-66be-4b9a-8bd2-ac2ca21fa68d"}], "unmatched_passage_links": [{"chunk_id": "515003fb-3676-4dbd-8abb-a58e725319ce", "excerpt": "Whereof you tried to entice me who am wishing to win over the wanton and wroth, you unlucky female  Rambha, thereof you will become a rocklike statued wastrel. [1-64-12]  ब्राह्मणः सुमहातेजास्तपोबलसमन्वितः |उद्धरिष्यति रंभे त्वां मत्क्रोधकलुषीकृताम् || १-६४-१३  13. rambhe = oh Rambha; sumahaatejaaH = very high resplendent one;  tapobalasamanvitaH = having …", "excerpt_truncated": true, "page_or_section": "Introduction", "relationship": "context", "source": {"author": "Valmiki", "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "title": "Valmiki Ramayana, Bala Kanda, Sarga 64", "url": "https://www.valmikiramayan.net/utf8/baala/sarga64/balasans64.htm"}, "source_id": "8d1e7888-6577-4564-b935-96ed0ae1b902"}]}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('1c0f0a3c-38e8-4ff7-99e6-08f1a6dfb7dc','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "1c0f0a3c-38e8-4ff7-99e6-08f1a6dfb7dc", "claim_kind": "traditional_account", "claim_relations": [], "claim_text": "The thousand-year durations assigned to multiple tapas cycles in Bala Kanda are features of epic sacred narrative and should be quoted as the text''s chronology rather than silently converted into literal modern historical duration.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Recorded source access issue"], "evidence_type": "traditional_narrative", "lens": {"field_id": "8d36194b-360a-499b-a5a1-e055ce8db12b", "field_label": "Mythologization vs. historical core, explicitly flagged rather than artificially resolved", "parameter_id": "e9e12cd4-53da-4743-8917-a2868006ced2", "parameter_name": "Contested or Uncertain Aspects"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Bala Kanda repeatedly measures Vishvamitra''s penance in thousand-year spans.", "link_id": "f5bbde38-bfc4-48d8-9b87-0c9d1de3325d", "page_or_section": "1.63-65", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana, Bala Kanda 1.63. IIT Kanpur Valmiki Ramayanam.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same Bala Kanda chapter is linked below; compare editions before using a quotation.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayanam — Bala Kanda, Sarga 63", "url": "https://www.valmiki.iitk.ac.in/sloka?field_kanda_tid=1&field_sarga_value=63&language=dv"}, "source_id": "2025af50-f65e-4a13-b670-adc6a2a0e3dc"}, {"evidence_excerpt": "Bala Kanda repeatedly measures Vishvamitra''s penance in thousand-year spans.", "link_id": "8162c8f6-be74-4c3c-8905-d2fb6bfd8b6c", "page_or_section": "1.63-65", "passages": [{"chunk_id": "1c601c57-75d6-404c-868e-11361f2be7ee", "confidence": 0.868571428571429, "excerpt": "\" ''All this is the mischief of gods to defraud me of the great merit of my ascesis.  Ten years have rolled by as if they are just a day and a night. Furthermore, I who  am under the influence of lust and lure had to encounter this hindrance in my ascesis.''  Oh, Rama, that best saint suspired heavily when he became emotional with reparation.  But on seeing …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Book I : Bala Kanda - The Youthful Majesties\niSarga 63 n Prose", "relationship": "supports", "section_title": "Book I : Bala Kanda - The Youthful Majesties\niSarga 63 n Prose", "source_id": "d39ddd21-67b7-4c7c-bfae-ea1f99918420", "textual_layer": "Ramayana — Bala Kanda"}, {"chunk_id": "9c862712-4d53-404e-a5bb-1c24e1296451", "confidence": 0.841428571428571, "excerpt": "On Vishvamitra''s performing severe ascesis Brahma accords the sageship   of ''Great-sage'' to him, whereas Vishvamitra''s ambition is to acquire   the sageship of a ''Brahma-sage'' Absolute-sageship. In the meanwhile,   the celestial wench Menaka arrives at that place and Vishvamitra is   enticed by her beauty and spends some years with her. Later, on realising  …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Book I : Bala Kanda - The Youthful Majesties\niSarga 63 n Prose", "relationship": "supports", "section_title": "Book I : Bala Kanda - The Youthful Majesties\niSarga 63 n Prose", "source_id": "d39ddd21-67b7-4c7c-bfae-ea1f99918420", "textual_layer": "Ramayana — Bala Kanda"}], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution); English rendering by Desiraju Hanumanta Rao", "authority_metadata": {"verified_http_status": 200}, "citation": "Valmiki Ramayana, Bala Kanda 1.63, chapter-level prose rendering.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": "Publicly accessible chapter page; preserve source attribution and link.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayana — Bala Kanda, Sarga 63 (prose)", "url": "https://www.valmikiramayan.net/utf8/baala/sarga63/bala_63_prose.htm"}, "source_id": "d39ddd21-67b7-4c7c-bfae-ea1f99918420"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('21eef295-6488-45ca-b86e-fc5ae5e7c25d','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "21eef295-6488-45ca-b86e-fc5ae5e7c25d", "claim_kind": "traditional_account", "claim_relations": [], "claim_text": "The Brahmarshi transformation is securely a fact about the Ramayana narrative even when questions about the historical individual remain open.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "CONTESTED", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "traditional_narrative", "lens": {"field_id": "8d36194b-360a-499b-a5a1-e055ce8db12b", "field_label": "Mythologization vs. historical core, explicitly flagged rather than artificially resolved", "parameter_id": "e9e12cd4-53da-4743-8917-a2868006ced2", "parameter_name": "Contested or Uncertain Aspects"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The text explicitly narrates Vasistha''s recognition; this supports a textual claim without proving external biography.", "link_id": "566e9326-ec6a-4d85-a884-b1e5a1c6b62e", "page_or_section": "1.65.26-27", "passages": [{"chunk_id": "d5e6cd91-c377-43d8-a3aa-a6233c8d0a82", "confidence": 0.55, "excerpt": "This meal is prepared by Vishvamitra alone after a thousand years and such self-cooking  of food by the ascetics is called, vaishva devam, since it is a sacred  preparation anena vaishvadeva ante samaagato atithiH svayam upoShyaa api sviiya anna pradaanena  sambhojya iti suucitam - dk  तस्मैः दत्त्वा तदा सिद्धम् सर्वम् विप्राय निश्चितः | निःषेषिते अन्ने …", "excerpt_truncated": true, "is_active": true, "link_method": "citation_partial", "page_or_section": "Introduction", "relationship": "context", "section_title": "Introduction", "source_id": "b1ff445c-d9d0-4f8e-a28f-f3a8053787ad", "textual_layer": "Ramayana — Bala Kanda"}, {"chunk_id": "ef5de7fd-af8f-4eaa-9685-ac9b0a43aa7d", "confidence": 0.75, "excerpt": "Vishvamitra becomes Brahma-sage after a prolonged ascesis that made all the worlds  to startle. All gods request Brahma to accord the supreme Brahma-sageship on Vishvamitra  as he is cleansed of all mortal impurities, and Brahma accords that highest order  on him. Thus Sage Shataananda concludes his narration about the legend of Vishvamitra.  अथ हैमवतीम् …", "excerpt_truncated": true, "is_active": true, "link_method": "adaptive_strong", "page_or_section": "Introduction", "relationship": "context", "section_title": "Introduction", "source_id": "b1ff445c-d9d0-4f8e-a28f-f3a8053787ad", "textual_layer": "Ramayana — Bala Kanda"}], "relationship": "supports", "source": {"author": "Valmiki", "authority_metadata": {}, "citation": "Valmiki Ramayana, Bala Kanda, Sarga 65 (https://www.valmikiramayan.net/utf8/baala/sarga65/balasans65.htm.orig)", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Valmiki Ramayana, Bala Kanda, Sarga 65", "url": "https://www.valmikiramayan.net/utf8/baala/sarga65/balasans65.htm.orig"}, "source_id": "b1ff445c-d9d0-4f8e-a28f-f3a8053787ad"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
