insert into original_claims values ('8583457f-521b-461d-b3c9-78c236ac82e4','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "8583457f-521b-461d-b3c9-78c236ac82e4", "claim_kind": "traditional_account", "claim_relations": [], "claim_text": "The Mahabharata Shakuntala tradition establishes a literary genealogy from Vishvamitra through Shakuntala to Bharata; whether and how that genealogy maps onto historical persons is a separate question the text itself does not resolve.", "current_status": "approved", "epistemics": {"contract_basis": "interpretation", "contract_satisfied": true, "contract_status": "CONTESTED_REPRESENTED", "epistemic_type": "CONTESTED", "proposed_type": "CONTESTED", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source", "Recorded source access issue"], "evidence_type": "traditional_narrative", "lens": {"field_id": "8d36194b-360a-499b-a5a1-e055ce8db12b", "field_label": "Mythologization vs. historical core, explicitly flagged rather than artificially resolved", "parameter_id": "e9e12cd4-53da-4743-8917-a2868006ced2", "parameter_name": "Contested or Uncertain Aspects"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Adi Parva genealogical recitation identifies Shakuntala as Vishvamitra''s daughter and Bharata as her son.", "link_id": "b4fc342a-2bc5-4a7a-a9a1-5ff8ff028f3b", "page_or_section": "1.90.30", "passages": [{"chunk_id": "8277035d-74ce-48b1-993e-17952dd165df", "confidence": 0.845, "excerpt": "जनमेजय उवाच । श्रुतस्त्वत्तो मया विप्र पूर्वेषां संभवो महान् । उदाराश्चापि वंशेऽस्मिन्राजानो मे परिश्रुताः  Janamejaya said: “O brāhmaṇa, I have heard from you the great origins of the ancients; and I have also heard that in this lineage there were noble kings.”  किं तु लघ्वर्थसंयुक्तं प्रियाख्यानं न मामति । प्रीणात्यतो भवान्भूयो विस्तरेण ब्रवीतु मे  …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Shlokas", "relationship": "supports", "section_title": "Shlokas", "source_id": "976f33cf-1de6-4118-b64f-c07b7a358389", "textual_layer": "Mahabharata tradition"}, {"chunk_id": "c93b8ceb-826c-4dc9-b6cc-adb66be98503", "confidence": 0.901666666666667, "excerpt": "Ādi Parva, Adhyāya 90 — Pūror Vaṃśa, Kuru-Pravara, and the Janamejaya Line (Genealogical Recitation)  Upa-parva: Anuvaṃśa (Pūru–Kuru Vaṃśānukīrtana) — Dynastic Genealogy and Legitimacy Discourse  This chapter begins with Janamejaya asking for a fuller account of his ancestors, saying that a condensed telling does not satisfy his longing for the sacred …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Adhyaya 90", "relationship": "supports", "section_title": "Adhyaya 90", "source_id": "976f33cf-1de6-4118-b64f-c07b7a358389", "textual_layer": "Mahabharata tradition"}], "relationship": "supports", "source": {"author": "Vyasa (traditional attribution); BORI Critical Edition", "authority_metadata": {}, "citation": "Mahabharata BORI, Adi Parva, 90", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Bhandarkar Oriental Research Institute critical text / Vedapath presentation", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Mahabharata (BORI Critical Edition), Adi Parva, Adhyaya 90", "url": "https://vedapath.app/en/mahabharata-bori/adi-parva/90"}, "source_id": "976f33cf-1de6-4118-b64f-c07b7a358389"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('97f0b346-8b02-4297-8b71-5765954446f0','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "97f0b346-8b02-4297-8b71-5765954446f0", "claim_kind": "traditional_account", "claim_relations": [], "claim_text": "The exceptional bodily benefits attributed to Bala and Atibala belong to Vishvamitra''s speech within the epic and should be represented as traditional claims, not experimentally verified effects.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Recorded source access issue", "Claim-passage link points to a source absent from claim-source links"], "evidence_type": "traditional_narrative", "lens": {"field_id": "8d36194b-360a-499b-a5a1-e055ce8db12b", "field_label": "Mythologization vs. historical core, explicitly flagged rather than artificially resolved", "parameter_id": "e9e12cd4-53da-4743-8917-a2868006ced2", "parameter_name": "Contested or Uncertain Aspects"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The teaching passage attributes freedom from fatigue, hunger, thirst, and vulnerability to the disciplines.", "link_id": "49a4e362-627d-403e-b74e-6895613f028c", "page_or_section": "1.22", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur Valmiki Ramayanam Project", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same Bala Kanda chapter is linked below; compare editions before using a quotation.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayanam, Bala Kanda, Sarga 22", "url": "https://www.valmiki.iitk.ac.in/summary?field_kanda_tid=1&field_sarga_value=22"}, "source_id": "9898fcd7-2c32-429e-aba6-4e662d2214cd"}], "unmatched_passage_links": [{"chunk_id": "271446df-1b16-4af1-b22d-f06365591e27", "excerpt": "गृहाण वत्स सलिलं मा भूत् कालस्य पर्ययः || १-२२-११  मंत्रग्रामं गृहाण त्वं बलामतिबलां तथा |  11b, 12a. vatsa salilam gR^ihaaNa = my boy, you take water; tvam   tathaa = you, like that; mantragraamam = group of hymns; balaam   atibalaam = bala, atibala hymns; gR^ihaaNa = receive; kaalasya   paryayaH maa bhuut = not let there be time''s lapse.  \" \"Take water, …", "excerpt_truncated": true, "page_or_section": "Introduction", "relationship": "context", "source": {"author": "Valmiki", "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "title": "Valmiki Ramayana, Bala Kanda, Sarga 22", "url": "https://www.valmikiramayan.net/utf8/baala/sarga22/balasans22.htm"}, "source_id": "4772171e-b53b-4ae5-9ffa-e6edf7a8f9de"}, {"chunk_id": "3953cd95-3cdf-4535-8e2d-1cc370c49c78", "excerpt": "The meaning of As''vins from as''va a horse, Persian asp, Greek  ιππος Latin equus, Welsh *eck, is   Horsemen. They were twin deities of whom frequent mention is made in the Vedas   and the Indian myths. The As''vins have much in common with the Dioscuri of Greece,   and their mythical genealogy seems to indicate that their origin was astronomical.   They …", "excerpt_truncated": true, "page_or_section": "Introduction", "relationship": "context", "source": {"author": "Valmiki", "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "title": "Valmiki Ramayana, Bala Kanda, Sarga 22", "url": "https://www.valmikiramayan.net/utf8/baala/sarga22/balasans22.htm"}, "source_id": "4772171e-b53b-4ae5-9ffa-e6edf7a8f9de"}]}'::jsonb,'approved','system_test_bulk');
