insert into original_claims values ('5909bf8a-b6ac-425f-b74c-a9df3fe197de','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "5909bf8a-b6ac-425f-b74c-a9df3fe197de", "claim_kind": "established_fact", "claim_relations": [], "claim_text": "The intermediate Maharshi title in Bala Kanda 1.63 should be reviewed alongside the earlier Rajarshi and later Brahmarshi labels so the profile represents a sequence rather than treating all honorifics as simultaneous equivalents.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "SYNTHETIC_INTERPRETATION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Recorded source access issue"], "evidence_type": "uncertain", "lens": {"field_id": "73a82542-244d-4f88-a213-2e1e66d2416b", "field_label": "Sensitive / contested material requiring mentor review", "parameter_id": "e9e12cd4-53da-4743-8917-a2868006ced2", "parameter_name": "Contested or Uncertain Aspects"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The chapter explicitly places Maharshi recognition within an unfinished progression.", "link_id": "36217928-3e15-4f73-ab63-2761c3b17b15", "page_or_section": "1.63", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana, Bala Kanda 1.63. IIT Kanpur Valmiki Ramayanam.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation o