insert into original_claims values ('5e436375-781c-4b07-baa2-4bafcd5230a3','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "5e436375-781c-4b07-baa2-4bafcd5230a3", "claim_kind": "established_fact", "claim_relations": [], "claim_text": "The Mahabharata Shakuntala genealogy should be approved as ''Mahabharata tradition'' separately from claims about the Rigvedic seer, because identifying the father of Shakuntala with the same historical individual is an additional harmonizing step.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "HISTORICAL_FACT", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source", "Recorded source access issue"], "evidence_type": "uncertain", "lens": {"field_id": "73a82542-244d-4f88-a213-2e1e66d2416b", "field_label": "Sensitive / contested material requiring mentor review", "parameter_id": "e9e12cd4-53da-4743-8917-a2868006ced2", "parameter_name": "Contested or Uncertain Aspects"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The epic explicitly gives the genealogy; historical identity across corpora remains unresolved.", "link_id": "b4e1aa40-f2cc-47f4-aea1-cee5a3a951eb", "page_or_section": "Identity review flag", "passages": [{"chunk_id": "2ad0891e-0801-48ee-9214-f551339926d0", "confidence": 0.843076923076923, "excerpt": "The central dilemma is dynastic preservation versus normative constraints: when succession fails (Vicitravīrya dies heirless), the tradition authorizes exceptional mechanisms (Vyāsa’s niyoga) to sustain political order and lineage legitimacy.  Genealogy is presented as ethical infrastructure: individual actions (vows, restraint, ritual duty, or impulsive …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Frequently Asked Questions", "relationship": "supports", "section_title": "Frequently Asked Questions", "source_id": "976f33cf-1de6-4118-b64f-c07b7a358389", "textual_layer": "Mahabharata tradition"}], "relationship": "supports", "source": {"author": "Vyasa (traditional attribution); BORI Critical Edition", "authority_metadata": {}, "citation": "Mahabharata BORI, Adi Parva, 90", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Bhandarkar Oriental Research Institute critical text / Vedapath presentation", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Mahabharata (BORI Critical Edition), Adi Parva, Adhyaya 90", "url": "https://vedapath.app/en/mahabharata-bori/adi-parva/90"}, "source_id": "976f33cf-1de6-4118-b64f-c07b7a358389"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
