insert into original_claims values ('c88ab442-bb3c-4c39-b1d6-a910eda7a43b','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "c88ab442-bb3c-4c39-b1d6-a910eda7a43b", "claim_kind": "established_fact", "claim_relations": [], "claim_text": "DCF’s Rishi framework requires mythologized, contested, or easily sensationalized material to remain flagged until mentor sign-off; such claims should never become approved automatically.", "current_status": "needs_review", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "CONTESTED", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Missing assigned epistemic classification", "Associated source is not approved", "Associated source URL missing", "Recorded source access issue"], "evidence_type": "uncertain", "lens": {"field_id": "73a82542-244d-4f88-a213-2e1e66d2416b", "field_label": "Sensitive / contested material requiring mentor review", "parameter_id": "e9e12cd4-53da-4743-8917-a2868006ced2", "parameter_name": "Contested or Uncertain Aspects"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The supplied framework explicitly requires mentor sign-off.", "link_id": "2fbf17bb-5b1e-4eb2-837e-9d874a5e8243", "page_or_section": "Parameter 9: Contested or Uncertain Aspects", "passages": [{"chunk_id": "f91d4d5c-060d-46fe-9d3e-b84b57aff719", "confidence": 0.99, "excerpt": "DCF Parameters to Study Rishis  Vocation and role within the Rishi tradition includes the type of rishi and the primary function as drashta, guru, darshana founder, smriti author, or ashram head.  Textual contribution includes mantras and suktas revealed with Veda and mandala references, associat