insert into original_claims values ('497ecd3e-909d-4d46-a2a9-91f3c20a0927','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "497ecd3e-909d-4d46-a2a9-91f3c20a0927", "claim_kind": "uncertain", "claim_relations": [], "claim_text": "The database should not assign one simple historical date to all Vishvamitra traditions because the Rigvedic hymns and the Ramayana biography belong to different textual corpora and layers.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "SYNTHETIC_INTERPRETATION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "uncertain", "lens": {"field_id": "c688c3f6-83fa-4790-9651-6dfb02e3e21b", "field_label": "Approximate era / yuga placement and caveats around dating", "parameter_id": "a0fd0f1a-762f-410b-874a-1c9f5476abf6", "parameter_name": "Historical and Textual Context"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The earliest evidence used here is Rigvedic, whereas the detailed biography comes from the epic Bala Kanda.", "link_id": "3c3b2d53-b66a-4f5c-a39c-0cf4c4a884ce", "page_or_section": "Textual-layer caution", "passages": [{"chunk_id": "4a6201da-d8d2-4984-83c0-9ab33f9820c5", "confidence": 0.843076923076923, "excerpt": "The Rigveda is the oldest compilation of human wisdom. This Samhita (Collection) is unique in its nature. In fact, it is not a book, but a compilation composed of several books which can be individually distinguished from each other. The present from of this Samhita clearly indic