insert into original_claims values ('53373b04-b4b1-4b5a-b0bd-92ea0077a0ef','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "53373b04-b4b1-4b5a-b0bd-92ea0077a0ef", "claim_kind": "uncertain", "claim_relations": [], "claim_text": "The Vedic Heritage Portal dates the Aitareya Brahmana itself broadly between 1000 and 500 BCE; this is a date range for the text, not a secure lifespan for Vishvamitra.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "PARTIALLY_SUPPORTED", "epistemic_type": "HISTORICAL_FACT", "proposed_type": "HISTORICAL_FACT", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "uncertain", "lens": {"field_id": "c688c3f6-83fa-4790-9651-6dfb02e3e21b", "field_label": "Approximate era / yuga placement and caveats around dating", "parameter_id": "a0fd0f1a-762f-410b-874a-1c9f5476abf6", "parameter_name": "Historical and Textual Context"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The portal provides the broad dating range while describing the Aitareya Brahmana''s structure and attribution.", "link_id": "cb017976-8594-45eb-9600-712fda25b8bb", "page_or_section": "Aitareya Brahmana overview", "passages": [{"chunk_id": "3e6fdfef-5922-45e7-bc56-c8468dac2c19", "confidence": 0.846086956521739, "excerpt": "Aitareya Brahmana belongs to Shakala Shakha of the Rigveda. This work is ascribed to Mahidasa Aitareya and dated variously from 1000 BCE to 500 BCE. It is divided into eight Panchikas and each of the Panchika is divided into eight adhyayas. Totally, it consist forty adhyayas.  The first six panchikas of Aitareya Brahmana dealing with