insert into original_claims values ('948f90bd-4f53-42e7-8c19-190892b0918d','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "948f90bd-4f53-42e7-8c19-190892b0918d", "claim_kind": "uncertain", "claim_relations": [], "claim_text": "The numerical spans of thousands of years assigned to tapas in Bala Kanda function inside epic sacred chronology and should not be converted directly into modern chronological dates.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": null, "contract_status": "NOT_EVIDENTIARY", "epistemic_type": "METHODOLOGICAL", "proposed_type": "METHODOLOGICAL", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["Current approval origin does not establish strict verification", "Recorded source access issue"], "evidence_type": "uncertain", "lens": {"field_id": "c688c3f6-83fa-4790-9651-6dfb02e3e21b", "field_label": "Approximate era / yuga placement and caveats around dating", "parameter_id": "a0fd0f1a-762f-410b-874a-1c9f5476abf6", "parameter_name": "Historical and Textual Context"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The final tapas cycle uses thousand-year durations as part of its ascetic narrative.", "link_id": "caf16ec7-b0cd-47f6-ae1e-e6512363db98", "page_or_section": "1.63-65", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur Valmiki Ramayanam Project", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same Bala Kanda chapter is linked below; compare editions before using a quotation.", "source_status": "approved",