insert into original_claims values ('a67b288b-5a52-4cca-bf8b-9b4f6c2b3101','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "a67b288b-5a52-4cca-bf8b-9b4f6c2b3101", "claim_kind": "uncertain", "claim_relations": [], "claim_text": "For a source-grounded profile, the safest placement is by textual layer: Vishvamitra/family appears in Rigvedic material, while Kausika/Vishvamitra receives an extended biography in the Ramayana tradition. The selected sources do not justify one absolute historical date.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "uncertain", "lens": {"field_id": "c688c3f6-83fa-4790-9651-6dfb02e3e21b", "field_label": "Approximate era / yuga placement and caveats around dating", "parameter_id": "a0fd0f1a-762f-410b-874a-1c9f5476abf6", "parameter_name": "Historical and Textual Context"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The Vedic layer is certain; absolute dating/identity equivalence is not resolved here.", "link_id": "05b3d5ee-5fa8-4d66-80d4-7a16ac8f2bc8", "page_or_section": "Rigveda Mandala 3 overview", "passages": [], "relationship": "supports", "source": {"author": null, "authority_metadata": {}, "citation": "Vedic Heritage Portal, Rigveda, Shakala Samhita, Mandala overview.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Indira Gandhi National Centre for the Arts (IGNCA), Ministry of Culture, Government of India", "rights_or_access_note": null, "source_status": "approved", "source_type": "institutional", "storage_path": null, "title": "Vedic Heritage Portal — Rigveda Shakala Samhita", "url": "https://vedicheritage.gov.in/samhitas/rigveda/shakala-samhita/"}, "source_id": "210ff1a8-35b1-4ce1-9441-95fcc36d4247"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('ac72a43b-7713-4faf-a3fb-395a26137752','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "ac72a43b-7713-4faf-a3fb-395a26137752", "claim_kind": "uncertain", "claim_relations": [], "claim_text": "The Arsheya Upanishad is explicitly described by the Vedic Heritage Portal as a comparatively later Vedantic Upanishad, so its Vishvamitra material must not be projected backward into the Rigvedic period.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "SYNTHETIC_INTERPRETATION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "uncertain", "lens": {"field_id": "c688c3f6-83fa-4790-9651-6dfb02e3e21b", "field_label": "Approximate era / yuga placement and caveats around dating", "parameter_id": "a0fd0f1a-762f-410b-874a-1c9f5476abf6", "parameter_name": "Historical and Textual Context"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The portal distinguishes it from principal/older Upanishads and calls it a later Vedantic text.", "link_id": "059c13d9-a5a3-4a37-b22a-8cd60b690cdf", "page_or_section": "Arsheya Upanishad overview", "passages": [{"chunk_id": "2d2aac38-e6ad-4b85-b8a5-5c566247b921", "confidence": 0.901666666666667, "excerpt": "Ārṣeya Upaniṣad is not considered as a principal Upaniṣad of Vedic Literature but it is recognised as a significant Upaniṣad among the ‘Vedānta-Upanis̩ads’ of comparatively later times. Later Upaniṣads were developed to propound the concepts of certain famous schools, such as Yoga, Vedānta, Śākta, Vaiṣṇava and Śaiva.  ĀrṣeyaUpaniṣad is a …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Arsheyopanishad", "relationship": "supports", "section_title": "Arsheyopanishad", "source_id": "f76efd31-3f90-4b32-b386-99e3cce78d6a", "textual_layer": "Traditional or scholarly source"}], "relationship": "supports", "source": {"author": "Traditional text", "authority_metadata": {}, "citation": "Arsheya Upanishad", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Vedic Heritage Portal / IGNCA / Ministry of Culture, Government of India", "rights_or_access_note": null, "source_status": "approved", "source_type": "institutional", "storage_path": null, "title": "Arsheya Upanishad", "url": "https://vedicheritage.gov.in/upanishads/aarsheyopanishad/"}, "source_id": "f76efd31-3f90-4b32-b386-99e3cce78d6a"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('b17375a8-1e95-471c-9f56-31798dd6fbc8','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "b17375a8-1e95-471c-9f56-31798dd6fbc8", "claim_kind": "uncertain", "claim_relations": [], "claim_text": "Mahabharata references to Vishvamitra belong to epic textual traditions and cannot by themselves date the Rigvedic seer; the database should retain source-level chronology rather than a single person-level date.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "PARTIALLY_SUPPORTED", "epistemic_type": "SYNTHETIC_INTERPRETATION", "proposed_type": "SYNTHETIC_INTERPRETATION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source", "Recorded source access issue", "Claim-passage link points to a source absent from claim-source links"], "evidence_type": "uncertain", "lens": {"field_id": "c688c3f6-83fa-4790-9651-6dfb02e3e21b", "field_label": "Approximate era / yuga placement and caveats around dating", "parameter_id": "a0fd0f1a-762f-410b-874a-1c9f5476abf6", "parameter_name": "Historical and Textual Context"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The genealogical and narrative material occurs in the Mahabharata, a different corpus from Mandala 3.", "link_id": "2fedd4da-f663-46bd-97df-dc7699f48c66", "page_or_section": "Methodological note", "passages": [], "relationship": "supports", "source": {"author": "Vyasa (traditional attribution); BORI Critical Edition", "authority_metadata": {}, "citation": "Mahabharata BORI, Adi Parva, 90", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Bhandarkar Oriental Research Institute critical text / Vedapath presentation", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Mahabharata (BORI Critical Edition), Adi Parva, Adhyaya 90", "url": "https://vedapath.app/en/mahabharata-bori/adi-parva/90"}, "source_id": "976f33cf-1de6-4118-b64f-c07b7a358389"}], "unmatched_passage_links": [{"chunk_id": "8dbe50f7-cb3d-41f7-b786-90e9bb723ac9", "excerpt": "48 the text of the Mahābhārata, i suggest, may be more productively regarded as ‘performances’ within the confines of textual space. Such a reading enables the historical analysis of the epic without becoming mired in the interminable and largely unanswerable questions of its textual development.27 if, as the prevailing, ‘analytic’ opinion holds, the epic …", "excerpt_truncated": true, "page_or_section": "p. 48 (PDF page 8)", "relationship": "context", "source": {"author": "Adheesh Sathaye", "publication_year": 2007, "publisher_or_institution": "Acta Orientalia Vilnensia / Vilnius University Press", "rights_or_access_note": "Official journal diamond open access, CC BY 4.0: https://www.journals.vu.lt/acta-orientalia-vilnensia/journalpolicy", "source_status": "approved", "source_type": "scholarly_article", "title": "How to become a Brahman: The construction of varṇa as social place in the Mahābhārata’s legends of Viśvāmitra", "url": "https://www.journals.vu.lt/acta-orientalia-vilnensia/article/download/3751/5207"}, "source_id": "06fec486-e5af-4c7e-95db-afbb2e237c75"}]}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('deebd153-c2ff-4d14-80f2-5772e8f6f442','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "deebd153-c2ff-4d14-80f2-5772e8f6f442", "claim_kind": "uncertain", "claim_relations": [], "claim_text": "Traditional yuga placement belongs to religious chronology, while modern historical dating of texts is a separate scholarly question; the two should not be collapsed into one date field.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "SYNTHETIC_INTERPRETATION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "uncertain", "lens": {"field_id": "c688c3f6-83fa-4790-9651-6dfb02e3e21b", "field_label": "Approximate era / yuga placement and caveats around dating", "parameter_id": "a0fd0f1a-762f-410b-874a-1c9f5476abf6", "parameter_name": "Historical and Textual Context"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The Ramayana source itself discusses textual layering questions, illustrating why textual and traditional chronology should be distinguished.", "link_id": "91d20d2c-04d2-42b0-b747-2466c0897fa5", "page_or_section": "Methodological note", "passages": [], "relationship": "supports", "source": {"author": "Valmiki Ramayana project", "authority_metadata": {}, "citation": "Valmiki Ramayana: Textual Introduction (https://www.valmikiramayan.net/utf8/ramayana.shtml)", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Valmiki Ramayana: Textual Introduction", "url": "https://www.valmikiramayan.net/utf8/ramayana.shtml"}, "source_id": "dfa79e19-c93e-49ae-868b-766f5860b699"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('10da6d9d-b836-4af4-b5f9-d5decb67c5a7','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "10da6d9d-b836-4af4-b5f9-d5decb67c5a7", "claim_kind": "uncertain", "claim_relations": [], "claim_text": "RV 3.36 changes seer attribution at verse level: most verses are attributed to Gathina Vishvamitra while verse 10 is assigned to Ghora Angirasa.", "current_status": "approved", "epistemics": {"contract_basis": "text", "contract_satisfied": true, "contract_status": "SUPPORTED", "epistemic_type": "TEXTUAL_ASSERTION", "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "uncertain", "lens": {"field_id": "2ae95e47-4c23-4773-b5bb-e44806c2c9ac", "field_label": "Distinguish possibly multiple figures sharing the same name", "parameter_id": "a0fd0f1a-762f-410b-874a-1c9f5476abf6", "parameter_name": "Historical and Textual Context"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The metadata explicitly differentiates verse 10 from the rest of the hymn.", "link_id": "bf75405b-af51-4802-8e2a-622703522950", "page_or_section": "RV 3.36", "passages": [{"chunk_id": "5693903c-9b91-4bad-b29f-46e648918520", "confidence": 0.74, "excerpt": "Hindi Translation by Pt. Sripada Damodara Satavalekar  English Translation by H.H. Wilson  Commentary of Sayanacharya", "excerpt_truncated": false, "is_active": true, "link_method": "single_chunk_curated_source", "page_or_section": "Links", "relationship": "supports", "section_title": "Links", "source_id": "2b92511c-e116-465c-9613-3297866ef4dd", "textual_layer": "Rigveda — Mandala 3"}], "relationship": "supports", "source": {"au