insert into original_claims values ('f2af0330-153c-46fe-9b1f-f33567119996','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "f2af0330-153c-46fe-9b1f-f33567119996", "claim_kind": "uncertain", "claim_relations": [], "claim_text": "The multiple-Vishvamitra hypothesis is useful primarily as a warning against automatic harmonization: it should not be converted into a fixed count of historical individuals without stronger independent evidence.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": null, "contract_status": "NOT_EVIDENTIARY", "epistemic_type": "METHODOLOGICAL", "proposed_type": "METHODOLOGICAL", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source", "Recorded source access issue"], "evidence_type": "uncertain", "lens": {"field_id": "2ae95e47-4c23-4773-b5bb-e44806c2c9ac", "field_label": "Distinguish possibly multiple figures sharing the same name", "parameter_id": "a0fd0f1a-762f-410b-874a-1c9f5476abf6", "parameter_name": "Historical and Textual Context"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The argument is reconstructive and should remain tagged as a scholarly hypothesis.", "link_id": "c0610849-8c9f-42f7-a96b-c1befb804169", "page_or_section": "Methodological caution", "passages": [], "relationship": "supports", "source": {"author": "", "authority_metadata": {}, "citation": "Traditional History discussion of Vishvamitra chronology", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IGNCA Digital Library, Government of India", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Traditional History from the Earliest Time", "url": "https://ignca.gov.in/Asi_data/73904.pdf"}, "source_id": "4f6eef53-13c9-4c33-8135-d9acea0795be"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('ff6282b8-a153-4b9d-b9dd-d944839042ff','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "ff6282b8-a153-4b9d-b9dd-d944839042ff", "claim_kind": "uncertain", "claim_relations": [], "claim_text": "The database should separately track ''Gathina Vishvamitra,'' named Vaishvamitra descendants/seers, the epic King-Kausika Vishvamitra, and later figures invoked under the same name, while allowing mentors to decide where identities may overlap.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "uncertain", "lens": {"field_id": "2ae95e47-4c23-4773-b5bb-e44806c2c9ac", "field_label": "Distinguish possibly multiple figures sharing the same name", "parameter_id": "a0fd0f1a-762f-410b-874a-1c9f5476abf6", "parameter_name": "Historical and Textual Context"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The Mandala attribution pattern itself demonstrates why finer-grained identity fields are necessary.", "link_id": "7d1d9649-2b57-4734-a593-fa65550394c1", "page_or_section": "Identity-resolution recommendation", "passages": [{"chunk_id": "eee5715c-a576-45d8-89da-c841232e4f80", "confidence": 0.74, "excerpt": "Hindi Translation by Pt. Sripada Damodara Satavalekar  English Translation by H.H. Wilson  Commentary of Sayanacharya", "excerpt_truncated": false, "is_active": true, "link_method": "single_chunk_curated_source", "page_or_section": "Links