insert into original_claims values ('06cc6120-9874-4c1c-bb42-3817f4ea1eb3','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "06cc6120-9874-4c1c-bb42-3817f4ea1eb3", "claim_kind": "established_fact", "claim_relations": [], "claim_text": "Within Mandala 3, shifts from Gathina Vishvamitra to Rishabha Vaishvamitra, Kata Vaishvamitra, Gathi Kaushika, and Bharata seers demonstrate internal layering or family diversity that a single-author label obscures.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "uncertain", "lens": {"field_id": "4cf7f8c5-2b71-46e7-9bd0-0a03bb01410d", "field_label": "Textual layers where the Rishi appears", "parameter_id": "a0fd0f1a-762f-410b-874a-1c9f5476abf6", "parameter_name": "Historical and Textual Context"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The hymn-by-hymn attribution list differentiates these seers across the mandala.", "link_id": "cd6522b2-b283-4a09-8b6a-341a53e0813b", "page_or_section": "Hymns to the Mystic Fire contents", "passages": [], "relationship": "supports", "source": {"author": "Sri Aurobindo", "authority_metadata": {}, "citation": "Sri Aurobindo, Hymns to the Mystic Fire", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Sri Aurobindo Ashram", "rights_or_access_note": null, "source_status": "approved", "source_