insert into original_claims values ('0d8f57ad-7515-4109-bdc2-a27ba156bb73','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "0d8f57ad-7515-4109-bdc2-a27ba156bb73", "claim_kind": "established_fact", "claim_relations": [], "claim_text": "The Mahabharata''s Kalmashapada feud is not a duplicate of the Ramayana Shabala conflict: it places Vishvamitra within a later conflict involving Vasistha''s son Shakti and a possessed king.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source", "Recorded source access issue"], "evidence_type": "uncertain", "lens": {"field_id": "4cf7f8c5-2b71-46e7-9bd0-0a03bb01410d", "field_label": "Textual layers where the Rishi appears", "parameter_id": "a0fd0f1a-762f-410b-874a-1c9f5476abf6", "parameter_name": "Historical and Textual Context"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Adi Parva 1.166 has a distinct cast, causal chain, and outcome.", "link_id": "137760ec-f942-44c5-acb8-38a82db5e18c", "page_or_section": "1.166", "passages": [], "relationship": "supports", "source": {"author": "Vyasa (traditional attribution); BORI Critical Edition", "authority_metadata": {}, "citation": "Mahabharata BORI, Adi Parva, 166", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Bhandarkar Oriental Research Institute critical text / Vedapath presentation", "rights_or_acces