insert into original_claims values ('1b0df374-b0dc-41a9-82bd-409dc072570f','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "1b0df374-b0dc-41a9-82bd-409dc072570f", "claim_kind": "established_fact", "claim_relations": [], "claim_text": "Mahabharata Anushasana Parva supplies a birth mechanism for Vishvamitra through the Ruchika-Satyavati charu exchange that is absent from the Ramayana''s simpler Gadhi/Kushika genealogy.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source", "Recorded source access issue"], "evidence_type": "uncertain", "lens": {"field_id": "4cf7f8c5-2b71-46e7-9bd0-0a03bb01410d", "field_label": "Textual layers where the Rishi appears", "parameter_id": "a0fd0f1a-762f-410b-874a-1c9f5476abf6", "parameter_name": "Historical and Textual Context"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "", "link_id": "1c8d3f59-b85c-4f32-af30-10d1d1847ebb", "page_or_section": "p. 60 (PDF page 20)", "passages": [{"chunk_id": "2ddc390c-b991-4dca-9651-3b58162db2c5", "confidence": 0.95, "excerpt": "60 be viewed as a return home. As Bhīṣma himself explains, ‘So, King Yudhiṣṭhira, the great ascetic Viśvāmitra was not in fact a Kṣatriya, since Ṛcīka had infused the highest brahman within him’ (Mbh 13.4.59). through this strategic use of a genealogical narrative, the Mahābhārata produces the strongest possible affirmation of normative social discourse: an …", "excerpt_truncated": true, "is