insert into original_claims values ('3496f004-7b6b-4ba8-9262-a2cc200464c1','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "3496f004-7b6b-4ba8-9262-a2cc200464c1", "claim_kind": "established_fact", "claim_relations": [], "claim_text": "The Mahabharata Shakuntala genealogy adds Vishvamitra as father of Shakuntala and ancestor of Bharata, a genealogical role not developed in Bala Kanda''s Vishvamitra biography.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source", "Recorded source access issue"], "evidence_type": "uncertain", "lens": {"field_id": "4cf7f8c5-2b71-46e7-9bd0-0a03bb01410d", "field_label": "Textual layers where the Rishi appears", "parameter_id": "a0fd0f1a-762f-410b-874a-1c9f5476abf6", "parameter_name": "Historical and Textual Context"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Adi Parva 1.90.30 states this relationship directly.", "link_id": "5af9b6a9-2224-454d-bd67-f84f76f3f782", "page_or_section": "1.90.30", "passages": [{"chunk_id": "29a70543-dcfe-48cb-9a29-3a3fed666876", "confidence": 0.855294117647059, "excerpt": "Saṃyāti, it is said, married Varāṅgī, the fair-limbed daughter of Dṛṣadvata. From her, Ahaṃpāti was born to him.  अहंपातिस्तु खलु कृतवीर्यदुहितरमुपयेमे भानुमतीं नाम । तस्यामस्य जज्ञे सार्वभौमः  Ahaṃpāti, it is said, married Bhānumatī, the daughter of Kṛtavīrya. From her, Sārvabhauma was born to him.  सार्वभौमः खलु जित्वाजहार कैकेयीं सुनन्दां नाम । 