insert into original_claims values ('8be45ecb-1983-4dfb-bdf3-07d523685bcc','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "8be45ecb-1983-4dfb-bdf3-07d523685bcc", "claim_kind": "established_fact", "claim_relations": [], "claim_text": "Even within Rigveda Mandala 3, attribution is not uniform to one individual: some hymns or verses are assigned to other Vaishvamitras or alternative seers.", "current_status": "approved", "epistemics": {"contract_basis": "text", "contract_satisfied": true, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "uncertain", "lens": {"field_id": "4cf7f8c5-2b71-46e7-9bd0-0a03bb01410d", "field_label": "Textual layers where the Rishi appears", "parameter_id": "a0fd0f1a-762f-410b-874a-1c9f5476abf6", "parameter_name": "Historical and Textual Context"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "RV 3.54 is attributed to Prajapati Vaishvamitra (or Prajapati Vachya), showing variation within the mandala.", "link_id": "41d7483e-5c0d-4c96-a0f6-ab01b1de9abe", "page_or_section": "RV 3.54", "passages": [{"chunk_id": "5c2b4241-4689-487b-b3bf-32b2d1162fb6", "confidence": 0.74, "excerpt": "Hindi Translation by Pt. Sripada Damodara Satavalekar  English Translation by H.H. Wilson  Commentary of Sayanacharya", "excerpt_truncated": false, "is_active": true, "link_method": "single_chunk_curated_source", "page_or_section": "Links", "relationship": "supports", "section_title": "Links", "source_id": "79c4f851-b111-454f-980f-d03472e6a191", "textual_la