insert into original_claims values ('9188b1ed-cb2f-4b1e-961f-cb89eb0096b4','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "9188b1ed-cb2f-4b1e-961f-cb89eb0096b4", "claim_kind": "established_fact", "claim_relations": [], "claim_text": "The Shalya Parva Sarasvati curse narrative constitutes yet another independent Vishvamitra-Vasistha rivalry tradition tied to tirtha geography.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source", "Recorded source access issue"], "evidence_type": "uncertain", "lens": {"field_id": "4cf7f8c5-2b71-46e7-9bd0-0a03bb01410d", "field_label": "Textual layers where the Rishi appears", "parameter_id": "a0fd0f1a-762f-410b-874a-1c9f5476abf6", "parameter_name": "Historical and Textual Context"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The Vasisthapavaha episode is structurally distinct from both Shabala and Kalmashapada narratives.", "link_id": "7e8aadfe-7075-4f03-b637-c1f581003c54", "page_or_section": "Shalya Parva Vasisthapavaha", "passages": [], "relationship": "supports", "source": {"author": "Vyasa (traditional attribution); BORI Critical Edition", "authority_metadata": {}, "citation": "Mahabharata BORI, Shalya Parva", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Bhandarkar Oriental Research Institute critical text / Vedapath presentation", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Mahabharata (BORI Critical Edition), Shalya Parva", "url": "https://vedapath.app/en/mahabharata-bori/shalya-parva"}, "source_id": "1235fefa-2528-496e-86d5-4297dbe57f04"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('b1b6f11d-3340-40c0-8b4c-c375872b36a7','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "b1b6f11d-3340-40c0-8b4c-c375872b36a7", "claim_kind": "established_fact", "claim_relations": [], "claim_text": "The Arsheya Upanishad represents reception rather than primary biography: its use of Vishvamitra in Vedantic dialogue belongs to a much later philosophical textual environment.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "PARTIALLY_SUPPORTED", "epistemic_type": "SYNTHETIC_INTERPRETATION", "proposed_type": "SYNTHETIC_INTERPRETATION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "uncertain", "lens": {"field_id": "4cf7f8c5-2b71-46e7-9bd0-0a03bb01410d", "field_label": "Textual layers where the Rishi appears", "parameter_id": "a0fd0f1a-762f-410b-874a-1c9f5476abf6", "parameter_name": "Historical and Textual Context"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The portal explicitly calls it a comparatively later Vedantic Upanishad.", "link_id": "b0c0199e-de8e-4ad2-be44-c59a366c55bd", "page_or_section": "Arsheya Upanishad", "passages": [{"chunk_id": "2d2aac38-e6ad-4b85-b8a5-5c566247b921", "confidence": 0.848571428571429, "excerpt": "Ārṣeya Upaniṣad is not considered as a principal Upaniṣad of Vedic Literature but it is recognised as a significant Upaniṣad among the ‘Vedānta-Upanis̩ads’ of comparatively later times. Later Upaniṣads were developed to propound the concepts of certain famous schools, such as Yoga, Vedānta, Śākta, Vaiṣṇava and Śaiva.  ĀrṣeyaUpaniṣad is a …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Arsheyopanishad", "relationship": "supports", "section_title": "Arsheyopanishad", "source_id": "f76efd31-3f90-4b32-b386-99e3cce78d6a", "textual_layer": "Traditional or scholarly source"}], "relationship": "supports", "source": {"author": "Traditional text", "authority_metadata": {}, "citation": "Arsheya Upanishad", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Vedic Heritage Portal / IGNCA / Ministry of Culture, Government of India", "rights_or_access_note": null, "source_status": "approved", "source_type": "institutional", "storage_path": null, "title": "Arsheya Upanishad", "url": "https://vedicheritage.gov.in/upanishads/aarsheyopanishad/"}, "source_id": "f76efd31-3f90-4b32-b386-99e3cce78d6a"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('b8712298-1548-4e25-95a3-b157bbdefe16','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "b8712298-1548-4e25-95a3-b157bbdefe16", "claim_kind": "established_fact", "claim_relations": [], "claim_text": "A source-aware AI answer should be able to say ''the Rigveda attributes,'' ''the Aitareya Brahmana narrates,'' ''Bala Kanda narrates,'' or ''the Mahabharata narrates'' instead of synthesizing incompatible layers into an undifferentiated historical biography.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "uncertain", "lens": {"field_id": "4cf7f8c5-2b71-46e7-9bd0-0a03bb01410d", "field_label": "Textual layers where the Rishi appears", "parameter_id": "a0fd0f1a-762f-410b-874a-1c9f5476abf6", "parameter_name": "Historical and Textual Context"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The expanded corpus contains multiple independently framed textual traditions requiring explicit provenance.", "link_id": "6ce52d06-c6f8-412d-affc-19c1b18d186f", "page_or_section": "Dataset methodology", "passages": [{"chunk_id": "3e6fdfef-5922-45e7-bc56-c8468dac2c19", "confidence": 0.840689655172414, "excerpt": "Aitareya Brahmana belongs to Shakala Shakha of the Rigveda. This work is ascribed to Mahidasa Aitareya and dated variously from 1000 BCE to 500 BCE. It is divided into eight Panchikas and each of the Panchika is divided into eight adhyayas. Totally, it consist forty adhyayas.  The first six panchikas of Aitareya Brahmana dealing with Soma Sacrifice (fire …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Aitareya Brahmana", "relationship": "supports", "section_title": "Aitareya Brahmana", "source_id": "d7d8aaa4-5733-44cf-b9bf-0f494d707b99", "textual_layer": "Aitareya Brahmana tradition"}], "relationship": "supports", "source": {"author": "Mahidasa Aitareya (traditional attribution)", "authority_metadata": {}, "citation": "Aitareya Brahmana", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Vedic Heritage Portal / IGNCA / Ministry of Culture, Government of India", "rights_or_access_note": null, "source_status": "approved", "source_type": "institutional", "storage_path": null, "title": "Aitareya Brahmana", "url": "https://vedicheritage.gov.in/brahmanas/aitareya-brahmana/"}, "source_id": "d7d8aaa4-5733-44cf-b9bf-0f494d707b99"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('bda45d3d-cbe2-4b40-b7cd-4ff011403811','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "bda45d3d-cbe2-4b40-b7cd-4ff011403811", "claim_kind": "established_fact", "claim_relations": [], "claim_text": "Sri Aurobindo''s Secret of the Veda is a twentieth-century interpretive layer and should be linked to the ancient hymns as commentary, never stored as if it were a primary Vedic witness.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": null, "contract_status": "NOT_EVIDENTIARY", "epistemic_type": "METHODOLOGICAL", "proposed_type": "METHODOLOGICAL", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "uncertain", "lens": {"field_id": "4cf7f8c5-2b71-46e7-9bd0-0a03bb01410d", "field_label": "Textual layers where the Rishi appears", "parameter_id": "a0fd0f1a-762f-410b-874a-1c9f5476abf6", "parameter_name": "Historical and Textual Context"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The work openly presents a modern interpretive theory of Vedic symbolism.", "link_id": "024cce4f-51e5-42ac-a617-ff49e352dd81", "page_or_section": "Modern commentary layer", "passages": [], "relationship": "supports", "source": {"author": "Sri Aurobindo", "authority_metadata": {}, "citation": "Sri Aurobindo, The Secret of the Veda. Sri Aurobindo Ashram.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Sri Aurobindo Ashram", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_book", "storage_path": null, "title": "The Secret 