insert into original_claims values ('cff0a579-e996-4a39-a425-6a2cd16f6ea6','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "cff0a579-e996-4a39-a425-6a2cd16f6ea6", "claim_kind": "established_fact", "claim_relations": [], "claim_text": "The Aitareya Brahmana Shunahshepa-Devarata account and the Bala Kanda Shunahshepa account share names and themes but differ substantially in ritual setting, kinship details, and narrative purpose; they should be stored as parallel versions, not merged sentence by sentence.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "METHODOLOGICAL", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source", "Recorded source access issue"], "evidence_type": "uncertain", "lens": {"field_id": "4cf7f8c5-2b71-46e7-9bd0-0a03bb01410d", "field_label": "Textual layers where the Rishi appears", "parameter_id": "a0fd0f1a-762f-410b-874a-1c9f5476abf6", "parameter_name": "Historical and Textual Context"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The Brahmana version continues into Devarata''s adoption and lineage succession, material structurally different from the Ramayana telling.", "link_id": "2ee0cf94-6ae2-4767-b5b0-09ced7eb15e2", "page_or_section": "Aitareya vs. Ramayana Shunahshepa", "passages": [], "relationship": "supports", "source": {"author": "", "authority_metadata": {}, "citation": "Aitareya Brahmana Shunahshepa-Devarata passage", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IGNCA Digital Library, Government of India", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Aitareya Brahmana / related Indian antiquarian edition, Shunahshepa-Devarata passage", "url": "https://ignca.gov.in/Asi_data/14189.pdf"}, "source_id": "aaf4aa38-c1b0-4d20-afd0-f83df099bc2a"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('f5851c72-8c59-4e3b-90b9-a1c3834013e6','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "f5851c72-8c59-4e3b-90b9-a1c3834013e6", "claim_kind": "established_fact", "claim_relations": [], "claim_text": "The Valmiki Ramayana site itself notes scholarly views that Bala Kanda may contain later textual strata, so the Vishvamitra biography should be tagged as epic tradition rather than automatically projected back into the Rigvedic period.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "uncertain", "lens": {"field_id": "4cf7f8c5-2b71-46e7-9bd0-0a03bb01410d", "field_label": "Textual layers where the Rishi appears", "parameter_id": "a0fd0f1a-762f-410b-874a-1c9f5476abf6", "parameter_name": "Historical and Textual Context"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The site''s textual introduction reports scholarly arguments about later additions in Bala and Uttara Kandas.", "link_id": "fc43eacc-e9fc-4b13-9f25-669e87e43315", "page_or_section": "Textual introduction", "passages": [{"chunk_id": "1aca410a-48c6-4909-9735-01549a2c4ffc", "confidence": 0.953333333333333, "excerpt": "Srimad Valmiki Ramayana is an epic poem of India which narrates the journey of Virtue  to annihilate vice. Sri  Rama is the Hero and aayana His journey.  We in India believe that Sri Rama lived in Treta Yug, millennia BC and we are presently concerned with what  Srimad Valmiki Ramayana tells us, rather than when it was told.  This epic poem  Ramayana is a …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Valmiki Ramayana", "relationship": "supports", "section_title": "Valmiki Ramayana", "source_id": "dfa79e19-c93e-49ae-868b-766f5860b699", "textual_layer": "Ramayana — Bala Kanda"}, {"chunk_id": "529e0591-a7f3-4db8-b6a7-31d8a65edb72", "confidence": 0.926666666666667, "excerpt": "the lyrical values of Ramayana, but as a great devotee-singer said \"Whoever calls you in whatever way, you are that  One\".  Ramayana contains 24,000 verses [sloka]  arranged into numerous cantos [sarga] which are contained in 6 books as  mentioned earlier. Each chapter, sarga, will be given briefly  in english prose at its start and each verse will be …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Valmiki Ramayana", "relationship": "supports", "section_title": "Valmiki Ramayana", "source_id": "dfa79e19-c93e-49ae-868b-766f5860b699", "textual_layer": "Ramayana — Bala Kanda"}], "relationship": "supports", "source": {"author": "Valmiki Ramayana project", "authority_metadata": {}, "citation": "Valmiki Ramayana: Textual Introduction (https://www.valmikiramayan.net/utf8/ramayana.shtml)", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Valmiki Ramayana: Textual Introduction", "url": "https://www.valmikiramayan.net/utf8/ramayana.shtml"}, "source_id": "dfa79e19-c93e-49ae-868b-766f5860b699"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('06015b7f-650f-4522-976d-43ef2fec7e7e','{"approval_origin": "system_test_bulk", "certainty": "medium", "claim_id": "06015b7f-650f-4522-976d-43ef2fec7e7e", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "The final food-gift episode places tapas and generosity in direct tension: Vishvamitra has completed a long fasting vow but gives the entire meal to a disguised supplicant instead of ending his deprivation.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "SYNTHETIC_INTERPRETATION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Recorded source access issue", "Claim-passage link points to a source absent from claim-source links"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "a1633a99-ed36-455f-923c-0af504e50c70", "field_label": "Capacity to hold fierce tapas and compassion; shaap / vardaan episodes handled carefully", "parameter_id": "9c42159a-91da-4ccd-9ad9-2c5747627b7e", "parameter_name": "Inner Qualities (Rishi-specific virtues)"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The episode narrates Indra''s request immediately before Vishvamitra is about to eat.", "link_id": "0f962e12-3ad6-4d32-b54d-f5752e09004e", "page_or_section": "1.65", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur Valmiki Ramayanam Project", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same Bala Kanda chapter is linked below; compare editions before using a quotation.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayanam, Bala Kanda, Sarga 65", "url": "https://www.valmiki.iitk.ac.in/summary?field_kanda_tid=1&field_sarga_value=65"}, "source_id": "35d30c22-48b6-4242-ad17-697405136d76"}], "unmatched_passage_links": [{"chunk_id": "ef5de7fd-af8f-4eaa-9685-ac9b0a43aa7d", "excerpt": "Vishvamitra becomes Brahma-sage after a prolonged ascesis that made all the worlds  to startle. All gods request Brahma to accord the supreme Brahma-sageship on Vishvamitra  as he is cleansed of all mortal impurities, and Brahma accords that highest order  on him. Thus Sage Shataananda concludes his narration about the legend of Vishvamitra.  अथ हैमवतीम् …", "excerpt_truncated": true, "page_or_section": "Introduction", "relationship": "context", "source": {"author": "Valmiki", "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "title": "Valmiki Ramayana, Bala Kanda, Sarga 65", "url": "https://www.valmikiramayan.net/utf8/baala/sarga65/balasans65.htm.orig"}, "source_id": "b1ff445c-d9d0-4f8e-a28f-f3a8053787ad"}]}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('0b9eef21-41df-49fa-91de-c6580704eb75','{"approval_origin": "system_test_bulk", "certainty": "medium", "claim_id": "0b9eef21-41df-49fa-91de-c6580704eb75", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "Trishanku''s appeal produces a similar tension between ascetic power and protection: Vishvamitra takes up the cause of a rejected king because the king has sought refuge with him.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "PARTIALLY_SUPPORTED", "epistemic_type": "SYNTHETIC_INTERPRETATION", "proposed_type": "SYNTHETIC_INTERPRETATION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["Current approval origin does not establish strict verification", "Recorded source access issue"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "a1633a99-ed36-455f-923c-0af504e50c70", "field_label": "Capacity to hold fierce tapas and compassion; shaap / vardaan episodes handled carefully", "parameter_id": "9c42159a-91da-4ccd-9ad9-2c5747627b7e", "parameter_name": "Inner Qualities (Rishi-specific virtues)"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Sarga 58 presents Trishanku approaching Vishvamitra after rejection and Vishvamitra responding with pity/protection.", "link_id": "3b934632-89d9-4dc5-b0fe-5ac852224a1c", "page_or_section": "1.58", "passages": [{"chunk_id": "4849c222-55e8-426f-b3a6-c482a6154f41", "confidence": 0.903478260869565, "excerpt": "Trishanku seeks shelter of Vishvamitra when the sons of Vashishta rebuffed   him, and even cursed him to become a profaner. Narrating his sad tale   and his idealistic idea of going to heaven with mortal body, Trishanku   earnestly appeals to Vishvamitra.  \"On hearing the sentence of Trishanku, oh, Rama, the hundred sons of sage Vashishta  infuriately said …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Book I : Bala Kanda - The Youthful Majesties\nSarga 58  in Prose", "relationship": "supports", "section_title": "Book I : Bala Kanda - The Youthful Majesties\nSarga 58  in Prose", "source_id": "397c4acd-7d33-4400-88ac-a1cc49c58e35", "textual_layer": "Ramayana — Bala Kanda"}, {"chunk_id": "832c5c38-711a-4f73-9f40-6263ac1cc2bf", "confidence": 0.903478260869565, "excerpt": "\"But the sons of the sage Vashishta, on hearing that sentence of the king, that  is inclusive of and leading to a calamitous situation, have become very highly infuriated  and cursed saying, ''you shall get into a state of basely profaner.'' That is the  curse issued by the sons of Vashishta to Trishanku.  This expression caNDaal has its own impact. The …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Book I : Bala Kanda - The Youthful Majesties\nSarga 58  in Prose", "relationship": "supports", "section_title": "Book I : Bala Kanda - The Youthful Majesties\nSarga 58  in Prose", "source_id": "397c4acd-7d33-4400-88ac-a1cc49c58e35", "textual_layer": "Ramayana — Bala Kanda"}], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution); English rendering by Desiraju Hanumanta Rao", "authority_metadata": {"verified_http_status": 200}, "citation": "Valmiki Ramayana, Bala Kanda 1.58, chapter-level prose rendering.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": "Publicly accessible chapter page; preserve source attribution and link.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayana — Bala Kanda, Sarga 58 (prose)", "url": "https://www.valmikiramayan.net/utf8/baala/sarga58/bala_58_prose.htm"}, "source_id": "397c4acd-7d33-4400-88ac-a1cc49c58e35"}, {"evidence_excerpt": "Sarga 58 presents Trishanku approaching Vishvamitra after rejection and Vishvamitra responding with pity/protection.", "link_id": "4fab4139-484c-4b25-88a6-25330dce7097", "page_or_section": "1.58", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur Valmiki Ramayanam Project", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same Bala Kanda chapter is linked below; compare editions before using a quotation.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayanam, Bala Kanda, Sarga 58", "url": "https://www.valmiki.iitk.ac.in/summary?field_kanda_tid=1&field_sarga_value=58"}, "source_id": "fc5ce0d6-619b-404d-868f-ee5d67067ac7"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('0cb31337-5d17-43e9-b011-62c513752d66','{"approval_origin": "system_test_bulk", "certainty": "medium", "claim_id": "0cb31337-5d17-43e9-b011-62c513752d66", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "Mahabharata Shalya Parva''s Sarasvati story offers a contrasting portrayal in which intense rivalry and anger lead Vishvamitra to threaten Vasistha and curse the river, reminding the dataset not to equate tapas automatically with compassion.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "METHODOLOGICAL", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source", "Recorded source access issue"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "a1633a99-ed36-455f-923c-0af504e50c70", "field_label": "Capacity to hold fierce tapas and compassion; shaap / vardaan episodes handled carefully", "parameter_id": "9c42159a-91da-4ccd-9ad9-2c5747627b7e", "parameter_name": "Inner Qualities (Rishi-specific virtues)"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The Vasisthapavaha account links Vishvamitra''s tapas-rivalry with anger and a curse on Sarasvati.", "link_id": "0ebeac82-bcb1-40e9-8019-942d1e372c7b", "page_or_section": "Shalya Parva Vasisthapavaha", "passages": [], "relationship": "supports", "source": {"author": "Vyasa (traditional attribution); BORI Critical Edition", "authority_metadata": {}, "citation": "Mahabharata BORI, Shalya Parva", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Bhandarkar Oriental Research Institute critical text / Vedapath presentation", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Mahabharata (BORI Critical Edition), Shalya Parva", "url": "https://vedapath.app/en/mahabharata-bori/shalya-parva"}, "source_id": "1235fefa-2528-496e-86d5-4297dbe57f04"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('16f8e94b-2975-4e65-bc9e-1d8146d7e87e','{"approval_origin": "system_test_bulk", "certainty": "medium", "claim_id": "16f8e94b-2975-4e65-bc9e-1d8146d7e87e", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "The Shunahshepa narrative gives evidence for compassion/protection because the boy explicitly seeks refuge and Vishvamitra acts to save him through ritual instruction.", "current_status": "approved", "epistemics": {"contract_basis": "interpretation", "contract_satisfied": true, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "SCHOLARLY_INTERPRETATION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "a1633a99-ed36-455f-923c-0af504e50c70", "field_label": "Capacity to hold fierce tapas and compassion; shaap / vardaan episodes handled carefully", "parameter_id": "9c42159a-91da-4ccd-9ad9-2c5747627b7e", "parameter_name": "Inner Qualities (Rishi-specific virtues)"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Shunahshepa asks Vishvamitra for protection; Vishvamitra consoles him and provides a ritual solution.", "link_id": "01f510c4-268f-4759-b461-1f0ed8f07b67", "page_or_section": "1.62.4-18", "passages": [{"chunk_id": "01b9c2bc-82aa-4320-b659-3d37088c6c3b", "confidence": 0.851578947368421, "excerpt": "Vividly: ''A father''s ambition in begetting sons is to do something good and positive  to the society in the present world and when departed a right place is acquired  in heavens through these sons, by their yearly death-day rituals etc., and hence  you do some good in saving this boy from premature death and earn an apt place for  me in heavens...''  अयं …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Introduction", "relationship": "supports", "section_title": "Introduction", "source_id": "4bd01c3e-d436-4013-a8a9-49d839abe475", "textual_layer": "Ramayana — Bala Kanda"}, {"chunk_id": "e4ea51bd-02c1-4363-af67-82b98757e401", "confidence": 0.851578947368421, "excerpt": "Sage Vishvamitra curses his sons as they defy his orders and accords two esoteric  hymns to Shunashepa, for chanting them in the Vedic-ritual of Ambariisha. Shunashepa  gets longevity on chanting those hymns. Thus Vishvamitra not only creates another  universe as in Trishanku''s episode, he even accords longevity, or even deathlessness  to mortals by his …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Introduction", "relationship": "supports", "section_title": "Introduction", "source_id": "4bd01c3e-d436-4013-a8a9-49d839abe475", "textual_layer": "Ramayana — Bala Kanda"}], "relationship": "supports", "source": {"author": "Valmiki", "authority_metadata": {}, "citation": "Valmiki Ramayana, Bala Kanda, Sarga 62 (https://www.valmikiramayan.net/utf8/baala/sarga62/balasans62.htm)", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Valmiki Ramayana, Bala Kanda, Sarga 62", "url": "https://www.valmikiramayan.net/utf8/baala/sarga62/balasans62.htm"}, "source_id": "4bd01c3e-d436-4013-a8a9-49d839abe475"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('439a4a25-4480-4a17-a828-4cb25ddb68b5','{"approval_origin": "system_test_bulk", "certainty": "medium", "claim_id": "439a4a25-4480-4a17-a828-4cb25ddb68b5", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "The post-Tataka weapon transfer is framed by Vishvamitra''s pleasure and affection toward Rama, pairing his ascetic authority with a positive mentor relationship.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "PARTIALLY_SUPPORTED", "epistemic_type": "SYNTHETIC_INTERPRETATION", "proposed_type": "SYNTHETIC_INTERPRETATION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["Current approval origin does not establish strict verification", "Recorded source access issue"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "a1633a99-ed36-455f-923c-0af504e50c70", "field_label": "Capacity to hold fierce tapas and compassion; shaap / vardaan episodes handled carefully", "parameter_id": "9c42159a-91da-4ccd-9ad9-2c5747627b7e", "parameter_name": "Inner Qualities (Rishi-specific virtues)"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The narrative describes him as pleased before rewarding Rama with sacred weapon knowledge.", "link_id": "76b186b2-37de-4335-b940-0746dcce011f", "page_or_section": "1.26-27", "passages": [{"chunk_id": "0d13a212-8365-4a87-8d31-4148b91f702d", "confidence": 0.905454545454545, "excerpt": "\"Lakshmana, see that yakshii''s grisly and ghastly physique, seeing which hearts of cowards are prone  to burst. She is unstoppable and has magical powers, is''t, you may see now how I will make her to  readily retreat by lopping off her ears and the tip of nose. As it is her feminineness is protecting  her, and I too I do not really attempt to kill her, but …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Book I : Bala Kanda - The Youthful Majesties\nSarga 26 in Prose", "relationship": "supports", "section_title": "Book I : Bala Kanda - The Youthful Majesties\nSarga 26 in Prose", "source_id": "20585d18-784f-4e7d-8daf-49e857c82117", "textual_layer": "Ramayana — Bala Kanda"}, {"chunk_id": "2c5b47db-6540-4f24-9cc3-6db9940c0037", "confidence": 0.847272727272727, "excerpt": "Rama encounters his first problem-female demoness Tataka, also called as Taadaka, and   eliminates her at the orders of sage Vishvamitra. This is a crucial test put to Rama by   Vishvamitra in ascertaining whether Rama is the follower of dharma through elder men''s   orders or not. Rama eradicates Tataka basing on his own self-confidence.  On hearing the …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Book I : Bala Kanda - The Youthful Majesties\nSarga 26 in Prose", "relationship": "supports", "section_title": "Book I : Bala Kanda - The Youthful Majesties\nSarga 26 in Prose", "source_id": "20585d18-784f-4e7d-8daf-49e857c82117", "textual_layer": "Ramayana — Bala Kanda"}], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution); English rendering by Desiraju Hanumanta Rao", "authority_metadata": {"verified_http_status": 200}, "citation": "Valmiki Ramayana, Bala Kanda 1.26, chapter-level prose rendering.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": "Publicly accessible chapter page; preserve source attribution and link.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayana — Bala Kanda, Sarga 26 (prose)", "url": "https://www.valmikiramayan.net/utf8/baala/sarga26/bala_26_prose.htm"}, "source_id": "20585d18-784f-4e7d-8daf-49e857c82117"}, {"evidence_excerpt": "The narrative describes him as pleased before rewarding Rama with sacred weapon knowledge.", "link_id": "b21b54e4-c307-4fae-81f0-a692d192a939", "page_or_section": "1.26-27", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur Valmiki Ramayanam Project", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same Bala Kanda chapter is linked below; compare editions before using a quotation.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayanam, Bala Kanda, Sarga 26", "url": "https://www.valmiki.iitk.ac.in/summary?field_kanda_tid=1&field_sarga_value=26"}, "source_id": "52fd4b07-98c1-4502-b0b4-3adadf160d62"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('58022795-a537-4c0e-9e5c-0508a93b6e11','{"approval_origin": "system_test_bulk", "certainty": "medium", "claim_id": "58022795-a537-4c0e-9e5c-0508a93b6e11", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "The Shanti Parva famine story depicts ascetic stature without immunity from bodily vulnerability: Vishvamitra becomes desperately hungry and reasons about survival, preventing an unrealistically emotionless portrait of tapas.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "UNSUPPORTED", "epistemic_type": "TRADITIONAL_NARRATIVE", "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source", "Recorded source access issue"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "a1633a99-ed36-455f-923c-0af504e50c70", "field_label": "Capacity to hold fierce tapas and compassion; shaap / vardaan episodes handled carefully", "parameter_id": "9c42159a-91da-4ccd-9ad9-2c5747627b7e", "parameter_name": "Inner Qualities (Rishi-specific virtues)"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The story explicitly describes famine, emaciation, lack of wealth, and urgent hunger.", "link_id": "db71286a-b083-4690-af85-ca9e4280be2c", "page_or_section": "12.142", "passages": [], "relationship": "supports", "source": {"author": "Vyasa (traditional attribution)", "authority_metadata": {}, "citation": "Mahabharata, Shanti Parva, 142", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Gita Press edition / Vedapath presentation", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Mahabharata (Gita Press edition), Shanti Parva, Adhyaya 142", "url": "https://vedapath.app/en/mahabharata-gita-press/shanti-parva/142"}, "source_id": "1265258a-bc16-44e0-8c55-55ca3104767e"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('7efaaf4b-bc24-4991-b1b7-73ae679a50ac','{"approval_origin": "system_test_bulk", "certainty": "medium", "claim_id": "7efaaf4b-bc24-4991-b1b7-73ae679a50ac", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "The Galava cycle complicates the guru ideal: Vishvamitra initially asks for no payment, but after Galava refuses to accept release he names a burden that drives a long and ethically difficult quest.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source", "Recorded source access issue"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "a1633a99-ed36-455f-923c-0af504e50c70", "field_label": "Capacity to hold fierce tapas and compassion; shaap / vardaan episodes handled carefully", "parameter_id": "9c42159a-91da-4ccd-9ad9-2c5747627b7e", "parameter_name": "Inner Qualities (Rishi-specific virtues)"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The demand follows Galava''s repeated insistence on paying guru-dakshina.", "link_id": "40558608-ce38-49d9-9b0c-9ec291d58072", "page_or_section": "5.104", "passages": [], "relationship": "supports", "source": {"author": "Vyasa (traditional attribution); BORI Critical Edition", "authority_metadata": {}, "citation": "Mahabharata BORI, Udyoga Parva, 104", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Bhandarkar Oriental Research Institute critical text / Vedapath presentation", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Mahabharata (BORI Critical Edition), Udyoga Parva, Adhyaya 104", "url": "https://vedapath.app/en/mahabharata-bori/udyoga-parva/104"}, "source_id": "855f8c75-16cc-4e96-9ba3-d79579231842"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('7f085f80-1ddd-47bf-abce-61662b2b9eee','{"approval_origin": "system_test_bulk", "certainty": "medium", "claim_id": "7f085f80-1ddd-47bf-abce-61662b2b9eee", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "The Vishvamitra narrative contains both protective/teaching roles and severe anger episodes. A balanced profile should therefore present compassion, fierceness, remorse, and self-discipline together rather than assigning a one-sided virtue label.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "PARTIALLY_SUPPORTED", "epistemic_type": "SYNTHETIC_INTERPRETATION", "proposed_type": "SYNTHETIC_INTERPRETATION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Current approval origin does not establish strict verification", "Recorded source access issue", "Claim-passage link points to a source absent from claim-source links"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "a1633a99-ed36-455f-923c-0af504e50c70", "field_label": "Capacity to hold fierce tapas and compassion; shaap / vardaan episodes handled carefully", "parameter_id": "9c42159a-91da-4ccd-9ad9-2c5747627b7e", "parameter_name": "Inner Qualities (Rishi-specific virtues)"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The Rambha episode explicitly includes anger followed by remorse and renewed resolve.", "link_id": "e379e6d1-5198-4b58-b9f9-596c887e5a33", "page_or_section": "Bala Kanda 1.64.14–18", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana, Bala Kanda 1.64. IIT Kanpur Valmiki Ramayanam.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same Bala Kanda chapter is linked below; compare editions before using a quotation.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayanam — Bala Kanda, Sarga 64", "url": "https://www.valmiki.iitk.ac.in/sloka?field_kanda_tid=1&field_sarga_value=64&language=dv"}, "source_id": "84367293-66be-4b9a-8bd2-ac2ca21fa68d"}], "unmatched_passage_links": [{"chunk_id": "515003fb-3676-4dbd-8abb-a58e725319ce", "excerpt": "Whereof you tried to entice me who am wishing to win over the wanton and wroth, you unlucky female  Rambha, thereof you will become a rocklike statued wastrel. [1-64-12]  ब्राह्मणः सुमहातेजास्तपोबलसमन्वितः |उद्धरिष्यति रंभे त्वां मत्क्रोधकलुषीकृताम् || १-६४-१३  13. rambhe = oh Rambha; sumahaatejaaH = very high resplendent one;  tapobalasamanvitaH = having …", "excerpt_truncated": true, "page_or_section": "Introduction", "relationship": "context", "source": {"author": "Valmiki", "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "title": "Valmiki Ramayana, Bala Kanda, Sarga 64", "url": "https://www.valmikiramayan.net/utf8/baala/sarga64/balasans64.htm"}, "source_id": "8d1e7888-6577-4564-b935-96ed0ae1b902"}]}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('882a50a9-1b63-40a1-8649-429e9243e63d','{"approval_origin": "system_test_bulk", "certainty": "medium", "claim_id": "882a50a9-1b63-40a1-8649-429e9243e63d", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "The Trishanku cycle also shows the limits of a simple compassion reading because Vishvamitra later curses sages who refuse participation, so protection of one supplicant coexists with punitive anger toward opponents.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "SYNTHETIC_INTERPRETATION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Recorded source access issue"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "a1633a99-ed36-455f-923c-0af504e50c70", "field_label": "Capacity to hold fierce tapas and compassion; shaap / vardaan episodes handled carefully", "parameter_id": "9c42159a-91da-4ccd-9ad9-2c5747627b7e", "parameter_name": "Inner Qualities (Rishi-specific virtues)"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Sarga 59 combines the refuge commitment with curses against refusers.", "link_id": "a61fbe84-445d-43f6-ab41-fbb460c7326c", "page_or_section": "1.59", "passages": [{"chunk_id": "5326a31a-1540-4cb8-bab3-96ed76b89a7a", "confidence": 0.86962962962963, "excerpt": "\"The eminent sage Vishvamitra having heard those words of the sons of Vashishta  from all of his disciples, said this rancorously with bloodshot eyes.  \" ''He who reproves me, who am abiding in rigorous ascesis, and who am an  unreprovable one by my ascetic merit, that irreverent person will be reduced to  ashes, and there is no doubt about it. Now they will …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Book I : Bala Kanda - The Youthful Majesties\n Sarga 59 in Prose", "relationship": "supports", "section_title": "Book I : Bala Kanda - The Youthful Majesties\n Sarga 59 in Prose", "source_id": "7b637414-d012-4349-9ea0-bded3c081f08", "textual_layer": "Ramayana — Bala Kanda"}, {"chunk_id": "7fa20770-91d1-4b00-a9ae-b651c966d204", "confidence": 0.897037037037037, "excerpt": "Vishvamitra undertakes Trishanku''s Vedic ritual and sends disciples   to invite all Vedic-scholars. Many sages have come except for   Vashishta and his sons. Further, the sons of Vashishta have   ridiculed this ritual of Vishvamitra and Trishanku. Vishvamitra gets   irritated and hurls curses at the sons of Vashishta.  \"Vishvamitra, the son of Kushi, …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Book I : Bala Kanda - The Youthful Majesties\n Sarga 59 in Prose", "relationship": "supports", "section_title": "Book I : Bala Kanda - The Youthful Majesties\n Sarga 59 in Prose", "source_id": "7b637414-d012-4349-9ea0-bded3c081f08", "textual_layer": "Ramayana — Bala Kanda"}], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution); English rendering by Desiraju Hanumanta Rao", "authority_metadata": {"verified_http_status": 200}, "citation": "Valmiki Ramayana, Bala Kanda 1.59, chapter-level prose rendering.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": "Publicly accessible chapter page; preserve source attribution and link.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayana — Bala Kanda, Sarga 59 (prose)", "url": "https://www.valmikiramayan.net/utf8/baala/sarga59/bala_59_prose.htm"}, "source_id": "7b637414-d012-4349-9ea0-bded3c081f08"}, {"evidence_excerpt": "Sarga 59 combines the refuge commitment with curses against refusers.", "link_id": "6afdf71d-e644-42a3-a4c9-e20154b56343", "page_or_section": "1.59", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur Valmiki Ramayanam Project", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same Bala Kanda chapter is linked below; compare editions before using a quotation.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayanam, Bala Kanda, Sarga 59", "url": "https://www.valmiki.iitk.ac.in/summary?field_kanda_tid=1&field_sarga_value=59"}, "source_id": "a7c009d6-db4c-405e-b465-47bdc344f5b4"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('9559d070-c4a4-4f00-81c1-271b2d20bc49','{"approval_origin": "system_test_bulk", "certainty": "medium", "claim_id": "9559d070-c4a4-4f00-81c1-271b2d20bc49", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "The Rambha episode likewise presents the tension between great tapas and incomplete anger-control, followed by remorse and renewed self-discipline.", "current_status": "approved", "epistemics": {"contract_basis": "tradition", "contract_satisfied": true, "contract_status": "SUPPORTED", "epistemic_type": "TRADITIONAL_NARRATIVE", "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "a1633a99-ed36-455f-923c-0af504e50c70", "field_label": "Capacity to hold fierce tapas and compassion; shaap / vardaan episodes handled carefully", "parameter_id": "9c42159a-91da-4ccd-9ad9-2c5747627b7e", "parameter_name": "Inner Qualities (Rishi-specific virtues)"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The narrative explicitly moves from curse in anger to shame and renewed austerity.", "link_id": "bcd921a9-db01-4902-bde1-8a2f02a01dd0", "page_or_section": "1.64", "passages": [{"chunk_id": "2a5bae86-6077-4fd8-8d21-59b2a47b760a", "confidence": 0.847272727272727, "excerpt": "Vishvamitra curses Rambha, the celestial wench, knowing that she arrived at the behest of Indra to cause  hindrance to his ascesis. But later feels ashamed to loose his tongue and then he is determined to undertake  another round of ascesis to conquer is own senses.  सुरकार्यमिदं रंभे कर्तव्यं सुमहत्त्वया |लोभनं कौशिकस्येह काममोहसमन्वितम् || १-६४-१  1. …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Introduction", "relationship": "supports", "section_title": "Introduction", "source_id": "8d1e7888-6577-4564-b935-96ed0ae1b902", "textual_layer": "Ramayana — Bala Kanda"}, {"chunk_id": "515003fb-3676-4dbd-8abb-a58e725319ce", "confidence": 0.905454545454545, "excerpt": "Whereof you tried to entice me who am wishing to win over the wanton and wroth, you unlucky female  Rambha, thereof you will become a rocklike statued wastrel. [1-64-12]  ब्राह्मणः सुमहातेजास्तपोबलसमन्वितः |उद्धरिष्यति रंभे त्वां मत्क्रोधकलुषीकृताम् || १-६४-१३  13. rambhe = oh Rambha; sumahaatejaaH = very high resplendent one;  tapobalasamanvitaH = having …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Introduction", "relationship": "supports", "section_title": "Introduction", "source_id": "8d1e7888-6577-4564-b935-96ed0ae1b902", "textual_layer": "Ramayana — Bala Kanda"}], "relationship": "supports", "source": {"author": "Valmiki", "authority_metadata": {}, "citation": "Valmiki Ramayana, Bala Kanda, Sarga 64 (https://www.valmikiramayan.net/utf8/baala/sarga64/balasans64.htm)", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Valmiki Ramayana, Bala Kanda, Sarga 64", "url": "https://www.valmikiramayan.net/utf8/baala/sarga64/balasans64.htm"}, "source_id": "8d1e7888-6577-4564-b935-96ed0ae1b902"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('9bedb2d7-24cf-4f1b-9740-eed513164e45','{"approval_origin": "system_test_bulk", "certainty": "medium", "claim_id": "9bedb2d7-24cf-4f1b-9740-eed513164e45", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "The same episode resists a one-sided saintly portrait because Vishvamitra becomes furious with his sons and curses them when they refuse his demand.", "current_status": "approved", "epistemics": {"contract_basis": "interpretation", "contract_satisfied": true, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "SCHOLARLY_INTERPRETATION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "a1633a99-ed36-455f-923c-0af504e50c70", "field_label": "Capacity to hold fierce tapas and compassion; shaap / vardaan episodes handled carefully", "parameter_id": "9c42159a-91da-4ccd-9ad9-2c5747627b7e", "parameter_name": "Inner Qualities (Rishi-specific virtues)"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Sarga 62 explicitly narrates his anger and curse against his sons.", "link_id": "e3622880-c4b6-44ec-a815-532bf2f90f47", "page_or_section": "1.62.13-17", "passages": [{"chunk_id": "72182ad9-a330-4762-8f24-13100a2975a7", "confidence": 0.937142857142857, "excerpt": "Vishvamitra will be nagged by almost all, including his sons, on this ''dog-meat-eating.''  There is a parable in Maha Bharata that Vishvamitra once tried to eat dog''s meat  when he did not get any food, but caught red-handedly. Later this has become the  curse-theme to Vishvamitra when he cursed Vashishta''s sons. At the present juncture  also he curses his …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Introduction", "relationship": "supports", "section_title": "Introduction", "source_id": "4bd01c3e-d436-4013-a8a9-49d839abe475", "textual_layer": "Ramayana — Bala Kanda"}, {"chunk_id": "e4ea51bd-02c1-4363-af67-82b98757e401", "confidence": 0.907619047619048, "excerpt": "Sage Vishvamitra curses his sons as they defy his orders and accords two esoteric  hymns to Shunashepa, for chanting them in the Vedic-ritual of Ambariisha. Shunashepa  gets longevity on chanting those hymns. Thus Vishvamitra not only creates another  universe as in Trishanku''s episode, he even accords longevity, or even deathlessness  to mortals by his …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Introduction", "relationship": "supports", "section_title": "Introduction", "source_id": "4bd01c3e-d436-4013-a8a9-49d839abe475", "textual_layer": "Ramayana — Bala Kanda"}], "relationship": "supports", "source": {"author": "Valmiki", "authority_metadata": {}, "citation": "Valmiki Ramayana, Bala Kanda, Sarga 62 (https://www.valmikiramayan.net/utf8/baala/sarga62/balasans62.htm)", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Valmiki Ramayana, Bala Kanda, Sarga 62", "url": "https://www.valmikiramayan.net/utf8/baala/sarga62/balasans62.htm"}, "source_id": "4bd01c3e-d436-4013-a8a9-49d839abe475"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('0073259b-5428-4888-a85a-9edb0ff04776','{"approval_origin": "system_test_bulk", "certainty": "medium", "claim_id": "0073259b-5428-4888-a85a-9edb0ff04776", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "A balanced profile should therefore distinguish universal applicability claimed by later interpreters from the narrower ritual, lineage, and royal contexts actually visible in early textual sources.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "UNSUPPORTED", "epistemic_type": "SYNTHETIC_INTERPRETATION", "proposed_type": "SYNTHETIC_INTERPRETATION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "e43e873a-1b16-4b8a-b5ef-436e30a72ea2", "field_label": "Universality of vision vs. sectarian narrowness", "parameter_id": "9c42159a-91da-4ccd-9ad9-2c5747627b7e", "parameter_name": "Inner Qualities (Rishi-specific virtues)"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The contrast between later Vedantic reception and earlier ritual/narrative roles makes the distinction necessary.", "link_id": "59589b71-9a7f-43f6-8bae-319a032af9f1", "page_or_section": "Cross-layer synthesis", "passages": [], "relationship": "supports", "source": {"author": "Traditional text", "authority_metadata": {}, "citation": "Arsheya Upanishad", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Vedic Heritage Portal / IGNCA / Ministry of Culture, Government of India", "rights_or_access_note": null, "source_status": "approved", "source_type": "institutional", "storage_path": null, "title": "Arsheya Upanishad", "url": "https://vedicheritage.gov.in/upanishads/aarsheyopanishad/"}, "source_id": "f76efd31-3f90-4b32-b386-99e3cce78d6a"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('062ff005-15a9-4f97-8259-1d0698482a87','{"approval_origin": "system_test_bulk", "certainty": "medium", "claim_id": "062ff005-15a9-4f97-8259-1d0698482a87", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "Sri Aurobindo''s psychological interpretation deliberately moves Vedic imagery away from purely tribal or external readings, but this universalizing move belongs to his modern hermeneutic.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "SCHOLARLY_INTERPRETATION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "e43e873a-1b16-4b8a-b5ef-436e30a72ea2", "field_label": "Universality of vision vs. sectarian narrowness", "parameter_id": "9c42159a-91da-4ccd-9ad9-2c5747627b7e", "parameter_name": "Inner Qualities (Rishi-specific virtues)"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The Secret of the Veda interprets the rivers and divine figures as movements of consciousness.", "link_id": "5d356a4f-2d38-4dcb-9f47-93c39966ba2d", "page_or_section": "Modern interpretive lens", "passages": [], "relationship": "supports", "source": {"author": "Sri Aurobindo", "authority_metadata": {}, "citation": "Sri Aurobindo, The Secret of the Veda. Sri Aurobindo Ashram.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Sri Aurobindo Ashram", "rights_or_access_