insert into original_claims values ('17e108fa-cbdb-4f1e-b11c-51d6cc22b8d3','{"approval_origin": "system_test_bulk", "certainty": "medium", "claim_id": "17e108fa-cbdb-4f1e-b11c-51d6cc22b8d3", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "The later Arsheya Upanishad places five famous rishis together in philosophical discussion of Atman and related Vedantic themes; this is evidence for a later integrative reception, not proof of Vishvamitra''s original social outlook.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "PARTIALLY_SUPPORTED", "epistemic_type": "SYNTHETIC_INTERPRETATION", "proposed_type": "SYNTHETIC_INTERPRETATION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "e43e873a-1b16-4b8a-b5ef-436e30a72ea2", "field_label": "Universality of vision vs. sectarian narrowness", "parameter_id": "9c42159a-91da-4ccd-9ad9-2c5747627b7e", "parameter_name": "Inner Qualities (Rishi-specific virtues)"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The portal identifies five seers and summarizes the Upanishad''s shared philosophical themes.", "link_id": "0ec45876-721a-44b4-9c7f-b56067e1efdd", "page_or_section": "Arsheya Upanishad overview", "passages": [{"chunk_id": "2d2aac38-e6ad-4b85-b8a5-5c566247b921", "confidence": 0.931851851851852, "excerpt": "Ārṣeya Upaniṣad is not considered as a principal Upaniṣad of Vedic Literature but it is recognised as a significant Upaniṣad among the ‘Vedānta-Upanis̩ads’ of comparatively later times. Later Upaniṣads were developed to propound the concepts of certain famous schools, such as Yoga, Vedānta, Śākta, Vaiṣṇava and Śaiva.  ĀrṣeyaUpaniṣad is a …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Arsheyopanishad", "relationship": "supports", "section_title": "Arsheyopanishad", "source_id": "f76efd31-3f90-4b32-b386-99e3cce78d6a", "textual_layer": "Traditional or scholarly source"}], "relationship": "supports", "source": {"author": "Traditional text", "authority_metadata": {}, "citation": "Arsheya Upanishad", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Vedic Heritage Portal / IGNCA / Ministry of Culture, Government of India", "rights_or_access_note": null, "source_status": "approved", "source_type": "institutional", "storage_path": null, "title": "Arsheya Upanishad", "url": "https://vedicheritage.gov.in/upanishads/aarsheyopanishad/"}, "source_id": "f76efd31-3f90-4b32-b386-99e3cce78d6a"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('597dc8b2-1382-4632-83b1-51319f1bfb53','{"approval_origin": "system_test_bulk", "certainty": "medium", "claim_id": "597dc8b2-1382-4632-83b1-51319f1bfb53", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "The primary sources do not yield a simple measurable verdict on “universality versus sectarian narrowness.” Sri Aurobindo later reads Vishvamitra’s Vedic imagery psychologically and spiritually; that must remain a clearly labeled modern interpretation.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "METHODOLOGICAL", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "e43e873a-1b16-4b8a-b5ef-436e30a72ea2", "field_label": "Universality of vision vs. sectarian narrowness", "parameter_id": "9c42159a-91da-4ccd-9ad9-2c5747627b7e", "parameter_name": "Inner Qualities (Rishi-specific virtues)"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Sri Aurobindo interprets Vishvamitra’s river imagery as streams of conscious being.", "link_id": "b681aca0-0c44-48b7-9160-92596477f229", "page_or_section": "The Secret of the Veda — “The Seven Rivers”", "passages": [{"chunk_id": "13cd0822-035c-4563-bcfe-e14feeadd8d7", "confidence": 0.55, "excerpt": "372 Hymns of the Atris three heavens. More, there is a triple world below, — Heaven, Earth and the intervening mid-region; a triple world between, the shining heavens of the Sun; a triple world above, the supreme and rapturous abodes of the Godhead. But other principles intervene and make the order of the worlds yet more complex. These principles are …", "excerpt_truncated": true, "is_active": true, "link_method": "citation_partial", "page_or_section": "Page 384", "relationship": "context", "section_title": "Page 384", "source_id": "7efe2589-0b7e-4cee-bcc0-b71b0ba418e6", "textual_layer": "Modern spiritual interpretation"}], "relationship": "supports", "source": {"author": "Sri Aurobindo", "authority_metadata": {}, "citation": "Sri Aurobindo, The Secret of the Veda. Sri Aurobindo Ashram.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Sri Aurobindo Ashram", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_book", "storage_path": null, "title": "The Secret of the Veda", "url": "https://www.sriaurobindoashram.org/sriaurobindo/downloadpdf.php?id=30"}, "source_id": "7efe2589-0b7e-4cee-bcc0-b71b0ba418e6"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('5f5eb567-b0a6-482e-84fe-edf2e7a37162','{"approval_origin": "system_test_bulk", "certainty": "medium", "claim_id": "5f5eb567-b0a6-482e-84fe-edf2e7a37162", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "The available primary texts do not provide a simple modern category of ''universal'' versus ''sectarian'' for Vishvamitra; such a judgment should be made only with an explicit interpretive framework.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "PARTIALLY_SUPPORTED", "epistemic_type": "SYNTHETIC_INTERPRETATION", "proposed_type": "SYNTHETIC_INTERPRETATION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "e43e873a-1b16-4b8a-b5ef-436e30a72ea2", "field_label": "Universality of vision vs. sectarian narrowness", "parameter_id": "9c42159a-91da-4ccd-9ad9-2c5747627b7e", "parameter_name": "Inner Qualities (Rishi-specific virtues)"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The Vedic evidence is hymn-based and deity-specific, while the epic evidence is narrative; neither source labels Vishvamitra in this modern binary.", "link_id": "d796e923-9eac-4970-814c-82cce54b7b4a", "page_or_section": "Source-limit statement", "passages": [{"chunk_id": "9b97ceb8-689b-43d6-a99c-34242db71f5a", "confidence": 0.84, "excerpt": "The whole of the Rigveda-Samhita is in form of verses, known as Rik.  ‘Rik’ is the name given to those Mantras which are meant for the praise of the deities. Thus the collection (Samhita) of Riks is known as Rigveda-Samhita. Only one recession or school (Shakha) of the Rigveda is available today and it is the Shaakala. The Rigveda Samhita contains about …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "B. Form and Classification :", "relationship": "supports", "section_title": "B. Form and Classification :", "source_id": "a81542bb-e361-49cb-b474-ef4919118501", "textual_layer": "Rigveda — Mandala 3"}], "relationship": "supports", "source": {"author": "Vedic Heritage Portal", "authority_metadata": {}, "citation": "Vedic Heritage Portal: Rigveda Overview (https://vedicheritage.gov.in/samhitas/rigveda/)", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IGNCA / Ministry of Culture, Government of India", "rights_or_access_note": null, "source_status": "approved", "source_type": "institutional", "storage_path": null, "title": "Vedic Heritage Portal: Rigveda Overview", "url": "https://vedicheritage.gov.in/samhitas/rigveda/"}, "source_id": "a81542bb-e361-49cb-b474-ef4919118501"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('6df9ba55-b447-46b9-a821-7e4aa40d516e','{"approval_origin": "system_test_bulk", "certainty": "medium", "claim_id": "6df9ba55-b447-46b9-a821-7e4aa40d516e", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "A broader modern spiritual reading exists in Sri Aurobindo''s interpretation of Vedic symbolism, but that is a later interpretive lens and should remain distinct from the ancient text itself.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "METHODOLOGICAL", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "e43e873a-1b16-4b8a-b5ef-436e30a72ea2", "field_label": "Universality of vision vs. sectarian narrowness", "parameter_id": "9c42159a-91da-4ccd-9ad9-2c5747627b7e", "parameter_name": "Inner Qualities (Rishi-specific virtues)"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Sri Aurobindo explicitly offers a psychological/spiritual interpretation of Vedic symbols, including Vishvamitra''s hymns.", "link_id": "a4ca9938-1903-44d2-8ba3-42d9d53e1778", "page_or_section": "The Secret of the Veda", "passages": [], "relationship": "supports", "source": {"author": "Sri Aurobindo", "authority_metadata": {}, "citation": "Sri Aurobindo, The Secret of the Veda. Sri Aurobindo Ashram.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Sri Aurobindo Ashram", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_book", "storage_path": null, "title": "The Secret of the Veda", "url": "https://www.sriaurobindoashram.org/sriaurobindo/downloadpdf.php?id=30"}, "source_id": "7efe2589-0b7e-4cee-bcc0-b71b0ba418e6"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('aa8b121b-a2d5-4c0d-99fa-69118c5892a6','{"approval_origin": "system_test_bulk", "certainty": "medium", "claim_id": "aa8b121b-a2d5-4c0d-99fa-69118c5892a6", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "The same Aitareya episode should not be converted into a modern equality claim: it is a specific ancient lineage narrative with its own ritual and social categories.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": null, "contract_status": "NOT_EVIDENTIARY", "epistemic_type": "METHODOLOGICAL", "proposed_type": "METHODOLOGICAL", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source", "Recorded source access issue"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "e43e873a-1b16-4b8a-b5ef-436e30a72ea2", "field_label": "Universality of vision vs. sectarian narrowness", "parameter_id": "9c42159a-91da-4ccd-9ad9-2c5747627b7e", "parameter_name": "Inner Qualities (Rishi-specific virtues)"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The text describes adoption, precedence, and family branches in its own ritual-genealogical framework.", "link_id": "e64e898f-112f-47e8-b5f6-cacaa31e9e68", "page_or_section": "Methodological caution", "passages": [], "relationship": "supports", "source": {"author": "", "authority_metadata": {}, "citation": "Aitareya Brahmana Devarata lineage passage", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IGNCA Digital Library, Government of India", "rights_or_access_note": null, "source_status": "approved", "s