insert into original_claims values ('ba717b34-55b3-43b0-b6ff-ed5b48f9f2fb','{"approval_origin": "system_test_bulk", "certainty": "medium", "claim_id": "ba717b34-55b3-43b0-b6ff-ed5b48f9f2fb", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "The Aitareya Brahmana''s adoption of Shunahshepa as Devarata shows that lineage identity in this tradition can be reorganized through ritual, declaration, and acceptance rather than being described only by biological descent.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "SCHOLARLY_INTERPRETATION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source", "Recorded source access issue"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "e43e873a-1b16-4b8a-b5ef-436e30a72ea2", "field_label": "Universality of vision vs. sectarian narrowness", "parameter_id": "9c42159a-91da-4ccd-9ad9-2c5747627b7e", "parameter_name": "Inner Qualities (Rishi-specific virtues)"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The released Shunahshepa becomes Devarata, son of Vishvamitra, and is incorporated into the family.", "link_id": "18a94f54-8920-490a-868f-074c29d6edea", "page_or_section": "Aitareya Brahmana Shunahshepa cycle", "passages": [], "relationship": "supports", "source": {"author": "", "authority_metadata": {}, "citation": "Aitareya Brahmana Shunahshepa-Devarata passage", "original_work_identity": {}, "publication_year": null, "publisher_o