insert into original_claims values ('f5739e7d-ad7c-4576-b75f-e73af013e2d7','{"approval_origin": "system_test_bulk", "certainty": "medium", "claim_id": "f5739e7d-ad7c-4576-b75f-e73af013e2d7", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "The Shanti Parva famine dialogue places Vishvamitra in serious argument with a shvapaka about dharma, survival, and prohibited food, making cross-status moral reasoning part of the narrative without erasing the text''s social hierarchy.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "SCHOLARLY_INTERPRETATION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source", "Recorded source access issue"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "e43e873a-1b16-4b8a-b5ef-436e30a72ea2", "field_label": "Universality of vision vs. sectarian narrowness", "parameter_id": "9c42159a-91da-4ccd-9ad9-2c5747627b7e", "parameter_name": "Inner Qualities (Rishi-specific virtues)"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Both speakers offer substantive arguments about right conduct during famine.", "link_id": "3ac0e89b-ebfd-41ff-a21b-3d1b02417ec8", "page_or_section": "12.142", "passages": [], "relationship": "supports", "source": {"author": "Vyasa (traditional attribution)", "authority_metadata": {}, "citation": "Mahabharata, Shanti Parva, 142", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Gita Pres