insert into original_claims values ('003a9c62-4155-458b-b5f9-af45bbc4d7b3','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "003a9c62-4155-458b-b5f9-af45bbc4d7b3", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "The narrative of the astras portrays pedagogical completeness: Vishvamitra does not stop after granting power but answers Rama''s request for the knowledge needed to withdraw it safely.", "current_status": "approved", "epistemics": {"contract_basis": "tradition", "contract_satisfied": true, "contract_status": "SUPPORTED", "epistemic_type": "TRADITIONAL_NARRATIVE", "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["Current approval origin does not establish strict verification", "Recorded source access issue"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "0471832c-9435-4ecc-8676-8f229edb045f", "field_label": "Viveka, samatva, akrodha, satya-nishtha and other evidenced virtues", "parameter_id": "9c42159a-91da-4ccd-9ad9-2c5747627b7e", "parameter_name": "Inner Qualities (Rishi-specific virtues)"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Sarga 28 supplies the withdrawal procedures after the grant of weapons.", "link_id": "14d65998-c8c9-402c-8aa4-82342584b039", "page_or_section": "1.28", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur Valmiki Ramayanam Project", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same Bala Kanda chapter is linked below; compare editions before using a quotation.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayanam, Bala Kanda, Sarga 28", "url": "https://www.valmiki.iitk.ac.in/sloka?field_kanda_tid=1&field_sarga_value=28&language=dv"}, "source_id": "7aa52a0f-84ca-425a-8671-21e4e2c4e6c0"}, {"evidence_excerpt": "Sarga 28 supplies the withdrawal procedures after the grant of weapons.", "link_id": "83d90b52-6a86-4127-a2a0-914d028838de", "page_or_section": "1.28", "passages": [{"chunk_id": "618e42b7-09de-4ee2-9794-6231f2f36deb", "confidence": 0.847272727272727, "excerpt": "Rama requests sage Vishvamitra for endowing annulment missiles, besides projectile ones  that have been accorded in the previous chapter. Sage Vishvamitra accords them, and while they are journeying  further, they chance to see a picturesque forest on their way and Rama enquires about it.  On becoming personally purified Rama, the descendent of Kakutstha-s, …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Book I : Bala Kanda - The Youthful MajestiesSarga 28 in Prose", "relationship": "supports", "section_title": "Book I : Bala Kanda - The Youthful MajestiesSarga 28 in Prose", "source_id": "b829b48c-8875-4cb2-802b-bcb274d48fa9", "textual_layer": "Ramayana — Bala Kanda"}], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution); English rendering by Desiraju Hanumanta Rao", "authority_metadata": {"verified_http_status": 200}, "citation": "Valmiki Ramayana, Bala Kanda 1.28, chapter-level prose rendering.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": "Publicly accessible chapter page; preserve source attribution and link.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayana — Bala Kanda, Sarga 28 (prose)", "url": "https://www.valmikiramayan.net