insert into original_claims values ('2f4ad300-608b-4b39-b15a-35a2f553150e','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "2f4ad300-608b-4b39-b15a-35a2f553150e", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "Vishvamitra''s affection for Rama is directly narrated after the Tataka episode and before the transmission of astras, giving textual support for warmth within the teacher-student relationship.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Recorded source access issue"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "0471832c-9435-4ecc-8676-8f229edb045f", "field_label": "Viveka, samatva, akrodha, satya-nishtha and other evidenced virtues", "parameter_id": "9c42159a-91da-4ccd-9ad9-2c5747627b7e", "parameter_name": "Inner Qualities (Rishi-specific virtues)"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The post-Tataka sequence depicts Vishvamitra pleased with and affectionate toward Rama.", "link_id": "875b09ee-60fb-454e-b812-fd8474469b5f", "page_or_section": "1.26-27", "passages": [{"chunk_id": "0d13a212-8365-4a87-8d31-4148b91f702d", "confidence": 0.874782608695652, "excerpt": "\"Lakshmana, see that yakshii''s grisly and ghastly physique, seeing which hearts of cowards are prone  to burst. She is unstoppable and has magical powers, is''t, you may see now how I will make her to  readily retreat by lopping off her ears and the tip of nose. As it is her feminineness is protecting  her, and I too I do not really attempt to kill her, but …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Book I : Bala Kanda - The Youthful Majesties\nSarga 26 in Prose", "relationship": "supports", "section_title": "Book I : Bala Kanda - The Youthful Majesties\nSarga 26 in Prose", "source_id": "20585d18-784f-4e7d-8daf-49e857c82117", "textual_layer": "Ramayana — Bala Kanda"}, {"chunk_id": "2c5b47db-6540-4f24-9cc3-6db9940c0037", "confidence": 0.846086956521739, "excerpt": "Rama encounters his first problem-female demoness Tataka, also called as Taadaka, and   eliminates her at the orders of sage Vishvamitra. This is a crucial test put to Rama by   Vishvamitra in ascertaining whether Rama is the follower of dharma through elder men''s   orders or not. Rama eradicates Tataka basing on his own self-confidence.  On hearing the …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Book I : Bala Kanda - The Youthful Majesties\nSarga 26 in Prose", "relationship": "supports", "section_title": "Book I : Bala Kanda - The Youthful Majesties\nSarga 26 in Prose", "source_id": "20585d18-784f-4e7d-8daf-49e857c82117", "textual_layer": "Ramayana — Bala Kanda"}], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution); English rendering by Desiraju Hanumanta Rao", "authority_metadata": {"verified_http_status": 200}, "citation": "Valmiki Ramayana, Bala Kanda 1.26, chapter-level prose rendering.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": "Publicly accessible chapter page; preserve source attribution and link.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayana — Bala Kanda, Sarga 26 (prose)", "url": "https://www.valmikiramayan.net/utf8/baala/sarga26/bala_26_prose.htm"},