insert into original_claims values ('5c040721-d928-4eb0-96bd-7c0c37803768','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "5c040721-d928-4eb0-96bd-7c0c37803768", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "Vishvamitra gives away all of the cooked food he was finally about to eat after a long vow.", "current_status": "approved", "epistemics": {"contract_basis": "tradition", "contract_satisfied": true, "contract_status": "SUPPORTED", "epistemic_type": "TRADITIONAL_NARRATIVE", "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["Current approval origin does not establish strict verification", "Has parent claim ID b358938a-3a13-4a7f-ac36-a1cd2a00bd59", "Retention/access rights note missing for an associated source"], "evidence_type": "traditional_narrative", "lens": {"field_id": "0471832c-9435-4ecc-8676-8f229edb045f", "field_label": "Viveka, samatva, akrodha, satya-nishtha and other evidenced virtues", "parameter_id": "9c42159a-91da-4ccd-9ad9-2c5747627b7e", "parameter_name": "Inner Qualities (Rishi-specific virtues)"}, "parent_claim_id": "b358938a-3a13-4a7f-ac36-a1cd2a00bd59", "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "This meal is prepared by Vishvamitra alone after a thousand years and such self-cooking  of food by the ascetics is called, vaishva devam, since it is a sacred  preparation anena vaishvadeva ante samaagato atithiH svayam upoShyaa api sviiya anna pradaanena  sambhojya iti suucitam - dk  तस्मैः दत्त्वा तदा सिद्धम् सर्वम् विप्राय निश्चितः | निःषेषिते अन्ने …", "link_id": "e7871de6-8def-40b4-a106-7e832a0deb56", "page_or_section": "1.65", "passages": [{"chunk_id": "d5e6cd91-c377-43d8-a3aa-a6233c8d0a82", "confidence": 0.95, "excerpt": "This meal is prepared by Vishvamitra alone after a thousand years and such self-cooking  of food by the ascetics is called, vaishva devam, since it is a sacred  preparation anena vaishvadeva ante samaagato atithiH svayam upoShyaa api sviiya anna pradaanena  sambhojya iti suucitam - dk  तस्मैः दत्त्वा तदा सिद्धम् सर्वम् विप्राय निश्चितः | निःषेषिते अन्ने …", "excerpt_truncated": true, "is_active": true, "link_method": "reconciliation_exact", "page_or_section": "Introduction", "relationship": "supports", "section_title": "Introduction", "source_id": "b1ff445c-d9d0-4f8e-a28f-f3a8053787ad", "textual_layer": "Ramayana — Bala Kanda"}], "relationship": "supports", "source": {"author": "Valmiki", "authority_metadata": {}, "citation": "Valmiki Ramayana, Bala Kanda, Sarga 65 (https://www.valmikiramayan.net/utf8/baala/sarga65/balasans65.htm.orig)", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Valmiki Ramayana, Bala Kanda, Sarga 65", "url": "https://www.valmikiramayan.net/utf8/baala/sarga65/balasans65.htm.orig"}, "source_id": "b1ff445c-d9d0-4f8e-a28f-f3a8053787ad"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('863edbcb-46dc-48f9-be88-be61f8ab6613','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "863edbcb-46dc-48f9-be88-be61f8ab6613", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "A strong evidence-based inner-quality theme is perseverance toward self-mastery: after episodes of anger and setback, the Ramayana depicts remorse, renewed restraint, further tapas, and eventual Brahmarshi recognition.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "PARTIALLY_SUPPORTED", "epistemic_type": "SYNTHETIC_INTERPRETATION", "proposed_type": "SYNTHETIC_INTERPRETATION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Current approval origin does not establish strict verification", "Recorded source access issue", "Claim-passage link points to a source absent from claim-source links"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "0471832c-9435-4ecc-8676-8f229edb045f", "field_label": "Viveka, samatva, akrodha, satya-nishtha and other evidenced virtues", "parameter_id": "9c42159a-91da-4ccd-9ad9-2c5747627b7e", "parameter_name": "Inner Qualities (Rishi-specific virtues)"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "After cursing Rambha, Vishvamitra experiences remorse and resolves to control anger.", "link_id": "aea43792-d218-4ba3-b84c-2b11bba18e57", "page_or_section": "Bala Kanda 1.64.14–18", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana, Bala Kanda 1.64. IIT Kanpur Valmiki Ramayanam.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same Bala Kanda chapter is linked below; compare editions before using a quotation.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayanam — Bala Kanda, Sarga 64", "url": "https://www.valmiki.iitk.ac.in/sloka?field_kanda_tid=1&field_sarga_value=64&language=dv"}, "source_id": "84367293-66be-4b9a-8bd2-ac2ca21fa68d"}], "unmatched_passage_links": [{"chunk_id": "2a5bae86-6077-4fd8-8d21-59b2a47b760a", "excerpt": "Vishvamitra curses Rambha, the celestial wench, knowing that she arrived at the behest of Indra to cause  hindrance to his ascesis. But later feels ashamed to loose his tongue and then he is determined to undertake  another round of ascesis to conquer is own senses.  सुरकार्यमिदं रंभे कर्तव्यं सुमहत्त्वया |लोभनं कौशिकस्येह काममोहसमन्वितम् || १-६४-१  1. …", "excerpt_truncated": true, "page_or_section": "Introduction", "relationship": "context", "source": {"author": "Valmiki", "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "title": "Valmiki Ramayana, Bala Kanda, Sarga 64", "url": "https://www.valmikiramayan.net/utf8/baala/sarga64/balasans64.htm"}, "source_id": "8d1e7888-6577-4564-b935-96ed0ae1b902"}, {"chunk_id": "515003fb-3676-4dbd-8abb-a58e725319ce", "excerpt": "Whereof you tried to entice me who am wishing to win over the wanton and wroth, you unlucky female  Rambha, thereof you will become a rocklike statued wastrel. [1-64-12]  ब्राह्मणः सुमहातेजास्तपोबलसमन्वितः |उद्धरिष्यति रंभे त्वां मत्क्रोधकलुषीकृताम् || १-६४-१३  13. rambhe = oh Rambha; sumahaatejaaH = very high resplendent one;  tapobalasamanvitaH = having …", "excerpt_truncated": true, "page_or_section": "Introduction", "relationship": "context", "source": {"author": "Valmiki", "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "title": "Valmiki Ramayana, Bala Kanda, Sarga 64", "url": "https://www.valmikiramayan.net/utf8/baala/sarga64/balasans64.htm"}, "source_id": "8d1e7888-6577-4564-b935-96ed0ae1b902"}]}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('a14fa6d2-5519-4606-9b3b-56cc3ac61dff','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "a14fa6d2-5519-4606-9b3b-56cc3ac61dff", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "Self-control is presented as an achieved goal rather than an effortless starting trait: the Rambha episode explicitly shows anger as a failure that prompts renewed discipline.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "SCHOLARLY_INTERPRETATION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "0471832c-9435-4ecc-8676-8f229edb045f", "field_label": "Viveka, samatva, akrodha, satya-nishtha and other evidenced virtues", "parameter_id": "9c42159a-91da-4ccd-9ad9-2c5747627b7e", "parameter_name": "Inner Qualities (Rishi-specific virtues)"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Vishvamitra curses Rambha in anger, regrets the loss of control, and resolves to continue austerity.", "link_id": "8a086c5e-5eda-4dab-ac65-81fcd2b96a71", "page_or_section": "1.64", "passages": [{"chunk_id": "2a5bae86-6077-4fd8-8d21-59b2a47b760a", "confidence": 0.872, "excerpt": "Vishvamitra curses Rambha, the celestial wench, knowing that she arrived at the behest of Indra to cause  hindrance to his ascesis. But later feels ashamed to loose his tongue and then he is determined to undertake  another round of ascesis to conquer is own senses.  सुरकार्यमिदं रंभे कर्तव्यं सुमहत्त्वया |लोभनं कौशिकस्येह काममोहसमन्वितम् || १-६४-१  1. …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Introduction", "relationship": "supports", "section_title": "Introduction", "source_id": "8d1e7888-6577-4564-b935-96ed0ae1b902", "textual_layer": "Ramayana — Bala Kanda"}, {"chunk_id": "515003fb-3676-4dbd-8abb-a58e725319ce", "confidence": 0.872, "excerpt": "Whereof you tried to entice me who am wishing to win over the wanton and wroth, you unlucky female  Rambha, thereof you will become a rocklike statued wastrel. [1-64-12]  ब्राह्मणः सुमहातेजास्तपोबलसमन्वितः |उद्धरिष्यति रंभे त्वां मत्क्रोधकलुषीकृताम् || १-६४-१३  13. rambhe = oh Rambha; sumahaatejaaH = very high resplendent one;  tapobalasamanvitaH = having …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Introduction", "relationship": "supports", "section_title": "Introduction", "source_id": "8d1e7888-6577-4564-b935-96ed0ae1b902", "textual_layer": "Ramayana — Bala Kanda"}], "relationship": "supports", "source": {"author": "Valmiki", "authority_metadata": {}, "citation": "Valmiki Ramayana, Bala Kanda, Sarga 64 (https://www.valmikiramayan.net/utf8/baala/sarga64/balasans64.htm)", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Valmiki Ramayana, Bala Kanda, Sarga 64", "url": "https://www.valmikiramayan.net/utf8/baala/sarga64/balasans64.htm"}, "source_id": "8d1e7888-6577-4564-b935-96ed0ae1b902"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('b358938a-3a13-4a7f-ac36-a1cd2a00bd59','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "b358938a-3a13-4a7f-ac36-a1cd2a00bd59", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "Bala Kanda 1.65 portrays generosity under deprivation when Vishvamitra gives away all of the cooked food he was finally about to eat after a long vow, while keeping his silence intact.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "SYNTHETIC_INTERPRETATION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Recorded source access issue", "Claim-passage link points to a source absent from claim-source links"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "0471832c-9435-4ecc-8676-8f229edb045f", "field_label": "Viveka, samatva, akrodha, satya-nishtha and other evidenced virtues", "parameter_id": "9c42159a-91da-4ccd-9ad9-2c5747627b7e", "parameter_name": "Inner Qualities (Rishi-specific virtues)"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The disguised Indra asks for food and Vishvamitra silently gives the entire prepared meal.", "link_id": "bf244d48-d876-4b8f-9b1c-19c9c8f95082", "page_or_section": "1.65", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur Valmiki Ramayanam Project", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same Bala Kanda chapter is linked below; compare editions before using a quotation.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayanam, Bala Kanda, Sarga 65", "url": "https://www.valmiki.iitk.ac.in/summary?field_kanda_tid=1&field_sarga_value=65"}, "source_id": "35d30c22-48b6-4242-ad17-697405136d76"}], "unmatched_passage_links": [{"chunk_id": "d5e6cd91-c377-43d8-a3aa-a6233c8d0a82", "excerpt": "This meal is prepared by Vishvamitra alone after a thousand years and such self-cooking  of food by the ascetics is called, vaishva devam, since it is a sacred  preparation anena vaishvadeva ante samaagato atithiH svayam upoShyaa api sviiya anna pradaanena  sambhojya iti suucitam - dk  तस्मैः दत्त्वा तदा सिद्धम् सर्वम् विप्राय निश्चितः | निःषेषिते अन्ने …", "excerpt_truncated": true, "page_or_section": "Introduction", "relationship": "context", "source": {"author": "Valmiki", "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "title": "Valmiki Ramayana, Bala Kanda, Sarga 65", "url": "https://www.valmikiramayan.net/utf8/baala/sarga65/balasans65.htm.orig"}, "source_id": "b1ff445c-d9d0-4f8e-a28f-f3a8053787ad"}]}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('d1be6ab1-60f7-4f74-bef4-d4045525098c','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "d1be6ab1-60f7-4f74-bef4-d4045525098c", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "The Shanti Parva famine episode portrays practical concern for survival under extreme conditions rather than idealized ascetic detachment; interpreting that response as a virtue or fault requires ethical review.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "UNSUPPORTED", "epistemic_type": "TRADITIONAL_NARRATIVE", "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source", "Recorded source access issue"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "0471832c-9435-4ecc-8676-8f229edb045f", "field_label": "Viveka, samatva, akrodha, satya-nishtha and other evidenced virtues", "parameter_id": "9c42159a-91da-4ccd-9ad9-2c5747627b7e", "parameter_name": "Inner Qualities (Rishi-specific virtues)"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Vishvamitra argues from desperate hunger and preservation of life during famine.", "link_id": "53e86cb1-4585-4f32-9887-5486d879294a", "page_or_section": "12.142", "passages": [], "relationship": "supports", "source": {"author": "Vyasa (traditional attribution)", "authority_metadata": {}, "citation": "Mahabharata, Shanti Parva, 142", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Gita Press edition / Vedapath presentation", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Mahabharata (Gita Press edition), Shanti Parva, Adhyaya 142", "url": "https://vedapath.app/en/mahabharata-gita-press/shanti-parva/142"}, "source_id": "1265258a-bc16-44e0-8c55-55ca3104767e"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('dede2f64-dbd6-424f-8ca0-a4d1564de84d','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "dede2f64-dbd6-424f-8ca0-a4d1564de84d", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "The Shunahshepa episode depicts a protective impulse toward a vulnerable petitioner, although it is combined with a severe and troubling demand made to Vishvamitra''s own sons.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "0471832c-9435-4ecc-8676-8f229edb045f", "field_label": "Viveka, samatva, akrodha, satya-nishtha and other evidenced virtues", "parameter_id": "9c42159a-91da-4ccd-9ad9-2c5747627b7e", "parameter_name": "Inner Qualities (Rishi-specific virtues)"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The text juxtaposes protection of Shunahshepa with Vishvamitra''s demand that his sons take the boy''s place.", "link_id": "f146119a-f754-4cb5-9d13-2cc9df07aaa9", "page_or_section": "1.62.4-17", "passages": [{"chunk_id": "dc4c7878-13d3-455d-94ef-43178aa33bc6", "confidence": 0.848571428571429, "excerpt": "I have no mother or a father to save me. Then wherefore cousins or relatives  will be there to protect me. Oh, peaceable saint the eminent, it will be apt of  you to protect me according to saintliness. [1-62-4b, 5a]  त्राता त्वं हि नरश्रेष्ठ सर्वेषां त्वं हि भावनः || १-६२-५ राजा च कृतकार्यः स्यादहं दीर्घायुरव्ययः | स्वर्गलोकमुपाश्नीयां तपस्तप्त्वा …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Introduction", "relationship": "supports", "section_title": "Introduction", "source_id": "4bd01c3e-d436-4013-a8a9-49d839abe475", "textual_layer": "Ramayana — Bala Kanda"}, {"chunk_id": "e4ea51bd-02c1-4363-af67-82b98757e401", "confidence": 0.848571428571429, "excerpt": "Sage Vishvamitra curses his sons as they defy his orders and accords two esoteric  hymns to Shunashepa, for chanting them in the Vedic-ritual of Ambariisha. Shunashepa  gets longevity on chanting those hymns. Thus Vishvamitra not only creates another  universe as in Trishanku''s episode, he even accords longevity, or even deathlessness  to mortals by his …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Introduction", "relationship": "supports", "section_title": "Introduction", "source_id": "4bd01c3e-d436-4013-a8a9-49d839abe475", "textual_layer": "Ramayana — Bala Kanda"}], "relationship": "supports", "source": {"author": "Valmiki", "authority_metadata": {}, "citation": "Valmiki Ramayana, Bala Kanda, Sarga 62 (https://www.valmikiramayan.net/utf8/baala/sarga62/balasans62.htm)", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Valmiki Ramayana, Bala Kanda, Sarga 62", "url": "https://www.valmikiramayan.net/utf8/baala/sarga62/balasans62.htm"}, "source_id": "4bd01c3e-d436-4013-a8a9-49d839abe475"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('e3926185-b82d-40dd-bd0c-73dbbcd1fc3e','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "e3926185-b82d-40dd-bd0c-73dbbcd1fc3e", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "Bala Kanda 1.34 depicts strong familial attachment when Vishvamitra explains that he remains near the Kausiki river because of his love for his sister Satyavati.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Recorded source access issue"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "0471832c-9435-4ecc-8676-8f229edb045f", "field_label": "Viveka, samatva, akrodha, satya-nishtha and other evidenced virtues", "parameter_id": "9c42159a-91da-4ccd-9ad9-2c5747627b7e", "parameter_name": "Inner Qualities (Rishi-specific virtues)"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Vishvamitra explicitly gives affection for his sister as the reason for staying in the Himalayan region.", "link_id": "2ec615db-ee9c-4ac1-b626-319a59ff86f0", "page_or_section": "1.34", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur Valmiki Ramayanam Project", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same Bala Kanda chapter is linked below; compare editions before using a quotation.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayanam, Bala Kanda, Sarga 34", "url": "https://www.valmiki.iitk.ac.in/summary?field_kanda_tid=1&field_sarga_value=34"}, "source_id": "8721f3dd-09b0-4df0-a874-fce53a8b5fcc"}, {"evidence_excerpt": "Vishvamitra explicitly gives affection for his sister as the reason for staying in the Himalayan region.", "link_id": "0e013633-698e-4c59-b786-a6904cea9352", "page_or_section": "1.34", "passages": [{"chunk_id": "c060e52a-01eb-48d8-947e-9c835d8da08e", "confidence": 0.943636363636364, "excerpt": "Vishvamitra narrates about the birth of Gaadhi, his own father and the son of Kushanaabha.  Incidentally he narrates about the emergence and prominence of River Kaushiki, who is Vishwamitra''s  elder sister turned out as a sacred River.  When Brahmadatta has married and left, oh, Raghava, king Kushanaabha he embarked on Vedic-ritual  called putra kaameSTHi …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Book I : Bala Kanda - The Youthful Majesties\nsarga 34 in prose", "relationship": "supports", "section_title": "Book I : Bala Kanda - The Youthful Majesties\nsarga 34 in prose", "source_id": "97d602de-f163-49e6-9d4c-fbfe076b6607", "textual_layer": "Ramayana — Bala Kanda"}], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution); English rendering by Desiraju Hanumanta Rao", "authority_metadata": {"verified_http_status": 200}, "citation": "Valmiki Ramayana, Bala Kanda 1.34, chapter-level prose rendering.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": "Publicly accessible chapter page; preserve source attribution and link.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayana — Bala Kanda, Sarga 34 (prose)", "url": "https://www.valmikiramayan.net/utf8/baala/sarga34/bala_34_prose.htm"}, "source_id": "97d602de-f163-49e6-9d4c-fbfe076b6607"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('edbb24e9-8475-4bee-9525-461f7f5eee70','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "edbb24e9-8475-4bee-9525-461f7f5eee70", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "The Galava narrative presents a mixed picture of generosity and severity: Vishvamitra first releases the student without requiring payment, but after repeated insistence imposes an extraordinarily difficult guru-dakshina.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "UNSUPPORTED", "epistemic_type": "TRADITIONAL_NARRATIVE", "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source", "Recorded source access issue"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "0471832c-9435-4ecc-8676-8f229edb045f", "field_label": "Viveka, samatva, akrodha, satya-nishtha and other evidenced virtues", "parameter_id": "9c42159a-91da-4ccd-9ad9-2c5747627b7e", "parameter_name": "Inner Qualities (Rishi-specific virtues)"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The sequence moves from release to the demand for eight hundred rare horses only after Galava persists.", "link_id": "2b7ecb64-c1cd-4c04-9878-ff05dda7a63b", "page_or_section": "5.104", "passages": [], "relationship": "supports", "source": {"author": "Vyasa (traditional attribution); BORI Critical Edition", "authority_metadata": {}, "citation": "Mahabharata BORI, Udyoga Parva, 104", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Bhandarkar Oriental Research Institute critical text / Vedapath presentation", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Mahabharata (BORI Critical Edition), Udyoga Parva, Adhyaya 104", "url": "https://vedapath.app/en/mahabharata-bori/udyoga-parva/104"}, "source_id": "855f8c75-16cc-4e96-9ba3-d79579231842"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('f5522a47-6799-4ad3-a46b-62774d6bde6e','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "f5522a47-6799-4ad3-a46b-62774d6bde6e", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "The Trishanku episode attributes a strong commitment to protecting a supplicant to Vishvamitra: after Trishanku seeks refuge, Vishvamitra insists that the person who has come to him for shelter should not be abandoned.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "SYNTHETIC_INTERPRETATION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Recorded source access issue"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "0471832c-9435-4ecc-8676-8f229edb045f", "field_label": "Viveka, samatva, akrodha, satya-nishtha and other evidenced virtues", "parameter_id": "9c42159a-91da-4ccd-9ad9-2c5747627b7e", "parameter_name": "Inner Qualities (Rishi-specific virtues)"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The refuge statement is part of Vishvamitra''s defense of taking up Trishanku''s cause.", "link_id": "3faf2c91-2b56-4955-8b38-01f20e2c18fa", "page_or_section": "1.59", "passages": [{"chunk_id": "5326a31a-1540-4cb8-bab3-96ed76b89a7a", "confidence": 0.94, "excerpt": "\"The eminent sage Vishvamitra having heard those words of the sons of Vashishta  from all of his disciples, said this rancorously with bloodshot eyes.  \" ''He who reproves me, who am abiding in rigorous ascesis, and who am an  unreprovable one by my ascetic merit, that irreverent person will be reduced to  ashes, and there is no doubt about it. Now they will …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Book I : Bala Kanda - The Youthful Majesties\n Sarga 59 in Prose", "relationship": "supports", "section_title": "Book I : Bala Kanda - The Youthful Majesties\n Sarga 59 in Prose", "source_id": "7b637414-d012-4349-9ea0-bded3c081f08", "textual_layer": "Ramayana — Bala Kanda"}, {"chunk_id": "7fa20770-91d1-4b00-a9ae-b651c966d204", "confidence": 0.88, "excerpt": "Vishvamitra undertakes Trishanku''s Vedic ritual and sends disciples   to invite all Vedic-scholars. Many sages have come except for   Vashishta and his sons. Further, the sons of Vashishta have   ridiculed this ritual of Vishvamitra and Trishanku. Vishvamitra gets   irritated and hurls curses at the sons of Vashishta.  \"Vishvamitra, the son of Kushi, …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Book I : Bala Kanda - The Youthful Majesties\n Sarga 59 in Prose", "relationship": "supports", "section_title": "Book I : Bala Kanda - The Youthful Majesties\n Sarga 59 in Prose", "source_id": "7b637414-d012-4349-9ea0-bded3c081f08", "textual_layer": "Ramayana — Bala Kanda"}], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution); English rendering by Desiraju Hanumanta Rao", "authority_metadata": {"verified_http_status": 200}, "citation": "Valmiki Ramayana, Bala Kanda 1.59, chapter-level prose rendering.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": "Publicly accessible chapter page; preserve source attribution and link.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayana — Bala Kanda, Sarga 59 (prose)", "url": "https://www.valmikiramayan.net/utf8/baala/sarga59/bala_59_prose.htm"}, "source_id": "7b637414-d012-4349-9ea0-bded3c081f08"}, {"evidence_excerpt": "The refuge statement is part of Vishvamitra''s defense of taking up Trishanku''s cause.", "link_id": "d6cb0da5-a43e-4a47-b2c2-6946b8145e3a", "page_or_section": "1.59", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur Valmiki Ramayanam Project", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same Bala Kanda chapter is linked below; compare editions before using a quotation.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayanam, Bala Kanda, Sarga 59", "url": "https://www.valmiki.iitk.ac.in/summary?field_kanda_tid=1&field_sarga_value=59"}, "source_id": "a7c009d6-db4c-405e-b465-47bdc344f5b4"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('ff09192b-7da6-4617-886a-8d18771c983a','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "ff09192b-7da6-4617-886a-8d18771c983a", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "Perseverance is strongly supported as a literary trait in the Ramayana portrayal because Vishvamitra repeatedly resumes tapas after major reversals.", "current_status": "approved", "epistemics": {"contract_basis": "interpretation", "contract_satisfied": true, "contract_status": "SUPPORTED", "epistemic_type": "SCHOLARLY_INTERPRETATION", "proposed_type": "SCHOLARLY_INTERPRETATION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "0471832c-9435-4ecc-8676-8f229edb045f", "field_label": "Viveka, samatva, akrodha, satya-nishtha and other evidenced virtues", "parameter_id": "9c42159a-91da-4ccd-9ad9-2c5747627b7e", "parameter_name": "Inner Qualities (Rishi-specific virtues)"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The final sarga follows repeated setbacks with another severe ascetic effort culminating in recognition.", "link_id": "813870d7-ee02-4a4c-ace8-34fb33045f89", "page_or_section": "1.65", "passages": [{"chunk_id": "d5e6cd91-c377-43d8-a3aa-a6233c8d0a82", "confidence": 0.844, "excerpt": "This meal is prepared by Vishvamitra alone after a thousand years and such self-cooking  of food by the ascetics is called, vaishva devam, since it is a sacred  preparation anena vaishvadeva ante samaagato atithiH svayam upoShyaa api sviiya anna pradaanena  sambhojya iti suucitam - dk  तस्मैः दत्त्वा तदा सिद्धम् सर्वम् विप्राय निश्चितः | निःषेषिते अन्ने …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Introduction", "relationship": "supports", "section_title": "Introduction", "source_id": "b1ff445c-d9d0-4f8e-a28f-f3a8053787ad", "textual_layer": "Ramayana — Bala Kanda"}], "relationship": "supports", "source": {"author": "Valmiki", "authority_metadata": {}, "citation": "Valmiki Ramayana, Bala Kanda, Sarga 65 (https://www.valmikiramayan.net/utf8/baala/sarga65/balasans65.htm.orig)", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Valmiki Ramayana, Bala Kanda, Sarga 65", "url": "https://www.valmikiramayan.net/utf8/baala/sarga65/balasans65.htm.orig"}, "source_id": "b1ff445c-d9d0-4f8e-a28f-f3a8053787ad"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('01b5d47e-4f1b-4b10-a117-512e1f1ee739','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "01b5d47e-4f1b-4b10-a117-512e1f1ee739", "claim_kind": "traditional_account", "claim_relations": [], "claim_text": "The Kama hermitage at the Sarayu-Ganga region is one of the early stops where Vishvamitra and the princes lodge after leaving Ayodhya, expanding his itinerary beyond Sarayu and Siddhashrama.", "current_status": "approved", "epistemics": {"contract_basis": "tradition", "contract_satisfied": true, "contract_status": "SUPPORTED", "epistemic_type": "TRADITIONAL_NARRATIVE", "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["Current approval origin does not establish strict verification", "Recorded source access issue"], "evidence_type": "traditional_narrative", "lens": {"field_id": "0c4a5b7d-dfe7-409c-af93-91f50cf6eb4f", "field_label": "Ashram / geographic seat and its later significance", "parameter_id": "b8062cec-c53d-45f3-a06d-fbb38116ba63", "parameter_name": "Parampara and Lineage"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Sarga 23 brings the group to the hermitage associated with Kama at the river confluence.", "link_id": "b103d6e5-4d3b-4f56-9dd2-afb44f6b548f", "page_or_section": "1.23", "passages": [{"chunk_id": "b19d7040-f437-4dee-aadd-2e43a3657117", "confidence": 0.907619047619048, "excerpt": "Then onwards Love-god is renowned as Ananga, as he is without body, and where his body  is given up that is renowned as Anga province.  \"This merited hermitage thus belongs to Shiva and, oh, brave Rama, these sages abiding  in virtue are Shiva''s disciples at one time, thus sin is unverifiable with them.  This hermitage belongs to Love God or Shiva, tasya …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Book I : Bala Kanda - The Youthful \nMajestiesSarga 23 in Prose", "relationship": "supports", "section_title": "Book I : Bala Kanda - The Youthful \nMajestiesSarga 23 in Prose", "source_id": "3e5ba864-3449-49b0-85e5-ef9e8796f620", "textual_layer": "Ramayana — Bala Kanda"}, {"chunk_id": "fcab0c80-7050-4eb3-b709-d03638794b6d", "confidence": 0.946666666666667, "excerpt": "Rama and Lakshmana proceeding with Vishvamitra sojourn in a hermitage at a place where  River Ganga and River Sarayu are confluent. Once god Shiva with his third eye burnt down the physical  entity of Manmatha, the Love-god, at this place.  At dawn after that night the great saint Vishvamitra spoke to the legatees of Kakutstha,  Rama and Lakshmana, those …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Book I : Bala Kanda - The Youthful \nMajestiesSarga 23 in Prose", "relationship": "supports", "section_title": "Book I : Bala Kanda - The Youthful \nMajestiesSarga 23 in Prose", "source_id": "3e5ba864-3449-49b0-85e5-ef9e8796f620", "textual_layer": "Ramayana — Bala Kanda"}], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution); English rendering by Desiraju Hanumanta Rao", "authority_metadata": {"verified_http_status": 200}, "citation": "Valmiki Ramayana, Bala Kanda 1.23, chapter-level prose rendering.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": "Publicly accessible chapter page; preserve source attribution and link.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayana — Bala Kanda, Sarga 23 (prose)", "url": "https://www.valmikiramayan.net/utf8/baala/sarga23/bala_23_prose.htm"}, "source_id": "3e5ba864-3449-49b0-85e5-ef9e8796f620"}, {"evidence_excerpt": "Sarga 23 brings the group to the hermitage associated with Kama at the river confluence.", "link_id": "bece89a0-1a7b-40dd-98cb-b387683bf133", "page_or_section": "1.23", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur Valmiki Ramayanam Project", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same Bala Kanda chapter is linked below; compare editions before using a quotation.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayanam, Bala Kanda, Sarga 23", "url": "https://www.valmiki.iitk.ac.in/summary?field_kanda_tid=1&field_sarga_value=23"}, "source_id": "e91df81f-65d9-4d7d-9691-d98effd0f6c4"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('11fc077a-6f10-40f7-90d3-38026f3abb9f','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "11fc077a-6f10-40f7-90d3-38026f3abb9f", "claim_kind": "traditional_account", "claim_relations": [], "claim_text": "Gautama''s hermitage is a distinct stop on Vishvamitra''s route; he intentionally brings Rama into the hermitage rather than merely passing the site.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "PARTIALLY_SUPPORTED", "epistemic_type": "SYNTHETIC_INTERPRETATION", "proposed_type": "SYNTHETIC_INTERPRETATION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Current approval origin does not establish strict verification", "Recorded source access issue", "Claim-passage link points to a source absent from claim-source links"], "evidence_type": "traditional_narrative", "lens": {"field_id": "0c4a5b7d-dfe7-409c-af93-91f50cf6eb4f", "field_label": "Ashram / geographic seat and its later significance", "parameter_id": "b8062cec-c53d-45f3-a06d-fbb38116ba63", "parameter_name": "Parampara and Lineage"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Sarga 49 locates the Ahalya episode in Gautama''s hermitage under Vishvamitra''s guidance.", "link_id": "b4dff45a-8494-40b8-9bd2-4875b3b8736c", "page_or_section": "1.49", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur Valmiki Ramayanam Project", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same Bala Kanda chapter is linked below; compare editions before using a quotation.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayanam, Bala Kanda, Sarga 49", "url": "https://www.valmiki.iitk.ac.in/summary?field_kanda_tid=1&field_sarga_value=49"}, "source_id": "acd930f8-6206-4068-8b46-c6da0ebee1c8"}], "unmatched_passage_links": [{"chunk_id": "1bec402a-35e2-4f91-8091-8a68bce7a412", "excerpt": "Oh, Raghava, owing to the efficacy of the great-souled Gautama and his ascesis,  from then onwards Indra has became one with the testes of a goat. [1-49-10]  तदागच्छ महातेज आश्रमं पुण्यकर्मणः | तारयैनां महाभागामहल्यां देवरूपिणीम् || १-४९-११  11. mahaateja = oh great-resplendent Rama; tat = therefore; puNyakarmaNaH aashramam aagacCha =  you come - enter into …", "excerpt_truncated": true, "page_or_section": "Introduction", "relationship": "context", "source": {"author": "Valmiki (traditional attribution)", "publication_year": null, "publisher_or_institution": "IIT Kanpur Valmiki Ramayanam Project", "rights_or_access_note": null, "source_status": "approved", "source_type": "primary_text", "title": "Valmiki Ramayanam 1.49 — sibling page (valmikiramayan.net)", "url": "https://valmikiramayan.net/utf8/baala/sarga49/balasans49.htm"}, "source_id": "c14e6a75-1805-4f7a-b6a7-8c79f8e2cdbc"}]}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('140b24bc-fac2-4bbc-852b-066b185f59df','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "140b24bc-fac2-4bbc-852b-066b185f59df", "claim_kind": "traditional_account", "claim_relations": [], "claim_text": "Mahabharata Shalya Parva attaches another Vishvamitra-Vasistha rivalry narrative to the Sarasvati tirtha landscape, showing a separate sacred-geography tradition outside Bala Kanda.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source", "Recorded source access issue"], "evidence_type": "traditional_narrative", "lens": {"field_id": "0c4a5b7d-dfe7-409c-af93-91f50cf6eb4f", "field_label": "Ashram / geographic seat and its later significance", "parameter_id": "b8062cec-c53d-45f3-a06d-fbb38116ba63", "parameter_name": "Parampara and Lineage"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The Vasisthapavaha story locates their neighboring hermitages and conflict by Sarasvati.", "link_id": "883cd08d-c52f-4696-84cc-c219f18aab34", "page_or_section": "Shalya Parva Vasisthapavaha", "passages": [], "relationship": "supports", "source": {"author": "Vyasa (traditional attribution); BORI Critical Edition", "authority_metadata": {}, "citation": "Mahabharata BORI, Shalya Parva", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Bhandarkar Oriental Research Institu