insert into original_claims values ('71013c24-2783-4079-88fc-1364284e2ebb','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "71013c24-2783-4079-88fc-1364284e2ebb", "claim_kind": "traditional_account", "claim_relations": [], "claim_text": "The Ramayana places Vishvamitra’s austerities at Pushkara. Such locations should be stored as textual geographies and not automatically treated as archaeologically verified residence sites.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "METHODOLOGICAL", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Recorded source access issue", "Claim-passage link points to a source absent from claim-source links"], "evidence_type": "traditional_narrative", "lens": {"field_id": "0c4a5b7d-dfe7-409c-af93-91f50cf6eb4f", "field_label": "Ashram / geographic seat and its later significance", "parameter_id": "b8062cec-c53d-45f3-a06d-fbb38116ba63", "parameter_name": "Parampara and Lineage"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Pushkara is explicitly named as a site of austerity.", "link_id": "c53e0f12-90dc-437d-822e-a972542927fd", "page_or_section": "Bala Kanda 1.62.28", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana, Bala Kanda 1.62. IIT Kanpur Valmiki Ramayanam.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur", "rights_or_access_note": "The original IITK lin