insert into original_claims values ('868ef59c-9b3b-4890-887b-2c57a0c6c2a7','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "868ef59c-9b3b-4890-887b-2c57a0c6c2a7", "claim_kind": "traditional_account", "claim_relations": [], "claim_text": "Vishala is another named stage of Vishvamitra''s route toward Mithila, where the narrative continues with teachings connected to earlier divine events.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "PARTIALLY_SUPPORTED", "epistemic_type": "TRADITIONAL_NARRATIVE", "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Current approval origin does not establish strict verification", "Recorded source access issue", "Claim-passage link points to a source absent from claim-source links"], "evidence_type": "traditional_narrative", "lens": {"field_id": "0c4a5b7d-dfe7-409c-af93-91f50cf6eb4f", "field_label": "Ashram / geographic seat and its later significance", "parameter_id": "b8062cec-c53d-45f3-a06d-fbb38116ba63", "parameter_name": "Parampara and Lineage"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The Ganga narrative transitions into the party''s movement through Vishala.", "link_id": "9f06b575-cfce-4f69-a151-a59609bae82c", "page_or_section": "1.45", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur Valmiki Ramayanam Project", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same Bala Kanda chapter is linked below; compare editions before using a quotation.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayanam, Bala Kanda, Sarga 45", "url": "https://www.valmiki.iitk.ac.in/summary?field_kanda_tid=1&field_sarga_value=45"}, "source_id": "d6c16f50-ea4b-4af0-87d6-fbabf4b1dbd3"}], "unmatched_passage_links": [{"chunk_id": "31e53319-0ea8-4b8f-851a-42ecec0fe314", "excerpt": "\"When all are wading into annihilation then the ambidextrous Vishnu swiftly impounded  Amrita, the Ambrosia, by assuming an illusory for of Mohini...  Comment: Mohini literally means ''that which bewitches...'' usually a feminine or neutral.  Here Vishnu assumed a physique of such a voluptuous and bewitching seductress, marvellously limbed,  and mantled in …", "excerpt_truncated": true, "page_or_section": "Book I : Bala \nKanda - The Youthful Majesties Sarga 45 in Prose", "relationship": "context", "source": {"author": "Valmiki (traditional attribution)", "publication_year": null, "publisher_or_institution": "IIT Kanpur Valmiki Ramayanam Project", "rights_or_access_note": null, "source_status": "approved", "source_type": "primary_text", "title": "Valmiki Ramayanam 1.45 — sibling page (valmikiramayan.net)", "url": "https://www.valmikiramayan.net/utf8/baala/sarga45/bala_45_prose.htm"}, "source_id": "dbc9191b-477d-427c-b336-43148ecd9dc0"}]}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('925113d6-b92d-497a-bd0e-ecfcc6cffa5b','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "925113d6-b92d-497a-bd0e-ecfcc6cffa5b", "claim_kind": "traditional_account", "claim_relations": [], "claim_text": "Mithila becomes the culmination of the journey''s teaching phase, with Vishvamitra moving from forest and river settings into Janaka''s royal-sacrificial court.", "current_status": "approved", "epistemics": {"contract_basis": "tradition", "contract_satisfied": true, "contract_status": "SUPPORTED", "epistemic_type": "TRADITIONAL_NARRATIVE", "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["Current approval origin does not establish strict verification", "Recorded source access issue"], "evidence_type": "traditional_narrative", "lens": {"field_id": "0c4a5b7d-dfe7-409c-af93-91f50cf6eb4f", "field_label": "Ashram / geographic seat and its later significance", "parameter_id": "b8062cec-c53d-45f3-a06d-fbb38116ba63", "parameter_name": "Parampara and Lineage"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Sarga 50 places Vishvamitra and the princes before Janaka and recounts the route that brought them there.", "link_id": "4ad83f7f-8618-45b6-94d2-10ac300c66a9", "page_or_section": "1.50", "passages": [{"chunk_id": "488dfd2b-47d8-44d7-86f8-bba5d8548695", "confidence": 0.846086956521739, "excerpt": "\"Today my Vedic ritual is enriched with your advent, whereby I deem that gods  have fructified the ritual. Let the ritual be like that. I deem that I have  obtained the fruit of the ritual just on seeing godlike you here today.  \"Oh, Brahman, at which Vedic-ritual hall you have arrived along with so many  sages that happens to be mine, whereby, oh, eminent …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Book I : Bala Kanda - The Youthful Majesties\nSarga 50 in Prose", "relationship": "supports", "section_title": "Book I : Bala Kanda - The Youthful Majesties\nSarga 50 in Prose", "source_id": "1c8e472c-d8aa-4fe2-9fca-b5b3d067165f", "textual_layer": "Ramayana — Bala Kanda"}, {"chunk_id": "60f34feb-d36a-4a60-b89c-8fd47e1c04ba", "confidence": 0.932173913043478, "excerpt": "Rama arrives at Mithila along with Lakshmana led on by Vishvamitra. On hearing that  Vishvamitra has arrived at their city Mithila, King Janaka proceeds to him welcomingly.  On seeing Rama and Lakshmana near at Vishvamitra, Janaka inquisitively asks Vishvamitra  about these two princes. Vishvamitra announces them as the sons of Dasharatha and  informs about …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Book I : Bala Kanda - The Youthful Majesties\nSarga 50 in Prose", "relationship": "supports", "section_title": "Book I : Bala Kanda - The Youthful Majesties\nSarga 50 in Prose", "source_id": "1c8e472c-d8aa-4fe2-9fca-b5b3d067165f", "textual_layer": "Ramayana — Bala Kanda"}], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution); English rendering by Desiraju Hanumanta Rao", "authority_metadata": {"verified_http_status": 200}, "citation": "Valmiki Ramayana, Bala Kanda 1.50, chapter-level prose rendering.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": "Publicly accessible chapter page; preserve source attribution and link.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayana — Bala Kanda, Sarga 50 (prose)", "url": "https://www.valmikiramayan.net/utf8/baala/sarga50/bala_50_prose.htm"}, "source_id": "1c8e472c-d8aa-4fe2-9fca-b5b3d067165f"}, {"evidence_excerpt": "Sarga 50 places Vishvamitra and the princes before Janaka and recounts the route that brought them there.", "link_id": "6933c50a-a3f7-47a4-b032-7344359a778a", "page_or_section": "1.50", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur Valmiki Ramayanam Project", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same Bala Kanda chapter is linked below; compare editions before using a quotation.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayanam, Bala Kanda, Sarga 50", "url": "https://www.valmiki.iitk.ac.in/summary?field_kanda_tid=1&field_sarga_value=50"}, "source_id": "5d691354-d41e-4e2b-8f55-8de88be0c506"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('9b38fbaa-b69d-4dfb-804c-d93e855bf18d','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "9b38fbaa-b69d-4dfb-804c-d93e855bf18d", "claim_kind": "traditional_account", "claim_relations": [], "claim_text": "Bala Kanda 1.34 links Vishvamitra personally with the Himalayan region around the river Kausiki, explaining his residence there through his affection for his sister Satyavati in the epic tradition.", "current_status": "approved", "epistemics": {"contract_basis": "tradition", "contract_satisfied": true, "contract_status": "SUPPORTED", "epistemic_type": "TRADITIONAL_NARRATIVE", "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["Current approval origin does not establish strict verification", "Recorded source access issue"], "evidence_type": "traditional_narrative", "lens": {"field_id": "0c4a5b7d-dfe7-409c-af93-91f50cf6eb4f", "field_label": "Ashram / geographic seat and its later significance", "parameter_id": "b8062cec-c53d-45f3-a06d-fbb38116ba63", "parameter_name": "Parampara and Lineage"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Vishvamitra says he dwells near the mountains because Satyavati became the Kausiki river.", "link_id": "ee8e1d1e-5b2d-493c-afea-65d7bccf365b", "page_or_section": "1.34", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur Valmiki Ramayanam Project", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same Bala Kanda chapter is linked below; compare editions before using a quo