insert into original_claims values ('9fceb517-48f7-4dcf-8441-78dd274c31d3','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "9fceb517-48f7-4dcf-8441-78dd274c31d3", "claim_kind": "traditional_account", "claim_relations": [], "claim_text": "Vishvamitra identifies the confluence of the Sarayu and Ganga and uses it as a teaching point about sacred rivers during the journey.", "current_status": "approved", "epistemics": {"contract_basis": "tradition", "contract_satisfied": true, "contract_status": "SUPPORTED", "epistemic_type": "TRADITIONAL_NARRATIVE", "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["Current approval origin does not establish strict verification", "Recorded source access issue"], "evidence_type": "traditional_narrative", "lens": {"field_id": "0c4a5b7d-dfe7-409c-af93-91f50cf6eb4f", "field_label": "Ashram / geographic seat and its later significance", "parameter_id": "b8062cec-c53d-45f3-a06d-fbb38116ba63", "parameter_name": "Parampara and Lineage"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Sarga 24 explains the river confluence to Rama and Lakshmana.", "link_id": "789c236a-43b6-4546-97ce-7a30f8b654b2", "page_or_section": "1.24", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur Valmiki Ramayanam Project", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same Bala Kanda chapter is linked below; compare editions before using a quotation.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayanam, Bala Kanda, Sarga 24", "url": "https://www.valmiki.iitk.ac.in/summary?field_kanda_tid=1&field_sarga_value=24"}, "source_id": "0333872b-78c3-458b-81d4-39f890b5a400"}, {"evidence_excerpt": "Sarga 24 explains the river confluence to Rama and Lakshmana.", "link_id": "35c4007a-8a53-4904-8dd7-b801d58b42ae", "page_or_section": "1.24", "passages": [{"chunk_id": "ec0ac32a-ede9-42a8-ac78-dcb0d578d54c", "confidence": 0.96, "excerpt": "While crossing over the River Ganga, sage Vishvamitra sails them through its confluence  with River Sarayu, which flows at their capital Ayodhya. The sage leads them to a deadly forest on the  other bank of River Ganga and narrates about the ambushing nature of demoness Tataka, preparing him  to kill her.  Then, in the fresh of the morning those enemy …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Book I : Bala Kanda - The Youthful \nMajestiesSarga 24  in Prose", "relationship": "supports", "section_title": "Book I : Bala Kanda - The Youthful \nMajestiesSarga 24  in Prose", "source_id": "ca29e431-b425-45c2-9399-21c10c2d25ba", "textual_layer": "Ramayana — Bala Kanda"}], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution); English rendering by Desiraju Hanumanta Rao", "authority_metadata": {"verified_http_status": 200}, "citation": "Valmiki Ramayana, Bala Kanda 1.24, chapter-level prose rendering.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": "Publicly accessible chapter page; preserve source attribution and link.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayana — Bala Kanda, Sarga 24 (prose)", "url": "https://www.valmikiramayan.net/utf8/baala/sarga24/bala_24_prose.htm"}, "source_id": "ca29e431-b425-45c2-9399-21c10c2d25ba"}], "unmatched_passage_links": []}'::jsonb,'ap