insert into original_claims values ('bf2a8831-bb66-4186-98ca-4e0d51e4054a','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "bf2a8831-bb66-4186-98ca-4e0d51e4054a", "claim_kind": "traditional_account", "claim_relations": [], "claim_text": "The Ganga itself is not merely crossed in Vishvamitra''s journey: the party bathes and performs rites there before he narrates its sacred history.", "current_status": "approved", "epistemics": {"contract_basis": "tradition", "contract_satisfied": true, "contract_status": "SUPPORTED", "epistemic_type": "TRADITIONAL_NARRATIVE", "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["Current approval origin does not establish strict verification", "Recorded source access issue"], "evidence_type": "traditional_narrative", "lens": {"field_id": "0c4a5b7d-dfe7-409c-af93-91f50cf6eb4f", "field_label": "Ashram / geographic seat and its later significance", "parameter_id": "b8062cec-c53d-45f3-a06d-fbb38116ba63", "parameter_name": "Parampara and Lineage"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Sarga 35 combines travel, ritual action, and narration at the river.", "link_id": "80a0003c-daa6-418b-bb78-29bacf70e20b", "page_or_section": "1.35", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur Valmiki Ramayanam Project", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same Bala Kanda chapter is linked below; compare editions before using a quotation.", "source_status": "approved", "source_type": "primary_text", "s