insert into original_claims values ('da2f1e6f-07c7-4df4-a3e9-8ca154a5b17d','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "da2f1e6f-07c7-4df4-a3e9-8ca154a5b17d", "claim_kind": "traditional_account", "claim_relations": [], "claim_text": "At the end of the Bala Kanda sequence, Vishvamitra takes leave and departs toward the northern mountains, showing that the epic does not confine him to a single permanent seat.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "traditional_narrative", "lens": {"field_id": "0c4a5b7d-dfe7-409c-af93-91f50cf6eb4f", "field_label": "Ashram / geographic seat and its later significance", "parameter_id": "b8062cec-c53d-45f3-a06d-fbb38116ba63", "parameter_name": "Parampara and Lineage"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Sarga 74.1 says Vishvamitra departs for the northern mountains after the Mithila events.", "link_id": "b8bfe80a-9ac4-4139-be43-98f17fb13d5d", "page_or_section": "1.74.1", "passages": [{"chunk_id": "c14197c2-5339-4c55-aa09-7d6d165943ad", "confidence": 0.85, "excerpt": "5b, 6a. raajaa  = king Janaka;   susamhR^iSTaH  = very highly  gladdened; hiraNyasya = of gold; suvarNasya = of silver; muktaanaam =  of pearls; vidrumasya ca = red corals, even; anuttamam = beau idéal;   kanyaadhanam = bridal riches; dadau = he gave.  King Janaka gave beau idéal bridal riches in gold, silver, pearls and corals even,  for he is very highly …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Introduction", "relationship": "supports", "section_title": "Introduction", "source_id": "582a2381-dc45-429d-a615-f021939714cb", "textual_layer": "Ramayana — Bala Kanda"}, {"chunk_id": "d2971222-8d87-4bae-a49a-935718f3f74a", "confidence": 0.91, "excerpt": "Parashu Rama confronts the wedding party that is returning to Ayodhya from  Mithila. On his very entry, the atmosphere becomes pell-mell and a whirlwind ensues.  Expecting some problem from this Parashu Rama, the sages like Vashishta and others starts  to receive him in a peaceable manner. Not caring anyone around Parashu Rama starts a  dialogue with …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Introduction", "relationship": "supports", "section_title": "Introduction", "source_id": "582a2381-dc45-429d-a615-f021939714cb", "textual_layer": "Ramayana — Bala Kanda"}], "relationship": "supports", "source": {"author": "Valmiki", "authority_metadata": {}, "citation": "Valmiki Ramayana, Bala Kanda, Sarga 74 (https://www.valmikiramayan.net/utf8/baala/sarga74/balasans74.htm)", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Valmiki Ramayana, Bala Kanda, Sarga 74", "url": "https://www.valmikiramayan.net/utf8/baala/sarga74/balasans74.htm"}, "source_id": "582a2381-dc45-429d-a615-f021939714cb"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('f6e90959-0378-40bc-a8d3-31cb060f148a','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "f6e90959-0378-40bc-a8d3-31cb060f148a", "claim_kind": "traditional_account", "claim_relations": [], "claim_text": "Siddhashrama is a major location in Vishvamitra''s Ramayana role: he brings Rama and Lakshmana there and explains its sacred history.", "current_status": "approved", "epistemics": {"contract_basis": "tradition", "contract_satisfied": true, "contract_status": "SUPPORTED", "epistemic_type": "TRADITIONAL_NARRATIVE", "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "traditional_narrative", "lens": {"field_id": "0c4a5b7d-dfe7-409c-af93-91f50cf6eb4f", "field_label": "Ashram / geographic seat and its later significance", "parameter_id": "b8062cec-c53d-45f3-a06d-fbb38116ba63", "parameter_name": "Parampara and Lineage"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Sarga 29 identifies Siddhashrama and places Vishvamitra there with the princes and resident sages.", "link_id": "bd5d8ac0-586e-4305-a7f6-4b72bc377662", "page_or_section": "1.29", "passages": [{"chunk_id": "aa32ff19-8d5e-4696-ac02-020c336fa4e6", "confidence": 0.918823529411765, "excerpt": "\"This hermitage which at one time is presided by Vishnu, is an eradicator   of stress, either the stress and strain caused by the evil on earth,   or the stress of going through the cycle of birth and death, thus this   hermitage is an accorded of salvation, and I am also beneficed with   this hermitage owing to my devotion to Vaamana. [1-29-22]  …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Introduction", "relationship": "supports", "section_title": "Introduction", "source_id": "588fb085-d2af-42be-9eca-bf08c63060d6", "textual_layer": "Ramayana — Bala Kanda"}, {"chunk_id": "faf89375-2fcd-47d3-b5f9-66a6fd896f4e", "confidence": 0.887058823529412, "excerpt": "यथार्हं चक्रिरे पूजां विश्वामित्राय धीमते |  तथैव राजपुत्राभ्यामकुर्वन्नतिथिक्रियाम् || १-२९-२७  27. dhiimate vishvaamitraaya = to sagacious Vishvamitra;  yathaarham puujaam cakrire = offered reverence as deservedly;  tathaa eva = like, that; raajaputraabhyaam= for two princes;  atithikriyaam akurvan = they made [offered] guest works [reception] .  Those …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Introduction", "relationship": "supports", "section_title": "Introduction", "source_id": "588fb085-d2af-42be-9eca-bf08c63060d6", "textual_layer": "Ramayana — Bala Kanda"}], "relationship": "supports", "source": {"author": "Valmiki", "authority_metadata": {}, "citation": "Valmiki Ramayana, Bala Kanda, Sarga 29 (https://www.valmikiramayan.net/utf8/baala/sarga29/balasans29.htm)", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Valmiki Ramayana, Bala Kanda, Sarga 29", "url": "https://www.valmikiramayan.net/utf8/baala/sarga29/balasans29.htm"}, "source_id": "588fb085-d2af-42be-9eca-bf08c63060d6"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('282b4a26-7155-4cb3-81e9-ab1d10244ab8','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "282b4a26-7155-4cb3-81e9-ab1d10244ab8", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "The division between Vishvamitra''s sons who accept Devarata and those who reject his precedence is preserved as a lineage-making event in the Aitareya Brahmana.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "PARTIALLY_SUPPORTED", "epistemic_type": "TRADITIONAL_NARRATIVE", "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source", "Recorded source access issue", "Claim-passage link points to a source absent from claim-source links"], "evidence_type": "traditional_narrative", "lens": {"field_id": "aaef870f-643c-4889-8e16-7ee162486a6b", "field_label": "Gotra founded or continued", "parameter_id": "b8062cec-c53d-45f3-a06d-fbb38116ba63", "parameter_name": "Parampara and Lineage"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The story organizes branches of the family through the sons'' responses to Devarata.", "link_id": "e192a9f9-663d-4247-85ec-a5340259b5d1", "page_or_section": "Aitareya Brahmana Devarata section", "passages": [], "relationship": "supports", "source": {"author": "", "authority_metadata": {}, "citation": "Aitareya Brahmana Devarata lineage passage", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IGNCA Digital Library, Government of India", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Aitareya Brahmana / related Indian edition, Devarata lineage passage", "url": "https://ignca.gov.in/Asi_data/24136.pdf"}, "source_id": "56d9174f-e2bb-487a-b201-8eb56236df04"}], "unmatched_passage_links": [{"chunk_id": "af480590-dc3c-4f84-9c69-7a30b3df0970", "excerpt": "9:10  17  (Sunahsepa is Released. He Invents the Aiijtxh Sava Preparation of the Soma, V ii&imitra Adopts him a; hit San. Shtiuas.)  The priests now said to fhupakjepa, ** Thou art now only ours (thou art now a priest like us); take part in the performance of the particular ceremonies of this day (the abifeehauijya He then saw (invented) the method of …", "excerpt_truncated": true, "page_or_section": "p. 320 (scan page 175)", "relationship": "context", "source": {"author": "", "publication_year": null, "publisher_or_institution": "IGNCA Digital Library, Government of India", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "title": "Aitareya Brahmana of the Rigveda vol.2 — repository scan copy (in.gov.ignca.24136)", "url": "https://archive.org/details/in.gov.ignca.24136"}, "source_id": "a5105f0d-6f88-4d51-a6e7-1a4daac3a1da"}, {"chunk_id": "b66ef3b1-4c79-42a7-a6f2-6a14624ae868", "excerpt": "jnira ; that is, it appears to refer to Sudas''s campaign against Sariivarana westwards into the Panjab. These considerations corroborate the point that Sudas''s first priest was Vasistha, that Yasistha^s son Sakti was killed through Visvamitra''s instigation, and that ultimately Vasistha departed to Sariivarana and Visvamitra became Sudas''s priest.^ Manu''s …", "excerpt_truncated": true, "page_or_section": "p. 237 (scan leaf 249)", "relationship": "context", "source": {"author": "F. E. Pargiter", "publication_year": 1922, "publisher_or_institution": "Oxford University Press (London: Humphrey Milford)", "rights_or_access_note": "Rights-clear public-domain scan (archive.org item metadata: NOT_IN_COPYRIGHT; scanned by University of Toronto Robarts Library). Only pages naming Vishvamitra and relevant to approved claims were ingested.", "source_status": "approved", "source_type": "scholarly_book", "title": "Ancient Indian Historical Tradition", "url": "https://archive.org/details/ancientindianhis00parguoft"}, "source_id": "70bed1d6-b121-41fb-9ec4-650a746f154c"}]}'::jsonb,'approved','system_test_bulk');
