insert into original_claims values ('abeca18e-c146-4f95-a996-fa30c63f4a54','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "abeca18e-c146-4f95-a996-fa30c63f4a54", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "Mahabharata Adi Parva genealogy calls Shakuntala the daughter of Vishvamitra, making Bharata a grandson of Vishvamitra within that epic lineage tradition.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source", "Recorded source access issue"], "evidence_type": "traditional_narrative", "lens": {"field_id": "aaef870f-643c-4889-8e16-7ee162486a6b", "field_label": "Gotra founded or continued", "parameter_id": "b8062cec-c53d-45f3-a06d-fbb38116ba63", "parameter_name": "Parampara and Lineage"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Verse 1.90.30 identifies Shakuntala as Vishvamitra''s daughter and Bharata as her son by Dushyanta.", "link_id": "c7e7bc4e-2b61-498a-b2fc-65a57045061f", "page_or_section": "1.90.30", "passages": [{"chunk_id": "b240b588-247f-4b52-b144-d2bc945e7701", "confidence": 0.855294117647059, "excerpt": "रेतोधाः पुत्र उन्नयति नरदेव यमक्षयात् । त्वं चास्य धाता गर्भस्य सत्यमाह शकुन्तला  ‘O king, the son—born of a man’s seed—raises him beyond the condition of Yama (death). And you are indeed the begetter of this pregnancy; Śakuntalā speaks the truth.’  From that, he came to be known as ‘Bharata’.  भरतः खलु काशेयीमुपयेमे सार्वसेनीं सुनन्दां नाम । तस्यामस्य …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Shlokas", "relationship": "supports", "section_title": "Shlokas", "source_id": "976f33cf-1de6-4118-b64f-c07b7a358389", "textual_layer": "Mahabharata tradition"}, {"chunk_id": "c93b8ceb-826c-4dc9-b6cc-adb66be98503", "confidence": 0.887058823529412, "excerpt": "Ādi Parva, Adhyāya 90 — Pūror Vaṃśa, Kuru-Pravara, and the Janamejaya Line (Genealogical Recitation)  Upa-parva: Anuvaṃśa (Pūru–Kuru Vaṃśānukīrtana) — Dynastic Genealogy and Legitimacy Discourse  This chapter begins with Janamejaya asking for a fuller account of his ancestors, saying that a condensed telling does not satisfy his longing for the sacred …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Adhyaya 90", "relationship": "supports", "section_title": "Adhyaya 90", "source_id": "976f33cf-1de6-4118-b64f-c07b7a358389", "textual_layer": "Mahabharata tradition"}], "relationship": "supports", "source": {"author": "Vyasa (traditional attribution); BORI Critical Edition", "authority_metadata": {}, "citation": "Mahabharata BORI, Adi Parva, 90", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Bhandarkar Oriental Research Institute critical text / Vedapath presentation", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Mahabharata (BORI Critical Edition), Adi Parva, Adhyaya 90", "url": "https://vedapath.app/en/mahabharata-bori/adi-parva/90"}, "source_id": "976f33cf-1de6-4118-b64f-c07b7a358389"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
