insert into original_claims values ('178faf90-3962-4fa1-9a17-e72cf51d35a3','{"approval_origin": "system_test_bulk", "certainty": "medium", "claim_id": "178faf90-3962-4fa1-9a17-e72cf51d35a3", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "Rama actively asks Vishvamitra for the knowledge needed to withdraw the astras, showing a dialogic student role rather than merely passive reception of gifts.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "PARTIALLY_SUPPORTED", "epistemic_type": "SYNTHETIC_INTERPRETATION", "proposed_type": "SYNTHETIC_INTERPRETATION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["Current approval origin does not establish strict verification", "Recorded source access issue"], "evidence_type": "traditional_narrative", "lens": {"field_id": "8f38ab86-8c89-4c6a-a344-dfb0005d8abe", "field_label": "Guru (if known) and disciples", "parameter_id": "b8062cec-c53d-45f3-a06d-fbb38116ba63", "parameter_name": "Parampara and Lineage"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Sarga 28 opens with Rama asking his preceptor for methods of withdrawal.", "link_id": "852ee45f-7d23-4580-9d64-990ea8e66aa5", "page_or_section": "1.28", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur Valmiki Ramayanam Project", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same Bala Kanda chapter is linked below; compare editions before using a quotation.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayanam, Bala Kanda, Sarga 28", "url": "https://www.valmiki.iitk.ac.in/sloka?field_kanda_tid=1&field_sarga_value=28&language=dv"}, "source_id": "7aa52a0f-84ca-425a-8671-21e4e2c4e6c0"}, {"evidence_excerpt": "Sarga 28 opens with Rama asking his preceptor for methods of withdrawal.", "link_id": "0f1562b0-4bc4-4290-8650-c17f5e4a8fde", "page_or_section": "1.28", "passages": [{"chunk_id": "618e42b7-09de-4ee2-9794-6231f2f36deb", "confidence": 0.846086956521739, "excerpt": "Rama requests sage Vishvamitra for endowing annulment missiles, besides projectile ones  that have been accorded in the previous chapter. Sage Vishvamitra accords them, and while they are journeying  further, they chance to see a picturesque forest on their way and Rama enquires about it.  On becoming personally purified Rama, the descendent of Kakutstha-s, …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Book I : Bala Kanda - The Youthful MajestiesSarga 28 in Prose", "relationship": "supports", "section_title": "Book I : Bala Kanda - The Youthful MajestiesSarga 28 in Prose", "source_id": "b829b48c-8875-4cb2-802b-bcb274d48fa9", "textual_layer": "Ramayana — Bala Kanda"}], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution); English rendering by Desiraju Hanumanta Rao", "authority_metadata": {"verified_http_status": 200}, "citation": "Valmiki Ramayana, Bala Kanda 1.28, chapter-level prose rendering.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": "Publicly accessible chapter page; preserve source attribution and link.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayana — Bala Kanda, Sarga 28 (prose)", "url": "https://www.valmikiramayan.net/utf8/baala/sarga28/bala_28_prose.htm"}, "source_id": "b829b48c-8875-4cb2-802b-b