insert into original_claims values ('59c517e4-43e6-4dc8-a5fb-a83ca3e0ba0d','{"approval_origin": "system_test_bulk", "certainty": "medium", "claim_id": "59c517e4-43e6-4dc8-a5fb-a83ca3e0ba0d", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "The reviewed primary sources in this set do not establish a named human guru who initiated Vishvamitra into a formal lineage; claims of a specific guru require additional sourcing.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "UNSUPPORTED", "epistemic_type": "TRADITIONAL_NARRATIVE", "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "traditional_narrative", "lens": {"field_id": "8f38ab86-8c89-4c6a-a344-dfb0005d8abe", "field_label": "Guru (if known) and disciples", "parameter_id": "b8062cec-c53d-45f3-a06d-fbb38116ba63", "parameter_name": "Parampara and Lineage"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The Bala Kanda transformation narrative emphasizes tapas and interactions with Vasistha/Brahma rather than a clearly named initiating guru.", "link_id": "097b1ef4-fd50-4b78-8e8c-8c92e44e37ab", "page_or_section": "Source-limit statement", "passages": [], "relationship": "supports", "source": {"author": "Valmiki", "authority_metadata": {}, "citation": "Valmiki Ramayana, Bala Kanda, Sarga 65 (https://www.valmikiramayan.net/utf8/baala/sarga65/balasans65.htm.orig)", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_not