insert into original_claims values ('76129959-eef3-4292-89a0-0f85704e541f','{"approval_origin": "system_test_bulk", "certainty": "medium", "claim_id": "76129959-eef3-4292-89a0-0f85704e541f", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "The Mahabharata Galava cycle eventually links Vishvamitra to Ashtaka as a son born from Madhavi, meaning the same story combines guru-disciple obligation with a genealogical extension of Vishvamitra''s line.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source", "Recorded source access issue"], "evidence_type": "traditional_narrative", "lens": {"field_id": "8f38ab86-8c89-4c6a-a344-dfb0005d8abe", "field_label": "Guru (if known) and disciples", "parameter_id": "b8062cec-c53d-45f3-a06d-fbb38116ba63", "parameter_name": "Parampara and Lineage"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The concluding Galava-Madhavi sequence has Vishvamitra accept Madhavi and father Ashtaka before releasing her.", "link_id": "58ac524f-dd7f-49bc-be41-e188d4c10b83", "page_or_section": "Udyoga Parva, Galava-Madhavi conclusion", "passages": [], "relationship": "supports", "source": {"author": "Vyasa (traditional attribution); BORI Critical Edition", "authority_metadata": {}, "citation": "Mahabharata BORI, Udyoga Parva", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Bhandarkar Oriental Research Institute critical text / Vedapath presentation", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Mahabharata (BORI Critical Edition), Udyoga Parva", "url": "https://vedapath.app/en/mahabharata-bori/udyoga-parva"}, "source_id": "c3dbce9c-6c8c-4e2c-923b-c0394ecc916c"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('786d7110-5c53-4c4b-a4d1-e5fc3132fa3b','{"approval_origin": "system_test_bulk", "certainty": "medium", "claim_id": "786d7110-5c53-4c4b-a4d1-e5fc3132fa3b", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "The Aitareya Brahmana does more than describe Shunahshepa as a beneficiary: after release he becomes Devarata and is taken as Vishvamitra''s son, creating an adoptive lineage relationship.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "PARTIALLY_SUPPORTED", "epistemic_type": "TRADITIONAL_NARRATIVE", "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source", "Recorded source access issue", "Claim-passage link points to a source absent from claim-source links"], "evidence_type": "traditional_narrative", "lens": {"field_id": "8f38ab86-8c89-4c6a-a344-dfb0005d8abe", "field_label": "Guru (if known) and disciples", "parameter_id": "b8062cec-c53d-45f3-a06d-fbb38116ba63", "parameter_name": "Parampara and Lineage"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Shunahshepa stands by Vishvamitra and is identified thereafter as Devarata, son of Vishvamitra.", "link_id": "8043f188-7e24-4d9c-95e6-e0e252e6287e", "page_or_section": "Aitareya Brahmana Shunahshepa cycle", "passages": [], "relationship": "supports", "source": {"author": "", "authority_metadata": {}, "citation": "Aitareya Brahmana Shunahshepa-Devarata passage", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IGNCA Digital Library, Governm