insert into original_claims values ('7ba43136-895b-4e78-a5a6-74ca4b738d75','{"approval_origin": "system_test_bulk", "certainty": "medium", "claim_id": "7ba43136-895b-4e78-a5a6-74ca4b738d75", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "Bala Kanda explicitly places Rama in a student relationship to Vishvamitra when he receives Bala and Atibala and performs guru duties afterward.", "current_status": "approved", "epistemics": {"contract_basis": "tradition", "contract_satisfied": true, "contract_status": "SUPPORTED", "epistemic_type": "TRADITIONAL_NARRATIVE", "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "traditional_narrative", "lens": {"field_id": "8f38ab86-8c89-4c6a-a344-dfb0005d8abe", "field_label": "Guru (if known) and disciples", "parameter_id": "b8062cec-c53d-45f3-a06d-fbb38116ba63", "parameter_name": "Parampara and Lineage"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The chapter narrates initiation into Bala/Atibala and Rama''s subsequent guru-service.", "link_id": "4187bff2-770c-4b04-ad03-bf18a1f07e38", "page_or_section": "1.22.11-22", "passages": [{"chunk_id": "6e846439-227f-40f0-9421-4bab574c778b", "confidence": 0.918823529411765, "excerpt": "21b, 22. bhuurivikramaH = one with marvellous valiance; Rama;  vidyaasamuditaH = on obtaining teachings; kushikaatmaje =   in respect of Vishvamitra; sarvaaNi gurukaaryaaNi = all, teacher''s   works - works to be done in respect of teacher; niyujya = on performing;  sharadi = in autumn; sahasrarashmiH bhagavaan = thousand rayed,   god; divaakaraH iva = sun, …", "excerpt_truncated": true, "is_active": true