insert into original_claims values ('b821092f-d062-4d44-a760-59f68ba3fbe5','{"approval_origin": "system_test_bulk", "certainty": "medium", "claim_id": "b821092f-d062-4d44-a760-59f68ba3fbe5", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "In the Aitareya version Vishvamitra orders his existing sons to recognize Devarata''s precedence, so discipleship/adoption also becomes an issue of succession inside the Vishvamitra family.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "PARTIALLY_SUPPORTED", "epistemic_type": "TRADITIONAL_NARRATIVE", "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source", "Recorded source access issue", "Claim-passage link points to a source absent from claim-source links"], "evidence_type": "traditional_narrative", "lens": {"field_id": "8f38ab86-8c89-4c6a-a344-dfb0005d8abe", "field_label": "Guru (if known) and disciples", "parameter_id": "b8062cec-c53d-45f3-a06d-fbb38116ba63", "parameter_name": "Parampara and Lineage"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The sons are directed to accept Devarata as their leader; responses divide the lineage.", "link_id": "c75be132-ccd3-4ec6-bd53-1270604fc6bc", "page_or_section": "Aitareya Brahmana Devarata section", "passages": [], "relationship": "supports", "source": {"author": "", "authority_metadata": {}, "citation": "Aitareya Brahmana Devarata lineage passage", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IGNCA Digital Library, Government of India", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Aitareya Brahmana / related Indian edition, Devarata lineage passage", "url": "https://ignca.gov.in/Asi_data/24136.pdf"}, "source_id": "56d9174f-e2bb-487a-b201-8eb56236df04"}], "unmatched_passage_links": [{"chunk_id": "9c1bade2-fdf8-4702-b4d5-9125e7a3bdb1", "excerpt": "322  \" Yo sous of GtUhi, blessed with children, you nil will be successful when headed by Devarnla; he will (always) lead you on the path of truth.\"  “ This Devswkta, is your master (man); follow him, ye Koshkas! He will exercise the paternal rights over yon os his heritage from me, and hake possession of the sacred knowledge that we have.\"  “ All the true …", "excerpt_truncated": true, "page_or_section": "p. 322 (scan page 177)", "relationship": "context", "source": {"author": "", "publication_year": null, "publisher_or_institution": "IGNCA Digital Library, Government of India", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "title": "Aitareya Brahmana of the Rigveda vol.2 — repository scan copy (in.gov.ignca.24136)", "url": "https://archive.org/details/in.gov.ignca.24136"}, "source_id": "a5105f0d-6f88-4d51-a6e7-1a4daac3a1da"}]}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('b8f844d3-900f-43b3-9f59-6000e38a86ec','{"approval_origin": "system_test_bulk", "certainty": "medium", "claim_id": "b8f844d3-900f-43b3-9f59-6000e38a86ec", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "Lakshmana accompanies Rama under Vishvamitra''s guidance throughout the same journey, although the transmission scene addresses Rama most directly.", "current_status": "approved", "epistemics": {"contract_basis": "tradition", "contract_satisfied": true, "contract_status": "SUPPORTED", "epistemic_type": "TRADITIONAL_NARRATIVE", "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "traditional_narrative", "lens": {"field_id": "8f38ab86-8c89-4c6a-a344-dfb0005d8abe", "field_label": "Guru (if known) and disciples", "parameter_id": "b8062cec-c53d-45f3-a06d-fbb38116ba63", "parameter_name": "Parampara and Lineage"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Rama and Lakshmana travel behind Vishvamitra; the chapter commentary treats both princes as students in the journey.", "link_id": "b31d2c6e-8c75-4529-bf6e-d9ff9ff691a1", "page_or_section": "1.22", "passages": [{"chunk_id": "3e790a17-403e-47fd-b349-d85f9c4d92bd", "confidence": 0.907619047619048, "excerpt": "King Dasharatha sends Rama and Lakshmana along with Sage Vishvamitra as requested   by the sage. In their course of travel, Sage Vishvamitra imparts a secret knowledge   to the young princes Rama and Lakshmana, called bala-atibala-   vidya-s, by practicing which nothing can wither their vigour and vitality.  तथा वसिष्ठे ब्रुवति राजा दशरथः स्वयम् |  …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Introduction", "relationship": "supports", "section_title": "Introduction", "source_id": "4772171e-b53b-4ae5-9ffa-e6edf7a8f9de", "textual_layer": "Ramayana — Bala Kanda"}, {"chunk_id": "6e846439-227f-40f0-9421-4bab574c778b", "confidence": 0.907619047619048, "excerpt": "21b, 22. bhuurivikramaH = one with marvellous valiance; Rama;  vidyaasamuditaH = on obtaining teachings; kushikaatmaje =   in respect of Vishvamitra; sarvaaNi gurukaaryaaNi = all, teacher''s   works - works to be done in respect of teacher; niyujya = on performing;  sharadi = in autumn; sahasrarashmiH bhagavaan = thousand rayed,   god; divaakaraH iva = sun, …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Introduction", "relationship": "supports", "section_title": "Introduction", "source_id": "4772171e-b53b-4ae5-9ffa-e6edf7a8f9de", "textual_layer": "Ramayana — Bala Kanda"}], "relationship": "supports", "source": {"author": "Valmiki", "authority_metadata": {}, "citation": "Valmiki Ramayana, Bala Kanda, Sarga 22 (https://www.valmikiramayan.net/utf8/baala/sarga22/balasans22.htm)", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Valmiki Ramayana, Bala Kanda, Sarga 22", "url": "https://www.valmikiramayan.net/utf8/baala/sarga22/balasans22.htm"}, "source_id": "4772171e-b53b-4ae5-9ffa-e6edf7a8f9de"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('b981e4dc-19db-4efd-a927-33a26e7ca058','{"approval_origin": "system_test_bulk", "certainty": "medium", "claim_id": "b981e4dc-19db-4efd-a927-33a26e7ca058", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "Vishvamitra initially tells Galava that his service is sufficient and releases him, before Galava''s repeated insistence causes the guru-dakshina demand to be stated.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "UNSUPPORTED", "epistemic_type": "TRADITIONAL_NARRATIVE", "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source", "Recorded source access issue"], "evidence_type": "traditional_narrative", "lens": {"field_id": "8f38ab86-8c89-4c6a-a344-dfb0005d8abe", "field_label": "Guru (if known) and disciples", "parameter_id": "b8062cec-c53d-45f3-a06d-fbb38116ba63", "parameter_name": "Parampara and Lineage"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The narrative sequence distinguishes release from the later demand generated by insistence.", "link_id": "8c17d852-a05a-4eca-8804-9a414723f9a0", "page_or_section": "5.104", "passages": [], "relationship": "supports", "source": {"author": "Vyasa (traditional attribution); BORI Critical Edition", "authority_metadata": {}, "citation": "Mahabharata BORI, Udyoga Parva, 104", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Bhandarkar Oriental Research Institute critical text / Vedapath presentation", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Mahabharata (BORI Critical Edition), Udyoga Parva, Adhyaya 104", "url": "https://vedapath.app/en/mahabharata-bori/udyoga-parva/104"}, "source_id": "855f8c75-16cc-4e96-9ba3-d79579231842"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('bc2b59e2-d9ff-4d95-908e-9dc0e491b2ed','{"approval_origin": "system_test_bulk", "certainty": "medium", "claim_id": "bc2b59e2-d9ff-4d95-908e-9dc0e491b2ed", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "The post-Tataka scene describes Vishvamitra''s affection toward Rama before he transfers the celestial weapons, adding an explicitly relational dimension to their teacher-student bond.", "current_status": "approved", "epistemics": {"contract_basis": "tradition", "contract_satisfied": true, "contract_status": "SUPPORTED", "epistemic_type": "TRADITIONAL_NARRATIVE", "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["Current approval origin does not establish strict verification", "Recorded source access issue"], "evidence_type": "traditional_narrative", "lens": {"field_id": "8f38ab86-8c89-4c6a-a344-dfb0005d8abe", "field_label": "Guru (if known) and disciples", "parameter_id": "b8062cec-c53d-45f3-a06d-fbb38116ba63", "parameter_name": "Parampara and Lineage"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "After the Tataka episode the narrative depicts Vishvamitra warmly rewarding Rama with further knowledge.", "link_id": "529b24cf-e2b9-4701-8c4d-6adcfaa04663", "page_or_section": "1.26-27", "passages": [{"chunk_id": "2c5b47db-6540-4f24-9cc3-6db9940c0037", "confidence": 0.843076923076923, "excerpt": "Rama encounters his first problem-female demoness Tataka, also called as Taadaka, and   eliminates her at the orders of sage Vishvamitra. This is a crucial test put to Rama by   Vishvamitra in ascertaining whether Rama is the follower of dharma through elder men''s   orders or not. Rama eradicates Tataka basing on his own self-confidence.  On hearing the …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Book I : Bala Kanda - The Youthful Majesties\nSarga 26 in Prose", "relationship": "supports", "section_title": "Book I : Bala Kanda - The Youthful Majesties\nSarga 26 in Prose", "source_id": "20585d18-784f-4e7d-8daf-49e857c82117", "textual_layer": "Ramayana — Bala Kanda"}, {"chunk_id": "d16508d6-1660-4988-b84f-4fd1d2b71a40", "confidence": 0.870769230769231, "excerpt": "These are the sons like missiles of Krishaashava Prajaapati. About them, the divine weaponry and  their birth, c.f. 21st sarga/chapter, verse 10 to 20.  \"Rama is steadfast in following your assignments and thus he is the worthy receiver of those  missiles, and this prince has to accomplish a very great deed of gods.” So said gods to Vishvamitra.  All the …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Book I : Bala Kanda - The Youthful Majesties\nSarga 26 in Prose", "relationship": "supports", "section_title": "Book I : Bala Kanda - The Youthful Majesties\nSarga 26 in Prose", "source_id": "20585d18-784f-4e7d-8daf-49e857c82117", "textual_layer": "Ramayana — Bala Kanda"}], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution); English rendering by Desiraju Hanumanta Rao", "authority_metadata": {"verified_http_status": 200}, "citation": "Valmiki Ramayana, Bala Kanda 1.26, chapter-level prose rendering.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": "Publicly accessible chapter page; preserve source attribution and link.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayana — Bala Kanda, Sarga 26 (prose)", "url": "https://www.valmikiramayan.net/utf8/baala/sarga26/bala_26_prose.htm"}, "source_id": "20585d18-784f-4e7d-8daf-49e857c82117"}, {"evidence_excerpt": "After the Tataka episode the narrative depicts Vishvamitra warmly rewarding Rama with further knowledge.", "link_id": "b76bb62d-c963-4d4d-a31b-07c287386221", "page_or_section": "1.26-27", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur Valmiki Ramayanam Project", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same Bala Kanda chapter is linked below; compare editions before using a quotation.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayanam, Bala Kanda, Sarga 26", "url": "https://www.valmiki.iitk.ac.in/summary?field_kanda_tid=1&field_sarga_value=26"}, "source_id": "52fd4b07-98c1-4502-b0b4-3adadf160d62"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('d9dca12d-f5e9-4f01-8a68-5d72d022c18b','{"approval_origin": "system_test_bulk", "certainty": "medium", "claim_id": "d9dca12d-f5e9-4f01-8a68-5d72d022c18b", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "Shunahshepa approaches Vishvamitra for protection and receives ritual hymns from him, creating another mentor-protégé relationship in the epic narrative.", "current_status": "approved", "epistemics": {"contract_basis": "tradition", "contract_satisfied": true, "contract_status": "SUPPORTED", "epistemic_type": "TRADITIONAL_NARRATIVE", "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "traditional_narrative", "lens": {"field_id": "8f38ab86-8c89-4c6a-a344-dfb0005d8abe", "field_label": "Guru (if known) and disciples", "parameter_id": "b8062cec-c53d-45f3-a06d-fbb38116ba63", "parameter_name": "Parampara and Lineage"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Shunahshepa appeals to Vishvamitra for protection; Vishvamitra later gives him hymns for the sacrifice.", "link_id": "7e9ce186-413a-4652-a841-6b1e601b6b01", "page_or_section": "1.62.4-18", "passages": [{"chunk_id": "90006a17-a967-4741-b750-d7d0a4a667c8", "confidence": 0.884444444444444, "excerpt": "When Shunashepa is tied to ritual post he immensely pleased two gods, namely Indra  and Upendra as well, with those two hymns he got from Vishvamitra. [1-62-25]  ततः प्रीतः सहस्राक्षो रहस्यस्तुतितोषितः | दीर्घमायुस्तदा प्रादाच्छुनःशेपाय राघव || १-६२-२६  26. raaghava = oh Raghava; tataH = then; rahasyastutitoSitaH  = who is satisfied by esoteric laudation; …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Introduction", "relationship": "supports", "section_title": "Introduction", "source_id": "4bd01c3e-d436-4013-a8a9-49d839abe475", "textual_layer": "Ramayana — Bala Kanda"}, {"chunk_id": "e4ea51bd-02c1-4363-af67-82b98757e401", "confidence": 0.915555555555556, "excerpt": "Sage Vishvamitra curses his sons as they defy his orders and accords two esoteric  hymns to Shunashepa, for chanting them in the Vedic-ritual of Ambariisha. Shunashepa  gets longevity on chanting those hymns. Thus Vishvamitra not only creates another  universe as in Trishanku''s episode, he even accords longevity, or even deathlessness  to mortals by his …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Introduction", "relationship": "supports", "section_title": "Introduction", "source_id": "4bd01c3e-d436-4013-a8a9-49d839abe475", "textual_layer": "Ramayana — Bala Kanda"}], "relationship": "supports", "source": {"author": "Valmiki", "authority_metadata": {}, "citation": "Valmiki Ramayana, Bala Kanda, Sarga 62 (https://www.valmikiramayan.net/utf8/baala/sarga62/balasans62.htm)", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Valmiki Ramayana, Bala Kanda, Sarga 62", "url": "https://www.valmikiramayan.net/utf8/baala/sarga62/balasans62.htm"}, "source_id": "4bd01c3e-d436-4013-a8a9-49d839abe475"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('debdd225-2480-4d3d-9a59-fc5450c2feaa','{"approval_origin": "system_test_bulk", "certainty": "medium", "claim_id": "debdd225-2480-4d3d-9a59-fc5450c2feaa", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "The Aitareya text blesses the sons who accept Devarata and condemns those who resist, creating a lineage-memory explanation for internal branches of the Vishvamitra family.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "PARTIALLY_SUPPORTED", "epistemic_type": "TRADITIONAL_NARRATIVE", "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source", "Recorded source access issue", "Claim-passage link points to a source absent from claim-source links"], "evidence_type": "traditional_narrative", "lens": {"field_id": "8f38ab86-8c89-4c6a-a344-dfb0005d8abe", "field_label": "Guru (if known) and disciples", "parameter_id": "b8062cec-c53d-45f3-a06d-fbb38116ba63", "parameter_name": "Parampara and Lineage"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The Devarata section distinguishes accepting and resisting sons and their consequences.", "link_id": "427eab1c-11ee-432c-af6a-653147a9ba1d", "page_or_section": "Aitareya Brahmana Devarata section", "passages": [], "relationship": "supports", "source": {"author": "", "authority_metadata": {}, "citation": "Aitareya Brahmana Devarata lineage passage", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IGNCA Digital Library, Government of India", "rights_or_acc