insert into original_claims values ('f559c932-9c89-4f8f-bab0-371d9b95b97e','{"approval_origin": "system_test_bulk", "certainty": "medium", "claim_id": "f559c932-9c89-4f8f-bab0-371d9b95b97e", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "The selected sources do not securely identify a guru for Vishvamitra. The Ramayana clearly portrays him as a teacher of Rama and Lakshmana.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Recorded source access issue", "Claim-passage link points to a source absent from claim-source links"], "evidence_type": "traditional_narrative", "lens": {"field_id": "8f38ab86-8c89-4c6a-a344-dfb0005d8abe", "field_label": "Guru (if known) and disciples", "parameter_id": "b8062cec-c53d-45f3-a06d-fbb38116ba63", "parameter_name": "Parampara and Lineage"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Vishvamitra explicitly gives Rama the Bala and Atibala mantras.", "link_id": "b69faba5-3fb1-4fc4-abe1-dcb0a398f47a", "page_or_section": "Bala Kanda 1.22.12 onward", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana, Bala Kanda 1.22. IIT Kanpur Valmiki Ramayanam.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same Bala Kanda chapter is linked below; compare editions before using a quotation.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayanam — Bala Kanda, Sarga 22", "url": "https://www.valmiki.iitk.ac.in/sloka?field_kanda_tid=1&field_sarga_value=22&language=dv"}, "source_id": "1b4c231b-8eda-4bda-b817-a5fc93481511"}], "unmatched_passage_links": [{"chunk_id": "271446df-1b16-4af1-b22d-f06365591e27", "excerpt": "गृहाण वत्स सलिलं मा भूत् कालस्य पर्ययः || १-२२-११  मंत्रग्रामं गृहाण त्वं बलामतिबलां तथा |  11b, 12a. vatsa salilam gR^ihaaNa = my boy, you take water; tvam   tathaa = you, like that; mantragraamam = group of hymns; balaam   atibalaam = bala, atibala hymns; gR^ihaaNa = receive; kaalasya   paryayaH maa bhuut = not let there be time''s lapse.  \" \"Take water, …", "excerpt_truncated": true, "page_or_section": "Introduction", "relationship": "context", "source": {"author": "Valmiki", "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "title": "Valmiki Ramayana, Bala Kanda, Sarga 22", "url": "https://www.valmikiramayan.net/utf8/baala/sarga22/balasans22.htm"}, "source_id": "4772171e-b53b-4ae5-9ffa-e6edf7a8f9de"}, {"chunk_id": "6e846439-227f-40f0-9421-4bab574c778b", "excerpt": "21b, 22. bhuurivikramaH = one with marvellous valiance; Rama;  vidyaasamuditaH = on obtaining teachings; kushikaatmaje =   in respect of Vishvamitra; sarvaaNi gurukaaryaaNi = all, teacher''s   works - works to be done in respect of teacher; niyujya = on performing;  sharadi = in autumn; sahasrarashmiH bhagavaan = thousand rayed,   god; divaakaraH iva = sun, …", "excerpt_truncated": true, "page_or_section": "Introduction", "relationship": "context", "source": {"author": "Valmiki", "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "title": "Valmiki Ramayana, Bala Kanda, Sarga 22", "url": "https://www.valmikiramayan.net/utf8/baala/sarga22/balasans22.htm"}, "source_id": "4772171e-b53b-4ae5-9ffa-e6edf7a8f9de"}]}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('ffcc8e6e-758f-4c3b-9a4a-e27c98ac2b53','{"approval_origin": "system_test_bulk", "certainty": "medium", "claim_id": "ffcc8e6e-758f-4c3b-9a4a-e27c98ac2b53", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "Vasistha''s reassurance to Dasharatha treats Vishvamitra as sufficiently capable to protect and advance Rama even before Rama has demonstrated martial expertise, revealing recognized trust in Vishvamitra as preceptor.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "PARTIALLY_SUPPORTED", "epistemic_type": "SYNTHETIC_INTERPRETATION", "proposed_type": "SYNTHETIC_INTERPRETATION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["Current approval origin does not establish strict verification", "Recorded source access issue"], "evidence_type": "traditional_narrative", "lens": {"field_id": "8f38ab86-8c89-4c6a-a344-dfb0005d8abe", "field_label": "Guru (if known) and disciples", "parameter_id": "b8062cec-c53d-45f3-a06d-fbb38116ba63", "parameter_name": "Parampara and Lineage"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Vasistha argues that Rama will be safe under Kausika and that Vishvamitra seeks Rama''s fame.", "link_id": "9e53c638-c71a-42c2-8af1-5630e6fa7cac", "page_or_section": "1.21", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur Valmiki Ramayanam Project", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same Bala Kanda chapter is linked below; compare editions before using a quotation.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayanam, Bala Kanda, Sarga 21", "url": "https://www.valmiki.iitk.ac.in/summary?field_kanda_tid=1&field_sarga_value=21"}, "source_id": "0537c002-ff50-437a-88f6-1ca1f43572cf"}, {"evidence_excerpt": "Vasistha argues that Rama will be safe under Kausika and that Vishvamitra seeks Rama''s fame.", "link_id": "74c8fbba-94ba-47ea-98f4-c004604480f2", "page_or_section": "1.21", "passages": [{"chunk_id": "16e8b4c0-c2b9-44bb-b4df-2f3f97395940", "confidence": 0.873333333333333, "excerpt": "\"All the missiles known to Vishvamitra are the highly righteous children of Krishaasva  Prajapati, where Prajapati-s were the earliest ruler of mankind, and god Shiva gave them to Vishvamitra  when was ruling kingdom. Those missiles are the sons of Daksha Prajaapati''s daughters and her husband  Krishaasva Prajapati, and they are disparate in their form, …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Valmiki Ramayana - Bala Kanda in \nProse Sarga 21", "relationship": "supports", "section_title": "Valmiki Ramayana - Bala Kanda in \nProse Sarga 21", "source_id": "9227358e-67a7-46f5-a873-bb5582ebb893", "textual_layer": "Ramayana — Bala Kanda"}, {"chunk_id": "eb13ef00-ba13-431c-9957-e70d915433bf", "confidence": 0.845, "excerpt": "The ire of sage Vishvamitra is shown at king Dasharatha. To pacify sage Vishvamitra,  sage Vashishta intervenes and convinces king Dasharatha to send Rama with sage Vishvamitra. While doing  so, sage Vashishta enumerates the capabilities of sage Vishvamitra, his knowledge of weaponry. Vashishta  also suggests that all those weapons will be given to Rama, if …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Valmiki Ramayana - Bala Kanda in \nProse Sarga 21", "relationship": "supports", "section_title": "Valmiki Ramayana - Bala Kanda in \nProse Sarga 21", "source_id": "9227358e-67a7-46f5-a873-bb5582ebb893", "textual_layer": "Ramayana — Bala Kanda"}], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution); English rendering by Desiraju Hanumanta Rao", "authority_metadata": {"verified_http_status": 200}, "citation": "Valmiki Ramayana, Bala Kanda 1.21, chapter-level prose rendering.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": "Publicly accessible chapter page; preserve source attribution and link.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayana — Bala Kanda, Sarga 21 (prose)", "url": "https://www.valmikiramayan.net/utf8/baala/sarga21/bala_21_prose.htm"}, "source_id": "9227358e-67a7-46f5-a873-bb5582ebb893"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('0207c641-72a8-456d-ad19-97221c8b97e6','{"approval_origin": "imported_existing", "certainty": "high", "claim_id": "0207c641-72a8-456d-ad19-97221c8b97e6", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "Rigveda 3.62.10 invokes Savitar’s radiance and asks that it impel or guide human thought/intellect. Within the Vishvamitra textual corpus, this is a central spiritual-intellectual motif grounded directly in the mantra.", "current_status": "approved", "epistemics": {"contract_basis": "tradition", "contract_satisfied": true, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source", "Claim-passage link points to a source absent from claim-source links"], "evidence_type": "traditional_narrative", "lens": {"field_id": "300f5dd0-5491-4da5-8bd0-ce8a5d1c4cbb", "field_label": "Core teaching or metaphysical insight distinctively associated with the Rishi", "parameter_id": "4faa5bc1-1b4d-4c48-a26a-cd1b111232e0", "parameter_name": "Philosophical / Doctrinal Position"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Savitar is the deity for the relevant verses and the mantra centers on divine radiance and dhi.", "link_id": "b5562bae-ace7-4c95-9c6e-16f801a1566c", "page_or_section": "Rigveda 3.62.10", "passages": [{"chunk_id": "dbcfbb5a-8120-4b13-9f5a-9d266e46e0d0", "confidence": 0.74, "excerpt": "Hindi Translation by Pt. Sripada Damodara Satavalekar  English Translation by H.H. Wilson  Commentary of Sayanacharya", "excerpt_truncated": false, "is_active": true, "link_method": "single_chunk_curated_source", "page_or_section": "Links", "relationship": "supports", "section_title": "Links", "source_id": "c2d10c6c-8da2-4f5a-becf-93b160eb267b", "textual_layer": "Rigveda — Mandala 3, Sukta 62"}], "relationship": "supports", "source": {"author": "Traditional Vedic text", "authority_metadata": {}, "citation": "Rigveda 3.62, Shakala Samhita. Vedic Heritage Portal.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Vedic Heritage Portal, IGNCA, Ministry of Culture, Government of India", "rights_or_access_note": null, "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Rigveda Shakala Samhita — Mandala 3, Sukta 62", "url": "https://vedicheritage.gov.in/hi/samhitas/rigveda/shakala-samhita/rigveda-shakala-samhita-mandal-03-sukta-062/"}, "source_id": "c2d10c6c-8da2-4f5a-becf-93b160eb267b"}], "unmatched_passage_links": [{"chunk_id": "dd375eab-f1d4-4ae5-ba56-333acb244fb0", "excerpt": "तत्सवितुर्वरेण्यं भर्गो देवस्य धीमहि । धियो यो नः प्रचोदयात् tatsaviturvareṇyaṃ bhargo devasya dhīmahi | dhiyo yo naḥ pracodayāt May we attain that excellent glory of Savitar the God: So May he stimulate our prayers.", "excerpt_truncated": false, "page_or_section": "3.62.10", "relationship": "context", "source": {"author": null, "publication_year": null, "publisher_or_institution": null, "rights_or_access_note": null, "source_status": "approved", "source_type": "primary_text", "title": "Maṇḍala 3 — 62 hymns of the Viśvāmitra family (incl. Gāyatrī) — Rigveda — Swaveda", "url": "https://www.swaveda.com/texts/rigveda/3/"}, "source_id": "681b7993-1899-497d-864c-287d302819ec"}]}'::jsonb,'approved','imported_existing');
insert into original_claims values ('20323952-4f89-4e5d-b034-a1fb74461c33','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "20323952-4f89-4e5d-b034-a1fb74461c33", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "Bala Kanda 1.24 has Vishvamitra instruct the princes to honor the confluence of the Sarayu and Ganga, embedding reverence toward sacred geography in his teaching role.", "current_status": "approved", "epistemics": {"contract_basis": "tradition", "contract_satisfied": true, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Recorded source access issue"], "evidence_type": "traditional_narrative", "lens": {"field_id": "300f5dd0-5491-4da5-8bd0-ce8a5d1c4cbb", "field_label": "Core teaching or metaphysical insight distinctively associated with the Rishi", "parameter_id": "4faa5bc1-1b4d-4c48-a26a-cd1b111232e0", "parameter_name": "Philosophical / Doctrinal Position"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Vishvamitra explains the river confluence and directs Rama and Lakshmana in appropriate reverence.", "link_id": "fb00e770-3251-471b-a253-07c5d8ef533d", "page_or_section": "1.24", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur Valmiki Ramayanam Project", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same Bala Kanda chapter is linked below; compare editions before using a quotation.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayanam, Bala Kanda, Sarga 24", "url": "https://www.valmiki.iitk.ac.in/summary?field_kanda_tid=1&field_sarga_value=24"}, "source_id": "0333872b-78c3-458b-81d4-39f890b5a400"}, {"evidence_excerpt": "Vishvamitra explains the river confluence and directs Rama and Lakshmana in appropriate reverence.", "link_id": "6a17609a-4ce5-43dd-8adb-9b9eb354fa75", "page_or_section": "1.24", "passages": [{"chunk_id": "76d47139-2b81-4cb8-ba5e-62ea2cdbe778", "confidence": 0.82, "excerpt": "\"Indeed, none is able to enter this sort of province, Rama, destroyed by the hazardous  and invincible unearthly being who turned into a demoness, namely Tataka, hence you have to make the  provinces habitable.  \"As to how that ghoulish Tataka destroyed this entire forest, rendering it as a devastated  place, without refraining from it even today, all that …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Book I : Bala Kanda - The Youthful \nMajestiesSarga 24  in Prose", "relationship": "supports", "section_title": "Book I : Bala Kanda - The Youthful \nMajestiesSarga 24  in Prose", "source_id": "ca29e431-b425-45c2-9399-21c10c2d25ba", "textual_layer": "Ramayana — Bala Kanda"}, {"chunk_id": "ec0ac32a-ede9-42a8-ac78-dcb0d578d54c", "confidence": 0.95, "excerpt": "While crossing over the River Ganga, sage Vishvamitra sails them through its confluence  with River Sarayu, which flows at their capital Ayodhya. The sage leads them to a deadly forest on the  other bank of River Ganga and narrates about the ambushing nature of demoness Tataka, preparing him  to kill her.  Then, in the fresh of the morning those enemy …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Book I : Bala Kanda - The Youthful \nMajestiesSarga 24  in Prose", "relationship": "supports", "section_title": "Book I : Bala Kanda - The Youthful \nMajestiesSarga 24  in Prose", "source_id": "ca29e431-b425-45c2-9399-21c10c2d25ba", "textual_layer": "Ramayana — Bala Kanda"}], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution); English rendering by Desiraju Hanumanta Rao", "authority_metadata": {"verified_http_status": 200}, "citation": "Valmiki Ramayana, Bala Kanda 1.24, chapter-level prose rendering.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": "Publicly accessible chapter page; preserve source attribution and link.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayana — Bala Kanda, Sarga 24 (prose)", "url": "https://www.valmikiramayan.net/utf8/baala/sarga24/bala_24_prose.htm"}, "source_id": "ca29e431-b425-45c2-9399-21c10c2d25ba"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('2ec8306d-1812-4c0c-92fb-6634082e1c8c','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "2ec8306d-1812-4c0c-92fb-6634082e1c8c", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "In Shanti Parva, even after deciding to use otherwise forbidden food, Vishvamitra first attempts to incorporate it into rites for the gods and ancestors; the narrative therefore frames his emergency reasoning as an effort to preserve ritual obligation under crisis.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source", "Recorded source access issue"], "evidence_type": "traditional_narrative", "lens": {"field_id": "300f5dd0-5491-4da5-8bd0-ce8a5d1c4cbb", "field_label": "Core teaching or metaphysical insight distinctively associated with the Rishi", "parameter_id": "4faa5bc1-1b4d-4c48-a26a-cd1b111232e0", "parameter_name": "Philosophical / Doctrinal Position"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Verses later in the chapter describe him preparing ritual offerings before eating.", "link_id": "84c1a2a5-5932-488c-a7ae-b9f16e18cab4", "page_or_section": "12.142.93-96", "passages": [], "relationship": "supports", "source": {"author": "Vyasa (traditional attribution)", "authority_metadata": {}, "citation": "Mahabharata, Shanti Parva, 142", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Gita Press edition / Vedapath presentation", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Mahabharata (Gita Press edition), Shanti Parva, Adhyaya 142", "url": "https://vedapath.app/en/mahabharata-gita-press/shanti-parva/142"}, "source_id": "1265258a-bc16-44e0-8c55-55ca3104767e"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('3b81fde2-868b-4112-99a0-c2438b0b18e7','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "3b81fde2-868b-4112-99a0-c2438b0b18e7", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "The Galava story makes excessive insistence itself part of the moral frame: Vishvamitra initially releases Galava, but the student''s repeated insistence on guru-dakshina leads to the near-impossible horse demand.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "UNSUPPORTED", "epistemic_type": "TRADITIONAL_NARRATIVE", "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source", "Recorded source access issue"], "evidence_type": "traditional_narrative", "lens": {"field_id": "300f5dd0-5491-4da5-8bd0-ce8a5d1c4cbb", "field_label": "Core teaching or metaphysical insight distinctively associated with the Rishi", "parameter_id": "4faa5bc1-1b4d-4c48-a26a-cd1b111232e0", "parameter_name": "Philosophical / Doctrinal Position"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Udyoga 5.104 is introduced as an exemplum concerning harmful obstinate insistence (nirbandha).", "link_id": "5461505f-f04a-4305-8d6a-732d32dc1296", "page_or_section": "5.104", "passages": [], "relationship": "supports", "source": {"author": "Vyasa (traditional attribution); BORI Critical Edition", "authority_metadata": {}, "citation": "Mahabharata BORI, Udyoga Parva, 104", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Bhandarkar Oriental Research Institute critical text / Vedapath presentation", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Mahabharata (BORI Critical Edition), Udyoga Parva, Adhyaya 104", "url": "https://vedapath.app/en/mahabharata-bori/udyoga-parva/104"}, "source_id": "855f8c75-16cc-4e96-9ba3-d79579231842"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('3fdd1f6a-ece1-4b4b-a2e8-d810a849e204','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "3fdd1f6a-ece1-4b4b-a2e8-d810a849e204", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "In the Trishanku cycle Vishvamitra states that one who has come to him for refuge should not be abandoned, giving the episode an explicit refuge-protection principle even though the wider story remains ethically complex.", "current_status": "approved", "epistemics": {"contract_basis": "tradition", "contract_satisfied": true, "contract_status": "SUPPORTED", "epistemic_type": "TRADITIONAL_NARRATIVE", "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["Current approval origin does not establish strict verification", "Recorded source access issue"], "evidence_type": "traditional_narrative", "lens": {"field_id": "300f5dd0-5491-4da5-8bd0-ce8a5d1c4cbb", "field_label": "Core teaching or metaphysical insight distinctively associated with the Rishi", "parameter_id": "4faa5bc1-1b4d-4c48-a26a-cd1b111232e0", "parameter_name": "Philosophical / Doctrinal Position"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Vishvamitra defends his commitment to Trishanku after the king seeks his protection.", "link_id": "2d669357-3865-4a3d-af2d-fdffeff252c5", "page_or_section": "1.59", "passages": [{"chunk_id": "5326a31a-1540-4cb8-bab3-96ed76b89a7a", "confidence": 0.846086956521739, "excerpt": "\"The eminent sage Vishvamitra having heard those words of the sons of Vashishta  from all of his disciples, said this rancorously with bloodshot eyes.  \" ''He who reproves me, who am abiding in rigorous ascesis, and who am an  unreprovable one by my ascetic merit, that irreverent person will be reduced to  ashes, and there is no doubt about it. Now they will …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Book I : Bala Kanda - The Youthful Majesties\n Sarga 59 in Prose", "relationship": "supports", "section_title": "Book I : Bala Kanda - The Youthful Majesties\n Sarga 59 in Prose", "source_id": "7b637414-d012-4349-9ea0-bded3c081f08", "textual_layer": "Ramayana — Bala Kanda"}, {"chunk_id": "7fa20770-91d1-4b00-a9ae-b651c966d204", "confidence": 0.903478260869565, "excerpt": "Vishvamitra undertakes Trishanku''s Vedic ritual and sends disciples   to invite all Vedic-scholars. Many sages have come except for   Vashishta and his sons. Further, the sons of Vashishta have   ridiculed this ritual of Vishvamitra and Trishanku. Vishvamitra gets   irritated and hurls curses at the sons of Vashishta.  \"Vishvamitra, the son of Kushi, …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Book I : Bala Kanda - The Youthful Majesties\n Sarga 59 in Prose", "relationship": "supports", "section_title": "Book I : Bala Kanda - The Youthful Majesties\n Sarga 59 in Prose", "source_id": "7b637414-d012-4349-9ea0-bded3c081f08", "textual_layer": "Ramayana — Bala Kanda"}], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution); English rendering by Desiraju Hanumanta Rao", "authority_metadata": {"verified_http_status": 200}, "citation": "Valmiki Ramayana, Bala Kanda 1.59, chapter-level prose rendering.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": "Publicly accessible chapter page; preserve source attribution and link.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayana — Bala Kanda, Sarga 59 (prose)", "url": "https://www.valmikiramayan.net/utf8/baala/sarga59/bala_59_prose.htm"}, "source_id": 