insert into original_claims values ('6237bce9-cc10-42c3-8421-1f83604af642','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "6237bce9-cc10-42c3-8421-1f83604af642", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "The river dialogue of Rigveda 3.33 can be read textually as negotiated speech: request, resistance, praise, and accommodation unfold through dialogue rather than force, without requiring a modern ethical theory to be projected onto it.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "UNSUPPORTED", "epistemic_type": "NORMATIVE_RELEVANCE", "proposed_type": "NORMATIVE_RELEVANCE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source", "Recorded source access issue"], "evidence_type": "traditional_narrative", "lens": {"field_id": "300f5dd0-5491-4da5-8bd0-ce8a5d1c4cbb", "field_label": "Core teaching or metaphysical insight distinctively associated with the Rishi", "parameter_id": "4faa5bc1-1b4d-4c48-a26a-cd1b111232e0", "parameter_name": "Philosophical / Doctrinal Position"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The hymn preserves alternating speech between the human speaker and the rivers around passage.", "link_id": "ec332b71-fe3e-4334-b36e-8ec3e3fbd50e", "page_or_section": "RV 3.33", "passages": [], "relationship": "supports", "source": {"author": "", "authority_metadata": {}, "citation": "Rigveda Mandala 3 translation edition", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IGNCA Digital Library, Government of India", "