insert into original_claims values ('7179ac2d-207b-4509-bcb4-465d21533301','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "7179ac2d-207b-4509-bcb4-465d21533301", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "After the brahma-danda defeat Vishvamitra explicitly concludes that brahma-tejas is superior to kshatriya force and changes the goal of his life toward attainment through tapas.", "current_status": "approved", "epistemics": {"contract_basis": "tradition", "contract_satisfied": true, "contract_status": "SUPPORTED", "epistemic_type": "TRADITIONAL_NARRATIVE", "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["Current approval origin does not establish strict verification", "Recorded source access issue"], "evidence_type": "traditional_narrative", "lens": {"field_id": "300f5dd0-5491-4da5-8bd0-ce8a5d1c4cbb", "field_label": "Core teaching or metaphysical insight distinctively associated with the Rishi", "parameter_id": "4faa5bc1-1b4d-4c48-a26a-cd1b111232e0", "parameter_name": "Philosophical / Doctrinal Position"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Verses 1.56.23-24 contain Vishvamitra''s own stated conclusion and resolve.", "link_id": "0c25f68c-2294-465e-91d5-cbf8e21ab7d0", "page_or_section": "1.56.23-24", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur Valmiki Ramayanam Project", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same Bala Kanda chapter is linked below; compare editions before us