insert into original_claims values ('10feff07-2e7e-44e7-af77-2780a905e89e','{"approval_origin": "system_test_bulk", "certainty": "medium", "claim_id": "10feff07-2e7e-44e7-af77-2780a905e89e", "claim_kind": "uncertain", "claim_relations": [], "claim_text": "The later Arsheya Upanishad moves the Vishvamitra name into explicitly Vedantic conversation about Atman and ultimate reality, demonstrating reception history rather than a direct continuation of Mandala 3''s ritual-poetic setting.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "PARTIALLY_SUPPORTED", "epistemic_type": "SYNTHETIC_INTERPRETATION", "proposed_type": "SYNTHETIC_INTERPRETATION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "uncertain", "lens": {"field_id": "fc3c24fb-b9f5-48a9-abf4-3e65ec920fdc", "field_label": "Relationship to major currents such as Vedanta, Samkhya, Mimamsa, etc.", "parameter_id": "4faa5bc1-1b4d-4c48-a26a-cd1b111232e0", "parameter_name": "Philosophical / Doctrinal Position"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The portal calls the text a later Vedantic Upanishad and summarizes its Atman teaching.", "link_id": "9d697ab1-d4f2-4f0a-aeae-9301b0b11b71", "page_or_section": "Arsheya Upanishad overview", "passages": [{"chunk_id": "2d2aac38-e6ad-4b85-b8a5-5c566247b921", "confidence": 0.868571428571429, "excerpt": "Ārṣeya Upaniṣad is not considered as a principal Upaniṣad of Vedic Literature but it is recognised as a significant Upaniṣad among the ‘Vedānta-Upanis̩ads’ of comparatively later times. Later Upaniṣads were developed to propound the concepts of certain 