insert into original_claims values ('3b730549-f714-4956-8602-e26a519d208f','{"approval_origin": "system_test_bulk", "certainty": "medium", "claim_id": "3b730549-f714-4956-8602-e26a519d208f", "claim_kind": "uncertain", "claim_relations": [], "claim_text": "The earliest Vishvamitra material in this corpus belongs to the Rigvedic ritual-poetic world; the Ramayana material presents a later epic-ascetic portrait.", "current_status": "approved", "epistemics": {"contract_basis": "tradition", "contract_satisfied": true, "contract_status": "SUPPORTED", "epistemic_type": "TRADITIONAL_NARRATIVE", "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "uncertain", "lens": {"field_id": "fc3c24fb-b9f5-48a9-abf4-3e65ec920fdc", "field_label": "Relationship to major currents such as Vedanta, Samkhya, Mimamsa, etc.", "parameter_id": "4faa5bc1-1b4d-4c48-a26a-cd1b111232e0", "parameter_name": "Philosophical / Doctrinal Position"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The two corpora differ in genre and textual layer: Vedic hymn collection versus epic narrative.", "link_id": "d2217914-3535-4d87-800e-2134db3de435", "page_or_section": "Textual-layer comparison", "passages": [{"chunk_id": "4a6201da-d8d2-4984-83c0-9ab33f9820c5", "confidence": 0.872, "excerpt": "The Rigveda is the oldest compilation of human wisdom. This Samhita (Collection) is unique in its nature. In fact, it is not a book, but a compilation composed of several books which can be individually distinguished from each other. The present from of this Samhita clearly indicates that the collection is not a single work, but consists of older and later …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "A. Nature and Importance:", "relationship": "supports", "section_title": "A. Nature and Importance:", "source_id": "a81542bb-e361-49cb-b474-ef4919118501", "textual_layer": "Rigveda — Mandala 3"}], "relationship": "supports", "source": {"author": "Vedic Heritage Portal", "authority_metadata": {}, "citation": "Vedic Heritage Portal: Rigveda Overview (https://vedicheritage.gov.in/samhitas/rigveda/)", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IGNCA / Ministry of Culture, Government of India", "rights_or_access_note": null, "source_status": "approved", "source_type": "institutional", "storage_path": null, "title": "Vedic Heritage Portal: Rigveda Overview", "url": "https://vedicheritage.gov.in/samhitas/rigveda/"}, "source_id": "a81542bb-e361-49cb-b474-ef4919118501"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('6925a824-75a7-4e44-8878-458c18f6f613','{"approval_origin": "system_test_bulk", "certainty": "medium", "claim_id": "6925a824-75a7-4e44-8878-458c18f6f613", "claim_kind": "uncertain", "claim_relations": [], "claim_text": "The Mahabharata expands Vishvamitra into multiple dharma settings—genealogy, guru-dakshina, rivalry, emergency ethics, and tirtha narrative—rather than reproducing a single Ramayana biography.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "SYNTHETIC_INTERPRETATION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source", "Recorded source access issue"], "evidence_type": "uncertain", "lens": {"field_id": "fc3c24fb-b9f5-48a9-abf4-3e65ec920fdc", "field_label": "Relationship to major currents such as Vedanta, Samkhya, Mimamsa, etc.", "parameter_id": "4faa5bc1-1b4d-4c48-a26a-cd1b111232e0", "parameter_name": "Philosophical / Doctrinal Position"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Separate Mahabharata parvas preserve distinct Vishvamitra episodes with different ethical and genealogical functions.", "link_id": "2c2b912e-afbb-4dfc-90e0-0f01ae33bd38", "page_or_section": "Cross-parva Mahabharata reception", "passages": [], "relationship": "supports", "source": {"author": "Vyasa (traditional attribution); BORI Critical Edition", "authority_metadata": {}, "citation": "Mahabharata BORI, Udyoga Parva", "original_work_identity": {}, "publication_year": null, "pub