insert into original_claims values ('8c1c100c-5998-4d6e-9c00-db75bbd02e07','{"approval_origin": "imported_existing", "certainty": "medium", "claim_id": "8c1c100c-5998-4d6e-9c00-db75bbd02e07", "claim_kind": "uncertain", "claim_relations": [], "claim_text": "The current source set does not justify mapping Vishvamitra directly onto a later named philosophical system; the safest classification is within the Vedic rishi/mantra tradition.", "current_status": "needs_review", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Missing assigned epistemic classification", "Associated source is not approved", "Associated source URL missing", "Recorded source access issue"], "evidence_type": "uncertain", "lens": {"field_id": "fc3c24fb-b9f5-48a9-abf4-3e65ec920fdc", "field_label": "Relationship to major currents such as Vedanta, Samkhya, Mimamsa, etc.", "parameter_id": "4faa5bc1-1b4d-4c48-a26a-cd1b111232e0", "parameter_name": "Philosophical / Doctrinal Position"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "This field remains deliberately unresolved pending stronger scholarship.", "link_id": "72fa4211-a146-4b0b-a35e-052e77ee9dd6", "page_or_section": "Rishi framework: Philosophical/Doctrinal Position", "passages": [{"chunk_id": "f91d4d5c-060d-46fe-9d3e-b84b57aff719", "confidence": 0.99, "excerpt": "DCF Parameters to Study Rishis  Vocation and role within the Rishi tradition includes the type of rishi and the primary function as drashta, guru, darshana founder, smriti author, or ashram head.  Textual contribution includes mantras and suktas revealed with Veda and mandala references, associated texts, and any school of thought founded or elaborated.  …", "excerpt_truncated": true, "is_active": true, "link_method": "section_metadata", "page_or_section": null, "relationship": "supports", "section_title": null, "source_id": "b6ad83cb-662d-4bda-865b-cb0fa29cfee9", "textual_layer": "DCF research framework"}], "relationship": "supports", "source": {"author": "DCF / framework supplied from Dr. Sampadananda Mishra", "authority_metadata": {}, "citation": "DCF internal document: Parameters to study Rishis.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Dharma Civilization Foundation", "rights_or_access_note": "Internal test framework; no public original source link.", "source_status": "rejected", "source_type": "dcf_content", "storage_path": null, "title": "DCF — Parameters to study Rishis", "url": null}, "source_id": "b6ad83cb-662d-4bda-865b-cb0fa29cfee9"}], "unmatched_passage_links": []}'::jsonb,'needs_review','imported_existing');
insert into original_claims values ('8e37690e-1553-47d2-8bf6-8b8d46f6b944','{"approval_origin": "system_test_bulk", "certainty": "medium", "claim_id": "8e37690e-1553-47d2-8bf6-8b8d46f6b944", "claim_kind": "uncertain", "claim_relations": [], "claim_text": "The Aitareya Devarata story foregrounds lineage incorporation and ritual succession, showing a different current of Vishvamitra tradition from the epic emphasis on personal ascetic transformation.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "SYNTHETIC_INTERPRETATION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source", "Recorded source access issue"], "evidence_type": "uncertain", "lens": {"field_id": "fc3c24fb-b9f5-48a9-abf4-3e65ec920fdc", "field_label": "Relationship to major currents such as Vedanta, Samkhya, Mimamsa, etc.", "parameter_id": "4faa5bc1-1b4d-4c48-a26a-cd1b111232e0", "parameter_name": "Philosophical / Doctrinal Position"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The narrative organizes Vishvamitra''s sons around Devarata and describes dual heritage.", "link_id": "63af0530-a7e1-4a80-95f5-a5b7e3755457", "page_or_section": "Aitareya Brahmana Devarata section", "passages": [], "relationship": "supports", "source": {"author": "", "authority_metadata": {}, "citation": "Aitareya Brahmana Devarata lineage passage", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IGNCA Digital Library, Government of Indi