insert into original_claims values ('9ce64740-e77d-4bd8-b47f-2acdd768a570','{"approval_origin": "system_test_bulk", "certainty": "medium", "claim_id": "9ce64740-e77d-4bd8-b47f-2acdd768a570", "claim_kind": "uncertain", "claim_relations": [], "claim_text": "Sri Aurobindo represents a modern interpretive current in which Vishvamitra''s Vedic imagery is reread psychologically and spiritually rather than treated only as external ritual or nature poetry.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "PARTIALLY_SUPPORTED", "epistemic_type": "SYNTHETIC_INTERPRETATION", "proposed_type": "SYNTHETIC_INTERPRETATION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "uncertain", "lens": {"field_id": "fc3c24fb-b9f5-48a9-abf4-3e65ec920fdc", "field_label": "Relationship to major currents such as Vedanta, Samkhya, Mimamsa, etc.", "parameter_id": "4faa5bc1-1b4d-4c48-a26a-cd1b111232e0", "parameter_name": "Philosophical / Doctrinal Position"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The Secret of the Veda turns specifically to Vishvamitra''s first Agni hymn while developing the ''seven rivers'' symbolism.", "link_id": "51194f47-2a1e-46eb-a341-13a5c77c689c", "page_or_section": "The Secret of the Veda", "passages": [{"chunk_id": "98573e10-d4b9-4da7-af79-d9b99141d9e8", "confidence": 0.55, "excerpt": "60 The Secret of the Veda Bharadwaja. The fifth is occupied by the hymns of the house of Atri. In each of these Mandalas the Suktas addressed to Agni are first collected together and followed by those of which Indra is the deity; the invocations of other gods, Brihaspati, Surya, the Ribhus, Usha etc. close the Mandala. A whole book, the ninth, is given to a …", "excerpt_truncated": true, "is_active": true, "link_method": "adaptive_partial", "page_or_section": "Page 72", "relationship": "context", "section_title": "Page 72", "source_id": "7efe2589-0b7e-4cee-bcc0-b71b0ba418e6", "textual_layer": "Modern spiritual interpretation"}], "relationship": "supports", "source": {"author": "Sri Aurobindo", "authority_metadata": {}, "citation": "Sri Aurobindo, The Secret of the Veda. Sri Aurobindo Ashram.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Sri Aurobindo Ashram", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_book", "storage_path": null, "title": "The Secret of the Veda", "url": "https://www.sriaurobindoashram.org/sriaurobindo/downloadpdf.php?id=30"}, "source_id": "7efe2589-0b7e-4cee-bcc0-b71b0ba418e6"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('d092b2ea-3bff-4982-af58-f72ce645b262','{"approval_origin": "system_test_bulk", "certainty": "medium", "claim_id": "d092b2ea-3bff-4982-af58-f72ce645b262", "claim_kind": "uncertain", "claim_relations": [], "claim_text": "Bala Kanda''s brahma-tejas versus kshatriya-bala contrast makes transformation of the basis of authority—from inherited royal force toward acquired ascetic potency—a central current in its Vishvamitra narrative.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Recorded source access issue"], "evidence_type": "uncertain", "lens": {"field_id": "fc3c24fb-b9f5-48a9-abf4-3e65ec920fdc", "field_label": "Relationship to major currents such as Vedanta, Samkhya, Mimamsa, etc.", "parameter_id": "4faa5bc1-1b4d-4c48-a26a-cd1b111232e0", "parameter_name": "Philosophical / Doctrinal Position"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Vishvamitra explicitly renounces confidence in kshatriya force after Vasistha''s brahma-danda defeats his weapons.", "link_id": "335a6d79-a1f9-41f2-9582-1cb7772db67c", "page_or_section": "1.56.23-24", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur Valmiki Ramayanam Project", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same Bala Kanda chapter is linked below; compare editions before using a quotation.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayanam, Bala Kanda, Sarga 56", "url": "https://www.valmiki.iitk.ac.in/sloka?field_kanda_tid=1&field_sarga_value=56&language=dv"}, "source_id": "63e0dfbf-3f57-476e-98c0-5adc0a85599c"}, {"evidence_excerpt": "Vishvamitra explicitly renounces confidence in kshatriya force after Vasistha''s brahma-danda defeats his weapons.", "link_id": "b9a87bc4-06fa-4bc7-b62b-cd47e0610dab", "page_or_section": "1.56.23-24", "passages": [{"chunk_id": "63e4bb3c-9a10-44c8-b7b6-a9049065e49b", "confidence": 0.78, "excerpt": "Vashishta nullifies Vishvamitra''s missiles just by his Brahma''s baton.   All missiles are defused when Vashishta consumed tghem. Vishvamitra   launches the highest missile, namely Brahma-missile, which too is consumed   by Vashishta, whereby the body of Vashishta becomes a Brahma missile   and starts to emit radiation. Then, upon the prayer of gods and …", "excerpt_truncated": true, "is_active": true, "link_method": "adaptive_strong", "page_or_section": "Book I : Bala Kanda - The Youthful Majesties\n Sarga 56 in Prose", "relationship": "context", "section_title": "Book I : Bala Kanda - The Youthful Majesties\n Sarga 56 in Prose", "source_id": "ffea4c95-a602-4362-b393-4dfe6fd279d0", "textual_layer": "Ramayana — Bala Kanda"}], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution); English rendering by Desiraju Hanumanta Rao", "authority_metadata": {"verified_http_status": 200}, "citation": "Valmiki Ramayana, Bala Kanda 1.56, chapter-level prose rendering.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": "Publicly accessible chapter page; preserve source attribution and link.", "source_status": "