insert into original_claims values ('f2a2e5df-dfe2-46f5-9d2c-f0760ea0bdc0','{"approval_origin": "system_test_bulk", "certainty": "medium", "claim_id": "f2a2e5df-dfe2-46f5-9d2c-f0760ea0bdc0", "claim_kind": "uncertain", "claim_relations": [], "claim_text": "The Aitareya Brahmana extends Vishvamitra''s reception from Rigvedic hymn-seer into the ritual prose world of Brahmana literature, particularly through the Shunahshepa-Devarata narrative.", "current_status": "approved", "epistemics": {"contract_basis": "text", "contract_satisfied": true, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "uncertain", "lens": {"field_id": "fc3c24fb-b9f5-48a9-abf4-3e65ec920fdc", "field_label": "Relationship to major currents such as Vedanta, Samkhya, Mimamsa, etc.", "parameter_id": "4faa5bc1-1b4d-4c48-a26a-cd1b111232e0", "parameter_name": "Philosophical / Doctrinal Position"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The Aitareya Brahmana is a Shakala Rigveda Brahmana centered heavily on sacrifice; its Shunahshepa material gives Vishvamitra a ritual-lineage role.", "link_id": "fc5d51a6-34f6-461c-b743-5c8bb0bd97ed", "page_or_section": "Aitareya Brahmana", "passages": [{"chunk_id": "3e6fdfef-5922-45e7-bc56-c8468dac2c19", "confidence": 0.99, "excerpt": "Aitareya Brahmana belongs to Shakala Shakha of the Rigveda. This work is ascribed to Mahidasa Aitareya and dated variously from 1000 BCE to 500 BCE. It is divided into eight Panchikas and each of the Panchika is divided into eight adhyayas. Totally, it consist forty adhyayas.  The first six panchikas of Aitareya Brahmana dealing with Soma Sacrifice (fire …", "excerpt_truncated": true, "is_active": true, "link_method": "section_metadata", "page_or_section": "Aitareya Brahmana", "relationship": "supports", "section_title": "Aitareya Brahmana", "source_id": "d7d8aaa4-5733-44cf-b9bf-0f494d707b99", "textual_layer": "Aitareya Brahmana tradition"}], "relationship": "supports", "source": {"author": "Mahidasa Aitareya (traditional attribution)", "authority_metadata": {}, "citation": "Aitareya Brahmana", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Vedic Heritage Portal / IGNCA / Ministry of Culture, Government of India", "rights_or_access_note": null, "source_status": "approved", "source_type": "institutional", "storage_path": null, "title": "Aitareya Brahmana", "url": "https://vedicheritage.gov.in/brahmanas/aitareya-brahmana/"}, "source_id": "d7d8aaa4-5733-44cf-b9bf-0f494d707b99"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('00719858-2216-4eb3-9b7d-61488e67193a','{"approval_origin": "imported_existing", "certainty": "high", "claim_id": "00719858-2216-4eb3-9b7d-61488e67193a", "claim_kind": "established_fact", "claim_relations": [], "claim_text": "A distinctive textual legacy associated with Vishvamitra is the Third Mandala tradition of the Rigveda, including the Savitr/Gayatri mantra at 3.62.10 and the river dialogue at Rigveda 3.33.", "current_status": "approved", "epistemics": {"contract_basis": "text", "contract_satisfied": true, "contract_status": "SUPPORTED", "epistemic_type": "TEXTUAL_ASSERTION", "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "uncertain", "lens": {"field_id": "b4c5ae8d-219a-49ee-96e1-b85387118954", "field_label": "Unique or ahead-of-their-time conceptual contribution", "parameter_id": "4faa5bc1-1b4d-4c48-a26a-cd1b111232e0", "parameter_name": "Philosophical / Doctrinal Position"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "One of the best-known mantras in the Vishvamitra-linked Mandala 3 corpus.", "link_id": "b7f68aed-d2af-4d7b-8538-fc8948bc5910", "page_or_section": "Rigveda 3.62.10", "passages": [{"chunk_id": "dbcfbb5a-8120-4b13-9f5a-9d266e46e0d0", "confidence": 0.74, "excerpt": "Hindi Translation by Pt. Sripada Damodara Satavalekar  English Translation by H.H. Wilson  Commentary of Sayanacharya", "excerpt_truncated": false, "is_active": true, "link_method": "single_chunk_curated_source", "page_or_section": "Links", "relationship": "supports", "section_title": "Links", "source_id": "c2d10c6c-8da2-4f5a-becf-93b160eb267b", "textual_layer": "Rigveda — Mandala 3, Sukta 62"}], "relationship": "supports", "source": {"author": "Traditional Vedic text", "authority_metadata": {}, "citation": "Rigveda 3.62, Shakala Samhita. Vedic Heritage Portal.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Vedic Heritage Portal, IGNCA, Ministry of Culture, Government of India", "rights_or_access_note": null, "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Rigveda Shakala Samhita — Mandala 3, Sukta 62", "url": "https://vedicheritage.gov.in/hi/samhitas/rigveda/shakala-samhita/rigveda-shakala-samhita-mandal-03-sukta-062/"}, "source_id": "c2d10c6c-8da2-4f5a-becf-93b160eb267b"}], "unmatched_passage_links": []}'::jsonb,'approved','imported_existing');
insert into original_claims values ('03b34b29-beed-4666-bbf6-b4d41b1701ae','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "03b34b29-beed-4666-bbf6-b4d41b1701ae", "claim_kind": "established_fact", "claim_relations": [], "claim_text": "The Bala Kanda pedagogy is notable for pairing transmission of powerful astras with instruction in their withdrawal, preserving a literary model in which knowledge of restraint is part of mastery.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "SYNTHETIC_INTERPRETATION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Recorded source access issue"], "evidence_type": "uncertain", "lens": {"field_id": "b4c5ae8d-219a-49ee-96e1-b85387118954", "field_label": "Unique or ahead-of-their-time conceptual contribution", "parameter_id": "4faa5bc1-1b4d-4c48-a26a-cd1b111232e0", "parameter_name": "Philosophical / Doctrinal Position"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Rama receives withdrawal procedures immediately after receiving the weapons.", "link_id": "e3337d79-360d-4931-841e-4b6be875a263", "page_or_section": "1.28", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur Valmiki Ramayanam Project", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation o