insert into original_claims values ('10c8c212-ca1f-4bbe-a2ec-4c3f0fb9e735','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "10c8c212-ca1f-4bbe-a2ec-4c3f0fb9e735", "claim_kind": "established_fact", "claim_relations": [], "claim_text": "The Aitareya Brahmana''s Devarata episode gives the Vishvamitra tradition an unusually explicit account of adoption and reorganization of lineage around sacred knowledge and family acceptance.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source", "Recorded source access issue", "Claim-passage link points to a source absent from claim-source links"], "evidence_type": "uncertain", "lens": {"field_id": "b4c5ae8d-219a-49ee-96e1-b85387118954", "field_label": "Unique or ahead-of-their-time conceptual contribution", "parameter_id": "4faa5bc1-1b4d-4c48-a26a-cd1b111232e0", "parameter_name": "Philosophical / Doctrinal Position"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Devarata is placed at the head of Vishvamitra''s sons and described as entering two heritages.", "link_id": "e554e421-0a83-4b93-b94d-4336d7842e80", "page_or_section": "Aitareya Brahmana Devarata section", "passages": [], "relationship": "supports", "source": {"author": "", "authority_metadata": {}, "citation": "Aitareya Brahmana Devarata lineage passage", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IGNCA Digital Library, Government of India", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Aitareya Brahmana / related Indian edition, Devarata lineage passage", "url": "https://ignca.gov.in/Asi_data/24136.pdf"}, "source_id": "56d9174f-e2bb-487a-b201-8eb56236df04"}], "unmatched_passage_links": [{"chunk_id": "9c1bade2-fdf8-4702-b4d5-9125e7a3bdb1", "excerpt": "322  \" Yo sous of GtUhi, blessed with children, you nil will be successful when headed by Devarnla; he will (always) lead you on the path of truth.\"  “ This Devswkta, is your master (man); follow him, ye Koshkas! He will exercise the paternal rights over yon os his heritage from me, and hake possession of the sacred knowledge that we have.\"  “ All the true …", "excerpt_truncated": true, "page_or_section": "p. 322 (scan page 177)", "relationship": "context", "source": {"author": "", "publication_year": null, "publisher_or_institution": "IGNCA Digital Library, Government of India", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "title": "Aitareya Brahmana of the Rigveda vol.2 — repository scan copy (in.gov.ignca.24136)", "url": "https://archive.org/details/in.gov.ignca.24136"}, "source_id": "a5105f0d-6f88-4d51-a6e7-1a4daac3a1da"}]}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('1202b642-b547-4807-997f-31eada48a96e','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "1202b642-b547-4807-997f-31eada48a96e", "claim_kind": "established_fact", "claim_relations": [], "claim_text": "Vishvamitra''s role as narrator gives Bala Kanda a chain of embedded traditions—including dynasty, rivers, sacred places, and earlier divine events—so his character also functions as a vehicle for transmitting cultural memory to Rama.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "SYNTHETIC_INTERPRETATION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Recorded source access issue"], "evidence_type": "uncertain", "lens": {"field_id": "b4c5ae8d-219a-49ee-96e1-b85387118954", "field_label": "Unique or ahead-of-their-time conceptual contribution", "parameter_id": "4faa5bc1-1b4d-4c48-a26a-cd1b111232e0", "parameter_name": "Philosophical / Doctrinal Position"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The Ganga narration is one of several long teaching narratives Vishvamitra supplies during the journey.", "link_id": "78a6d532-704f-4cd4-a8db-d3f25205bcff", "page_or_section": "Bala Kanda journey narratives", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur Valmiki Ramayanam Project", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same Bala Kanda chapter is linked below; compare editions before using a quotation.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayanam, Bala Kanda, Sarga 35", "url": "https://www.valmiki.iitk.ac.in/summary?field_kanda_tid=1&field_sarga_value=35"}, "source_id": "3f8184f5-2d01-45b4-a672-080c7ab608d2"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('1e7de698-bda7-442d-9d6e-3eaa323c38c1','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "1e7de698-bda7-442d-9d6e-3eaa323c38c1", "claim_kind": "established_fact", "claim_relations": [], "claim_text": "Across Vedic, Brahmana, Ramayana, Mahabharata, ritual-sutra, later Upanishadic, and modern interpretive sources, Vishvamitra has an exceptionally long reception history; that cross-genre continuity should itself be represented as a research finding rather than collapsed into one biography.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "SYNTHETIC_INTERPRETATION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "uncertain", "lens": {"field_id": "b4c5ae8d-219a-49ee-96e1-b85387118954", "field_label": "Unique or ahead-of-their-time conceptual contribution", "parameter_id": "4faa5bc1-1b4d-4c48-a26a-cd1b111232e0", "parameter_name": "Philosophical / Doctrinal Position"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The later Upanishad is one documented endpoint of a reception sequence that begins in the Rigvedic corpus.", "link_id": "00deb406-2eab-4a55-bca8-5dcfde0d70f6", "page_or_section": "Reception-history synthesis", "passages": [], "relationship": "supports", "source": {"author": "Traditional text", "authority_metadata": {}, "citation": "Arsheya Upanishad", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Vedic Heritage Portal / IGNCA / Ministry of Culture, Government of India", "rights_or_access_note": null, "source_status": "approved", "source_type": "institutional", "storage_path": null, "title": "Arsheya Upanishad", "url": "https://vedicheritage.gov.in/upanishads/aarsheyopanishad/"}, "source_id": "f76efd31-3f90-4b32-b386-99e3cce78d6a"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('2f5ce657-2949-470a-b1d7-4ef54fa87785','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "2f5ce657-2949-470a-b1d7-4ef54fa87785", "claim_kind": "established_fact", "claim_relations": [], "claim_text": "Vishvamitra''s Vedic profile is unusually substantial because the Vedic Heritage Portal associates the entire Third Mandala with Vishvamitra and his family.", "current_status": "approved", "epistemics": {"contract_basis": "text", "contract_satisfied": true, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "uncertain", "lens": {"field_id": "b4c5ae8d-219a-49ee-96e1-b85387118954", "field_label": "Unique or ahead-of-their-time conceptual contribution", "parameter_id": "4faa5bc1-1b4d-4c48-a26a-cd1b111232e0", "parameter_name": "Philosophical / Doctrinal Position"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Mandala 3 contains 62 suktas and 617 mantras and is assigned to Vishvamitra and his family.", "link_id": "0be26cc7-6123-461b-9209-070f90bb4305", "page_or_section": "Mandala 3 overview", "passages": [{"chunk_id": "9b97ceb8-689b-43d6-a99c-34242db71f5a", "confidence": 0.823529411764706, "excerpt": "The whole of the Rigveda-Samhita is in form of verses, known as Rik.  ‘Rik’ is the name given to those Mantras which are meant for the praise of the deities. Thus the collection (Samhita) of Riks is known as Rigveda-Samhita. Only one recession or school (Shakha) of the Rigveda is available today and it is the Shaakala. The Rigveda Samhita contains about …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "B. Form and Classification :", "relationship": "supports", "section_title": "B. Form and Classification :", "source_id": "a81542bb-e361-49cb-b474-ef4919118501", "textual_layer": "Rigveda — Mandala 3"}, {"chunk_id": "bd805da5-7fe7-4dc6-b84f-f4582b0f721c", "confidence": 0.823529411764706, "excerpt": "Among 1028 Suktas of the Rigveda Samhita some suktas are very popular and frequently referred by the readers of Vedas. Some of them are:  Hiranya-garbha Sukta  Dhana-anna-dana Sukta  Duhsvapna-nashna Sukta  Yama-yami-samvada Sukta  Besides, there are Suktas offered to different deities, such as, Indra, Maruta, Varuna, Usha, Surya, Bhumi, Soma, Agni etc. …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "C. Some Important Hymns:", "relationship": "supports", "section_title": "C. Some Important Hymns:", "source_id": "a81542bb-e361-49cb-b474-ef4919118501", "textual_layer": "Rigveda — Mandala 3"}], "relationship": "supports", "source": {"author": "Vedic Heritage Portal", "authority_metadata": {}, "citation": "Vedic Heritage Portal: Rigveda Overview (https://vedicheritage.gov.in/samhitas/rigveda/)", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IGNCA / Ministry of Culture, Government of India", "rights_or_access_note": null, "source_status": "approved", "source_type": "institutional", "storage_path": null, "title": "Vedic Heritage Portal: Rigveda Overview", "url": "https://vedicheritage.gov.in/samhitas/rigveda/"}, "source_id": "a81542bb-e361-49cb-b474-ef4919118501"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('31a9db58-f790-4094-a1fc-5e0ce309c7ef','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "31a9db58-f790-4094-a1fc-5e0ce309c7ef", "claim_kind": "established_fact", "claim_relations": [], "claim_text": "Rigveda 3.1.21 and 3.18.4 both use plural Vishvamitra-family language inside the hymns, giving unusually direct textual evidence for a collective seer tradition.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "uncertain", "lens": {"field_id": "b4c5ae8d-219a-49ee-96e1-b85387118954", "field_label": "Unique or ahead-of-their-time conceptual contribution", "parameter_id": "4faa5bc1-1b4d-4c48-a26a-cd1b111232e0", "parameter_name": "Philosophical / Doctrinal Position"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Two Mandala 3 passages contain plural Vishvamitra designations rather than only metadata supplied by later indexing.", "link_id": "d338e03a-1ebf-421f-83b2-29557f4a309c", "page_or_section": "RV 3.1.21 and 3.18.4", "passages": [{"chunk_id": "eee5715c-a576-45d8-89da-c841232e4f80", "confidence": 0.74, "excerpt": "Hindi Translation by Pt. Sripada Damodara Satavalekar  English Translation by H.H. Wilson  Commentary of Sayanacharya", "excerpt_truncated": false, "is_active": true, "link_method": "single_chunk_curated_source", "page_or_section": "Links", "relationship": "supports", "section_title": "Links", "source_id": "5bef2a36-07ca-4a1f-91a1-1454275e2dfa", "textual_layer": "Rigveda — Mandala 3"}], "relationship": "supports", "source": {"author": "Vedic Heritage Portal", "authority_metadata": {}, "citation": "Vedic Heritage Portal: Rigveda Mandala 3 (https://vedicheritage.gov.in/samhitas/rigveda/shakala-samhita/mandal-03/)", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IGNCA / Ministry of Culture, Government of India", "rights_or_access_note": null, "source_status": "approved", "source_type": "institutional", "storage_path": null, "title": "Vedic Heritage Portal: Rigveda Mandala 3", "url": "https://vedicheritage.gov.in/samhitas/rigveda/shakala-samhita/mandal-03/"}, "source_id": "5bef2a36-07ca-4a1f-91a1-1454275e2dfa"}, {"evidence_excerpt": "Two Mandala 3 passages contain plural Vishvamitra designations rather than only metadata supplied by later indexing.", "link_id": "d51a5058-1900-4c51-a37f-01fd6db0852c", "page_or_section": "RV 3.1.21 and 3.18.4", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution); English rendering by Desiraju Hanumanta Rao", "authority_metadata": {"verified_http_status": 200}, "citation": "Valmiki Ramayana, Bala Kanda 1.21, chapter-level prose rendering.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": "Publicly accessible chapter page; preserve source attribution and link.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayana — Bala Kanda, Sarga 21 (prose)", "url": "https://www.valmikiramayan.net/utf8/baala/sarga21/bala_21_prose.htm"}, "source_id": "9227358e-67a7-46f5-a873-bb5582ebb893"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('3e3c62d3-f568-48c2-81aa-cc9e49b20db2','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "3e3c62d3-f568-48c2-81aa-cc9e49b20db2", "claim_kind": "established_fact", "claim_relations": [], "claim_text": "Mandala 3 is internally diverse enough that a strong Vishvamitra profile can map individual seers hymn by hymn; this family architecture is itself a distinctive feature of the corpus associated with him.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "uncertain", "lens": {"field_id": "b4c5ae8d-219a-49ee-96e1-b85387118954", "field_label": "Unique or ahead-of-their-time conceptual contribution", "parameter_id": "4faa5bc1-1b4d-4c48-a26a-cd1b111232e0", "parameter_name": "Philosophical / Doctrinal Position"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Sri Aurobindo''s Hymns to the Mystic Fire table of contents differentiates Gathina Vishvamitra, Rishabha Vaishvamitra, Kata Vaishvamitra, Gathin Kaushika, and others within Mandala 3.", "link_id": "11426326-fb52-40b7-a160-26ff525e4c9f", "page_or_section": "Mandala 3 attribution map", "passages": [], "relationship": "supports", "source": {"author": "Sri Aurobindo", "authority_metadata": {}, "citation": "Sri Aurobindo, Hymns to the Mystic Fire", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Sri Aurobindo Ashram", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_book", "storage_path": null, "title": "Hymns to the Mystic Fire", "url": "https://www.sriaurobindoashram.org/sriaurobindo/downloadpdf.php?id=31"}, "source_id": "87b5a887-05f8-4956-81ea-431dc6e200bb"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('4af8d45b-3d7a-40c2-8c81-58eaf5cab52e','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "4af8d45b-3d7a-40c2-8c81-58eaf5cab52e", "claim_kind": "established_fact", "claim_relations": [], "claim_text": "Rigveda 3.53 is important for the historical-literary profile because it contains explicit references to Vishvamitra, the Kushikas, and Sudas within the hymn itself.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "uncertain", "lens": {"field_id": "b4c5ae8d-219a-49ee-96e1-b85387118954", "field_label": "Unique or ahead-of-their-time conceptual contribution", "parameter_id": "4faa5bc1-1b4d-4c48-a26a-cd1b111232e0", "parameter_name": "Philosophical / Doctrinal Position"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Verses 7-13 include Vishvamitra/Kushika language and a Sudas reference.", "link_id": "858c9ece-e884-49ff-914e-5af1a65cf7c5", "page_or_section": "RV 3.53.7-13", "passages": [{"chunk_id": "9829672a-8a69-4e30-8c1c-790ace3144f4", "confidence": 0.74, "excerpt": "Hindi Translation by Pt. Sripada Damodara Satavalekar  English Translation by H.H. Wilson  Commentary of Sayanacharya", "excerpt_truncated": false, "is_active": true, "link_method": "single_chunk_curated_source", "page_or_section": "Links", "relationship": "supports", "section_title": "Links", "source_id": "1d1d4614-230f-4895-9e80-fafa8dc85f1a", "textual_layer": "Rigveda — Mandala 3"}], "relationship": "supports", "source": {"author": "Vedic Heritage Portal", "authority_metadata": {}, "citation": "Rigveda 3.53 (https://vedicheritage.gov.in/samhitas/rigveda/shakala-samhita/rigveda-shakala-samhita-mandal-03-sukta-053/)", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IGNCA / Ministry of Culture, Government of India", "rights_or_access_note": null, "source_status": "approved", "source_type": "institutional", "storage_path": null, "title": "Rigveda 3.53", "url": "https://vedicheritage.gov.in/samhitas/rigveda/shakala-samhita/rigveda-shakala-samhita-mandal-03-sukta-053/"}, "source_id": "1d1d4614-230f-4895-9e80-fafa8dc85f1a"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('70e29914-2e17-43dc-8135-4d549889e26e','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "70e29914-2e17-43dc-8135-4d549889e26e", "claim_kind": "established_fact", "claim_relations": [], "claim_text": "Rigveda 3.53.12-13 links the Vishvamitra tradition directly with Bharata protection and prayer to Indra, providing more concrete social-historical texture than a generic seer attribution.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "PARTIALLY_SUPPORTED", "epistemic_type": "TEXTUAL_ASSERTION", "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source", "Recorded source access issue", "Claim-passage link points to a source absent from claim-source links"], "evidence_type": "uncertain", "lens": {"field_id": "b4c5ae8d-219a-49ee-96e1-b85387118954", "field_label": "Unique or ahead-of-their-time conceptual contribution", "parameter_id": "4faa5bc1-1b4d-4c48-a26a-cd1b111232e0", "parameter_name": "Philosophical / Doctrinal Position"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The verses explicitly connect Vishvamitra/Vishvamitras, Bharata, and Indra.", "link_id": "31743069-e043-41e3-a856-17a3a68bbdb7", "page_or_section": "RV 3.53.12-13", "passages": [], "relationship": "supports", "source": {"author": "", "authority_metadata": {}, "citation": "Rigveda Mandala 3, including RV 3.53", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IGNCA Digital Library, Government of India", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Rigveda translation / study, Mandala 3 passages", "url": "https://ignca.gov.in/Asi_data/8739.pdf"}, "source_id": "25a74bde-3037-402a-b7bf-1e4f6034ccd6"}], "unmatched_passage_links": [{"chunk_id": "b544cd7e-eb36-444f-9618-4a82bab1d8fa", "excerpt": "य इमे रोदसी उभे अहमिन्द्रमतुष्टवम् । विश्वामित्रस्य रक्षति ब्रह्मेदं भारतं जनम् ya ime rodasī ubhe ahamindramatuṣṭavam | viśvāmitrasya rakṣati brahmedaṃ bhārataṃ janam Praises to Indra have I sung, sustainer of this earth and heaven. This prayer of Visvamitra keeps secure the race of Bharatas.", "excerpt_truncated": false, "page_or_section": "3.53.12", "relationship": "context", "source": {"author": null, "publication_year": null, "publisher_or_institution": null, "rights_or_access_note": null, "source_status": "approved", "source_type": "primary_text", "title": "Maṇḍala 3 — 62 hymns of the Viśvāmitra family (incl. Gāyatrī) — Rigveda — Swaveda", "url": "https://www.swaveda.com/texts/rigveda/3/"}, "source_id": "681b7993-1899-497d-864c-287d302819ec"}]}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('774bb3e4-a19f-4e5d-af85-733bdce7a8e6','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "774bb3e4-a19f-4e5d-af85-733bdce7a8e6", "claim_kind": "established_fact", "claim_relations": [], "claim_text": "Rigveda 3.33 combines poetic river dialogue, a practical crossing request, lineage identification, and the movement of the Bharatas, making it a particularly rich source for studying the social dimension of the Vishvamitra tradition.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "PARTIALLY_SUPPORTED", "epistemic_type": "SYNTHETIC_INTERPRETATION", "proposed_type": "SYNTHETIC_INTERPRETATION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source", "Recorded source access issue", "Claim-passage link points to a source absent from claim-source links"], "evidence_type": "uncertain", "lens": {"field_id": "b4c5ae8d-219a-49ee-96e1-b85387118954", "field_label": "Unique or ahead-of-their-time conceptual contribution", "parameter_id": "4faa5bc1-1b4d-4c48-a26a-cd1b111232e0", "parameter_name": "Philosophical / Doctrinal Position"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The hymn''s dialogue contains the Kushika speaker, river response, and Bharata crossing.", "link_id": "df847a27-1dfb-435d-ba24-3b6d3eabc075", "page_or_section": "RV 3.33", "passages": [], "relationship": "supports", "source": {"author": "", "authority_metadata": {}, "citation": "Rigveda Mandala 3 translation edition", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IGNCA Digital Library, Government of India", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Rigveda Samhita, Volume III", "url": "https://ignca.gov.in/eBooks/RigVeda_Samhita_Vol_03.pdf"}, "source_id": "eabc9c3f-496a-4d87-acae-c67d983ccf20"}], "unmatched_passage_links": [{"chunk_id": "380060ae-d4c7-4f49-986d-4d9ecc998983", "excerpt": "अतारिषुर्भरता गव्यवः समभक्त विप्रः सुमतिं नदीनाम् । प्र पिन्वध्वमिषयन्तीः सुराधा आ वक्षणाः पृणध्वं यात शीभम् atāriṣurbharatā gavyavaḥ samabhakta vipraḥ sumatiṃ nadīnām | pra pinvadhvamiṣayantīḥ surādhā ā vakṣaṇāḥ pṛṇadhvaṃ yāta śībham The warrior host, the Bharatas, fared over the singer won the favour of the Rivers. Swell with your billows, hasting, …", "excerpt_truncated": true, "page_or_section": "3.33.12", "relationship": "context", "source": {"author": null, "publication_year": null, "publisher_or_institution": null, "rights_or_access_note": null, "source_status": "approved", "source_type": "primary_text", "title": "Maṇḍala 3 — 62 hymns of the Viśvāmitra family (incl. Gāyatrī) — Rigveda — Swaveda", "url": "https://www.swaveda.com/texts/rigveda/3/"}, "source_id": "681b7993-1899-497d-864c-287d302819ec"}, {"chunk_id": "391eb3b5-1fcd-4354-91a6-1149ddbc926c", "excerpt": "रमध्वं मे वचसे सोम्याय ऋतावरीरुप मुहूर्तमेवैः । प्र सिन्धुमच्छा बृहती मनीषावस्युरह्वे कुशिकस्य सूनुः ramadhvaṃ me vacase somyāya ṛtāvarīrupa muhūrtamevaiḥ | pra sindhumacchā bṛhatī manīṣāvasyurahve kuśikasya sūnuḥ Linger a little at my friendly bidding rest, Holy Ones, a moment in your journey. With hymn sublime soliciting your favour Kusika''s son hath …", "excerpt_truncated": true, "page_or_section": "3.33.5", "relationship": "context", "source": {"author": null, "publication_year": null, "publisher_or_institution": null, "rights_or_access_note": null, "source_status": "approved", "source_type": "primary_text", "title": "Maṇḍala 3 — 62 hymns of the Viśvāmitra family (incl. Gāyatrī) — Rigveda — Swaveda", "url": "https://www.swaveda.com/texts/rigveda/3/"}, "source_id": "681b7993-1899-497d-864c-287d302819ec"}]}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('a4d6ed9a-8640-42c8-abf9-6e9f1bc35dfc','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "a4d6ed9a-8640-42c8-abf9-6e9f1bc35dfc", "claim_kind": "established_fact", "claim_relations": [], "claim_text": "Rigveda 3.53.12 says that the prayer of Vishvamitra keeps the Bharata people secure, in a verse of praise to Indra.", "current_status": "approved", "epistemics": {"contract_basis": "text", "contract_satisfied": true, "contract_status": "SUPPORTED", "epistemic_type": "TEXTUAL_ASSERTION", "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["Current approval origin does not establish strict verification", "Has parent claim ID 70e29914-2e17-43dc-8135-4d549889e26e", "Retention/access rights note missing for an associated source"], "evidence_type": "uncertain", "lens": {"field_id": "b4c5ae8d-219a-49ee-96e1-b85387118954", "field_label": "Unique or ahead-of-their-time conceptual contribution", "parameter_id": "4faa5bc1-1b4d-4c48-a26a-cd1b111232e0", "parameter_name": "Philosophical / Doctrinal Position"}, "parent_claim_id": "70e29914-2e17-43dc-8135-4d549889e26e", "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "य इमे रोदसी उभे अहमिन्द्रमतुष्टवम् । विश्वामित्रस्य रक्षति ब्रह्मेदं भारतं जनम् ya ime rodasī ubhe ahamindramatuṣṭavam | viśvāmitrasya rakṣati brahmedaṃ bhārataṃ janam Praises to Indra have I sung, sustainer of this earth and heaven. This prayer of Visvamitra keeps secure the race of Bharatas.", "link_id": "cfe62521-f6ae-47c2-9a4b-a673229a6c32", "page_or_section": "RV 3.53.12-13", "passages": [{"chunk_id": "b544cd7e-eb36-444f-9618-4a82bab1d8fa", "confidence": 0.95, "excerpt": "य इमे रोदसी उभे अहमिन्द्रमतुष्टवम् । विश्वामित्रस्य रक्षति ब्रह्मेदं भारतं जनम् ya ime rodasī ubhe ahamindramatuṣṭavam | viśvāmitrasya rakṣati brahmedaṃ bhārataṃ janam Praises to Indra have I sung, sustainer of this earth and heaven. This prayer of Visvamitra keeps secure the race of Bharatas.", "excerpt_truncated": false, "is_active": true, "link_method": "reconciliation_exact", "page_or_section": "3.53.12", "relationship": "supports", "section_title": "Maṇḍala 3 — 62 hymns of the Viśvāmitra family (incl. Gāyatrī) — Rigveda — Swaveda", "source_id": "681b7993-1899-497d-864c-287d302819ec", "textual_layer": "Rigveda"}], "relationship": "supports", "source": {"author": null, "authority_metadata": {"editorialStatus": "Public-domain text reproduction; Swaveda articles are AI drafted and not peer reviewed"}, "citation": "https://www.swaveda.com/texts/rigveda/3/", "original_work_identity": {"independentWorkKey": "rigveda|ralph t. h. griffith|1896", "sourceFamily": "www.swaveda.com/texts/rigveda/", "underlyingWork": "Rigveda, Mandala 3"}, "publication_year": null, "publisher_or_institution": null, "rights_or_access_note": null, "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Maṇḍala 3 — 62 hymns of the Viśvāmitra family (incl. Gāyatrī) — Rigveda — Swaveda", "url": "https://www.swaveda.com/texts/rigveda/3/"}, "source_id": "681b7993-1899-497d-864c-287d302819ec"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
