insert into original_claims values ('183ccb29-24ac-481b-a9cc-789304da3b37','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "183ccb29-24ac-481b-a9cc-789304da3b37", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "Rigveda 3.53 also connects the Vishvamitra/Kushika tradition with King Sudas, though the exact historical relationship requires careful Vedic interpretation.", "current_status": "approved", "epistemics": {"contract_basis": "tradition", "contract_satisfied": true, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source", "Claim-passage link points to a source absent from claim-source links"], "evidence_type": "traditional_narrative", "lens": {"field_id": "de20bc35-2696-4a80-b095-614bb650a581", "field_label": "Advisory relationships with kings or dynasties", "parameter_id": "700ce11a-bd45-4116-99a4-a246dc97c505", "parameter_name": "Relational / Social Role"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "RV 3.53.9-11 includes Sudas and Kushika/Vishvamitra language.", "link_id": "dc748b71-2a38-488b-bdee-4480eca4242f", "page_or_section": "RV 3.53.9-11", "passages": [{"chunk_id": "9829672a-8a69-4e30-8c1c-790ace3144f4", "confidence": 0.74, "excerpt": "Hindi Translation by Pt. Sripada Damodara Satavalekar  English Translation by H.H. Wilson  Commentary of Sayanacharya", "excerpt_truncated": false, "is_active": true, "link_method": "single_chunk_curated_source", "page_or_section": "Links", "relationship": "supports", "section_title": "Links", "source_id": "1d1d4614-230f-4895-9e80-fafa8dc85f1a", "textual_layer": "Rigveda — Mandala 3"}], "relationship": "supports", "source": {"author": "Vedic Heritage Portal", "authority_metadata": {}, "citation": "Rigveda 3.53 (https://vedicheritage.gov.in/samhitas/rigveda/shakala-samhita/rigveda-shakala-samhita-mandal-03-sukta-053/)", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IGNCA / Ministry of Culture, Government of India", "rights_or_access_note": null, "source_status": "approved", "source_type": "institutional", "storage_path": null, "title": "Rigveda 3.53", "url": "https://vedicheritage.gov.in/samhitas/rigveda/shakala-samhita/rigveda-shakala-samhita-mandal-03-sukta-053/"}, "source_id": "1d1d4614-230f-4895-9e80-fafa8dc85f1a"}], "unmatched_passage_links": [{"chunk_id": "f73a324f-8c2f-4e7c-aad7-97fda0468509", "excerpt": "58 as resulting from tapas, but the Vālmīki Rāmāyaṇa further regulates this tapas through a lengthy expansion of the narrative. In between his conflict with Vasiṣṭha and his triumphant self-transformation, the Rāmāyaṇa embeds a sequence of the other familiar Viśvāmitra-centered legends: the stories of Triśaṅku, Śunaḥśepa, Menakā, and Rambhā. These are all …", "excerpt_truncated": true, "page_or_section": "p. 58 (PDF page 18)", "relationship": "context", "source": {"author": "Adheesh Sathaye", "publication_year": 2007, "publisher_or_institution": "Acta Orientalia Vilnensia / Vilnius University Press", "rights_or_access_note": "Official journal diamond open access, CC BY 4.0: https://www.journals.vu.lt/acta-orientalia-vilnensia/journalpolicy", "source_status": "approved", "source_type": "scholarly_article", "title": "How to become a Brahman: The construction of varṇa as social place in the Mahābhārata’s legends of Viśvāmitra", "url": "https://www.journals.vu.lt/acta-orientalia-vilnensia/article/download/3751/5207"}, "source_id": "06fec486-e5af-4c7e-95db-afbb2e237c75"}]}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('1854d002-13eb-42d0-8e53-f67690b7059c','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "1854d002-13eb-42d0-8e53-f67690b7059c", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "The Aitareya Shunahshepa narrative associates Vishvamitra with a royal sacrifice and its crisis, extending his royal-ritual function into Brahmana literature.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "UNSUPPORTED", "epistemic_type": "TRADITIONAL_NARRATIVE", "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source", "Recorded source access issue"], "evidence_type": "traditional_narrative", "lens": {"field_id": "de20bc35-2696-4a80-b095-614bb650a581", "field_label": "Advisory relationships with kings or dynasties", "parameter_id": "700ce11a-bd45-4116-99a4-a246dc97c505", "parameter_name": "Relational / Social Role"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The Shunahshepa episode is embedded in a royal sacrificial context in which Vishvamitra is a ritual authority.", "link_id": "5c26ca82-c707-416b-8853-e4c2cf02cb80", "page_or_section": "Aitareya Brahmana Shunahshepa cycle", "passages": [], "relationship": "supports", "source": {"author": "", "authority_metadata": {}, "citation": "Aitareya Brahmana Shunahshepa-Devarata passage", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IGNCA Digital Library, Government of India", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Aitareya Brahmana / related Indian antiquarian edition, Shunahshepa-Devarata passage", "url": "https://ignca.gov.in/Asi_data/14189.pdf"}, "source_id": "aaf4aa38-c1b0-4d20-afd0-f83df099bc2a"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('190611a0-bb2d-4b01-b063-b3354d3f3450','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "190611a0-bb2d-4b01-b063-b3354d3f3450", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "Vishvamitra directly negotiates with King Dasharatha for Rama''s participation in protecting a sacrifice, showing an authoritative relationship with royal power.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "traditional_narrative", "lens": {"field_id": "de20bc35-2696-4a80-b095-614bb650a581", "field_label": "Advisory relationships with kings or dynasties", "parameter_id": "700ce11a-bd45-4116-99a4-a246dc97c505", "parameter_name": "Relational / Social Role"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Vishvamitra asks Dasharatha to send Rama and argues for Rama''s capacity to defeat the ritual-disrupting demons.", "link_id": "c1b5a650-43cd-4981-a7d8-a9141e845af5", "page_or_section": "1.19", "passages": [{"chunk_id": "22f5abe8-802f-451a-a350-7a0c994f1637", "confidence": 0.94, "excerpt": "These verses are commented extensively by early commentators. In 14th verse, the   pronoun aham, ''I'' used by Sage Vishvamitra is to announce definiteness   about his own stature to know the Absolute vis-a-vis the Absolute Himself. Vishvamitra   was an emperor who left off everything. He was primarily a raajarShi,   kingly sage, later became brahmarShi and …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Introduction", "relationship": "supports", "section_title": "Introduction", "source_id": "826d5c8a-6135-4304-8825-09579ff9a478", "textual_layer": "Ramayana — Bala Kanda, Sarga 19"}, {"chunk_id": "9374da7d-e000-40d3-83fc-7d752aa7f76c", "confidence": 0.95, "excerpt": "Sage Vishvamitra asks King Dasharatha to send Rama to protect the Vedic ritual   that is being conducted by him, from the demons that are constantly disrupting   it. The sage asserts King Dasharatha that he and the other sages in Dasharatha''s   court know the capabilities of Rama and though Rama is in his adolescence, he   can easily kill the demons. But …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Introduction", "relationship": "supports", "section_title": "Introduction", "source_id": "826d5c8a-6135-4304-8825-09579ff9a478", "textual_layer": "Ramayana — Bala Kanda, Sarga 19"}], "relationship": "supports", "source": {"author": "Valmiki", "authority_metadata": {}, "citation": "Valmiki Ramayana, Bala Kanda, Sarga 19 (https://valmikiramayan.net/utf8/baala/sarga19/balasans19.htm)", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Valmiki Ramayana, Bala Kanda, Sarga 19", "url": "https://valmikiramayan.net/utf8/baala/sarga19/balasans19.htm"}, "source_id": "826d5c8a-6135-4304-8825-09579ff9a478"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('35c9c378-40ea-4ff7-a1ac-9681cd4cf575','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "35c9c378-40ea-4ff7-a1ac-9681cd4cf575", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "The relationship is not merely advisory: Dasharatha ultimately entrusts Rama to Vishvamitra, placing the sage in temporary guardianship and instruction of the prince.", "current_status": "approved", "epistemics": {"contract_basis": "tradition", "contract_satisfied": true, "contract_status": "SUPPORTED", "epistemic_type": "TRADITIONAL_NARRATIVE", "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "traditional_narrative", "lens": {"field_id": "de20bc35-2696-4a80-b095-614bb650a581", "field_label": "Advisory relationships with kings or dynasties", "parameter_id": "700ce11a-bd45-4116-99a4-a246dc97c505", "parameter_name": "Relational / Social Role"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Dasharatha entrusts Rama to Vishvamitra before the journey begins.", "link_id": "ad322f2d-b8aa-4978-84bb-6a60e29d2859", "page_or_section": "1.22.2-3", "passages": [{"chunk_id": "3e790a17-403e-47fd-b349-d85f9c4d92bd", "confidence": 0.89, "excerpt": "King Dasharatha sends Rama and Lakshmana along with Sage Vishvamitra as requested   by the sage. In their course of travel, Sage Vishvamitra imparts a secret knowledge   to the young princes Rama and Lakshmana, called bala-atibala-   vidya-s, by practicing which nothing can wither their vigour and vitality.  तथा वसिष्ठे ब्रुवति राजा दशरथः स्वयम् |  …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Introduction", "relationship": "supports", "section_title": "Introduction", "source_id": "4772171e-b53b-4ae5-9ffa-e6edf7a8f9de", "textual_layer": "Ramayana — Bala Kanda"}, {"chunk_id": "b6e661c7-935d-4437-966f-55bbe4dbc538", "confidence": 0.825, "excerpt": "क्षुत्पिपासे न ते राम भविष्येते नरोत्तम |  बलामतिबलां चैव पठतस्तात राघव || १-२२-१७  17. narottama raaghava = oh best among people, Raghava; balam atibalam   cha eva = bala and atibala hymns; paThataH = if recited; taata   = my dear; te = to you; raama = Rama;  kSutpipaase = hunger and thirst; na bhaviSyete = not, will be there.  \"Oh, best one among men, …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Introduction", "relationship": "supports", "section_title": "Introduction", "source_id": "4772171e-b53b-4ae5-9ffa-e6edf7a8f9de", "textual_layer": "Ramayana — Bala Kanda"}], "relationship": "supports", "source": {"author": "Valmiki", "authority_metadata": {}, "citation": "Valmiki Ramayana, Bala Kanda, Sarga 22 (https://www.valmikiramayan.net/utf8/baala/sarga22/balasans22.htm)", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Valmiki Ramayana, Bala Kanda, Sarga 22", "url": "https://www.valmikiramayan.net/utf8/baala/sarga22/balasans22.htm"}, "source_id": "4772171e-b53b-4ae5-9ffa-e6edf7a8f9de"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('4e722593-ea71-48ac-93d6-f3fd80160670','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "4e722593-ea71-48ac-93d6-f3fd80160670", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "Vasistha''s intervention in Dasharatha''s court is itself evidence of Vishvamitra''s recognized standing: the royal priest argues that entrusting Rama to Vishvamitra is the safer and more honorable course.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "PARTIALLY_SUPPORTED", "epistemic_type": "TRADITIONAL_NARRATIVE", "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Current approval origin does not establish strict verification", "Recorded source access issue"], "evidence_type": "traditional_narrative", "lens": {"field_id": "de20bc35-2696-4a80-b095-614bb650a581", "field_label": "Advisory relationships with kings or dynasties", "parameter_id": "700ce11a-bd45-4116-99a4-a246dc97c505", "parameter_name": "Relational / Social Role"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Vasistha persuades Dasharatha to keep his promise and emphasizes Vishvamitra''s competence.", "link_id": "b6fe24f7-86fd-4770-8357-327af0d6422b", "page_or_section": "1.21", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur Valmiki Ramayanam Project", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same Bala Kanda chapter is linked below; compare editions before using a quotation.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayanam, Bala Kanda, Sarga 21", "url": "https://www.valmiki.iitk.ac.in/summary?field_kanda_tid=1&field_sarga_value=21"}, "source_id": "0537c002-ff50-437a-88f6-1ca1f43572cf"}, {"evidence_excerpt": "Vasistha persuades Dasharatha to keep his promise and emphasizes Vishvamitra''s competence.", "link_id": "cf3214f1-d051-474c-8a66-aed1cb24fde6", "page_or_section": "1.21", "passages": [{"chunk_id": "eb13ef00-ba13-431c-9957-e70d915433bf", "confidence": 0.75, "excerpt": "The ire of sage Vishvamitra is shown at king Dasharatha. To pacify sage Vishvamitra,  sage Vashishta intervenes and convinces king Dasharatha to send Rama with sage Vishvamitra. While doing  so, sage Vashishta enumerates the capabilities of sage Vishvamitra, his knowledge of weaponry. Vashishta  also suggests that all those weapons will be given to Rama, if …", "excerpt_truncated": true, "is_active": true, "link_method": "adaptive_strong", "page_or_section": "Valmiki Ramayana - Bala Kanda in \nProse Sarga 21", "relationship": "context", "section_title": "Valmiki Ramayana - Bala Kanda in \nProse Sarga 21", "source_id": "9227358e-67a7-46f5-a873-bb5582ebb893", "textual_layer": "Ramayana — Bala Kanda"}], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution); English rendering by Desiraju Hanumanta Rao", "authority_metadata": {"verified_http_status": 200}, "citation": "Valmiki Ramayana, Bala Kanda 1.21, chapter-level prose rendering.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": "Publicly accessible chapter page; preserve source attribution and link.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayana — Bala Kanda, Sarga 21 (prose)", "url": "https://www.valmikiramayan.net/utf8/baala/sarga21/bala_21_prose.htm"}, "source_id": "9227358e-67a7-46f5-a873-bb5582ebb893"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('5e54ae2f-91be-438b-989d-060257649be6','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "5e54ae2f-91be-438b-989d-060257649be6", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "Vishvamitra asks Janaka to display Shiva''s bow, making him an active initiator of the event that leads to Rama''s bow feat and the marriage negotiations.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Recorded source access issue", "Claim-passage link points to a source absent from claim-source links"], "evidence_type": "traditional_narrative", "lens": {"field_id": "de20bc35-2696-4a80-b095-614bb650a581", "field_label": "Advisory relationships with kings or dynasties", "parameter_id": "700ce11a-bd45-4116-99a4-a246dc97c505", "parameter_name": "Relational / Social Role"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Sarga 66 has Vishvamitra request that the bow be shown to the princes.", "link_id": "7327dd00-017e-4aa8-8acc-996246c02835", "page_or_section": "1.66", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur Valmiki Ramayanam Project", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same Bala Kanda chapter is linked below; compare editions before using a quotation.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayanam, Bala Kanda, Sarga 66", "url": "https://www.valmiki.iitk.ac.in/summary?field_kanda_tid=1&field_sarga_value=66"}, "source_id": "0702c2be-0f44-44bd-a8c1-07d82ff398c3"}], "unmatched_passage_links": [{"chunk_id": "ad2aa921-7d84-43f3-b6ff-f5dcf27b708d", "excerpt": "Legend of Shiva''s bow is narrated as Vishvamitra asks Janaka to show   that bow to Rama and Lakshmana, as they have come this far to have a   glimpse of that great bow. Janaka, while narrating its history, makes   an offer saying that his daughter Seetha will be given in marriage,   if only Rama can string the bowstring of Shiva''s bow. In the very same   …", "excerpt_truncated": true, "page_or_section": "Book I : Bala Kanda - The Youthful MajestiesSarga 66 in Prose", "relationship": "context", "source": {"author": "Valmiki (traditional attribution)", "publication_year": null, "publisher_or_institution": "IIT Kanpur Valmiki Ramayanam Project", "rights_or_access_note": null, "source_status": "approved", "source_type": "primary_text", "title": "Valmiki Ramayanam 1.66 — sibling page (valmikiramayan.net)", "url": "https://www.valmikiramayan.net/utf8/baala/sarga66/bala_66_prose.htm"}, "source_id": "0a82a3cf-3c73-408e-92d1-03c271eb8925"}]}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('68cb3f3e-2f39-40d3-90a7-b68c2c27f6cb','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "68cb3f3e-2f39-40d3-90a7-b68c2c27f6cb", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "After Rama handles the bow, Janaka looks to Vishvamitra for consent in sending messengers to Dasharatha, showing the sage functioning as a trusted intermediary between royal houses.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Recorded source access issue", "Claim-passage link points to a source absent from claim-source links"], "evidence_type": "traditional_narrative", "lens": {"field_id": "de20bc35-2696-4a80-b095-614bb650a581", "field_label": "Advisory relationships with kings or dynasties", "parameter_id": "700ce11a-bd45-4116-99a4-a246dc97c505", "parameter_name": "Relational / Social Role"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The post-bow discussion explicitly involves Vishvamitra''s approval before royal messengers are sent.", "link_id": "202a1993-2dfe-41c1-b308-4dcc49fddf3c", "page_or_section": "1.67", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur Valmiki Ramayanam Project", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same Bala Kanda chapter is linked below; compare editions before using a quotation.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayanam, Bala Kanda, Sarga 67", "url": "https://www.valmiki.iitk.ac.in/summary?field_kanda_tid=1&field_sarga_value=67"}, "source_id": "5d52e3f5-c52d-4373-bbe8-80416792eb49"}], "unmatched_passage_links": [{"chunk_id": "b1c1944b-29d4-4c26-a1b9-b6d707e3ac98", "excerpt": "Bewildered by that raucous caused by the breakage of bow, all the people swooned,  except for that eminent-saint Vishvamitra, king Janaka, and those two Raghava-s,  namely Rama and Lakshmana. While the people are being reaccustomed after their undergoing  the shock, at that moment that sententious king Janaka, whose discomfiture has completely  departed by …", "excerpt_truncated": true, "page_or_section": "Book I : Bala Kanda - Book Of Youthful Majesties  Sarga 67 in Prose", "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "publication_year": null, "publisher_or_institution": "IIT Kanpur Valmiki Ramayanam Project", "rights_or_access_note": null, "source_status": "approved", "source_type": "primary_text", "title": "Valmiki Ramayanam 1.67 — sibling page (valmikiramayan.net)", "url": "https://www.valmikiramayan.net/utf8/baala/sarga67/bala_67_prose.htm"}, "source_id": "7c0bc50d-dd59-4b31-804b-0389432eebd1"}]}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('98000dfd-249f-42d3-90ca-cfa8b402a4a0','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "98000dfd-249f-42d3-90ca-cfa8b402a4a0", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "At Mithila Vishvamitra explains to Janaka why Rama and Lakshmana have come, recounting their journey and linking the princes'' visit to the desire to see Shiva''s bow.", "current_status": "approved", "epistemics": {"contract_basis": "tradition", "contract_satisfied": true, "contract_status": "SUPPORTED", "epistemic_type": "TRADITIONAL_NARRATIVE", "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["Current approval origin does not establish strict verification", "Recorded source access issue"], "evidence_type": "traditional_narrative", "lens": {"field_id": "de20bc35-2696-4a80-b095-614bb650a581", "field_label": "Advisory relationships with kings or dynasties", "parameter_id": "700ce11a-bd45-4116-99a4-a246dc97c505", "parameter_name": "Relational / Social Role"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Sarga 50 has Vishvamitra present the princes'' recent history to Janaka.", "link_id": "b5c5d681-0a12-4939-bf80-cc201cf1d72d", "page_or_section": "1.50", "passages": [{"chunk_id": "488dfd2b-47d8-44d7-86f8-bba5d8548695", "confidence": 0.918823529411765, "excerpt": "\"Today my Vedic ritual is enriched with your advent, whereby I deem that gods  have fructified the ritual. Let the ritual be like that. I deem that I have  obtained the fruit of the ritual just on seeing godlike you here today.  \"Oh, Brahman, at which Vedic-ritual hall you have arrived along with so many  sages that happens to be mine, whereby, oh, eminent …", "excerpt_truncated": true, "is_active": true, "link_met