insert into original_claims values ('996b4e9f-3f14-4dde-a9a8-3ee740edb9ee','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "996b4e9f-3f14-4dde-a9a8-3ee740edb9ee", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "The Ramayana presents Vishvamitra in direct relationships with rulers, including asking King Dasharatha to entrust Rama to him for the protection of a sacrifice.", "current_status": "approved", "epistemics": {"contract_basis": "tradition", "contract_satisfied": true, "contract_status": "SUPPORTED", "epistemic_type": "TRADITIONAL_NARRATIVE", "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["Current approval origin does not establish strict verification", "Recorded source access issue", "Claim-passage link points to a source absent from claim-source links"], "evidence_type": "traditional_narrative", "lens": {"field_id": "de20bc35-2696-4a80-b095-614bb650a581", "field_label": "Advisory relationships with kings or dynasties", "parameter_id": "700ce11a-bd45-4116-99a4-a246dc97c505", "parameter_name": "Relational / Social Role"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The narrative places Vishvamitra in direct counsel/request before Dasharatha.", "link_id": "694c57a9-268e-4e5a-a334-29f884865f9c", "page_or_section": "Bala Kanda 1.19", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana, Bala Kanda 1.19. IIT Kanpur Valmiki Ramayanam.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same Bala Kanda chapter is linked below; compare editions before using a quotation.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayanam — Bala Kanda, Sarga 19", "url": "https://www.valmiki.iitk.ac.in/summary?field_kanda_tid=1&field_sarga_value=19"}, "source_id": "1cfcb796-be35-48c3-aa3c-ef3cffec11fc"}], "unmatched_passage_links": [{"chunk_id": "9374da7d-e000-40d3-83fc-7d752aa7f76c", "excerpt": "Sage Vishvamitra asks King Dasharatha to send Rama to protect the Vedic ritual   that is being conducted by him, from the demons that are constantly disrupting   it. The sage asserts King Dasharatha that he and the other sages in Dasharatha''s   court know the capabilities of Rama and though Rama is in his adolescence, he   can easily kill the demons. But …", "excerpt_truncated": true, "page_or_section": "Introduction", "relationship": "supports", "source": {"author": "Valmiki", "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "title": "Valmiki Ramayana, Bala Kanda, Sarga 19", "url": "https://valmikiramayan.net/utf8/baala/sarga19/balasans19.htm"}, "source_id": "826d5c8a-6135-4304-8825-09579ff9a478"}]}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('9e04db9f-e074-4f3a-a770-2e3a7109a3c5','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "9e04db9f-e074-4f3a-a770-2e3a7109a3c5", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "In the Trishanku tradition Vishvamitra becomes patron and ritual advocate for a king rejected elsewhere, placing him in a direct but adversarial relationship with royal-sacrificial legitimacy.", "current_status": "approved", "epistemics": {"contract_basis": "tradition", "contract_satisfied": true, "contract_status": "SUPPORTED", "epistemic_type": "TRADITIONAL_NARRATIVE", "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["Current approval origin does not establish strict verification", "Recorded source access issue"], "evidence_type": "traditional_narrative", "lens": {"field_id": "de20bc35-2696-4a80-b095-614bb650a581", "field_label": "Advisory relationships with kings or dynasties", "parameter_id": "700ce11a-bd45-4116-99a4-a246dc97c505", "parameter_name": "Relational / Social Role"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Trishanku seeks Vishvamitra after rejection by Vasistha''s line and receives his support.", "link_id": "b58e5ac2-d919-4212-b277-af4353781a52", "page_or_section": "1.58-59", "passages": [{"chunk_id": "4849c222-55e8-426f-b3a6-c482a6154f41", "confidence": 0.932173913043478, "excerpt": "Trishanku seeks shelter of Vishvamitra when the sons of Vashishta rebuffed   him, and even cursed him to become a profaner. Narrating his sad tale   and his idealistic idea of going to heaven with mortal body, Trishanku   earnestly appeals to Vishvamitra.  \"On hearing the sentence of Trishanku, oh, Rama, the hundred sons of sage Vashishta  infuriately said …", "excerpt_tr