insert into original_claims values ('ed7d40c3-c8ca-4149-835a-0e26a7d342a3','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "ed7d40c3-c8ca-4149-835a-0e26a7d342a3", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "Shatananda''s retrospective account describes Vishvamitra''s earlier kingship as one in which the welfare of subjects defined the king''s happiness, providing an epic memory of governance before his ascetic transformation.", "current_status": "approved", "epistemics": {"contract_basis": "tradition", "contract_satisfied": true, "contract_status": "SUPPORTED", "epistemic_type": "TRADITIONAL_NARRATIVE", "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["Current approval origin does not establish strict verification", "Recorded source access issue"], "evidence_type": "traditional_narrative", "lens": {"field_id": "de20bc35-2696-4a80-b095-614bb650a581", "field_label": "Advisory relationships with kings or dynasties", "parameter_id": "700ce11a-bd45-4116-99a4-a246dc97c505", "parameter_name": "Relational / Social Role"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Sarga 51''s account of Kausika''s kingship praises his learning and concern for subjects.", "link_id": "6e27a512-5a63-42ce-83c6-f22ce1724b54", "page_or_section": "1.51", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur Valmiki Ramayanam Project", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same Bala Kanda chapter is linked below; compare editions before using a quotation.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayanam, Bala Kanda, Sarga 51", "url": "https://www.valmiki.iitk.ac.in/summary?field_kanda_tid=1&field_sarga_value=51"}, "source_id": "33cac492-759f-493f-88b7-774e6b1785f3"}, {"evidence_excerpt": "Sarga 51''s account of Kausika''s kingship praises his learning and concern for subjects.", "link_id": "0854d743-427b-48ff-8203-a98d0ca287b5", "page_or_section": "1.51", "passages": [{"chunk_id": "df62e567-491e-404e-9393-0f4f24f23977", "confidence": 0.873333333333333, "excerpt": "Enquiring about his father Gautama''s reuniting with his mother Ahalya,   Sage Shataananda relates the legend of Vishvamitra. Shataananda greets   Rama for his adherence to the rectitude of Vishvamitra, which Vishvamitra   gained through a series of self-important exploits, when he was a great   king at one time. Shataananda finds worth in informing the …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Book I : Bala Kanda - The Youthful Majesties\nSarga 51 in Prose", "relationship": "supports", "section_title": "Book I : Bala Kanda - The Youthful Majesties\nSarga 51 in Prose", "source_id": "7a3546e2-6126-489c-a987-5f8354045ba2", "textual_layer": "Ramayana — Bala Kanda"}, {"chunk_id": "efd46cc3-a4a3-4524-bd56-a1c0168d4ca8", "confidence": 0.873333333333333, "excerpt": "On hearing those words of that highly intellectual Vishvamitra, high refulgent sage  Shataananda spoke these words to Rama. \"Hail to thee! Oh, best one among men Rama,  your arrival is a godsend, not only to Mithila but to entire humanity, and oh, Raghava,  as an undefeatable great-sage Vishvamitra spearheads you, so shall your mission  be undefeatable, …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Book I : Bala Kanda - The Youthful Majesties\nSarga 51 in Prose", "relationship": "supports", "section_title": "Book I : Bala Kanda - The Youthful Majesties\nSarga 51 in Prose", "source_id": "7a3546e2-6126-489c-a987-5f8354045ba2", "textual_layer": "Ramayana — Bala Kanda"}], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution); English rendering by Desiraju Hanumanta Rao", "authority_metadata": {"verified_http_status": 200}, "citation": "Valmiki Ramayana, Bala Kanda 1.51, chapter-level prose rendering.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": "Publicly accessible chapter page; preserve source attribution and link.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayana — Bala Kanda, Sarga 51 (prose)", "url": "https://www.valmikiramayan.net/utf8/baala/sarga51/bala_51_prose.htm"}, "source_id": "7a3546e2-6126-489c-a987-5f8354045ba2"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('0c73e76e-6d41-4831-ab52-92cb3e140a02','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "0c73e76e-6d41-4831-ab52-92cb3e140a02", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "Indra''s interactions with Vishvamitra are adversarial and testing across several episodes, including attempts involving Menaka/Rambha and the later food request in disguise.", "current_status": "approved", "epistemics": {"contract_basis": "tradition", "contract_satisfied": true, "contract_status": "SUPPORTED", "epistemic_type": "TRADITIONAL_NARRATIVE", "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["Current approval origin does not establish strict verification", "Recorded source access issue"], "evidence_type": "traditional_narrative", "lens": {"field_id": "a04bf1d1-b32a-40f3-9994-4328cd6eef07", "field_label": "Interactions with other rishis: collaboration, rivalry, debate", "parameter_id": "700ce11a-bd45-4116-99a4-a246dc97c505", "parameter_name": "Relational / Social Role"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The final food test is one of several episodes in which Indra intervenes in Vishvamitra''s tapas narrative.", "link_id": "4894cd43-4ece-4542-8255-a47e234c2f54", "page_or_section": "1.63-65", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur Valmiki Ramayanam Project", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same Bala Kanda chapter is linked below; compare editions before u