insert into original_claims values ('2490638e-c070-403f-b630-206f85ad94ff','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "2490638e-c070-403f-b630-206f85ad94ff", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "Vasistha is not portrayed only as Vishvamitra''s rival: in Bala Kanda 1.21 he strongly endorses Vishvamitra''s knowledge and trustworthiness when persuading Dasharatha to send Rama.", "current_status": "approved", "epistemics": {"contract_basis": "tradition", "contract_satisfied": true, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Recorded source access issue"], "evidence_type": "traditional_narrative", "lens": {"field_id": "a04bf1d1-b32a-40f3-9994-4328cd6eef07", "field_label": "Interactions with other rishis: collaboration, rivalry, debate", "parameter_id": "700ce11a-bd45-4116-99a4-a246dc97c505", "parameter_name": "Relational / Social Role"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Vasistha publicly praises Vishvamitra''s weapon knowledge, ascetic power, and ability to protect Rama.", "link_id": "b9364e60-c91d-4883-9484-c89e25774ae9", "page_or_section": "1.21.11-19", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur Valmiki Ramayanam Project", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same Bala Kanda chapter is linked below; compare editions before using a quotation.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayanam, Bala Kanda, Sarga 21", "url": "https://www.valmiki.iitk.ac.in/summary?field_kanda_tid=1&field_sarga_value=21"}, "source_id": "0537c002-ff50-437a-88f6-1ca1f43572cf"}, {"evidence_excerpt": "Vasistha publicly praises Vishvamitra''s weapon knowledge, ascetic power, and ability to protect Rama.", "link_id": "78a0dede-ec67-4e54-a28d-dbfb7d49d8e8", "page_or_section": "1.21.11-19", "passages": [{"chunk_id": "16e8b4c0-c2b9-44bb-b4df-2f3f97395940", "confidence": 0.82, "excerpt": "\"All the missiles known to Vishvamitra are the highly righteous children of Krishaasva  Prajapati, where Prajapati-s were the earliest ruler of mankind, and god Shiva gave them to Vishvamitra  when was ruling kingdom. Those missiles are the sons of Daksha Prajaapati''s daughters and her husband  Krishaasva Prajapati, and they are disparate in their form, …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Valmiki Ramayana - Bala Kanda in \nProse Sarga 21", "relationship": "supports", "section_title": "Valmiki Ramayana - Bala Kanda in \nProse Sarga 21", "source_id": "9227358e-67a7-46f5-a873-bb5582ebb893", "textual_layer": "Ramayana — Bala Kanda"}, {"chunk_id": "eb13ef00-ba13-431c-9957-e70d915433bf", "confidence": 0.88, "excerpt": "The ire of sage Vishvamitra is shown at king Dasharatha. To pacify sage Vishvamitra,  sage Vashishta intervenes and convinces king Dasharatha to send Rama with sage Vishvamitra. While doing  so, sage Vashishta enumerates the capabilities of sage Vishvamitra, his knowledge of weaponry. Vashishta  also suggests that all those weapons will be given to Rama, if …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Valmiki Ramayana - Bala Kanda in \nProse Sarga 21", "relationship": 