insert into original_claims values ('375deee8-bbb1-4032-b108-692c108c2bd2','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "375deee8-bbb1-4032-b108-692c108c2bd2", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "The transformation narrative culminates not merely with divine recognition but with Vasistha''s explicit acceptance of Vishvamitra as Brahmarshi.", "current_status": "approved", "epistemics": {"contract_basis": "tradition", "contract_satisfied": true, "contract_status": "SUPPORTED", "epistemic_type": "TRADITIONAL_NARRATIVE", "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source", "Claim-passage link points to a source absent from claim-source links"], "evidence_type": "traditional_narrative", "lens": {"field_id": "a04bf1d1-b32a-40f3-9994-4328cd6eef07", "field_label": "Interactions with other rishis: collaboration, rivalry, debate", "parameter_id": "700ce11a-bd45-4116-99a4-a246dc97c505", "parameter_name": "Relational / Social Role"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Vasistha says there is no doubt that Vishvamitra is a Brahmarshi.", "link_id": "7b9359eb-5535-4326-9593-bad52edd0047", "page_or_section": "1.65.26-27", "passages": [{"chunk_id": "5b71c4bf-b0a2-47bd-b126-271b16c341d3", "confidence": 0.830769230769231, "excerpt": "\" ''Along with the assemblages of Marut-Wind-gods, I bestow upon you a long life.  Let blissfulness betide you. You be safe. Oh, gentle sage, you may take leave as  you please.'' Thus, Brahma said to Vishvamitra. [1-65-20b, 21a]  पितामह वचः श्रुत्वा सर्वेषाम् त्रिदिव ओकसाम् || १-६५-२१ कृत्वा प्रणामम् मुदितो व्याजहार महामुनिः |  21b, 22a. mahaamuniH = …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Introduction", "relationship": "supports", "section_title": "Introduction", "source_id": "b1ff445c-d9d0-4f8e-a28f-f3a8053787ad", "textual_layer": "Ramayana — Bala Kanda"}, {"chunk_id": "f5d6ea55-a71d-40d3-a62f-a3c4632bc140", "confidence": 0.830769230769231, "excerpt": "ब्रह्मर्षिः त्वम् न संदेहः सर्वम् संपद्यते तव | इति उक्त्वा देवताः च अपि सर्वा जग्मुः यथा आगतम् || १-६५-२६  26. tvam brahmarSiH = you are, Brahma-sage; sandehaH na = doubt,  is not there; tava sarvam sampadyate = to you, everything, will accrue  - in accordance with this sageship; iti uktvaa = thus, on saying; sarvaa  devataaH ca api = all, gods, also, …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Introduction", "relationship": "supports", "section_title": "Introduction", "source_id": "b1ff445c-d9d0-4f8e-a28f-f3a8053787ad", "textual_layer": "Ramayana — Bala Kanda"}], "relationship": "supports", "source": {"author": "Valmiki", "authority_metadata": {}, "citation": "Valmiki Ramayana, Bala Kanda, Sarga 65 (https://www.valmikiramayan.net/utf8/baala/sarga65/balasans65.htm.orig)", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Valmiki Ramayana, Bala Kanda, Sarga 65", "url": "https://www.valmikiramayan.net/utf8/baala/sarga65/balasans65.htm.orig"}, "source_id": "b1ff445c-d9d0-4f8e-a28f-f3a8053787ad"}], "unmatched_passage_links": [{"chunk_id": "383490b2-4a1b-4312-a927-eb63e1e46f35", "excerpt": "became their purohita.^ Both Asita and Devala were celebrated brahma-vadins^ as mentioned above ;^ and oth-jr statements are made about them in brahmanical accounts.^ Various other Kasyapas are mentioned, such as Yaja, who became king- Drupada''s sacrifice;^ but they are generally indefinite or unimportant. The genealogy says there were three groups among …", "excerpt_truncated": true, "page_or_section": "p. 234 (scan leaf 246)", "relationship": "context", "source": {"author": "F. E. Pargiter", "publication_year": 1922, "publisher_or_institution": "Oxford University Press (London: Humphrey Milford)", "rights_or_access_note": "Rights-clear public-domain scan (archive.org item metadata: NOT_IN_COPYRIGHT; scanned by University of Toronto Robarts Library). Only pages naming Vishvamitra and relevant to approved claims were ingested.", "source_status": "approved", "source_type": "scholarly_book", "title": "Ancient Indian Historical Tradition", "url": "https://archive.org/details/ancientindianhis00parguoft"}, "source_id": "70bed1d6-b121-41fb-9ec4-650a746f154c"}, {"chunk_id": "9870780e-cb83-4682-a1a8-c8b9a2b68519", "excerpt": "But tradition hardly seems to acknowledg-e this distinction^ for the Visvamitras generally seem to have been known as Kusikas and Kausikas^ after Visvamitra^s grandfather king Kusika (p. 144). The next Visvamitra was the father of Sakuntala, Dusyanta''s queen and Bharata''s mother {ante). Nothing particular is said about him and he is generally confused with …", "excerpt_truncated": true, "page_or_section": "p. 236 (scan leaf 248)", "relationship": "context", "source": {"author": "F. E. Pargiter", "publication_year": 1922, "publisher_or_institution": "Oxford University Press (London: Humphrey Milford)", "rights_or_access_note": "Rights-clear public-domain scan (archive.org item metadata: NOT_IN_COPYRIGHT; scanned by University of Toronto Robarts Library). Only pages naming Vishvamitra and relevant to approved claims were ingested.", "source_status": "approved", "source_type": "scholarly_book", "title": "Ancient Indian Historical Tradition", "url": "https://archive.org/details/ancientindianhis00parguoft"}, "source_id": "70bed1d6-b121-41fb-9ec4-650a746f154c"}]}':