insert into original_claims values ('49785a44-fbae-406d-b7f6-6ca55f096ad3','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "49785a44-fbae-406d-b7f6-6ca55f096ad3", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "The Ramayana narrates a prolonged Vishvamitra–Vasistha relationship that moves through conflict and culminates in Vasistha’s recognition of Vishvamitra as Brahmarshi.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "PARTIALLY_SUPPORTED", "epistemic_type": "TRADITIONAL_NARRATIVE", "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Current approval origin does not establish strict verification", "Recorded source access issue", "Claim-passage link points to a source absent from claim-source links"], "evidence_type": "traditional_narrative", "lens": {"field_id": "a04bf1d1-b32a-40f3-9994-4328cd6eef07", "field_label": "Interactions with other rishis: collaboration, rivalry, debate", "parameter_id": "700ce11a-bd45-4116-99a4-a246dc97c505", "parameter_name": "Relational / Social Role"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Vasistha explicitly acknowledges Vishvamitra as Brahmarshi.", "link_id": "fa8f0191-185e-412f-a02c-353f7a85d20e", "page_or_section": "Bala Kanda 1.65.23–26", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana, Bala Kanda 1.65. IIT Kanpur Valmiki Ramayanam.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same Bala Kanda chapter is linked below; compare editions before using a quotation.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayanam — Bala Kanda, Sarga 65", "url": "https://www.valmiki.iitk.ac.in/sloka?field_kanda_tid=1&field_sarga_value=65&language=dv"}, "source_id": "ba6fee9f-7a6a-413e-80f0-045ce4c2ffea"}], "unmatched_passage_links": [{"chunk_id": "3cd3af14-7e10-43dd-8dee-276714bab92a", "excerpt": "47 thus help paint an idealized moral backdrop to the turbulent events of the primary narrative, a storyworld populated with bodies clearly marked as Brahman, Kṣatriya, Vaiśya, or Śūdra.22 At the same time, these embedded stories often feature characters whose actions pose striking challenges to Brahmanic social norms.23 Viśvāmitra, for example, is the only …", "excerpt_truncated": true, "page_or_section": "p. 47 (PDF page 7)", "relationship": "context", "source": {"author": "Adheesh Sathaye", "publication_year": 2007, "publisher_or_institution": "Acta Orientalia Vilnensia / Vilnius University Press", "rights_or_access_note": "Official journal diamond open access, CC BY 4.0: https://www.journals.vu.lt/acta-orientalia-vilnensia/journalpolicy", "source_status": "approved", "source_type": "scholarly_article", "title": "How to become a Brahman: The construction of varṇa as social place in the Mahābhārata’s legends of Viśvāmitra", "url": "https://www.journals.vu.lt/acta-orientalia-vilnensia/article/download/3751/5207"}, "source_id": "06fec486-e5af-4c7e-95db-afbb2e237c75"}, {"chunk_id": "5b71c4bf-b0a2-47bd-b126-271b16c341d3", "excerpt": "\" ''Along with the assemblages of Marut-Wind-gods, I bestow upon you a long life.  Let blissfulness betide you. You be safe. Oh, gentle sage, you may take leave as  you please.'' Thus, Brahma said to Vishvamitra. [1-65-20b, 21a]  पितामह वचः श्रुत्वा सर्वेषाम् त्रिदिव ओकसाम् || १-६५-२१ कृत्वा प्रणामम् मुदितो व्याजहार महामुनिः |  21b, 22a. mahaamuniH = …", "excerpt_truncated": true, "page_or_section": "Introduction", "relationship": "context", "source": {"author": "Valmiki", "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "title": "Valmiki Ramayana, Bala Kanda, Sarga 65", "url": "https://www.valmikiramayan.net/utf8/baala/sarga65/balasans65.htm.orig"}, "source_id": "b1ff445c-d9d0-4f8e-a28f-f3a8053787ad"}, {"chunk_id": "ca0f8f83-0fca-448d-8af5-483d8ceb3687", "excerpt": "how to become a Brahman: the construction of varṇa as social place in the Mahābhārata’s legends of Viśvāmitra Adheesh Sathaye University of British Columbia This article investigates varṇa as an embodied and spatialized social practice in the Sanskrit Mahābhārata, with a focus on the epic subnarratives of Viśvāmitra, the legendary king who became a Brahman. …", "excerpt_truncated": true, "page_or_section": "p. 41 (PDF page 1)", "relationship": "context", "source": {"author": "Adheesh Sathaye", "publication_year": 2007, "publisher_or_institution": "Acta Orientalia Vilnensia / Vilnius University Press", "rights_or_access_note": "Official journal diamond open access, CC BY 4.0: https://www.journals.vu.lt/acta-orientalia-vilnensia/journalpolicy", "source_status": "approved", "source_type": "scholarly_article", "title": "How to become a Brahman: The construction of varṇa as social place in the Mahābhārata’s legends of Viśvāmitra", "url": "https://www.journals.vu.lt/acta-orientalia-vilnensia/article/download/3751/5207"}, "source_id": "06fec486-e5af-4c7e-95db-afbb2e237c75"}, {"chunk_id": "e5fb1a31-b359-4f2d-b844-49153434802a", "excerpt": "44 Tell me how Triśaṅku, the Ikṣvāku, though shunned by his peers, was led gladly into heaven, upside-down, and placed in the southern direction.9 Tell me how Viśvāmitra’s broad river, the Kauśikī, is frequented by rājarṣis [royal sages], blessed and auspicious, and served by throngs of brahmarṣis [Brahman-sages].10 Tell me how the esteemed nymph named …", "excerpt_truncated": true, "page_or_section": "p. 44 (PDF page 4)", "relationship": "context", "source": {"author": "Adheesh Sathaye", "publication_year": 2007, "publisher_or_institution": "Acta Orientalia Vilnensia / Vilnius University Press", "rights_or_access_note": "Official journal diamond open access, CC BY 4.0: https://www.journals.vu.lt/acta-orientalia-vilnensia/journalpolicy", "source_status": "approved", "source_type": "scholarly_article", "title": "How to become a Brahman: The construction of varṇa as social place in the Mahābhārata’s legends of Viśvāmitra", "url": "https://www.journals.vu.lt/acta-orientalia-vilnensia/article/download/3751/5207"}, "source_id": "06fec486-e5af-4c7e-95db-afbb2e237c75"}]}'::jsonb,'approved','system_test_bulk');
