insert into original_claims values ('76c99f89-0e8f-4f92-9895-34657b974ace','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "76c99f89-0e8f-4f92-9895-34657b974ace", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "The Vasistha-Vishvamitra relationship is central to the epic biography: conflict over Shabala becomes a turning point in Vishvamitra''s movement from royal power toward ascetic power.", "current_status": "approved", "epistemics": {"contract_basis": "tradition", "contract_satisfied": true, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "traditional_narrative", "lens": {"field_id": "a04bf1d1-b32a-40f3-9994-4328cd6eef07", "field_label": "Interactions with other rishis: collaboration, rivalry, debate", "parameter_id": "700ce11a-bd45-4116-99a4-a246dc97c505", "parameter_name": "Relational / Social Role"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The Shabala dispute directly pits King Vishvamitra against Sage Vasistha.", "link_id": "42d7b012-836b-4165-b67b-b543d5b035d1", "page_or_section": "1.53", "passages": [{"chunk_id": "d875c0e7-aa4d-4c0c-bdc7-baa0d08e5529", "confidence": 0.848571428571429, "excerpt": "\"When honoured along with his advisers, ministers and attendants by way of receiving a royal banquet,  king Vishvamitra then in high admiration spoke this to Vashishta. [1-53-7]  पूजितो अहम् त्वया ब्रह्मन् पूज अर्हेण सुसत्कृतः |श्रूयताम् अभिधास्यामि वाक्यम् वाक्य विशारद || १-५३-८  8. brahman = oh, Brahman; puuja a