insert into original_claims values ('88575aed-b45d-4148-b30f-2af470dd8103','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "88575aed-b45d-4148-b30f-2af470dd8103", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "Brahma appears repeatedly as the authority who grants intermediate recognition yet withholds final satisfaction, making divine evaluation part of Vishvamitra''s staged ascetic progression.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Recorded source access issue"], "evidence_type": "traditional_narrative", "lens": {"field_id": "a04bf1d1-b32a-40f3-9994-4328cd6eef07", "field_label": "Interactions with other rishis: collaboration, rivalry, debate", "parameter_id": "700ce11a-bd45-4116-99a4-a246dc97c505", "parameter_name": "Relational / Social Role"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "After a thousand-year cycle Brahma grants an elevated title but the narrative continues toward further discipline.", "link_id": "94146dd6-fb05-40d9-81a0-d29313d31de2", "page_or_section": "1.63", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana, Bala Kanda 1.63. IIT Kanpur Valmiki Ramayanam.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same Bala Kanda chapter is linked below; compare editions before using a quotation.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayanam — Bala Kanda, Sarga 63", "url": "https://www.valmiki.iitk.ac.in/sloka?field_kanda_tid=1&field_sarga_value=63&language=dv"}, "source_id": "2025af50-f65e-4a13-b670-adc6a2a0e3dc"}, {"evidence_excerpt": "After a thousand-year cycle Brahma grants an elevated title but the narrative continues toward further discipline.", "link_id": "d077b0ea-a2ac-48e9-bae0-eb73ff7381e0", "page_or_section": "1.63", "passages": [{"chunk_id": "1c601c57-75d6-404c-868e-11361f2be7ee", "confidence": 0.867586206896552, "excerpt": "\" ''All this is the mischief of gods to defraud me of the great merit of my ascesis.  Ten years have rolled by as if they are just a day and a night. Furthermore, I who  am under the influence of lust and lure had to encounter this hindrance in my ascesis.''  Oh, Rama, that best saint suspired heavily when he became emotional with reparation.  But on seeing …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Book I : Bala Kanda - The Youthful Majesties\niSarga 63 n Prose", "relationship": "supports", "section_title": "Book I : Bala Kanda - The Youthful Majesties\niSarga 63 n Prose", "source_id": "d39ddd21-67b7-4c7c-bfae-ea1f99918420", "textual_layer": "Ramayana — Bala Kanda"}, {"chunk_id": "9c862712-4d53-404e-a5bb-1c24e1296451", "confidence": 0.89448275862069, "excerpt": "On Vishvamitra''s performing severe ascesis Brahma accords the sageship   of ''Great-sage'' to him, whereas Vishvamitra''s ambition is to acquire   the sageship of a ''Brahma-sage'' Absolute-sageship. In the meanwhile,   the celestial wench Menaka arrives at that place and Vishvamitra is   enticed by her beauty and spends some years with her. Later, on realising  …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Book I : Bala Kanda - The Youthful Majesties\niSarga 63 n Prose", "relationship": "supports", "section_title": "Book I : Bala Kanda - The Youthful Majesties\niSarga 63 n Prose", "source_id": "d39ddd21-67b7-4c7c-bfae-ea1f99918420", "textual_layer": "Ramayana — Bala Kanda"}], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution); English rendering by Desiraju Hanumanta Rao", "authority_metadata": {"verified_http_status": 200}, "citation": "Valmiki Ramayana, Bala Kanda 1.63, chapter-level prose rendering.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": "Publicly accessible chapter page; preserve source attribution and link.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayana — Bala Kanda, Sarga 63 (prose)", "url": "https://www.valmikiramayan.net/utf8/baala/sarga63/bala_63_prose.htm"}, "source_id": "d39ddd21-67b7-4c7c-bfae-ea1f99918420"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('a3ac2e12-2923-4423-a36f-b4cf5b6f17d0','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "a3ac2e12-2923-4423-a36f-b4cf5b6f17d0", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "The early Vasistha hermitage visit begins with formal hospitality and mutual inquiry before the Shabala dispute, so the relationship is initially narrated through guest-host etiquette rather than immediate hostility.", "current_status": "approved", "epistemics": {"contract_basis": "tradition", "contract_satisfied": true, "contract_status": "SUPPORTED", "epistemic_type": "TRADITIONAL_NARRATIVE", "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["Current approval origin does not establish strict verification", "Recorded source access issue"], "evidence_type": "traditional_narrative", "lens": {"field_id": "a04bf1d1-b32a-40f3-9994-4328cd6eef07", "field_label": "Interactions with other rishis: collaboration, rivalry, debate", "parameter_id": "700ce11a-bd45-4116-99a4-a246dc97c505", "parameter_name": "Relational / Social Role"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Vishvamitra asks after the hermitage, austerities, sacrifices, disciples, and trees after being received by Vasistha.", "link_id": "3c7390a0-667a-4d46-99a9-45fca3ad7598", "page_or_section": "1.52", "passages": [{"chunk_id": "3de92d6c-3eb4-4ea0-bc5a-1c74580fe53b", "confidence": 0.921379310344828, "excerpt": "Vashishta offers hospitality to Vishvamitra and his armies. Even though   the King Vishvamitra is disinclined to pressurise a hermit with such   a burdensome affair of hospitality to hosts, Vashishta entreats the   king to accept. Vishvamitra had to oblige the same. Vashishta summons   his do-all Divine Sacred Cow, Shabala, also known as Kaamadhenu, …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Book I : Bala Kanda - The Youthful Majesties\n Sarga 52 in Prose", "relationship": "supports", "section_title": "Book I : Bala Kanda - The Youthful Majesties\n Sarga 52 in Prose", "source_id": "cd5ab49d-c448-4872-9ac8-d51b431647e6", "textual_layer": "Ramayana — Bala Kanda"}, {"chunk_id": "7aeb0416-a6d5-40b8-8ab4-bef492be6d50", "confidence": 0.921379310344828, "excerpt": "''It is quiet meaningless on the part of this sage, subsisting on wild fruits and  tubers, to offer a royal banquet or rations to military and feed to horses and elephants''  - is the thinking of King Vishvamitra. For that, the sage is saying that a king  is to be reverenced ''effortfully...'' But, Vishvamitra is reluctantly evading the  so-called hospitality …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Book I : Bala Kanda - The Youthful Majesties\n Sarga 52 in Prose", "relationship": "supports", "section_title": "Book I : Bala Kanda - The Youthful Majesties\n Sarga 52 in Prose", "source_id": "cd5ab49d-c448-4872-9ac8-d51b431647e6", "textual_layer": "Ramayana — Bala Kanda"}], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution); English rendering by Desiraju Hanumanta Rao", "authority_metadata": {"verified_http_status": 200}, "citation": "Valmiki Ramayana, Bala Kanda 1.52, chapter-level prose rendering.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": "Publicly accessible chapter page; preserve source attribution and link.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayana — Bala Kanda, Sarga 52 (prose)", "url": "https://www.valmikiramayan.net/utf8/baala/sarga52/bala_52_prose.htm"}, "source_id": "cd5ab49d-c448-4872-9ac8-d51b431647e6"}, {"evidence_excerpt": "Vishvamitra asks after the hermitage, austerities, sacrifices, disciples, and trees after being received by Vasistha.", "link_id": "1e243f09-ecd1-4421-83a2-ef70674a47c0", "page_or_section": "1.52", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur Valmiki Ramayanam Project", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same Bala Kanda chapter is linked below; compare editions before using a quotation.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayanam, Bala Kanda, Sarga 52", "url": "https://www.valmiki.iitk.ac.in/summary?field_kanda_tid=1&field_sarga_value=52"}, "source_id": "ce375a1c-3a5c-46fe-9d70-84af48c52744"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('a972419e-df1c-4a74-b8c1-8063afde85a0','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "a972419e-df1c-4a74-b8c1-8063afde85a0", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "Shatananda, Gautama and Ahalya''s son, is the narrator who praises Vishvamitra and recounts his earlier life at Janaka''s court, making him an important internal witness to the sage''s reputation.", "current_status": "approved", "epistemics": {"contract_basis": "tradition", "contract_satisfied": true, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Recorded source access issue"], "evidence_type": "traditional_narrative", "lens": {"field_id": "a04bf1d1-b32a-40f3-9994-4328cd6eef07", "field_label": "Interactions with other rishis: collaboration, rivalry, debate", "parameter_id": "700ce11a-bd45-4116-99a4-a246dc97c505", "parameter_name": "Relational / Social Role"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Shatananda asks about Vishvamitra and begins the long retrospective narrative.", "link_id": "7cef145f-7853-44dc-8956-47de98428c8a", "page_or_section": "1.51", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur Valmiki Ramayanam Project", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same Bala Kanda chapter is linked below; compare editions before using a quotation.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayanam, Bala Kanda, Sarga 51", "url": "https://www.valmiki.iitk.ac.in/summary?field_kanda_tid=1&field_sarga_value=51"}, "source_id": "33cac492-759f-493f-88b7-774e6b1785f3"}, {"evidence_excerpt": "Shatananda asks about Vishvamitra and begins the long retrospective narrative.", "link_id": "e3b9c5af-6204-4d80-81f6-cfa91cadbdea", "page_or_section": "1.51", "passages": [{"chunk_id": "df62e567-491e-404e-9393-0f4f24f23977", "confidence": 0.934545454545455, "excerpt": "Enquiring about his father Gautama''s reuniting with his mother Ahalya,   Sage Shataananda relates the legend of Vishvamitra. Shataananda greets   Rama for his adherence to the rectitude of Vishvamitra, which Vishvamitra   gained through a series of self-important exploits, when he was a great   king at one time. Shataananda finds worth in informing the …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Book I : Bala Kanda - The Youthful Majesties\nSarga 51 in Prose", "relationship": "supports", "section_title": "Book I : Bala Kanda - The Youthful Majesties\nSarga 51 in Prose", "source_id": "7a3546e2-6126-489c-a987-5f8354045ba2", "textual_layer": "Ramayana — Bala Kanda"}, {"chunk_id": "efd46cc3-a4a3-4524-bd56-a1c0168d4ca8", "confidence": 0.934545454545455, "excerpt": "On hearing those words of that highly intellectual Vishvamitra, high refulgent sage  Shataananda spoke these words to Rama. \"Hail to thee! Oh, best one among men Rama,  your arrival is a godsend, not only to Mithila but to entire humanity, and oh, Raghava,  as an undefeatable great-sage Vishvamitra spearheads you, so shall your mission  be undefeatable, …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Book I : Bala Kanda - The Youthful Majesties\nSarga 51 in Prose", "relationship": "supports", "section_title": "Book I : Bala Kanda - The Youthful Majesties\nSarga 51 in Prose", "source_id": "7a3546e2-6126-489c-a987-5f8354045ba2", "textual_layer": "Ramayana — Bala Kanda"}], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution); English rendering by Desiraju Hanumanta Rao", "authority_metadata": {"verified_http_status": 200}, "citation": "Valmiki Ramayana, Bala Kanda 1.51, chapter-level prose rendering.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": "Publicly accessible chapter page; preserve source attribution and link.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayana — Bala Kanda, Sarga 51 (prose)", "url": "https://www.valmikiramayan.net/utf8/baala/sarga51/bala_51_prose.htm"}, "source_id": "7a3546e2-6126-489c-a987-5f8354045ba2"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('b9d19737-9bca-4614-800f-081200b79689','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "b9d19737-9bca-4614-800f-081200b79689", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "The Mahabharata traditions therefore preserve both violent rivalry and later recognition/test motifs involving Vasistha, warning against reducing the relationship to a single unchanging interpersonal story.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source", "Recorded source access issue"], "evidence_type": "traditional_narrative", "lens": {"field_id": "a04bf1d1-b32a-40f3-9994-4328cd6eef07", "field_label": "Interactions with other rishis: collaboration, rivalry, debate", "parameter_id": "700ce11a-bd45-4116-99a4-a246dc97c505", "parameter_name": "Relational / Social Role"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Different parvas and the Ramayana assign markedly different functions to the Vishvamitra-Vasistha relationship.", "link_id": "5e4fdcb7-996c-4195-aea2-5678959e50f9", "page_or_section": "Cross-text synthesis", "passages": [], "relationship": "supports", "source": {"author": "Vyasa (traditional attribution); BORI Critical Edition", "authority_metadata": {}, "citation": "Mahabharata BORI, Adi Parva, 166", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Bhandarkar Oriental Research Institute critical text / Vedapath presentation", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Mahabharata (BORI Critical Edition), Adi Parva, Adhyaya 166", "url": "https://vedapath.app/en/mahabharata-bori/adi-parva/166"}, "source_id": "45d82d9c-b330-4c24-8bb2-25434372729d"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('e3a8cb39-8e99-46bf-ad98-22ddfe0d45ec','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "e3a8cb39-8e99-46bf-ad98-22ddfe0d45ec", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "In Mahabharata Udyoga Parva, Dharma adopts the appearance of Vasistha to test Vishvamitra''s hospitality, symbolically reusing the Vasistha relationship in a very different narrative setting.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "UNSUPPORTED", "epistemic_type": "TRADITIONAL_NARRATIVE", "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source", "Recorded source access issue"], "evidence_type": "traditional_narrative", "lens": {"field_id": "a04bf1d1-b32a-40f3-9994-4328cd6eef07", "field_label": "Interactions with other rishis: collaboration, rivalry, debate", "parameter_id": "700ce11a-bd45-4116-99a4-a246dc97c505", "parameter_name": "Relational / Social Role"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The test explicitly uses Vasistha''s form before Vishvamitra''s brahmana status is affirmed.", "link_id": "bdb085d2-d303-4bb3-87e9-43c59560de9d", "page_or_section": "5.104", "passages": [], "relationship": "supports", "source": {"author": "Vyasa (traditional attribution); BORI Critical Edition", "authority_metadata": {}, "citation": "Mahabharata BORI, Udyoga Parva, 104", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Bhandarkar Oriental Research Institute critical text / Vedapath presentation", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Mahabharata (BORI Critical Edition), Udyoga Parva, Adhyaya 104", "url": "https://vedapath.app/en/mahabharata-bori/udyoga-parva/104"}, "source_id": "855f8c75-16cc-4e96-9ba3-d79579231842"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('e7f3f6e9-2653-45df-8506-27d02bc380ff','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "e7f3f6e9-2653-45df-8506-27d02bc380ff", "claim_kind": "traditional_account", "claim_relations": [], "claim_text": "Vishvamitra identifies the demons disrupting his ritual near its completion as Mareecha and Subaahu, who drench the fire altar with blood and meat.", "current_status": "approved", "epistemics": {"contract_basis": "tradition", "contract_satisfied": true, "contract_status": "SUPPORTED", "epistemic_type": "TRADITIONAL_NARRATIVE", "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "traditional_narrative", "lens": {"field_id": "a04bf1d1-b32a-40f3-9994-4328cd6eef07", "field_label": "Interactions with other rishis: collaboration, rivalry, debate", "parameter_id": "700ce11a-bd45-4116-99a4-a246dc97c505", "parameter_name": "Relational / Social Role"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Sage Vishvamitra asks King Dasharatha to send Rama to protect the Vedic ritual   that is being conducted by him, from the demons that are constantly disrupting   it. The sage asserts King Dasharatha that he and the other sages in Dasharatha''s   court know the capabilities of Rama and though Rama is in his adolescence, he   can easily kill the demons. But …", "link_id": "cf004146-091f-49bb-ac66-cfe5ac12be99", "page_or_section": "Introduction", "passages": [{"chunk_id": "49491f41-5500-43be-977a-a8f12fc6841f", "confidence": 0.99, "excerpt": "\"At the near end of almost completed ritual of mine two valiant and well-trained   demons, namely Mareecha and Subaahu, are drenching the Altar of Fire with streams   of meat and blood. [1-19-5, 6a]  अवधूते तथाभूते तस्मिन्नियमनिश्चये || १-१९-६  कृतश्रमो निरुत्साहस्तस्माद्देशादपाक्रमे |  6b, 7a. tasmin niyamanishchaye = that, ritual vow; avadhuute   = …", "excerpt_truncated": true, "is_active": true, "link_method": "section_metadata", "page_or_section": "Introduction", "relationship": "supports", "section_title": "Introduction", "source_id": "826d5c8a-6135-4304-8825-09579ff9a478", "textual_layer": "Ramayana — Bala Kanda, Sarga 19"}, {"chunk_id": "9374da7d-e000-40d3-83fc-7d752aa7f76c", "confidence": 0.99, "excerpt": "Sage Vishvamitra asks King Dasharatha to send Rama to protect the Vedic ritual   that is being conducted by him, from the demons that are constantly disrupting   it. The sage asserts King Dasharatha that he and the other sages in Dasharatha''s   court know the capabilities of Rama and though Rama is in his adolescence, he   can easily kill the demons. But …", "excerpt_truncated": true, "is_active": true, "link_method": "section_metadata", "page_or_section": "Introduction", "relationship": "supports", "section_title": "Introduction", "source_id": "826d5c8a-6135-4304-8825-09579ff9a478", "textual_layer": "Ramayana — Bala Kanda, Sarga 19"}, {"chunk_id": "b1bc66f5-1954-483e-a7db-b00c168c90df", "confidence": 0.913548387096774, "excerpt": "Now Rama''s reputation is going to be enhanced by Sage Vishvamitra in eliminating   demoness Tataka, in releasing Ahalya from her curse, breaking Shiva''s bow, marriage   with Seetha, rebuffing Parashuraama etc. And also Vishvamitra leaves the decision   to Dasharatha, ''if only your ministers, clergy as well political, permit then   alone you send Rama with …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Introduction", "relationship": "supports", "section_title": "Introduction", "source_id": "826d5c8a-6135-4304-8825-09579ff9a478", "textual_layer": "Ramayana — Bala Kanda, Sarga 19"}], "relationship": "supports", "source": {"author": "Valmiki", "authority_metadata": {}, "citation": "Valmiki Ramayana, Bala Kanda, Sarga 19 (https://valmikiramayan.net/utf8/baala/sarga19/balasans19.htm)", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Valmiki Ramayana, Bala Kanda, Sarga 19", "url": "https://valmikiramayan.net/utf8/baala/sarga19/balasans19.htm"}, "source_id": "826d5c8a-6135-4304-8825-09579ff9a478"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('f644de11-fdae-4dc1-b381-45812aae69a6','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "f644de11-fdae-4dc1-b381-45812aae69a6", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "After acquiring weapons through ascetic practice, Vishvamitra again confronts Vasistha, and the Brahma-danda episode emphasizes the limits of martial power against brahmanical ascetic power.", "current_status": "approved", "epistemics": {"contract_basis": "tradition", "contract_satisfied": true, "contract_status": "SUPPORTED", "epistemic_type": "TRADITIONAL_NARRATIVE", "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "traditional_narrative", "lens": {"field_id": "a04bf1d1-b32a-40f3-9994-4328cd6eef07", "field_label": "Interactions with other rishis: collaboration, rivalry, debate", "parameter_id": "700ce11a-bd45-4116-99a4-a246dc97c505", "parameter_name": "Relational / Social Role"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Sarga 55 narrates Vishvamitra''s return with missiles and Vasistha''s opposition through the Brahma-danda.", "link_id": "8bf58ef1-584a-4868-a63d-0f337f899049", "page_or_section": "1.55", "passages": [{"chunk_id": "a2fc6f30-74e7-4faf-8a7e-e6ac98483baa", "confidence": 0.905454545454545, "excerpt": "\"After a long lost time, the Holy Bull masted God of Gods, Shiva, has shown himself  to that great-saint Vishvamitra, for He is a ready boon-giver...  \" ''Oh, king, for which purpose you undertook this ascesis... tell that, what really  is tellable by you... what is the boon that you beseech... that be made kno