insert into original_claims values ('10c95288-090d-4e4a-8ebd-f5514ced25d0','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "10c95288-090d-4e4a-8ebd-f5514ced25d0", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "Vishvamitra directly stages Rama''s entry into the Ahalya-Gautama episode by inviting him into the hermitage and explaining its background.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "PARTIALLY_SUPPORTED", "epistemic_type": "TRADITIONAL_NARRATIVE", "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Current approval origin does not establish strict verification", "Recorded source access issue", "Claim-passage link points to a source absent from claim-source links"], "evidence_type": "traditional_narrative", "lens": {"field_id": "480af3d9-6cea-428a-8b51-7a4c721f8545", "field_label": "Role in Ramayana / Mahabharata narratives when applicable", "parameter_id": "700ce11a-bd45-4116-99a4-a246dc97c505", "parameter_name": "Relational / Social Role"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Sarga 49 links his guidance to the restoration and reunion episode.", "link_id": "2fd534bb-fece-4b6f-b2c9-b948ae69e1a7", "page_or_section": "1.49", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur Valmiki Ramayanam Project", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same Bala Kanda chapter is linked below; compare editions before using a quotation.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayanam, Bala Kanda, Sarga 49", "url": "https://www.valmiki.iitk.ac.in/summary?field_kanda_tid=1&field_sarga_value=49"}, "source_id": "acd930f8-6206-4068-8b46-c6da0ebee1c8"}], "unmatched_passage_links": [{"chunk_id": "1e94d760-1a06-442d-a84c-c9da728260d0", "excerpt": "Crafted by the Creator with a careful contemplation she is like a completely phantasmal  divine entity, and she is limbed like the tongue of a flaring fire, but cloaked around are the fumes,  [for, she is hitherto practising an utmost penance subsisting on air alone, that alone made her like  a flaring Ritual Fire.] She is like a full moon, but befogged and …", "excerpt_truncated": true, "page_or_section": "Book \nI : Bala Kanda - The Youthful Majesties Sarga 49 in Prose", "relationship": "context", "source": {"author": "Valmiki (traditional attribution)", "publication_year": null, "publisher_or_institution": "IIT Kanpur Valmiki Ramayanam Project", "rights_or_access_note": null, "source_status": "approved", "source_type": "primary_text", "title": "Valmiki Ramayanam 1.49 — sibling page (valmikiramayan.net)", "url": "https://www.valmikiramayan.net/utf8/baala/sarga49/bala_49_prose.htm"}, "source_id": "87bde6ad-021d-41ed-a177-1748962939ba"}]}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('1154a63a-081f-4456-ba98-d9c7f4cc7066','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "1154a63a-081f-4456-ba98-d9c7f4cc7066", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "He leads Rama and Lakshmana onward toward Mithila and remains part of the narrative through the marriage-cycle events.", "current_status": "approved", "epistemics": {"contract_basis": "tradition", "contract_satisfied": true, "contract_status": "SUPPORTED", "epistemic_type": "TRADITIONAL_NARRATIVE", "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "traditional_narrative", "lens": {"field_id": "480af3d9-6cea-428a-8b51-7a4c721f8545", "field_label": "Role in Ramayana / Mahabharata narratives when applicable", "parameter_id": "700ce11a-bd45-4116-99a4-a246dc97c505", "parameter_name": "Relational / Social Role"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Sarga 74 records Vishvamitra taking leave after the Mithila events.", "link_id": "01d00167-e36e-4db0-ae9c-b007d7ede9d9", "page_or_section": "1.74.1", "passages": [{"chunk_id": "c14197c2-5339-4c55-aa09-7d6d165943ad", "confidence": 0.9225, "excerpt": "5b, 6a. raajaa  = king Janaka;   susamhR^iSTaH  = very highly  gladdened; hiraNyasya = of gold; suvarNasya = of silver; muktaanaam =  of pearls; vidrumasya ca = red corals, even; anuttamam = beau idéal;   kanyaadhanam = bridal riches; dadau = he gave.  King Janaka gave beau idéal bridal riches in gold, silver, pearls and corals even,  for he is very highly …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Introduction", "relationship": "supports", "section_title": "Introduction", "source_id": "582a2381-dc45-429d-a615-f021939714cb", "textual_layer": "Ramayana — Bala Kanda"}, {"chunk_id": "d2971222-8d87-4bae-a49a-935718f3f74a", "confidence": 0.9225, "excerpt": "Parashu Rama confronts the wedding party that is returning to Ayodhya from  Mithila. On his very entry, the atmosphere becomes pell-mell and a whirlwind ensues.  Expecting some problem from this Parashu Rama, the sages like Vashishta and others starts  to receive him in a peaceable manner. Not caring anyone around Parashu Rama starts a  dialogue with …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Introduction", "relationship": "supports", "section_title": "Introduction", "source_id": "582a2381-dc45-429d-a615-f021939714cb", "textual_layer": "Ramayana — Bala Kanda"}], "relationship": "supports", "source": {"author": "Valmiki", "authority_metadata": {}, "citation": "Valmiki Ramayana, Bala Kanda, Sarga 74 (https://www.valmikiramayan.net/utf8/baala/sarga74/balasans74.htm)", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Valmiki Ramayana, Bala Kanda, Sarga 74", "url": "https://www.valmikiramayan.net/utf8/baala/sarga74/balasans74.htm"}, "source_id": "582a2381-dc45-429d-a615-f021939714cb"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('2039c724-d79f-43e5-ae9d-553870bffa1e','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "2039c724-d79f-43e5-ae9d-553870bffa1e", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "Vishvamitra''s role in the Tataka episode includes giving Rama the command and justification to act, making him the authority who authorizes one of Rama''s first major confrontations outside Ayodhya.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Recorded source access issue"], "evidence_type": "traditional_narrative", "lens": {"field_id": "480af3d9-6cea-428a-8b51-7a4c721f8545", "field_label": "Role in Ramayana / Mahabharata narratives when applicable", "parameter_id": "700ce11a-bd45-4116-99a4-a246dc97c505", "parameter_name": "Relational / Social Role"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Sarga 26 centers Vishvamitra''s direction and Rama''s obedience to father/guru instruction.", "link_id": "2b2a6fd0-bc71-415c-aa59-05754ecea122", "page_or_section": "1.26", "passages": [{"chunk_id": "2c5b47db-6540-4f24-9cc3-6db9940c0037", "confidence": 0.958260869565217, "excerpt": "Rama encounters his first problem-female demoness Tataka, also called as Taadaka, and   eliminates her at the orders of sage Vishvamitra. This is a crucial test put to Rama by   Vishvamitra in ascertaining whether Rama is the follower of dharma through elder men''s   orders or not. Rama eradicates Tataka basing on his own se