insert into original_claims values ('415b54ab-a1cc-4d5e-9f61-2eb7e51dae1f','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "415b54ab-a1cc-4d5e-9f61-2eb7e51dae1f", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "Vishvamitra is the narrative bridge from Siddhashrama to Mithila because he introduces Janaka''s sacrifice and Shiva''s bow as the next destination.", "current_status": "approved", "epistemics": {"contract_basis": "tradition", "contract_satisfied": true, "contract_status": "SUPPORTED", "epistemic_type": "TRADITIONAL_NARRATIVE", "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["Current approval origin does not establish strict verification", "Recorded source access issue"], "evidence_type": "traditional_narrative", "lens": {"field_id": "480af3d9-6cea-428a-8b51-7a4c721f8545", "field_label": "Role in Ramayana / Mahabharata narratives when applicable", "parameter_id": "700ce11a-bd45-4116-99a4-a246dc97c505", "parameter_name": "Relational / Social Role"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Sarga 31 motivates the movement to Mithila.", "link_id": "cd058a62-ede7-496c-8c57-30054e4a4a1c", "page_or_section": "1.31", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur Valmiki Ramayanam Project", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same Bala Kanda chapter is linked below; compare editions before using a quotation.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayanam, Bala Kanda, Sarga 31", "url": "https://www.valmiki.iitk.ac.in/summary?field_kanda_tid=1&field_sarga_value=31"}, "source_id": "6c753ad7-bf16-4884-857f-27532c924fe6"}, {"evidence_excerpt": "Sarga 31 motivates the movement to Mithila.", "link_id": "2bd53cd2-cc7e-4032-b843-6d0cc5e7dc86", "page_or_section": "1.31", "passages": [{"chunk_id": "8fde6331-f36a-429f-ab3d-e3fa23ccabbb", "confidence": 0.893333333333333, "excerpt": "\"Once Devaraata, the grandparent of the present king Janaka of Mithila, conducted a Vedic-ritual and  he indeed prayed only for this supreme bow with a best grip-handle as the fruit of that ritual from  all of the gods and oh, tigerly man Rama, he got the same from them.  For this kuurma puraaNa, padma puraNna puts it as:  priitaH ca bhagavaan iisaH …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Book I : Bala Kanda - The Youthful MajestiesSarga 31 in prose", "relationship": "supports", "section_title": "Book I : Bala Kanda - The Youthful MajestiesSarga 31 in prose", "source_id": "db7b0f86-1988-42bd-9eef-b546d4787ad7", "textual_layer": "Ramayana — Bala Kanda"}, {"chunk_id": "ce795047-e5d4-44d0-a4e1-2596082e264d", "confidence": 0.926666666666667, "excerpt": "Sage Vishwamitra travels to Mithila kingdom to attend a ritual of King Janaka and  also to see the auspicious bow of Shiva that is being worshipped in the palace of  Janaka from ages. The other sages suggest to Rama, that he too may go over there  along with them to see that marvellous bow. They all proceed from Siddha Ashram  towards River SoNa, a …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Book I : Bala Kanda - The Youthful MajestiesSarga 31 in prose", "relationship": "supports", "section_title": "Book I : Bala Kanda - The Youthful MajestiesSarga 31 in prose", "source_id": "db7b0f86-1988-42bd-9eef-b546d4787ad7", "textual_layer": "Ramayana — Bala Kanda"}], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution); English rendering by Desiraju Hanumanta Rao", "authority_metadata": {"verified_http_status": 200}, "citation": "Valmiki Ramayana, Bala Kanda 1.31, chapter-level prose rendering.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": "Publicly accessible chapter page; preserve source attribution and link.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayana — Bala Kanda, Sarga 31 (prose)", "url": "https://www.valmikiramayan.net/utf8/baala/sarga31/bala_31_prose.htm"}, "source_id": "db7b0f86-1988-42bd-9eef-b546d4787ad7"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('4183a4b4-d4f8-48d4-9419-71050d8368e6','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "4183a4b4-d4f8-48d4-9419-71050d8368e6", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "During the Siddhashrama sacrifice Vishvamitra''s vow creates the narrative condition in which Rama and Lakshmana must independently defend the rite for six days and nights.", "current_status": "approved", "epistemics": {"contract_basis": "tradition", "contract_satisfied": true, "contract_status": "SUPPORTED", "epistemic_type": "TRADITIONAL_NARRATIVE", "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["Current approval origin does not establish strict verification", "Recorded source access issue"], "evidence_type": "traditional_narrative", "lens": {"field_id": "480af3d9-6cea-428a-8b51-7a4c721f8545", "field_label": "Role in Ramayana / Mahabharata narratives when applicable", "parameter_id": "700ce11a-bd45-4116-99a4-a246dc97c505", "parameter_name": "Relational / Social Role"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The sage remains in ritual silence while the princes perform protective duty.", "link_id": "d6de95fe-3555-4fae-8f28-e680d8254df4", "page_or_section": "1.30", "passages": [{"chunk_id": "a7ec8ae6-04f3-4603-acf2-bb83387319d9", "confidence": 0.876363636363636, "excerpt": "While the Vedic ritual is proceeding well towards its conclusion according to hymnal  rendering and rules of conducting the ritual, a strident and frightening blare is generated in the sky.  As to how massive clouds appear in torrential cloudburst, likewise two demons appeared enshrouding the  sky, and performing wizardry they about to swoop down towards …", "excerpt_truncated": true, "is_active"