insert into original_claims values ('a7dcdb04-4d15-494c-bb14-adfdb233a33c','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "a7dcdb04-4d15-494c-bb14-adfdb233a33c", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "The Ganga cycle makes Vishvamitra a major internal storyteller in Bala Kanda, supplying Rama with a long sacred-history narrative during travel.", "current_status": "approved", "epistemics": {"contract_basis": "tradition", "contract_satisfied": true, "contract_status": "SUPPORTED", "epistemic_type": "TRADITIONAL_NARRATIVE", "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["Current approval origin does not establish strict verification", "Recorded source access issue"], "evidence_type": "traditional_narrative", "lens": {"field_id": "480af3d9-6cea-428a-8b51-7a4c721f8545", "field_label": "Role in Ramayana / Mahabharata narratives when applicable", "parameter_id": "700ce11a-bd45-4116-99a4-a246dc97c505", "parameter_name": "Relational / Social Role"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Sarga 35 begins Vishvamitra''s extended narration connected with the Ganga.", "link_id": "48693f01-cd3c-49bf-ac59-c7272a9e6f10", "page_or_section": "1.35 onward", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur Valmiki Ramayanam Project", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same Bala Kanda chapter is linked below; compare editions before using a quotation.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayanam, Bala Kanda, Sarga 35", "url": "https://www.valmiki.iitk.ac.in/summary?field_kanda_tid=1&field_sarga_value=35"}, "source_id": "3f8184f5-2d01-45b4-a672-080c7ab608d2"}, {"evidence_excerpt": "Sarga 35 begins Vishvamitra''s extended narration connected with the Ganga.", "link_id": "4ed110a4-8c85-4dc4-be02-ed68174f0715", "page_or_section": "1.35 onward", "passages": [{"chunk_id": "c66709a7-d35e-4ec5-9dd5-3d0a4e99a306", "confidence": 0.82, "excerpt": "Motivated by Rama''s words the eminent-sage Vishvamitra commenced to narrate about the  emergence and that way even about the progression of River Ganga.  \"The lordly mountain Himavan who is the greatest treasure trove of minerals, Rama, also  treasures up a pair of daughters who by their comeliness are unequalled on earth. The slender-waisted  and …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Book I : Bala Kanda - The Youthful \nMajesties Sarga 35 in Prose", "relationship": "supports", "section_title": "Book I : Bala Kanda - The Youthful \nMajesties Sarga 35 in Prose", "source_id": "7ac166d3-a3f1-4e9c-a44a-32bf54c7db27", "textual_layer": "Ramayana — Bala Kanda"}, {"chunk_id": "e1e7a506-57fb-4b64-96bc-065eb978949e", "confidence": 0.85, "excerpt": "Sage Vishvamitra along with others reach the banks of River Ganga and they make their  sojourn on that riverbank. There when Rama inquisitively enquires about River Ganga Vishvamitra narrates  the legend of Ganga, as to how she is taken to heavens by gods from her father Himalayas.  On sojourning the remaining night on the bank of river Sona along with …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Book I : Bala Kanda - The Youthful \nMajesties Sarga 35 in Prose", "relationship": "supports", "section_title": "Book I : Bala Kanda - The Youthful \nMajesties Sarga 35 in Prose", "source_id": "7ac166d3-a3f1-4e9c-a44a-32bf54c7db27", "textual_layer": "Ramayana — Bala Kanda"}], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution); English rendering by Desiraju Hanumanta Rao", "authority_metadata": {"verified_http_status": 200}, "citation": "Valmiki Ramayana, Bala Kanda 1.35, chapter-level prose rendering.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": "Publicly accessible chapter page; preserve source attribution and link.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayana — Bala Kanda, Sarga 35 (prose)", "url": "https://www.valmikiramayan.net/utf8/baala/sarga35/bala_35_prose.htm"}, "source_id": "7ac166d3-a3f1-4e9c-a44a-32bf54c7db27"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('ad96df5e-bf7a-45a4-99d5-77586f00ab03','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "ad96df5e-bf7a-45a4-99d5-77586f00ab03", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "He serves as a sacred-geography narrator, explaining places and older stories encountered during the journey.", "current_status": "approved", "epistemics": {"contract_basis": "tradition", "contract_satisfied": true, "contract_status": "SUPPORTED", "epistemic_type": "TRADITIONAL_NARRATIVE", "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "traditional_narrative", "lens": {"field_id": "480af3d9-6cea-428a-8b51-7a4c721f8545", "field_label": "Role in Ramayana / Mahabharata narratives when applicable", "parameter_id": "700ce11a-bd45-4116-99a4-a246dc97c505", "parameter_name": "Relational / Social Role"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "At Siddhashrama he explains the earlier history of the site.", "link_id": "2efb7d15-c789-466c-9a06-6a238a5564ec", "page_or_section": "1.29", "passages": [{"chunk_id": "3d948c33-642e-46bf-ba1d-74c67d7a7263", "confidence": 0.825, "excerpt": "\"That dwarf ascetic boy Vaamana begged and received a space that can   be covered in three strides, but strode all the three worlds in those   three steps for the purpose of saving worlds, as he is interested in   the welfare of all the worlds. Vishnu gave the earth back to Indra restraining   Emperor Bali with his vitality. Thus that great resplendent …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Introduction", "relationship": "supports", "section_title": "Introduction", "source_id": "588fb085-d2af-42be-9eca-bf08c63060d6", "textual_layer": "Ramayana — Bala Kanda"}], "relationship": "supports", "source": {"author": "Valmiki", "authority_metadata": {}, "citation": "Valmiki Ramayana, Bala Kanda, Sarga 29 (https://www.valmikiramayan.net/utf8/baala/sarga29/balasans29.htm)", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Valmiki Ramayana, Bala Kanda, Sarga 29", "url": "https://www.valmikiramayan.net/utf8/baala/sarga29/balasans29.htm"}, "source_id": "588fb085-d2af-42be-9eca-bf08c63060d6"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('d966314a-3bbb-4e33-8806-d703f95acc35','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "d966314a-3bbb-4e33-8806-d703f95acc35", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "In the Bala Kanda, Vishvamitra is a major guide and teacher of Rama and Lakshmana; he brings them from Ayodhya and transmits Bala and Atibala.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "PARTIALLY_SUPPORTED", "epistemic_type": "TRADITIONAL_NARRATIVE", "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Current approval origin does not establish strict verification", "Recorded source access issue", "Claim-passage link points to a source absent from claim-source links"], "evidence_type": "traditional_narrative", "lens": {"field_id": "480af3d9-6cea-428a-8b51-7a4c721f8545", "field_label": "Role in Ramayana / Mahabharata narratives when applicable", "parameter_id": "700ce11a-bd45-4116-99a4-a246dc97c505", "parameter_name": "Relational / Social Role"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Vishvamitra leads and instructs Rama and Lakshmana.", "link_id": "1ae89c1b-9de2-44b8-bb8c-a252a872df43", "page_or_section": "Bala Kanda 1.22", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana, Bala Kanda 1.22. IIT Kanpur Valmiki Ramayanam.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same Bala Kanda chapter is linked below; compare editions before using a quotation.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayanam — Bala Kanda, Sarga 22", "url": "https://www.valmiki.iitk.ac.in/sloka?field_kanda_tid=1&field_sarga_value=22&language=dv"}, "source_id": "1b4c231b-8eda-4bda-b817-a5fc93481511"}], "unmatched_passage_links": [{"chunk_id": "0916dfc9-783d-412f-8147-df4c3d5c6695", "excerpt": "56 of cows (Proudfoot 1987), the kāmadhenu legend appears clearly impacted by the ahiṃsā doctrine—which Jha believes to have ‘made its first appearance in the Upaniṣadic thought and literature’ (Jha 2002, 140; see also Chapple 1996). If it is indeed vegetarian, the Brahman feast is perhaps meant to contrast with the violence of the Kṣatriya hunt, but in any …", "excerpt_truncated": true, "page_or_section": "p. 56 (PDF page 16)", "relationship": "context", "source": {"author": "Adheesh Sathaye", "publication_year": 2007, "publisher_or_institution": "Acta Orientalia Vilnensia / Vilnius University Press", "rights_or_access_note": "Official journal diamond open access, CC BY 4.0: https://www.journals.vu.lt/acta-orientalia-vilnensia/journalpolicy", "source_status": "approved", "source_type": "scholarly_article", "title": "How to become a Brahman: The construction of varṇa as social place in the Mahābhārata’s legends of Viśvāmitra", "url": "https://www.journals.vu.lt/acta-orientalia-vilnensia/article/download/3751/5207"}, "source_id": "06fec486-e5af-4c7e-95db-afbb2e237c75"}, {"chunk_id": "347af684-3faf-459c-902b-b4f21353fb0c", "excerpt": "Sage Vishvamitra is the Seer for Gayatri hymn. He is the same Sage to impart balaatibala  hymns to Rama and Lakshmana. For those readers that are interested to know or to practice,  the Upanishad of balaatibala is included hereunder. This hymn is yet another  aspect of Gayatri, and there is no hymn superior than Gayatri, na gaayatryaaH  paramam japam  …", "excerpt_truncated": true, "page_or_section": "bala-atibala-teachings", "relationship": "context", "source": {"author": "Valmiki", "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "title": "Valmiki Ramayana, Bala Kanda, Sarga 22", "url": "https://www.valmikiramayan.net/utf8/baala/sarga22/balasans22.htm"}, "source_id": "4772171e-b53b-4ae5-9ffa-e6edf7a8f9de"}]}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('eff3931e-3bfe-49bd-9c14-497b21a6a68f','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "eff3931e-3bfe-49bd-9c14-497b21a6a68f", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "The celestial-weapon sequence makes Vishvamitra the conduit through whom Rama gains a large repertoire of astras and the knowledge for controlling them.", "current_status": "approved", "epistemics": {"contract_basis": "tradition", "contract_satisfied": true, "contract_status": "SUPPORTED", "epistemic_type": "TRADITIONAL_NARRATIVE", "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["Current approval origin does not establish strict verification", "Recorded source access issue"], "evidence_type": "traditional_narrative", "lens": {"field_id": "480af3d9-6cea-428a-8b51-7a4c721f8545", "field_label": "Role in Ramayana / Mahabharata narratives when applicable", "parameter_id": "700ce11a-bd45-4116-99a4-a246dc97c505", "parameter_name": "Relational / Social Role"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Sarga 27 gives the weapons; Sarga 28 gives withdrawal methods.", "link_id": "effd4323-f6d7-4252-94c2-724a197a1e99", "page_or_section": "1.27-28", "passages": [{"chunk_id": "4cd2f9db-d7f3-4cbf-a7ba-5ba1b92b5363", "confidence": 0.821052631578947, "excerpt": "\"Oh, mighty armed son of the best king, I am giving a great missile named Vaidyadhara  by its name, and a gem of sword named Nandana. Thus, the missile which is very much liked by Gandharva-s,  namely Mohana, [The Stupefier,] the missile called Prasvapana [The Inducer of Sleep,] and the gentle  Prashamana, [The Pacifier of enemy''s anger.]  \"Oh, highly …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Book I : Bala Kanda - The Youthful MajestiesSarga 27 in Prose", "relationship": "supports", "section_title": "Book I : Bala Kanda - The Youthful MajestiesSarga 27 in Prose", "source_id": "810e23ca-7c61-499e-85f4-e37468b88b6f", "textual_layer": "Ramayana — Bala Kanda"}, {"chunk_id": "6fe6bb6e-47f1-458e-b2f9-8f7a60f0b08f", "confidence": 0.882105263157895, "excerpt": "Sage Vishvamitra satisfied with the behaviour of Rama in obliging the orders of elders  and performing the act that is assigned to him, gives many weapons to Rama, called shastra, astra-s.  The weaponry is categorised mainly into two types. One is shastra - a handheld weapon like  sword, lance or mace. The other is astra - a projectile missile invoked by …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Book I : Bala Kanda - The Youthful MajestiesSarga 27 in Prose", "relationship": "supports", "section_title": "Book I : Bala Kanda - The Youthful MajestiesSarga 27 in Prose", "source_id": "810e23ca-7c61-499e-85f4-e37468b88b6f", "textual_layer": "Ramayana — Bala Kanda"}], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution); English rendering by Desiraju Hanumanta Rao", "authority_metadata": {"verified_http_status": 200}, "citation": "Valmiki Ramayana, Bala Kanda 1.27, chapter-level prose rendering.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": "Publicly accessible chapter page; preserve source attribution and link.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayana — Bala Kanda, Sarga 27 (prose)", "url": "https://www.valmikiramayan.net/utf8/baala/sarga27/bala_27_prose.htm"}, "source_id": "810e23ca-7c61-499e-85f4-e37468b88b6f"}, {"evidence_excerpt": "Sarga 27 gives the weapons; Sarga 28 gives withdrawal methods.", "link