insert into original_claims values ('f2b5e152-f9c0-4ead-9d06-9b0410f10262','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "f2b5e152-f9c0-4ead-9d06-9b0410f10262", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "The Mahabharata also uses Vishvamitra as an exemplum in the Galava and famine narratives, so his epic reception extends far beyond the Ramayana''s Rama-mentor role.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source", "Recorded source access issue"], "evidence_type": "traditional_narrative", "lens": {"field_id": "480af3d9-6cea-428a-8b51-7a4c721f8545", "field_label": "Role in Ramayana / Mahabharata narratives when applicable", "parameter_id": "700ce11a-bd45-4116-99a4-a246dc97c505", "parameter_name": "Relational / Social Role"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Udyoga and Shanti Parvas independently deploy Vishvamitra in dharma narratives.", "link_id": "98a55db7-3353-4976-a68d-bdb6b6474cda", "page_or_section": "Mahabharata cross-parva reception", "passages": [], "relationship": "supports", "source": {"author": "Vyasa (traditional attribution); BORI Critical Edition", "authority_metadata": {}, "citation": "Mahabharata BORI, Udyoga Parva", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Bhandarkar Oriental Research Institute critical text / Vedapath presentation", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Mahabharata (BORI Critical Edition), Udyoga Parva", "url": "https://vedapath.app/en/mahabharata-bori/udyoga-parva"}, "source_id": "c3dbce9c-6c8c-4e2c-923b-c0394ecc916c"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('fc365f5c-ce67-432e-931e-2fb59278cb82','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "fc365f5c-ce67-432e-931e-2fb59278cb82", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "The Mahabharata gives Vishvamitra a separate itihasa role as biological father of Shakuntala and therefore an ancestor within the Bharata genealogy.", "current_status": "approved", "epistemics": {"contract_basis": "tradition", "contract_satisfied": true, "contract_status": "SUPPORTED", "epistemic_type": "TRADITIONAL_NARRATIVE", "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source", "Recorded source access issue"], "evidence_type": "traditional_narrative", "lens": {"field_id": "480af3d9-6cea-428a-8b51-7a4c721f8545", "field_label": "Role in Ramayana / Mahabharata narratives when applicable", "parameter_id": "700ce11a-bd45-4116-99a4-a246dc97c505", "parameter_name": "Relational / Social Role"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Adi Parva 1.90.30 places him in the genealogy leading to Bharata.", "link_id": "1a259f1c-1e8e-4e6b-bec4-1c0c72255a06", "page_or_section": "1.90.30", "passages": [{"chunk_id": "b240b588-247f-4b52-b144-d2bc945e7701", "confidence": 0.855294117647059, "excerpt": "रेतोधाः पुत्र उन्नयति नरदेव यमक्षयात् । त्वं चास्य धाता गर्भस्य सत्यमाह शकुन्तला  ‘O king, the son—born of a man’s seed—raises him beyond the condition of Yama (death). And you are indeed the begetter of this pregnancy; Śakuntalā speaks the truth.’  From that, he came to be known as ‘Bharata’.  भरतः खलु काशेयीमुपयेमे सार्वसेनीं सुनन्दां नाम । तस्यामस्य …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Shlokas", "relationship": "supports", "section_title": "Shlokas", "source_id": "976f33cf-1de6-4118-b64f-c07b7a358389", "textual_layer": "Mahabharata tradition"}, {"chunk_id": "c93b8ceb-826c-4dc9-b6cc-adb66be98503", "confidence": 0.855294117647059, "excerpt": "Ādi Parva, Adhyāya 90 — Pūror Vaṃśa, Kuru-Pravara, and the Janamejaya Line (Genealogical Recitation)  Upa-parva: Anuvaṃśa (Pūru–Kuru Vaṃśānukīrtana) — Dynastic Genealogy and Legitimacy Discourse  This chapter begins with Janamejaya asking for a fuller account of his ancestors, saying that a condensed telling does not satisfy his longing for the sacred …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Adhyaya 90", "relationship": "supports", "section_title": "Adhyaya 90", "source_id": "976f33cf-1de6-4118-b64f-c07b7a358389", "textual_layer": "Mahabharata tradition"}], "relationship": "supports", "source": {"author": "Vyasa (traditional attribution); BORI Critical Edition", "authority_metadata": {}, "citation": "Mahabharata BORI, Adi Parva, 90", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Bhandarkar Oriental Research Institute critical text / Vedapath presentation", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Mahabharata (BORI Critical Edition), Adi Parva, Adhyaya 90", "url": "https://vedapath.app/en/mahabharata-bori/adi-parva/90"}, "source_id": "976f33cf-1de6-4118-b64f-c07b7a358389"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('0597d5db-8bf6-4b3f-974a-b0e80e5fc97b','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "0597d5db-8bf6-4b3f-974a-b0e80e5fc97b", "claim_kind": "traditional_account", "claim_relations": [], "claim_text": "The Bala Kanda narrative depicts Vishvamitra''s tapas as prolonged, repeated, and progressively intensified rather than as a single period of austerity.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "traditional_narrative", "lens": {"field_id": "62bccf46-2599-432a-acef-c38265ecbb47", "field_label": "Nature and intensity of tapasya undertaken", "parameter_id": "1b7184a9-e92f-4f89-8300-af633b008d29", "parameter_name": "Tapas and Sadhana"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Sarga 65 describes another severe phase of tapas after earlier interruptions and setbacks.", "link_id": "751f52a8-f9e9-4938-ae00-5eda9dbd7090", "page_or_section": "1.65.1-3", "passages": [{"chunk_id": "ef5de7fd-af8f-4eaa-9685-ac9b0a43aa7d", "confidence": 0.55, "excerpt": "Vishvamitra becomes Brahma-sage after a prolonged ascesis that made all the worlds  to startle. All gods request Brahma to accord the supreme Brahma-sageship on Vishvamitra  as he is cleansed of all mortal impurities, and Brahma accords that highest order  on him. Thus Sage Shataananda concludes his narration about the legend of Vishvamitra.  अथ हैमवतीम् …", "excerpt_truncated": true, "is_active": true, "link_method": "citation_partial", "page_or_section": "Introduction", "relationship": "context", "section_title": "Introduction", "source_id": "b1ff445c-d9d0-4f8e-a28f-f3a8053787ad", "textual_layer": "Ramayana — Bala Kanda"}], "relationship": "supports", "source": {"author": "Valmiki", "authority_metadata": {}, "citation": "Valmiki Ramayana, Bala Kanda, Sarga 65 (https://www.valmikiramayan.net/utf8/baala/sarga65/balasans65.htm.orig)", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Valmiki Ramayana, Bala Kanda, Sarga 65", "url": "https://www.valmikiramayan.net/utf8/baala/sarga65/balasans65.htm.orig"}, "source_id": "b1ff445c-d9d0-4f8e-a28f-f3a8053787ad"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('28fae74f-9fed-454e-a367-094a03e0e39e','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "28fae74f-9fed-454e-a367-094a03e0e39e", "claim_kind": "traditional_account", "claim_relations": [], "claim_text": "The Menaka interruption in Bala Kanda 1.63 is narrated as lasting ten years in Vishvamitra''s hermitage before he recognizes the interruption and resumes his quest.", "current_status": "approved", "epistemics": {"contract_basis": "tradition", "contract_satisfied": true, "contract_status": "SUPPORTED", "epistemic_type": "TRADITIONAL_NARRATIVE", "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["Current approval origin does not establish strict verification", "Recorded source access issue"], "evidence_type": "traditional_narrative", "lens": {"field_id": "62bccf46-2599-432a-acef-c38265ecbb47", "field_label": "Nature and intensity of tapasya undertaken", "parameter_id": "1b7184a9-e92f-4f89-8300-af633b008d29", "parameter_name": "Tapas and Sadhana"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Verses 1.63.7-10 say Menaka remained there for ten years and Vishvamitra later experienced grief and remorse.", "link_id": "d9c29efd-1501-4337-b692-262b523b90b1", "page_or_section": "1.63.7-10", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana, Bala Kanda 1.63. IIT Kanpur Valmiki Ramayanam.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same Bala Kanda chapter is linked below; compare editions before using a quotation.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayanam — Bala Kanda, Sarga 63", "url": "https://www.valmiki.iitk.ac.in/sloka?field_kanda_tid=1&field_sarga_value=63&language=dv"}, "source_id": "2025af50-f65e-4a13-b670-adc6a2a0e3dc"}, {"evidence_excerpt": "Verses 1.63.7-10 say Menaka remained there for ten years and Vishvamitra later experienced grief and remorse.", "link_id": "3534cccd-ef68-4aa6-924c-fc0b77e3ed55", "page_or_section": "1.63.7-10", "passages": [{"chunk_id": "1c601c57-75d6-404c-868e-11361f2be7ee", "confidence": 0.853333333333333, "excerpt": "\" ''All this is the mischief of gods to defraud me of the great merit of my ascesis.  Ten years have rolled by as if they are just a day and a night. Furthermore, I who  am under the influence of lust and lure had to encounter this hindrance in my ascesis.''  Oh, Rama, that best saint suspired heavily when he became emotional with reparation.  But on seeing …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Book I : Bala Kanda - The Youthful Majesties\niSarga 63 n Prose", "relationship": "supports", "section_title": "Book I : Bala Kanda - The Youthful Majesties\niSarga 63 n Prose", "source_id": "d39ddd21-67b7-4c7c-bfae-ea1f99918420", "textual_layer": "Ramayana — Bala Kanda"}, {"chunk_id": "9c862712-4d53-404e-a5bb-1c24e1296451", "confidence": 0.884444444444444, "excerpt": "On Vishvamitra''s performing severe ascesis Brahma accords the sageship   of ''Great-sage'' to him, whereas Vishvamitra''s ambition is to acquire   the sageship of a ''Brahma-sage'' Absolute-sageship. In the meanwhile,   the celestial wench Menaka arrives at that place and Vishvamitra is   enticed by her beauty and spends some years with her. Later, on realising  …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Book I : Bala Kanda - The Youthful Majesties\niSarga 63 n Prose", "relationship": "supports", "section_title": "Book I : Bala Kanda - The Youthful Majesties\niSarga 63 n Prose", "source_id": "d39ddd21-67b7-4c7c-bfae-ea1f99918420", "textual_layer": "Ramayana — Bala Kanda"}], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution); English rendering by Desiraju Hanumanta Rao", "authority_metadata": {"verified_http_status": 200}, "citation": "Valmiki Ramayana, Bala Kanda 1.63, chapter-level prose rendering.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": "Publicly accessible chapter page; preserve source attribution and link.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayana — Bala Kanda, Sarga 63 (prose)", "url": "https://www.valmikiramayan.net/utf8/baala/sarga63/bala_63_prose.htm"}, "source_id": "d39ddd21-67b7-4c7c-bfae-ea1f99918420"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('29616716-52cd-4252-88d0-3fa57c4e1e05','{"approval_origin": "imported_existing", "certainty": "high", "claim_id": "29616716-52cd-4252-88d0-3fa57c4e1e05", "claim_kind": "traditional_account", "claim_relations": [], "claim_text": "The Bala Kanda repeatedly portrays Vishvamitra undertaking severe and prolonged tapas, including continued austerities at Pushkara.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "PARTIALLY_SUPPORTED", "epistemic_type": "TRADITIONAL_NARRATIVE", "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Current approval origin does not establish strict verification", "Recorded source access issue", "Claim-passage link points to a source absent from claim-source links"], "evidence_type": "traditional_narrative", "lens": {"field_id": "62bccf46-2599-432a-acef-c38265ecbb47", "field_label": "Nature and intensity of tapasya undertaken", "parameter_id": "1b7184a9-e92f-4f89-8300-af633b008d29", "parameter_name": "Tapas and Sadhana"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The text describes continued austerities at Pushkara.", "link_id": "19155e86-b671-4c33-ac05-ba74a176f299", "page_or_section": "Bala Kanda 1.62.28", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana, Bala Kanda 1.62. IIT Kanpur Valmiki Ramayanam.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same Bala Kanda chapter is linked below; compare editions before using a quotation.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayanam — Bala Kanda, Sarga 62", "url": "https://www.valmiki.iitk.ac.in/sloka?field_kanda_tid=1&field_sarga_value=62&language=ro"}, "source_id": "1bd6679d-930b-415a-9d32-d4db80d96693"}], "unmatched_passage_links": [{"chunk_id": "48ed5f42-6093-4bdd-9a40-0882f3231976", "excerpt": "55 water alone, or air, or eating only dried leaves; [it was filled] with others who ate only fruits and roots, those who had conquered their passions and subdued their senses, and with sages [ṛṣis] and divine ascetics, who were devoted to prayer and sacrifice. Thus did the mighty Viśvāmitra, greatest of warriors, behold Vasiṣṭha’s hermitage, resembling …", "excerpt_truncated": true, "page_or_section": "p. 55 (PDF page 15)", "relationship": "context", "source": {"author": "Adheesh Sathaye", "publication_year": 2007, "publisher_or_institution": "Acta Orientalia Vilnensia / Vilnius University Press", "rights_or_access_note": "Official journal diamond open access, CC BY 4.0: https://www.journals.vu.lt/acta-orientalia-vilnensia/journalpolicy", "source_status": "approved", "source_type": "scholarly_article", "title": "How to become a Brahman: The construction of varṇa as social place in the Mahābhārata’s legends of Viśvāmitra", "url": "https://www.journals.vu.lt/acta-orientalia-vilnensia/article/download/3751/5207"}, "source_id": "06fec486-e5af-4c7e-95db-afbb2e237c75"}, {"chunk_id": "90006a17-a967-4741-b750-d7d0a4a667c8", "excerpt": "When Shunashepa is tied to ritual post he immensely pleased two gods, namely Indra  and Upendra as well, with those two hymns he got from Vishvamitra. [1-62-25]  ततः प्रीतः सहस्राक्षो रहस्यस्तुतितोषितः | दीर्घमायुस्तदा प्रादाच्छुनःशेपाय राघव || १-६२-२६  26. raaghava = oh Raghava; tataH = then; rahasyastutitoSitaH  = who is satisfied by esoteric laudation; …", "excerpt_truncated": true, "page_or_section": "Introduction", "relationship": "context", "source": {"author": "Valmiki", "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "title": "Valmiki Ramayana, Bala Kanda, Sarga 62", "url": "https://www.valmikiramayan.net/utf8/baala/sarga62/balasans62.htm"}, "source_id": "4bd01c3e-d436-4013-a8a9-49d839abe475"}]}'::jsonb,'approved','imported_existing');
