insert into original_claims values ('51c9b51f-76a0-44c1-910a-c07dfaa17c65','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "51c9b51f-76a0-44c1-910a-c07dfaa17c65", "claim_kind": "traditional_account", "claim_relations": [], "claim_text": "In the Rambha episode Vishvamitra explicitly identifies conquering both desire and anger as his ascetic objective, showing that internal discipline is part of the intensity of tapas in the story.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "PARTIALLY_SUPPORTED", "epistemic_type": "TRADITIONAL_NARRATIVE", "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Current approval origin does not establish strict verification", "Recorded source access issue", "Claim-passage link points to a source absent from claim-source links"], "evidence_type": "traditional_narrative", "lens": {"field_id": "62bccf46-2599-432a-acef-c38265ecbb47", "field_label": "Nature and intensity of tapasya undertaken", "parameter_id": "1b7184a9-e92f-4f89-8300-af633b008d29", "parameter_name": "Tapas and Sadhana"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Verse 1.64.12 describes him as striving to conquer kama and krodha.", "link_id": "9e0bd341-1732-4606-8188-46b69e096c29", "page_or_section": "1.64.12", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana, Bala Kanda 1.64. IIT Kanpur Valmiki Ramayanam.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same Bala Kanda chapter is linked below; compare editions before using a quotation.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayanam — Bala Kanda, Sarga 64", "url": "https://www.valmiki.iitk.ac.in/sloka?field_kanda_tid=1&field_sarga_value=64&language=dv"}, "source_id": "84367293-66be-4b9a-8bd2-ac2ca21fa68d"}], "unmatched_passage_links": [{"chunk_id": "2a5bae86-6077-4fd8-8d21-59b2a47b760a", "excerpt": "Vishvamitra curses Rambha, the celestial wench, knowing that she arrived at the behest of Indra to cause  hindrance to his ascesis. But later feels ashamed to loose his tongue and then he is determined to undertake  another round of ascesis to conquer is own senses.  सुरकार्यमिदं रंभे कर्तव्यं सुमहत्त्वया |लोभनं कौशिकस्येह काममोहसमन्वितम् || १-६४-१  1. …", "excerpt_truncated": true, "page_or_section": "Introduction", "relationship": "context", "source": {"author": "Valmiki", "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "title": "Valmiki Ramayana, Bala Kanda, Sarga 64", "url": "https://www.valmikiramayan.net/utf8/baala/sarga64/balasans64.htm"}, "source_id": "8d1e7888-6577-4564-b935-96ed0ae1b902"}]}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('54f22437-c791-4cbb-ba1b-d31af2814b53','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "54f22437-c791-4cbb-ba1b-d31af2814b53", "claim_kind": "traditional_account", "claim_relations": [], "claim_text": "The final Bala Kanda austerity stage includes suspended breathing for another thousand-year period in the narrative, an extreme ascetic motif that should be recorded as epic description rather than biological history.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Recorded source access issue", "Claim-passage link points to a source absent from claim-source links"], "evidence_type": "traditional_narrative", "lens": {"field_id": "62bccf46-2599-432a-acef-c38265ecbb47", "field_label": "Nature and intensity of tapasya undertaken", "parameter_id": "1b7184a9-e92f-4f89-8300-af633b008d29", "parameter_name": "Tapas and Sadhana"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The summary explicitly narrates breath suspension for a further thousand years.", "link_id": "2f50d7ab-845c-4602-bba2-c5daa400b53a", "page_or_section": "1.65", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur Valmiki Ramayanam Project", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same Bala Kanda chapter is linked below; compare editions before using a quotation.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayanam, Bala Kanda, Sarga 65", "url": "https://www.valmiki.iitk.ac.in/summary?field_kanda_tid=1&field_sarga_value=65"}, "source_id": "35d30c22-48b6-4242-ad17-697405136d76"}], "unmatched_passage_links": [{"chunk_id": "d5e6cd91-c377-43d8-a3aa-a6233c8d0a82", "excerpt": "This meal is prepared by Vishvamitra alone after a thousand years and such self-cooking  of food by the ascetics is called, vaishva devam, since it is a sacred  preparation anena vaishvadeva ante samaagato atithiH svayam upoShyaa api sviiya anna pradaanena  sambhojya iti suucitam - dk  तस्मैः दत्त्वा तदा सिद्धम् सर्वम् विप्राय निश्चितः | निःषेषिते अन्ने …", "excerpt_truncated": true, "page_or_section": "Introduction", "relationship": "context", "source": {"author": "Valmiki", "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "title": "Valmiki Ramayana, Bala Kanda, Sarga 65", "url": "https://www.valmikiramayan.net/utf8/baala/sarga65/balasans65.htm.orig"}, "source_id": "b1ff445c-d9d0-4f8e-a28f-f3a8053787ad"}]}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('7562e441-ee71-4c12-a9a4-8769da12c232','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "7562e441-ee71-4c12-a9a4-8769da12c232", "claim_kind": "traditional_account", "claim_relations": [], "claim_text": "Bala Kanda 1.63 explicitly marks one austerity cycle as lasting a thousand years before the gods approach Vishvamitra, showing that the epic uses enormous time spans to signal ascetic intensity.", "current_status": "approved", "epistemics": {"contract_basis": "tradition", "contract_satisfied": true, "contract_status": "SUPPORTED", "epistemic_type": "TRADITIONAL_NARRATIVE", "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["Current approval origin does not establish strict verification", "Recorded source access issue"], "evidence_type": "traditional_narrative", "lens": {"field_id": "62bccf46-2599-432a-acef-c38265ecbb47", "field_label": "Nature and intensity of tapasya undertaken", "parameter_id": "1b7184a9-e92f-4f89-8300-af633b008d29", "parameter_name": "Tapas and Sadhana"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Verse 1.63.1 says a thousand-year period of penance had been completed.", "link_id": "1a837160-2a8b-4b0d-96f0-f32b0bec24d8", "page_or_section": "1.63.1", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana, Bala Kanda 1.63. IIT Kanpur Valmiki Ramayanam.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same Bala Kanda chapter is linked below; compare editions before using a quotation.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayanam — Bala Kanda, Sarga 63", "url": "https://www.valmiki.iitk.ac.in/sloka?field_kanda_tid=1&field_sarga_value=63&language=dv"}, "source_id": "2025af50-f65e-4a13-b670-adc6a2a0e3dc"}, {"evidence_excerpt": "Verse 1.63.1 says a thousand-year period of penance had been completed.", "link_id": "ca13bbfc-ad75-4e4c-a35c-d6a9d071f971", "page_or_section": "1.63.1", "passages": [{"chunk_id": "1c601c57-75d6-404c-868e-11361f2be7ee", "confidence": 0.897037037037037, "excerpt": "\" ''All this is the mischief of gods to defraud me of the great merit of my ascesis.  Ten years have rolled by as if they are just a day and a night. Furthermore, I who  am under the influence of lust and lure had to encounter this hindrance in my ascesis.''  Oh, Rama, that best saint suspired heavily when he became emotional with reparation.  But on seeing …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Book I : Bala Kanda - The Youthful Majesties\niSarga 63 n Prose", "relationship": "supports", "section_title": "Book I : Bala Kanda - The Youthful Majesties\niSarga 63 n Prose", "source_id": "d39ddd21-67b7-4c7c-bfae-ea1f99918420", "textual_layer": "Ramayana — Bala Kanda"}, {"chunk_id": "9c862712-4d53-404e-a5bb-1c24e1296451", "confidence": 0.939259259259259, "excerpt": "On Vishvamitra''s performing severe ascesis Brahma accords the sageship   of ''Great-sage'' to him, whereas Vishvamitra''s ambition is to acquire   the sageship of a ''Brahma-sage'' Absolute-sageship. In the meanwhile,   the celestial wench Menaka arrives at that place and Vishvamitra is   enticed by her beauty and spends some years with her. Later, on realising  …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Book I : Bala Kanda - The Youthful Majesties\niSarga 63 n Prose", "relationship": "supports", "section_title": "Book I : Bala Kanda - The Youthful Majesties\niSarga 63 n Prose", "source_id": "d39ddd21-67b7-4c7c-bfae-ea1f99918420", "textual_layer": "Ramayana — Bala Kanda"}], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution); English rendering by Desiraju Hanumanta Rao", "authority_metadata": {"verified_http_status": 200}, "citation": "Valmiki Ramayana, Bala Kanda 1.63, chapter-level prose rendering.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": "Publicly accessible chapter page; preserve source attribution and link.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayana — Bala Kanda, Sarga 63 (prose)", "url": "https://www.valmikiramayan.net/utf8/baala/sarga63/bala_63_prose.htm"}, "source_id": "d39ddd21-67b7-4c7c-bfae-ea1f99918420"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('9473eb9c-69d6-4b37-ae0d-d7ec3476ed49','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "9473eb9c-69d6-4b37-ae0d-d7ec3476ed49", "claim_kind": "traditional_account", "claim_relations": [], "claim_text": "His tapas is repeatedly restarted after setbacks involving power, desire, or anger, making persistence a central feature of the epic portrayal.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "traditional_narrative", "lens": {"field_id": "62bccf46-2599-432a-acef-c38265ecbb47", "field_label": "Nature and intensity of tapasya undertaken", "parameter_id": "1b7184a9-e92f-4f89-8300-af633b008d29", "parameter_name": "Tapas and Sadhana"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "After the Rambha episode, Vishvamitra resolves to undertake further tapas and conquer anger/senses.", "link_id": "c83e7983-ec6b-4657-9b9d-5a76bb679401", "page_or_section": "1.64", "passages": [{"chunk_id": "2a5bae86-6077-4fd8-8d21-59b2a47b760a", "confidence": 0.940869565217391, "excerpt": "Vishvamitra curses Rambha, the celestial wench, knowing that she arrived at the behest of Indra to cause  hindrance to his ascesis. But later feels ashamed to loose his tongue and then he is determined to undertake  another round of ascesis to conquer is own senses.  सुरकार्यमिदं रंभे कर्तव्यं सुमहत्त्वया |लोभनं कौशिकस्येह काममोहसमन्वितम् || १-६४-१  1. …", "e