insert into original_claims values ('fd077ec7-e2c8-4b05-829f-521fb9f895ce','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "fd077ec7-e2c8-4b05-829f-521fb9f895ce", "claim_kind": "traditional_account", "claim_relations": [], "claim_text": "Near the end of the final austerity cycle, Vishvamitra gives away all the cooked food he was about to eat to Indra disguised as a Brahmin and begins another period of penance without breaking silence.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "PARTIALLY_SUPPORTED", "epistemic_type": "TRADITIONAL_NARRATIVE", "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Current approval origin does not establish strict verification", "Recorded source access issue", "Claim-passage link points to a source absent from claim-source links"], "evidence_type": "traditional_narrative", "lens": {"field_id": "62bccf46-2599-432a-acef-c38265ecbb47", "field_label": "Nature and intensity of tapasya undertaken", "parameter_id": "1b7184a9-e92f-4f89-8300-af633b008d29", "parameter_name": "Tapas and Sadhana"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The episode occurs after completion of the long vow, immediately before another ascetic phase.", "link_id": "3a9a8cd6-ec88-46f2-89b7-e7a5dc42a488", "page_or_section": "1.65", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur Valmiki Ramayanam Project", "rights_or_access_note": "The original IITK link has a TLS certi