insert into original_claims values ('298f6156-0701-4c1d-bd2a-bd17ad8e20f4','{"approval_origin": "imported_existing", "certainty": "high", "claim_id": "298f6156-0701-4c1d-bd2a-bd17ad8e20f4", "claim_kind": "traditional_account", "claim_relations": [], "claim_text": "The Ramayana attributes extraordinary powers to Vishvamitra, including supernatural consequences in episodes such as Trishanku and Rambha. These should be stored as traditional/scriptural narratives, not independently verified empirical events.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "CONTESTED", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Recorded source access issue", "Claim-passage link points to a source absent from claim-source links"], "evidence_type": "traditional_narrative", "lens": {"field_id": "6bbd8d21-db3a-450c-85f8-2932df3ef2ba", "field_label": "Siddhis or powers attributed, including literal vs. symbolic framing", "parameter_id": "1b7184a9-e92f-4f89-8300-af633b008d29", "parameter_name": "Tapas and Sadhana"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The text narrates an extraordinary curse; this is evidence of the tradition, not empirical verification.", "link_id": "34739c6b-d8c7-466a-b446-24d29cadddc3", "page_or_section": "Bala Kanda 1.64", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana, Bala Kanda 1.64. IIT Kanpur Valmiki Ramayanam.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same Bala Kanda chapter is linked below; compare editions before using a quotation.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayanam — Bala Kanda, Sarga 64", "url": "https://www.valmiki.iitk.ac.in/sloka?field_kanda_tid=1&field_sarga_value=64&language=dv"}, "source_id": "84367293-66be-4b9a-8bd2-ac2ca21fa68d"}], "unmatched_passage_links": [{"chunk_id": "515003fb-3676-4dbd-8abb-a58e725319ce", "excerpt": "Whereof you tried to entice me who am wishing to win over the wanton and wroth, you unlucky female  Rambha, thereof you will become a rocklike statued wastrel. [1-64-12]  ब्राह्मणः सुमहातेजास्तपोबलसमन्वितः |उद्धरिष्यति रंभे त्वां मत्क्रोधकलुषीकृताम् || १-६४-१३  13. rambhe = oh Rambha; sumahaatejaaH = very high resplendent one;  tapobalasamanvitaH = having …", "excerpt_truncated": true, "page_or_section": "Introduction", "relationship": "context", "source": {"author": "Valmiki", "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "title": "Valmiki Ramayana, Bala Kanda, Sarga 64", "url": "https://www.valmikiramayan.net/utf8/baala/sarga64/balasans64.htm"}, "source_id": "8d1e7888-6577-4564-b935-96ed0ae1b902"}]}'::jsonb,'approved','imported_existing');
insert into original_claims values ('3335f31b-5ace-4f00-a6f5-a2e861c903cf','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "3335f31b-5ace-4f00-a6f5-a2e861c903cf", "claim_kind": "traditional_account", "claim_relations": [], "claim_text": "The Trishanku cycle escalates Vishvamitra''s narrated power to the threat of creating an alternate Indra or alternate cosmic order before a compromise with the gods is reached.", "current_status": "approved", "epistemics": {"contract_basis": "tradition", "contract_satisfied": true, "contract_status": "SUPPORTED", "epistemic_type": "TRADITIONAL_NARRATIVE", "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["Current approval origin does not establish strict verification", "Recorded source access issue", "Claim-passage link points to a source absent from claim-source links"], "evidence_type": "traditional_narrative", "lens": {"field_id": "6bbd8d21-db3a-450c-85f8-2932df3ef2ba", "field_label": "Siddhis or powers attributed, including literal vs. symbolic framing", "parameter_id": "1b7184a9-e92f-4f89-8300-af633b008d29", "parameter_name": "Tapas and Sadhana"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Sarga 60 narrates the cosmological escalation and negotiation around Trishanku.", "link_id": "a0a434f5-7854-45e2-bea0-33f3f8cb782c", "page_or_section": "1.60", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur Valmiki Ramayanam Project", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same Bala Kanda chapter is linked below; compare editions before using a quotation.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayanam, Bala Kanda, Sarga 60", "url": "https://www.valmiki.iitk.ac.in/sloka?field_kanda_tid=1&field_sarga_value=60&language=dv"}, "source_id": "ea18bd33-64b2-4955-aa31-e76c3a647290"}], "unmatched_passage_links": [{"chunk_id": "33a57f01-6ce1-4db2-9ee5-8d3a9443e449", "excerpt": "Vishvamitra effectuates Trishanku''s travel to heaven, but Indra throws him down  as Trishanku has not acquired any merit to reach heaven. Vishvamitra enraged at  this starts to replicate universe with constellation of stars and galaxies, and  he proceeds to clone even gods. On seeing this chaotic situation, Indra with gods  yield to the pertinence of …", "excerpt_truncated": true, "page_or_section": "Book I : Bala Kanda - The Youthful Majesties\n Sarga 60 in Prose", "relationship": "supports", "source": {"author": "Valmiki", "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "title": "Valmiki Ramayana, Bala Kanda, Sarga 60", "url": "https://www.valmikiramayan.net/utf8/baala/sarga60/bala_60_prose.htm"}, "source_id": "2ac81052-5bd0-4907-9e76-0deeaf0768d2"}, {"chunk_id": "e99d9182-5399-46ab-9d2e-f0eb1b2babb7", "excerpt": "Trishanku is the son of one Suuryaaruna and his original name is Satyavrat and this name Trishanku is  his pseudonym. He got this because three sins are attached to him tri shanka-s  as said in another work Harivamsha. There it is said: pituH shaapa aadi doShena | guru dogdhre vadhena  ca | a-prokShito prayogaat ca | trividhaa tat vyatikramaH | evam triiNi …", "excerpt_truncated": true, "page_or_section": "Book I : Bala Kanda - The Youthful Majesties\n Sarga 60 in Prose", "relationship": "context", "source": {"author": "Valmiki", "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "title": "Valmiki Ramayana, Bala Kanda, Sarga 60", "url": "https://www.valmikiramayan.net/utf8/baala/sarga60/bala_60_prose.htm"}, "source_id": "2ac81052-5bd0-4907-9e76-0deeaf0768d2"}]}'::jsonb,'approved','system_test_bulk');
