insert into original_claims values ('79dc18aa-e604-40bf-a754-553f10851aa9','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "79dc18aa-e604-40bf-a754-553f10851aa9", "claim_kind": "traditional_account", "claim_relations": [], "claim_text": "Bala Kanda attributes extraordinary effects to Bala and Atibala—protection from fatigue, hunger, thirst, and attack while asleep—within the story-world.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Has parent claim ID 917c9de6-090a-41fb-a395-d4d7e2334eae", "Retention/access rights note missing for an associated source"], "evidence_type": "traditional_narrative", "lens": {"field_id": "6bbd8d21-db3a-450c-85f8-2932df3ef2ba", "field_label": "Siddhis or powers attributed, including literal vs. symbolic framing", "parameter_id": "1b7184a9-e92f-4f89-8300-af633b008d29", "parameter_name": "Tapas and Sadhana"}, "parent_claim_id": "917c9de6-090a-41fb-a395-d4d7e2334eae", "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "गृहाण वत्स सलिलं मा भूत् कालस्य पर्ययः || १-२२-११  मंत्रग्रामं गृहाण त्वं बलामतिबलां तथा |  11b, 12a. vatsa salilam gR^ihaaNa = my boy, you take water; tvam   tathaa = you, like that; mantragraamam = group of hymns; balaam   atibalaam = bala, atibala hymns; gR^ihaaNa = receive; kaalasya   paryayaH maa bhuut = not let there be time''s lapse.  \" \"Take water, …", "link_id": "ce51ff05-c5ea-480e-a123-7d5b615c23d6", "page_or_section": "1.22", "passages": [{"chunk_id": "271446df-1b16-4af1-b22d-f06365591e27", "confidence": 0.95