insert into original_claims values ('8391e3e7-7edb-4d22-84c0-205fe61095d6','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "8391e3e7-7edb-4d22-84c0-205fe61095d6", "claim_kind": "traditional_account", "claim_relations": [], "claim_text": "Mahabharata Udyoga Parva''s test by Dharma disguised as Vasistha belongs to another supernatural narrative layer and should be identified as a Mahabharata tradition, not merged into the Ramayana biography.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source", "Recorded source access issue"], "evidence_type": "traditional_narrative", "lens": {"field_id": "6bbd8d21-db3a-450c-85f8-2932df3ef2ba", "field_label": "Siddhis or powers attributed, including literal vs. symbolic framing", "parameter_id": "1b7184a9-e92f-4f89-8300-af633b008d29", "parameter_name": "Tapas and Sadhana"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Dharma assumes Vasistha''s form to test Vishvamitra''s hospitality and tapas.", "link_id": "303d1433-ec15-4497-b7de-111b95912f66", "page_or_section": "5.104", "passages": [], "relationship": "supports", "source": {"author": "Vyasa (traditional attribution); BORI Critical Edition", "authority_metadata": {}, "citation": "Mahabharata BORI, Udyoga Parva, 104", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Bhandarkar Oriental Research Institute critical text / Vedapath presentation", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Mahabharata (BORI Critical Edition), Udyoga Parva, Adhyaya 104", "url": "https://vedapath.app/en/mahabharata-bori/udyoga-parva/104"}, "source_id": "855f8c75-16cc-4e96-9ba3-d79579231842"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('917c9de6-090a-41fb-a395-d4d7e2334eae','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "917c9de6-090a-41fb-a395-d4d7e2334eae", "claim_kind": "traditional_account", "claim_relations": [], "claim_text": "Bala Kanda attributes extraordinary effects to Bala and Atibala—protection from fatigue, hunger, thirst, and attack while asleep—within the story-world; these should not be converted into biomedical claims.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Recorded source access issue", "Claim-passage link points to a source absent from claim-source links"], "evidence_type": "traditional_narrative", "lens": {"field_id": "6bbd8d21-db3a-450c-85f8-2932df3ef2ba", "field_label": "Siddhis or powers attributed, including literal vs. symbolic framing", "parameter_id": "1b7184a9-e92f-4f89-8300-af633b008d29", "parameter_name": "Tapas and Sadhana"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Vishvamitra''s teaching speech lists exceptional benefits of Bala and Atibala.", "link_id": "2f6325f9-2216-46cb-aec8-17a36f52089b", "page_or_section": "1.22", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur Valmiki Ramayanam Project", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same Bala Kanda chapter is linked below; compare editions before using a quotation.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayanam, Bala Kanda, Sarga 22", "url": "https://www.valmiki.iitk.ac.in/summary?field_kanda_tid=1&field_sarga_value=22"}, "source_id": "9898fcd7-2c32-429e-aba6-4e662d2214cd"}], "unmatched_passage_links": [{"chunk_id": "271446df-1b16-4af1-b22d-f06365591e27", "excerpt": "गृहाण वत्स सलिलं मा भूत् कालस्य पर्ययः || १-२२-११  मंत्रग्रामं गृहाण त्वं बलामतिबलां तथा |  11b, 12a. vatsa salilam gR^ihaaNa = my boy, you take water; tvam   tathaa = you, like that; mantragraamam = group of hymns; balaam   atibalaam = bala, atibala hymns; gR^ihaaNa = receive; kaalasya   paryayaH maa bhuut = not let there be time''s lapse.  \" \"Take water, …", "excerpt_truncated": true, "page_or_section": "Introduction", "relationship": "context", "source": {"author": "Valmiki", "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "title": "Valmiki Ramayana, Bala Kanda, Sarga 22", "url": "https://www.valmikiramayan.net/utf8/baala/sarga22/balasans22.htm"}, "source_id": "4772171e-b53b-4ae5-9ffa-e6edf7a8f9de"}]}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('960e78c9-9fb2-463b-99ab-6bb3988a0ddf','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "960e78c9-9fb2-463b-99ab-6bb3988a0ddf", "claim_kind": "traditional_account", "claim_relations": [], "claim_text": "The final tapas narrative describes smoke issuing from Vishvamitra''s head and distress spreading through the worlds; this is an epic supernatural image of ascetic potency, not an empirical physiological observation.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "PARTIALLY_SUPPORTED", "epistemic_type": "TRADITIONAL_NARRATIVE", "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Current approval origin does not establish strict verification", "Recorded source access issue", "Claim-passage link points to a source absent from claim-source links"], "evidence_type": "traditional_narrative", "lens": {"field_id": "6bbd8d21-db3a-450c-85f8-2932df3ef2ba", "field_label": "Siddhis or powers attributed, including literal vs. symbolic framing", "parameter_id": "1b7184a9-e92f-4f89-8300-af633b008d29", "parameter_name": "Tapas and Sadhana"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The summary says smoke emanates from his head and the worlds feel scorched.", "link_id": "091f2880-ae2c-458e-aa59-8c6b4db57289", "page_or_section": "1.65", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur Valmiki Ramayanam Project", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same Bala Kanda chapter is linked below; compare editions before using a quotation.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayanam, Bala Kanda, Sarga 65", "url": "https://www.valmiki.iitk.ac.in/summary?field_kanda_tid=1&field_sarga_value=65"}, "source_id": "35d30c22-48b6-4242-ad17-697405136d76"}], "unmatched_passage_links": [{"chunk_id": "d3cba065-7fbe-446a-93fd-ddca36cd608b", "excerpt": "\"Then the gods, sages, gandharva-s, serpents, reptiles, demons are puzzled at the  ascesis of Vishvamitra, and as their own resplendence is dulled by the ascesis of  Vishvamitra, thereby they are marred by this blemish of lowered resplendence, then  all of them addressed the Grandparent, Brahma. [1-65-9b, 10]  बहुभिः कारणैः देव विश्वामित्रो महामुनिः | …", "excerpt_truncated": true, "page_or_section": "Introduction", "relationship": "context", "source": {"author": "Valmiki", "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "title": "Valmiki Ramayana, Bala Kanda, Sarga 65", "url": "https://www.valmikiramayan.net/utf8/baala/sarga65/balasans65.htm.orig"}, "source_id": "b1ff445c-d9d0-4f8e-a28f-f3a8053787ad"}, {"chunk_id": "d5e6cd91-c377-43d8-a3aa-a6233c8d0a82", "excerpt": "This meal is prepared by Vishvamitra alone after a thousand years and such self-cooking  of food by the ascetics is called, vaishva devam, since it is a sacred  preparation anena vaishvadeva ante samaagato atithiH svayam upoShyaa api sviiya anna pradaanena  sambhojya iti suucitam - dk  तस्मैः दत्त्वा तदा सिद्धम् सर्वम् विप्राय निश्चितः | निःषेषिते अन्ने …", "excerpt_truncated": true, "page_or_section": "Introduction", "relationship": "context", "source": {"author": "Valmiki", "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "title": "Valmiki Ramayana, Bala Kanda, Sarga 65", "url": "https://www.valmikiramayan.net/utf8/baala/sarga65/balasans65.htm.orig"}, "source_id": "b1ff445c-d9d0-4f8e-a28f-f3a8053787ad"}]}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('9c7297ce-96f5-4d38-955f-36bfa96d2e94','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "9c7297ce-96f5-4d38-955f-36bfa96d2e94", "claim_kind": "traditional_account", "claim_relations": [], "claim_text": "When the astras are transmitted in Bala Kanda 1.27, they appear in personified form and declare themselves available to Rama; this is supernatural narrative imagery tied to mantra transmission.", "current_status": "approved", "epistemics": {"contract_basis": "tradition", "contract_satisfied": true, "contract_status": "SUPPORTED", "epistemic_type": "TRADITIONAL_NARRATIVE", "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["Current approval origin does not establish strict verification", "Recorded source access issue"], "evidence_type": "traditional_narrative", "lens": {"field_id": "6bbd8d21-db3a-450c-85f8-2932df3ef2ba", "field_label": "Siddhis or powers attributed, including literal vs. symbolic framing", "parameter_id": "1b7184a9-e92f-4f89-8300-af633b008d29", "parameter_name": "Tapas and Sadhana"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Verses 1.27.23-24 personify the weapons as appearing and speaking.", "link_id": "97c7a913-ce09-470e-a27f-85161b89377a", "page_or_section": "1.27.23-24", "passages": [{"chunk_id": "6fe6bb6e-47f1-458e-b2f9-8f7a60f0b08f", "confidence": 0.82, "excerpt": "Sage Vishvamitra satisfied with the behaviour of Rama in obliging the orders of elders  and performing the act that is assigned to him, gives many weapons to Rama, called shastra, astra-s.  The weaponry is categorised mainly into two types. One is shastra - a handheld weapon like  sword, lance or mace. The other is astra - a projectile missile invoked by …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Book I : Bala Kanda - The Youthful MajestiesSarga 27 in Prose", "relationship": "supports", "section_title": "Book I : Bala Kanda - The Youthful MajestiesSarga 27 in Prose", "source_id": "810e23ca-7c61-499e-85f4-e37468b88b6f", "textual_layer": "Ramayana — Bala Kanda"}], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution); English rendering by Desiraju Hanumanta Rao", "authority_metadata": {"verified_http_status": 200}, "citation": "Valmiki Ramayana, Bala Kanda 1.27, chapter-level prose rendering.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": "Publicly accessible chapter page; preserve source attribution and link.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayana — Bala Kanda, Sarga 27 (prose)", "url": "https://www.valmikiramayan.net/utf8/baala/sarga27/bala_27_prose.htm"}, "source_id": "810e23ca-7c61-499e-85f4-e37468b88b6f"}, {"evidence_excerpt": "Verses 1.27.23-24 personify the weapons as appearing and speaking.", "link_id": "10c0afec-5e17-4a54-b361-c948dd57a01c", "page_or_section": "1.27.23-24", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur Valmiki Ramayanam Project", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same Bala Kanda chapter is linked below; compare editions before using a quotation.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayanam, Bala Kanda, Sarga 27", "url": "https://www.valmiki.iitk.ac.in/sloka?field_kanda_tid=1&field_sarga_value=27&language=d