insert into original_claims values ('bb309837-64ce-4503-aaee-5bf344de434c','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "bb309837-64ce-4503-aaee-5bf344de434c", "claim_kind": "traditional_account", "claim_relations": [], "claim_text": "The Shunahshepa episode similarly attributes protective and life-preserving efficacy to mantras given by Vishvamitra within the epic story-world.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "traditional_narrative", "lens": {"field_id": "6bbd8d21-db3a-450c-85f8-2932df3ef2ba", "field_label": "Siddhis or powers attributed, including literal vs. symbolic framing", "parameter_id": "1b7184a9-e92f-4f89-8300-af633b008d29", "parameter_name": "Tapas and Sadhana"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Sarga 62 describes Vishvamitra protecting Shunahshepa and giving him hymns for the ritual.", "link_id": "5963c5df-b029-4a58-ac7b-a51f43eb0a34", "page_or_section": "1.62.18 onward", "passages": [{"chunk_id": "01b9c2bc-82aa-4320-b659-3d37088c6c3b", "confidence": 0.937142857142857, "excerpt": "Vividly: ''A father''s ambition in begetting sons is to do something good and positive  to the society in the present world and when departed a right place is acquired  in heavens through these sons, by their yearly death-day rituals etc., and hence  you do some good in saving this boy from premature death and earn an apt place for  me in heavens...''  अयं …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Introduction", "relationship": "supports", "section_title": "Introduction", "source_id": "4bd01c3e-d436-4013-a8a9-49d839abe475", "textual_layer": "Ramayana — Bala Kanda"}, {"chunk_id": "e4ea51bd-02c1-4363-af67-82b98757e401", "confidence": 0.878095238095238, "excerpt": "Sage Vishvamitra curses his sons as they defy his orders and accords two esoteric  hymns to Shunashepa, for chanting them in the Vedic-ritual of Ambariisha. Shunashepa  gets longevity on chanting those hymns. Thus Vishvamitra not only creates another  universe as in Trishanku''s episode, he even accords longevity, or even deathlessness  to mortals by his …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Introduction", "relationship": "supports", "section_title": "Introduction", "source_id": "4bd01c3e-d436-4013-a8a9-49d839abe475", "textual_layer": "Ramayana — Bala Kanda"}], "relationship": "supports", "source": {"author": "Valmiki", "authority_metadata": {}, "citation": "Valmiki Ramayana, Bala Kanda, Sarga 62 (https://www.valmikiramayan.net/utf8/baala/sarga62/balasans62.htm)", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Valmiki Ramayana, Bala Kanda, Sarga 62", "url": "https://www.valmikiramayan.net/utf8/baala/sarga62/balasans62.htm"}, "source_id": "4bd01c3e-d436-4013-a8a9-49d839abe475"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('bf922fd9-48be-4064-8c41-eed5a28c9adc','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "bf922fd9-48be-4064-8c41-eed5a28c9adc", "claim_kind": "traditional_account", "claim_relations": [], "claim_text": "Bala Kanda 1.21 attributes to Vishvamitra knowledge of weapons unknown even to other divine and nonhuman beings; this is a statement inside Vasistha''s epic speech and should be labeled accordingly.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Recorded source access issue"], "evidence_type": "traditional_narrative", "lens": {"field_id": "6bbd8d21-db3a-450c-85f8-2932df3ef2ba", "field_label": "Siddhis or powers attributed, including literal vs. symbolic framing", "parameter_id": "1b7184a9-e92f-4f89-8300-af633b008d29", "parameter_name": "Tapas and Sadhana"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Vasistha''s reassurance to Dasharatha uses superlative language about Vishvamitra''s weapon knowledge.", "link_id": "45b69393-1f91-4932-ba5d-03b9de4441fd", "page_or_section": "1.21.11-19", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur Valmiki Ramayanam Project", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same Bala Kanda chapter is linked below; compare editions before using a quotation.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayanam, Bala Kanda, Sarga 21", "url": "https://www.valmiki.iitk.ac.in/summary?field_kanda_tid=1&field_sarga_value=21"}, "source_id": "0537c002-ff50-437a-88f6-1ca1f43572cf"}, {"evidence_excerpt": "Vasistha''s reassurance to Dasharatha uses superlative language about Vishvamitra''s weapon knowledge.", "link_id": "152db826-5ffd-42c6-839a-0512beca8232", "page_or_section": "1.21.11-19", "passages": [{"chunk_id": "16e8b4c0-c2b9-44bb-b4df-2f3f97395940", "confidence": 0.901666666666667, "excerpt": "\"All the missiles known to Vishvamitra are the highly righteous children of Krishaasva  Prajapati, where Prajapati-s were the earliest ruler of mankind, and god Shiva gave them to Vishvamitra  when was ruling kingdom. Those missiles are the sons of Daksha Prajaapati''s daughters and her husband  Krishaasva Prajapati, and they are disparate in their form, …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Valmiki Ramayana - Bala Kanda in \nProse Sarga 21", "relationship": "supports", "section_title": "Valmiki Ramayana - Bala Kanda in \nProse Sarga 21", "source_id": "9227358e-67a7-46f5-a873-bb5582ebb893", "textual_layer": "Ramayana — Bala Kanda"}, {"chunk_id": "eb13ef00-ba13-431c-9957-e70d915433bf", "confidence": 0.938333333333333, "excerpt": "The ire of sage Vishvamitra is shown at king Dasharatha. To pacify sage Vishvamitra,  sage Vashishta intervenes and convinces king Dasharatha to send Rama with sage Vishvamitra. While doing  so, sage Vashishta enumerates the capabilities of sage Vishvamitra, his knowledge of weaponry. Vashishta  also suggests that all those weapons will be given to Rama, if …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Valmiki Ramayana - Bala Kanda in \nProse Sarga 21", "relationship": "supports", "section_title": "Valmiki Ramayana - Bala Kanda in \nProse Sarga 21", "source_id": "9227358e-67a7-46f5-a873-bb5582ebb893", "textual_layer": "Ramayana — Bala Kanda"}], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution); English rendering by Desiraju Hanumanta Rao", "authority_metadata": {"verified_http_status": 200}, "citation": "Valmiki Ramayana, Bala Kanda 1.21, chapter-level prose rendering.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": "Publicly accessible chapter page; preserve source attribution and link.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayana — Bala Kanda, Sarga 21 (prose)", "url": "https://www.valmikiramayan.net/utf8/baala/sarga21/bala_21_prose.htm"}, "source_id": "9227358e-67a7-46f5-a873-bb5582ebb893"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('da9e0088-0233-424d-9e3a-cbd0ba03679b','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "da9e0088-0233-424d-9e3a-cbd0ba03679b", "claim_kind": "traditional_account", "claim_relations": [], "claim_text": "The Mahabharata Shalya Parva Sarasvati story attributes curse-power over a river to Vishvamitra; database answers should state that the epic narrates this rather than present it as hydrological history.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "UNSUPPORTED", "epistemic_type": "TRADITIONAL_NARRATIVE", "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source", "Recorded source access issue"], "evidence_type": "traditional_narrative", "lens": {"field_id": "6bbd8d21-db3a-450c-85f8-2932df3ef2ba", "field_label": "Siddhis or powers attributed, including literal vs. symbolic framing", "parameter_id": "1b7184a9-e92f-4f89-8300-af633b008d29", "parameter_name": "Tapas and Sadhana"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The Vasisthapavaha account has Vishvamitra curse Sarasvati to carry blood-mixed water for a period.", "link_id": "aad0dc05-637b-4cc6-a6ee-2dfdacb7daa3", "page_or_section": "Shalya Parva, Vasisthapavaha", "passages": [], "relationship": "supports", "source": {"author": "Vyasa (traditional attribution); BORI Critical Edition", "authority_metadata": {}, "citation": "Mahabharata BORI, Shalya Parva", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Bhandarkar Oriental Resear