insert into original_claims values ('104cc799-9d9f-4ef8-aa26-c71e1813c82d','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "104cc799-9d9f-4ef8-aa26-c71e1813c82d", "claim_kind": "traditional_account", "claim_relations": [], "claim_text": "At the Ganga the party under Vishvamitra bathes, lights sacrificial fires, and makes offerings to gods and ancestors before continuing the journey.", "current_status": "approved", "epistemics": {"contract_basis": "tradition", "contract_satisfied": true, "contract_status": "SUPPORTED", "epistemic_type": "TRADITIONAL_NARRATIVE", "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["Current approval origin does not establish strict verification", "Recorded source access issue"], "evidence_type": "traditional_narrative", "lens": {"field_id": "4fbda67a-a586-4c2e-aab6-b057d9c2c4fa", "field_label": "Specific spiritual practice or discipline associated with the Rishi", "parameter_id": "1b7184a9-e92f-4f89-8300-af633b008d29", "parameter_name": "Tapas and Sadhana"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Sarga 35 describes bathing and ritual offerings at the Ganga.", "link_id": "b23beea9-030e-4769-a479-ba1dfef64880", "page_or_section": "1.35", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur Valmiki Ramayanam Project", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same Bala Kanda chapter is linked below; compare editions before using a quotation.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayanam, Bala Kanda, Sarga 35", "url": "https://www.valmiki.iitk.ac.in/summary?field_kanda_tid=1&field_sarga_value=35"}, "source_id": "3f8184f5-2d01-45b4-a672-080c7ab608d2"}, {"evidence_excerpt": "Sarga 35 describes bathing and ritual offerings at the Ganga.", "link_id": "d5d7bfee-912f-48f6-9be5-b3c496581a1f", "page_or_section": "1.35", "passages": [{"chunk_id": "c66709a7-d35e-4ec5-9dd5-3d0a4e99a306", "confidence": 0.853333333333333, "excerpt": "Motivated by Rama''s words the eminent-sage Vishvamitra commenced to narrate about the  emergence and that way even about the progression of River Ganga.  \"The lordly mountain Himavan who is the greatest treasure trove of minerals, Rama, also  treasures up a pair of daughters who by their comeliness are unequalled on earth. The slender-waisted  and …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Book I : Bala Kanda - The Youthful \nMajesties Sarga 35 in Prose", "relationship": "supports", "section_title": "Book I : Bala Kanda - The Youthful \nMajesties Sarga 35 in Prose", "source_id": "7ac166d3-a3f1-4e9c-a44a-32bf54c7db27", "textual_layer": "Ramayana — Bala Kanda"}, {"chunk_id": "e1e7a506-57fb-4b64-96bc-065eb978949e", "confidence": 0.946666666666667, "excerpt": "Sage Vishvamitra along with others reach the banks of River Ganga and they make their  sojourn on that riverbank. There when Rama inquisitively enquires about River Ganga Vishvamitra narrates  the legend of Ganga, as to how she is taken to heavens by gods from her father Himalayas.  On sojourning the remaining night on the bank of river Sona along with …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Book I : Bala Kanda - The Youthful \nMajesties Sarga 35 in Prose", "relationship": "supports", "section_title": "Book I : Bala Kanda - The Youthful \nMajesties Sarga 35 in Prose", "source_id": "7ac166d3-a3f1-4e9c-a44a-32bf54c7db27", "textual_layer": "Ramayana — Bala Kanda"}], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution); English rendering by Desiraju Hanumanta Rao", "authority_metadata": {"verified_http_status": 200}, "citation": "Valmiki Ramayana, Bala Kanda 1.35, chapter-level prose rendering.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": "Publicly accessible chapter page; preserve source attribution and link.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayana — Bala Kanda, Sarga 35 (prose)", "url": "https://www.valmikiramayan.net/utf8/baala/sarga35/bala_35_prose.htm"}, "source_id": "7ac166d3-a3f1-4e9c-a44a-32bf54c7db27"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('23be0733-87bf-4483-b320-9850b727605b','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "23be0733-87bf-4483-b320-9850b727605b", "claim_kind": "traditional_account", "claim_relations": [], "claim_text": "The final food-gift episode shows that ritual silence remains unbroken even when Vishvamitra gives away his entire prepared meal to a supplicant.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Recorded source access issue", "Claim-passage link points to a source absent from claim-source links"], "evidence_type": "traditional_narrative", "lens": {"field_id": "4fbda67a-a586-4c2e-aab6-b057d9c2c4fa", "field_label": "Specific spiritual practice or discipline associated with the Rishi", "parameter_id": "1b7184a9-e92f-4f89-8300-af633b008d29", "parameter_name": "Tapas and Sadhana"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The narrative stresses that he silently gives all the food and continues his vow.", "link_id": "5ed2238c-e08f-403b-afe8-42bfde64440a", "page_or_section": "1.65", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur Valmiki Ramayanam Project", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same Bala Kanda chapter is linked below; compare editions before using a quotation.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayanam, Bala Kanda, Sarga 65", "url": "https://www.valmiki.iitk.ac.in/summary?field_kanda_tid=1&field_sarga_value=65"}, "source_id": "35d30c22-48b6-4242-ad17-697405136d76"}], "unmatched_passage_links": [{"chunk_id": "78708c3d-c722-4223-95c2-92c74a53f606", "excerpt": "\" ''All the beings in the triad of the worlds are very highly perturbed at their  senses and they are as though stupefied, and when juxtaposed the sun is lustreless  before the resplendence of that great sage. [1-65-15b, 16a]  बुद्धिम् न कुरुते यावत् नाशे देव महामुनिः || १-६५-१६ तावत् प्रसादो भगवान् अग्नि रूपो महाद्युतिः |  16b, 17a. deva = oh, god; …", "excerpt_truncated": true, "page_or_section": "Introduction", "relationship": "context", "source": {"author": "Valmiki", "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "title": "Valmiki Ramayana, Bala Kanda, Sarga 65", "url": "https://www.valmikiramayan.net/utf8/baala/sarga65/balasans65.htm.orig"}, "source_id": "b1ff445c-d9d0-4f8e-a28f-f3a8053787ad"}, {"chunk_id": "d5e6cd91-c377-43d8-a3aa-a6233c8d0a82", "excerpt": "This meal is prepared by Vishvamitra alone after a thousand years and such self-cooking  of food by the ascetics is called, vaishva devam, since it is a sacred  preparation anena vaishvadeva ante samaagato atithiH svayam upoShyaa api sviiya anna pradaanena  sambhojya iti suucitam - dk  तस्मैः दत्त्वा तदा सिद्धम् सर्वम् विप्राय निश्चितः | निःषेषिते अन्ने …", "excerpt_truncated": true, "page_or_section": "Introduction", "relationship": "context", "source": {"author": "Valmiki", "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "title": "Valmiki Ramayana, Bala Kanda, Sarga 65", "url": "https://www.valmikiramayan.net/utf8/baala/sarga65/balasans65.htm.orig"}, "source_id": "b1ff445c-d9d0-4f8e-a28f-f3a8053787ad"}]}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('35d0e471-4e1a-45ff-8832-7c5b0e26ae37','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "35d0e471-4e1a-45ff-8832-7c5b0e26ae37", "claim_kind": "traditional_account", "claim_relations": [], "claim_text": "The Shanti Parva famine narrative distinguishes involuntary starvation from voluntary tapas: Vishvamitra''s hunger there is a crisis of survival, not an ascetic dietary vow.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "UNSUPPORTED", "epistemic_type": "TRADITIONAL_NARRATIVE", "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source", "Recorded source access issue"], "evidence_type": "traditional_narrative", "lens": {"field_id": "4fbda67a-a586-4c2e-aab6-b057d9c2c4fa", "field_label": "Specific spiritual practice or discipline associated with the Rishi", "parameter_id": "1b7184a9-e92f-4f89-8300-af633b008d29", "parameter_name": "Tapas and Sadhana"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The chapter frames him as impoverished and emaciated by famine, seeking food to preserve life.", "link_id": "44b3fcc5-20c2-46f1-9f85-ea734c1bca7b", "page_or_section": "12.142", "passages": [], "relationship": "supports", "source": {"author": "Vyasa (traditional attribution)", "authority_metadata": {}, "citation": "Mahabharata, Shanti Parva, 142", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Gita Press edition / Vedapath presentation", "rights_or_access_note": null, "source_status": "approved", "