insert into original_claims values ('414589e3-ad4f-4f1c-941a-b93274ca0444','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "414589e3-ad4f-4f1c-941a-b93274ca0444", "claim_kind": "traditional_account", "claim_relations": [], "claim_text": "Vishvamitra''s instruction to Rama includes both invocation and withdrawal procedures for astras, presenting restraint and reversibility as part of competent sacred-weapon practice.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Recorded source access issue"], "evidence_type": "traditional_narrative", "lens": {"field_id": "4fbda67a-a586-4c2e-aab6-b057d9c2c4fa", "field_label": "Specific spiritual practice or discipline associated with the Rishi", "parameter_id": "1b7184a9-e92f-4f89-8300-af633b008d29", "parameter_name": "Tapas and Sadhana"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Sarga 28 explicitly concerns the methods of invoking, dispatching, and withdrawing astras.", "link_id": "87cd6045-70f7-4c2b-a9e4-b8655398a6a4", "page_or_section": "1.28", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur Valmiki Ramayanam Project", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel trans