insert into original_claims values ('524298c4-56e4-44d2-886a-8e4304877f88','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "524298c4-56e4-44d2-886a-8e4304877f88", "claim_kind": "traditional_account", "claim_relations": [], "claim_text": "The astras are transmitted through mantras in the Bala Kanda account, making recitation and sacred formulae integral to Vishvamitra''s martial-spiritual pedagogy.", "current_status": "approved", "epistemics": {"contract_basis": "tradition", "contract_satisfied": true, "contract_status": "SUPPORTED", "epistemic_type": "TRADITIONAL_NARRATIVE", "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["Current approval origin does not establish strict verification", "Recorded source access issue"], "evidence_type": "traditional_narrative", "lens": {"field_id": "4fbda67a-a586-4c2e-aab6-b057d9c2c4fa", "field_label": "Specific spiritual practice or discipline associated with the Rishi", "parameter_id": "1b7184a9-e92f-4f89-8300-af633b008d29", "parameter_name": "Tapas and Sadhana"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Verses 1.27.21-23 describe the mantragrama and the weapons responding to Vishvamitra''s japa.", "link_id": "c59ce241-14be-4e07-9671-c3b12148dcd4", "page_or_section": "1.27.21-23", "passages": [{"chunk_id": "4cd2f9db-d7f3-4cbf-a7ba-5ba1b92b5363", "confidence": 0.82, "excerpt": "\"Oh, mighty armed son of the best king, I am giving a great missile named Vaidyadhara  by its name, and a gem of sword named Nandana. Thus, the missile which is very much liked by Gandharva-s,  namely Mohana, [The Stupefier,] the missile called Prasvapana [The Inducer of Sleep,] and the gentle  Prashamana, [The Pacifier of enemy''s anger.]  \"Oh, highly …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Book I : Bala Kanda - The Youthful MajestiesSarga 27 in Prose", "relationship": "supports", "section_title": "Book I : Bala Kanda - The Youthful MajestiesSarga 27 in Prose", "source_id": "810e23ca-7c61-499e-85f4-e37468b88b6f", "textual_layer": "Ramayana — Bala Kanda"}, {"chunk_id": "6fe6bb6e-47f1-458e-b2f9-8f7a60f0b08f", "confidence": 0.88, "excerpt": "Sage Vishvamitra satisfied with the behaviour of Rama in obliging the orders of elders  and performing the act that is assigned to him, gives many weapons to Rama, called shastra, astra-s.  The weaponry is categorised mainly into two types. One is shastra - a handheld weapon like  sword, lance or mace. The other is astra - a projectile missile invoked by …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Book I : Bala Kanda - The Youthful MajestiesSarga 27 in Prose", "relationship": "supports", "section_title": "Book I : Bala Kanda - The Youthful MajestiesSarga 27 in Prose", "source_id": "810e23ca-7c61-499e-85f4-e37468b88b6f", "textual_layer": "Ramayana — Bala Kanda"}], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution); English rendering by Desiraju Hanumanta Rao", "authority_metadata": {"verified_http_status": 200}, "citation": "Valmiki Ramayana, Bala Kanda 1.27, chapter-level prose rendering.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": "Publicly accessible chapter page; preserve source attribution and link.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayana — Bala Kanda, Sarga 27 (prose)", "url": "https://www.valmikiramayan.net/utf8/baala/sarga27/bala_27_prose.htm"}, "source_id": "810e23ca-7c61-499e-85f4-e37468b88b6f"}, {"evidence_excerpt": "Verses 1.27.21-23 describe the mantragrama and the weapons responding to Vishvamitra''s japa.", "link_id": "8c3cc083-a7ee-4d8e-b023-5413e06068a0", "page_or_section": "1.27.21-23", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur Valmiki Ramayanam Project", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same Bala Kanda chapter is linked below; compare editions before using a quotation.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayanam, Bala Kanda, Sarga 27", "url": "https://www.valmiki.iitk.ac.in/sloka?field_kanda_tid=1&field_sarga_value=27&language=dv"}, "source_id": "f1d7e0f2-22cc-4086-84d5-66fb03fdef01"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('5570814f-30f0-4646-8356-cb40b235e457','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "5570814f-30f0-4646-8356-cb40b235e457", "claim_kind": "traditional_account", "claim_relations": [], "claim_text": "Before transmitting the celestial weapons in Bala Kanda 1.27, Vishvamitra performs purification and faces east, presenting the instruction as ritually structured rather than as ordinary military training.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Recorded source access issue"], "evidence_type": "traditional_narrative", "lens": {"field_id": "4fbda67a-a586-4c2e-aab6-b057d9c2c4fa", "field_label": "Specific spiritual practice or discipline associated with the Rishi", "parameter_id": "1b7184a9-e92f-4f89-8300-af633b008d29", "parameter_name": "Tapas and Sadhana"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Verse 1.27.21 describes purification, eastward orientation, and transmission of the mantra collection.", "link_id": "a1eab8a9-7bc2-402f-b74d-1381874c0ce4", "page_or_section": "1.27.21", "passages": [{"chunk_id": "6fe6bb6e-47f1-458e-b2f9-8f7a60f0b08f", "confidence": 0.843076923076923, "excerpt": "Sage Vishvamitra satisfied with the behaviour of Rama in obliging the orders of elders  and performing the act that is assigned to him, gives many weapons to Rama, called shastra, astra-s.  The weaponry is categorised mainly into two types. One is shastra - a handheld weapon like  sword, lance or mace. The other is astra - a projectile missile invoked by …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Book I : Bala Kanda - The Youthful MajestiesSarga 27 in Prose", "relationship": "supports", "section_title": "Book I : Bala Kanda - The Youthful MajestiesSarga 27 in Prose", "source_id": "810e23ca-7c61-499e-85f4-e37468b88b6f", "textual_layer": "Ramayana — Bala Kanda"}], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution); English rendering by Desiraju Hanumanta Rao", "authority_metadata": {"verified_http_status": 200}, "citation": "Valmiki Ramayana, Bala Kanda 1.27, chapter-level prose rendering.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": "Publicly accessible chapter page; preserve source attribution and link.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayana — Bala Kanda, Sarga 27 (prose)", "url": "https://www.valmikiramayan.net/utf8/baala/sarga27/bala_27_prose.htm"}, "source_id": "810e23ca-7c61-499e-85f4-e37468b88b6f"}, {"evidence_excerpt": "Verse 1.27.21 describes purification, eastward orientation, and transmission of the mantra collection.", "link_id": "5e6da54a-8e09-4345-b144-044b9e3184cf", "page_or_section": "1.27.21", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur Valmiki Ramayanam Project", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same Bala Kanda chapter is linked below; compare editions before using a quotation.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayan