insert into original_claims values ('7beb27aa-8818-4859-9e04-beb1c8f19db5','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "7beb27aa-8818-4859-9e04-beb1c8f19db5", "claim_kind": "traditional_account", "claim_relations": [], "claim_text": "Sage Vishvamitra undertakes a sacrificial vow to attain a spiritual goal, which faces obstacles from shape-shifting demons.", "current_status": "approved", "epistemics": {"contract_basis": "tradition", "contract_satisfied": true, "contract_status": "SUPPORTED", "epistemic_type": "TRADITIONAL_NARRATIVE", "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "traditional_narrative", "lens": {"field_id": "4fbda67a-a586-4c2e-aab6-b057d9c2c4fa", "field_label": "Specific spiritual practice or discipline associated with the Rishi", "parameter_id": "1b7184a9-e92f-4f89-8300-af633b008d29", "parameter_name": "Tapas and Sadhana"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Sage Vishvamitra asks King Dasharatha to send Rama to protect the Vedic ritual   that is being conducted by him, from the demons that are constantly disrupting   it. The sage asserts King Dasharatha that he and the other sages in Dasharatha''s   court know the capabilities of Rama and though Rama is in his adolescence, he   can easily kill the demons. But …", "link_id": "216ca388-564a-4a0e-b3ab-7e949daad1f8", "page_or_section": "Introduction", "passages": [{"chunk_id": "49491f41-5500-43be-977a-a8f12fc6841f", "confidence": 0.99, "excerpt": "\"At the near end of almost completed ritual of mine two valiant and well-trained   demons, namely Mareecha and Subaahu, are drenching the Altar of Fire with streams   of meat and blood. [1-19-5, 6a]  अवधूते तथाभूते तस्मिन्नियमनिश्चये || १-१९-६  कृतश्रमो निरुत्साहस्तस्माद्देशादपाक्रमे |  6b, 7a. tasmin niyamanishchaye = that, ritual vow; avadhuute   = …", "excerpt_truncated": true, "is_active": true, "link_method": "section_metadata", "page_or_section": "Introduction", "relationship": "supports", "section_title": "Introduction", "source_id": "826d5c8a-6135-4304-8825-09579ff9a478", "textual_layer": "Ramayana — Bala Kanda, Sarga 19"}, {"chunk_id": "9374da7d-e000-40d3-83fc-7d752aa7f76c", "confidence": 0.99, "excerpt": "Sage Vishvamitra asks King Dasharatha to send Rama to protect the Vedic ritual   that is being conducted by him, from the demons that are constantly disrupting   it. The sage asserts King Dasharatha that he and the other sages in Dasharatha''s   court know the capabilities of Rama and though Rama is in his adolescence, he   can easily kill the demons. But …", "excerpt_truncated": true, "is_active": true, "link_method": "section_metadata", "page_or_section": "Introduction", "relationship": "supports", "section_title": "Introduction", "source_id": "826d5c8a-6135-4304-8825-09579ff9a478", "textual_layer": "Ramayana — Bala Kanda, Sarga 19"}, {"chunk_id": "b1bc66f5-1954-483e-a7db-b00c168c90df", "confidence": 0.913333333333333, "excerpt": "Now Rama''s reputation is going to be enhanced by Sage Vishvamitra in eliminating   demoness Tataka, in releasing Ahalya from her curse, breaking Shiva''s bow, marriage   with Seetha, rebuffing Parashuraama etc. And also Vishvamitra leaves the decision   to Dasharatha, ''if only your ministers, clergy as well political, permit then   alone you send Rama with …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Introduction", "relationship": "supports", "section_title": "Introduction", "source_id": "826d5c8a-6135-4304-8825-09579ff9a478", "textual_layer": "Ramayana — Bala Kanda, Sarga 19"}], "relationship": "supports", "source": {"author": "Valmiki", "authority_metadata": {}, "citation": "Valmiki Ramayana, Bala Kanda, Sarga 19 (https://valmikiramayan.net/utf8/baala/sarga19/balasans19.htm)", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Valmiki Ramayana, Bala Kanda, Sarga 19", "url": "https://valmikiramayan.net/utf8/baala/sarga19/balasans19.htm"}, "source_id": "826d5c8a-6135-4304-8825-09579ff9a478"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('99acbe03-a70c-4ad2-ba5c-4b099da1e780','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "99acbe03-a70c-4ad2-ba5c-4b099da1e780", "claim_kind": "traditional_account", "claim_relations": [], "claim_text": "The epic portrayal treats mastery of anger as part of Vishvamitra''s ascetic project, not merely acquisition of supernatural power.", "current_status": "approved", "epistemics": {"contract_basis": "tradition", "contract_satisfied": true, "contract_status": "SUPPORTED", "epistemic_type": "TRADITIONAL_NARRATIVE", "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "traditional_narrative", "lens": {"field_id": "4fbda67a-a586-4c2e-aab6-b057d9c2c4fa", "field_label": "Specific spiritual practice or discipline associated with the Rishi", "parameter_id": "1b7184a9-e92f-4f89-8300-af633b008d29", "parameter_name": "Tapas and Sadhana"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The Rambha episode ends in shame over anger and renewed determination for self-conquest.", "link_id": "9519826c-f77e-4896-b8ee-e1a9c11322a6", "page_or_section": "1.64", "passages": [{"chunk_id": "2a5bae86-6077-4fd8-8d21-59b2a47b760a", "confidence": 0.847272727272727, "excerpt": "Vishvamitra curses Rambha, the celestial wench, knowing that she arrived at the behest of Indra to cause  hindrance to his ascesis. But later feels ashamed to loose his tongue and then he is determined to undertake  another round of ascesis to conquer is own senses.  सुरकार्यमिदं रंभे कर्तव्यं सुमहत्त्वया |लोभनं कौशिकस्येह काममोहसमन्वितम् || १-६४-१  1. …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Introduction", "relationship": "supports", "section_title": "Introduction", "source_id": "8d1e7888-6577-4564-b935-96ed0ae1b902", "textual_layer": "Ramayana — Bala Kanda"}, {"chunk_id": "515003fb-3676-4dbd-8abb-a58e725319ce", "confidence": 0.943636363636364, "excerpt": "Whereof you tried to entice me who am wishing to win over the wanton and wroth, you unlucky female  Rambha, thereof you will become a rocklike statued wastrel. [1-64-12]  ब्राह्मणः सुमहातेजास्तपोबलसमन्वितः |उद्धरिष्यति रंभे त्वां मत्क्रोधकलुषीकृताम् || १-६४-१३  13. rambhe = oh Rambha; sumahaatejaaH = very high resplendent one;  tapobalasamanvitaH = having …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Introduction", "relationship": "supports", "section_title": "Introduction", "source_id": "8d1e7888-6577-4564-b935-96ed0ae1b902", "textual_layer": "Ramayana — Bala Kanda"}], "relationship": "supports", "source": {"author": "Valmiki", "authority_metadata": {}, "citation": "Valmiki Ramayana, Bala Kanda, Sarga 64 (https://www.valmikiramayan.net/utf8/baala/sarga64/balasans64.htm)", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Valmiki Ramayana, Bala Kanda, Sarga 64", "url": "https://www.valmikiramayan.net/utf8/baala/sarga64/balasans64.htm"}, "source_id": "8d1e7888-6577-4564-b935-96ed0ae1b902"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('b070cd29-c722-4478-b2ce-56ff7085e386','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "b070cd29-c722-4478-b2ce-56ff7085e386", "claim_kind": "traditional_account", "claim_relations": [], "claim_text": "Bala and Atibala are presented as disciplines transmitted by Vishvamitra to Rama, and the text links their efficacy to practice and ascetic cultivation.", "current_status": "approved", "epistemics": {"contract_basis": "tradition", "contract_satisfied": true, "contract_status": "SUPPORTED", "epistemic_type": "TRADITIONAL_NARRATIVE", "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source", "Claim-passage link points to a source absent from claim-source links"], "evidence_type": "traditional_narrative", "lens": {"field_id": "4fbda67a-a586-4c2e-aab6-b057d9c2c4fa", "field_label": "Specific spiritual practice or discipline associated with the Rishi", "parameter_id": "1b7184a9-e92f-4f89-8300-af633b008d29", "parameter_name": "Tapas and Sadhana"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Vishvamitra transmits Bala and Atibala and says their qualities are cultivated through tapas/practice.", "link_id": "243a46a2-16bf-41e4-899f-5075b3580302", "page_or_section": "1.22.11-20", "passages": [{"chunk_id": "347af684-3faf-459c-902b-b4f21353fb0c", "confidence": 0.825, "excerpt": "Sage Vishvamitra is the Seer for Gayatri hymn. He is the same Sage to impart balaatibala  hymns to Rama and Lakshmana. For those readers that are interested to know or to practice,  the Upanishad of balaatibala is included hereunder. This hymn is yet another  aspect of Gayatri, and there is no hymn superior than Gayatri, na gaayatryaaH  paramam japam  …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "bala-atibala-teachings", "relationship": "supports", "section_title": "bala-atibala-teachings", "source_id": "4772171e-b53b-4ae5-9ffa-e6edf7a8f9de", "textual_layer": "Ramayana — Bala Kanda"}, {"chunk_id": "b6e661c7-935d-4437-966f-55bbe4dbc538", "confidence": 0.825, "excerpt": "क्षुत्पिपासे न ते राम भविष्येते नरोत्तम |  बलामतिबलां चैव पठतस्तात राघव || १-२२-१७  17. narottama raaghava = oh best among people, Raghava; balam atibalam   cha eva = bala and atibala hymns; paThataH = if recited; taata   = my dear; te = to you; raama = Rama;  kSutpipaase = hunger and thirst; na bhaviSyete = not, will be there.  \"Oh, best one among men, …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Introduction", "relationship": "supports", "section_title": "Introduction", "source_id": "4772171e-b53b-4ae5-9ffa-e6edf7a8f9de", "textual_layer": "Ramayana — Bala Kanda"}], "relationship": "supports", "source": {"author": "Valmiki", "authority_metadata": {}, "citation": "Valmiki Ramayana, Bala Kanda, Sarga 22 (https://www.valmikiramayan.net/utf8/baala/sarga22/balasans22.htm)", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Valmiki Ramayana, Bala Kanda, Sarga 22", "url": "https://www.valmikiramayan.net/utf8/baala/sarga22/balasans22.htm"}, "source_id": "4772171e-b53b-4ae5-9ffa-e6edf7a8f9de"}], "unmatched_passage_links": [{"chunk_id": "ce8f66d2-4cf5-459e-b23b-950ff05a8b64", "excerpt": "53 Epithet Number of Occurrences Citations ‘blessed [bhagavant]’ 6 Mbh 9.39.19, Rām 1.51.2d, 1.51.12a, 1.52.10a, 1.52.21a, 1.55.2a ‘having great splendor [mahātejas]’ 3 Rām 1.51.20a, 1.54.26a, 1.55.22a ‘excellent sage [munivara, munisattama]’ 3 Mbh 9.39.20b Rām 1.51.3c, 1.52.10b ‘having great ascetic power [mahātapas]’ 2 Rām 1.51.6b, 1.55.22b ‘having great …", "excerpt_truncated": true, "page_or_section": "p. 53 (PDF page 13)", "relationship": "context", "source": {"author": "Adheesh Sathaye", "publication_year": 2007, "publisher_or_institution": "Acta Orientalia Vilnensia / Vilnius University Press", "rights_or_access_note": "Official journal diamond open access, CC BY 4.0: https://www.journals.vu.lt/acta-orientalia-vilnensia/journalpolicy", "source_status": "approved", "source_type": "scholarly_article", "title": "How to become a Brahman: The construction of varṇa as social place in the Mahābhārata’s legends of Viśvāmitra", "url": "https://www.journals.vu.lt/acta-orientalia-vilnensia/article/download/3751/5207"}, "source_id": "06fec486-e5af-4c7e-95db-afbb2e237c75"}]}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('b3aaa65c-60bf-480a-b5d2-c163d8c588cc','{"approval_origin": "imported_existing", "certainty": "high", "claim_id": "b3aaa65c-60bf-480a-b5d2-c163d8c588cc", "claim_kind": "traditional_account", "claim_relations": [], "claim_text": "Practices attributed to Vishvamitra include fruit-and-root subsistence, sense-control, prolonged tapas, silence, fasting, and increasingly strict self-restraint.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Recorded source access issue"], "evidence_type": "traditional_narrative", "lens": {"field_id": "4fbda67a-a586-4c2e-aab6-b057d9c2c4fa", "field_label": "Specific spiritual practice or discipline associated with the Rishi", "parameter_id": "1b7184a9-e92f-4f89-8300-af633b008d29", "parameter_name": "Tapas and Sadhana"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Fruit/root subsistence, controlled senses, and rigorous penance are explicitly described.", "link_id": "da5d3065-09c5-4c9a-8e42-b6cd94c546af", "page_or_section": "Bala Kanda 1.57.2", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana, Bala Kanda 1.57. IIT Kanpur Valmiki Ramayanam.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same Bala Kanda chapter is linked below; compare editions before using a quotation.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayanam — Bala Kanda, Sarga 57", "url": "https://www.valmiki.iitk.ac.in/sloka?field_kanda_tid=1&field_sarga_value=57&language=te"}, "source_id": "062ddd1e-1bce-4f90-82cb-7fc948220c7e"}, {"evidence_excerpt": "Fruit/root subsistence, controlled senses, and rigorous penance are explicitly described.", "link_id": "7474503c-818a-49df-bd92-89ff55d6ba13", "page_or_section": "Bala Kanda 1.57.2", "passages": [{"chunk_id": "5eb8cac4-0092-435c-b415-a6a6a3647938", "confidence": 0.55, "excerpt": "The legend of Trishanku is narrated to Rama, which forms a part of Vishvamitra''s   legend. When Brahma blesses Vishvamitra to be a kingly-saint, rather   than a Brahman-saint, Vishvamitra continues his ascesis in southerly   parts of country. In the meantime, one king named Trishanku desired   to go to heaven with mortal body and approaches Vashishta who …", "excerpt_truncated": true, "is_active": true, "link_method": "citation_partial", "page_or_section": "Valmiki Ramayana - Bala Kanda in Prose Sarga 57", "relationship": "context", "section_title": "Valmiki Ramayana - Bala Kanda in Prose Sarga 57", "source_id": "eb352cb8-8b04-4907-8b16-cd99b62da56e", "textual_layer": "Ramayana — Bala Kanda"}], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution); English rendering by Desiraju Hanumanta Rao", "authority_metadata": {"verified_http_status": 200}, "citation": "Valmiki Ramayana, Bala Kanda 1.57, chapter-level prose rendering.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": "Publicly accessible chapter page; preserve source attribution and link.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayana — Bala Kanda, Sarga 57 (prose)", "url": "https://www.valmikiramayan.net/utf8/baala/sarga57/bala_57_prose.htm"}, "source_id": "eb352cb8-8b04-4907-8b16-cd99b62da56e"}], "unmatched_passage_links": []}'::jsonb,'approved','imported_existing');
insert into original_claims values ('c20928a6-f1d5-4a73-b31d-de78684a4f7c','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "c20928a6-f1d5-4a73-b31d-de78684a4f7c", "claim_kind": "traditional_account", "claim_relations": [], "claim_text": "The Ramayana associates Vishvamitra''s sadhana with tapas, restraint, vows, silence, and repeated efforts at control of desire and anger.", "current_status": "approved", "epistemics": {"contract_basis": "tradition", "contract_satisfied": true, "contract_status": "SUPPORTED", "epistemic_type": "TRADITIONAL_NARRATIVE", "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "traditional_narrative", "lens": {"field_id": "4fbda67a-a586-4c2e-aab6-b057d9c2c4fa", "field_label": "Specific spiritual practice or discipline associated with the Rishi", "parameter_id": "1b7184a9-e92f-4f89-8300-af633b008d29", "parameter_name": "Tapas and Sadhana"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The culminating tapas phase emphasizes silence and endurance after earlier failures of self-control.", "link_id": "7a81a160-482f-450a-8cf5-f33b3651ac24", "page_or_section": "1.64-65", "passages": [{"chunk_id": "d5e6cd91-c377-43d8-a3aa-a6233c8d0a82", "confidence": 0.85, "excerpt": "This meal is prepared by Vishvamitra alone after a thousand years and such self-cooking  of food by the ascetics is called, vaishva devam, since it is a sacred  preparation anena vaishvadeva ante samaagato atithiH svayam upoShyaa api sviiya anna pradaanena  sambhojya iti suucitam - dk  तस्मैः दत्त्वा तदा सिद्धम् सर्वम् विप्राय निश्चितः | निःषेषिते अन्ने …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Introduction", "relationship": "supports", "section_title": "Introduction", "source_id": "b1ff445c-d9d0-4f8e-a28f-f3a8053787ad", "textual_layer": "Ramayana — Bala Kanda"}, {"chunk_id": "ef5de7fd-af8f-4eaa-9685-ac9b0a43aa7d", "confidence": 0.82, "excerpt": "Vishvamitra becomes Brahma-sage after a prolonged ascesis that made all the worlds  to startle. All gods request Brahma to accord the supreme Brahma-sageship on Vishvamitra  as he is cleansed of all mortal impurities, and Brahma accords that highest order  on him. Thus Sage Shataananda concludes his narration about the legend of Vishvamitra.  अथ हैमवतीम् …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Introduction", "relationship": "supports", "section_title": "Introduction", "source_id": "b1ff445c-d9d0-4f8e-a28f-f3a8053787ad", "textual_layer": "Ramayana — Bala Kanda"}], "relationship": "supports", "source": {"author": "Valmiki", "authority_metadata": {}, "citation": "Valmiki Ramayana, Bala Kanda, Sarga 65 (https://www.valmikiramayan.net/utf8/baala/sarga65/balasans65.htm.orig)", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Valmiki Ramayana, Bala Kanda, Sarga 65", "url": "https://www.valmikiramayan.net/utf8/baala/sarga65/balasans65.htm.orig"}, "source_id": "b1ff445c-d9d0-4f8e-a28f-f3a8053787ad"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('ccbb927c-37fc-4b62-8924-52c2433dba48','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "ccbb927c-37fc-4b62-8924-52c2433dba48", "claim_kind": "traditional_account", "claim_relations": [], "claim_text": "The Pushkara phase explicitly includes a root-and-fruit diet alongside severe tapas, providing a concrete dietary austerity rather than only a generic reference to penance.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "PARTIALLY_SUPPORTED", "epistemic_type": "SYNTHETIC_INTERPRETATION", "proposed_type": "SYNTHETIC_INTERPRETATION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["Current approval origin does not establish strict verification", "Recorded source access issue"], "evidence_type": "traditional_narrative", "lens": {"field_id": "4fbda67a-a586-4c2e-aab6-b057d9c2c4fa", "field_label": "Specific spiritual practice or discipline associated with the Rishi", "parameter_id": "1b7184a9-e92f-4f89-8300-af633b008d29", "parameter_name": "Tapas and Sadhana"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The text describes Vishvamitra at Pushkara as mulaphalashana while performing intense austerities.", "link_id": "547262d1-e1fe-4756-869e-d5c87c6f3d74", "page_or_section": "1.61.4", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur Valmiki Ramayanam Project", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same Bala Kanda chapter is linked below; compare editions before using a quotation.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayanam, Bala Kanda, Sarga 61", "url": "https://www.valmiki.iitk.ac.in/sloka?field_kanda_tid=1&field_sarga_value=61&language=dv"}, "source_id": "9f59c2e1-f58e-4f53-99e6-4cac5b3f307c"}, {"evidence_excerpt": "The text describes Vishvamitra at Pushkara as mulaphalashana while performing intense austerities.", "link_id": "d6ebaae7-ea35-4dab-916c-437ea8b7aef0", "page_or_section": "1.61.4", "passages": [{"chunk_id": "0f976ed8-309c-404b-bc7e-56c059c59280", "confidence": 0.842222222222222, "excerpt": "The Legend of Shunashepa is commenced and Sage Shataananda continues   this as a part of Vishvamitra''s legend. When Rama''s grandparent   Ambariisha undertook a ritual, Indra impounds that ritual''s horse.   Then Ambariisha had to fetch a human-animal in lieu of that lost   horse. When none is available one named Shunashepa, son of Sage   Riciika, and a …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Book I : Bala Kanda - The Youthful Majesties\nSarga 61in Prose", "relationship": "supports", "section_title": "Book I : Bala Kanda - The Youthful Majesties\nSarga 61in Prose", "source_id": "e95fc345-1672-4147-847b-4d7ab480740f", "textual_layer": "Ramayana — Bala Kanda"}], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution); English rendering by Desiraju Hanumanta Rao", "authority_metadata": {"verified_http_status": 200}, "citation": "Valmiki Ramayana, Bala Kanda 1.61, chapter-level prose rendering.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": "Publicly accessible chapter page; preserve source attribution and link.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayana — Bala Kanda, Sarga 61 (prose)", "url": "https:/