insert into original_claims values ('ed2ae34d-53f1-461b-8fd6-b066d864d5fb','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "ed2ae34d-53f1-461b-8fd6-b066d864d5fb", "claim_kind": "traditional_account", "claim_relations": [], "claim_text": "Bala Kanda 1.55 portrays Vishvamitra''s worship of Maheswara as the means by which he seeks Dhanurveda knowledge and a comprehensive repertoire of astras.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "PARTIALLY_SUPPORTED", "epistemic_type": "TRADITIONAL_NARRATIVE", "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Current approval origin does not establish strict verification", "Recorded source access issue", "Claim-passage link points to a source absent from claim-source links"], "evidence_type": "traditional_narrative", "lens": {"field_id": "4fbda67a-a586-4c2e-aab6-b057d9c2c4fa", "field_label": "Specific spiritual practice or discipline associated with the Rishi", "parameter_id": "1b7184a9-e92f-4f89-8300-af633b008d29", "parameter_name": "Tapas and Sadhana"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "After installing his son as king, Vishvamitra retires to the Himalayas and worships Shiva for weapon knowledge.", "link_id": "04cce2fe-9a69-4ec6-895b-dffc32111f6c", "page_or_section": "1.55", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur Valmiki Ramayanam Project", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same Bala Kanda chapter is linked below; compare editions before using a quotation.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayanam, Bala Kanda, Sarga 55", "url": "https://www.valmiki.iitk.ac.in/summary?field_kanda_tid=1&field_sarga_value=55"}, "source_id": "d066d3a2-2155-4655-8930-66d256bc28cb"}], "unmatched_passage_links": [{"chunk_id": "a2fc6f30-74e7-4faf-8a7e-e6ac98483baa", "excerpt": "\"After a long lost time, the Holy Bull masted God of Gods, Shiva, has shown himself  to that great-saint Vishvamitra, for He is a ready boon-giver...  \" ''Oh, king, for which purpose you undertook this ascesis... tell that, what really  is tellable by you... what is the boon that you beseech... that be made known to  me for I am the boon-giver at the …", "excerpt_truncated": true, "page_or_section": "Book I : Bala Kanda - The Youthful Majesties\nSarga 55 in Prose", "relationship": "context", "source": {"author": "Valmiki", "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "title": "Valmiki Ramayana, Bala Kanda, Sarga 55", "url": "https://www.valmikiramayan.net/utf8/baala/sarga55/bala_55_prose.htm"}, "source_id": "f73e8d72-d089-4ee7-a92e-4a948f36984f"}]}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('f37c5c15-eea4-454b-af48-14f09d63edb3','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "f37c5c15-eea4-454b-af48-14f09d63edb3", "claim_kind": "traditional_account", "claim_relations": [], "claim_text": "At Siddhashrama Vishvamitra''s ritual observance includes mauna during the sacrifice, while the princes protect the rite externally.", "current_status": "approved", "epistemics": {"contract_basis": "tradition", "contract_satisfied": true, "contract_status": "SUPPORTED", "epistemic_type": "TRADITIONAL_NARRATIVE", "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["Current approval origin does not establish strict verification", "Recorded source access issue"], "evidence_type": "traditional_narrative", "lens": {"field_id": "4fbda67a-a586-4c2e-aab6-b057d9c2c4fa", "field_label": "Specific spiritual practice or discipline associated with the Rishi", "parameter_id": "1b7184a9-e92f-4f89-8300-af633b008d29", "parameter_name": "Tapas and Sadhana"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The chapter states that Vishvamitra remains silent during the protected yajna.", "link_id": "bc3f0245-711c-4b2b-ba96-4a4327a982c0", "page_or_section": "1.30", "passages": [{"chunk_id": "a7ec8ae6-04f3-4603-acf2-bb83387319d9", "confidence": 0.822222222222222, "excerpt": "While the Vedic ritual is proceeding well towards its conclusion according to hymnal  rendering and rules of conducting the ritual, a strident and frightening blare is generated in the sky.  As to how massive clouds appear in torrential cloudburst, likewise two demons appeared enshrouding the  sky, and performing wizardry they about to swoop down towards …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Book I : Bala Kanda - The Youthful \nMajestiesSarga 30 in Prose", "relationship": "supports", "section_title": "Book I : Bala Kanda - The Youthful \nMajestiesSarga 30 in Prose", "source_id": "71a02349-8e43-4784-b671-a4c6cdbac61a", "textual_layer": "Ramayana — Bala Kanda"}, {"chunk_id": "c2264186-8ff6-4560-b37e-23f2668f17a4", "confidence": 0.884444444444444, "excerpt": "Rama and Lakshmana while safeguarding the ritual of Sage Vishvamitra for six days and  nights, on the last night demons named Maareecha and Subaahu come to hinder the ritual. Rama acts deftly  and hits out Maareecha to a long distance, but kills the other, namely Subaahu. Rama thus makes the  ritual of sage Vishvamitra a success.  The two enemy subjugators, …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Book I : Bala Kanda - The Youthful \nMajestiesSarga 30 in Prose", "relationship": "supports", "section_title": "Book I : Bala Kanda - The Youthful \nMajestiesSarga 30 in Prose", "source_id": "71a02349-8e43-4784-b671-a4c6cdbac61a", "textual_layer": "Ramayana — Bala Kanda"}], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution); English rendering by Desiraju Hanumanta Rao", "authority_metadata": {"verified_http_status": 200}, "citation": "Valmiki Ramayana, Bala Kanda 1.30, chapter-level prose rendering.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": "Publicly accessible chapter page; preserve source attribution and link.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayana — Bala Kanda, Sarga 30 (prose)", "url": "https://www.valmikiramayan.net/utf8/baala/sarga30/bala_30_prose.htm"}, "source_id": "71a02349-8e43-4784-b671-a4c6cdbac61a"}, {"evidence_excerpt": "The chapter states that Vishvamitra remains silent during the protected yajna.", "link_id": "805a8a89-a164-4334-acd9-5fbb09c308c2", "page_or_section": "1.30", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur Valmiki Ramayanam Project", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same Bala Kanda chapter is linked below; compare editions before using a quotation.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayanam, Bala Kanda, Sarga 30", "url": "https://www.valmiki.iitk.ac.in/summary?field_kanda_tid=1&field_sarga_value=30"}, "source_id": "c006a140-843f-4e0f-bd26-d6f273aeb801"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('023b117d-1272-43f7-be60-6a267e2cb07f','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "023b117d-1272-43f7-be60-6a267e2cb07f", "claim_kind": "established_fact", "claim_relations": [], "claim_text": "The Aitareya Brahmana preserves a Shunahshepa-Devarata narrative in which Vishvamitra becomes central to the boy''s post-sacrifice identity and lineage; this is a distinct Brahmana-layer tradition from the Ramayana version.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source", "Recorded source access issue", "Claim-passage link points to a source absent from claim-source links"], "evidence_type": "uncertain", "lens": {"field_id": "65d1ba35-9925-4929-bdbc-1da8142809b1", "field_label": "Authored or associated texts", "parameter_id": "a2eb1f36-a2a0-47fb-8d45-68d9db573054", "parameter_name": "Textual Contribution"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The Aitareya account continues beyond Shunahshepa''s release to his adoption into Vishvamitra''s lineage.", "link_id": "4f7693fc-b89e-4796-8663-b9476f4dcc4a", "page_or_section": "Aitareya Brahmana, Shunahshepa/Devarata narrative", "passages": [], "relationship": "supports", "source": {"author": "", "authority_metadata": {}, "citation": "Aitareya Brahmana Shunahshepa-Devarata passage", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IGNCA Digital Library, Government of India", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Aitareya Brahmana / related Indian antiquarian edition, Shunahshepa-Devarata passage", "url": "https://ignca.gov.in/Asi_data/14189.pdf"}, "source_id": "aaf4aa38-c1b0-4d20-afd0-f83df099bc2a"}], "unmatched_passage_links": [{"chunk_id": "02d02a6b-7f58-4397-8699-1a7b483c23ae", "excerpt": "li lHISilMNIJUA AMJ SL’KAHSKPA.  Rohita says: ff Bis III, I will give you u hundred cows if yon will give me one of these thy sons to be sacrificed in mv place.” The father embraced the eldest son, and said : I£ Not him,” The mother embraced the youngest, and said: \" Nor him.” Thus they agreed to give Suitalusepa the middle son. Rohita gore a hundred cow#, …", "excerpt_truncated": true, "page_or_section": "p. 97 (scan page 116)", "relationship": "context", "source": {"author": "", "publication_year": null, "publisher_or_institution": "IGNCA Digital Library, Government of India", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "title": "Ancient and mediaeval India vol.1 — repository scan copy (in.gov.ignca.14189)", "url": "https://archive.org/details/in.gov.ignca.14189"}, "source_id": "a3b83e3e-3616-4bcc-83bc-5e4ab7649109"}]}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('09980ef1-ba12-4d0a-8d99-8213b3f9c813','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "09980ef1-ba12-4d0a-8d99-8213b3f9c813", "claim_kind": "established_fact", "claim_relations": [], "claim_text": "Mahabharata Anushasana Parva 13.4 preserves a separate Vishvamitra birth and lineage explanation built around Gadhi, Satyavati, Ruchika, ritual charu, and later brahmarshi attainment.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "PARTIALLY_SUPPORTED", "epistemic_type": "TEXTUAL_ASSERTION", "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source", "Recorded source access issue"], "evidence_type": "uncertain", "lens": {"field_id": "65d1ba35-9925-4929-bdbc-1da8142809b1", "field_label": "Authored or associated texts", "parameter_id": "a2eb1f36-a2a0-47fb-8d45-68d9db573054", "parameter_name": "Textual Contribution"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "", "link_id": "af677de7-3f34-415a-a66a-698c1db13009", "page_or_section": "p. 59 (PDF page 19)", "passages": [{"chunk_id": "c5aafcbd-e8cb-4400-8a22-215f9ea5322c", "confidence": 0.95, "excerpt": "59 asks Gādhi for his daughter’s hand in marriage. Gādhi, deeming the destitute ascetic to be an unworthy groom for his daughter, demands a seemingly unattainable bride price [śulka]: ‘one thousand horses, the color of the moon’s rays, fast as the wind, but each having one black ear’ (Mbh 13.4.12abc). To the king’s surprise, however, Ṛcīka propitiates the …", "excerpt_truncated": true, "is_active": true, "link_method": "manual_exact_passage", "page_or_section": "p. 59 (PDF page 19)", "relationship": "supports", "section_title": "Page 19", "source_id": "06fec486-e5af-4c7e-95db-afbb2e237c75", "textual_layer": "Modern academic interpretation of Mahabharata"}], "relationship": "supports", "source": {"author": "Adheesh Sathaye", "authority_metadata": {}, "citation": "Sathaye, Adheesh. “How to become a Brahman.” Acta Orientalia Vilnensia 8.1 (2007): 41–67. doi:10.15388/AOV.2007.1.3751.", "original_work_identity": {"doi": "10.15388/aov.2007.1.3751", "independentWorkKey": "10.15388/aov.2007.1.3751", "sourceFamily": "journals.vu.lt/acta-orientalia-vilnensia"}, "publication_year": 2007, "publisher_or_institution": "Acta Orientalia Vilnensia / Vilnius University Press", "rights_or_access_note": "Official journal diamond open access, CC BY 4.0: https://www.journals.vu.lt/acta-orientalia-vilnensia/journalpolicy", "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "How to become a Brahman: The construction of varṇa as social place in the Mahābhārata’s legends of Viśvāmitra", "url": "https://www.journals.vu.lt/acta-orientalia-vilnensia/article/download/3751/5207"}, "source_id": "06fec486-e5af-4c7e-95db-afbb2e237c75"}, {"evidence_excerpt": "The chapter is explicitly organized as a Vishvamitra birth/genealogy account.", "link_id": "01fd9e0e-086b-4f8a-b623-7010faa684fc", "page_or_section": "13.4", "passages": [], "relationship": "supports", "source": {"author": "Vyasa (traditional attribution); BORI Critical Edition", "authority_metadata": {}, "citation": "Mahabharata BORI, Anushasana Parva, 4", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Bhandarkar Oriental Research Institute critical text / Vedapath presentation", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Mahabharata (BORI Critical Edition), Anushasana Parva, Adhyaya 4", "url": "https://vedapath.app/en/mahabharata-bori/anushasana-parva/4"}, "source_id": "452b0f98-1f3c-49f2-b276-8e0bd02c7eef"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('298bf8ce-f66f-4f2e-86e4-a83c7632cc2e','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "298bf8ce-f66f-4f2e-86e4-a83c7632cc2e", "claim_kind": "established_fact", "claim_relations": [], "claim_text": "Mahabharata Shanti Parva uses Vishvamitra as the central figure in a famine-time moral dilemma over emergency conduct and forbidden food, giving him a dharma-exemplum role distinct from the heroic epic biography.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "SYNTHETIC_INTERPRETATION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source", "Recorded source access issue"], "evidence_type": "uncertain", "lens": {"field_id": "65d1ba35-9925-4929-bdbc-1da8142809b1", "field_label": "Authored or associated texts", "parameter_id": "a2eb1f36-a2a0-47fb-8d45-68d9db573054", "parameter_name": "Textual Contribution"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Shanti Parva 12.142 frames Vishvamitra''s hunger and survival decision as a dharma crisis.", "link_id": "ec6386d7-f1b6-4c3e-aa9e-152ebc6457e5", "page_or_section": "12.142", "passages": [], "relationship": "supports", "source": {"author": "Vyasa (traditional attribution)", "authority_metadata": {}, "citation": "Mahabharata, Shanti Parva, 142", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Gita Press edition / Vedapath presentation", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Mahabharata (Gita Press edition), Shanti Parva, Adhyaya 142", "url": "https://vedapath.app/en/mahabharata-gita-press/shanti-parva/142"}, "source_id": "1265258a-bc16-44e0-8c55-55ca3104767e"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('2bc7b256-c728-4363-b090-0dea5a655bb1','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "2bc7b256-c728-4363-b090-0dea5a655bb1", "claim_kind": "established_fact", "claim_relations": [], "claim_text": "Vishvamitra is associated with two very different textual corpora in the present research set: Rigvedic hymns and the later epic narrative of the Valmiki Ramayana''s Bala Kanda.", "current_status": "approved", "epistemics": {"contract_basis": "tradition", "contract_satisfied": true, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "uncertain", "lens": {"field_id": "65d1ba35-9925-4929-bdbc-1da8142809b1", "field_label": "Authored or associated texts", "parameter_id": "a2eb1f36-a2a0-47fb-8d45-68d9db573054", "parameter_name": "Textual Contribution"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The Vedic source establishes the Mandala 3 association; the Ramayana sources preserve a separate epic biography and teaching role.", "link_id": "9023c622-0b48-492f-a159-e743a4b1c99a", "page_or_section": "Rigveda Mandala 3", "passages": [{"chunk_id": "4a6201da-d8d2-4984-83c0-9ab33f9820c5", "confidence": 0.870769230769231, "excerpt": "The Rigveda is the oldest compilation of human wisdom. This Samhita (Collection) is unique in its nature. In fact, it is not a book, but a compilation composed of several books which can be individually distinguished from each other. The present from of this Samhita clearly indicates that the collection is not a single work, but consists of older and later …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "A. Nature and Importance:", "relationship": "supports", "section_title": "A. Nature and Importance:", "source_id": "a81542bb-e361-49cb-b474-ef4919118501", "textual_layer": "Rigveda — Mandala 3"}], "relationship": "supports", "source": {"author": "Vedic Heritage Portal", "authority_metadata": {}, "citation": "Vedic Heritage Portal: Rigveda Overview (https://vedicheritage.gov.in/samhitas/rigveda/)", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IGNCA / Ministry of Culture, Government of India", "rights_or_access_note": null, "source_status": "approved", "source_type": "institutional", "storage_path": null, "title": "Vedic Heritage Portal: Rigveda Overview", "url": "https://vedicheritage.gov.in/samhitas/rigveda/"}, "source_id": "a81542bb-e361-49cb-b474-ef4919118501"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('2e71baba-394f-4d47-a2d5-0d40f2fcc588','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "2e71baba-394f-4d47-a2d5-0d40f2fcc588", "claim_kind": "established_fact", "claim_relations": [], "claim_text": "Mahabharata Adi Parva preserves a Shakuntala genealogy in which Shakuntala is identified as Vishvamitra''s daughter and later becomes the mother of Bharata.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source", "Recorded source access issue"], "evidence_type": "uncertain", "lens": {"field_id": "65d1ba35-9925-4929-bdbc-1da8142809b1", "field_label": "Authored or associated texts", "parameter_id": "a2eb1f36-a2a0-47fb-8d45-68d9db573054", "parameter_name": "Textual Contribution"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Adi Parva 1.90.30 identifies Shakuntala as the daughter of Vishvamitra in the dynastic genealogy.", "link_id": "70d2123d-c8a8-4180-b0d3-f63dd71efc16", "page_or_section": "1.90.30", "passages": [{"chunk_id": "29a70543-dcfe-48cb-9a29-3a3fed666876", "confidence": 0.862857142857143, "excerpt": "Saṃyāti, it is said, married Varāṅgī, the fair-limbed daughter of Dṛṣadvata. From her, Ahaṃpāti was born to him.  अहंपातिस्तु खलु कृतवीर्यदुहितरमुपयेमे भानुमतीं नाम । तस्यामस्य जज्ञे सार्वभौमः  Ahaṃpāti, it is said, married Bhānumatī, the daughter of Kṛtavīrya. From her, Sārvabhauma was born to him.  सार्वभौमः खलु जित्वाजहार कैकेयीं सुनन्दां नाम । तस्यामस्य …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Shlokas", "relationship": "supports", "section_title": "Shlokas", "source_id": "976f33cf-1de6-4118-b64f-c07b7a358389", "textual_layer": "Mahabharata tradition"}, {"chunk_id": "c93b8ceb-826c-4dc9-b6cc-adb66be98503", "confidence": 0.931428571428571, "excerpt": "Ādi Parva, Adhyāya 90 — Pūror Vaṃśa, Kuru-Pravara, and the Janamejaya Line (Genealogical Recitation)  Upa-parva: Anuvaṃśa (Pūru–Kuru Vaṃśānukīrtana) — Dynastic Genealogy and Legitimacy Discourse  This chapter begins with Janamejaya asking for a fuller account of his ancestors, saying that a condensed telling does not satisfy his longing for the sacred …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Adhyaya 90", "relationship": "supports", "section_title": "Adhyaya 90", "source_id": "976f33cf-1de6-4118-b64f-c07b7a358389", "textual_layer": "Mahabharata tradition"}], "relationship": "supports", "source": {"author": "Vyasa (traditional attribution); BORI Critical Edition", "authority_metadata": {}, "citation": "Mahabharata BORI, Adi Parva, 90", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Bhandarkar Oriental Research Institute critical text / Vedapath presentation", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Mahabharata (BORI Critical Edition), Adi Parva, Adhyaya 90", "url": "https://vedapath.app/en/mahabharata-bori/adi-parva/90"}, "source_id": "976f33cf-1de6-4118-b64f-c07b7a358389"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
