insert into original_claims values ('afdb795a-80bc-444d-bc3b-3d78a4db6bdf','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "afdb795a-80bc-444d-bc3b-3d78a4db6bdf", "claim_kind": "established_fact", "claim_relations": [], "claim_text": "The Arsheya Upanishad represents a much later Vedantic reception of Vishvamitra, placing his name in philosophical dialogue rather than in a Vedic hymn or epic biography.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "PARTIALLY_SUPPORTED", "epistemic_type": "SYNTHETIC_INTERPRETATION", "proposed_type": "SYNTHETIC_INTERPRETATION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "uncertain", "lens": {"field_id": "65d1ba35-9925-4929-bdbc-1da8142809b1", "field_label": "Authored or associated texts", "parameter_id": "a2eb1f36-a2a0-47fb-8d45-68d9db573054", "parameter_name": "Textual Contribution"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The Vedic Heritage Portal explicitly classifies the work as a comparatively later Vedantic Upanishad.", "link_id": "ae8ac143-3a20-4573-b2f1-a87f027594f8", "page_or_section": "Arsheya Upanishad overview", "passages": [{"chunk_id": "2d2aac38-e6ad-4b85-b8a5-5c566247b921", "confidence": 0.901666666666667, "excerpt": "Ārṣeya Upaniṣad is not considered as a principal Upaniṣad of Vedic Literature but it is recognised as a significant Upaniṣad among the ‘Vedānta-Upanis̩ads’ of comparatively later times. Later Upaniṣads were developed to propound the concepts of certain famous schools, such as Yoga, Vedānta, Śākta, Vaiṣṇava and Śaiva.  ĀrṣeyaUpaniṣad is a …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Arsheyopanishad", "relationship": "supports", "section_title": "Arsheyopanishad", "source_id": "f76efd31-3f90-4b32-b386-99e3cce78d6a", "textual_layer": "Traditional or scholarly source"}], "relationship": "supports", "source": {"author": "Traditional text", "authority_metadata": {}, "citation": "Arsheya Upanishad", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Vedic Heritage Portal / IGNCA / Ministry of Culture, Government of India", "rights_or_access_note": null, "source_status": "approved", "source_type": "institutional", "storage_path": null, "title": "Arsheya Upanishad", "url": "https://vedicheritage.gov.in/upanishads/aarsheyopanishad/"}, "source_id": "f76efd31-3f90-4b32-b386-99e3cce78d6a"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
