insert into original_claims values ('cea8864e-8964-4ac9-a820-93b23b278fac','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "cea8864e-8964-4ac9-a820-93b23b278fac", "claim_kind": "established_fact", "claim_relations": [], "claim_text": "Mahabharata Udyoga Parva contains an extended Galava-Madhavi cycle centered on Galava''s guru-dakshina obligation to Vishvamitra, adding a major disciple narrative not found in the Bala Kanda Rama cycle.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source", "Recorded source access issue"], "evidence_type": "uncertain", "lens": {"field_id": "65d1ba35-9925-4929-bdbc-1da8142809b1", "field_label": "Authored or associated texts", "parameter_id": "a2eb1f36-a2a0-47fb-8d45-68d9db573054", "parameter_name": "Textual Contribution"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The Udyoga Parva sequence 5.104 onward follows Galava''s effort to satisfy the difficult guru-dakshina.", "link_id": "0e274ae1-f6ac-4d44-b0a0-0267c49462b3", "page_or_section": "Udyoga Parva, Galavopakhyana", "passages": [], "relationship": "supports", "source": {"author": "Vyasa (traditional attribution); BORI Critical Edition", "authority_metadata": {}, "citation": "Mahabharata BORI, Udyoga Parva", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Bhandarkar Oriental Research Institute cr