insert into original_claims values ('fca7eb49-d669-44bc-b631-f22c9c04f0cf','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "fca7eb49-d669-44bc-b631-f22c9c04f0cf", "claim_kind": "established_fact", "claim_relations": [], "claim_text": "Within Bala Kanda, the Vishvamitra material is not a single episode but a sustained sequence covering his relationship with Dasharatha and Rama, Vasistha, Trishanku, Shunahshepa, Menaka/Rambha, and his final recognition.", "current_status": "approved", "epistemics": {"contract_basis": "tradition", "contract_satisfied": true, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "uncertain", "lens": {"field_id": "65d1ba35-9925-4929-bdbc-1da8142809b1", "field_label": "Authored or associated texts", "parameter_id": "a2eb1f36-a2a0-47fb-8d45-68d9db573054", "parameter_name": "Textual Contribution"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The concluding sarga explicitly closes the extended legend of Vishvamitra narrated by Shatananda.", "link_id": "ee00da7d-ec72-45ae-80e6-7bea8d55d5da", "page_or_section": "Bala Kanda 1.51-65", "passages": [{"chunk_id": "df62e567-491e-404e-9393-0f4f24f23977", "confidence": 0.843076923076923, "excerpt": "Enquiring about his father Gautama''s reuniting with his mother Ahalya,   Sage Shataananda relates the legend of Vishvamitra. Shataananda greets   Rama for his adherence to the rectitude of Vishvamitra, which Vishvamitra   gained through a series of self-important exploits, when he was a great   king at one time. Shataananda finds worth in informing the …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Book I : Bala Kanda - The Youthful Majesties\nSarga 51 in Prose", "relationship": "supports", "section_title": "Book I : Bala Kanda - The Youthful Majesties\nSarga 51 in Prose", "source_id": "7a3546e2-6126-489c-a987-5f8354045ba2", "textual_layer": "Ramayana — Bala Kanda"}, {"chunk_id": "efd46cc3-a4a3-4524-bd56-a1c0168d4ca8", "confidence": 0.843076923076923, "excerpt": "On hearing those words of that highly intellectual Vishvamitra, high refulgent sage  Shataananda spoke these words to Rama. \"Hail to thee! Oh, best one among men Rama,  your arrival is a godsend, not only to Mithila but to entire humanity, and oh, Raghava,  as an undefeatable great-sage Vishvamitra spearheads you, so shall your mission  be undefeatable, …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Book I : Bala Kanda - The Youthful Majesties\nSarga 51 in Prose", "relationship": "supports", "section_title": "Book I : Bala Kanda - The Youthful Majesties\nSarga 51 in Prose", "source_id": "7a3546e2-6126-489c-a987-5f8354045ba2", "textual_layer": "Ramayana — Bala Kanda"}], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution); English rendering by Desiraju Hanumanta Rao", "authority_metadata": {"verified_http_status": 200}, "citation": "Valmiki Ramayana, Bala Kanda 1.51, chapter-level prose rendering.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": "Publicly accessible chapter page; preserve source attribution and link.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayana — Bala Kanda, Sarga 51 (prose)", "url": "https://www.valmikiramayan.net/utf8/baala/sarga51/bala_51_prose.htm"}, "source_id": "7a3546e2-6126-489c-a987-5f8354045ba2"}, {"evidence_excerpt": "The concluding sarga explicitly closes the extended legend of Vishvamitra narrated by Shatananda.", "link_id": "5e52b05e-97da-45b1-a050-51bd083a6d8e", "page_or_section": "Bala Kanda 1.51-65", "passages": [], "relationship": "supports", "source": {"author": "Valmiki", "authority_metadata": {}, "citation": "Valmiki Ramayana, Bala Kanda, Sarga 65 (https://www.valmikiramayan.net/utf8/baala/sarga65/balasans65.htm.orig)", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Valmiki Ramayana, Bala Kanda, Sarga 65", "url": "https://www.valmikiramayan.net/utf8/baala/sarga65/balasans65.htm.orig"}, "source_id": "b1ff445c-d9d0-4f8e-a28f-f3a8053787ad"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('04c9540b-05c8-45e2-822a-2c2c5fe322d3','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "04c9540b-05c8-45e2-822a-2c2c5fe322d3", "claim_kind": "established_fact", "claim_relations": [], "claim_text": "Rigveda 3.10 has its own seer metadata rather than being safely subsumed under a blanket ''Vishvamitra authored Mandala 3'' statement: the Vedic Heritage Portal records Gathina Vishvamitra as rishi, Agni as the principal deity focus, and Ushnik as the metrical profile.", "current_status": "approved", "epistemics": {"contract_basis": "text", "contract_satisfied": true, "contract_status": "SUPPORTED", "epistemic_type": "TEXTUAL_ASSERTION", "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "uncertain", "lens": {"field_id": "c7b1c499-9c19-4106-9025-78e9e3a788aa", "field_label": "Mantras / suktas revealed, with Veda and mandala / kanda reference where known", "parameter_id": "a2eb1f36-a2a0-47fb-8d45-68d9db573054", "parameter_name": "Textual Contribution"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Vedic Heritage Portal metadata for RV 3.10 records rishi, devata, and metre at hymn level.", "link_id": "04ba053a-3de6-4841-98cf-4b53570a6fcf", "page_or_section": "Rigveda 3.10 metadata", "passages": [{"chunk_id": "1d722e1d-f047-4592-ac7e-47c4c66df1b4", "confidence": 0.74, "excerpt": "Hindi Translation by Pt. Sripada Damodara Satavalekar  English Translation by H.H. Wilson  Commentary of Sayanacharya", "excerpt_truncated": false, "is_active": true, "link_method": "single_chunk_curated_source", "page_or_section": "Links", "relationship": "sup