insert into original_claims values ('17f34059-e261-42f7-bd44-5cfc42a5d9c2','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "17f34059-e261-42f7-bd44-5cfc42a5d9c2", "claim_kind": "established_fact", "claim_relations": [], "claim_text": "The Vedic Heritage Portal attributes Rigveda Mandala 3, comprising 62 suktas and 617 mantras, to Vishvamitra and his family rather than to Vishvamitra alone.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "uncertain", "lens": {"field_id": "c7b1c499-9c19-4106-9025-78e9e3a788aa", "field_label": "Mantras / suktas revealed, with Veda and mandala / kanda reference where known", "parameter_id": "a2eb1f36-a2a0-47fb-8d45-68d9db573054", "parameter_name": "Textual Contribution"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The Mandala table lists 62 suktas and 617 mantras for Mandala 3 and names Vishvamitra and his family.", "link_id": "e2e04272-26dc-4323-aafd-d1177031f8ff", "page_or_section": "Mandala 3 overview", "passages": [{"chunk_id": "4a6201da-d8d2-4984-83c0-9ab33f9820c5", "confidence": 0.823529411764706, "excerpt": "The Rigveda is the oldest compilation of human wisdom. This Samhita (Collection) is unique in its nature. In fact, it is not a book, but a compilation composed of several books which can be individually distinguished from each other. The present from of this Samhita clearly indicates that the collection is not a single work, but consists of older and later …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "A. Nature and Importance:", "relationship": "supports", "section_title": "A. Nature and Importance:", "source_id": "a81542bb-e361-49cb-b474-ef4919118501", "textual_layer": "Rigveda — Mandala 3"}, {"chunk_id": "bd805da5-7fe7-4dc6-b84f-f4582b0f721c", "confidence": 0.855294117647059, "excerpt": "Among 1028 Suktas of the Rigveda Samhita some suktas are very popular and frequently referred by the readers of Vedas. Some of them are:  Hiranya-garbha Sukta  Dhana-anna-dana Sukta  Duhsvapna-nashna Sukta  Yama-yami-samvada Sukta  Besides, there are Suktas offered to different deities, such as, Indra, Maruta, Varuna, Usha, Surya, Bhumi, Soma, Agni etc. …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "C. Some Important Hymns:", "relationship": "supports", "section_title": "C. Some Important Hymns:", "source_id": "a81542bb-e361-49cb-b474-ef4919118501", "textual_layer": "Rigveda — Mandala 3"}], "relationship": "supports", "source": {"author": "Vedic Heritage Portal", "authority_metadata": {}, "citation": "Vedic Heritage Portal: Rigveda Overview (https://vedicheritage.gov.in/samhitas/rigveda/)", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IGNCA / Ministry of Culture, Government of India", "rights_or_access_note": null, "source_status": "approved", "source_type": "institutional", "storage_path": null, "title": "Vedic Heritage Portal: Rigveda Overview", "url": "https://vedicheritage.gov.in/samhitas/rigveda/"}, "source_id": "a81542bb-e361-49cb-b474-ef4919118501"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
