insert into original_claims values ('3fee4a02-7952-4225-89c7-41360576e194','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "3fee4a02-7952-4225-89c7-41360576e194", "claim_kind": "established_fact", "claim_relations": [], "claim_text": "In Rigveda 3.33 the human speaker identifies himself through the Kushika lineage while requesting passage from the rivers, giving the hymn a more specific social voice than a generic nature hymn.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "PARTIALLY_SUPPORTED", "epistemic_type": "TEXTUAL_ASSERTION", "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source", "Recorded source access issue", "Claim-passage link points to a source absent from claim-source links"], "evidence_type": "uncertain", "lens": {"field_id": "c7b1c499-9c19-4106-9025-78e9e3a788aa", "field_label": "Mantras / suktas revealed, with Veda and mandala / kanda reference where known", "parameter_id": "a2eb1f36-a2a0-47fb-8d45-68d9db573054", "parameter_name": "Textual Contribution"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The translation of RV 3.33 includes the speaker''s Kushika identification in the river dialogue.", "link_id": "33326c62-8f12-47d3-806c-3a28edb8520b", "page_or_section": "RV 3.33", "passages": [], "relationship": "supports", "source": {"author": "", "authority_metadata": {}, "citation": "Rigveda Mandala 3 translation edition", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IGNCA Digital Library, Government 