insert into original_claims values ('5804f39e-9960-4b0b-8891-468573ac7288','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "5804f39e-9960-4b0b-8891-468573ac7288", "claim_kind": "established_fact", "claim_relations": [], "claim_text": "Rigveda 3.53 is attributed to Gathina Vishvamitra and includes verses that explicitly mention Vishvamitra and the Kushikas.", "current_status": "approved", "epistemics": {"contract_basis": "text", "contract_satisfied": true, "contract_status": "SUPPORTED", "epistemic_type": "TEXTUAL_ASSERTION", "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source", "Claim-passage link points to a source absent from claim-source links"], "evidence_type": "uncertain", "lens": {"field_id": "c7b1c499-9c19-4106-9025-78e9e3a788aa", "field_label": "Mantras / suktas revealed, with Veda and mandala / kanda reference where known", "parameter_id": "a2eb1f36-a2a0-47fb-8d45-68d9db573054", "parameter_name": "Textual Contribution"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The rishi metadata names Gathina Vishvamitra; verses 7-13 contain Vishvamitra/Kushika references.", "link_id": "c186462f-478d-4a67-b09c-63ba28d7ffc1", "page_or_section": "RV 3.53", "passages": [{"chunk_id": "9829672a-8a69-4e30-8c1c-790ace3144f4", "confidence": 0.74, "excerpt": "Hindi Translation by Pt. Sripada Damodara Satavalekar  English Translation by H.H. Wilson  Commentary of Sayanacharya", "excerpt_truncated": false, "is_active": true, "link_method": "single_chunk_curated_source", "page_or_section": "Links", "relationship": "supports", "section_title": "Links", "source_id": "1d1d4614-230f-4895-9e80-fafa8dc85f1a", "textual_layer": "Rigveda — Mandala 3"}], "relationship": "supports", "source": {"author": "Vedic Heritage Portal", "authority_metadata": {}, "citation": "Rigveda 3.53 (https://vedicheritage.gov.in/samhitas/rigveda/shakala-samhita/rigveda-shakala-samhita-mandal-03-sukta-053/)", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IGNCA / Ministry of Culture, Government of India", "rights_or_access_note": null, "source_status": "approved", "source_type": "institutional", "storage_path": null, "title": "Rigveda 3.53", "url": "https://vedicheritage.gov.in/samhitas/rigveda/shakala-samhita/rigveda-shakala-samhita-mandal-03-sukta-053/"}, "source_id": "1d1d4614-230f-4895-9e80-fafa8dc85f1a"}], "unmatched_passage_links": [{"chunk_id": "0423b876-a9a3-496a-bd68-4f09a1f8936c", "excerpt": "महाँ ऋषिर्देवजा देवजूतोऽस्तभ्नात्सिन्धुमर्णवं नृचक्षाः । विश्वामित्रो यदवहत्सुदासमप्रियायत कुशिकेभिरिन्द्रः mahā~ ṛṣirdevajā devajūto''stabhnātsindhumarṇavaṃ nṛcakṣāḥ | viśvāmitro yadavahatsudāsamapriyāyata kuśikebhirindraḥ The mighty sage, God-born and God-incited, who looks on men, restrained the billowy river. When Visvamitra was Sudas''s escort, then …", "excerpt_truncated": true, "page_or_section": "3.53.9", "relationship": "context", "source": {"author": null, "publication_year": null, "publisher_or_institution": null, "rights_or_access_note": null, "source_status": "approved", "source_type": "primary_text", "title": "Maṇḍala 3 — 62 hymns of the Viśvāmitra family (incl. Gāyatrī) — Rigveda — Swaveda", "url": "https://www.swaveda.com/texts/rigveda/3/"}, "source_id": "681b7993-1899-497d-864c-287d302819ec"}]}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('61ee6b48-b09e-44ae-804a-0b0b237032fc','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "61ee6b48-b09e-44ae-804a-0b0b237032fc", "claim_kind": "established_fact", "claim_relations": [], "claim_text": "Rigveda 3.53.12 explicitly associates Vishvamitra''s prayer with protection of the Bharata people, a more precise textual relationship than the broad claim that the hymn merely mentions Vishvamitra.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "PARTIALLY_SUPPORTED", "epistemic_type": "TEXTUAL_ASSERTION", "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source", "Recorded source access issue", "Claim-passage link points to a source absent from claim-source links"], "evidence_type": "uncertain", "lens": {"field_id": "c7b1c499-9c19-4106-9025-78e9e3a788aa", "field_label": "Mantras / suktas revealed, with Veda and mandala / kanda reference where known", "parameter_id": "a2eb1f36-a2a0-47fb-8d45-68d9db573054", "parameter_name": "Textual Contribution"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The translation of RV 3.53.12 describes the prayer of Vishvamitra in relation to the Bharata line.", "link_id": "0c48fb06-4ea2-45dd-b197-c82042276c16", "page_or_section": "RV 3.53.12", "passages": [], "relationship": "supports", "source": {"author": "", "authority_metadata": {}, "citation": "Rigveda Mandala 3, including RV 3.53", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IGNCA Digital Library, Government of India", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Rigveda translation / study, Mandala 3 passages", "url": "https://ignca.gov.in/Asi_data/8739.pdf"}, "source_id": "25a74bde-3037-402a-b7bf-1e4f6034ccd6"}], "unmatched_passage_links": [{"chunk_id": "b544cd7e-eb36-444f-9618-4a82bab1d8fa", "excerpt": "य इमे रोदसी उभे अहमिन्द्रमतुष्टवम् । विश्वामित्रस्य रक्षति ब्रह्मेदं भारतं जनम् ya ime rodasī ubhe ahamindramatuṣṭavam | viśvāmitrasya rakṣati brahmedaṃ bhārataṃ janam Praises to Indra have I sung, sustainer of this earth and heaven. This prayer of Visvamitra keeps secure the race of Bharatas.", "excerpt_truncated": false, "page_or_section": "3.53.12", "relationship": "context", "source": {"author": null, "publication_year": null, "publisher_or_institution": null, "rights_or_access_note": null, "source_status": "approved", "source_type": "primary_text", "title": "Maṇḍala 3 — 62 hymns of the Viśvāmitra family (incl. Gāyatrī) — Rigveda — Swaveda", "url": "https://www.swaveda.com/texts/rigveda/3/"}, "source_id": "681b7993-1899-497d-864c-287d302819ec"}]}'::jsonb,'approved','system_test_bulk');
