insert into original_claims values ('8939f28a-6119-408b-86a4-5ed8dea7b6bd','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "8939f28a-6119-408b-86a4-5ed8dea7b6bd", "claim_kind": "established_fact", "claim_relations": [], "claim_text": "Rigveda 3.33 depicts a negotiated river crossing: the speaker asks the Vipash and Shutudri to lower themselves enough for wagons to pass, and the rivers answer rather than remaining passive scenery.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source", "Recorded source access issue", "Claim-passage link points to a source absent from claim-source links"], "evidence_type": "uncertain", "lens": {"field_id": "c7b1c499-9c19-4106-9025-78e9e3a788aa", "field_label": "Mantras / suktas revealed, with Veda and mandala / kanda reference where known", "parameter_id": "a2eb1f36-a2a0-47fb-8d45-68d9db573054", "parameter_name": "Textual Contribution"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Verses 9-13 preserve request-and-response language around making the rivers fordable.", "link_id": "8b173fab-2af5-407d-a5c3-e7493f840350", "page_or_section": "RV 3.33.9-13", "passages": [], "relationship": "supports", "source": {"author": "", "authority_metadata": {}, "citation": "Rigveda Mandala 3 translation edition", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IGNCA Digital Library, Government of India", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Rigveda Samhita, Volume III", "url": "https://ignca.gov.in/eBooks/RigVeda_Samhita_Vol_03.pdf"}, "source_id": "eabc9c3f-496a-4d87-acae-c67d983ccf20"}], "unmatched_passage_links": [{"chunk_id": "380060ae-d4c7-4f49-986d-4d9ecc998983", "excerpt": "अतारिषुर्भरता गव्यवः समभक्त विप्रः सुमतिं नदीनाम् । प्र पिन्वध्वमिषयन्तीः सुराधा आ वक्षणाः पृणध्वं यात शीभम् atāriṣurbharatā gavyavaḥ samabhakta vipraḥ sumatiṃ nadīnām | pra pinvadhvamiṣayantīḥ surādhā ā vakṣaṇāḥ pṛṇadhvaṃ yāta śībham The warrior host, the Bharatas, fared over the singer won the favour of the Rivers. Swell with your billows, hasting, …", "excerpt_truncated": true, "page_or_section": "3.33.12", "relationship": "context", "source": {"author": null, "publication_year": null, "publisher_or_institution": null, "rights_or_access_note": null, "source_status": "approved", "source_type": "primary_text", "title": "Maṇḍala 3 — 62 hymns of the Viśvāmitra family (incl. Gāyatrī) — Rigveda — Swaveda", "url": "https://www.swaveda.com/texts/rigveda/3/"}, "source_id": "681b7993-1899-497d-864c-287d302819ec"}, {"chunk_id": "61434d14-c023-4ffa-975a-eb121212a033", "excerpt": "यदङ्ग त्वा भरताः संतरेयुर्गव्यन्ग्राम इषित इन्द्रजूतः । अर्षादह प्रसवः सर्गतक्त आ वो वृणे सुमतिं यज्ञियानाम् yadaṅga tvā bharatāḥ saṃtareyurgavyangrāma iṣita indrajūtaḥ | arṣādaha prasavaḥ sargatakta ā vo vṛṇe sumatiṃ yajñiyānām Soon as the Bharatas have fared across thee, the warrior band, urged on and sped by Indra, Then let your streams flow on in rapid …", "excerpt_truncated": true, "page_or_section": "3.33.11", "relationship": "context", "source": {"author": null, "publication_year": null, "publisher_or_institution": null, "rights_or_access_note": null, "source_status": "approved", "source_type": "primary_text", "title": "Maṇḍala 3 — 62 hymns of the Viśvāmitra family (incl. Gāyatrī) — Rigveda — Swaveda", "url": "https://www.swaveda.com/texts/rigveda/3/"}, "source_id": "681b7993-1899-497d-864c-287d302819ec"}, {"chunk_id": "b84f798a-3c3e-4b49-914b-1e4912979554", "excerpt": "ओ षु स्वसारः कारवे शृणोत ययौ वो दूरादनसा रथेन । नि षू नमध्वं भवता सुपारा अधोअक्षाः सिन्धवः स्रोत्याभिः o ṣu svasāraḥ kārave śṛṇota yayau vo dūrādanasā rathena | ni ṣū namadhvaṃ bhavatā supārā adhoakṣāḥ sindhavaḥ srotyābhiḥ List quickly, Sisters, to the bard who cometh to you from far away with car and wagon. Bow lowly down; be easy to be traversed stay, …", "excerpt_truncated": true, "page_or_section": "3.33.9", "relationship": "context", "source": {"author": null, "publication_year": null, "publisher_or_institution": null, "rights_or_access_note": null, "source_status": "approved", "source_type": "primary_text", "title": "Maṇḍala 3 — 62 hymns of the Viśvāmitra family (incl. Gāyatrī) — Rigveda — Swaveda", "url": "https://www.swaveda.com/texts/rigveda/3/"}, "source_id": "681b7993-1899-497d-864c-287d302819ec"}, {"chunk_id": "c0fcc833-98b1-448c-91ca-37c85c5bace7", "excerpt": "आ ते कारो शृणवामा वचांसि ययाथ दूरादनसा रथेन । नि ते नंसै पीप्यानेव योषा मर्यायेव कन्या शश्वचै ते ā te kāro śṛṇavāmā vacāṃsi yayātha dūrādanasā rathena | ni te naṃsai pīpyāneva yoṣā maryāyeva kanyā śaśvacai te Yea, we will listen to thy words, O singer. With wain and car from far away thou comest. Low, like a nursing mother, will I bend me, and yield me as a …", "excerpt_truncated": true, "page_or_section": "3.33.10", "relationship": "context", "source": {"author": null, "publication_year": null, "publisher_or_institution": null, "rights_or_access_note": null, "source_status": "approved", "source_type": "primary_text", "title": "Maṇḍala 3 — 62 hymns of the Viśvāmitra family (incl. Gāyatrī) — Rigveda — Swaveda", "url": "https://www.swaveda.com/texts/rigveda/3/"}, "source_id": "681b7993-1899-497d-864c-287d302819ec"}]}'::jsonb,'approved','system_test_bulk');
