insert into original_claims values ('15f37f68-c8cb-4c40-be3b-6934e3a1a350','{"approval_origin": "imported_existing", "certainty": "medium", "claim_id": "15f37f68-c8cb-4c40-be3b-6934e3a1a350", "claim_kind": "uncertain", "claim_relations": [], "claim_text": "The selected source set does not establish Vishvamitra as founder of a later classical darshana or securely place him inside Vedanta, Samkhya, Mimamsa, or another later named philosophical school.", "current_status": "needs_review", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "SYNTHETIC_INTERPRETATION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Missing assigned epistemic classification", "Associated source is not approved", "Associated source URL missing", "Recorded source access issue"], "evidence_type": "uncertain", "lens": {"field_id": "acb0d457-4064-4750-8bfb-c76cbe313c15", "field_label": "School of thought (darshana) founded or elaborated, if any", "parameter_id": "a2eb1f36-a2a0-47fb-8d45-68d9db573054", "parameter_name": "Textual Contribution"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The framework itself says “if any” and asks for careful placement.", "link_id": "ca18bb3d-8989-4d38-beff-ba5cad044873", "page_or_section": "Rishi framework: textual contribution / philosophical position", "passages": [{"chunk_id": "f91d4d5c-060d-46fe-9d3e-b84b57aff719", "confidence": 0.99, "excerpt": "DCF Parameters to Study Rishis  Vocation and role within the Rishi tradition includes the type of rishi and the primary function as drashta, guru, darshana founder, smriti author, or ashram head.  Textual contribution includes mantras and suktas revealed with Veda and mandala references, associated texts, and any school of thought founded or elaborated.  …", "excerpt_truncated": true, "is_active": true, "link_method": "section_metadata", "page_or_section": null, "relationship": "supports", "section_title": null, "source_id": "b6ad83cb-662d-4bda-865b-cb0fa29cfee9", "textual_layer": "DCF research framework"}], "relationship": "supports", "source": {"author": "DCF / framework supplied from Dr. Sampadananda Mishra", "authority_metadata": {}, "citation": "DCF internal document: Parameters to study Rishis.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Dharma Civilization Foundation", "rights_or_access_note": "Internal test framework; no public original source link.", "source_status": "rejected", "source_type": "dcf_content", "storage_path": null, "title": "DCF — Parameters to study Rishis", "url": null}, "source_id": "b6ad83cb-662d-4bda-865b-cb0fa29cfee9"}], "unmatched_passage_links": []}'::jsonb,'needs_review','imported_existing');
insert into original_claims values ('18ae987c-c024-49b3-b452-375bfa153f75','{"approval_origin": "system_test_bulk", "certainty": "medium", "claim_id": "18ae987c-c024-49b3-b452-375bfa153f75", "claim_kind": "uncertain", "claim_relations": [], "claim_text": "Any assignment of Vishvamitra to a later philosophical school should therefore be presented as retrospective interpretation unless a specific later source is cited.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "SYNTHETIC_INTERPRETATION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "uncertain", "lens": {"field_id": "acb0d457-4064-4750-8bfb-c76cbe313c15", "field_label": "School of thought (darshana) founded or elaborated, if any", "parameter_id": "a2eb1f36-a2a0-47fb-8d45-68d9db573054", "parameter_name": "Textual Contribution"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "This is a chronological/source-method caution based on the character of the primary evidence.", "link_id": "7740826d-8eae-4b1e-9b6c-d93479044368", "page_or_section": "Methodological inference", "passages": [{"chunk_id": "4a6201da-d8d2-4984-83c0-9ab33f9820c5", "confidence": 0.85, "excerpt": "The Rigveda is the oldest compilation of human wisdom. This Samhita (Collection) is unique in its nature. In fact, it is not a book, but a compilation composed of several books which can be individually distinguished from each other. The present from of this Samhita clearly indicates that the collection is not a single work, but consists of older and later …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "A. Nature and Importance:", "relationship": "supports", "section_title": "A. Nature and Importance:", "source_id": "a81542bb-e361-49cb-b474-ef4919118501", "textual_layer": "Rigveda — Mandala 3"}], "relationship": "supports", "source": {"author": "Vedic Heritage Portal", "authority_metadata": {}, "citation": "Vedic Heritage Portal: Rigveda Overview (https://vedicheritage.gov.in/samhitas/rigveda/)", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IGNCA / Ministry of Culture, Government of India", "rights_or_access_note": null, "source_status": "approved", "source_type": "institutional", "storage_path": null, "title": "Vedic Heritage Portal: Rigveda Overview", "url": "https://vedicheritage.gov.in/samhitas/rigveda/"}, "source_id": "a81542bb-e361-49cb-b474-ef4919118501"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('28e7e129-ebd5-4953-be7d-539ec83d01b1','{"approval_origin": "system_test_bulk", "certainty": "medium", "claim_id": "28e7e129-ebd5-4953-be7d-539ec83d01b1", "claim_kind": "uncertain", "claim_relations": [], "claim_text": "Sri Aurobindo''s treatment of Vishvamitra belongs to a modern psychological-spiritual interpretation of Vedic symbolism, not to evidence for Vishvamitra''s own membership in a historical philosophical sect.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "uncertain", "lens": {"field_id": "acb0d457-4064-4750-8bfb-c76cbe313c15", "field_label": "School of thought (darshana) founded or elaborated, if any", "parameter_id": "a2eb1f36-a2a0-47fb-8d45-68d9db573054", "parameter_name": "Textual Contribution"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The Secret of the Veda explicitly rereads Vishvamitra''s hymn symbolically in terms of inner consciousness.", "link_id": "08aa68dc-2702-4e07-b8ff-7b89b71e4b36", "page_or_section": "The Secret of the Veda, ''The Seven Rivers''", "passages": [{"chunk_id": "ef24ca05-1fe2-47cc-a308-9e19c7d14740", "confidence": 0.95, "excerpt": "108 The Secret of the Veda Thus we find that both Veda and Purana use the same symbolic images; the ocean is for them the image of infinite and eternal existence. We find also that the image of the river or flowing current is used to symbolise a stream of conscious being. We find that Saraswati, one of the seven rivers, is the river of inspiration flowing …", "excerpt_truncated": true, "is_active": true, "link_method": "manual_exact_passage", "page_or_section": "Page 120", "relationship": "supports", "section_title": "Page 120", "source_id": "7efe2589-0b7e-4cee-bcc0-b71b0ba418e6", "textual_layer": "Modern spiritual interpretation"}], "relationship": "supports", "source": {"author": "Sri Aurobindo", "authority_metadata": {}, "citation": "Sri Aurobindo, The Secret of the Veda. Sri Aurobindo Ashram.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Sri Aurobindo Ashram", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_book", "storage_path": null, "title": "The Secret of the Veda", "url": "https://www.sriaurobindoashram.org/sriaurobindo/downloadpdf.php?id=30"}, "source_id": "7efe2589-0b7e-4cee-bcc0-b71b0ba418e6"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('af272d22-83df-436b-b950-839dd6947d2b','{"approval_origin": "system_test_bulk", "certainty": "medium", "claim_id": "af272d22-83df-436b-b950-839dd6947d2b", "claim_kind": "uncertain", "claim_relations": [], "claim_text": "The Shanti Parva famine episode places Vishvamitra inside an apaddharma-style debate about what conduct may be justified under extreme threat to life; its philosophical relevance is ethical and situational rather than school-based.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "UNSUPPORTED", "epistemic_type": "NORMATIVE_RELEVANCE", "proposed_type": "NORMATIVE_RELEVANCE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source", "Recorded source access issue"], "evidence_type": "uncertain", "lens": {"field_id": "acb0d457-4064-4750-8bfb-c76cbe313c15", "field_label": "School of thought (darshana) founded or elaborated, if any", "parameter_id": "a2eb1f36-a2a0-47fb-8d45-68d9db573054", "parameter_name": "Textual Contribution"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The dialogue debates survival, purity restrictions, precedent, and dharma under famine conditions.", "link_id": "b4f5b428-7f35-46d1-9c0c-cb039fc98aaa", "page_or_section": "12.142", "passages": [], "relationship": "supports", "source": {"author": "Vyasa (traditional attribution)", "authority_metadata": {}, "citation": "Mahabharata, Shanti Parva, 142", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Gita Press edition / Vedapath presentation", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Mahabharata (Gita Press edition), Shanti Parva, Adhyaya 142", "url": "https://vedapath.app/en/mahabharata-gita-press/shanti-parva/142"}, "source_id": "1265258a-bc16-44e0-8c55-55ca3104767e"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('ba6afc2a-361a-4340-9b10-57d4f44d4c22','{"approval_origin": "system_test_bulk", "certainty": "medium", "claim_id": "ba6afc2a-361a-4340-9b10-57d4f44d4c22", "claim_kind": "uncertain", "claim_relations": [], "claim_text": "Across the expanded corpus, Vishvamitra is better represented through changing textual roles—Vedic seer, Brahmana ritual figure, epic ascetic, and later philosophical interlocutor—than by forcing those layers into one classical school label.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "uncertain", "lens": {"field_id": "acb0d457-4064-4750-8bfb-c76cbe313c15", "field_label": "School of thought (darshana) founded or elaborated, if any", "parameter_id": "a2eb1f36-a2a0-47fb-8d45-68d9db573054", "parameter_name": "Textual Contribution"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The later Arsheya reception demonstrates that philosophical placement changes across textual layers.", "link_id": "17c2e66b-1b0d-4b69-9b62-caccba9eb7e0", "page_or_section": "Cross-layer methodological synthesis", "passages": [], "relationship": "supports", "source": {"author": "Traditional text", "authority_metadata": {}, "citation": "Arsheya Upanishad", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Vedic Heritage Portal / IGNCA / Ministry of Culture, Government of India", "rights_or_access_note": null, "source_status": "approved", "source_type": "institutional", "storage_path": null, "title": "Arsheya Upanishad", "url": "https://vedicheritage.gov.in/upanishads/aarsheyopanishad/"}, "source_id": "f76efd31-3f90-4b32-b386-99e3cce78d6a"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('c77ab698-f91c-4d86-8500-d69ce688b3b8','{"approval_origin": "system_test_bulk", "certainty": "medium", "claim_id": "c77ab698-f91c-4d86-8500-d69ce688b3b8", "claim_kind": "uncertain", "claim_relations": [], "claim_text": "The Aitareya Brahmana material associates Vishvamitra with ritual theology and royal-sacrificial concerns characteristic of the Brahmana layer, a different intellectual setting from later metaphysical Vedanta.", "current_status": "approved", "epistemics": {"contract_basis": "text", "contract_satisfied": true, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "uncertain", "lens": {"field_id": "acb0d457-4064-4750-8bfb-c76cbe313c15", "field_label": "School of thought (darshana) founded or elaborated, if any", "parameter_id": "a2eb1f36-a2a0-47fb-8d45-68d9db573054", "parameter_name": "Textual Contribution"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The Vedic Heritage Portal describes the Aitareya Brahmana as largely concerned with Soma sacrifice and royal consecration.", "link_id": "fef6e545-b0d2-4d24-b6bf-f5cc1642852a", "page_or_section": "Aitareya Brahmana overview", "passages": [{"chunk_id": "3e6fdfef-5922-45e7-bc56-c8468dac2c19", "confidence": 0.870769230769231, "excerpt": "Aitareya Brahmana belongs to Shakala Shakha of the Rigveda. This work is ascribed to Mahidasa Aitareya and dated variously from 1000 BCE to 500 BCE. It is divided into eight Panchikas and each of the Panchika is divided into eight adhyayas. Totally, it consist forty adhyayas.  The first six panchikas of Aitareya Brahmana dealing with Soma Sacrifice (fire …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Aitareya Brahmana", "relationship": "supports", "section_title": "Aitareya Brahmana", "source_id": "d7d8aaa4-5733-44cf-b9bf-0f494d707b99", "textual_layer": "Aitareya Brahmana tradition"}], "relationship": "supports", "source": {"author": "Mahidasa Aitareya (traditional attribution)", "authority_metadata": {}, "citation": "Aitareya Brahmana", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Vedic Heritage Portal / IGNCA / Ministry of Culture, Government of India", "rights_or_access_note": null, "source_status": "approved", "source_type": "institutional", "storage_path": null, "title": "Aitareya Brahmana", "url": "https://vedicheritage.gov.in/brahmanas/aitareya-brahmana/"}, "source_id": "d7d8aaa4-5733-44cf-b9bf-0f494d707b99"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('ce8b99d9-ffce-49a6-80bf-660e144bc5fe','{"approval_origin": "system_test_bulk", "certainty": "medium", "claim_id": "ce8b99d9-ffce-49a6-80bf-660e144bc5fe", "claim_kind": "uncertain", "claim_relations": [], "claim_text": "Bala Kanda 1.56 gives Vishvamitra a sharply stated narrative conviction that brahma-tejas surpasses kshatriya-bala after the failure of his weapons against Vasistha''s brahma-danda; this is an epic value statement, not a formal darshana affiliation.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "SYNTHETIC_INTERPRETATION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Recorded source access issue"], "evidence_type": "uncertain", "lens": {"field_id": "acb0d457-4064-4750-8bfb-c76cbe313c15", "field_label": "School of thought (darshana) founded or elaborated, if any", "parameter_id": "a2eb1f36-a2a0-47fb-8d45-68d9db573054", "parameter_name": "Textual Contribution"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Vishvamitra explicitly contrasts kshatriya power with brahma-tejas and resolves to seek brahminhood through tapas.", "link_id": "402de032-ba37-4268-af9e-e9f5fa3cc210", "page_or_section": "1.56.23-24", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur Valmiki Ramayanam Project", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same Bala Kanda chapter is linked below; compare editions before using a quotation.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayanam, Bala Kanda, Sarga 56", "url": "https://www.valmiki.iitk.ac.in/sloka?field_kanda_tid=1&field_sarga_value=56&language=dv"}, "source_id": "63e0dfbf-3f57-476e-98c0-5adc0a85599c"}, {"evidence_excerpt": "Vishvamitra explicitly contrasts kshatriya power with brahma-tejas and resolves to seek brahminhood through tapas.", "link_id": "dc0307c0-1691-4b72-a647-a47f250b8209", "page_or_section": "1.56.23-24", "passages": [{"chunk_id": "63e4bb3c-9a10-44c8-b7b6-a9049065e49b", "confidence": 0.78, "excerpt": "Vashishta nullifies Vishvamitra''s missiles just by his Brahma''s baton.   All missiles are defused when Vashishta consumed tghem. Vishvamitra   launches the highest missile, namely Brahma-missile, which too is consumed   by Vashishta, whereby the body of Vashishta becomes a Brahma missile   and starts to emit radiation. Then, upon the prayer of gods and …", "excerpt_truncated": true, "is_active": true, "link_method": "adaptive_strong", "page_or_section": "Book I : Bala Kanda - The Youthful Majesties\n Sarga 56 in Prose", "relationship": "context", "section_title": "Book I : Bala Kanda - The Youthful Majesties\n Sarga 56 in Prose", "source_id": "ffea4c95-a602-4362-b393-4dfe6fd279d0", "textual_layer": "Ramayana — Bala Kanda"}, {"chunk_id": "6a94efd0-174d-4312-89b5-661d00d6acfb", "confidence": 0.55, "excerpt": "\"Brahma''s son Vashishta defused all of those missiles just with his baton and when  all of them are thus silenced, Gaadhi''s son Vishvamitra touched off Brahma''s missile.  When Vishvamitra brandished and set up Brahma missile for launching, seeing it all  the gods keeping the Fire-god at their vanguard, godly sages, reptiles along with  gandharva-s are …", "excerpt_truncated": true, "is_active": true, "link_method": "citation_partial", "page_or_section": "Book I : Bala Kanda - The Youthful Majesties\n Sarga 56 in Prose", "relationship": "context", "section_title": "Book I : Bala Kanda - The Youthful Majesties\n Sarga 56 in Prose", "source_id": "ffea4c95-a602-4362-b393-4dfe6fd279d0", "textual_layer": "Ramayana — Bala Kanda"}], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution); English rendering by Desiraju Hanumanta Rao", "authority_metadata": {"verified_http_status": 200}, "citation": "Valmiki Ramayana, Bala Kanda 1.56, chapter-level prose rendering.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": "Publicly accessible chapter page; preserve source attribution and link.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayana — Bala Kanda, Sarga 56 (prose)", "url": "https://www.valmikiramayan.net/utf8/baala/sarga56/bala_56_prose.htm"}, "source_id": "ffea4c95-a602-4362-b393-4dfe6fd279d0"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('ddd79c96-183f-4ecb-9722-a1c3b0133f9a','{"approval_origin": "system_test_bulk", "certainty": "medium", "claim_id": "ddd79c96-183f-4ecb-9722-a1c3b0133f9a", "claim_kind": "uncertain", "claim_relations": [], "claim_text": "The primary sources used here do not identify Vishvamitra as the founder of a later classical darshana such as Vedanta, Samkhya, Yoga, Nyaya, Vaisheshika, or Mimamsa.", "current_status": "approved", "epistemics": {"contract_basis": "text", "contract_satisfied": true, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "uncertain", "lens": {"field_id": "acb0d457-4064-4750-8bfb-c76cbe313c15", "field_label": "School of thought (darshana) founded or elaborated, if any", "parameter_id": "a2eb1f36-a2a0-47fb-8d45-68d9db573054", "parameter_name": "Textual Contribution"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The Vedic material identifies rishi, devata, metre, and hymn associations, not membership in a later classical philosophical school.", "link_id": "16b97f77-809f-454a-8e25-492f6915e1a8", "page_or_section": "Source-limit statement", "passages": [{"chunk_id": "9b97ceb8-689b-43d6-a99c-34242db71f5a", "confidence": 0.842222222222222, "excerpt": "The whole of the Rigveda-Samhita is in form of verses, known as Rik.  ‘Rik’ is the name given to those Mantras which are meant for the praise of the deities. Thus the collection (Samhita) of Riks is known as Rigveda-Samhita. Only one recession or school (Shakha) of the Rigveda is available today and it is the Shaakala. The Rigveda Samhita contains about …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "B. Form and Classification :", "relationship": "supports", "section_title": "B. Form and Classification :", "source_id": "a81542bb-e361-49cb-b474-ef4919118501", "textual_layer": "Rigveda — Mandala 3"}], "relationship": "supports", "source": {"author": "Vedic Heritage Portal", "authority_metadata": {}, "citation": "Vedic Heritage Portal: Rigveda Overview (https://vedicheritage.gov.in/samhitas/rigveda/)", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IGNCA / Ministry of Culture, Government of India", "rights_or_access_note": null, "source_status": "approved", "source_type": "institutional", "storage_path": null, "title": "Vedic Heritage Portal: Rigveda Overview", "url": "https://vedicheritage.gov.in/samhitas/rigveda/"}, "source_id": "a81542bb-e361-49cb-b474-ef4919118501"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('ec01577c-6342-40f4-bf36-cd6bb4a9b0f2','{"approval_origin": "system_test_bulk", "certainty": "medium", "claim_id": "ec01577c-6342-40f4-bf36-cd6bb4a9b0f2", "claim_kind": "uncertain", "claim_relations": [], "claim_text": "The Arsheya Upanishad shows a later Vedantic reception of the name Vishvamitra: he appears among seers discussing Atman and related Vedantic ideas, but this does not demonstrate that the Rigvedic Vishvamitra historically belonged to a later Vedanta school.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "PARTIALLY_SUPPORTED", "epistemic_type": "SYNTHETIC_INTERPRETATION", "proposed_type": "SYNTHETIC_INTERPRETATION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "uncertain", "lens": {"field_id": "acb0d457-4064-4750-8bfb-c76cbe313c15", "field_label": "School of thought (darshana) founded or elaborated, if any", "parameter_id": "a2eb1f36-a2a0-47fb-8d45-68d9db573054", "parameter_name": "Textual Contribution"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The portal calls the Arsheya Upanishad a comparatively later Vedantic Upanishad and names Vishvamitra among its five seers.", "link_id": "4b09251c-e46f-40fe-9842-6f9ee71651bc", "page_or_section": "Arsheya Upanishad overview", "passages": [{"chunk_id": "2d2aac38-e6ad-4b85-b8a5-5c566247b921", "confidence": 0.939259259259259, "excerpt": "Ārṣeya Upaniṣad is not considered as a principal Upaniṣad of Vedic Literature but it is recognised as a significant Upaniṣad among the ‘Vedānta-Upanis̩ads’ of comparatively later times. Later Upaniṣads were developed to propound the concepts of certain famous schools, such as Yoga, Vedānta, Śākta, Vaiṣṇava and Śaiva.  ĀrṣeyaUpaniṣad is a …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Arsheyopanishad", "relationship": "supports", "section_title": "Arsheyopanishad", "source_id": "f76efd31-3f90-4b32-b386-99e3cce78d6a", "textual_layer": "Traditional or scholarly source"}], "relationship": "supports", "source": {"author": "Traditional text", "authority_metadata": {}, "citation": "Arsheya Upanishad", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Vedic Heritage Portal / IGNCA / Ministry of Culture, Government of India", "rights_or_access_note": null, "source_status": "approved", "source_type": "institutional", "storage_path": null, "title": "Arsheya Upanishad", "url": "https://vedicheritage.gov.in/upanishads/aarsheyopanishad/"}, "source_id": "f76efd31-3f90-4b32-b386-99e3cce78d6a"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('0d05d868-f451-4311-9b5b-8887ea9e7f80','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "0d05d868-f451-4311-9b5b-8887ea9e7f80", "claim_kind": "established_fact", "claim_relations": [], "claim_text": "At the Ganga, Vishvamitra functions as both ritual participant and teacher: after bathing and making offerings, he continues explaining the river''s sacred history to Rama.", "current_status": "approved", "epistemics": {"contract_basis": "tradition", "contract_satisfied": true, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Recorded source access issue"], "evidence_type": "uncertain", "lens": {"field_id": "cc71c2f4-ed36-406a-b0b2-470408e3226d", "field_label": "Primary function: drashta, guru, darshana-founder, smriti-author, ashram-head", "parameter_id": "0ec41561-655d-4982-b2d8-97b4a2b9fe7c", "parameter_name": "Vocation / Role within the Rishi Tradition"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The group bathes and performs offerings; Vishvamitra then narrates the Ganga tradition.", "link_id": "9ded70e5-d05f-4319-a627-31037684db4e", "page_or_section": "1.35", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur Valmiki Ramayanam Project", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same Bala Kanda chapter is linked below; compare editions before using a quotation.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayanam, Bala Kanda, Sarga 35", "url": "https://www.valmiki.iitk.ac.in/summary?field_kanda_tid=1&field_sarga_value=35"}, "source_id": "3f8184f5-2d01-45b4-a672-080c7ab608d2"}, {"evidence_excerpt": "The group bathes and performs offerings; Vishvamitra then narrates the Ganga tradition.", "link_id": "8a87d641-8925-4328-8711-6efba8e34538", "page_or_section": "1.35", "passages": [{"chunk_id": "c66709a7-d35e-4ec5-9dd5-3d0a4e99a306", "confidence": 0.878095238095238, "excerpt": "Motivated by Rama''s words the eminent-sage Vishvamitra commenced to narrate about the  emergence and that way even about the progression of River Ganga.  \"The lordly mountain Himavan who is the greatest treasure trove of minerals, Rama, also  treasures up a pair of daughters who by their comeliness are unequalled on earth. The slender-waisted  and …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Book I : Bala Kanda - The Youthful \nMajesties Sarga 35 in Prose", "relationship": "supports", "section_title": "Book I : Bala Kanda - The Youthful \nMajesties Sarga 35 in Prose", "source_id": "7ac166d3-a3f1-4e9c-a44a-32bf54c7db27", "textual_layer": "Ramayana — Bala Kanda"}, {"chunk_id": "e1e7a506-57fb-4b64-96bc-065eb978949e", "confidence": 0.946666666666667, "excerpt": "Sage Vishvamitra along with others reach the banks of River Ganga and they make their  sojourn on that riverbank. There when Rama inquisitively enquires about River Ganga Vishvamitra narrates  the legend of Ganga, as to how she is taken to heavens by gods from her father Himalayas.  On sojourning the remaining night on the bank of river Sona along with …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Book I : Bala Kanda - The Youthful \nMajesties Sarga 35 in Prose", "relationship": "supports", "section_title": "Book I : Bala Kanda - The Youthful \nMajesties Sarga 35 in Prose", "source_id": "7ac166d3-a3f1-4e9c-a44a-32bf54c7db27", "textual_layer": "Ramayana — Bala Kanda"}], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution); English rendering by Desiraju Hanumanta Rao", "authority_metadata": {"verified_http_status": 200}, "citation": "Valmiki Ramayana, Bala Kanda 1.35, chapter-level prose rendering.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": "Publicly accessible chapter page; preserve source attribution and link.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayana — Bala Kanda, Sarga 35 (prose)", "url": "https://www.valmikiramayan.net/utf8/baala/sarga35/bala_35_prose.htm"}, "source_id": "7ac166d3-a3f1-4e9c-a44a-32bf54c7db27"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('166c37a2-67ae-46fb-b62d-d6806897988f','{"approval_origin": "imported_existing", "certainty": "high", "claim_id": "166c37a2-67ae-46fb-b62d-d6806897988f", "claim_kind": "established_fact", "claim_relations": [], "claim_text": "In the Rigvedic layer, Vishvamitra and his family are associated with Mandala 3 as mantra-seers; in the Ramayana, Vishvamitra also functions as an ascetic teacher and guide to Rama.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source", "Claim-passage link points to a source absent from claim-source links"], "evidence_type": "uncertain", "lens": {"field_id": "cc71c2f4-ed36-406a-b0b2-470408e3226d", "field_label": "Primary function: drashta, guru, darshana-founder, smriti-author, ashram-head", "parameter_id": "0ec41561-655d-4982-b2d8-97b4a2b9fe7c", "parameter_name": "Vocation / Role within the Rishi Tradition"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Mandala 3 is associated with Vishvamitra and his family.", "link_id": "6626637a-2e68-4df0-9f11-dee2dd741553", "page_or_section": "Rigveda Mandala 3 overview", "passages": [], "relationship": "supports", "source": {"author": null, "authority_metadata": {}, "citation": "Vedic Heritage Portal, Rigveda, Shakala Samhita, Mandala overview.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Indira Gandhi National Centre for the Arts (IGNCA), Ministry of Culture, Government of India", "rights_or_access_note": null, "source_status": "approved", "source_type": "institutional", "storage_path": null, "title": "Vedic Heritage Portal — Rigveda Shakala Samhita", "url": "https://vedicheritage.gov.in/samhitas/rigveda/shakala-samhita/"}, "source_id": "210ff1a8-35b1-4ce1-9441-95fcc36d4247"}], "unmatched_passage_links": [{"chunk_id": "3e560af5-ea2a-4bd4-a148-1bcb4209738c", "excerpt": "62 of Viśvāmitra, to be taken up time and again by literary and popular cultural traditions in south Asia. Finally, the analysis of textual performance in the epic addresses the important question of why the Mahābhārata gained broad cultural power in early indian society. the Mahābhārata is an expansive, all-encompassing text that famously claims ‘that …", "excerpt_truncated": true, "page_or_section": "p. 62 (PDF page 22)", "relationship": "context", "source": {"author": "Adheesh Sathaye", "publication_year": 2007, "publisher_or_institution": "Acta Orientalia Vilnensia / Vilnius University Press", "rights_or_access_note": "Official journal diamond open access, CC BY 4.0: https://www.journals.vu.lt/acta-orientalia-vilnensia/journalpolicy", "source_status": "approved", "source_type": "scholarly_article", "title": "How to become a Brahman: The construction of varṇa as social place in the Mahābhārata’s legends of Viśvāmitra", "url": "https://www.journals.vu.lt/acta-orientalia-vilnensia/article/download/3751/5207"}, "source_id": "06fec486-e5af-4c7e-95db-afbb2e237c75"}, {"chunk_id": "52b5dd80-12a0-4b93-bfe3-6895f2e0d104", "excerpt": "specially sacred in that a^e.^ The region was called Brahmavarta also/ thoug-h from what time is not clear. Brahmanism thus appears to have developed in accordance with Aila ideas, and to have owed much of its advance to the influence of ksatriyas/ first, of Visvamitra and his sons, and afterwards mainly of the Bharata princes and ksatriyan brahmans It con- …", "excerpt_truncated": true, "page_or_section": "scan leaf 328", "relationship": "context", "source": {"author": "F. E. Pargiter", "publication_year": 1922, "publisher_or_institution": "Oxford University Press (London: Humphrey Milford)", "rights_or_access_note": "Rights-clear public-domain scan (archive.org item metadata: NOT_IN_COPYRIGHT; scanned by University of Toronto Robarts Library). Only pages naming Vishvamitra and relevant to approved claims were ingested.", "source_status": "approved", "source_type": "scholarly_book", "title": "Ancient Indian Historical Tradition", "url": "https://archive.org/details/ancientindianhis00parguoft"}, "source_id": "70bed1d6-b121-41fb-9ec4-650a746f154c"}, {"chunk_id": "6cf0b45c-d760-4089-8d18-77a0f2a0578e", "excerpt": "42 the beginning of the Common Era (Pollock 2006, 224–6). Equally significant is the epic’s role in the development of varṇa as a normative discourse in post-Vedic social life. What emerges in Vedic culture as a ‘totalistic classificatory system’ (see Smith 1994, 8),2 and what functions as an all-encompassing social ideology within śāstraic texts3 appears …", "excerpt_truncated": true, "page_or_section": "p. 42 (PDF page 2)", "relationship": "context", "source": {"author": "Adheesh Sathaye", "publication_year": 2007, "publisher_or_institution": "Acta Orientalia Vilnensia / Vilnius University Press", "rights_or_access_note": "Official journal diamond open access, CC BY 4.0: https://www.journals.vu.lt/acta-orientalia-vilnensia/journalpolicy", "source_status": "approved", "source_type": "scholarly_article", "title": "How to become a Brahman: The construction of varṇa as social place in the Mahābhārata’s legends of Viśvāmitra", "url": "https://www.journals.vu.lt/acta-orientalia-vilnensia/article/download/3751/5207"}, "source_id": "06fec486-e5af-4c7e-95db-afbb2e237c75"}, {"chunk_id": "97111899-c75b-4870-a47f-b050d15908e1", "excerpt": "of persons having- the same name or patronymic, so that^ to cite the most striking instances, all the Vasisthas became jumbled into one Vasistha and all the Visvamitras into one Visvamitra. Hence the mention of a person by the simple name is no sure criterion that the original j)erson of that name is intended, but often means a descendant. This must be …", "excerpt_truncated": true, "page_or_section": "scan leaf 152", "relationship": "context", "source": {"author": "F. E. Pargiter", "publication_year": 1922, "publisher_or_institution": "Oxford University Press (London: Humphrey Milford)", "rights_or_access_note": "Rights-clear public-domain scan (archive.org item metadata: NOT_IN_COPYRIGHT; scanned by University of Toronto Robarts Library). Only pages naming Vishvamitra and relevant to approved claims were ingested.", "source_status": "approved", "source_type": "scholarly_book", "title": "Ancient Indian Historical Tradition", "url": "https://archive.org/details/ancientindianhis00parguoft"}, "source_id": "70bed1d6-b121-41fb-9ec4-650a746f154c"}, {"chunk_id": "b8e61cd3-e303-4c07-a6da-f12b3ecb8e18", "excerpt": "identified with the Kasyapa who in accounts of the creation is made the progenitor of all beings, and is called the father of the gods and asuras.^ Thus the first account given that professes to be a vamsa of the Kasyapas- diverges oif into the creation. It declares that in this lineage the world had its origin, thus : Marlei begot a son, the prajiipati …", "excerpt_truncated": true, "page_or_section": "p. 189 (scan leaf 201)", "relationship": "context", "source": {"author": "F. E. Pargiter", "publication_year": 1922, "publisher_or_institution": "Oxford University Press (London: Humphrey Milford)", "rights_or_access_note": "Rights-clear public-domain scan (archive.org item metadata: NOT_IN_COPYRIGHT; scanned by University of Toronto Robarts Library). Only pages naming Vishvamitra and relevant to approved claims were ingested.", "source_status": "approved", "source_type": "scholarly_book", "title": "Ancient Indian Historical Tradition", "url": "https://archive.org/details/ancientindianhis00parguoft"}, "source_id": "70bed1d6-b121-41fb-9ec4-650a746f154c"}, {"chunk_id": "d2b36176-fe43-4f55-b29f-7d64cf1c00db", "excerpt": "the mythical Vasistha. The genealog-y consists of three distinct fc^ections, lines 1-11, 12-16 and 17-18, which seemingly start from one and the same Vasistha but really give separate disconnected pedigrees as will appear. It is not accurate, but may supplement information derived from elsewhere ; and the only safe course is to distinguish the several …", "excerpt_truncated": true, "page_or_section": "p. 205 (scan leaf 217)", "relationship": "context", "source": {"author": "F. E. Pargiter", "publication_year": 1922, "publisher_or_institution": "Oxford University Press (London: Humphrey Milford)", "rights_or_access_note": "Rights-clear public-domain scan (archive.org item metadata: NOT_IN_COPYRIGHT; scanned by University of Toronto Robarts Library). Only pages naming Vishvamitra and relevant to approved claims were ingested.", "source_status": "approved", "source_type": "scholarly_book", "title": "Ancient Indian Historical Tradition", "url": "https://archive.org/details/ancientindianhis00parguoft"}, "source_id": "70bed1d6-b121-41fb-9ec4-650a746f154c"}, {"chunk_id": "d502c78d-2777-4109-9110-428bf6f99b62", "excerpt": "Exaltation of Vedic literature has drawn historical conclusions even from its silence. It is not of historical purpose and does not deal with history (p. 2), hence its silence about historical points is of no significance, and to draw historical conclusions from its mere silence is astonishing. Two illustrations of this may be adduced. First, it is said …", "excerpt_truncated": true, "page_or_section": "scan leaf 24", "relationship": "context", "source": {"author": "F. E. Pargiter", "publication_year": 1922, "publisher_or_institution": "Oxford University Press (London: Humphrey Milford)", "rights_or_access_note": "Rights-clear public-domain scan (archive.org item metadata: NOT_IN_COPYRIGHT; scanned by University of Toronto Robarts Library). Only pages naming Vishvamitra and relevant to approved claims were ingested.", "source_status": "approved", "source_type": "scholarly_book", "title": "Ancient Indian Historical Tradition", "url": "https://archive.org/details/ancientindianhis00parguoft"}, "source_id": "70bed1d6-b121-41fb-9ec4-650a746f154c"}, {"chunk_id": "df171e1a-d43e-4980-a5f1-a3404cd7ba36", "excerpt": "66 ―――. Ahiṃsā and a Mahābhārata Story: The Development of the Story of Tulādhāra in the Mahābhārata in connection with Non-violence, Cow protection and Sacrifice, canberra: Faculty of Asian Studies, 1987. Quigley, Declan. The Interpretation of Caste, Oxford: clarendon Press, 1993. raheja, gloria goodwin. ‘india: caste, Kingship, and Dominance …", "excerpt_truncated": true, "page_or_section": "p. 66 (PDF page 26)", "relationship": "context", "source": {"author": "Adheesh Sathaye", "publication_year": 2007, "publisher_or_institution": "Acta Orientalia Vilnensia / Vilnius University Press", "rights_or_access_note": "Official journal diamond open access, CC BY 4.0: https://www.journals.vu.lt/acta-orientalia-vilnensia/journalpolicy", "source_status": "approved", "source_type": "scholarly_article", "title": "How to become a Brahman: The construction of varṇa as social place in the Mahābhārata’s legends of Viśvāmitra", "url": "https://www.journals.vu.lt/acta-orientalia-vilnensia/article/download/3751/5207"}, "source_id": "06fec486-e5af-4c7e-95db-afbb2e237c75"}, {"chunk_id": "e651e27b-1008-4f64-b9ef-623958d2b817", "excerpt": "46 Pauline Kolenda and others have explored the complexities of south Asian social formations muted within Dumont’s work (Kolenda 1976; Barnett, Fruzetti, and Östor 1976), while Arjun Appadurai has taken particular aim at Dumont’s opposition of the individualistic West to holistic India (Appadurai 1986; see also Berreman 1971). mcKim marriott, richard …", "excerpt_truncated": true, "page_or_section": "p. 46 (PDF page 6)", "relationship": "con