insert into original_claims values ('2c9cc1ed-06a5-4dc8-8aa3-b68aee84b66f','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "2c9cc1ed-06a5-4dc8-8aa3-b68aee84b66f", "claim_kind": "established_fact", "claim_relations": [], "claim_text": "Vishvamitra also functions as a narrator and guide in Bala Kanda, explaining sacred places and earlier traditions to Rama during the journey.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "uncertain", "lens": {"field_id": "cc71c2f4-ed36-406a-b0b2-470408e3226d", "field_label": "Primary function: drashta, guru, darshana-founder, smriti-author, ashram-head", "parameter_id": "0ec41561-655d-4982-b2d8-97b4a2b9fe7c", "parameter_name": "Vocation / Role within the Rishi Tradition"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "At Siddhashrama Vishvamitra explains the sacred history of the place to Rama.", "link_id": "a7391c04-48bd-462c-b23d-f500f4535d10", "page_or_section": "1.29", "passages": [{"chunk_id": "3d948c33-642e-46bf-ba1d-74c67d7a7263", "confidence": 0.8575, "excerpt": "\"That dwarf ascetic boy Vaamana begged and received a space that can   be covered in three strides, but strode all the three worlds in those   three steps for the purpose of saving worlds, as he is interested in   the welfare of all the worlds. Vishnu gave the earth back to Indra restraining   Emperor Bali with his vitality. Thus that great resplendent …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Introduction", "relationship": "supports", "section_title": "Introduction", "source_id": "588fb085-d2af-42be-9eca-bf08c63060d6", "textual_layer": "Ramayana — Bala Kanda"}, {"chunk_id": "faf89375-2fcd-47d3-b5f9-66a6fd896f4e", "confidence": 0.8575, "excerpt": "यथार्हं चक्रिरे पूजां विश्वामित्राय धीमते |  तथैव राजपुत्राभ्यामकुर्वन्नतिथिक्रियाम् || १-२९-२७  27. dhiimate vishvaamitraaya = to sagacious Vishvamitra;  yathaarham puujaam cakrire = offered reverence as deservedly;  tathaa eva = like, that; raajaputraabhyaam= for two princes;  atithikriyaam akurvan = they made [offered] guest works [reception] .  Those …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Introduction", "relationship": "supports", "section_title": "Introduction", "source_id": "588fb085-d2af-42be-9eca-bf08c63060d6", "textual_layer": "Ramayana — Bala Kanda"}], "relationship": "supports", "source": {"author": "Valmiki", "authority_metadata": {}, "citation": "Valmiki Ramayana, Bala Kanda, Sarga 29 (https://www.valmikiramayan.net/utf8/baala/sarga29/balasans29.htm)", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Valmiki Ramayana, Bala Kanda, Sarga 29", "url": "https://www.valmikiramayan.net/utf8/baala/sarga29/balasans29.htm"}, "source_id": "588fb085-d2af-42be-9eca-bf08c63060d6"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('466d347e-ea44-4c91-882b-bb13dd3324d5','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "466d347e-ea44-4c91-882b-bb13dd3324d5", "claim_kind": "established_fact", "claim_relations": [], "claim_text": "In Janaka''s court Vishvamitra acts as an intermediary with enough authority that Janaka consults him regarding the bow episode and the next steps connecting Rama with Dasharatha''s household.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Recorded source access issue", "Claim-passage link points to a source absent from claim-source links"], "evidence_type": "uncertain", "lens": {"field_id": "cc71c2f4-ed36-406a-b0b2-470408e3226d", "field_label": "Primary function: drashta, guru, darshana-founder, smriti-author, ashram-head", "parameter_id": "0ec41561-655d-4982-b2d8-97b4a2b9fe7c", "parameter_name": "Vocation / Role within the Rishi Tradition"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Bala Kanda 1.67 places Vishvamitra at the center of the bow demonstration and ensuing royal communication.", "link_id": "4aa8c475-da93-4514-9b92-e201b8ba8019", "page_or_section": "1.67", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur Valmiki Ramayanam Project", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same Bala Kanda chapter is linked below; compare editions before using a quotation.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayanam, Bala Kanda, Sarga 67", "url": "https://www.valmiki.iitk.ac.in/summary?field_kanda_tid=1&field_sarga_value=67"}, "source_id": "5d52e3f5-c52d-4373-bbe8-80416792eb49"}], "unmatched_passage_links": [{"chunk_id": "0a195f9c-6d97-42df-ac23-da8dfbf75cfe", "excerpt": "24. brahman  = oh Brahman;   kaushika  = oh Kaushika;  bhavataH anumate = by you, in consent - with your consent; mama mantriNaH = my,  ministers; tvaritaaH = hastned; speedily; rathaiH ayodhyaam shiighram  gacChantu = they go quickly to Ayodhya by chariots; te bhadram = you be safe.  Should you give consent, oh, Brahman, my ministers will be hastened to …", "excerpt_truncated": true, "page_or_section": "Introduction", "relationship": "context", "source": {"author": "Valmiki (traditional attribution)", "publication_year": null, "publisher_or_institution": "IIT Kanpur Valmiki Ramayanam Project", "rights_or_access_note": null, "source_status": "approved", "source_type": "primary_text", "title": "Valmiki Ramayanam 1.67 — sibling page (valmikiramayan.net)", "url": "https://valmikiramayan.net/utf8/baala/sarga67/balasans67.htm"}, "source_id": "00f1650f-f00c-4341-8145-ce932990549a"}]}'::jsonb,'approved','system_test_bulk');
