insert into original_claims values ('542a9313-97ff-46e7-b883-4598967332f3','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "542a9313-97ff-46e7-b883-4598967332f3", "claim_kind": "established_fact", "claim_relations": [], "claim_text": "Vishvamitra is the person who directs Rama''s attention to Janaka''s extraordinary bow and motivates the party''s journey to Mithila after the Siddhashrama sacrifice.", "current_status": "approved", "epistemics": {"contract_basis": "tradition", "contract_satisfied": true, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Recorded source access issue"], "evidence_type": "uncertain", "lens": {"field_id": "cc71c2f4-ed36-406a-b0b2-470408e3226d", "field_label": "Primary function: drashta, guru, darshana-founder, smriti-author, ashram-head", "parameter_id": "0ec41561-655d-4982-b2d8-97b4a2b9fe7c", "parameter_name": "Vocation / Role within the Rishi Tradition"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "He tells Rama of Janaka''s sacrifice at Mithila and of the remarkable bow kept there.", "link_id": "9edd2222-7ea6-4f06-adae-600763c997ca", "page_or_section": "1.31", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur Valmiki Ramayanam Project", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same Bala Kanda chapter is linked below; compare editions before using a quotation.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayanam, Bala Kanda, Sarga 31", "url": "https://www.valmiki.iitk.ac.in/summary?field_kanda_tid=1&field_sarga_value=31"}, "source_id": "6c753ad7-bf16-4884-857f-27532c924fe6"}, {"evidence_excerpt": "He tells Rama of Janaka''s sacrifice at Mithila and of the remarkable bow kept there.", "link_id": "1b1e4db0-15bc-4d3a-9a7d-23c5e861536b", "page_or_section": "1.31", "passages": [{"chunk_id": "8fde6331-f36a-429f-ab3d-e3fa23ccabbb", "confidence": 0.96, "excerpt": "\"Once Devaraata, the grandparent of the present king Janaka of Mithila, conducted a Vedic-ritual and  he indeed prayed only for this supreme bow with a best grip-handle as the fruit of that ritual from  all of the gods and oh, tigerly man Rama, he got the same from them.  For this kuurma puraaNa, padma puraNna puts it as:  priitaH ca bhagavaan iisaH …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Book I : Bala Kanda - The Youthful MajestiesSarga 31 in prose", "relationship": "supports", "section_title": "Book I : Bala Kanda - The Youthful MajestiesSarga 31 in prose", "source_id": "db7b0f86-1988-42bd-9eef-b546d4787ad7", "textual_layer": "Ramayana — Bala Kanda"}, {"chunk_id": "ce795047-e5d4-44d0-a4e1-2596082e264d", "confidence": 0.926666666666667, "excerpt": "Sage Vishwamitra travels to Mithila kingdom to attend a ritual of King Janaka and  also to see the auspicious bow of Shiva that is being worshipped in the palace of  Janaka from ages. The other sages suggest to Rama, that he too may go over there  along with them to see that marvellous bow. They all proceed from Siddha Ashram  towards River SoNa, a …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Book I : Bala Kanda - The Youthful MajestiesSarga 31 in prose", "relationship": "supports", "section_title": "Book I : Bala Kanda - The Youthful MajestiesSarga 31 in prose", "source_id": "db7b0f86-1988-42bd-9eef-b546d4787ad7", "textual_layer": "Ramayana — Bala Kanda"}], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution); English rendering by Desiraju Hanumanta Rao", "authority_metadata": {"verified_http_status": 200}, "citation": "Valmiki Ramayana, Bala Kanda 1.31, chapter-level prose rendering.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": "Publicly accessible chapter page; preserve source attribution and link.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayana — Bala Kanda, Sarga 31 (prose)", "url": "https://www.valmikiramayan.net/utf8/baala/sarga31/bala_31_prose.htm"}, "source_id": "db7b0f86-1988-42bd-9eef-b546d4787ad7"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('590244a5-7cdb-49e1-9796-65a48f25d983','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "590244a5-7cdb-49e1-9796-65a48f25d983", "claim_kind": "established_fact", "claim_relations": [], "claim_text": "In the Rigveda, Vishvamitra functions as a mantra-seer associated with hymns of the Third Mandala.", "current_status": "approved", "epistemics": {"contract_basis": "text", "contract_satisfied": true, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source", "Claim-passage link points to a source absent from claim-source links"], "evidence_type": "uncertain", "lens": {"field_id": "cc71c2f4-ed36-406a-b0b2-470408e3226d", "field_label": "Primary function: drashta, guru, darshana-founder, smriti-author, ashram-head", "parameter_id": "0ec41561-655d-4982-b2d8-97b4a2b9fe7c", "parameter_name": "Vocation / Role within the Rishi Tradition"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The Vedic Heritage Portal identifies Mandala 3 with Vishvamitra and his family.", "link_id": "6b73dfc9-5bd3-4db3-9b09-02ca15b457f9", "page_or_section": "Mandala 3 overview", "passages": [{"chunk_id": "4a6201da-d8d2-4984-83c0-9ab33f9820c5", "confidence": 0.828571428571429, "excerpt": "The Rigveda is the oldest compilation of human wisdom. This Samhita (Collection) is unique in its nature. In fact, it is not a book, but a compilation composed of several books which can be individually distinguished from each other. The present from of this Samhita clearly indicates that the collection is not a single work, but consists of older and later …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "A. Nature and Importance:", "relationship": "supports", "section_title": "A. Nature and Importance:", "source_id": "a81542bb-e361-49cb-b474-ef4919118501", "textual_layer": "Rigveda — Mandala 3"}, {"chunk_id": "9b97ceb8-689b-43d6-a99c-34242db71f5a", "confidence": 0.897142857142857, "excerpt": "The whole of the Rigveda-Samhita is in form of verses, known as Rik.  ‘Rik’ is the name given to those Mantras which are meant for the praise of the deities. Thus the collection (Samhita) of Riks is known as Rigveda-Samhita. Only one recession or school (Shakha) of the Rigveda is available today and it is the Shaakala. The Rigveda Samhita contains about …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "B. Form and Classification :", "relationship": "supports", "section_title": "B. Form and Classification :", "source_id": "a81542bb-e361-49cb-b474-ef4919118501", "textual_layer": "Rigveda — Mandala 3"}], "relationship": "supports", "source": {"author": "Vedic Heritage Portal", "authority_metadata": {}, "citation": "Vedic Heritage Portal: Rigveda Overview (https://vedicheritage.gov.in/samhitas/rigveda/)", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IGNCA / Ministry of Culture, Government of India", "rights_or_access_note": null, "source_status": "approved", "source_type": "institutional", "storage_path": null, "title": "Vedic Heritage Portal: Rigveda Overview", "url": "https://vedicheritage.gov.in/samhitas/rigveda/"}, "source_id": "a81542bb-e361-49cb-b474-ef4919118501"}], "unmatched_passage_links": [{"chunk_id": "7f33a99b-65cf-4500-9a1b-a77660ea34a7", "excerpt": "HYMNS UNDER THE BHARATAS 313 tion of the brahmans to the Ailas ; and it is probable that the Aila Visvamitra on becoming- a brahman modified the older and perhaps cruder brahmanic character and functions ; and, if so, the difference would have accentuated the hostility that Vasistha (who was a Manva brahman) showed to his brahmanhood (p. 244). The fact that …", "excerpt_truncated": true, "page_or_section": "p. 313 (scan leaf 327)", "relationship": "context", "source": {"author": "F. E. Pargiter", "publication_year": 1922, "publisher_or_institution": "Oxford University Press (London: Humphrey Milford)", "rights_or_access_note": "Rights-clear public-domain scan (archive.org item metadata: NOT_IN_COPYRIGHT; scanned by University of Toronto Robarts Library). Only pages naming Vishvamitra and relevant to approved claims were ingested.", "source_status": "approved", "source_type": "scholarly_book", "title": "Ancient Indian Historical Tradition", "url": "https://archive.org/details/ancientindianhis00parguoft"}, "source_id": "70bed1d6-b121-41fb-9ec4-650a746f154c"}]}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('929785db-3bda-44ea-805c-b111b850c6d2','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "929785db-3bda-44ea-805c-b111b850c6d2", "claim_kind": "established_fact", "claim_relations": [], "claim_text": "The Mahabharata Udyoga Parva explicitly presents Galava as Vishvamitra''s long-serving student, establishing a guru role for Vishvamitra outside the Ramayana''s Rama cycle.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "UNSUPPORTED", "epistemic_type": "TRADITIONAL_NARRATIVE", "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source", "Recorded source access issue"], "evidence_type": "uncertain", "lens": {"field_id": "cc71c2f4-ed36-406a-b0b2-470408e3226d", "field_label": "Primary function: drashta, guru, darshana-founder, smriti-author, ashram-head", "parameter_id": "0ec41561-655d-4982-b2d8-97b4a2b9fe7c", "parameter_name": "Vocation / Role within the Rishi Tradition"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Adhyaya 5.104 introduces Galava as Vishvamitra''s devoted pupil and centers their guru-dakshina relationship.", "link_id": "65d253a2-9278-4db7-a7be-ce50d382f2c4", "page_or_section": "5.104", "passages": [], "relationship": "supports", "source": {"author": "Vyasa (traditional attribution); BORI Critical Edition", "authority_metadata": {}, "citation": "Mahabharata BORI, Udyoga Parva, 104", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Bhandarkar Oriental Research Institute critic