insert into original_claims values ('c2aa3817-71a8-481d-afb1-34849456f05f','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "c2aa3817-71a8-481d-afb1-34849456f05f", "claim_kind": "established_fact", "claim_relations": [], "claim_text": "During the Siddhashrama rite Vishvamitra observes ritual silence while Rama and Lakshmana keep guard, showing him functioning as the principal ascetic-ritual participant whose vow constrains direct action during the ceremony.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "SYNTHETIC_INTERPRETATION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Recorded source access issue"], "evidence_type": "uncertain", "lens": {"field_id": "cc71c2f4-ed36-406a-b0b2-470408e3226d", "field_label": "Primary function: drashta, guru, darshana-founder, smriti-author, ashram-head", "parameter_id": "0ec41561-655d-4982-b2d8-97b4a2b9fe7c", "parameter_name": "Vocation / Role within the Rishi Tradition"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The sacrifice proceeds while Vishvamitra remains under a vow of silence and the princes guard it for six days and nights.", "link_id": "23e0dccf-4c4a-4d91-b990-4fa26ea9d244", "page_or_section": "1.30", "passages": [{"chunk_id": "a7ec8ae6-04f3-4603-acf2-bb83387319d9", "confidence": 0.842222222222222, "excerpt": "While the Vedic ritual is proceeding well towards its conclusion according to hymnal  rendering and rules of conducting the ritual, a strident and frightening blare is generated in the sky.  As to how massive clouds appear in torrential cloudburst, likewise two demons appeared enshrouding the  sky, and performing wizardry they about to swoop down towards …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Book I : Bala Kanda - The Youthful \nMajestiesSarga 30 in Prose", "relationship": "supports", "section_title": "Book I : Bala Kanda - The Youthful \nMajestiesSarga 30 in Prose", "source_id": "71a02349-8e43-4784-b671-a4c6cdbac61a", "textual_layer": "Ramayana — Bala Kanda"}, {"chunk_id": "c2264186-8ff6-4560-b37e-23f2668f17a4", "confidence": 0.924444444444444, "excerpt": "Rama and Lakshmana while safeguarding the ritual of Sage Vishvamitra for six days and  nights, on the last night demons named Maareecha and Subaahu come to hinder the ritual. Rama acts deftly  and hits out Maareecha to a long distance, but kills the other, namely Subaahu. Rama thus makes the  ritual of sage Vishvamitra a success.  The two enemy subjugators, …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Book I : Bala Kanda - The Youthful \nMajestiesSarga 30 in Prose", "relationship": "supports", "section_title": "Book I : Bala Kanda - The Youthful \nMajestiesSarga 30 in Prose", "source_id": "71a02349-8e43-4784-b671-a4c6cdbac61a", "textual_layer": "Ramayana — Bala Kanda"}], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution); English rendering by Desiraju Hanumanta Rao", "authority_metadata": {"verified_http_status": 200}, "citation": "Valmiki Ramayana, Bala Kanda 1.30, chapter-level prose rendering.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": "Publicly accessible chapter page; preserve source attribution and link.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayana — Bala Kanda, Sarga 30 (prose)", "url": "https://www.valmikiramayan.net/utf8/baala/sarga30/bala_30_prose.htm"}, "source_id": "71a02349-8e43-4784-b671-a4c6cdbac61a"}, {"evidence_excerpt": "The sacrifice proceeds while Vishvamitra remains under a vow of silence and the princes guard it for six days and nights.", "link_id": "2b55bd7f-0154-4b18-bf21-e352166c67fa", "page_or_section": "1.30", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur Valmiki Ramayanam Project", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same Bala Kanda chapter is linked below; compare editions before using a quotation.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayanam, Bala Kanda, Sarga 30", "url": "https://www.valmiki.iitk.ac.in/summary?field_kanda_tid=1&field_sarga_value=30"}, "source_id": "c006a140-843f-4e0f-bd26-d6f273aeb801"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('cdbb8fc9-a173-40f8-bcda-69052d4ecedd','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "cdbb8fc9-a173-40f8-bcda-69052d4ecedd", "claim_kind": "established_fact", "claim_relations": [], "claim_text": "At Gautama''s hermitage Vishvamitra explicitly directs Rama to enter and participate in the episode that results in Ahalya''s restoration and reunion with Gautama.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Recorded source access issue", "Claim-passage link points to a source absent from claim-source links"], "evidence_type": "uncertain", "lens": {"field_id": "cc71c2f4-ed36-406a-b0b2-470408e3226d", "field_label": "Primary function: drashta, guru, darshana-founder, smriti-author, ashram-head", "parameter_id": "0ec41561-655d-4982-b2d8-97b4a2b9fe7c", "parameter_name": "Vocation / Role within the Rishi Tradition"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Bala Kanda 1.49 places Vishvamitra as the guide who brings Rama into Gautama''s hermitage.", "link_id": "3e324eb8-018b-4982-9ac2-3442835d258f", "page_or_section": "1.49", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur Valmiki Ramayanam Project", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same Bala Kanda chapter is linked below; compare editions before using a quotation.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayanam, Bala Kanda, Sarga 49", "url": "https://www.valmiki.iitk.ac.in/summary?field_kanda_tid=1&field_sarga_value=49"}, "source_id": "acd930f8-6206-4068-8b46-c6da0ebee1c8"}], "unmatched_passage_links": [{"chunk_id": "1bec402a-35e2-4f91-8091-8a68bce7a412", "excerpt": "Oh, Raghava, owing to the efficacy of the great-souled Gautama and his ascesis,  from then onwards Indra has became one with the testes of a goat. [1-49-10]  तदागच्छ महातेज आश्रमं पुण्यकर्मणः | तारयैनां महाभागामहल्यां देवरूपिणीम् || १-४९-११  11. mahaateja = oh great-resplendent Rama; tat = therefore; puNyakarmaNaH aashramam aagacCha =  you come - enter into …", "excerpt_truncated": true, "page_or_section": "Introduction", "relationship": "context", "source": {"author": "Valmiki (traditional attribution)", "publication_year": null, "publisher_or_institution": "IIT Kanpur Valmiki Ramayanam Project", "rights_or_access_note": null, "source_status": "approved", "source_type": "primary_text", "title": "Valmiki Ramayanam 1.49 — sibling page (valmikiramayan.net)", "url": "https://valmikiramayan.net/utf8/baala/sarga49/balasans49.htm"}, "source_id": "c14e6a75-1805-4f7a-b6a7-8c79f8e2cdbc"}]}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('d1590d47-4e3e-401e-8ad7-d399d4ae7ac9','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "d1590d47-4e3e-401e-8ad7-d399d4ae7ac9", "claim_kind": "established_fact", "claim_relations": [], "claim_text": "Vasistha''s speech to Dasharatha in Bala Kanda 1.21 portrays Vishvamitra as an expert in the full range of celestial weapons and even as capable, within the epic narrative, of generating new ones.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Recorded source access issue"], "evidence_type": "uncertain", "lens": {"field_id": "cc71c2f4-ed36-406a-b0b2-470408e3226d", "field_label": "Primary function: drashta, guru, darshana-founder, smriti-author, ashram-head", "parameter_id": "0ec41561-655d-4982-b2d8-97b4a2b9fe7c", "parameter_name": "Vocation / Role within the Rishi Tradition"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Vasistha reassures Dasharatha by emphasizing Vishvamitra''s exceptional weapon knowledge and creative capacity.", "link_id": "eb7a294a-de88-444d-8971-a2d80e612a8d", "page_or_section": "1.21.11-19", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur Valmiki Ramayanam Project", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same Bala Kanda chapter is linked below; compare editions before using a quotation.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayanam, Bala Kanda, Sarga 21", "url": "https://www.valmiki.iitk.ac.in/summary?field_kanda_tid=1&field_sarga_value=21"}, "source_id": "0537c002-ff50-437a-88f6-1ca1f43572cf"}, {"evidence_excerpt": "Vasistha reassures Dasharatha by emphasizing Vishvamitra''s exceptional weapon knowledge and creative capacity.", "link_id": "98dcf243-eb23-41f4-8411-991ae4bf1b22", "page_or_section": "1.21.11-19", "passages": [{"chunk_id": "16e8b4c0-c2b9-44bb-b4df-2f3f97395940", "confidence": 0.844, "excerpt": "\"All the missiles known to Vishvamitra are the highly righteous children of Krishaasva  Prajapati, where Prajapati-s were the earliest ruler of mankind, and god Shiva gave them to Vishvamitra  when was ruling kingdom. Those missiles are the sons of Daksha Prajaapati''s daughters and her husband  Krishaasva Prajapati, and they are disparate in their form, …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Valmiki Ramayana - Bala Kanda in \nProse Sarga 21", "relationship": "supports", "section_title": "Valmiki Ramayana - Bala Kanda in \nProse Sarga 21", "source_id": "9227358e-67a7-46f5-a873-bb5582ebb893", "textual_layer": "Ramayana — Bala Kanda"}, {"chunk_id": "eb13ef00-ba13-431c-9957-e70d915433bf", "confidence": 0.9, "excerpt": "The ire of sage Vishvamitra is shown at king Dasharatha. To pacify sage Vishvamitra,  sage Vashishta intervenes and convinces king Dasharatha to send Rama with sage Vishvamitra. While doing  so, sage Vashishta enumerates the capabilities of sage Vishvamitra, his knowledge of weaponry. Vashishta  also suggests that all those weapons will be given to Rama, if …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Valmiki Ramayana - Bala Kanda in \nProse Sarga 21", "relationship": "supports", "section_title": "Valmiki Ramayana - Bala Kanda in \nProse Sarga 21", "source_id": "9227358e-67a7-46f5-a873-bb5582ebb893", "textual_layer": "Ramayana — Bala Kanda"}], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution); English rendering by Desiraju Hanumanta Rao", "authority_metadata": {"verified_http_status": 200}, "citation": "Valmiki Ramayana, Bala Kanda 1.21, chapter-level prose rendering.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": "Publicly accessible chapter page; preserve source attribution and link.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayana — Bala Kanda, Sarga 21 (prose)", "url": "https://www.valmikiramayan.net/utf8/baala/sarga21/bala_21_prose.htm"}, "source_id": "9227358e-67a7-46f5-a873-bb5582ebb893"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('d827478b-a8a8-4a86-9329-01b59c7f57c1','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "d827478b-a8a8-4a86-9329-01b59c7f57c1", "claim_kind": "established_fact", "claim_relations": [], "claim_text": "At dawn in Bala Kanda 1.23 Vishvamitra wakes Rama and Lakshmana and directs the next stage of their disciplined journey, reinforcing his day-to-day role as preceptor rather than only episodic adviser.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "PARTIALLY_SUPPORTED", "epistemic_type": "SYNTHETIC_INTERPRETATION", "proposed_type": "SYNTHETIC_INTERPRETATION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["Current approval origin does not establish strict verification", "Recorded source access issue"], "evidence_type": "uncertain", "lens": {"field_id": "cc71c2f4-ed36-406a-b0b2-470408e3226d", "field_label": "Primary function: drashta, guru, darshana-founder, smriti-author, ashram-head", "parameter_id": "0ec41561-655d-4982-b2d8-97b4a2b9fe7c", "parameter_name": "Vocation / Role within the Rishi Tradition"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The chapter opens with Vishvamitra awakening the princes before continuing the journey.", "link_id": "25f1dddd-ad66-48ce-997b-3479e1890d8b", "page_or_section": "1.23", "passages": [{"chunk_id": "71cf9f69-61e0-4126-bd04-f581eb9bc011", "confidence": 0.845, "excerpt": "There they have seen the merited hermitage of sages with contemplative souls, and who  are practising supreme ascesis for many thousand years. On seeing that merited hermitage Rama and Lakshmana  are highly pleased and said this word to that great-soul Sage Vishvamitra.  \"Whose hermitage is this merited one? Indeed who is the celebrity that lives therein?  …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Book I : Bala Kanda - The Youthful \nMajestiesSarga 23 in Prose", "relationship": "supports", "section_title": "Book I : Bala Kanda - The Youthful \nMajestiesSarga 23 in Prose", "source_id": "3e5ba864-3449-49b0-85e5-ef9e8796f620", "textual_layer": "Ramayana — Bala Kanda"}, {"chunk_id": "fcab0c80-7050-4eb3-b709-d03638794b6d", "confidence": 0.946666666666667, "excerpt": "Rama and Lakshmana proceeding with Vishvamitra sojourn in a hermitage at a place where  River Ganga and River Sarayu are confluent. Once god Shiva with his third eye burnt down the physical  entity of Manmatha, the Love-god, at this place.  At dawn after that night the great saint Vishvamitra spoke to the legatees of Kakutstha,  Rama and Lakshmana, those …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Book I : Bala Kanda - The Youthful \nMajestiesSarga 23 in Prose", "relationship": "supports", "section_title": "Book I : Bala Kanda - The Youthful \nMajestiesSarga 23 in Prose", "source_id": "3e5ba864-3449-49b0-85e5-ef9e8796f620", "textual_layer": "Ramayana — Bala Kanda"}], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution); English rendering by Desiraju Hanumanta Rao", "authority_metadata": {"verified_http_status": 200}, "citation": "Valmiki Ramayana, Bala Kanda 1.23, chapter-level prose rendering.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": "Publicly accessible chapter page; preserve source attribution and link.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayana — Bala Kanda, Sarga 23 (prose)", "url": "https://www.valmikiramayan.net/utf8/baala/sarga23/bala_23_prose.htm"}, "source_id": "3e5ba864-3449-49b0-85e5-ef9e