insert into original_claims values ('eed78f70-19a5-479c-ac79-8e4691b12fd7','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "eed78f70-19a5-479c-ac79-8e4691b12fd7", "claim_kind": "established_fact", "claim_relations": [], "claim_text": "In the Aitareya Brahmana Shunahshepa narrative Vishvamitra occupies an officiating-priest and ritual-adviser role rather than the warrior-preceptor role emphasized by Bala Kanda.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "SYNTHETIC_INTERPRETATION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source", "Recorded source access issue"], "evidence_type": "uncertain", "lens": {"field_id": "cc71c2f4-ed36-406a-b0b2-470408e3226d", "field_label": "Primary function: drashta, guru, darshana-founder, smriti-author, ashram-head", "parameter_id": "0ec41561-655d-4982-b2d8-97b4a2b9fe7c", "parameter_name": "Vocation / Role within the Rishi Tradition"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The Brahmana tradition places Vishvamitra among the ritual authorities involved in Shunahshepa''s release and later adoption.", "link_id": "3d70fb8d-cdb5-49a2-8c75-4cc826411f11", "page_or_section": "Aitareya Brahmana Shunahshepa cycle", "passages": [], "relationship": "supports", "source": {"author": "", "authority_metadata": {}, "citation": "Aitareya Brahmana Shunahshepa-Devarata passage", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IGNCA Digital Library, Government of India", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Aitareya Brahmana / related Indian antiquarian edition, Shunahshepa-Devarata passage", "url": "https://ignca.gov.in/Asi_data/14189.pdf"}, "source_id": "aaf4aa38-c1b0-4d20-afd0-f83df099bc2a"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('eef0824e-7368-4fb6-b60f-a5f417d01ef5','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "eef0824e-7368-4fb6-b60f-a5f417d01ef5", "claim_kind": "established_fact", "claim_relations": [], "claim_text": "In the Trishanku sacrifice cycle, Vishvamitra summons disciples, has sages invited, and organizes a sacrificial undertaking on behalf of a king who has sought his protection.", "current_status": "approved", "epistemics": {"contract_basis": "tradition", "contract_satisfied": true, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Recorded source access issue"], "evidence_type": "uncertain", "lens": {"field_id": "cc71c2f4-ed36-406a-b0b2-470408e3226d", "field_label": "Primary function: drashta, guru, darshana-founder, smriti-author, ashram-head", "parameter_id": "0ec41561-655d-4982-b2d8-97b4a2b9fe7c", "parameter_name": "Vocation / Role within the Rishi Tradition"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Bala Kanda 1.59 depicts Vishvamitra mobilizing disciples and other sages for Trishanku''s rite.", "link_id": "d2fab2b3-4585-42bf-bc13-957663527613", "page_or_section": "1.59", "passages": [{"chunk_id": "5326a31a-1540-4cb8-bab3-96ed76b89a7a", "confidence": 0.88, "excerpt": "\"The eminent sage Vishvamitra having heard those words of the sons of Vashishta  from all of his disciples, said this rancorously with bloodshot eyes.  \" ''He who reproves me, who am abiding in rigorous ascesis, and who am an  unreprovable one by my ascetic merit, that irreverent person will be reduced to  ashes, and there is no doubt about it. Now they will …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Book I : Bala Kanda - The Youthful Majesties\n Sarga 59 in Prose", "relationship": "supports", "section_title": "Book I : Bala Kanda - The Youthful Majesties\n Sarga 59 in Prose", "source_id": "7b637414-d012-4349-9ea0-bded3c081f08", "textual_layer": "Ramayana — Bala Kanda"}, {"chunk_id": "7fa20770-91d1-4b00-a9ae-b651c966d204", "confidence": 0.94, "excerpt": "Vishvamitra undertakes Trishanku''s Vedic ritual and sends disciples   to invite all Vedic-scholars. Many sages have come except for   Vashishta and his sons. Further, the sons of Vashishta have   ridiculed this ritual of Vishvamitra and Trishanku. Vishvamitra gets   irritated and hurls curses at the sons of Vashishta.  \"Vishvamitra, the son of Kushi, …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Book I : Bala Kanda - The Youthful Majesties\n Sarga 59 in Prose", "relationship": "supports", "section_title": "Book I : Bala Kanda - The Youthful Majesties\n Sarga 59 in Prose", "source_id": "7b637414-d012-4349-9ea0-bded3c081f08", "textual_layer": "Ramayana — Bala Kanda"}], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution); English rendering by Desiraju Hanumanta Rao", "authority_metadata": {"verified_http_status": 200}, "citation": "Valmiki Ramayana, Bala Kanda 1.59, chapter-level prose rendering.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": "Publicly accessible chapter page; preserve source attribution and link.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayana — Bala Kanda, Sarga 59 (prose)", "url": "https://www.valmikiramayan.net/utf8/baala/sarga59/bala_59_prose.htm"}, "source_id": "7b637414-d012-4349-9ea0-bded3c081f08"}, {"evidence_excerpt": "Bala Kanda 1.59 depicts Vishvamitra mobilizing disciples and other sages for Trishanku''s rite.", "link_id": "15b930dc-08e6-4f39-baad-3c1ec103ef65", "page_or_section": "1.59", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur Valmiki Ramayanam Project", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same Bala Kanda chapter is linked below; compare editions before using a quotation.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayanam, Bala Kanda, Sarga 59", "url": "https://www.valmiki.iitk.ac.in/summary?field_kanda_tid=1&field_sarga_value=59"}, "source_id": "a7c009d6-db4c-405e-b465-47bdc344f5b4"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('ef713392-697f-4e1a-854d-46c3b143d848','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "ef713392-697f-4e1a-854d-46c3b143d848", "claim_kind": "established_fact", "claim_relations": [], "claim_text": "In Bala Kanda, Vishvamitra functions as Rama''s teacher, transmitting Bala and Atibala and guiding Rama and Lakshmana during their journey.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "uncertain", "lens": {"field_id": "cc71c2f4-ed36-406a-b0b2-470408e3226d", "field_label": "Primary function: drashta, guru, darshana-founder, smriti-author, ashram-head", "parameter_id": "0ec41561-655d-4982-b2d8-97b4a2b9fe7c", "parameter_name": "Vocation / Role within the Rishi Tradition"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Vishvamitra teaches Bala and Atibala to Rama and is treated as the princes'' guru in the episode.", "link_id": "dbf2f8d3-3366-4de8-80f7-3f1c7932de8f", "page_or_section": "1.22.11-22", "passages": [{"chunk_id": "3e790a17-403e-47fd-b349-d85f9c4d92bd", "confidence": 0.893333333333333, "excerpt": "King Dasharatha sends Rama and Lakshmana along with Sage Vishvamitra as requested   by the sage. In their course of travel, Sage Vishvamitra imparts a secret knowledge   to the young princes Rama and Lakshmana, called bala-atibala-   vidya-s, by practicing which nothing can wither their vigour and vitality.  तथा वसिष्ठे ब्रुवति राजा दशरथः स्वयम् |  …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Introduction", "relationship": "supports", "section_title": "Introduction", "source_id": "4772171e-b53b-4ae5-9ffa-e6edf7a8f9de", "textual_layer": "Ramayana — Bala Kanda"}, {"chunk_id": "6e846439-227f-40f0-9421-4bab574c778b", "confidence": 0.893333333333333, "excerpt": "21b, 22. bhuurivikramaH = one with marvellous valiance; Rama;  vidyaasamuditaH = on obtaining teachings; kushikaatmaje =   in respect of Vishvamitra; sarvaaNi gurukaaryaaNi = all, teacher''s   works - works to be done in respect of teacher; niyujya = on performing;  sharadi = in autumn; sahasrarashmiH bhagavaan = thousand rayed,   god; divaakaraH iva = sun, …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Introduction", "relationship": "supports", "section_title": "Introduction", "source_id": "4772171e-b53b-4ae5-9ffa-e6edf7a8f9de", "textual_layer": "Ramayana — Bala Kanda"}], "relationship": "supports", "source": {"author": "Valmiki", "authority_metadata": {}, "citation": "Valmiki Ramayana, Bala Kanda, Sarga 22 (https://www.valmikiramayan.net/utf8/baala/sarga22/balasans22.htm)", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Valmiki Ramayana, Bala Kanda, Sarga 22", "url": "https://www.valmikiramayan.net/utf8/baala/sarga22/balasans22.htm"}, "source_id": "4772171e-b53b-4ae5-9ffa-e6edf7a8f9de"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('0c49c16d-3da1-4dce-84ca-7b2f51944b46','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "0c49c16d-3da1-4dce-84ca-7b2f51944b46", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "The Bala Kanda account culminates with Vasistha recognizing Vishvamitra as a Brahmarshi, making Brahmarshi the final status within that narrative arc.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "traditional_narrative", "lens": {"field_id": "2584faa6-0a1a-4804-8bb4-68f440c30ed6", "field_label": "Type of rishi (Brahmarishi, Maharishi, Rajarishi, Devarishi, Saptarishi, etc.)", "parameter_id": "0ec41561-655d-4982-b2d8-97b4a2b9fe7c", "parameter_name": "Vocation / Role within the Rishi Tradition"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Bala Kanda 1.65 ends Vishvamitra''s long tapas narrative with Vasistha''s recognition of his Brahmarshi status.", "link_id": "13798052-ba3b-45bb-8543-3b69ffb41dcd", "page_or_section": "1.65.26-27", "passages": [{"chunk_id": "78708c3d-c722-4223-95c2-92c74a53f606", "confidence": 0.825, "excerpt": "\" ''All the beings in the triad of the worlds are very highly perturbed at their  senses and they are as though stupefied, and when juxtaposed the sun is lustreless  before the resplendence of that great sage. [1-65-15b, 16a]  बुद्धिम् न कुरुते यावत् नाशे देव महामुनिः || १-६५-१६ तावत् प्रसादो भगवान् अग्नि रूपो महाद्युतिः |  16b, 17a. deva = oh, god; …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Introduction", "relationship": "supports", "section_title": "Introduction", "source_id": "b1ff445c-d9d0-4f8e-a28f-f3a8053787ad", "textual_layer": "Ramayana — Bala Kanda"}, {"chunk_id": "ef5de7fd-af8f-4eaa-9685-ac9b0a43aa7d", "confidence": 0.825, "excerpt": "Vishvamitra becomes Brahma-sage after a prolonged ascesis that made all the worlds  to startle. All gods request Brahma to accord the supreme Brahma-sageship on Vishvamitra  as he is cleansed of all mortal impurities, and Brahma accords that highest order  on him. Thus Sage Shataananda concludes his narration about the legend of Vishvamitra.  अथ हैमवतीम् …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Introduction", "relationship": "supports", "section_title": "Introduction", "source_id": "b1ff445c-d9d0-4f8e-a28f-f3a8053787ad", "textual_layer": "Ramayana — Bala Kanda"}], "relationship": "supports", "source": {"author": "Valmiki", "authority_metadata": {}, "citation": "Valmiki Ramayana, Bala Kanda, Sarga 65 (https://www.valmikiramayan.net/utf8/baala/sarga65/balasans65.htm.orig)", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Valmiki Ramayana, Bala Kanda, Sarga 65", "url": "https://www.valmikiramayan.net/utf8/baala/sarga65/balasans65.htm.orig"}, "source_id": "b1ff445c-d9d0-4f8e-a28f-f3a8053787ad"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('1a10ad90-85e2-4a01-8e3e-57e9b26ed54f','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "1a10ad90-85e2-4a01-8e3e-57e9b26ed54f", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "In the Bala Kanda narrative, Vishvamitra is explicitly presented first as a kingly sage (rajarshi) before the culmination of his ascetic transformation.", "current_status": "approved", "epistemics": {"contract_basis": "tradition", "contract_satisfied": true, "contract_status": "SUPPORTED", "epistemic_type": "TRADITIONAL_NARRATIVE", "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["Current approval origin does not establish strict verification"], "evidence_type": "traditional_narrative", "lens": {"field_id": "2584faa6-0a1a-4804-8bb4-68f440c30ed6", "field_label": "Type of rishi (Brahmarishi, Maharishi, Rajarishi, Devarishi, Saptarishi, etc.)", "parameter_id": "0ec41561-655d-4982-b2d8-97b4a2b9fe7c", "parameter_name": "Vocation / Role within the Rishi Tradition"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Brahma first accords Vishvamitra kingly-sage status; the passage then describes his continuing effort toward Brahmarshi status.", "link_id": "52d523bc-b6bb-408a-900e-5ccee9368f9e", "page_or_section": "Bala Kanda 1.63", "passages": [{"chunk_id": "9c862712-4d53-404e-a5bb-1c24e1296451", "confidence": 0.99, "excerpt": "On Vishvamitra''s performing severe ascesis Brahma accords the sageship   of ''Great-sage'' to him, whereas Vishvamitra''s ambition is to acquire   the sageship of a ''Brahma-sage'' Absolute-sageship. In the meanwhile,   the celestial wench Menaka arrives at that place and Vishvamitra is   enticed by her beauty and spends some years with her. Later, on realising  …", "excerpt_truncated": true, "is_active": true, "link_method": "manual_exact_passage", "page_or_section": "Book I : Bala Kanda - The Youthful Majesties\niSarga 63 n Prose", "relationship": "supports", "section_title": "Book I : Bala Kanda - The Youthful Majesties\niSarga 63 n Prose", "source_id": "d39ddd21-67b7-4c7c-bfae-ea1f99918420", "textual_layer": "Ramayana — Bala Kanda"}], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution); English rendering by Desiraju Hanumanta Rao", "authority_metadata": {"verified_http_status": 200}, "citation": "Valmiki Ramayana, Bala Kanda 1.63, chapter-level prose rendering.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": "Publicly accessible chapter page; preserve source attribution and link.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayana — Bala Kanda, Sarga 63 (prose)", "url": "https://www.valmikiramayan.net/utf8/baala/sarga63/bala_63_prose.htm"}, "source_id": "d39ddd21-67b7-4c7c-bfae-ea1f99918420"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('3fc886f6-2ffa-4869-9eb2-896060a9faec','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "3fc886f6-2ffa-4869-9eb2-896060a9faec", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "The Aitareya Brahmana''s Shunahshepa cycle presents Vishvamitra as a ritual authority who can incorporate Devarata into his own lineage, a role distinct from his epic portrayal as former king and ascetic.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source", "Recorded source access issue", "Claim-passage link points to a source absent from claim-source links"], "evidence_type": "traditional_narrative", "lens": {"field_id": "2584faa6-0a1a-4804-8bb4-68f440c30ed6", "field_label": "Type of rishi (Brahmarishi, Maharishi, Rajarishi, Devarishi, Saptarishi, etc.)", "parameter_id": "0ec41561-655d-4982-b2d8-97b4a2b9fe7c", "parameter_name": "Vocation / Role within the Rishi Tradition"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The Brahmana narrative has Shunahshepa stand beside Vishvamitra after release and then become Devarata, son of Vishvamitra.", "link_id": "58a1766c-586d-46ac-bf8d-3a9349d4fd84", "page_or_section": "Aitareya Brahmana Shunahshepa cycle", "passages": [], "relationship": "supports", "source": {"author": "", "authority_metadata": {}, "citation": "Aitareya Brahmana Shunahshepa-Devarata passage", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IGNCA Digital Library, Government of India", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Aitareya Brahmana / related Indian antiquarian edition, Shunahshepa-Devarata passage", "url": "https://ignca.gov.in/Asi_data/14189.pdf"}, "source_id": "aaf4aa38-c1b0-4d20-afd0-f83df099bc2a"}], "unmatched_passage_links": [{"chunk_id": "4bbac997-598f-47f9-8296-98c4fe95458e", "excerpt": "43 Viśvāmitra and varṇa in the Mahābhārata In a section of the Anuśāsana Parvan (Mbh 13.3–4) entitled the ‘Viśvāmitropākhyāna [The Viśvāmitra Subnarrative]’, Yudhiṣṭhira, newly victorious in the Bhārata War, poses a question to the dying Kuru patriarch Bhīṣma about Viśvāmitra, a Vedic personality quite clearly situated at the margins of epic narrative …", "excerpt_truncated": true, "page_or_section": "p. 43 (PDF page 3)", "relationship": "context", "source": {"author": "Adheesh Sathaye", "publication_year": 2007, "publisher_or_institution": "Acta Orientalia Vilnensia / Vilnius University Press", "rights_or_access_note": "Official journal diamond open access, CC BY 4.0: https://www.journals.vu.lt/acta-orientalia-vilnensia/journalpolicy", "source_status": "approved", "source_type": "scholarly_article", "title": "How to become a Brahman: The construction of varṇa as social place in the Mahābhārata’s legends of Viśvāmitra", "url": "https://www.journals.vu.lt/acta-orientalia-vilnensia/article/download/3751/5207"}, "source_id": "06fec486-e5af-4c7e-95db-afbb2e237c75"}]}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('4fbe3da5-9076-4e40-81ef-ac89ca097508','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "4fbe3da5-9076-4e40-81ef-ac89ca097508", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "A Mahabharata Shalya Parva tirtha narrative independently retells Vishvamitra as a kshatriya-born king who turns to tapas and attains brahmana status, showing that the transformation motif circulated beyond the Ramayana.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source", "Recorded source access issue"], "evidence_type": "traditional_narrative", "lens": {"field_id": "2584faa6-0a1a-4804-8bb4-68f440c30ed6", "field_label": "Type of rishi (Brahmarishi, Maharishi, Rajarishi, Devarishi, Saptarishi, etc.)", "parameter_id": "0ec41561-655d-4982-b2d8-97b4a2b9fe7c", "parameter_name": "Vocation / Role within the Rishi Tradition"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The Shalya Parva tirtha account summarizes his kingship, Vasistha conflict, tapas, and grant of brahmana status.", "link_id": "bbae9fc6-2dc8-44fc-9e0f-4a19299cedc1", "page_or_section": "Shalya Parva, Vishvamitra tirtha narrative", "passages": [], "relationship": "supports", "source": {"author": "Vyasa (traditional attribution); BORI Critical Edition", "authority_metadata": {}, "citation": "Mahabharata BORI, Shalya Parva", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Bhandarkar Oriental Research Institute critical text / Vedapath presentation", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Mahabharata (BORI Critical Edition), Shalya Parva", "url": "https://vedapath.app/en/mahabharata-bori/shalya-parva"}, "source_id": "1235fefa-2528-496e-86d5-4297dbe57f04"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('767ca43f-fbcc-46c8-ac6c-4c285ed1eedb','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "767ca43f-fbcc-46c8-ac6c-4c285ed1eedb", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "The later Arsheya Upanishad includes Vishvamitra among five rishis who participate in philosophical conversations, showing a post-Vedic reception of him as a philosophical seer.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source"], "evidence_type": "traditional_narrative", "lens": {"field_id": "2584faa6-0a1a-4804-8bb4-68f440c30ed6", "field_label": "Type of rishi (Brahmarishi, Maharishi, Rajarishi, Devarishi, Saptarishi, etc.)", "parameter_id": "0ec41561-655d-4982-b2d8-97b4a2b9fe7c", "parameter_name": "Vocation / Role within the Rishi Tradition"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The Vedic Heritage Portal describes Vishvamitra, Jamadagni, Bharadvaja, Gautama, and Vasistha as the five seers in the work.", "link_id": "a7a546f2-de3e-42cf-aacf-62dd997d7c85", "page_or_section": "Arsheya Upanishad overview", "passages": [{"chunk_id": "2d2aac38-e6ad-4b85-b8a5-5c566247b921", "confidence": 0.952, "excerpt": "Ārṣeya Upaniṣad is not considered as a principal Upaniṣad of Vedic Literature but it is recognised as a significant Upaniṣad among the ‘Vedānta-Upanis̩ads’ of comparatively later times. Later Upaniṣads were developed to propound the concepts of certain famous schools, such as Yoga, Vedānta, Śākta, Vaiṣṇava and Śaiva.  ĀrṣeyaUpaniṣad is a …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Arsheyopanishad", "relationship": "supports", "section_title": "Arsheyopanishad", "source_id": "f76efd31-3f90-4b32-b386-99e3cce78d6a", "textual_layer": "Traditional or scholarly source"}], "relationship": "supports", "source": {"author": "Traditional text", "authority_metadata": {}, "citation": "Arsheya Upanishad", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Vedic Heritage Portal / IGNCA / Ministry of Culture, Government of India", "rights_or_access_note": null, "source_status": "approved", "source_type": "institutional", "storage_path": null, "title": "Arsheya Upanishad", "url": "https://vedicheritage.gov.in/upanishads/aarsheyopanishad/"}, "source_id": "f76efd31-3f90-4b32-b386-99e3cce78d6a"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('b6948da1-9a8d-4be6-abf9-b618ccccbcd9','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "b6948da1-9a8d-4be6-abf9-b618ccccbcd9", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "Bala Kanda 1.63 presents Maharshi as an intermediate title in Vishvamitra''s progression: after a thousand-year austerity cycle the gods approach, yet the narrative continues because his goal is not complete.", "current_status": "approved", "epistemics": {"contract_basis": "tradition", "contract_satisfied": true, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Recorded source access issue"], "evidence_type": "traditional_narrative", "lens": {"field_id": "2584faa6-0a1a-4804-8bb4-68f440c30ed6", "field_label": "Type of rishi (Brahmarishi, Maharishi, Rajarishi, Devarishi, Saptarishi, etc.)", "parameter_id": "0ec41561-655d-4982-b2d8-97b4a2b9fe7c", "parameter_name": "Vocation / Role within the Rishi Tradition"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The chapter title and opening verses place the Maharshi recognition before later austerities and the Brahmarshi culmination.", "link_id": "e621ac18-6e16-4fed-9524-a249d91cb638", "page_or_section": "1.63.1-4", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana, Bala Kanda 1.63. IIT Kanpur Valmiki Ramayanam.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same Bala Kanda chapter is linked below; compare editions before using a quotation.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayanam — Bala Kanda, Sarga 63", "url": "https://www.valmiki.iitk.ac.in/sloka?field_kanda_tid=1&field_sarga_value=63&language=dv"}, "source_id": "2025af50-f65e-4a13-b670-adc6a2a0e3dc"}, {"evidence_excerpt": "The chapter title and opening verses place the Maharshi recognition before later austerities and the Brahmarshi culmination.", "link_id": "b5047a96-8511-483a-9c29-674f1bc62114", "page_or_section": "1.63.1-4", "passages": [{"chunk_id": "1c601c57-75d6-404c-868e-11361f2be7ee", "confidence": 0.868571428571429, "excerpt": "\" ''All this is the mischief of gods to defraud me of the great merit of my ascesis.  Ten years have rolled by as if they are just a day and a night. Furthermore, I who  am under the influence of lust and lure had to encounter this hindrance in my ascesis.''  Oh, Rama, that best saint suspired heavily when he became emotional with reparation.  But on seeing …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Book I : Bala Kanda - The Youthful Majesties\niSarga 63 n Prose", "relationship": "supports", "section_title": "Book I : Bala Kanda - The Youthful Majesties\niSarga 63 n Prose", "source_id": "d39ddd21-67b7-4c7c-bfae-ea1f99918420", "textual_layer": "Ramayana — Bala Kanda"}, {"chunk_id": "9c862712-4d53-404e-a5bb-1c24e1296451", "confidence": 0.922857142857143, "excerpt": "On Vishvamitra''s performing severe ascesis Brahma accords the sageship   of ''Great-sage'' to him, whereas Vishvamitra''s ambition is to acquire   the sageship of a ''Brahma-sage'' Absolute-sageship. In the meanwhile,   the celestial wench Menaka arrives at that place and Vishvamitra is   enticed by her beauty and spends some years with her. Later, on realising  …", "excerpt_truncated": true, "is_active": true, "link_method": "curated_source_token_overlap", "page_or_section": "Book I : Bala Kanda - The Youthful Majesties\niSarga 63 n Prose", "relationship": "supports", "section_title": "Book I : Bala Kanda - The Youthful Majesties\niSarga 63 n Prose", "source_id": "d39ddd21-67b7-4c7c-bfae-ea1f99918420", "textual_layer": "Ramayana — Bala Kanda"}], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution); English rendering by Desiraju Hanumanta Rao", "authority_metadata": {"verified_http_status": 200}, "citation": "Valmiki Ramayana, Bala Kanda 1.63, chapter-level prose rendering.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Valmiki Ramayana project", "rights_or_access_note": "Publicly accessible chapter page; preserve source attribution and link.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayana — Bala Kanda, Sarga 63 (prose)", "url": "https://www.valmikiramayan.net/utf8/baala/sarga63/bala_63_prose.htm"}, "source_id": "d39ddd21-67b7-4c7c-bfae-ea1f99918420"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('c0e8ed43-1bfd-4bb2-81b7-492f6500fb4e','{"approval_origin": "imported_existing", "certainty": "high", "claim_id": "c0e8ed43-1bfd-4bb2-81b7-492f6500fb4e", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "In the Valmiki Ramayana tradition, Vishvamitra passes through royal and ascetic statuses and is ultimately recognized as a Brahmarshi. This is a textual/traditional classification rather than a modern historical credential.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Recorded source access issue"], "evidence_type": "traditional_narrative", "lens": {"field_id": "2584faa6-0a1a-4804-8bb4-68f440c30ed6", "field_label": "Type of rishi (Brahmarishi, Maharishi, Rajarishi, Devarishi, Saptarishi, etc.)", "parameter_id": "0ec41561-655d-4982-b2d8-97b4a2b9fe7c", "parameter_name": "Vocation / Role within the Rishi Tradition"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "", "link_id": "84f67dc3-4374-4aa4-9abc-d4386ca14929", "page_or_section": "p. 51 (PDF page 11)", "passages": [{"chunk_id": "0e7accd9-6836-4438-852c-e1f2101925d5", "confidence": 0.95, "excerpt": "51 by the Brahman, Viśvāmitra becomes disenchanted with his Kṣatriya status and decides to become a Brahman himself. Divine forces urge him to stop, declaring that such a feat is impossible, but nonetheless, Viśvāmitra eventually succeeds in gaining Brahmanhood through a great amount of tapas.39 the cultural power of the kāmadhenu legend lies in how it …", "excerpt_truncated": true, "is_active": true, "link_method": "manual_exact_passage", "page_or_section": "p. 51 (PDF page 11)", "relationship": "supports", "section_title": "Page 11", "source_id": "06fec486-e5af-4c7e-95db-afbb2e237c75", "textual_layer": "Modern academic interpretation of Mahabharata"}], "relationship": "supports", "source": {"author": "Adheesh Sathaye", "authority_metadata": {}, "citation": "Sathaye, Adheesh. “How to become a Brahman.” Acta Orientalia Vilnensia 8.1 (2007): 41–67. doi:10.15388/AOV.2007.1.3751.", "original_work_identity": {"doi": "10.15388/aov.2007.1.3751", "independentWorkKey": "10.15388/aov.2007.1.3751", "sourceFamily": "journals.vu.lt/acta-orientalia-vilnensia"}, "publication_year": 2007, "publisher_or_institution": "Acta Orientalia Vilnensia / Vilnius University Press", "rights_or_access_note": "Official journal diamond open access, CC BY 4.0: https://www.journals.vu.lt/acta-orientalia-vilnensia/journalpolicy", "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "How to become a Brahman: The construction of varṇa as social place in the Mahābhārata’s legends of Viśvāmitra", "url": "https://www.journals.vu.lt/acta-orientalia-vilnensia/article/download/3751/5207"}, "source_id": "06fec486-e5af-4c7e-95db-afbb2e237c75"}, {"evidence_excerpt": "Vasistha acknowledges Vishvamitra as Brahmarshi.", "link_id": "00d8903e-553e-49b9-8490-93506cadaa9a", "page_or_section": "Bala Kanda 1.65", "passages": [], "relationship": "supports", "source": {"author": "Valmiki (traditional attribution)", "authority_metadata": {}, "citation": "Valmiki Ramayana, Bala Kanda 1.65. IIT Kanpur Valmiki Ramayanam.", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IIT Kanpur", "rights_or_access_note": "The original IITK link has a TLS certificate mismatch. A readable parallel translation of the same Bala Kanda chapter is linked below; compare editions before using a quotation.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Valmiki Ramayanam — Bala Kanda, Sarga 65", "url": "https://www.valmiki.iitk.ac.in/sloka?field_kanda_tid=1&field_sarga_value=65&language=dv"}, "source_id": "ba6fee9f-7a6a-413e-80f0-045ce4c2ffea"}], "unmatched_passage_links": []}'::jsonb,'approved','imported_existing');
insert into original_claims values ('db9d6367-4138-4694-89ec-59e98d64bad1','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "db9d6367-4138-4694-89ec-59e98d64bad1", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "Later ritual literature recognizes a Vishvamitra gotra as a priestly lineage category, indicating that ''Vishvamitra'' functions not only as an individual sage-name but also as a continuing ritual lineage designation.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source", "Recorded source access issue"], "evidence_type": "traditional_narrative", "lens": {"field_id": "2584faa6-0a1a-4804-8bb4-68f440c30ed6", "field_label": "Type of rishi (Brahmarishi, Maharishi, Rajarishi, Devarishi, Saptarishi, etc.)", "parameter_id": "0ec41561-655d-4982-b2d8-97b4a2b9fe7c", "parameter_name": "Vocation / Role within the Rishi Tradition"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The Baudhayana Srauta Sutra includes Vishvamitra gotra among lineages relevant to priestly selection.", "link_id": "26aeb620-3b22-449e-81d0-44b2ad1aaa0c", "page_or_section": "Baudhayana Srauta Sutra, priestly lineage prescription", "passages": [], "relationship": "supports", "source": {"author": "Baudhayana (traditional attribution)", "authority_metadata": {}, "citation": "Baudhayana Srauta Sutra", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "IGNCA Digital Library, Government of India", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "The Baudhayana Srauta-Sutra, Volume I", "url": "https://ignca.gov.in/eBooks/The_Baudhayana_Srauta-Sutra_Vol_I.pdf"}, "source_id": "b0c58dba-0bf4-4ea8-9be7-2c7f4d18cc1a"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('e1f57be6-631b-4ca2-aa84-77cb7f57c162','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "e1f57be6-631b-4ca2-aa84-77cb7f57c162", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "In the Mahabharata Udyoga Parva Galava cycle, Dharma tests Vishvamitra in the guise of Vasistha and the episode ends by affirming Vishvamitra''s brahmana status before the guru-dakshina story begins.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "UNSUPPORTED", "epistemic_type": "TRADITIONAL_NARRATIVE", "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "auto_assigned"}, "evidence_flags": ["No active supporting passage linked to an approved source", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source", "Recorded source access issue"], "evidence_type": "traditional_narrative", "lens": {"field_id": "2584faa6-0a1a-4804-8bb4-68f440c30ed6", "field_label": "Type of rishi (Brahmarishi, Maharishi, Rajarishi, Devarishi, Saptarishi, etc.)", "parameter_id": "0ec41561-655d-4982-b2d8-97b4a2b9fe7c", "parameter_name": "Vocation / Role within the Rishi Tradition"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Udyoga Parva 5.104 frames the hospitality trial as part of confirming Vishvamitra''s achieved brahmana standing.", "link_id": "d426cc8b-2a04-447c-b675-d50b7d67b7f1", "page_or_section": "5.104", "passages": [], "relationship": "supports", "source": {"author": "Vyasa (traditional attribution); BORI Critical Edition", "authority_metadata": {}, "citation": "Mahabharata BORI, Udyoga Parva, 104", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Bhandarkar Oriental Research Institute critical text / Vedapath presentation", "rights_or_access_note": null, "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Mahabharata (BORI Critical Edition), Udyoga Parva, Adhyaya 104", "url": "https://vedapath.app/en/mahabharata-bori/udyoga-parva/104"}, "source_id": "855f8c75-16cc-4e96-9ba3-d79579231842"}], "unmatched_passage_links": []}'::jsonb,'approved','system_test_bulk');
insert into original_claims values ('f37fc520-e58f-49da-bc2b-d1e12accfc1c','{"approval_origin": "system_test_bulk", "certainty": "high", "claim_id": "f37fc520-e58f-49da-bc2b-d1e12accfc1c", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "Mahabharata Anushasana Parva preserves an alternate explanatory tradition for Vishvamitra''s brahmarshi status, combining a birth-line ritual narrative with his later tapas and realization.", "current_status": "approved", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification", "Current approval origin does not establish strict verification", "Retention/access rights note missing for an associated source", "Recorded source access issue"], "evidence_type": "traditional_narrative", "lens": {"field_id": "2584faa6-0a1a-4804-8bb4-68f440c30ed6", "field_label": "Type of rishi (Brahmarishi, Maharishi, Rajarishi, Devarishi, Saptarishi, etc.)", "parameter_id": "0ec41561-655d-4982-b2d8-97b4a2b9fe7c", "parameter_name": "Vocation / Role within the Rishi Tradition"}, "parent_claim_id": null, "personality_id": "2853f4ed-98b1-4ef8-9f30-30f85d42edad", "personality_name": "Vishvamitra", "reviewer_decision": null, "sources": [{"evidence_excerpt": "", "link_id": "ab585d7b-6882-43dd-9da0-d0e8bca49cf5", "page_or_section": "p. 59 (PDF page 19)", "passages": [{"chunk_id": "c5aafcbd-e8cb-4400-8a22-215f9ea5322c", "confidence": 0.95, "excerpt": "59 asks Gādhi for his daughter’s hand in marriage. Gādhi, deeming the destitute ascetic to be an unworthy groom for his daughter, demands a seemingly unattainable bride price [śulka]: ‘one thousand horses, the color of the moon’s rays, fast as the wind, but each having one black ear’ (Mbh 13.4.12abc). To the king’s surprise, however, Ṛcīka propitiates the …", "excerpt_truncated": true, "is_active": true, "link_method": "manual_exact_passage", "page_or_section": "p. 59 (PDF page 19)", "relationship": "supports", "section_title": "Page 19", "source_id": "06fec486-e5af-4c7e-95db-afbb2e237c75", "textual_layer": "Modern academic interpretation of Mahabharata"}], "relationship": "supports", "source": {"author": "Adheesh Sathaye", "authority_metadata": {}, "citation": "Sathaye, Adheesh. “How to become a Brahman.” Acta Orientalia Vilnensia 8.1 (2007): 41–67. doi:10.15388/AOV.2007.1.3751.", "original_work_identity": {"doi": "10.15388/aov.2007.1.3751", "independentWorkKey": "10.15388/aov.2007.1.3751", "sourceFamily": "journals.vu.lt/acta-orientalia-vilnensia"}, "publication_year": 2007, "publisher_or_institution": "Acta Orientalia Vilnensia / Vilnius University Press", "rights_or_access_note": "Official journal diamond open access, CC BY 4.0: https://www.journals.vu.lt/acta-orientalia-vilnensia/journalpolicy", "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "How to become a Brahman: The construction of varṇa as social place in the Mahābhārata’s legends of Viśvāmitra", "url": "https://www.journals.vu.lt/acta-orientalia-vilnensia/article/download/3751/5207"}, "source_id": "06fec486-e5af-4c7e-95db-afbb2e237c75"}, {"evidence_excerpt": "Adhyaya 13.4 explicitly closes its genealogy by reaffirming Vishvamitra''s later brahmarshi attainment.", "link_id": "c611505c-4ffb-48b7-8f62-eb101e09c720", "page_or_section": "13.4", "passages": [], "relationship": "supports", "source": {"author": "Vyasa (traditional attribution); BORI Critical Edition", "authority_metadata": {}, "citation": "Mahabharata BORI, Anushasana Parva, 4", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Bhandarkar Oriental Research Institute critical text / Vedapath presentation", "rights_or_access_note": null, "source_status": "approved", "source_type": "s