insert into original_claims values ('4d0138bc-475e-41ed-95d2-2c14efa49c3c','{"approval_origin": "ai_candidate", "certainty": "high", "claim_id": "4d0138bc-475e-41ed-95d2-2c14efa49c3c", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "The debate closes in Brihadaranyaka 3.9.26 when Yajnavalkya demands that Shakalya identify \"the Person taught in the Upanishads\" on pain of his head falling off; Shakalya cannot, and the text says his head fell off and robbers carried away his bones. This is the narrative’s own claim, not a historical report.", "current_status": "draft", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification"], "evidence_type": "direct_primary_text", "lens": {"field_id": "deacfced-f020-44ef-94cd-27ff0c484505", "field_label": "Episodes commonly sensationalized or misread out of context", "parameter_id": "e9e12cd4-53da-4743-8917-a2868006ced2", "parameter_name": "Contested or Uncertain Aspects"}, "parent_claim_id": null, "personality_id": "6ef206bf-1446-4e3d-94a6-e583f7736e62", "personality_name": "Yajnavalkya", "reviewer_decision": null, "sources": [{"evidence_excerpt": "He who plucks apart and puts together these persons and passes beyond them—that is the Person taught in the Upanishads about whom I ask you. If him to me ye will not tell, Your head indeed will then fall off.’ But him Śākalya did not know, And so indeed his head fell off. Indeed, robbers carried off his bones, thinking they were something else.", "link_id": "c8c7ab90-235a-40eb-8cd0-7a1f1de6a2cc", "page_or_section": "BAU 3.9.26", "passages": [{"chunk_id": "80077056-7c77-4284-bd80-4fb81164e91d", "confidence": null, "excerpt": "He who plucks apart and puts together these persons and passes beyond them—that is the Person taught in the Upanishads about whom I ask you. If him to me ye will not tell, Your head indeed will then fall off.’ But him Śākalya did not know, And so indeed his head fell off. Indeed, robbers carried off his bones, thinking they were something else.", "excerpt_truncated": false, "is_active": true, "link_method": null, "page_or_section": "BAU 3.9.26", "relationship": "supports", "section_title": "Yajnavalkya: The debate closes in Brihadaranyaka 3.9.26 when Yajnavalkya demands that Shakalya identify \"the Person taught in the Upanishads\" on pain of his head falling off; Shakalya cannot, and the text says his head fell off and robbers carried away his bones. This is the narrative’s own claim, not a historical report.", "source_id": "5d0a41a4-b79b-4182-b6ee-afa099f453da", "textual_layer": "Early Upanishad: Brihadaranyaka (Kanva recension), in translation"}], "relationship": "supports", "source": {"author": "Robert Ernest Hume (translator)", "authority_metadata": {"verified_at": "2026-10-12"}, "citation": "Robert Ernest Hume (translator). Brihad-Aranyaka Upanishad, in The Thirteen Principal Upanishads. Oxford University Press; Online Library of Liberty edition. https://oll-resources.s3.us-east-2.amazonaws.com/oll3/store/titles/2058/Hume_1395_EBk_v6.0.pdf", "original_work_identity": {}, "publication_year": 1921, "publisher_or_institution": "Oxford University Press; Online Library of Liberty edition", "rights_or_access_note": "Public-domain 1921 Oxford translation; the e-book text layer prints \"?\" for some under-dotted Sanskrit letters.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Brihad-Aranyaka Upanishad, in The Thirteen Principal Upanishads", "url": "https://oll-resources.s3.us-east-2.amazonaws.com/oll3/store/titles/2058/Hume_1395_EBk_v6.0.pdf"}, "source_id": "5d0a41a4-b79b-4182-b6ee-afa099f453da"}], "unmatched_passage_links": []}'::jsonb,'draft','ai_candidate');
insert into original_claims values ('0961313a-d30e-49f6-84c7-4aa3a64ccfd9','{"approval_origin": "ai_candidate", "certainty": "medium", "claim_id": "0961313a-d30e-49f6-84c7-4aa3a64ccfd9", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "Witzel concludes that a nucleus of sayings and reports goes back to one person who was at once priest, teacher, philosopher and mystic, but that at the time the texts were redacted (he suggests about 150 BCE, with a question mark) hagiographic touches were added, such as Janaka giving all Videha to Yajnavalkya.", "current_status": "draft", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "HISTORICAL_INFERENCE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification"], "evidence_type": "historical_inference", "lens": {"field_id": "8d36194b-360a-499b-a5a1-e055ce8db12b", "field_label": "Mythologization vs. historical core, explicitly flagged rather than artificially resolved", "parameter_id": "e9e12cd4-53da-4743-8917-a2868006ced2", "parameter_name": "Contested or Uncertain Aspects"}, "parent_claim_id": null, "personality_id": "6ef206bf-1446-4e3d-94a6-e583f7736e62", "personality_name": "Yajnavalkya", "reviewer_decision": null, "sources": [{"evidence_excerpt": "In sum, if the strands of tradition visible in the Vedic texts are carefully screened, a nucleus emerges of texts composed by Yåjñavalkya, of his sayings and one-liners, and of reports dealing with him as an exceptional person: someone who is, at the same time, a late Vedic priest, a teacher, a philosopher and a mystic. These traditions represent the same …", "link_id": "b263870c-087a-4d92-bf01-c2381c469de4", "page_or_section": "§10", "passages": [{"chunk_id": "95d074dd-b0db-4f8e-8315-d29a832f0e9b", "confidence": null, "excerpt": "In sum, if the strands of tradition visible in the Vedic texts are carefully screened, a nucleus emerges of texts composed by Yåjñavalkya, of his sayings and one-liners, and of reports dealing with him as an exceptional person: someone who is, at the same time, a late Vedic priest, a teacher, a philosopher and a mystic. These traditions represent the same …", "excerpt_truncated": true, "is_active": true, "link_method": null, "page_or_section": "§10", "relationship": "supports", "section_title": "Yajnavalkya: Witzel concludes that a nucleus of sayings and reports goes back to one person who was at once priest, teacher, philosopher and mystic, but that at the time the texts were redacted (he suggests about 150 BCE, with a question mark) hagiographic touches were added, such as Janaka giving all Videha to Yajnavalkya.", "source_id": "3bdf7285-d73d-4e2f-a6dd-d40a442322dc", "textual_layer": "Modern Vedic philology (Harvard); argues for one historical teacher behind both texts"}], "relationship": "supports", "source": {"author": "Michael Witzel", "authority_metadata": {"verified_at": "2026-10-12"}, "citation": "Michael Witzel. Yājñavalkya as ritualist and philosopher, and his personal language. Paitimāna: Essays in Iranian, Indo-European, and Indian Studies in Honor of Hanns-Peter Schmidt (Mazda, Costa Mesa); author’s text circulated on the INDOLOGY list. https://list.indology.info/pipermail/indology/attachments/20170714/f690c648/attachment.pdf", "original_work_identity": {}, "publication_year": 2003, "publisher_or_institution": "Paitimāna: Essays in Iranian, Indo-European, and Indian Studies in Honor of Hanns-Peter Schmidt (Mazda, Costa Mesa); author’s text circulated on the INDOLOGY list", "rights_or_access_note": "Author’s PDF; text extraction drops some under-dotted Sanskrit letters and prints å for ā.", "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Yājñavalkya as ritualist and philosopher, and his personal language", "url": "https://list.indology.info/pipermail/indology/attachments/20170714/f690c648/attachment.pdf"}, "source_id": "3bdf7285-d73d-4e2f-a6dd-d40a442322dc"}], "unmatched_passage_links": []}'::jsonb,'draft','ai_candidate');
insert into original_claims values ('73b16746-4ae8-4db2-bd93-50f7f6a41a42','{"approval_origin": "ai_candidate", "certainty": "medium", "claim_id": "73b16746-4ae8-4db2-bd93-50f7f6a41a42", "claim_kind": "traditional_account", "claim_relations": [], "claim_text": "The Purana continues that Yajnavalkya praised the Sun, who appeared as a horse and gave him Yajus texts unknown to his former teacher; the Purana derives the school name Vajin from this, and says fifteen branches arose from Kanva and other pupils.", "current_status": "draft", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TRADITIONAL_NARRATIVE", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification"], "evidence_type": "traditional_narrative", "lens": {"field_id": "8d36194b-360a-499b-a5a1-e055ce8db12b", "field_label": "Mythologization vs. historical core, explicitly flagged rather than artificially resolved", "parameter_id": "e9e12cd4-53da-4743-8917-a2868006ced2", "parameter_name": "Contested or Uncertain Aspects"}, "parent_claim_id": null, "personality_id": "6ef206bf-1446-4e3d-94a6-e583f7736e62", "personality_name": "Yajnavalkya", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Glory to Savitrí, to Súrya, to Bháskara, to Vivaswat, to Áditya, to the first-born of gods or demons. I adore the eye of the universe, borne in a golden car, whose banners scatter ambrosia.\" Thus eulogized by Yájnawalkya, the sun, in the form of a horse, appeared to him, and said, \"Demand what you desire.\" To which the sage, having prostrated himself before …", "link_id": "e5aff9be-55e3-464b-9cb9-6f9dcd8eab54", "page_or_section": "Vishnu Purana 3.5 (Wilson, p. 281)", "passages": [{"chunk_id": "3498b27c-bd52-43ad-ac6e-fbb444b278cd", "confidence": null, "excerpt": "Glory to Savitrí, to Súrya, to Bháskara, to Vivaswat, to Áditya, to the first-born of gods or demons. I adore the eye of the universe, borne in a golden car, whose banners scatter ambrosia.\" Thus eulogized by Yájnawalkya, the sun, in the form of a horse, appeared to him, and said, \"Demand what you desire.\" To which the sage, having prostrated himself before …", "excerpt_truncated": true, "is_active": true, "link_method": null, "page_or_section": "Vishnu Purana 3.5 (Wilson, p. 281)", "relationship": "supports", "section_title": "Yajnavalkya: The Purana continues that Yajnavalkya praised the Sun, who appeared as a horse and gave him Yajus texts unknown to his former teacher; the Purana derives the school name Vajin from this, and says fifteen branches arose from Kanva and other pupils.", "source_id": "e1057aff-b432-47af-8318-f70ecf558442", "textual_layer": "Puranic tradition: Vishnu Purana, in translation"}], "relationship": "supports", "source": {"author": "Horace Hayman Wilson (translator)", "authority_metadata": {"verified_at": "2026-10-12"}, "citation": "Horace Hayman Wilson (translator). The Vishnu Purana, Book III, Chapter V. John Murray, London; transcription archived from sacred-texts.com. https://web.archive.org/web/2023id_/https://www.sacred-texts.com/hin/vp/vp079.htm", "original_work_identity": {}, "publication_year": 1840, "publisher_or_institution": "John Murray, London; transcription archived from sacred-texts.com", "rights_or_access_note": "Public-domain 1840 translation; transcription read through the Internet Archive Wayback Machine.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "The Vishnu Purana, Book III, Chapter V", "url": "https://web.archive.org/web/2023id_/https://www.sacred-texts.com/hin/vp/vp079.htm"}, "source_id": "e1057aff-b432-47af-8318-f70ecf558442"}], "unmatched_passage_links": []}'::jsonb,'draft','ai_candidate');
insert into original_claims values ('9235138e-1430-4350-a3a6-1fab84afa0fc','{"approval_origin": "ai_candidate", "certainty": "medium", "claim_id": "9235138e-1430-4350-a3a6-1fab84afa0fc", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "Eggeling notes that the story of Yajnavalkya disgorging the Yajus he had learned from Vaishampayana seems to appear first in the Puranas, and that Panini and Patanjali know the Taittiriya texts only as \"promulgated by Tittiri\"; the tale is therefore later tradition about the two Yajurveda schools, not early testimony.", "current_status": "draft", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "SCHOLARLY_INTERPRETATION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "8d36194b-360a-499b-a5a1-e055ce8db12b", "field_label": "Mythologization vs. historical core, explicitly flagged rather than artificially resolved", "parameter_id": "e9e12cd4-53da-4743-8917-a2868006ced2", "parameter_name": "Contested or Uncertain Aspects"}, "parent_claim_id": null, "personality_id": "6ef206bf-1446-4e3d-94a6-e583f7736e62", "personality_name": "Yajnavalkya", "reviewer_decision": null, "sources": [{"evidence_excerpt": "According to the story alluded to, Yâgñavalkya, having been taught the old Yagus texts by Vaisampâyana, incurred the displeasure of his teacher, and was forced by him to disgorge the sacred science which, on falling to the ground, became soiled p. xxviii (hence Black Yagus), and was picked up by Yâgñavalkya''s condisciples, who had assumed the form of …", "link_id": "ba3dd9e2-69b0-49d6-827c-905ff9e600e5", "page_or_section": "SBE 12, Introduction, pp. xxvii–xxviii, note", "passages": [{"chunk_id": "5f672947-edfa-48be-8038-7696beb21b05