insert into original_claims values ('0cf6cd03-4ca3-4fde-8db5-a75ab4230cf9','{"approval_origin": "ai_candidate", "certainty": "high", "claim_id": "0cf6cd03-4ca3-4fde-8db5-a75ab4230cf9", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "Yajnavalkya teaches Maitreyi that nothing is dear for its own sake but for the sake of the self, and that it is the self that should be seen, heard, reflected on and pondered.", "current_status": "draft", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification"], "evidence_type": "direct_primary_text", "lens": {"field_id": "300f5dd0-5491-4da5-8bd0-ce8a5d1c4cbb", "field_label": "Core teaching or metaphysical insight distinctively associated with the Rishi", "parameter_id": "4faa5bc1-1b4d-4c48-a26a-cd1b111232e0", "parameter_name": "Philosophical / Doctrinal Position"}, "parent_claim_id": null, "personality_id": "6ef206bf-1446-4e3d-94a6-e583f7736e62", "personality_name": "Yajnavalkya", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Lo, verily, not for love of all is all dear, but for love of the Soul all is dear. Lo, verily, it is the Soul (Ātman) that should be seen, that should be hearkened to, that should be thought on, that should be pondered on, O Maitreyī.", "link_id": "be040970-1c13-4ad6-a695-41464bf5fd81", "page_or_section": "BAU 2.4.5", "passages": [{"chunk_id": "e623e54f-b1c9-46a2-8370-013c5578991d", "confidence": null, "excerpt": "Lo, verily, not for love of all is all dear, but for love of the Soul all is dear. Lo, verily, it is the Soul (Ātman) that should be seen, that should be hearkened to, that should be thought on, that should be pondered on, O Maitreyī.", "excerpt_truncated": false, "is_active": true, "link_method