insert into original_claims values ('2c1da367-c645-4778-8047-16ca9e9bfa19','{"approval_origin": "ai_candidate", "certainty": "high", "claim_id": "2c1da367-c645-4778-8047-16ca9e9bfa19", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "Yajnavalkya’s answer to Gargi is that space itself is woven on \"the Imperishable\" (akshara), which he describes almost entirely by negation: not coarse, not fine, not short, not long, without breath or mouth, without measure, without inside or outside.", "current_status": "draft", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification"], "evidence_type": "direct_primary_text", "lens": {"field_id": "300f5dd0-5491-4da5-8bd0-ce8a5d1c4cbb", "field_label": "Core teaching or metaphysical insight distinctively associated with the Rishi", "parameter_id": "4faa5bc1-1b4d-4c48-a26a-cd1b111232e0", "parameter_name": "Philosophical / Doctrinal Position"}, "parent_claim_id": null, "personality_id": "6ef206bf-1446-4e3d-94a6-e583f7736e62", "personality_name": "Yajnavalkya", "reviewer_decision": null, "sources": [{"evidence_excerpt": "He said: ‘That, O Gārgī, Brahmans call the Imperishable (ak?ara). It is not coarse, not fine, not short, not long, not glowing [like fire], not adhesive [like water], without shadow and without darkness, without air and without space, without stickiness, (intangible),1 odorless, tasteless, without eye, without ear, without voice, without wind, without …", "link_id": "dc4ca178-756a-4cb6-b971-cf33ccdd8c03", "page_or_section": "BAU 3.8.8", "passages": [{"chunk_id": "82ecdae0-fd61-4e6f-98ce-51a8ef45efaa", "confidence": null, "excerpt": "He said: ‘That, O Gārgī, Brahmans call the Imperishable (ak?ara). It is not coarse, not fine, not short, not long, not glowing [like fire], not adhesive [like water], without shadow and without darkness, without air and without space, without stickiness, (intangible),1 odorless, tasteless, without eye, without ear, without voice, without wind, without …", "excerpt_truncated": true, "is_active": true, "link_method": null, "page_or_section": "BAU 3.8.8", "relationship": "supports", "section_title": "Yajnavalkya: Yajnavalkya’s answer to Gargi is that space itself is woven on \"the Imperishable\" (akshara), which he describes almost entirely by negation: not coarse, not fine, not short, not long, without breath or mouth, without measure, without inside or outside.", "source_id": "5d0a41a4-b79b-4182-b6ee-afa099f453da", "textual_layer": "Early Upanishad: Brihadaranyaka (Kanva recension), in translation"}], "relationship": "supports", "source": {"author": "Robert Ernest Hume (translator)", "authority_metadata": {"verified_at": "2026-10-12"}, "citation": "Robert Ernest Hume (translator). Brihad-Aranyaka Upanishad, in The Thirteen Principal Upanishads. Oxford University Press; Online Library of Liberty edition. https://oll-resources.s3.us-east-2.amazonaws.com/oll3/store/titles/2058/Hume_1395_EBk_v6.0.pdf", "original_work_identity": {}, "publication_year": 1921, "publisher_or_institution": "Oxford University Press; Online Library of Liberty edition", "rights_or_access_note": "Public-domain 1921 Oxford translation; the e-book text layer prints \"?\" for some under-dotted Sanskrit letters.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Brihad-Aranyaka Upanishad, in The Thirteen Principal Upanishads", "url": "https://oll-resources.s3.us-east-2.amazonaws.com/oll3/store/titles/2058/Hume_1395_EBk_v6.0.pdf"}, "source_id": "5d0a41a4-b79b-4182-b6ee-afa099f453da"}], "unmatched_passage_links": []}'::jsonb,'draft','ai_candidate');
insert into original_claims values ('2c739399-810f-42e4-9b41-9dbc8e24313a','{"approval_origin": "ai_candidate", "certainty": "high", "claim_id": "2c739399-810f-42e4-9b41-9dbc8e24313a", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "In Brihadaranyaka 3.7 Yajnavalkya teaches the self as the \"inner controller\" (antaryamin): the unseen seer, unheard hearer and unthought thinker, other than whom there is no seer, hearer or knower.", "current_status": "draft", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification"], "evidence_type": "direct_primary_text", "lens": {"field_id": "300f5dd0-5491-4da5-8bd0-ce8a5d1c4cbb", "field_label": "Core teaching or metaphysical insight distinctively associated with the Rishi", "parameter_id": "4faa5bc1-1b4d-4c48-a26a-cd1b111232e0", "parameter_name": "Philosophical / Doctrinal Position"}, "parent_claim_id": null, "personality_id": "6ef206bf-1446-4e3d-94a6-e583f7736e62", "personality_name": "Yajnavalkya", "reviewer_decision": null, "sources": [{"evidence_excerpt": "He is the unseen Seer, the unheard Hearer, the unthought Thinker, the ununderstood Understander. Other than He there is no seer. Other than He there is no hearer. Other than He there is no thinker. Other than He there is no understander. He is your Soul, the Inner Controller, the Immortal.’", "link_id": "0d323329-5ce6-47b8-a54b-be2e7aaab93f", "page_or_section": "BAU 3.7.23", "passages": [{"chunk_id": "c4ac643f-d470-4092-9fdd-cde54f8e4eca", "confidence": null, "excerpt": "He is the unseen Seer, the unheard Hearer, the unthought Thinker, the ununderstood Understander. Other than He there is no seer. Other than He there is no hearer. Other than He there is no thinker. Other than He th