insert into original_claims values ('827648c4-4036-4669-9813-623d6979029e','{"approval_origin": "ai_candidate", "certainty": "high", "claim_id": "827648c4-4036-4669-9813-623d6979029e", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "To Maitreyi, Yajnavalkya compares the great being to a lump of salt dissolved in water, which cannot be picked out yet makes all the water salty: it is a single mass of knowledge, and he adds that \"after death there is no consciousness\".", "current_status": "draft", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification"], "evidence_type": "direct_primary_text", "lens": {"field_id": "300f5dd0-5491-4da5-8bd0-ce8a5d1c4cbb", "field_label": "Core teaching or metaphysical insight distinctively associated with the Rishi", "parameter_id": "4faa5bc1-1b4d-4c48-a26a-cd1b111232e0", "parameter_name": "Philosophical / Doctrinal Position"}, "parent_claim_id": null, "personality_id": "6ef206bf-1446-4e3d-94a6-e583f7736e62", "personality_name": "Yajnavalkya", "reviewer_decision": null, "sources": [{"evidence_excerpt": "It is—as a lump of salt cast in water would dissolve right into the water; there would not be [any]2 of it to seize forth, as it were (iva), but wherever one may take, it is salty indeed—so, lo, verily, this great Being (bhūta). infinite, limitless, is just a mass of knowledge (vijñāna-ghana). Arising out of these elements (bhūta), into them also one …", "link_id": "28c4bebc-f4f7-4e37-acf1-f74997417bf7", "page_or_section": "BAU 2.4.12", "passages": [{"chunk_id": "abe15184-1aa2-479d-8b13-6461f122ba97", "confidence": null, "excerpt": "It is—as a lump of salt cast in water would dissolve right into the water; there would not be [any]2 of it to s