insert into original_claims values ('89ab97f4-e0ce-4a2e-97b9-59b1c8e0e245','{"approval_origin": "ai_candidate", "certainty": "high", "claim_id": "89ab97f4-e0ce-4a2e-97b9-59b1c8e0e245", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "Liberation in Yajnavalkya’s teaching to Janaka is freedom from desire: the breaths of one whose only desire is the self do not depart at death; \"being very Brahma, he goes to Brahma\", and a quoted verse says a mortal becomes immortal when the desires lodged in the heart are released.", "current_status": "draft", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification"], "evidence_type": "direct_primary_text", "lens": {"field_id": "300f5dd0-5491-4da5-8bd0-ce8a5d1c4cbb", "field_label": "Core teaching or metaphysical insight distinctively associated with the Rishi", "parameter_id": "4faa5bc1-1b4d-4c48-a26a-cd1b111232e0", "parameter_name": "Philosophical / Doctrinal Position"}, "parent_claim_id": null, "personality_id": "6ef206bf-1446-4e3d-94a6-e583f7736e62", "personality_name": "Yajnavalkya", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Now the man who does not desire. He who is without desire, who is freed from desire, whose desire is satisfied, whose desire is the Soul—his breaths do not depart. Being very Brahma, he goes to Brahma. On this point there is this verse:— When are liberated all The desires that lodge in one’s heart, Then a mortal becomes immortal! Therein he reaches Brahma!", "link_id": "7cc4344f-d1ed-403c-89a9-b9ca0079c88c", "page_or_section": "BAU 4.4.6–7", "passages": [{"chunk_id": "541d56c5-6e33-4ae1-ab88-29f522e121be", "confidence": null, "excerpt": "Now the man who does not desire. He who is without desire, 