insert into original_claims values ('96c36c29-be5d-4683-b991-f28d9e68d426','{"approval_origin": "ai_candidate", "certainty": "high", "claim_id": "96c36c29-be5d-4683-b991-f28d9e68d426", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "In Brihadaranyaka 4.2.4 Yajnavalkya tells Janaka that the self \"is not this, it is not that\" (neti, neti): it cannot be grasped, destroyed, attached or bound. He declares that Janaka has reached fearlessness, and the king offers him the Videhas and himself in service.", "current_status": "draft", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification"], "evidence_type": "direct_primary_text", "lens": {"field_id": "300f5dd0-5491-4da5-8bd0-ce8a5d1c4cbb", "field_label": "Core teaching or metaphysical insight distinctively associated with the Rishi", "parameter_id": "4faa5bc1-1b4d-4c48-a26a-cd1b111232e0", "parameter_name": "Philosophical / Doctrinal Position"}, "parent_claim_id": null, "personality_id": "6ef206bf-1446-4e3d-94a6-e583f7736e62", "personality_name": "Yajnavalkya", "reviewer_decision": null, "sources": [{"evidence_excerpt": "But the Soul (Ātman) is not this, it is not that (neti, neti). It is unseizable, for it cannot be seized. It is indestructible, for it cannot be destroyed. It is unattached, for it does not attach itself. It is unbound. It does not tremble. It is not injured. Verily, Janaka, you have reached fearlessness.’—Thus spake Yājñavalkya. Janaka, [king] of Videha, …", "link_id": "6a5a8ce5-a4ba-44a7-a6d3-c5ce40f9841b", "page_or_section": "BAU 4.2.4", "passages": [{"chunk_id": "adce372c-c1ff-47f9-a5b6-f7e1208aee6c", "confidence": null, "excerpt": "But the Soul (Ātman) is not this, it is not that (neti, neti). It is unseizable, for it cannot be seized. It is indestructible, for it cannot be destroyed. It is unattached, for it does not attach itself. It is unbound. It does not tremble. It is not injured. Verily, Janaka, you have reached fearlessness.’—Thus spake Yājñavalkya. Janaka, [king] of Videha, …", "excerpt_truncated": true, "is_active": true, "link_method": null, "page_or_section": "BAU 4.2.4", "relationship": "supports", "section_title": "Yajnavalkya: In Brihadaranyaka 4.2.4 Yajnavalkya tells Janaka that the self \"is not this, it is not that\" (neti, neti): it cannot be grasped, destroyed, attached or bound. He declares that Janaka has reached fearlessness, and the king offers him the Videhas and himself in service.", "source_id": "5d0a41a4-b79b-4182-b6ee-afa099f453da", "textual_layer": "Early Upanishad: Brihadaranyaka (Kanva recension), in translation"}], "relationship": "supports", "source": {"author": "Robert Ernest Hume (translator)", "authority_metadata": {"verified_at": "2026-10-12"}, "citation": "Robert Ernest Hume (translator). Brihad-Aranyaka Upanishad, in The Thirteen Principal Upanishads. Oxford University Press; Online Library of Liberty edition. https://oll-resources.s3.us-east-2.amazonaws.com/oll3/store/titles/2058/Hume_1395_EBk_v6.0.pdf", "original_work_identity": {}, "publication_year": 1921, "publisher_or_institution": "Oxford University Press; Online Library of Liberty edition", "rights_or_access_note": "Public-domain 1921 Oxford translation; the e-book text layer prints \"?\" for some under-dotted Sanskrit letters.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Brihad-Aranyaka Upanishad, in The Thirteen Principal Upanishads", "url": "https://oll-resources.s3.us-east-2.amazonaws.com/oll3/store/titles/2058/Hume_1395_EBk_v6.0.pdf"}, "source_id": "5d0a41a4-b79b-4182-b6ee-afa099f453da"}], "unmatched_passage_links": []}'::jsonb,'draft','ai_candidate');
insert into original_claims values ('b0a691c6-afed-4d9a-a406-4072bc09f177','{"approval_origin": "ai_candidate", "certainty": "high", "claim_id": "b0a691c6-afed-4d9a-a406-4072bc09f177", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "In Brihadaranyaka 3.2.13 Yajnavalkya takes his questioner Artabhaga by the hand and withdraws to discuss a question in private rather than in public; the text reports that what they spoke of was karma: one becomes good by good action and bad by bad action.", "current_status": "draft", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification"], "evidence_type": "direct_primary_text", "lens": {"field_id": "300f5dd0-5491-4da5-8bd0-ce8a5d1c4cbb", "field_label": "Core teaching or metaphysical insight distinctively associated with the Rishi", "parameter_id": "4faa5bc1-1b4d-4c48-a26a-cd1b111232e0", "parameter_name": "Philosophical / Doctrinal Position"}, "parent_claim_id": null, "personality_id": "6ef206bf-1446-4e3d-94a6-e583f7736e62", "personality_name": "Yajnavalkya", "reviewer_decision": null, "sources": [{"evidence_excerpt": "‘Ārtabhāga, my dear, take my hand. We two only will know of this. This is not for us two [to speak of] in public.’ The two went away and deliberated. What they said was karma (action). What they praised was karma. Verily, one becomes good by good action, bad by bad action.", "link_id": "3c8db0a4-2345-41e8-bb4e-7abe446af967", "page_or_section": "BAU 3.2.13", "passages": [{"chunk_id": "bc030239-b336-4cdb-afdd-b485bc65e01e", "confidence": null, "excerpt": "‘Ārtabhāga, my dear, take my hand. We two only will know of this. This is not for us two [to speak of] in public.’ The two went away and deliberated. What they said was karma 