insert into original_claims values ('c3fda81c-2612-42bb-9053-5db48dd87fc1','{"approval_origin": "ai_candidate", "certainty": "high", "claim_id": "c3fda81c-2612-42bb-9053-5db48dd87fc1", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "The long teaching of Brihadaranyaka 4.3 starts from Janaka’s question about what serves as a person’s light; when sun, moon, fire and speech are all gone, Yajnavalkya answers that the self (atman) is one’s light.", "current_status": "draft", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification"], "evidence_type": "direct_primary_text", "lens": {"field_id": "300f5dd0-5491-4da5-8bd0-ce8a5d1c4cbb", "field_label": "Core teaching or metaphysical insight distinctively associated with the Rishi", "parameter_id": "4faa5bc1-1b4d-4c48-a26a-cd1b111232e0", "parameter_name": "Philosophical / Doctrinal Position"}, "parent_claim_id": null, "personality_id": "6ef206bf-1446-4e3d-94a6-e583f7736e62", "personality_name": "Yajnavalkya", "reviewer_decision": null, "sources": [{"evidence_excerpt": "But when the sun has set, Yājñavalkya, and the moon has set, and the fire has gone out, and speech is hushed, what light does a person here have?’ ‘The soul (ātman), indeed, is his light,’ said he, ‘for with the soul, indeed, as his light one sits, moves around, does his work, and returns.’", "link_id": "c982b9c9-c61f-4a20-adc5-1e02cffdef2f", "page_or_section": "BAU 4.3.6", "passages": [{"chunk_id": "a62f4ec4-cdb7-4963-a2f2-e98a85531e28", "confidence": null, "excerpt": "But when the sun has set, Yājñavalkya, and the moon has set, and the fire has gone out, and speech is hushed, what light does a person here have?’ ‘The soul (ātman), indeed, is his light,’ said he, ‘for with the soul, indeed, as his light one sits, moves around, does his work, and returns.’", "excerpt_truncated": false, "is_active": true, "link_method": null, "page_or_section": "BAU 4.3.6", "relationship": "supports", "section_title": "Yajnavalkya: The long teaching of Brihadaranyaka 4.3 starts from Janaka’s question about what serves as a person’s light; when sun, moon, fire and speech are all gone, Yajnavalkya answers that the self (atman) is one’s light.", "source_id": "5d0a41a4-b79b-4182-b6ee-afa099f453da", "textual_layer": "Early Upanishad: Brihadaranyaka (Kanva recension), in translation"}], "relationship": "supports", "source": {"author": "Robert Ernest Hume (translator)", "authority_metadata": {"verified_at": "2026-10-12"}, "citation": "Robert Ernest Hume (translator). Brihad-Aranyaka Upanishad, in The Thirteen Principal Upanishads. Oxford University Press; Online Library of Liberty edition. https://oll-resources.s3.us-east-2.amazonaws.com/oll3/store/titles/2058/Hume_1395_EBk_v6.0.pdf", "original_work_identity": {}, "publication_year": 1921, "publisher_or_institution": "Oxford University Press; Online Library of Liberty edition", "rights_or_access_note": "Public-domain 1921 Oxford translation; the e-book text layer prints \"?\" for some under-dotted Sanskrit letters.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Brihad-Aranyaka Upanishad, in The Thirteen Principal Upanishads", "url": "https://oll-resources.s3.us-east-2.amazonaws.com/oll3/store/titles/2058/Hume_1395_EBk_v6.0.pdf"}, "source_id": "5d0a41a4-b79b-4182-b6ee-afa099f453da"}], "unmatched_passage_links": []}'::jsonb,'draft','ai_candidate');
insert into original_claims values ('dc55f82d-8149-47d0-9866-a8c2808b20cf','{"approval_origin": "ai_candidate", "certainty": "medium", "claim_id": "dc55f82d-8149-47d0-9866-a8c2808b20cf", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "Black describes Yajnavalkya as the most prominent teacher in the Brihadaranyaka Upanishad and says he characterizes the self (atman) in terms of consciousness rather than as a life-giving essence.", "current_status": "draft", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "SCHOLARLY_INTERPRETATION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "300f5dd0-5491-4da5-8bd0-ce8a5d1c4cbb", "field_label": "Core teaching or metaphysical insight distinctively associated with the Rishi", "parameter_id": "4faa5bc1-1b4d-4c48-a26a-cd1b111232e0", "parameter_name": "Philosophical / Doctrinal Position"}, "parent_claim_id": null, "personality_id": "6ef206bf-1446-4e3d-94a6-e583f7736e62", "personality_name": "Yajnavalkya", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Thus, he offers an organic understanding of ātman, characterizing the self in terms of the life force that animates all living beings. Yājñavalkya, the most prominent teacher in the Bṛhadāraṇyaka Upaniṣad, characterizes ātman more in terms of consciousness than as a life-giving essence. In a debate that pits him against Uddālaka—his senior colleague and, by …", "link_id": "d996220f-58ae-4b2d-b19c-1440e1c7ea28", "page_or_section": "§3", "passages": [{"chunk_id": "f6683f48-d460-4929-8ead-de9a8a041163", "confidence": null, "excerpt": "Thus, he offers an organic understanding of ātman, characterizing the self in terms of the life force that animates all living beings.