insert into original_claims values ('4c1d1c93-36a3-465f-8a03-05ec28e3e31a','{"approval_origin": "ai_candidate", "certainty": "medium", "claim_id": "4c1d1c93-36a3-465f-8a03-05ec28e3e31a", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "The Upanishads do not teach one doctrine: Black notes that Yajnavalkya equates atman with brahman (Brihadaranyaka 4.4.5), whereas Uddalaka Aruni, source of the phrase \"tat tvam asi\", never uses the word brahman.", "current_status": "draft", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "SCHOLARLY_INTERPRETATION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "fc3c24fb-b9f5-48a9-abf4-3e65ec920fdc", "field_label": "Relationship to major currents such as Vedanta, Samkhya, Mimamsa, etc.", "parameter_id": "4faa5bc1-1b4d-4c48-a26a-cd1b111232e0", "parameter_name": "Philosophical / Doctrinal Position"}, "parent_claim_id": null, "personality_id": "6ef206bf-1446-4e3d-94a6-e583f7736e62", "personality_name": "Yajnavalkya", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Although Śāṇḍilya’s teaching of ātman and brahman is often considered the central doctrine of the Upaniṣads, it is important to remember that this is not the only characterization either of the self or of ultimate reality. While some teachers, such as Yājñavalkya, also equate ātman with brahman (BU 4.4.5), others, such as Uddālaka Āruṇi, do not make this …", "link_id": "f9c54211-6322-42f0-8057-3ec2a938347b", "page_or_section": "§4", "passages": [{"chunk_id": "c848ad43-e717-47d9-b673-b15128a07751", "confidence": null, "excerpt": "Although Śāṇḍilya’s teaching of ātman and brahman is often considered the central doctrine of the Upaniṣads, it is important to remember that this is not the only characterization either of the self or of ultimate reality. While some teachers, such as Yājñavalkya, also equate ātman with brahman (BU 4.4.5), others, such as Uddālaka Āruṇi, do not make this …", "excerpt_truncated": true, "is_active": true, "link_method": null, "page_or_section": "§4", "relationship": "supports", "section_title": "Yajnavalkya: The Upanishads do not teach one doctrine: Black notes that Yajnavalkya equates atman with brahman (Brihadaranyaka 4.4.5), whereas Uddalaka Aruni, source of the phrase \"tat tvam asi\", never uses the word brahman.", "source_id": "c833b2a2-932f-4715-8339-d3f1860dc99d", "textual_layer": "Peer-reviewed philosophy reference; modern interpretation of the early Upanishads"}], "relationship": "supports", "source": {"author": "Brian Black", "authority_metadata": {"verified_at": "2026-10-12"}, "citation": "Brian Black. The Upaniṣads. Internet Encyclopedia of Philosophy (peer-reviewed). https://iep.utm.edu/upanisad/", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Internet Encyclopedia of Philosophy (peer-reviewed)", "rights_or_access_note": "Public original; short research excerpts.", "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "The Upaniṣads", "url": "https://iep.utm.edu/upanisad/"}, "source_id": "c833b2a2-932f-4715-8339-d3f1860dc99d"}], "unmatched_passage_links": []}'::jsonb,'draft','ai_candidate');
insert into original_claims values ('5d989d55-6b02-4626-b7b5-d9796aa33f37','{"approval_origin": "ai_candidate", "certainty": "medium", "claim_id": "5d989d55-6b02-4626-b7b5-d9796aa33f37", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "Yajnavalkya’s views were contested within the Upanishads themselves: Black points out that Prajapati in the Chandogya Upanishad treats as false or incomplete the account of the self as dreamless sleep, which Yajnavalkya calls the highest goal and highest bliss when teaching Janaka.", "current_status": "draft", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "SCHOLARLY_INTERPRETATION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "fc3c24fb-b9f5-48a9-abf4-3e65ec920fdc", "field_label": "Relationship to major currents such as Vedanta, Samkhya, Mimamsa, etc.", "parameter_id": "4faa5bc1-1b4d-4c48-a26a-cd1b111232e0", "parameter_name": "Philosophical / Doctrinal Position"}, "parent_claim_id": null, "personality_id": "6ef206bf-1446-4e3d-94a6-e583f7736e62", "personality_name": "Yajnavalkya", "reviewer_decision": null, "sources": [{"evidence_excerpt": "This pattern continues several times, before Prajāpati finally presents ātman as the ‘one who is aware’ of his final and true teaching. One of the teachings that Prajāpati presents as false, or at least as incomplete, is a description of ātman in terms of dreamless sleep, a teaching of the self that Yājñavalkya describes as the ‘highest goal’ and ‘the …", "link_id": "0299d678-f986-4743-9ee9-c9614865a0b7", "page_or_section": "§3", "passages": [{"chunk_id": "c5b7bd3c-5284-48a4-a096-8a5908f79cb9", "confidence": null, "excerpt": "This pattern continues several times, before Prajāpati finally presents ātman as the ‘one who is aware’ of his final and true teaching. One of the teachings that Prajāpati presents as false, or at least as incomplete, is a description of ātman in terms of dreamless sleep, a teaching of the self that Yājñavalkya describes as the ‘highest goal’ and ‘the …", "excerpt_truncated": true, "is_active": true, "link_method": null, "page_or_section": "§3", "relationship": "supports", "section_title": "Yajnavalkya: Yajnavalkya’s views were contested within the Upanishads themselves: Black points out that Prajapati in the Chandogya Upanishad treats as false or incomplete the account of the self as dreamless sleep, which Yajnavalkya calls the highest goal and highest bliss when teaching Janaka.", "source_id": "c833b2a2-932f-4715-8339-d3f1860dc99d", "textual_layer": "Peer-reviewed philosophy reference; modern interpretation of the early Upanishads"}], "relationship": "supports", "source": {"author": "Brian Black", "authority_metadata": {"verified_at": "2026-10-12"}, "citation": "Brian Black. The Upaniṣads. Internet Encyclopedia of Philosophy (peer-reviewed). https://iep.utm.edu/upanisad/", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Internet Encyclopedia of Philosophy (peer-reviewed)", "rights_or_access_note": "Public original; short research excerpts.", "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "The Upaniṣads", "url": "https://iep.utm.edu/upanisad/"}, "source_id": "c833b2a2-932f-4715-8339-d3f1860dc99d"}], "unmatched_passage_links": []}'::jsonb,'draft','ai_candidate');
insert into original_claims values ('8a8cc68e-83c2-43e7-bcee-a2746f315398','{"approval_origin": "ai_candidate", "certainty": "medium", "claim_id": "8a8cc68e-83c2-43e7-bcee-a2746f315398", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "Yajnavalkya’s positions were still cited in later philosophy outside Vedanta: Black notes that the Nyaya philosopher Gangesha (about 1300 CE) appears to quote the Upanishads for the claim that karmic retribution does not bind those who know the self, a position stated by Yajnavalkya.", "current_status": "draft", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "SCHOLARLY_INTERPRETATION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "fc3c24fb-b9f5-48a9-abf4-3e65ec920fdc", "field_label": "Relationship to major currents such as Vedanta, Samkhya, Mimamsa, etc.", "parameter_id": "4faa5bc1-1b4d-4c48-a26a-cd1b111232e0", "parameter_name": "Philosophical / Doctrinal Position"}, "parent_claim_id": null, "personality_id": "6ef206bf-1446-4e3d-94a6-e583f7736e62", "personality_name": "Yajnavalkya", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Another Nyāya philosopher, Gaṅgeśa (c. 1300 C.E.), seems to be quoting from the Upaniṣads to back up the claim that karmic retribution is not binding for those who know the self—a position stated by Yājñavalkya (BU 4.4.23). Moreover, a number of Sāṃkhya and Yoga philosophers use the Upaniṣads in an attempt to make their schools more compatible with Vedānta.", "link_id": "479fa0aa-57a8-4c4f-83cb-63e66deb348a", "page_or_section": "§7", "passages": [{"chunk_id": "43f056c2-4f33-4b0e-aac2-cdb8354a660d", "confidence": null, "excerpt": "Another Nyāya philosopher, Gaṅgeśa (c. 1300 C.E.), seems to be quoting from the Upaniṣads to back up the claim that karmic retribution is not binding for those who know the self—a position stated by Yājñavalkya (BU 4.4.23). Moreover, a number of Sāṃkhya and Yoga philosophers use the Upaniṣads in an attempt to make their schools more compatible with Vedānta.", "excerpt_truncated": false, "is_active": true, "link_method": null, "page_or_section": "§7", "relationship": "supports", "section_title": "Yajnavalkya: Yajnavalkya’s positions were still cited in later philosophy outside Vedanta: Black notes that the Nyaya philosopher Gangesha (about 1300 CE) appears to quote the Upanishads for the claim that karmic retribution does not bind those who know the self, a position stated by Yajnavalkya.", "source_id": "c833b2a2-932f-4715-8339-d3f1860dc99d", "textual_layer": "Peer-reviewed philosophy reference; modern interpretation of the early Upanishads"}], "relationship": "supports", "source": {"author": "Brian Black", "authority_metadata": {"verified_at": "2026-10-12"}, "citation": "Brian Black. The Upaniṣads. Internet Encyclopedia of Philosophy (peer-reviewed). https://iep.utm.edu/upanisad/", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Internet Encyclopedia of Philosophy (peer-reviewed)", "rights_or_access_note": "Public original; short research excerpts.", "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "The Upaniṣads", "url": "https://iep.utm.edu/upanisad/"}, "source_id": "c833b2a2-932f-4715-8339-d3f1860dc99d"}], "unmatched_passage_links": []}'::jsonb,'draft','ai_candidate');
insert into original_claims values ('31441eb5-4961-4766-ae96-792d244a25a7','{"approval_origin": "ai_candidate", "certainty": "medium", "claim_id": "31441eb5-4961-4766-ae96-792d244a25a7", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "On linguistic grounds Witzel argues that the Janaka dialogue contains new coinages: \"advaita\" (non-duality) occurs in Vedic literature only at Brihadaranyaka 4.3.32 and its Brahmana parallel, and he regards it as a word coined by Yajnavalkya.", "current_status": "draft", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "SCHOLARLY_INTERPRETATION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "b4c5ae8d-219a-49ee-96e1-b85387118954", "field_label": "Unique or ahead-of-their-time conceptual contribution", "parameter_id": "4faa5bc1-1b4d-4c48-a26a-cd1b111232e0", "parameter_name": "Philosophical / Doctrinal Position"}, "parent_claim_id": null, "personality_id": "6ef206bf-1446-4e3d-94a6-e583f7736e62", "personality_name": "Yajnavalkya", "reviewer_decision": null, "sources": [{"evidence_excerpt": "dvaitá- is found earlier in the sense of ''duality'' (''Doppelheit'', Thieme). Its occurrence as a- dvaita in BĀU is a Vedic hapax; it occurs only at ŚB 14.7.1.31, BĀU 4.3.32, and clearly is a word coined by Yåjñavalkya.89", "link_id": "0f03933c-9393-4962-aa5d-08bbbe0fba91", "page_or_section": "§6", "passages": [{"chunk_id": "fc63b32c-176b-43ed-96d3-8f8202333052", "confidence": null, "excerpt": "dvaitá- is found earlier in the sense of ''duality'' (''Doppelheit'', Thieme). Its occurrence as a- dvaita in BĀU is a Vedic hapax; it occurs only at ŚB 14.7.1.31, BĀU 4.3.32, and clearly is a word coined by Yåjñavalkya.89", "excerpt_truncated": false, "is_active": true, "link_method": null, "page_or_section": "§6", "relationship": "supports", "section_title": "Yajnavalkya: On linguistic grounds Witzel argues that the Janaka dialogue contains new coinages: \"advaita\" (non-duality) occurs in Vedic literature only at Brihadaranyaka 4.3.32 and its Brahmana parallel, and he regards it as a word coined by Yajnavalkya.", "source_id": "3bdf7285-d73d-4e2f-a6dd-d40a442322dc", "textual_layer": "Modern Vedic philology (Harvard); argues for one historical teacher behind both texts"}], "relationship": "supports", "source": {"author": "Michael Witzel", "authority_metadata": {"verified_at": "2026-10-12"}, "citation": "Michael Witzel. Yājñavalkya as ritualist and philosopher, and his personal language. Paitimāna: Essays in Iranian, Indo-European, and Indian Studies in Honor of Hanns-Peter Schmidt (Mazda, Costa Mesa); author’s text circulated on the INDOLOGY list. https://list.indology.info/pipermail/indology/attachments/20170714/f690c648/attachment.pdf", "original_work_identity": {}, "publication_year": 2003, "publisher_or_institution": "Paitimāna: Essays in Iranian, Indo-European, and Indian Studies in Honor of Hanns-Peter Schmidt (Mazda, Costa Mesa); author’s text circulated on the INDOLOGY list", "rights_or_access_note": "Author’s PDF; text extraction drops some under-dotted Sanskrit letters and prints å for ā.", "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Yājñavalkya as ritualist and philosopher, and his personal language", "url": "https://list.indology.info/pipermail/indology/attachments/20170714/f690c648/attachment.pdf"}, "source_id": "3bdf7285-d73d-4e2f-a6dd-d40a442322dc"}], "unmatched_passage_links": []}'::jsonb,'draft','ai_candidate');
insert into original_claims values ('644a190e-2f41-4176-9d31-946f006cef47','{"approval_origin": "ai_candidate", "certainty": "medium", "claim_id": "644a190e-2f41-4176-9d31-946f006cef47", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "The publisher’s description of Lindquist’s monograph calls Yajnavalkya the most important ancient Indian literary figure before the Buddha and lists the \"firsts\" associated with him in the literature: the first thorough discussion of brahman and atman, the first theory of karma and rebirth, the first to renounce household life, and the first to debate women on religious questions.", "current_status": "draft", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "SCHOLARLY_ATTRIBUTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "b4c5ae8d-219a-49ee-96e1-b85387118954", "field_label": "Unique or ahead-of-their-time conceptual contribution", "parameter_id": "4faa5bc1-1b4d-4c48-a26a-cd1b111232e0", "parameter_name": "Philosophical / Doctrinal Position"}, "parent_claim_id": null, "personality_id": "6ef206bf-1446-4e3d-94a6-e583f7736e62", "personality_name": "Yajnavalkya", "reviewer_decision": null, "sources": [{"evidence_excerpt": "In this fascinating study, Steven E. Lindquist investigates the intersections between historical context and literary production in the \"life\" of Yājñavalkya, the most important ancient Indian literary figure prior to the Buddha. Known for his sharp tongue and deep thought, Yājñavalkya is associated with a number of \"firsts\" in Indian religious literary …", "link_id": "4758e890-dc28-4563-b2ee-876e08bbfc2c", "page_or_section": "Publisher’s description", "passages": [{"chunk_id": "9a5b6607-946d-4402-923