insert into original_claims values ('078cbfa2-a58a-4784-be4e-a9f304e7e6a2','{"approval_origin": "ai_candidate", "certainty": "high", "claim_id": "078cbfa2-a58a-4784-be4e-a9f304e7e6a2", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "In Brihadaranyaka Upanishad 3.1, King Janaka of Videha holds a sacrifice attended by Brahmins of the Kuru-Panchala country and stakes a thousand cows, with gold tied to their horns, to find out which of them is the most learned; this is the setting of Yajnavalkya’s great debate.", "current_status": "draft", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification"], "evidence_type": "direct_primary_text", "lens": {"field_id": "de20bc35-2696-4a80-b095-614bb650a581", "field_label": "Advisory relationships with kings or dynasties", "parameter_id": "700ce11a-bd45-4116-99a4-a246dc97c505", "parameter_name": "Relational / Social Role"}, "parent_claim_id": null, "personality_id": "6ef206bf-1446-4e3d-94a6-e583f7736e62", "personality_name": "Yajnavalkya", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Janaka, [king] of Videha, sacrificed with a sacrifice at which many presents were distributed. Brahmans of the Kurupañcālas were gathered together there. In this Janaka of Videha there arose a desire to know which of these Brahmans was the most learned in scripture. He enclosed a thousand cows. To the horns of each ten pādas [of gold] were bound.", "link_id": "94eb521b-feaa-42b1-94a9-c00c9c751464", "page_or_section": "BAU 3.1.1", "passages": [{"chunk_id": "7c5428fd-64fb-4c4b-ab98-0645e5ff2f85", "confidence": null, "excerpt": "Janaka, [king] of Videha, sacrificed with a sacrifice at which many presents were distributed. Brahmans of the Kurupañc