insert into original_claims values ('0962a471-8a26-4c0a-b736-6782470e2ddf','{"approval_origin": "ai_candidate", "certainty": "high", "claim_id": "0962a471-8a26-4c0a-b736-6782470e2ddf", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "Shatapatha Brahmana 3.8.2.24–25 records a dispute over the order of basting in the animal sacrifice: a priest of the rival Charaka school of Adhvaryus curses Yajnavalkya, who looks at his grey arms and dismisses the curse. The passage shows him as an ageing practising priest in a contest between ritual schools.", "current_status": "draft", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification"], "evidence_type": "direct_primary_text", "lens": {"field_id": "a04bf1d1-b32a-40f3-9994-4328cd6eef07", "field_label": "Interactions with other rishis: collaboration, rivalry, debate", "parameter_id": "700ce11a-bd45-4116-99a4-a246dc97c505", "parameter_name": "Relational / Social Role"}, "parent_claim_id": null, "personality_id": "6ef206bf-1446-4e3d-94a6-e583f7736e62", "personality_name": "Yajnavalkya", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Now the Karaka-Adhvaryus, forsooth, baste first the clotted ghee, arguing that the clotted ghee is the breath; and a Karaka-Adhvaryu, forsooth, cursed Yâgñavalkya for so doing, saying, ''That Adhvaryu has shut out the breath; the breath shall depart from him!'' 3:8:2:2525. But he, looking at his arms, said, ''These hoary arms--what in the world has become of …", "link_id": "aaf57605-e259-48d6-b7a7-e9a495020599", "page_or_section": "ŚB 3.8.2.24–25", "passages": [{"chunk_id": "f6f489fc-0e6a-47f6-b19e-b7bd6a6ea9a0", "confidence": null, "excerpt": "Now the Karaka-Adhvaryus, forsooth, baste first the clotted ghee, arguing that the clotted ghee is the breath; and a Karaka-Adhvaryu, forsooth, cursed Yâgñavalkya for so doing, saying, ''That Adhvaryu has shut out the breath; the breath shall depart from him!'' 3:8:2:2525. But he, looking at his arms, said, ''These hoary arms--what in the world has become of …", "excerpt_truncated": true, "is_active": true, "link_method": null, "page_or_section": "ŚB 3.8.2.24–25", "relationship": "supports", "section_title": "Yajnavalkya: Shatapatha Brahmana 3.8.2.24–25 records a dispute over the order of basting in the animal sacrifice: a priest of the rival Charaka school of Adhvaryus curses Yajnavalkya, who looks at his grey arms and dismisses the curse. The passage shows him as an ageing practising priest in a contest between ritual schools.", "source_id": "f6192b65-d921-4f20-bf53-29ca06a90ded", "textual_layer": "Late Vedic ritual prose: Shatapatha Brahmana (Madhyandina recension), in translation"}], "relationship": "supports", "source": {"author": "Julius Eggeling (translator)", "authority_metadata": {"verified_at": "2026-10-12"}, "citation": "Julius Eggeling (translator). The Satapatha-Brahmana according to the Text of the Madhyandina School (Sacred Books of the East 12, 26, 44). Clarendon Press, Oxford; transcription archived from sacred-texts.com. https://web.archive.org/web/2023id_/https://www.sacred-texts.com/hin/sbr/index.htm", "original_work_identity": {}, "publication_year": 1900, "publisher_or_institution": "Clarendon Press, Oxford; transcription archived from sacred-texts.com", "rights_or_access_note": "Public-domain Oxford translation (1882–1900); transcription read through the Internet Archive Wayback Machine.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "The Satapatha-Brahmana according to the Text of the Madhyandina School (Sacred Books of the East 12, 26, 44)", "url": "https://web.archive.org/web/2023id_/https://www.sacred-texts.com/hin/sbr/index.htm"}, "source_id":