insert into original_claims values ('0a2a7f1f-c23c-409c-ae84-7cc83bbe1aef','{"approval_origin": "ai_candidate", "certainty": "high", "claim_id": "0a2a7f1f-c23c-409c-ae84-7cc83bbe1aef", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "In the earlier telling at Brihadaranyaka 2.4, Maitreyi asks whether the whole earth filled with wealth would make her immortal; Yajnavalkya says wealth gives no hope of immortality, and she asks instead to be taught what he knows.", "current_status": "draft", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification"], "evidence_type": "direct_primary_text", "lens": {"field_id": "a04bf1d1-b32a-40f3-9994-4328cd6eef07", "field_label": "Interactions with other rishis: collaboration, rivalry, debate", "parameter_id": "700ce11a-bd45-4116-99a4-a246dc97c505", "parameter_name": "Relational / Social Role"}, "parent_claim_id": null, "personality_id": "6ef206bf-1446-4e3d-94a6-e583f7736e62", "personality_name": "Yajnavalkya", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Then said Maitreyī: ‘If now, Sir, this whole earth filled with wealth were mine, would I be immortal thereby?’ ‘No,’ said Yājñavalkya. ‘As the life of the rich, even so would your life be. Of immortality, however, there is no hope through wealth.’ 3. Then said Maitreyī: ‘What should I do with that through which I may not be immortal? What you know, …", "link_id": "78732da1-819b-4a19-b90e-c364baf49ee3", "page_or_section": "BAU 2.4.2–3", "passages": [{"chunk_id": "91ff8426-65d4-403d-a741-162b0d06390c", "confidence": null, "excerpt": "Then said Maitreyī: ‘If now, Sir, this whole earth filled with wealth were mine, would I be immortal thereby?’ ‘No,’ said Yājñavalkya. ‘As the life of the rich, even so would your life be. Of immortality, however, there is no hope through wealth.’ 3. Then said Maitreyī: ‘What should I do with that through which I may not be immortal? What you know, …", "excerpt_truncated": true, "is_active": true, "link_method": null, "page_or_section": "BAU 2.4.2–3", "relationship": "supports", "section_title": "Yajnavalkya: In the earlier telling at Brihadaranyaka 2.4, Maitreyi asks whether the whole earth filled with wealth would make her immortal; Yajnavalkya says wealth gives no hope of immortality, and she asks instead to be taught what he knows.", "source_id": "5d0a41a4-b79b-4182-b6ee-afa099f453da", "textual_layer": "Early Upanishad: Brihadaranyaka (Kanva recension), in translation"}], "relationship": "supports", "source": {"author": "Robert Ernest Hume (translator)", "authority_metadata": {"verified_at": "2026-10-12"}, "citation": "Robert Ernest Hume (translator). Brihad-Aranyaka Upanishad, in The Thirteen Principal Upanishads. Oxford University Press; Online Library of Liberty edition. https://oll-resources.s3.us-east-2.amazonaws.com/oll3/store/titles/2058/Hume_1395_EBk_v6.0.pdf", "original_work_identity": {}, "publication_year": 1921, "publisher_or_institution": "Oxford University Press; Online Library of Liberty edition", "rights_or_access_note": "Public-domain 1921 Oxford translation; the e-book text layer prints \"?\" for some under-dotted Sanskrit letters.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Brihad-Aranyaka Upanishad, in The Thirteen Principal Upanishads", "url": "https://oll-resources.s3.us-east-2.amazonaws.com/oll3/store/titles/2058/Hume_1395_EBk_v6.0.pdf"}, "source_id": "5d0a41a4-b79b-4182-b6ee-afa099f453da"}], "unmatched_passage_links": []}'::jsonb,'draft','ai_candidate');
insert into original_claims values ('10536bf4-11f7-4f95-82d4-068a666914ae','{"approval_origin": "ai_candidate", "certainty": "high", "claim_id": "10536bf4-11f7-4f95-82d4-068a666914ae", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "Brihadaranyaka 4.5.1 says Yajnavalkya had two wives: Maitreyi, called a brahmavadini (one who discourses on sacred knowledge), and Katyayani, said to have only \"a woman’s knowledge\". About to take up another mode of life, he proposes to settle his property between them.", "current_status": "draft", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification"], "evidence_type": "direct_primary_text", "lens": {"field_id": "a04bf1d1-b32a-40f3-9994-4328cd6eef07", "field_label": "Interactions with other rishis: collaboration, rivalry, debate", "parameter_id": "700ce11a-bd45-4116-99a4-a246dc97c505", "parameter_name": "Relational / Social Role"}, "parent_claim_id": null, "personality_id": "6ef206bf-1446-4e3d-94a6-e583f7736e62", "personality_name": "Yajnavalkya", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Now then, Yājñavalkya had two wives, Maitreyī and Kātyāyanī. Of the two, Maitreyī was a discourser on sacred knowledge2 (brahma-vādinī); Kātyāyanī had just (eva) a woman’s knowledge in that matter (tarhi). Now then, Yājñavalkya was about to commence another mode of life.3 2. ‘Maitreyī!’ said Yājñavalkya, ‘lo, verily, I am about to wander forth4 from this …", "link_id": "6cacb2e2-a597-45e8-b180-b1e182dce0ce", "page_or_section": "BAU 4.5.1–2", "passages": [{"chunk_id": "8e367e22-ec97-4329-a46e-c8782bfb616c", "confidence": null, "excerpt": "Now then, Yājñavalkya had two wives, Maitreyī and Kātyāyanī. Of the two, Maitreyī was a discourser on sacred knowledge2 (brahma-vādinī); Kātyāyanī had just (eva) a woman’s knowledge in that matter (tarhi). Now then, Yājñavalkya was about to commence another mode of life.3 2. ‘Maitreyī!’ said Yājñavalkya, ‘lo, verily, I am about to wander forth4 from this …", "excerpt_truncated": true, "is_active": true, "link_method": null, "page_or_section": "BAU 4.5.1–2", "relationship": "supports", "section_title": "Yajnavalkya: Brihadaranyaka 4.5.1 says Yajnavalkya had two wives: Maitreyi, called a brahmavadini (one who discourses on sacred knowledge), and Katyayani, said to have only \"a woman’s knowledge\". About to take up another mode of life, he proposes to settle his property between them.", "source_id": "5d0a41a4-b79b-4182-b6ee-afa099f453da", "textual_layer": "Early Upanishad: Brihadaranyaka (Kanva recension), in translation"}], "relationship": "supports", "source": {"author": "Robert Ernest Hume (translator)", "authority_metadata": {"verified_at": "2026-10-12"}, "citation": "Robert Ernest Hume (translator). Brihad-Aranyaka Upanishad, in The Thirteen Principal Upanishads. Oxford University Press; Online Library of Liberty edition. https://oll-resources.s3.us-east-2.amazonaws.com/oll3/store/titles/2058/Hume_1395_EBk_v6.0.pdf", "original_work_identity": {}, "publication_year": 1921, "publisher_or_institution": "Oxford University Press; Online Library of Liberty edition", "rights_or_access_note": "Public-domain 1921 Oxford translation; the e-book text layer prints \"?\" for some under-dotted Sanskrit letters.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Brihad-Aranyaka Upanishad, in The Thirteen Principal Upanishads", "url": "https://oll-resources.s3.us-east-2.amazonaws.com/oll3/store/titles/2058/Hume_1395_EBk_v6.0.pdf"}, "source_id": "5d0a41a4-b79b-4182-b6ee-afa099f453da"}], "unmatched_passage_links": []}'::jsonb,'draft','ai_candidate');
insert into original_claims values ('3ebe5b3f-939f-4047-8478-2d53518fbdae','{"approval_origin": "ai_candidate", "certainty": "medium", "claim_id": "3ebe5b3f-939f-4047-8478-2d53518fbdae", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "Witzel compares Yajnavalkya with the other great teachers of the early Upanishads, naming Uddalaka Aruni and Shvetaketu Aruneya as the nearest in stature, and concludes that none is regarded as highly in the texts.", "current_status": "draft", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "SCHOLARLY_INTERPRETATION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "a04bf1d1-b32a-40f3-9994-4328cd6eef07", "field_label": "Interactions with other rishis: collaboration, rivalry, debate", "parameter_id": "700ce11a-bd45-4116-99a4-a246dc97c505", "parameter_name": "Relational / Social Role"}, "parent_claim_id": null, "personality_id": "6ef206bf-1446-4e3d-94a6-e583f7736e62", "personality_name": "Yajnavalkya", "reviewer_decision": null, "sources": [{"evidence_excerpt": "However, there is hardly anyone of equal stature in sight: One may think of Uddålaka Āru\u0003i, or perhaps of Śvetaketu Āru\u0003eya, yet, none of them is regarded as highly in the texts as Yåjñavalkya.94", "link_id": "1113a261-fa4f-4b5a-80bc-8b02251dbed6", "page_or_section": "§8", "passages": [{"chunk_id": "4038c960-9230-4797-b195-2e9ad50a8e33", "confidence": null, "excerpt": "However, there is hardly anyone of equal stature in sight: One may think of Uddålaka Āru\u0003i, or perhaps of Śvetaketu Āru\u0003eya, yet, none of them is regarded as highly in the texts as Yåjñavalkya.94", "excerpt_truncated": false, "is_active": true, "link_method": null, "page_or_section": "§8", "relationship": "supports", "section_title": "Yajnavalkya: Witzel compares Yajnavalkya with the other great teachers of the early Upanishads, naming Uddalaka Aruni and Shvetaketu Aruneya as the nearest in stature, and concludes that none is regarded as highly in the texts.", "source_id": "3bdf7285-d73d-4e2f-a6dd-d40a442322dc", "textual_layer": "Modern Vedic philology (Harvard); argues for one historical teacher behind both texts"}], "relationship": "supports", "source": {"author": "Michael Witzel", "authority_metadata": {"verified_at": "2026-10-12"}, "citation": "Michael Witzel. Yājñavalkya as ritualist and philosopher, and his personal language. Paitimāna: Essays in Iranian, Indo-European, and Indian Studies in Honor of Hanns-Peter Schmidt (Mazda, Costa Mesa); author’s text circulated on the INDOLOGY list. https://list.indology.info/pipermail/indology/attachments/20170714/f690c648/attachment.pdf", "original_work_identity": {}, "publication_year": 2003, "publisher_or_institution": "Paitimāna: Essays in Iranian, Indo-European, and Indian Studies in Honor of Hanns-Peter Schmidt (Mazda, Costa Mesa); author’s text circulated on the INDOLOGY list", "rights_or_access_note": "Author’s PDF; text extraction drops some under-dotted Sanskrit letters and prints å for ā.", "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Yājñavalkya as ritualist and philosopher, and his personal language", "url": "https://list.indology.info/pipermail/indology/attachments/20170714/f690c648/attachment.pdf"}, "source_id": "3bdf7285-d73d-4e2f-a6dd-d40a442322dc"}], "unmatched_passage_links": []}'::jsonb,'draft','ai_candidate');
