insert into original_claims values ('8bf94976-98cc-4f25-a8c4-21fd428692e4','{"approval_origin": "ai_candidate", "certainty": "high", "claim_id": "8bf94976-98cc-4f25-a8c4-21fd428692e4", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "In Brihadaranyaka 3.6, Gargi Vachaknavi asks Yajnavalkya what each level of the world is \"woven\" upon; when she asks what the worlds of Brahma are woven on, he warns her not to question too much lest her head fall off, and she falls silent.", "current_status": "draft", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification"], "evidence_type": "direct_primary_text", "lens": {"field_id": "a04bf1d1-b32a-40f3-9994-4328cd6eef07", "field_label": "Interactions with other rishis: collaboration, rivalry, debate", "parameter_id": "700ce11a-bd45-4116-99a4-a246dc97c505", "parameter_name": "Relational / Social Role"}, "parent_claim_id": null, "personality_id": "6ef206bf-1446-4e3d-94a6-e583f7736e62", "personality_name": "Yajnavalkya", "reviewer_decision": null, "sources": [{"evidence_excerpt": "‘On what then, pray, are the worlds of Brahma woven, warp and woof?’ Yājñavalkya said: ‘Gārgī, do not question too much, lest your head fall off. In truth you are questioning too much about a divinity about which further questions cannot be asked. Gārgī, do not over-question.’ Thereupon Gārgī Vācaknavī held her peace.", "link_id": "0ecb8f18-3b49-448e-b47b-6441b78dfa6a", "page_or_section": "BAU 3.6", "passages": [{"chunk_id": "c099f21e-6200-4b75-b013-38ad8641479a", "confidence": null, "excerpt": "‘On what then, pray, are the worlds of Brahma woven, warp and woof?’ Yājñavalkya said: ‘Gārgī, do not question too much, lest your head fall off. In truth you are questioning too much about a divinity about which further questions cannot be asked. Gārgī, do not over-question.’ Thereupon Gārgī Vācaknavī held her peace.", "excerpt_truncated": false, "is_active": true, "link_method": null, "page_or_section": "BAU 3.6", "relationship": "supports", "section_title": "Yajnavalkya: In Brihadaranyaka 3.6, Gargi Vachaknavi asks Yajnavalkya what each level of the world is \"woven\" upon; when she asks what the worlds of Brahma are woven on, he warns her not to question too much lest her head fall off, and she falls silent.", "source_id": "5d0a41a4-b79b-4182-b6ee-afa099f453da", "textual_layer": "Early Upanishad: Brihadaranyaka (Kanva recension), in translation"}], "relationship": "supports", "source": {"author": "Robert Ernest Hume (translator)", "authority_metadata": {"verified_at": "2026-10-12"}, "citation": "Robert Ernest Hume (translator). Brihad-Aranyaka Upanishad, in The Thirteen Principal Upanishads. Oxford University Press; Online Library of Liberty edition. https://oll-resources.s3.us-east-2.amazonaws.com/oll3/store/titles/2058/Hume_1395_EBk_v6.0.pdf", "original_work_identity": {}, "publication_year": 1921, "publisher_or_institution": "Oxford University Press; Online Library of Liberty edition", "rights_or_access_note": "Public-domain 1921 Oxford translation; the e-book text layer prints \"?\" for some under-dotted Sanskrit letters.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Brihad-Aranyaka Upanishad, in The Thirteen Principal Upanishads", "url": "https://oll-resources.s3.us-east-2.amazonaws.com/oll3/store/titles/2058/Hume_1395_EBk_v6.0.pdf"}, "source_id": "5d0a41a4-b79b-4182-b6ee-afa099f453da"}], "unmatched_passage_links": []}'::jsonb,'draft','ai_candidate');
