insert into original_claims values ('89771c0a-ff68-498d-9e7c-16527634a79d','{"approval_origin": "ai_candidate", "certainty": "high", "claim_id": "89771c0a-ff68-498d-9e7c-16527634a79d", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "The Maitreyi dialogue ends with the question \"whereby would one understand the understander?\"; Yajnavalkya tells her this instruction is immortality, and the text then says he departed.", "current_status": "draft", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification"], "evidence_type": "direct_primary_text", "lens": {"field_id": "4fbda67a-a586-4c2e-aab6-b057d9c2c4fa", "field_label": "Specific spiritual practice or discipline associated with the Rishi", "parameter_id": "1b7184a9-e92f-4f89-8300-af633b008d29", "parameter_name": "Tapas and Sadhana"}, "parent_claim_id": null, "personality_id": "6ef206bf-1446-4e3d-94a6-e583f7736e62", "personality_name": "Yajnavalkya", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Lo, whereby would one understand the understander? Thus you have the instruction told to you, Maitreyī. Such, lo, indeed, is immortality.’ After speaking thus, Yājñavalkya departed.", "link_id": "47b8b362-ea18-486c-beae-848a446cba2f", "page_or_section": "BAU 4.5.15", "passages": [{"chunk_id": "3ade6ed2-497f-4419-ae23-4a8de3a9a262", "confidence": null, "excerpt": "Lo, whereby would one understand the understander? Thus you have the instruction told to you, Maitreyī. Such, lo, indeed, is immortality.’ After speaking thus, Yājñavalkya departed.", "excerpt_truncated": false, "is_active": true, "link_method": null, "page_or_section": "BAU 4.5.15", "relationship": "supports", "section_title": "Yajnavalkya: The Maitreyi dialog