insert into original_claims values ('aa0040aa-f111-496f-b616-55ff280c1c11','{"approval_origin": "ai_candidate", "certainty": "high", "claim_id": "aa0040aa-f111-496f-b616-55ff280c1c11", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "Brihadaranyaka 4.4.22 links knowledge of the self with renunciation: Brahmins seek the self through Vedic recitation, sacrifice, gifts, austerity and fasting; knowing it one becomes a sage, and those who desire it alone give up the wish for sons, wealth and worlds and wander as mendicants.", "current_status": "draft", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification"], "evidence_type": "direct_primary_text", "lens": {"field_id": "4fbda67a-a586-4c2e-aab6-b057d9c2c4fa", "field_label": "Specific spiritual practice or discipline associated with the Rishi", "parameter_id": "1b7184a9-e92f-4f89-8300-af633b008d29", "parameter_name": "Tapas and Sadhana"}, "parent_claim_id": null, "personality_id": "6ef206bf-1446-4e3d-94a6-e583f7736e62", "personality_name": "Yajnavalkya", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Such a one the Brahmans desire to know by repetition of the Vedas, by sacrifices, by offerings, by penance, by fasting. On knowing him, in truth, one becomes an ascetic (muni). Desiring him only as their home, mendicants wander forth. Verily, because they know this, the ancients desired not offspring, saying: “What shall we do with offspring, we whose is …", "link_id": "bbbd9c36-a747-4882-ab95-20e84768bc15", "page_or_section": "BAU 4.4.22", "passages": [{"chunk_id": "70c7c54b-618f-4fbe-9048-a8d5860f3465", "confidence": null, "excerpt": "Such a one the Brahmans desire to know by repetition of the Vedas, by sacrifices, by offerings, by penance, by fasting. On knowing him, in truth, one becomes an ascetic (muni). Desiring him only as their home, mendicants wander forth. Verily, because they know this, the ancients desired not offspring, saying: “What shall we do with offspring, we whose is …", "excerpt_truncated": true, "is_active": true, "link_method": null, "page_or_section": "BAU 4.4.22", "relationship": "supports", "section_title": "Yajnavalkya: Brihadaranyaka 4.4.22 links knowledge of the self with renunciation: Brahmins seek the self through Vedic recitation, sacrifice, gifts, austerity and fasting; knowing it one becomes a sage, and those who desire it alone give up the wish for sons, wealth and worlds and wander as mendicants.", "source_id": "5d0a41a4-b79b-4182-b6ee-afa099f453da", "textual_layer": "Early Upanishad: Brihadaranyaka (Kanva recension), in translation"}], "relationship": "supports", "source": {"author": "Robert Ernest Hume (translator)", "authority_metadata": {"verified_at": "2026-10-12"}, "citation": "Robert Ernest Hume (translator). Brihad-Aranyaka Upanishad, in The Thirteen Principal Upanishads. Oxford University Press; Online Library of Liberty edition. https://oll-resources.s3.us-east-2.amazonaws.com/oll3/store/titles/2058/Hume_1395_EBk_v6.0.pdf", "original_work_identity": {}, "publication_year": 1921, "publisher_or_institution": "Oxford University Press; Online Library of Liberty edition", "rights_or_access_note": "Public-domain 1921 Oxford translation; the e-book text layer prints \"?\" for some under-dotted Sanskrit letters.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "Brihad-Aranyaka Upanishad, in The Thirteen Principal Upanishads", "url": "https://oll-resources.s3.us-east-2.amazonaws.com/oll3/store/titles/2058/Hume_1395_EBk_v6.0.pdf"}, "source_id": "5d0a41a4-b79b-4182-b6ee-afa099f453da"}], "unmatched_passage_links": []}'::jsonb,'draft','ai_candidate');
