insert into original_claims values ('91b223dc-2c04-4e24-beb9-d189d1293d20','{"approval_origin": "ai_candidate", "certainty": "high", "claim_id": "91b223dc-2c04-4e24-beb9-d189d1293d20", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "The lineage at the end of the Brihadaranyaka states that \"these white sacrificial formulas which come from Aditya\" (the Sun) are declared by Yajnavalkya of the Vajasaneyi school: the Upanishad’s own link between him and the White (Shukla) Yajurveda.", "current_status": "draft", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification"], "evidence_type": "direct_primary_text", "lens": {"field_id": "acb0d457-4064-4750-8bfb-c76cbe313c15", "field_label": "School of thought (darshana) founded or elaborated, if any", "parameter_id": "a2eb1f36-a2a0-47fb-8d45-68d9db573054", "parameter_name": "Textual Contribution"}, "parent_claim_id": null, "personality_id": "6ef206bf-1446-4e3d-94a6-e583f7736e62", "personality_name": "Yajnavalkya", "reviewer_decision": null, "sources": [{"evidence_excerpt": "These white1 sacrificial formulas (yajur) which come from Āditya are declared by Yājñavalkya of the Vājasaneyi school.", "link_id": "bad5dc2a-97a1-4bae-aad4-94a6dcc547c1", "page_or_section": "BAU 6.5.3", "passages": [{"chunk_id": "58ac49bc-b9f9-4a57-ab1c-77ed28c4e1f9", "confidence": null, "excerpt": "These white1 sacrificial formulas (yajur) which come from Āditya are declared by Yājñavalkya of the Vājasaneyi school.", "excerpt_truncated": false, "is_active": true, "link_method": null, "page_or_section": "BAU 6.5.3", "relationship": "supports", "section_title": "Yajnavalkya: The lineage at the end of the Brihadaranyaka states that \"these white sacrificial formul