insert into original_claims values ('aeeb1610-f68f-4803-b69e-1550032c5828','{"approval_origin": "ai_candidate", "certainty": "medium", "claim_id": "aeeb1610-f68f-4803-b69e-1550032c5828", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "Eggeling explains the White Yajurveda as a reform of older Yajus tradition: its school separated the sacrificial formulas from the explanatory prose, producing a distinct Samhita and Brahmana, and tradition ascribes the founding of this school, the Vajasaneyins, to Yajnavalkya Vajasaneya.", "current_status": "draft", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "SCHOLARLY_INTERPRETATION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "acb0d457-4064-4750-8bfb-c76cbe313c15", "field_label": "School of thought (darshana) founded or elaborated, if any", "parameter_id": "a2eb1f36-a2a0-47fb-8d45-68d9db573054", "parameter_name": "Textual Contribution"}, "parent_claim_id": null, "personality_id": "6ef206bf-1446-4e3d-94a6-e583f7736e62", "personality_name": "Yajnavalkya", "reviewer_decision": null, "sources": [{"evidence_excerpt": "It was with the view of remedying this want of arrangement, by entirely separating the exegetic matter from the formulas, that the new school of Adhvaryus was founded. The name given to this school is Vâgasaneyins, its origin being ascribed to Yâgñavalkya Vâgasaneya. The result of this new redaction of the Yagus texts was the formation of a Samhitâ, or …", "link_id": "6b2a9eaa-5d3e-45e3-bc8a-cb32cd5577f1", "page_or_section": "SBE 12, Introduction, pp. xxvi–xxvii", "passages": [{"chunk_id": "ab4ca36f-a447-45cb-b423-f6a378a9a55f", "confidence": null, "excerpt": "It was with the view of remedying this want of arrangement, by entirely separating the exegetic matter from the formulas, that the new school of Adhvaryus was founded. The name given to this school is Vâgasaneyins, its origin being ascribed to Yâgñavalkya Vâgasaneya. The result of this new redaction of the Yagus texts was the formation of a Samhitâ, or …", "excerpt_truncated": true, "is_active": true, "link_method": null, "page_or_section": "SBE 12, Introduction, pp. xxvi–xxvii", "relationship": "supports", "section_title": "Yajnavalkya: Eggeling explains the White Yajurveda as a reform of older Yajus tradition: its school separated the sacrificial formulas from the explanatory prose, producing a distinct Samhita and Brahmana, and tradition ascribes the founding of this school, the Vajasaneyins, to Yajnavalkya Vajasaneya.", "source_id": "a8dd14d9-66ba-4af5-aacc-0a5386bdc64c", "textual_layer": "Nineteenth-century Indological scholarship on the Brahmana; some judgments are dated"}], "relationship": "supports", "source": {"author": "Julius Eggeling", "authority_metadata": {"verified_at": "2026-10-12"}, "citation": "Julius Eggeling. Introduction to The Satapatha-Brahmana, Part I (Sacred Books of the East 12). Clarendon Press, Oxford; transcription archived from sacred-texts.com. https://web.archive.org/web/2023id_/https://www.sacred-texts.com/hin/sbr/sbe12/sbe1202.htm", "original_work_identity": {}, "publication_year": 1882, "publisher_or_institution": "Clarendon Press, Oxford; transcription archived from sacred-texts.com", "rights_or_access_note": "Public-domain 1882 introduction; transcription read through the Internet Archive Wayback Machine.", "source_status": "approved", "source_type": "scholarly_book", "storage_path": null, "title": "Introduction to The Satapatha-Brahmana, Part I (Sacred Books of the East 12)", "url": "https://web.archive.org/web/2023id_/https://www.sacred-texts.com/hin/sbr/sbe12/sbe1202.htm"}, "source_id": "a8dd14d9-66ba-4af5-aacc-0a5386bdc64c"}], "unmatched_passage_links": []}'::jsonb,'draft','ai_candidate');
insert into original_claims values ('d76806bb-0150-47c8-a227-78cc1fde0c86','{"approval_origin": "ai_candidate", "certainty": "medium", "claim_id": "d76806bb-0150-47c8-a227-78cc1fde0c86", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "The Upanishads that preserve Yajnavalkya’s teaching were most influentially interpreted by Shankara (about 700 CE), the main proponent of non-dualist Advaita Vedanta, whose readings shaped Indian philosophy for centuries and dominated interpretation of the texts into the early twentieth century.", "current_status": "draft", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "SCHOLARLY_INTERPRETATION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "acb0d457-4064-4750-8bfb-c76cbe313c15", "field_label": "School of thought (darshana) founded or elaborated, if any", "parameter_id": "a2eb1f36-a2a0-47fb-8d45-68d9db573054", "parameter_name": "Textual Contribution"}, "parent_claim_id": null, "personality_id": "6ef206bf-1446-4e3d-94a6-e583f7736e62", "personality_name": "Yajnavalkya", "reviewer_decision": null, "sources": [{"evidence_excerpt": "The most well-known philosopher of the Vedānta school was Śaṅkara (c. 700 C.E.), whose interpretations of the Upaniṣads made a major impact on the Indian philosophical tradition in the centuries after his lifetime and continued to dominate readings of the texts throughout the 19th and early 20th centuries. Śaṅkara was the main proponent of Advaita Vedānta, …", "link_id": "3cb94e97-a353-428b-83db-0aa045a69f13", "page_or_section": "§8", "passages": [{"chunk_id": "5166ce7d-1d6d-4a05-843c-f3205f5c09d2", "confidence": null, "excerpt": "The most well-known philosopher of the Vedānta school was Śaṅkara (c. 700 C.E.), whose interpretations of the Upaniṣads made a major impact on the Indian philosophical tradition in the centuries after his lifetime and continued to dominate readings of the texts throughout the 19th and early 20th centuries. Śaṅkara was the main proponent of Advaita Vedānta, …", "excerpt_truncated": true, "is_active": true, "link_method": null, "page_or_section": "§8", "relationship": "supports", "section_title": "Yajnavalkya: The Upanishads that preserve Yajnavalkya’s teaching were most influentially interpreted by Shankara (about 700 CE), the main proponent of non-dualist Advaita Vedanta, whose readings shaped Indian philosophy for centuries and dominated interpretation of the texts into the early twentieth century.", "source_id": "c833b2a2-932f-4715-8339-d3f1860dc99d", "textual_layer": "Peer-reviewed philosophy reference; modern interpretation of the early Upanishads"}], "relationship": "supports", "source": {"author": "Brian Black", "authority_metadata": {"verified_at": "2026-10-12"}, "citation": "Brian Black. The Upaniṣads. Internet Encyclopedia of Philosophy (peer-reviewed). https://iep.utm.edu/upanisad/", "original_work_identity": {}, "publication_year": null, "publisher_or_institution": "Internet Encyclopedia of Philosophy (peer-reviewed)", "rights_or_access_note": "Public original; short research excerpts.", "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "The Upaniṣads", "url": "https://iep.utm.edu/upanisad/"}, "source_id": "c833b2a2-932f-4715-8339-d3f1860dc99d"}], "unmatched_passage_links": []}'::jsonb,'draft','ai_candidate');
insert into original_claims values ('23ba382c-d287-4c35-9af9-2ee0d46e488f','{"approval_origin": "ai_candidate", "certainty": "high", "claim_id": "23ba382c-d287-4c35-9af9-2ee0d46e488f", "claim_kind": "textual_tradition", "claim_relations": [], "claim_text": "In the Shatapatha Brahmana Yajnavalkya appears as a ritual authority whose rulings are quoted: at 1.1.1.9, on whether a sacrificer should fast before the rite, he dissents from the rule of total fasting and says one should eat what \"counts as not eaten\".", "current_status": "draft", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "TEXTUAL_ASSERTION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification"], "evidence_type": "direct_primary_text", "lens": {"field_id": "cc71c2f4-ed36-406a-b0b2-470408e3226d", "field_label": "Primary function: drashta, guru, darshana-founder, smriti-author, ashram-head", "parameter_id": "0ec41561-655d-4982-b2d8-97b4a2b9fe7c", "parameter_name": "Vocation / Role within the Rishi Tradition"}, "parent_claim_id": null, "personality_id": "6ef206bf-1446-4e3d-94a6-e583f7736e62", "personality_name": "Yajnavalkya", "reviewer_decision": null, "sources": [{"evidence_excerpt": "1:1:1:99. Yâgñavalkya, on the other hand, said: ''If he does not eat, he thereby becomes a sacrificer to the Manes; and if he does eat, he eats before the gods have eaten: let him therefore eat what, when eaten, counts as not eaten.'' For that of which no offering is made, even though it is eaten, is considered as not eaten. When he therefore eats, he does …", "link_id": "d4f1ea70-842c-41c7-a206-70f192604eeb", "page_or_section": "ŚB 1.1.1.8–9", "passages": [{"chunk_id": "992ff368-6cbd-4bfd-b980-55979c2935bc", "confidence": null, "excerpt": "1:1:1:99. Yâgñavalkya, on the other hand, said: ''If he does not eat, he thereby becomes a sacrificer to the Manes; and if he does eat, he eats before the gods have eaten: let him therefore eat what, when eaten, counts as not eaten.'' For that of which no offering is made, even though it is eaten, is considered as not eaten. When he therefore eats, he does …", "excerpt_truncated": true, "is_active": true, "link_method": null, "page_or_section": "ŚB 1.1.1.8–9", "relationship": "supports", "section_title": "Yajnavalkya: In the Shatapatha Brahmana Yajnavalkya appears as a ritual authority whose rulings are quoted: at 1.1.1.9, on whether a sacrificer should fast before the rite, he dissents from the rule of total fasting and says one should eat what \"counts as not eaten\".", "source_id": "f6192b65-d921-4f20-bf53-29ca06a90ded", "textual_layer": "Late Vedic ritual prose: Shatapatha Brahmana (Madhyandina recension), in translation"}], "relationship": "supports", "source": {"author": "Julius Eggeling (translator)", "authority_metadata": {"verified_at": "2026-10-12"}, "citation": "Julius Eggeling (translator). The Satapatha-Brahmana according to the Text of the Madhyandina School (Sacred Books of the East 12, 26, 44). Clarendon Press, Oxford; transcription archived from sacred-texts.com. https://web.archive.org/web/2023id_/https://www.sacred-texts.com/hin/sbr/index.htm", "original_work_identity": {}, "publication_year": 1900, "publisher_or_institution": "Clarendon Press, Oxford; transcription archived from sacred-texts.com", "rights_or_access_note": "Public-domain Oxford translation (1882–1900); transcription read through the Internet Archive Wayback Machine.", "source_status": "approved", "source_type": "primary_text", "storage_path": null, "title": "The Satapatha-Brahmana according to the Text of the Madhyandina School (Sacred Books of the East 12, 26, 44)", "url": "https://web.archive.org/web/2023id_/https://www.sacred-texts.com/hin/sbr/index.htm"}, "source_id": "f6192b65-d921-4f20-bf53-29ca06a90ded"}], "unmatched_passage_links": []}'::jsonb,'draft','ai_candidate');
insert into original_claims values ('f337115f-8afb-406d-bd1c-bcb823bc9f76','{"approval_origin": "ai_candidate", "certainty": "medium", "claim_id": "f337115f-8afb-406d-bd1c-bcb823bc9f76", "claim_kind": "scholarly_interpretation", "claim_relations": [], "claim_text": "In the Brahmana, Witzel notes, Yajnavalkya appears above all as a Yajurveda ritualist discussing minute details of the solemn (Shrauta) ritual in about a dozen passages; his opinions are sometimes clever or innovative, but not always followed even by his own school.", "current_status": "draft", "epistemics": {"contract_basis": null, "contract_satisfied": false, "contract_status": "NEEDS_TYPE_REVIEW", "epistemic_type": null, "proposed_type": "SCHOLARLY_INTERPRETATION", "reviewer_kind": null, "type_origin": "deterministic", "type_review_status": "needs_type_review"}, "evidence_flags": ["Missing assigned epistemic classification"], "evidence_type": "scholarly_interpretation", "lens": {"field_id": "cc71c2f4-ed36-406a-b0b2-470408e3226d", "field_label": "Primary function: drashta, guru, darshana-founder, smriti-author, ashram-head", "parameter_id": "0ec41561-655d-4982-b2d8-97b4a2b9fe7c", "parameter_name": "Vocation / Role within the Rishi Tradition"}, "parent_claim_id": null, "personality_id": "6ef206bf-1446-4e3d-94a6-e583f7736e62", "personality_name": "Yajnavalkya", "reviewer_decision": null, "sources": [{"evidence_excerpt": "Most prominently, Yåjñavalkya appears as the typical YV ritualist who discusses (in in about a dozen cases) the minute details of the complicated Śrauta ritual. His opinions are sometimes clever, sometimes innovative, but they are not always followed even by his own school, the Våjasaneyins.", "link_id": "b9b5d0dc-9bc9-482b-92eb-c61b51654cfb", "page_or_section": "§4", "passages": [{"chunk_id": "698728f5-5174-4097-bd30-d252df01bc7c", "confidence": null, "excerpt": "Most prominently, Yåjñavalkya appears as the typical YV ritualist who discusses (in in about a dozen cases) the minute details of the complicated Śrauta ritual. His opinions are sometimes clever, sometimes innovative, but they are not always followed even by his own school, the Våjasaneyins.", "excerpt_truncated": false, "is_active": true, "link_method": null, "page_or_section": "§4", "relationship": "supports", "section_title": "Yajnavalkya: In the Brahmana, Witzel notes, Yajnavalkya appears above all as a Yajurveda ritualist discussing minute details of the solemn (Shrauta) ritual in about a dozen passages; his opinions are sometimes clever or innovative, but not always followed even by his own school.", "source_id": "3bdf7285-d73d-4e2f-a6dd-d40a442322dc", "textual_layer": "Modern Vedic philology (Harvard); argues for one historical teacher behind both texts"}], "relationship": "supports", "source": {"author": "Michael Witzel", "authority_metadata": {"verified_at": "2026-10-12"}, "citation": "Michael Witzel. Yājñavalkya as ritualist and philosopher, and his personal language. Paitimāna: Essays in Iranian, Indo-European, and Indian Studies in Honor of Hanns-Peter Schmidt (Mazda, Costa Mesa); author’s text circulated on the INDOLOGY list. https://list.indology.info/pipermail/indology/attachments/20170714/f690c648/attachment.pdf", "original_work_identity": {}, "publication_year": 2003, "publisher_or_institution": "Paitimāna: Essays in Iranian, Indo-European, and Indian Studies in Honor of Hanns-Peter Schmidt (Mazda, Costa Mesa); author’s text circulated on the INDOLOGY list", "rights_or_access_note": "Author’s PDF; text extraction drops some under-dotted Sanskrit letters and prints å for ā.", "source_status": "approved", "source_type": "scholarly_article", "storage_path": null, "title": "Yājñavalkya as ritualist and philosopher, and his personal language", "url": "https://list.indology.info/pipermail/indology/attachments/20170714/f690c648/attachment.pdf"}, "source_id": "3bdf7285-d73d-4e2f-a6dd-d40a442322dc"}], "unmatched_passage_links": []}'::jsonb,'draft','ai_candidate');
insert into review_decisions (claim_id,decision,proposed_wording,epistemic_type,evidence_references,verification_rationale) values ('1c773840-34a3-435e-8e8d-f51227baa7a5','REVISE AND APPROVE','The first experimental SLV-3 flight in August 1979 was only partially successful; the next launch, on July 18, 1980, placed Rohini RS-1 in orbit.','HISTORICAL_FACT','[{"url": "https://www.isro.gov.in/SLV.html", "locator": "SLV, introductory paragraphs, lines 4–6", "source_id": "b1670b9f-a5fa-4b1c-84d8-4ae3cd652c5f"}]'::jsonb,'ISRO''s mission history directly gives both flight outcomes and the July 18 date. Institutional original record is adequate for this narrowly scoped launch chronology. The original wording was precise enough, but the proposed wording names the satellite and date for clarity.');
insert into review_decisions (claim_id,decision,proposed_wording,epistemic_type,evidence_references,verification_rationale) values ('0056e637-ab83-4d5e-906a-a4fd1a6add5a','REVISE AND APPROVE','On July 18, 1980, India''s SLV-3 placed the Rohini RS-1 satellite in orbit.','HISTORICAL_FACT','[{"url": "https://www.isro.gov.in/SLV.html", "locator": "SLV, launch account, line 4", "source_id": "b1670b9f-a5fa-4b1c-84d8-4ae3cd652c5f"}]'::jsonb,'ISRO directly confirms the launch date and orbital placement. The broad claim that this ''established an indigenous Indian satellite-launch capability'' is interpretive and was removed.');
insert into review_decisions (claim_id,decision,proposed_wording,epistemic_type,evidence_references,verification_rationale) values ('0ad9f692-4372-4895-936d-6383d12a7a96','REVISE AND APPROVE','ISRO says the successful SLV-3 project paved the way for the later ASLV, PSLV, and GSLV launch-vehicle projects.','TEXTUAL_ASSERTION','[{"url": "https://www.isro.gov.in/SLV.html", "locator": "SLV, final paragraph, line 7", "source_id": "b1670b9f-a5fa-4b1c-84d8-4ae3cd652c5f"}]'::jsonb,'The agency explicitly links the SLV-3 project to the three later programmes. The comparative attribution to Kalam alone is not established by this page, so it was omitted.');
insert into review_decisions (claim_id,decision,proposed_wording,epistemic_type,evidence_references,verification_rationale) values ('bbaeed4c-7325-42ef-b531-88ec1c970ac6','REVISE AND APPROVE','The SLV-3 was a four-stage, all-solid launch vehicle designed to place roughly 40 kg payloads in low Earth orbit.','HISTORICAL_FACT','[{"url": "https://www.isro.gov.in/SLV.html", "locator": "SLV, opening paragraph, line 2", "source_id": "b1670b9f-a5fa-4b1c-84d8-4ae3cd652c5f"}]'::jsonb,'ISRO''s vehicle description directly supports the configuration and payload capacity. Wording specifies the documented approximate capacity.');
insert into review_decisions (claim_id,decision,proposed_wording,epistemic_type,evidence_references,verification_rationale) values ('61e944ef-a848-4865-b28b-7ab1b56dc7eb','REVISE AND APPROVE','At the 1992 Academy Awards, Satyajit Ray received an Honorary Award recognizing his filmmaking, rather than an award for an individual film.','HISTORICAL_FACT','[{"url": "https://www.oscars.org/oscars/ceremonies/1992/memorable-moments", "locator": "Honorary Award, lines 79–80", "source_id": null}]'::jsonb,'The Academy''s own ceremony record identifies an Honorary Award to Ray and names no individual film in the citation. The original phrase ''lifetime body of work'' was broader than the formal citation and was narrowed. The separately linked awards-database URL was not needed for this check.');
insert into review_decisions (claim_id,decision,proposed_wording,epistemic_type,evidence_references,verification_rationale) values ('0d6e0dc3-6b43-453e-b1f3-8b8abf08e8ab','REVISE AND APPROVE','The Academy''s 1992 Honorary Award citation credited Ray with influence on filmmakers and audiences worldwide; this records the Academy''s judgment of his reception.','MODERN_RECEPTION','[{"url": "https://www.oscars.org/oscars/ceremonies/1992/memorable-moments", "locator": "Honorary Award citation, lines 79–80", "source_id": null}]'::jsonb,'The Academy citation explicitly asserts the influence. Framing it as the Academy''s judgment preserves the difference between an institutional honor and an independently measured effect.');
insert into review_decisions (claim_id,decision,proposed_wording,epistemic_type,evidence_references,verification_rationale) values ('af48b048-b6a9-4e9a-a59f-09ee0496a5e4','REVISE AND APPROVE','The Brihadisvara Temple at Thanjavur has been under Archaeological Survey of India protection since 1922 and is part of the UNESCO-listed Great Living Chola Temples.','HISTORICAL_FACT','[{"url": "https://whc.unesco.org/en/list/250/", "locator": "Protection and management requirements, lines 75–76; site summary, lines 2–5", "source_id": "dfea9d16-e203-4fc9-aa62-53a649dbd7b4"}]'::jsonb,'UNESCO''s site record directly identifies the property and states ASI protection began in 1922. This is an institutional status claim.');
insert into review_decisions (claim_id,decision,proposed_wording,epistemic_type,evidence_references,verification_rationale) values ('e4ee4929-f977-4c13-ae94-5cf2912a281f','REVISE AND APPROVE','UNESCO''s architectural synthesis says construction of the Brihadisvara Temple possibly began in Rajaraja I''s 19th regnal year (1003–04) and that it was consecrated in his 25th (1009–10).','SCHOLARLY_INTERPRETATION','[{"url": "https://whc.unesco.org/en/list/250/", "locator": "Outstanding Universal Value, brief synthesis, line 50", "source_id": "dfea9d16-e203-4fc9-aa62-53a649dbd7b4"}]'::jsonb,'The UNESCO text directly supplies both regnal-year dates and marks the inauguration as possible. Attribution to its synthesis and the uncertainty qualifier avoid overstating the historical chronology.');
insert into review_decisions (claim_id,decision,proposed_wording,epistemic_type,evidence_references,verification_rationale) values ('fb1ea3bb-ab07-44df-8d1d-b586cb7ab895','REVISE AND APPROVE','UNESCO describes the Brihadisvara Temple''s vimana as 59.82 metres high with thirteen talas.','HISTORICAL_FACT','[{"url": "https://whc.unesco.org/en/list/250/", "locator": "Outstanding Universal Value, brief synthesis, lines 51–52", "source_id": "dfea9d16-e203-4fc9-aa62-53a649dbd7b4"}]'::jsonb,'UNESCO directly reports the dimensions and tier count. The original interpretive phrase about material evidence of a monumental programme was removed to keep this claim tied to the documented measurement.');
insert into review_decisions (claim_id,decision,proposed_wording,epistemic_type,evidence_references,verification_rationale) values ('5609a45d-ff75-4996-bc9f-556be05c0dba','REVISE AND APPROVE','UNESCO identifies the Brihadisvara Temple at Thanjavur, built under Rajaraja I, as a major example of Chola architecture and art.','SCHOLARLY_INTERPRETATION','[{"url": "https://whc.unesco.org/en/list/250/", "locator": "Site description and Outstanding Universal Value, lines 4–5 and 50–61", "source_id": null}]'::jsonb,'UNESCO links the temple to Rajaraja I and evaluates the property as an outstanding Chola architectural example. The original claim about a ''long cultural legacy'' was too open-ended for this source and was narrowed.');
